use sha2::{Digest, Sha256};

use crate::channel::{ChannelDecl, CompletionOutcome, Consolidation};
use crate::definitions::Definitions;
use crate::error::{ErrorKind, NxfError, Result};
use crate::facade::{self, AskReceipt};
use crate::model::{
    Disposition, MessageEnvelope, MessageKind, Priority, Refs, CHANNEL_KIND_DIRECT,
};
use crate::park::ParkRefusal;
use crate::role::{compose_system_prompt, Model, RoleDecl, WorkingTree};
use crate::store::{ChatStore, ThreadQuorum};
use crate::worker::{
    Coordinator, RoleSpec, TriggerError, TriggerOutcome, TriggerRequest, TurnTerms, Worker,
};
use crate::working_tree::{resolve_scope, QueuedTrigger, WorkScope, WORKING_TREE_LEASE_BOUND};

/// The role-runtime depth-guard cap (spec §5.3). A spawn chain — role summons role summons role,
/// including two roles that only ever push work at each other — cannot loop forever.
///
/// **What is counted is the OPEN chain** (nxf 6j6v.ka09): how much work is commissioned and not yet
/// answered. A hop that carries a RESULT back does not add to it — see [`ChainMove`], which also
/// states plainly what that gives up.
pub const MAX_HOP: u32 = 32;

/// The prefix a DECLARED channel's substrate id carries: `decl:<name>`. Minted in exactly one place
/// ([`ensure_declared_channel`]) and read back in three — [`route_declared_channel_completion`]'s
/// reverse lookup, [`needs_working_tree`]'s, and [`crate::facade::status`]'s `--channel <name>`
/// match — so the string that ties them together is written once rather than spelled out at each
/// end. `pub(crate)` for that third reader: a status scope names a channel the way a user types it,
/// and re-spelling the prefix there would be the same literal in a second place.
pub(crate) const DECLARED_CHANNEL_PREFIX: &str = "decl:";

/// Everything an orchestration verb needs that `cli.rs` used to read from the environment.
///
/// Borrowed rather than owned so a caller can build one per call over long-lived state without
/// cloning the catalogue on every verb.
///
/// `Copy` because every field already is (shared references, two `&dyn`, a `u32`), and because one
/// operation on it is worth spelling in one line: [`with_declarations`] rebinds `defs` to the
/// catalogue an operation is FROZEN to (nxf 6j6v.n92p) and leaves the other eleven fields alone.
/// Written out field by field, that rebinding is where a field added later gets forgotten.
#[derive(Clone, Copy)]
pub struct Ctx<'a> {
    /// The wall clock, injected. Never read from the system here — the CLI passes `NXC_NOW` or the
    /// real clock, an app passes its own.
    pub now: &'a str,
    /// The minting workspace identity (spec §2.2).
    pub origin: &'a str,
    /// The acting agent's bare name; `origin/actor` is the qualified chat identity.
    pub actor: &'a str,
    /// The ambient caller session, stamped into `refs.session_id` when the caller sets none.
    /// `None` — not a placeholder — when there is no real session: a bare-terminal kickoff has no
    /// live session to route a follow-up back to, and a fixed sentinel in its place would be a
    /// false signal that could later be mistaken for a genuine session identity.
    pub session: Option<&'a str>,
    /// The CURRENT (pre-increment) depth-guard counter, as the CALLER reports it. [`trigger_role`]
    /// advances it for the next hop; nothing here mutates it in place. Since nxf 6j6v.m48m it is a
    /// FLOOR rather than the source of truth — [`resolve_hop`] reads the authoritative depth back
    /// from the caller's own session and takes whichever is larger.
    pub hop: u32,
    pub defs: &'a Definitions,
    pub worker: &'a dyn Worker,
    /// How a one-shot re-check is scheduled — a declared channel's `timeout` tick and a workflow
    /// step's liveness window (PR #269 review, Code Quality #3). Injected for exactly
    /// [`Ctx::worker`]'s reason: this used to be `crate::timer::select_timer()`, called from inside
    /// these verbs, which read `NXC_TIMER` from process env in violation of the seam's own "reads no
    /// environment variable" rule — and left an embedding app unable to decline an `at` subprocess
    /// it pays for from inside the engine's locked section.
    pub timer: &'a dyn crate::timer::Timer,
    /// **How a thread this call OPENS gets its name** (nxf 6j6v.e76c). Injected for exactly
    /// [`Ctx::timer`]'s reason, one seam further along: the derivation runs a MODEL in a detached
    /// process, and an embedding app must be able to decline a cost it never asked for — its
    /// default is [`crate::naming::NamerConfig::Disabled`], which commissions nothing.
    pub namer: &'a dyn crate::naming::Namer,
    /// The workspace db path, stamped into a spawned role's `NXC_DB` so its own in-session `nxc`
    /// calls resolve the same workspace.
    pub db_path: &'a str,
    /// The project's `CLAUDE.md`, when the role's `claude_md` policy wants it. Host-supplied: the
    /// CLI reads it from the workspace root, an app supplies its own or `None`.
    pub project_claude_md: Option<&'a str>,
    /// **Where the sibling modules' session-start blocks come from** (nxf 6j6v.k8zq) — the board
    /// (`nxf prime`) and the project's memory (`nxm prime`), for the persona a trigger is about to
    /// summon. `None` — the default for a host that supplies none, and for every test that does not
    /// care — composes chat's own half alone, which is what makes a summoned session able to answer.
    ///
    /// Host-supplied for the same reason `project_claude_md` is, one layer further out: composing
    /// it needs the module registry, which lives in the umbrella crate above this one. See
    /// [`crate::facade::ModulePrimes`] for the whole argument.
    pub module_primes: Option<&'a dyn crate::facade::ModulePrimes>,
    /// **Which machine this is, who else is online, and the claims that make a pickup happen once**
    /// (nxf 6j6v.1c6k) — see [`crate::machine::Machines`]. `None` — the default for a host that
    /// supplies none, and for every test that does not care — names no machine: nothing is
    /// designated, and a chat starts where it is written, exactly as before the executing machine
    /// existed.
    pub machines: Option<&'a dyn crate::machine::Machines>,
}

/// **Who is calling, and nothing that can be derived from that** (nxf 6j6v.07me): [`Ctx`]'s caller
/// half, as a library caller hands it over ([`crate::engine::Engine`]'s verbs take exactly this,
/// spec §4).
///
/// A `Ctx` is what a verb needs; this is the part of it the HOST genuinely knows and the adapter
/// cannot work out for itself. Everything else — the declaration catalogue, the worker, the
/// workspace db path, the project `CLAUDE.md`, and since 6j6v.07me the [`Ambient`] triple as well —
/// belongs to whichever adapter is in play (`cli.rs` resolves it from the environment, `Engine`
/// from its own resolved workspace and the session map), so [`into_ctx`](Caller::into_ctx) is the
/// single place the two halves are joined and this type lives beside the one it completes.
///
/// **It carried five values and now carries two and a half.** The owner's question at the source on
/// 2026-08-21: once `send --to` and `reply --thread` are the only interaction verbs, does everything
/// not follow from who sends and who receives? For four of the five it does — see the block below
/// [`Ambient`] for what left and where each value comes from instead.
///
/// **What did NOT follow, and it is not what it looks like: `session`.** It is the SENDER's session,
/// not the recipient's. The recipient's is derived from the thread and needs no parameter; this one
/// is stamped onto the message as the RETURN ADDRESS (`refs.session_id`, `with_return_address`),
/// which is what makes a chain run in both directions:
///
/// ```text
/// supervisor -> send --to coder -> T   (the SUPERVISOR's session is stamped)
/// coder      -> reply --thread T       (wakes the supervisor, BECAUSE it is stamped there)
/// ```
///
/// Without it a supervisor could commission the coder and the coder's answer would have nobody to
/// wake. `None` — not a placeholder — when there is no real session: a bare-terminal kickoff has no
/// live session to route a follow-up back to, and a fixed sentinel would be a false signal that
/// could later be mistaken for a genuine identity. It is also what an agent throws away when it
/// discards its ambient identity to look like a fresh chain, at the price [`resolve_hop`]'s doc
/// names in full: "no return address on its posts, no resume, no ambient session for anything to be
/// attributed to."
///
/// **Why a struct and not two arguments.** They were five positional parameters on every `Engine`
/// verb, in an order fixed enough that it had to be written down in a comment; transposing two
/// `&str`s still compiled and the message came out attributed to someone who never sent it. Two
/// fields is fewer, and the hazard is not smaller: `session` and `actor` are BOTH `Option<&str>`, so
/// a positional pair would swap in silence. With named fields the order at the call site carries no
/// meaning at all (a Rust struct literal may list them in any order).
///
/// **Per call, not per handle.** `session` differs between two calls on the same `Engine`, so a host
/// builds this at each call rather than storing it. It is `Copy`, so a caller making several calls
/// with identical values can reuse one (and `Caller { session: Some(s), ..base }` varies one field
/// without restating the rest).
///
/// **Borrowed, not owned**, mirroring [`Ctx`]: the values pass into the `Ctx` verbatim, so a call
/// allocates and clones nothing on the way through. What that costs a caller across a bridge
/// boundary (FFI, a Tauri command) is one borrow per field — the owned `String`s it deserialized
/// stay in its own locals and it passes `s.as_deref()`. What such a caller cannot do is park a
/// `Caller` in a struct that outlives those strings, which the per-call rule above means it has no
/// reason to want.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Caller<'a> {
    /// The SENDER's session — see the type's own doc, which argues at length why this is the one
    /// field that could not be derived.
    pub session: Option<&'a str>,
    /// The acting agent's BARE name (`alice`, not `local/alice`), and **required exactly when
    /// [`session`](Caller::session) names no session this workspace minted**.
    ///
    /// Identity comes from PROVENANCE, not from assertion (design 2026-08-05 §4.1): where there is
    /// a session, the session map already knows which persona it belongs to, and
    /// [`resolve_actor`](Caller::resolve_actor) reads it back rather than believing a caller's
    /// account of itself. What is left for this field is the case the map cannot answer — a human at
    /// a terminal, or an app acting for its logged-in user — and passing both is that fallback
    /// rather than a conflict to resolve: a session that answers wins, silently and by design.
    ///
    /// Neither one is a NAMED `validation` error, never a silent default. The CLI's `actor()` chain
    /// (`NXC_ACTOR`, else `USER`, else `nxc`) is the CLI's own; a library that invented one would
    /// attribute a write to an identity nobody chose.
    pub actor: Option<&'a str>,
    /// The wall clock — an OVERRIDE, `None` meaning "use the system clock" (nxf 6j6v.07me).
    ///
    /// The only reason it was ever mandatory is determinism: the orchestration verbs read no clock,
    /// so "is this stale?" is reproducible in a golden and in a test. That is a property the CLI and
    /// the test suites need and an app does not — it had to format an RFC3339 string on every call
    /// to say "just use the clock". The verbs are untouched: they still take an injected `now`, and
    /// the default is resolved once by the ADAPTER ([`crate::engine::Engine`], via [`system_now`])
    /// before the store is even locked. The CLI keeps passing what `NXC_NOW` resolves to, which is
    /// what keeps every golden byte-stable.
    pub now: Option<&'a str>,
}

// `Caller.origin`, `Caller.hop` and the MANDATORY `Caller.now` stood here. REMOVED by nxf 6j6v.07me
// (owner, 2026-08-21, at the source): "wenn `send --to` und `reply --thread` die einzigen
// Interaktionsbefehle sind, ergibt sich dann nicht alles aus wer sendet und wer empfaengt?" — for
// four of the five values it does. Not one of them is a lost CAPABILITY; each is an answer that
// moved to where it was already known, and all four are COLLAPSES rather than losses:
//
// * `origin` COLLAPSES into the HANDLE. `Engine::workspace()` has always resolved exactly one
//   workspace, so a per-call origin could only agree with it or be wrong — on the one value access
//   rights will hang off (nxf 6j6v.6aza). `Engine::origin()` is the READ that replaces it, and it
//   exists rather than the value simply vanishing because a caller still has to be able to name the
//   `<origin>/<actor>` handle it just wrote as.
//
// * `hop` COLLAPSES into the SESSION MAP, and had already done so in fact before it did in the type
//   (nxf 6j6v.m48m): `resolve_hop` takes `persisted.max(claimed)`, so a claim could only ever RAISE
//   the depth. What is given up is the ability to raise it — a host tracking a chain OUTSIDE any
//   session can no longer say "I am already eight deep". That host does not exist: the seam's chains
//   run through sessions, whose depths are recorded, and the CLI (which is handed `NXC_HOP` and has
//   no other way to be told) keeps `Ctx::hop` and keeps claiming.
//
// * `actor` COLLAPSES into `session` where there is one — provenance over assertion, design
//   2026-08-05 §4.1 — and STAYS as a field for the case there is none. That is the whole of what it
//   ever answered on its own.
//
// * `now` stays as an OVERRIDE and gains a default. The library still reads no environment; what it
//   now reads, in the ADAPTER and never in a verb, is the clock — see [`system_now`].
//
// The one that could NOT go is `session`, and the reason is on the field: it is the SENDER's, it is
// the return address, and without it a commission is a one-way trip.

/// The three values the ADAPTER resolves and a [`Caller`] no longer carries (nxf 6j6v.07me) — the
/// other half of the [`Ctx`] mapping, grouped so the one call site names each of three `&str`s
/// rather than lining them up positionally.
///
/// Where each now comes from, and why it left the caller:
///
/// * **`now`** — [`Caller::now`] if the caller pinned one, else [`system_now`]. See that field.
/// * **`origin`** — the HANDLE's answer ([`crate::engine::Engine::origin`]), never a parameter. One
///   handle is one workspace, so a per-call value could only ever agree with it or be wrong — and
///   it is the value access rights will hang off (nxf 6j6v.6aza), which makes "wrong" expensive
///   rather than cosmetic. The answer itself is [`crate::workspace::origin_of`] — the workspace's
///   own replica prefix, which the CLI also falls back to when `NXC_ORIGIN` is unset, so the two
///   seams cannot name one workspace differently; that function's doc carries the owner decision of
///   2026-08-21 that made it the prefix rather than a workspace-independent constant, where a
///   federated identity will land, and the accepted `adopt_prefix` hazard (nxf 6j6v.dnzt).
/// * **`actor`** — [`Caller::resolve_actor`]: the session map's persona, else the caller's
///   [`actor`](Caller::actor), else a named `validation` error.
///
/// The fourth value that left, [`Ctx::hop`], is not here: it is not resolved from anything, it is
/// simply not claimed. See [`into_ctx`](Caller::into_ctx).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Ambient<'a> {
    pub now: &'a str,
    pub origin: &'a str,
    pub actor: &'a str,
}

/// **What the ADAPTER resolves, as one value** — [`Ambient`]'s counterpart, and the other half
/// [`Caller::into_ctx`] joins.
///
/// The declaration catalogue, the worker, the timer, the workspace db path, the project `CLAUDE.md`
/// and — since nxf 6j6v.k8zq — the sibling modules' prime source all belong to whichever adapter is
/// in play: `cli.rs` resolves them from the environment and the workspace, [`crate::engine::Engine`]
/// from its own resolved workspace and its config. None of them is something a HOST knows to pass
/// per call, which is exactly what distinguishes them from [`Caller`].
///
/// **It is a struct because the list grows.** `into_ctx` took eight positional arguments once the
/// prime source joined, five of them adapter-resolved and three of them `&str`-shaped — the shape
/// where a transposition compiles. Grouping them puts every one behind its own name at both call
/// sites, which is the same argument [`Ambient`] already made for its three.
pub struct Adapter<'a> {
    pub defs: &'a Definitions,
    pub worker: &'a dyn Worker,
    pub timer: &'a dyn crate::timer::Timer,
    pub namer: &'a dyn crate::naming::Namer,
    pub db_path: &'a str,
    pub project_claude_md: Option<&'a str>,
    pub module_primes: Option<&'a dyn crate::facade::ModulePrimes>,
    pub machines: Option<&'a dyn crate::machine::Machines>,
}

impl<'a> Caller<'a> {
    /// The acting agent's BARE name for this call: the session's persona if the session map knows
    /// it, else the caller's own [`actor`](Caller::actor), else a named `validation` error.
    ///
    /// **Provenance beats assertion** (design 2026-08-05 §4.1). A session id was minted by whoever
    /// spawned that session, against the role it was spawned as ([`ChatStore::session_role`]), so
    /// reading the persona back from it is reading a record rather than believing a claim. That is
    /// the same asymmetry [`resolve_hop`] applies to the depth one line further on, and it is why a
    /// caller that hands over both does not get to override the record with the assertion.
    ///
    /// A session id that names no session of ours — a hand-set `NXC_SESSION`, a session from another
    /// workspace — resolves NOTHING, exactly as it contributes no depth in `resolve_hop`. Then the
    /// caller's `actor` is what is left, and its absence is the error rather than a default.
    ///
    /// **The two seams still answer the same**, which is why this adds no semantics: the sidecar
    /// stamps a spawned session's env with `NXC_SESSION = internal_session` AND
    /// `NXC_ACTOR = role.handle` (`worker.rs`) — the very pair `create_pending_session` recorded.
    /// So for a running persona, what the CLI reads out of `NXC_ACTOR` and what this reads out of
    /// the session map are the same name from the same write. The difference is only what happens
    /// when they are made to disagree, and there the record wins.
    pub fn resolve_actor(&self, store: &ChatStore) -> Result<String> {
        if let Some(session) = self.session {
            if let Some(role) = store.session_role(session)? {
                return Ok(role);
            }
        }
        self.actor.map(str::to_owned).ok_or_else(|| {
            NxfError::validation(
                "this call names nobody: it carries no `session` this workspace minted and no \
                 `actor`. Pass the `session` the call is made from — its persona is read back from \
                 the session map — or, where there is none (a human at a terminal, an app acting \
                 for its logged-in user), the `actor` doing the acting.",
            )
        })
    }

    /// Complete this caller into the [`Ctx`] a verb takes, with what the adapter resolved. Written
    /// once, here, next to both types: the mapping cannot drift out of step with `Ctx` because there
    /// is no second copy of it to forget.
    pub fn into_ctx(self, ambient: Ambient<'a>, adapter: Adapter<'a>) -> Ctx<'a> {
        Ctx {
            now: ambient.now,
            origin: ambient.origin,
            actor: ambient.actor,
            session: self.session,
            // `Caller.hop` stood here and is GONE (nxf 6j6v.07me). Not resolved from somewhere else
            // — CLAIMED BY NOBODY, which is a different thing and the reason the guard loses
            // nothing by it. `resolve_hop` reads the authoritative depth back from the caller's own
            // session and takes `persisted.max(claimed)`: since 6j6v.m48m a caller can only ever
            // RAISE the depth, never lower it, so a host working through sessions that passed `0`
            // was already contributing nothing but the possibility of getting it wrong upward. `0`
            // is therefore the whole of what an app loses, and the chain a session belongs to still
            // carries its own depth from the map (`tests/caller_seam.rs` drives one to the cap with
            // nothing passed at all). `Ctx::hop` STAYS: the CLI is the seam that still claims one,
            // from `NXC_HOP`, and that claim is exactly as much of a floor as it ever was.
            hop: 0,
            defs: adapter.defs,
            worker: adapter.worker,
            timer: adapter.timer,
            namer: adapter.namer,
            db_path: adapter.db_path,
            project_claude_md: adapter.project_claude_md,
            module_primes: adapter.module_primes,
            machines: adapter.machines,
        }
    }
}

/// The system clock as an RFC3339 instant — [`Caller::now`]'s default when a caller pins none.
///
/// **The one place this library reads a clock, and it is an ADAPTER default rather than a verb.**
/// The orchestration verbs still take `now` injected and read nothing; what changed in nxf 6j6v.07me
/// is that the handle answers for a caller that has nothing to say about it. `cli.rs` calls this for
/// the same fallback, one branch below its `NXC_NOW` read, so the two seams format one instant the
/// same way and the CLI's determinism pin stays where it belongs: at the CLI.
pub fn system_now() -> Result<String> {
    time::OffsetDateTime::now_utc()
        .format(&time::format_description::well_known::Rfc3339)
        .map_err(|e| NxfError::io(format!("formatting current time: {e}")))
}

/// Resolve which model a trigger runs on: **call beats step beats role**.
///
/// The call override lets an app offer a model picker for one task without rewriting the
/// definition; the role's own value is the floor. Exactly one function so the rule cannot drift
/// apart across the call sites that apply it.
///
/// **The middle level is not a DECLARED step's** (nxf 6j6v.4c3e), and reading it as one would get
/// the precedence backwards in the one direction that matters. A step of a `steps:` flow may not
/// name a model at all — `validate_channel_for_use` refuses the key by name — and what it MAY move
/// is the band, which sits BELOW a role's declared `model:` and is applied by
/// [`RoleDecl::effective_model_at`]. This slot is the one a HOST composes for a step of its own,
/// above everything the declaration says; no shipped path fills it since the run engine that did
/// went with 6j6v.dvyq §3.
pub fn resolve_model(
    call: Option<Model>,
    step: Option<Model>,
    role: Option<Model>,
) -> Option<Model> {
    call.or(step).or(role)
}

/// The env a trigger contributes to the spawned session: the ambient `NXC_ORIGIN`/`NXC_DB` stamps
/// plus the `NXC_HOP` the triggered session runs at.
///
/// Propagating the counter at all is the point (6j6v.zenf review finding #1): before it, `hop` was
/// checked but never propagated, so every hop of a real A→B→C chain read the counter from its OWN
/// ambient env (typically unset → 0) and the cap could only ever fire if someone hand-set
/// `NXC_HOP=33`. A free function, and the ONLY place a trigger's env is built, so no call site can
/// quietly reintroduce that by hand-rolling its own `Vec`.
///
/// **`depth` is the TARGET's depth, already resolved** — not the caller's, and not incremented here
/// (nxf 6j6v.ka09). It used to be the caller's, advanced inside this function, which was fine while
/// every trigger went one hop DEEPER; a trigger that travels back UP the chain runs at a depth this
/// function cannot derive from the caller's. [`trigger_role`] now works out the one number and hands
/// it to both consumers — this stamp and [`ChatStore::record_trigger_depth`] — so what the spawned
/// session is TOLD and what is RECORDED against it cannot disagree. That matters more than where the
/// `+ 1` lives: [`resolve_hop`] takes the larger of the two, so a stamp one higher than the record
/// would silently win.
pub fn trigger_env(origin: &str, db_path: &str, depth: u32) -> Vec<(String, String)> {
    vec![
        ("NXC_ORIGIN".to_string(), origin.to_string()),
        ("NXC_DB".to_string(), db_path.to_string()),
        ("NXC_HOP".to_string(), depth.to_string()),
    ]
}

// `TriggerWorkflow`, `trigger_run_id` and `prompt_workflow_for` stood here (nxf 6j6v.1wgd): which
// declared workflow's per-role block a trigger folded into its composed prompt, and which run it
// resolved that from. REMOVED with the run record (6j6v.dvyq §3). A summoned persona is told what
// it is part of by the DECLARATION it was summoned through and by the thread it must answer into;
// there is no second graph beside those to compose a block out of.

/// One trigger's own inputs — everything that varies per summon/resume, beside the ambient [`Ctx`].
///
/// Named fields rather than the positional list this grew out of (PR #267 review, Code Quality #2),
/// for the reason [`Caller`]'s own doc gives: a parameter list long enough to need a comment about
/// its order is one a transposition can survive compilation. It also lets [`CheckedHop`] arrive as a
/// field a call site must NAME rather than as a ninth positional `u32` — which is what the guard's
/// type-level enforcement is worth having.
pub struct RoleSpawn<'a> {
    /// Already resolved by the caller via [`Definitions::role`] — see [`trigger_role`] for why
    /// resolving it any later was a bug.
    pub decl: &'a RoleDecl,
    /// The internal session id this trigger runs under: freshly minted for a summon, the existing
    /// one for a resume.
    pub internal_session: String,
    /// The real SDK session to resume, when there is one. `None` starts a fresh session.
    pub resume_real: Option<String>,
    pub message: &'a str,
    /// **The named place that admitted this trigger** (nxf 6j6v.ntp9) — carried through
    /// [`trigger_role`] onto [`TriggerRequest::coordinator`], where it is what a test at the worker
    /// seam reads. A required field, so a ninth call site cannot be added without answering the
    /// question this item exists to make unavoidable: who stood between the sender and the role?
    pub coordinator: Coordinator,
    /// The effective choice from ABOVE the role, already collapsed by [`resolve_model`].
    pub model_override: Option<Model>,
    /// This chain's depth, having passed the guard — obtainable only from [`resolve_hop`].
    pub hop: CheckedHop,
    /// Which way along the chain this trigger runs, and therefore what [`hop`](RoleSpawn::hop) means
    /// for the depth the target ends up at — see [`ChainMove`].
    pub chain: ChainMove,
    /// The thread this trigger's caller has already declared, on ITS OWN thread, that it expects a
    /// reply from the target on (nxf 6j6v.jepk's `expects_reply_from`) — threaded to
    /// [`compose_system_prompt`] so the target is TOLD the obligation it was just given, not left to
    /// infer it (nxf 6j6v.enrs, the guidance half; enforcement is ticket 8). `None` on every path
    /// that declares no such expectation, which today is every caller but two:
    ///
    /// - [`coordinator_commission`], which sets it from exactly the condition that call site
    ///   already uses to decide whether to write `expects_reply_from` in the first place, not a
    ///   second, subtly different one.
    /// - [`fire_queued_trigger`], re-firing a trigger `coordinator_commission` originally parked.
    ///   It cannot re-run that condition — the register was already written before the entry was
    ///   queued — so it reproduces the RESULT instead, asking [`facade::owes_reply`] whether the
    ///   role still owes a reply in that thread. Same obligation, read back rather than re-decided;
    ///   its own doc argues this at length.
    ///
    /// **Not the same thing as [`thread`](RoleSpawn::thread)**, and conflating the two was a real
    /// defect (PR review of nxf 6j6v.303b, Finding 1): this one is an OBLIGATION, set only where this
    /// trigger registered one, and it is `None` on every path that triggers into a thread somebody
    /// else already put a quorum on.
    pub reply_thread: Option<&'a str>,
    /// The thread this trigger BELONGS to — the conversation it is part of, whoever owes a reply on
    /// it (nxf 6j6v.303b). This is what [`resolve_scope`] takes as its claim area and what
    /// [`needs_working_tree`] resolves the declared channel through; it is set wherever a thread
    /// exists at all, which is strictly more often than [`reply_thread`](RoleSpawn::reply_thread) is.
    ///
    /// **Why two fields and not one** (PR review, Finding 1). The first cut used `reply_thread` for
    /// both, and that silently disabled the CHANNEL half of the lease on the one path the epic's own
    /// §4 example is written for: `open_declared_channel_and_fan_out` opens a real board thread but
    /// passes `reply_thread: None`, because its expectation is a multi-handle quorum `facade::ask`
    /// registers, not a single-role obligation this trigger declares. So `send --to <channel>` — one
    /// of the two entrances the epic requires to contend for the same lease — never contended at all,
    /// run or no run. The same conflation cost a second case: an `exclusive` role summoned into a
    /// thread that ALREADY carries someone else's quorum gets `reply_thread: None` by design
    /// ([`coordinator_commission`] must not collapse that quorum), and fell through to `session:`
    /// scope —
    /// even though that thread's outstanding expectation is precisely the deterministic release
    /// signal the session rule demands.
    ///
    /// **What a thread scope guarantees, stated exactly** (corrected in nxf 6j6v.fe0f; it used to
    /// claim that a thread which exists always carries `expects_reply_from`). USUALLY it does —
    /// `facade::ask` writes one for a board, `coordinator_commission` for a fresh 1:1 — and then
    /// the
    /// lease has a deterministic done signal, which is the whole argument for preferring a thread
    /// scope over a session one. But [`role_resume`] passes a thread while registering NOTHING, and
    /// the thread it pushes into may already have had its quorum discharged. So the honest claim is
    /// narrower: a thread scope has a NAMEABLE claim area whose obligations can be read back at any
    /// time — sometimes none. What happens to a lease over a scope that owes nothing is decided in
    /// one place, [`release_working_tree_if_scope_is_done`], which frees it at the next reply into
    /// that same thread rather than holding it to the two-hour bound.
    pub thread: Option<&'a str>,
    /// How urgent this trigger is — used for **one** thing: the order it comes back out of the
    /// working-tree queue if it has to wait for the lease (nxf 6j6v.303b). It changes nothing about
    /// a trigger that runs immediately, which is every trigger a `shared` role ever makes.
    ///
    /// A field rather than a hardcoded [`Priority::Normal`] at the enqueue site because the ordering
    /// column would otherwise be dead: the queue sorts on `(priority, enqueued_at, id)` for the
    /// reason the epic states in the owner's own words — "change the button label" must not sit
    /// forty minutes behind "build the website" just because it arrived later, if its sender called
    /// it more urgent. The senders that HAVE such a judgement (`send --to`, whether it names a
    /// persona or a channel) carry a `priority` already and pass theirs straight
    /// through; the machine-driven triggers that have none (a channel fan-out, a completion wake)
    /// pass [`Priority::Normal`], which is what they would have been given anyway.
    pub priority: Priority,
    /// When this trigger FIRST joined the working-tree queue, if it is one being re-attempted from
    /// it (nxf 6j6v.fe0f). `None` — every call site except [`fire_queued_trigger`] — means "this
    /// trigger is new; if it has to wait, it joins the queue now".
    ///
    /// The other half of [`priority`](RoleSpawn::priority)'s argument, and it exists for the same
    /// narrow reason (PR review, Finding 2). The queue's order is `(priority, enqueued_at, id)`, and
    /// a promoted entry that loses the post-release race for the lease is re-queued through this very
    /// function — so without this it would re-enter stamped with the CURRENT instant and fall behind
    /// same-priority entries that arrived while it was waiting. Preserving the urgency but resetting
    /// the wait would honour half of one ordering key.
    pub queued_since: Option<&'a str>,
}

/// **What a trigger did, and what it noticed while doing it** — the outcomes [`trigger_role`]'s
/// callers cannot observe for themselves, since a queued trigger and a spawned one both leave a
/// persisted message and a minted session behind (nxf 6j6v.303b).
///
/// Returned instead of `()` precisely so that reporting a spawn is impossible on a path that did not
/// spawn: a receipt that claims a session is working while the trigger is sitting in a queue is the
/// silent-failure class this epic's §6 is written against, and a `()` return had no way to say
/// otherwise.
///
/// `#[non_exhaustive]` for the reason every enum on this surface is: it goes irreversibly public
/// with the facade, and this axis is one the epic itself already names a third answer for — a
/// `working_tree: isolated` trigger (nxf 6j6v.3npy, the reserved third value at the same declaration
/// field) neither spawns into the shared tree nor waits for it. A host that matches on this today
/// should not be broken by that landing.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum TriggerAdmission {
    /// The worker was handed the trigger. Either the working tree was not needed at all, or this
    /// trigger's scope now holds the lease — a fresh acquire and an inherit are the same answer
    /// here, deliberately, exactly as [`ChatStore::acquire_working_tree`] returns one `true` for
    /// both: the caller has nothing different to do.
    Spawned {
        /// **The role's declaration is not the one its last spawn ran under** (nxf 6j6v.pkw9).
        /// `None` on the ordinary path — a role that has never run here, or one whose declaration
        /// has not moved since it last did.
        ///
        /// It rides the admission for the reason
        /// [`findings`](TriggerAdmission::Queued::findings) do: only the funnel can see
        /// it (it is the one place that knows which declaration a prompt was composed from), and a
        /// caller that got a receipt back would otherwise read `warnings: []` over a session
        /// running under rules nobody meant to change. `with_admission` folds it into the receipt's
        /// `warnings` like every other finding.
        ///
        /// It can only be `Some` on THIS variant, and that is a property of where it is taken: the
        /// comparison happens once the worker HAS taken the trigger, so a queued trigger records
        /// nothing and compares nothing — that happens when its entry is fired, one spawn later.
        declaration_changed: Option<FailedConsequence>,
    },
    /// **Nothing was spawned.** A different chain holds the working tree, so this trigger's raw
    /// inputs went onto the working-tree queue instead and will be re-composed and fired when the
    /// holder releases (nxf 6j6v.fe0f). The message it belongs to IS persisted and the session IS
    /// minted — what did not happen is the spawn.
    ///
    /// Only a [`ChainMove::Deeper`] trigger can ever land here; see [`trigger_role`] for why an
    /// answer travelling back UP a chain is never parked.
    Queued {
        /// **What getting into that queue noticed** — EMPTY on the ordinary path, which is the
        /// overwhelming majority of queued triggers.
        ///
        /// Two things can land here, and both are built where the fact is known because nowhere
        /// else knows it ([`TriggerReceipt`] has no thread of its own to name):
        ///
        /// - **the drain this park could not arm** (nxf 6j6v.fabb; review of that branch, Code
        ///   Quality #3) — a [`ConsequenceClass::TickUnscheduled`] finding. Parking normally
        ///   schedules a tick for the holder's own bound, so the queue drains even if nobody else
        ///   ever comes; this says it did not, and it is REPORTED rather than only breadcrumbed for
        ///   6j6v.93zd's reason, which the sibling scheduling site states in the same words: a
        ///   caller whose commission is parked with no clock behind it would otherwise read
        ///   `warnings: []` while nothing was ever going to come back for it.
        /// - **what the PARK of the expired holder came to** (fix round 1 of nxf 6j6v.8bv9) — a
        ///   [`ConsequenceClass::WorkNotParked`] or [`ConsequenceClass::WorkHandedOnUnparked`]
        ///   finding. Since that item, a newcomer's own trigger no longer reclaims an expired lease
        ///   without saving the holder's work first ([`the_queue_goes_before_a_newcomer`]), so this
        ///   trigger is the one call in which that hand-off happened and its receipt is the only one
        ///   there is. Neither class changes a verb's exit code — see `crate::cli`'s
        ///   `changes_the_exit_code`.
        ///
        /// **A list rather than the single slot it used to be**, for the reason
        /// [`TriggerAdmission::Spawned`]'s own finding is folded into `warnings` one level up: a
        /// second field per fact is a second place to look, and a caller reading only the first is
        /// how a finding goes missing.
        findings: Vec<FailedConsequence>,
        /// The `scope_key` of whoever holds the lease ([`WorkScope::key`]'s form: `run:…` /
        /// `thread:…`).
        ///
        /// `None` is possible and is not "queued behind nobody": `nxc send` and `nxc reply` are
        /// separate processes, so the holder can release in the window between the refused
        /// compare-and-swap and this read. [`trigger_role`] retries the acquire once when that
        /// happens; `None` here means even the retry lost, which leaves nobody nameable but does not
        /// make the queue entry any less real. **Key "was I queued?" on `position`, never on this.**
        behind: Option<String>,
        /// 1-based position in the queue's own `(priority, enqueued_at, id)` order, as of this call.
        position: i64,
    },
}

/// Which way along the spawn chain one trigger runs (nxf 6j6v.ka09).
///
/// **Why the depth guard needs to know.** Every trigger used to be counted as one hop DEEPER, which
/// is right for the three quarters of them that commission new work and wrong for the quarter that
/// carry a result back. A long-lived role's answers travel back up the same chain its commissions
/// went down, so a wake that closed a link still raised the depth of the session it closed it *for*
/// — and [`ChatStore::record_trigger_depth`] never lowers. An orchestrator talking to a channel owner
/// gained four hops a round and was permanently refused after seven, with nothing able to bring it
/// back: `MAX` does not fall, and a session handover replaces the RUNTIME session, not the internal
/// one the depth hangs on.
///
/// **What it costs and what it keeps.** The counter now measures the OPEN chain — how much work is
/// commissioned and not yet answered — instead of every agent-to-agent hop a session ever took part
/// in. A chain that only ever commissions still runs out: [`Deeper`](ChainMove::Deeper) advances
/// monotonically exactly as before, so two roles pushing tasks at each other with `send --to` and
/// never answering still hit the cap, and so does a straight A→B→C→… descent. What the cap no
/// longer bounds is an endless alternation of COMPLETED request/answer pairs — but that shape is
/// indistinguishable from the legitimate dialogue above (they differ only in whether they stop), so
/// no depth counter could ever have had both. Bounding a conversation by volume is a different
/// instrument from bounding a chain by depth; nxf 6j6v.w1tx tracks it.
///
/// **The guard is a cost brake, so name what is left holding that axis** (PR #278 review, Integrity
/// #1). Nothing in the ENGINE bounds such a dialogue any more. What bounds it in practice is the
/// runtime underneath: a remote one reaps a session it has not heard from — AgentCore at 15 minutes
/// idle or 8 hours total, the case [`TriggerError::SessionGone`](crate::worker::TriggerError) was
/// added for — so a runaway conversation dies with its sessions rather than running until someone
/// notices the bill. That is a property of a particular runtime and not a guarantee this crate makes:
/// a `Worker` whose sessions never expire has nothing bounding this axis at all, which is the whole
/// content of 6j6v.w1tx.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ChainMove {
    /// **Down**: the target is being handed NEW work on the caller's behalf — a summon
    /// ([`coordinator_commission`]), a direct push into a live session ([`role_resume`]), a channel
    /// fan-out.
    /// The target lands one hop past the caller.
    Deeper,
    /// **Back up**: the target is being handed the RESULT of work it commissioned itself — a reply
    /// routed by its own return address ([`resume_return_address`]), or a completed board's wake to
    /// the requester that opened it ([`wake_role_requester`], [`route_completion`]). The link the
    /// caller was occupying closes, so the target re-enters at the depth it already had rather than
    /// below the session that answered it.
    Unwind,
}

impl ChainMove {
    /// The depth the triggered session runs at: `caller + 1` going down, the target's own recorded
    /// depth coming back up.
    ///
    /// `persisted` is read lazily because only [`Unwind`](ChainMove::Unwind) needs it, and it is
    /// passed in rather than looked up here so this stays a pure function the unit tests can pin
    /// without a store. `None` — a session id that was never minted — reads as `0` for the same
    /// reason [`resolve_hop`] treats it that way: an id naming no session of ours contributes
    /// nothing, and there is no earlier depth to preserve.
    fn depth_for(
        self,
        caller: CheckedHop,
        persisted: impl FnOnce() -> Result<Option<u32>>,
    ) -> Result<u32> {
        match self {
            ChainMove::Deeper => Ok(caller.get() + 1),
            ChainMove::Unwind => Ok(persisted()?.unwrap_or(0)),
        }
    }
}

/// Compose `decl`'s system prompt and trigger the worker — the summon/resume path every caller
/// shares: a fresh persona summon (`resume_real: None`, what `send --to <persona>` runs), a direct
/// [`role_resume`], `reply`'s return-address routing, and a channel supervisor commissioning a
/// member.
///
/// `decl` MUST already be resolved by the caller (via [`Definitions::role`]), because resolving it
/// HERE — after the message has already been posted — was the bug a previous review round fixed:
/// an unknown role left an orphan persisted message behind a misleading non-zero exit.
///
/// Compose the `nxs prime --persona <handle>` text for the persona a trigger is about to summon
/// (nxf 6j6v.k8zq) — the sibling modules' blocks its declaration admits, then chat's own.
///
/// Degrades rather than fails on both axes, and both are deliberate. With no
/// [`ModulePrimes`](crate::facade::ModulePrimes) provider wired, chat's half alone is composed:
/// that is the half that makes a summoned session able to ANSWER, and a host that supplies no
/// board and no memories should get a working persona rather than an error. With `prime: false`,
/// nothing is composed at all — the role declared that its own `system_prompt` covers this ground,
/// and the forced ending survives regardless ([`compose_system_prompt`]).
///
/// The consumer is the persona's own qualified handle, exactly as `nxc prime --persona` resolves it
/// for a session at the keyboard, so the two produce the same block for the same persona.
fn persona_prime_block(ctx: &Ctx, store: &ChatStore, decl: &RoleDecl) -> Result<String> {
    if !decl.prime.is_primed() {
        return Ok(String::new());
    }
    let services = decl.prime.services();
    let siblings = match ctx.module_primes {
        // `ctx.db_path` — the workspace THIS call resolved, not whatever the process cwd would
        // resolve to (review of PR #379, Code Quality #1). It is the same value the spawned
        // session gets stamped into its `NXC_DB`, so the persona's block and the persona's own
        // in-session `nxc` calls provably read one workspace.
        Some(source) => source.module_primes(services, ctx.db_path)?,
        None => Vec::new(),
    };
    let consumer = format!("{}/{}", ctx.origin, decl.handle);
    crate::facade::compose_persona_prime(
        store,
        &consumer,
        &decl.handle,
        services,
        &siblings,
        ctx.now,
        ctx.defs.source(),
    )
}

/// Prompt layering, in order: the prime block (the role's own identity, canonical `nxc` usage, and —
/// when [`RoleSpawn::reply_thread`] names one — the obligation to answer into that thread, nxf
/// 6j6v.enrs; all of which should anchor how the model reads everything after it), then the
/// project's `CLAUDE.md`, then the role's own `system_prompt`. A fourth layer stood at the end
/// until 6j6v.dvyq §3 — the per-role block of the run this trigger belonged to — and went with the
/// run engine; what a summoned persona is told about the work it is part of comes from the
/// declaration it was summoned through and from the thread it must answer into.
///
/// `model_override` is the effective choice from ABOVE the role — a caller's per-call override,
/// already collapsed by [`resolve_model`]. `None` defers to the role's
/// own declared model (and, if it declares none, to the SDK's default). Collapsing above the role
/// here rather than taking all three levels keeps this function unable to apply the precedence
/// twice.
///
/// **This is also where the spawn chain's depth is written** (nxf 6j6v.m48m), because this is the
/// one funnel every trigger passes through: the triggered session is stamped by the process doing
/// the spawning — with the same value [`trigger_env`] hands it as `NXC_HOP` — so the counter the
/// guard reads back later is not one the spawned role reported about itself. WHICH value that is
/// comes from `chain` ([`ChainMove`]): one past the caller for a commission, the target's own depth
/// for an answer travelling back up (nxf 6j6v.ka09).
///
/// **This is also where the working-tree lease is taken, inherited, or waited for** (nxf 6j6v.303b),
/// for the same reason the depth is written here: it is the one funnel every declared-role trigger
/// passes through, so there is exactly one place that can decide it. The gate answers three
/// questions in order, and answering "no" to any of them leaves today's behaviour byte-identical —
/// which is what `working_tree: shared` (the default every existing declaration reads as) always
/// gets:
///
/// 1. **Is this trigger commissioning work?** Only [`ChainMove::Deeper`] competes. A
///    [`ChainMove::Unwind`] carries the RESULT of work back up a chain that was already admitted —
///    parking one would withhold the very answer whose arrival releases the lease, deadlocking the
///    holder against a queue entry that can never be reached. It also cannot be reported: the wake
///    sites have a receipt for a wake that FAILED, none for a wake that was deferred.
/// 2. **Does the work need the working copy to itself?** `decl.working_tree == Exclusive`, or the
///    thread it runs in belongs to a channel declared so — see [`needs_working_tree`], which is
///    where the "the channel's declaration counts too" half lives.
/// 3. **Does this trigger belong to a chain that can be released?** [`resolve_scope`] answers
///    [`WorkScope::Session`] for a trigger carrying neither a run nor a thread, and such a trigger
///    has nowhere to declare an expectation and therefore no deterministic done signal to release
///    on (nxf 6j6v.jepk's finding about the thread-less trigger, whose CLI entrance the owner
///    declared deprecated in favour of `send --to` and 6j6v.dvyq §3 removed). Taking a lease there would create exactly the state this
///    epic must not create: one nobody can give back, with a queue stalled behind it until the
///    two-hour backstop. So a session-scoped trigger runs exactly as it does today — a lease nobody
///    can release is worse than no lease.
///
/// Only when all three say yes does the trigger compare-and-swap for the lease. `true` — a fresh
/// acquire or its own chain inheriting, indistinguishable and deliberately so — proceeds. `false`
/// enqueues the trigger's raw inputs and returns [`TriggerAdmission::Queued`] **without spawning
/// anything**.
///
/// **The depth is written on the queued path too**, which is why the gate sits AFTER
/// `record_trigger_depth` rather than before it: that write is `MAX`-based and idempotent, it must
/// precede any spawn (see its own comment), and a trigger that ends up queued is a trigger whose
/// spawn is merely later. Prompt composition, by contrast, happens after the gate — a composed
/// prompt is exactly what the queue deliberately does NOT store, because
/// the engine re-reads the declaration folder on every verb and the entry has to be re-composed
/// against whatever it says at release time.
pub fn trigger_role(
    ctx: &Ctx,
    store: &mut ChatStore,
    req: RoleSpawn,
) -> std::result::Result<TriggerAdmission, TriggerError> {
    let RoleSpawn {
        decl,
        internal_session,
        resume_real,
        message,
        coordinator,
        model_override,
        hop,
        chain,
        reply_thread,
        thread,
        priority,
        queued_since,
    } = req;
    // ONE number, derived once, for both consumers: what is recorded against the session and what
    // the session is told in `NXC_HOP`. `resolve_hop` takes the larger of the two later, so letting
    // them be computed apart is letting the higher of two independent expressions silently win.
    let depth = chain.depth_for(hop, || store.session_depth(&internal_session))?;
    // BEFORE the spawn, never after: `Worker::trigger` is fire-and-forget, so the session it starts
    // can already be calling back into `nxc` — and reading its own depth — while this call is still
    // returning. A depth written afterwards would leave exactly that window unguarded.
    //
    // The price, taken deliberately: a spawn that FAILS has still spent a hop of that session's
    // budget, so 33 retries against one session with a broken worker leave it uncallable. That is the
    // fail-closed direction of a trade with no third option — writing after a successful trigger
    // would make the guard depend on a detached process losing a race it should never be in — and the
    // scenario it costs is one where nothing was running anyway. A `ChainMove::Unwind` pays none of
    // it: that write is `MAX(depth, depth)`, a deliberate no-op kept on the shared path so there is
    // exactly one place a trigger's depth is written.
    store.record_trigger_depth(&internal_session, depth)?;

    // **What a session resuming after a park is told** (nxf 6j6v.de9s) — set inside the lease gate
    // below, at the one point both ways back converge, and put in front of the message further down.
    // `None` for every trigger that has nothing parked, which is every trigger this engine made
    // before that item.
    let mut park_notice: Option<(i64, String)> = None;

    // ---- the working-tree lease (nxf 6j6v.303b) — see this function's own doc for the three
    // questions and why each "no" leaves today's behaviour untouched.
    let needs_the_copy =
        chain == ChainMove::Deeper && needs_working_tree(ctx, store, decl, thread)?;
    // **An operation whose work is PARKED has to ask for the copy again, whatever its chain
    // direction** (nxf 6j6v.de9s). This is the one clause that widens the gate, and leaving it out
    // would undo the park: the answer to an escalation arrives as a `ChainMove::Unwind` resume
    // ([`resume_return_address`]), whose own comments state that it never reaches this gate — true
    // and correct while the operation still HELD the copy, because it was inside its own claim. A
    // park gives that claim away, so the same resume would walk into a working copy that now belongs
    // to somebody else, which is the collision the whole epic exists to prevent and would arrive by
    // the one door the epic left open.
    //
    // **The cheap question first.** [`ChatStore::any_parked_work`] is a single indexed read of a
    // table that is empty in every workspace where no escalation has ever gone unanswered under
    // contention; only a `true` there pays for [`lease_claim_root`]'s thread-tree walk. So a
    // workspace that never parks anything pays one trivial read per trigger and nothing else.
    let anything_parked = store.any_parked_work().unwrap_or_else(|e| {
        eprintln!("warning: could not tell whether any work is parked in this workspace: {e}");
        false
    });
    if needs_the_copy || anything_parked {
        // **The claim area is the OPERATION** (nxf 6j6v.8y6t) — the root of this trigger's thread
        // tree, so every step of one operation competes under one key and the release waits for the
        // operation rather than for the branch the exclusive step happened to start in. That
        // subsumes what stood here before it and keeps both properties it was written for: a
        // channel's members still share one claim (they share a root), and the acquire and release
        // ends still name the same area, now trivially — the key IS the root and
        // [`ChatStore::work_scope_threads`] is that root's subtree.
        let claim_thread = lease_claim_root(store, thread)?;
        let scope = resolve_scope(claim_thread.as_deref(), &internal_session);
        // Whether THIS operation is one of the parked ones. A trigger belonging to any other
        // operation leaves this gate exactly as it found it, which is what keeps `anything_parked`
        // above a cheap pre-filter rather than a change of behaviour for unrelated work.
        let resumes_parked_work = !needs_the_copy
            && !matches!(scope, WorkScope::Session(_))
            && !store.parked_work(&scope.key())?.is_empty();
        if (needs_the_copy || resumes_parked_work) && !matches!(scope, WorkScope::Session(_)) {
            let entry = QueuedTrigger {
                // Ignored on the way in — `enqueue_working_tree`'s AUTOINCREMENT assigns the real
                // one and hands it back.
                id: 0,
                scope_key: scope.key(),
                role: decl.handle.clone(),
                session: internal_session.clone(),
                // The BELONGS-TO thread, which is what `scope_key` above is derived from and what a
                // re-fire has to run in. The obligation half (`reply_thread`) is deliberately not
                // frozen here: `coordinator_commission` decides it from the thread's quorum
                // register AT
                // TRIGGER TIME, and re-deriving it when this entry is fired is the same discipline
                // that makes the entry store raw inputs instead of a composed prompt (nxf 6j6v.fe0f
                // owns that re-derivation).
                thread: thread.map(str::to_string),
                message: message.to_string(),
                // The choice from ABOVE the role, stored as it arrived and NOT collapsed with
                // `decl.effective_model()`: the entry carries raw inputs, and the role's own half is
                // re-read from the catalogue when this is fired, exactly as it would have been now.
                model: model_override,
                depth,
                // The ORDERING key, and a raw input like every other field here: an entry that came
                // back out `Urgent` and went back in as something else would lose the one judgement
                // the queue's order exists to honour (nxf 6j6v.fe0f re-fires through this very
                // function, so a promoted entry can be queued again).
                priority,
                // `None` for a trigger meeting the queue for the first time — `enqueue_working_tree`
                // then stamps `ctx.now`. `Some` only for a promotion that lost the race again, which
                // keeps the place in line it already waited for.
                enqueued_at: queued_since.map(str::to_string),
            };
            if let Some((behind, position, findings)) =
                acquire_or_queue(ctx, store, &scope, &entry)?
            {
                return Ok(TriggerAdmission::Queued {
                    behind,
                    position,
                    findings,
                });
            }
            // From here this operation HOLDS the working copy, which is what makes both of the
            // following the right thing to do here and nowhere else (nxf 6j6v.de9s).
            //
            // **Where it started**, recorded on its FIRST acquire and never again — correction 2 of
            // that item, and the value a park would otherwise have to guess. Best-effort: an
            // operation with no base recorded cannot be parked, which is a named refusal at park
            // time rather than a failed trigger here.
            record_the_operation_base(ctx, store, &scope);
            // **…and, if it was parked, back to its own files.** This is the one line both ways back
            // pass through: an answer arriving while the copy is free acquires straight through,
            // one arriving while it is busy is queued and re-fired through this same function.
            park_notice = resume_parked_work(ctx, store, &scope);
        }
    }

    // WHERE this session now is (nxf 6j6v.a71h §3.1) — the parent edge a `nxc send --to …` from the
    // session started below will resolve against.
    //
    // **After the queue gate, unlike the depth above, and the two are not the same kind of write.**
    // The depth is a MAX-based budget: writing it early can only ever be conservative, so the queued
    // path pays nothing for it. This is a POSITION, and a plain assignment by design (a session must
    // be able to move back). A trigger that only QUEUES starts nothing — so recording it there would
    // repoint a session that is at that moment still live in ANOTHER thread, and its next
    // `send --to` would hang under a thread it has not been given yet. The queue self-heals
    // (`fire_queued_trigger` re-fires through this very function and records it then), but the window
    // is exactly the window in which that session is running and can send. Recorded here, the
    // position is written when the session is genuinely put in motion, which is what it means.
    //
    // Still BEFORE the spawn, and that part is not negotiable for the same reason the depth is: the
    // session `trigger_and_bind` starts can already be calling `nxc send --to …` back into this store
    // while this call is still returning, and that send reads exactly this value. The residual is a
    // spawn that fails after this line, which leaves the position moved for a session that never
    // started — harmless, since nothing is running there to send anything, and the next thing that
    // does put it in motion moves it again.
    //
    // `RoleSpawn::thread` is the right source and `reply_thread` is not: the position is the
    // conversation the trigger BELONGS to, whoever owes a reply on it, which is what its own doc
    // says. A trigger naming no thread leaves the session where it was (see `record_session_thread`).
    store.record_session_thread(&internal_session, thread)?;
    // …and that it is in MOTION again (nxf 6j6v.y1t9). A session that once announced its end
    // carries `ended` for good — `mark_session_ended` is first-wins — and a CONTINUED one would
    // therefore be invisible to `unended_sessions_in_thread`, which is what the liveness gate of
    // nxf 6j6v.10yb reads. The gate would stop applying to exactly the sessions a resume creates.
    // Unconditional and beside the position above for the same reason: both are facts about a
    // session being put in motion, and a freshly minted one has no end to clear.
    store.reopen_session(&internal_session)?;

    // The per-role workflow block that used to be folded in here went with the run engine
    // (6j6v.dvyq §3). What a summoned persona is told about the work it is part of now comes from
    // the DECLARATION it is summoned through — the channel's own `members:`/`flow:` — and from the
    // thread it is told to answer into.
    // **What this persona knows before it reads its task** (nxf 6j6v.k8zq). A spawned session runs
    // with `settingSources: []` (SDK isolation, 6j6v.93hz), so no SessionStart hook fires and no
    // `nxs prime` ever runs in it — until this item the whole of what it was told about the suite
    // was four hand-written `nxc` verbs. The isolation stays; the knowledge comes in as text, on
    // the same path `CLAUDE.md` already takes.
    let prime_block = persona_prime_block(ctx, store, decl)?;
    // **The forced ending, and whether THIS step may answer with a verdict** (nxf 6j6v.553s (a)).
    // Derived here, at the one funnel every declared-role trigger passes through, rather than
    // carried down from the eight call sites that build a `RoleSpawn`: the answer is a property of
    // the durable record (which step this thread was opened for, and what that step declares), so a
    // re-fire out of the working-tree queue — which cannot re-run the condition its original
    // commission ran — reads back exactly what the first attempt would have said.
    //
    // **Asked of `reply_thread` and not of `thread`, deliberately, even though the walk behind it is
    // now the same one two lines down.** The offer modifies an OBLIGATION, and the obligation is
    // about the thread being answered — so a trigger that carries one asks the question of that
    // thread. The two coincide wherever an obligation exists today; deriving this from `thread`
    // instead would make that coincidence load-bearing, and the two fields exist precisely because
    // conflating them was once a real defect (see `RoleSpawn::reply_thread`).
    let obligation = match reply_thread {
        Some(thread) => Some(crate::role::ReplyObligation {
            thread,
            may_ask_for_rework: step_offers_rework(ctx, store, thread)?,
        }),
        None => None,
    };
    // **What the STEP makes of this role** (nxf 6j6v.6kam and nxf 6j6v.4c3e) — the fourth prompt
    // layer and the band this one station runs at, both read off the same durable derivation and
    // both `None` for every trigger outside a declared flow. See [`commissioning_step`] for why the
    // question is asked here, at the funnel, rather than answered by the call sites.
    let step = commissioning_step(ctx, store, thread)?;
    let composed = compose_system_prompt(
        decl,
        ctx.project_claude_md,
        obligation,
        &prime_block,
        step.and_then(|s| s.task.as_deref())
            .map(|text| crate::role::StepTask { text }),
    );
    // **Which version of the declaration this prompt was composed from** (nxf 6j6v.pkw9). Derived
    // here, at the funnel, for the reason the two derivations above it are: it is a property of the
    // declaration the prompt was ACTUALLY built from, which is the frozen catalogue for a re-fire
    // out of the queue and the folder for everything else — and the eight call sites do not each
    // know which of the two they hold. Recording it is below, after the spawn.
    let declaration_hash = crate::declaration_version::role_declaration_hash(decl);
    trigger_and_bind(
        ctx,
        store,
        TriggerRequest {
            internal_session: internal_session.clone(),
            resume_real,
            // **The park notice goes FIRST** (nxf 6j6v.de9s), ahead of the body, for exactly the
            // reason [`wake_message`] puts `ESCALATION_NOTICE` there: the body is what the model
            // reads, and a session that starts writing before it learns which branch its own work is
            // on writes into the wrong tree.
            message: match &park_notice {
                Some((_, notice)) => format!("{notice}\n\n{message}"),
                None => message.to_string(),
            },
            role: RoleSpec {
                handle: decl.handle.clone(),
                system_prompt: composed.system_prompt,
                use_claude_code_preset: composed.use_claude_code_preset,
                tools: decl.tools.clone(),
                // The role author's declaration is above; what the ENGINE adds because it is about
                // to DEMAND something is decided once, at the funnel below (nxf 6j6v.kffm).
                granted_tools: Vec::new(),
                permissions: decl.permissions.clone(),
                // The role's own half is [`RoleDecl::effective_model_at`] — its declared `model:`,
                // else the model class of whichever band applies: the one the STEP asked for (nxf
                // 6j6v.4c3e), else the role's own `stage:` (nxf 6j6v.p6m1). Everything ABOVE the
                // role was already collapsed into `model_override` by [`resolve_model`], so the two
                // precedences meet here exactly once.
                model: model_override
                    .or_else(|| decl.effective_model_at(step.and_then(|s| s.stage))),
                // The version stamp of the declaration the three lines above were read from (nxf
                // 6j6v.pkw9) — into the session's own `spec.json`, so "did this session run under
                // the rules I wrote?" is a comparison rather than a text probe on its prompt.
                declaration_hash: Some(declaration_hash.clone()),
            },
            // The one funnel: every declared-role trigger's `RoleSpawn::reply_thread` reaches the
            // worker through here, whichever call site set it (nxf 6j6v.7e9d, ticket 8's other
            // half — the sidecar's teardown is what actually acts on it).
            reply_thread: reply_thread.map(str::to_string),
            // …and the same funnel is what carries WHO admitted this spawn to the seam (nxf
            // 6j6v.ntp9). Relayed, never decided here: this function is the coordinator's spawning
            // step, not a coordinator itself, and inventing a value here would let a caller that
            // named none look exactly like one that did.
            coordinator,
            // The coordinator's terms for this turn, stated once for every path through this funnel
            // (nxf 6j6v.ntp9). Not a field on `RoleSpawn`: no call site has a different answer, and
            // a per-site value would be eight places to disagree about one bound. When a channel or
            // a persona may declare its own, THIS is the line that reads the declaration.
            terms: TurnTerms::default(),
            env: trigger_env(ctx.origin, ctx.db_path, depth),
        },
    )?;

    // The park this trigger came back for, marked as told — after the spawn, for
    // [`note_the_park_was_resumed`]'s reason, which is the same one the write below it gives.
    if let Some((id, _)) = park_notice {
        note_the_park_was_resumed(ctx, store, id);
    }

    // **…and this session is no longer the process a withdrawal stopped** (nxf 6j6v.27b9). A
    // follow-up into a withdrawn thread before the tick parked resumes the stopped session under
    // its own id in a NEW process; the tick's one further SIGTERM is meant for a process that
    // ignored the first, and would stop exactly the work this trigger was asked for.
    //
    // **AFTER the spawn, not beside the reopen above** (review of PR #483, Integrity #1). While the
    // stopped process is still there it holds the session's claim, and the worker REFUSES the
    // spawn (`TriggerError::AlreadyRunning`) — the `?` above returns before this line, and the row
    // stays: the process the tick may ask again is still the one the withdrawal stopped. Forgotten
    // before the spawn, that refusal disarmed the further SIGTERM and the wedged warning for the
    // very process that was ignoring the first. Best-effort, for the bind's reason: a bookkeeping
    // miss after a successful start is not a failed trigger.
    if let Err(e) = store.forget_withdrawn_session(&internal_session) {
        eprintln!(
            "warning: session {internal_session} was put back in motion, but forgetting that a \
             withdrawal had stopped it failed ({e}); a tick may still name it as pinning its \
             claim, and send it the one further SIGTERM a withdrawn session gets"
        );
    }

    // **AFTER the spawn, and that is the whole meaning of the row** (nxf 6j6v.pkw9): it holds the
    // version the last spawn of this role RAN under, so a trigger the worker refused must not
    // advance it. Recording before would make the very next spawn compare against a version nothing
    // ever ran, and swallow the change — the failure class this item exists to end.
    //
    // It is therefore the opposite decision from `record_trigger_depth` a screen up, for the
    // opposite reason: that write is a BUDGET, where counting a failed attempt is the conservative
    // direction, and it must precede the spawn because the child reads it back. This is a RECORD OF
    // WHAT HAPPENED, where counting a failed attempt is simply false.
    //
    // The price, stated: `trigger_and_bind` is fire-and-forget, so between it and this line the
    // child is already running and could spawn THIS SAME ROLE itself. Then the child writes first,
    // reports the change on ITS receipt, and this call — reading the child's row — reports nothing.
    // The change is named either way; which receipt carries it is what the race decides. That is a
    // far smaller cost than a failed spawn eating the report outright, and it needs a nested spawn
    // of the same role inside the milliseconds it takes to return from a `Command::spawn`.
    let declaration_changed = store
        .note_spawn_declaration(&decl.handle, &declaration_hash, ctx.now)?
        .map(|previous| {
            FailedConsequence::declaration_changed(
                thread,
                &internal_session,
                &decl.handle,
                &declaration_hash,
                &previous,
            )
        });
    Ok(TriggerAdmission::Spawned {
        declaration_changed,
    })
}

/// **Does the flow step this trigger SERVES declare a back edge?** (nxf 6j6v.553s (a), widened by
/// nxf 6j6v.0dr0) — the one derivation behind [`crate::role::ReplyObligation::may_ask_for_rework`],
/// and therefore the one thing that decides whether `--needs-rework` is offered to the session about
/// to be started.
///
/// [`commissioning_step`] does the walk; the one fact this adds is that the step it finds declares
/// `on_needs_rework:`.
///
/// `false` is the answer for every thread outside a stepped flow, which is every thread that existed
/// before either item — so the obligation such a session reads is byte-identical to what it was.
///
/// **It asked [`step_at`] until nxf 6j6v.0dr0, and that left the offer one level short of the
/// parties it exists for.** A step whose target is a whole CHANNEL stands on that channel's thread;
/// its MEMBERS each get a thread below that, and the flow mark is on the parent, not on them. So the
/// three reviewers of a review round — the shipped shape, and the one the back edge was declared for
/// — read the two-ending form while the same role addressed directly as a step's target was
/// offered three. The bit existed, the machinery routed it, and nobody told the parties expected to
/// pull it.
///
/// **What made that widening a decision and not a typo, and how it is answered.** The offer is a
/// promise that a verdict GOES somewhere, so it may only be made where one member's verdict really
/// moves the run. It does: [`slot_verdict`] is any-member-wins and recurses into a commissioned
/// channel's member threads, so ONE member answering `--needs-rework` routes the outer step back
/// over its edge (owner, 2026-08-29; held by
/// `one_checker_of_a_quorum_is_enough_to_send_the_round_back_and_the_fold_still_runs`). That answer
/// is confirmed rather than inherited here — nxf 6j6v.0dr0's third acceptance point — and it is what
/// makes the offer honest for every member and not only for whichever one the fold happens to agree
/// with. Were consolidation ever to become what carries the bit, this offer is the second thing that
/// would have to move.
///
/// **The rule that survives unchanged is the one 553s (a) is made of**: the bit is offered exactly
/// where it has somewhere to go. A member of a channel commissioned by a step that declares no back
/// edge is still not offered it, and neither is a persona such a member commissions itself —
/// [`commissioning_step`]'s own boundary, which this now shares.
fn step_offers_rework(ctx: &Ctx, store: &ChatStore, thread: &str) -> Result<bool> {
    Ok(commissioning_step(ctx, store, Some(thread))?.is_some_and(|s| s.on_needs_rework.is_some()))
}

/// **The declared step this thread IS the slot of** — the walk behind every question this module
/// asks of a step, in one place so the three of them cannot answer differently.
///
/// Three facts have to line up, and any of them missing is `None`: the thread carries a
/// [`ChatStore::flow_mark`] (so it IS a step of a stepped channel), its parent resolves to a
/// declared channel, and that channel declares a step under the marked id.
///
/// **Resolved through the PARENT and not through the thread's own `channel_id`.** A role slot lives
/// in its channel's own substrate channel, so the two agree there — but a step naming a nested
/// CHANNEL keeps that channel's id, and looking the mark up in the nested declaration would ask the
/// wrong file for the wrong step. The parent is where the supervisor that wrote the mark stands, on
/// both shapes.
///
/// The borrow is `ctx.defs`', which outlives this call: the caller may go on writing through `store`
/// with the step in hand, and does.
fn step_at<'a>(
    ctx: &Ctx<'a>,
    store: &ChatStore,
    thread: &str,
) -> Result<Option<&'a crate::channel::FlowStep>> {
    let Some(mark) = store.flow_mark(thread)? else {
        return Ok(None);
    };
    let Some(parent) = store.thread_parent(thread)? else {
        return Ok(None);
    };
    let Some(channel) = store
        .thread_channel(&parent)
        .as_deref()
        .and_then(|id| id.strip_prefix(DECLARED_CHANNEL_PREFIX))
        .and_then(|name| ctx.defs.channel(name))
    else {
        return Ok(None);
    };
    Ok(channel.step(&mark.step))
}

/// **The step whose commission this trigger is serving** (nxf 6j6v.6kam / nxf 6j6v.4c3e) — what the
/// funnel reads the fourth prompt layer and the stage override off, and since nxf 6j6v.0dr0 the
/// third ending too ([`step_offers_rework`]).
///
/// **Three readers, one derivation, and that is the point of naming it.** The prompt layer, the band
/// and the verdict offer are three different decisions — 6kam/4c3e deliberately left the third alone
/// — but each rests on the same question, *which declared step is this session working for*. They
/// came to disagree by ANSWERING it separately: the offer kept a walk of its own, one level
/// shallower, and was therefore wrong for exactly the shape the other two had already got right.
///
/// Two shapes, because a step commissions two kinds of thing and only one of them is a session:
///
/// * a step whose target is a ROLE stands on its own slot thread, and [`step_at`] finds it there;
/// * a step whose target is a whole CHANNEL stands on that channel's thread, which runs no session
///   at all — its MEMBERS do, one thread each below it. So a member's own thread carries no mark,
///   and the step that gave it its job is one level up.
///
/// The nearest step wins: a member of a nested channel that is ITSELF stepped answers from its own
/// mark and never looks up, so the layer a session reads is the one that commissioned that session
/// and not something inherited down an arbitrary depth of nesting.
///
/// **And the look upward is not "whatever my parent is serving".** A session serving a step may open
/// a conversation of its own — `nxc send --to <persona>` — and that thread hangs under the step's
/// slot exactly as a channel's member thread hangs under the channel thread. Reading the parent's
/// step there would hand the step's task and its band to somebody the step never named, which is the
/// opposite of what both fields mean. So the parent must BE the channel that step opened, and that
/// is asked as TWO questions, because either alone is answerable by the wrong thing:
///
/// * did the step's target resolve to a declared CHANNEL at all ([`flow_step_is_channel`], the one
///   tie-break, so this branch asks exactly what [`open_flow_step`] asked when it chose which kind
///   of thing to open);
/// * and is this parent that channel's own thread ([`ChatStore::thread_channel`]).
///
/// **The first question is not redundant, and the review of PR #454 is why it is here.** A ROLE wins
/// a name a channel also declares ([`crate::channel::flow_step_target`], and `tests/public_channel.rs`
/// ships that shape), while [`Definitions::new`] polices role handles and channel names in separate
/// namespaces — so a channel may be named after the very role its own step commissions. That role's
/// slot thread is opened in the CONTAINING channel, so a bare comparison of the slot's channel name
/// against the step's target string matched, and the leak this whole paragraph exists to prevent
/// came straight back. Held by
/// `a_persona_a_steps_session_commissions_itself_gets_neither_the_task_nor_the_band` and
/// `a_channel_named_after_the_role_its_own_step_commissions_leaks_nothing`, both red first.
///
/// **Derived here rather than carried down from the eight call sites that build a [`RoleSpawn`]**,
/// for [`step_offers_rework`]'s reason: this is a property of the DURABLE record — which step this
/// thread was opened for, and what that step declares in the version this operation is bound to — so
/// a re-fire out of the working-tree queue, which cannot re-run the condition its original
/// commission ran, reads back exactly what the first attempt would have said. It is also what keeps
/// [`QueuedTrigger`] storing raw inputs: neither field has to survive the wait.
///
/// `None` for every trigger outside a stepped flow, and for every step that declares neither — which
/// is what makes both capabilities cost an existing declaration nothing.
fn commissioning_step<'a>(
    ctx: &Ctx<'a>,
    store: &ChatStore,
    thread: Option<&str>,
) -> Result<Option<&'a crate::channel::FlowStep>> {
    let Some(thread) = thread else {
        return Ok(None);
    };
    if let Some(step) = step_at(ctx, store, thread)? {
        return Ok(Some(step));
    }
    let Some(parent) = store.thread_parent(thread)? else {
        return Ok(None);
    };
    let Some(step) = step_at(ctx, store, &parent)? else {
        return Ok(None);
    };
    let parent_is_what_the_step_commissioned = flow_step_is_channel(ctx, &step.target)
        && store
            .thread_channel(&parent)
            .as_deref()
            .and_then(|id| id.strip_prefix(DECLARED_CHANNEL_PREFIX))
            .is_some_and(|name| name == step.target);
    Ok(parent_is_what_the_step_commissioned.then_some(step))
}

/// Whether this trigger needs the working copy and its build directory TO ITSELF — the declaration
/// half of the lease gate (nxf 6j6v.303b, epic §4).
///
/// **Two declarations, either of which is enough**, and the second is not a nicety: the epic's own
/// example declares `working_tree: exclusive` on the `coding` CHANNEL, not on every role that might
/// be a member of it. A trigger into a thread that lives in such a channel therefore needs the lease
/// even when the role it summons says nothing at all — the work is exclusive because of what it is
/// part of, not because of who does it. Checking only `decl` would silently let a `shared` reviewer
/// fanned into an `exclusive` board run beside the coder it is reviewing.
///
/// **And the channel's answer is DERIVED UPWARD from its declared members** — nxf 6j6v.1xw1's first
/// acceptance point, resolved by [`Definitions::channel_needs_working_tree`], which also carries the
/// "one hop, not transitive" argument in full. An author who has already said `working_tree:
/// exclusive` on the persona that builds does not repeat it on every channel that persona is a
/// member of, and the whole channel counts as protected — which is what keeps a board from opening
/// half queued and half running, its two members on opposite sides of a lease meant to cover the
/// chain.
///
/// **Recognised the way every other declared-channel decision recognises it**: the substrate id of a
/// declared channel is `decl:<name>` (minted in exactly one place, `ensure_declared_channel`), and
/// the declaration behind that name comes from [`Definitions::declared_channel`] — the same
/// resolution `send`, `ask` and [`crate::surface::send_to`] all act through, including its
/// fail-closed half: a declared channel edited into invalidity is a `validation` error here rather
/// than a silent "not declared, so shared". That is the fail-VISIBLE direction; guessing `shared`
/// for a malformed declaration would be guessing the permissive answer.
///
/// **`thread` is [`RoleSpawn::thread`], never [`RoleSpawn::reply_thread`]** — the conversation this
/// trigger is part of, not the obligation it registered. See the field's own doc for the defect that
/// distinction fixes; passing the obligation here is what made this whole check unreachable on the
/// fan-out path.
///
/// **The channel is resolved in the two steps this crate always uses**, `threads` first and the
/// thread's own messages second (PR review, Finding 5). `ChatStore::thread_channel` reads the
/// `threads` view, which its own doc records as empty for M1-style threads that were never formally
/// opened; `thread_channel_via_message` is that path. Stopping at the first would fail OPEN — a
/// thread known only through its messages would read as `shared` — which is the permissive direction
/// this function argues against two paragraphs up. `surface::reply_in_thread` and `facade::reply`
/// already resolve a thread exactly this way.
///
/// The role's own declaration is checked FIRST and short-circuits, so an `exclusive` role costs no
/// store read at all, and a `shared` role with no thread costs none either.
fn needs_working_tree(
    ctx: &Ctx,
    store: &ChatStore,
    decl: &RoleDecl,
    thread: Option<&str>,
) -> Result<bool> {
    if decl.working_tree == WorkingTree::Exclusive {
        return Ok(true);
    }
    let Some(thread) = thread else {
        return Ok(false);
    };
    let Some(channel_id) = store
        .thread_channel(thread)
        .or_else(|| store.thread_channel_via_message(thread))
    else {
        return Ok(false);
    };
    let Some(name) = channel_id.strip_prefix(DECLARED_CHANNEL_PREFIX) else {
        return Ok(false);
    };
    let Some(channel) = ctx.defs.declared_channel(name)? else {
        return Ok(false);
    };
    Ok(ctx.defs.channel_needs_working_tree(channel))
}

/// Take the working-tree lease for `scope`, or park `entry` behind whoever has it.
///
/// `Ok(None)` — go ahead, `scope` holds the lease (freshly, or by inheriting its own). `Ok(Some((
/// behind, position)))` — nothing may spawn; `entry` is on the queue at `position`.
///
/// **Nothing here is one transaction, and that is the whole difficulty.** `nxc send` and `nxc reply`
/// are separate PROCESSES against the same file, and every `ChatStore` call below is its own implicit
/// transaction, so the holder can release between any two of them. Two windows follow, and this
/// function closes both — the second one only since the PR review of this ticket, which was right
/// that assigning it to the release path alone does not work: release-then-drain being atomic still
/// interleaves with acquire-then-`INSERT`.
///
/// - **Before the `INSERT`** — the compare-and-swap is refused, then the holder releases, then this
///   reads "who holds it?" and gets nobody. Queuing on that answer would park behind a lease that no
///   longer exists, while the release that would have drained the queue has already happened. One
///   more acquire attempt turns the common shape of that race back into an ordinary acquire, and
///   costs one statement only in the rare case where the read came back empty.
/// - **After the `INSERT`** — the last acquire fails, the holder releases and drains an EMPTY queue,
///   and only then does this row land. Nobody would ever start it: the release that was supposed to
///   is already over. So the acquire is attempted once more with the row in place, and on success
///   this takes its OWN entry straight back out (by id — never
///   [`ChatStore::take_working_tree_queue`], which pops whatever is most urgent and could swallow
///   somebody else's turn) and proceeds as an ordinary acquire.
///
/// The pre-`INSERT` attempt is therefore an optimisation and the post-`INSERT` one is the soundness
/// argument: the second alone would be correct, the first is what keeps the common case from
/// churning a row in and straight back out.
///
/// **Before any of that runs, the queue's own turn is handed out** (nxf 6j6v.yd4w). Both windows
/// above are about not LOSING a trigger; the third thing that can go wrong here is starting the
/// wrong one. The compare-and-swap reclaims an expired lease without looking at the queue, so a
/// chain that has never waited takes the working copy while a rival stands at position 1 — the one
/// place in this mechanism where waiting is punished by waiting. So
/// [`the_queue_goes_before_a_newcomer`] runs first, and everything below decides what is left.
///
/// The one remaining branch — the post-`INSERT` acquire succeeds but the entry is already gone — is
/// only reachable once a release path exists to drain it (nxf 6j6v.fe0f). It means somebody else is
/// firing this exact trigger, so this reports "queued, not spawned" and leaves the lease held: the
/// scope it names is the scope that entry runs under, so it is inherited, not stranded.
/// Whether the lease `holder_key` names ALREADY covers `scope` — every thread this claim would work
/// in lies inside the holder's claim area (nxf 6j6v.43kw).
///
/// **The deadlock this closes.** The claim area has been a SUBTREE since 6j6v.1xw1 — the
/// conversation the work was commissioned in together with everything opened beneath it — but only
/// the RELEASE side ever asked it that way. The acquire side resolved a thread ONE hop upward, and
/// only for a supervised channel member, so any exclusive claim opened from
/// inside a held area came out with a DIFFERENT `scope_key`, failed the exact-match compare-and-swap
/// in [`ChatStore::acquire_working_tree`], and queued **behind its own parent**. The parent could
/// then never release: question (2) of [`release_working_tree_if_scope_is_done`] asks whether
/// anything in its area still owes a reply, and what it was waiting for was the very trigger it had
/// just parked. Deadlock until the backstop — and, when this was written, past it, because nothing
/// drained the queue except a release (nxf 6j6v.fabb gave the drain a clock, and 6j6v.yd4w gave the
/// waiter the turn). It took no nested exclusive CHANNEL: a plain
/// `send --to <persona>` whose role declares `working_tree: exclusive` was enough, because
/// [`needs_working_tree`] answers on the declaration and not on where the trigger stands.
///
/// So this asks the RELEASE side's own question, [`ChatStore::work_scope_threads`], from the acquire
/// end. That is what makes [`lease_claim_root`]'s "acquire and release name the same area" true
/// rather than merely intended: one function decides what an area contains, and both ends read it.
///
/// **Since nxf 6j6v.8y6t the common case no longer reaches here at all**, and that is worth knowing
/// before reading the rest as load-bearing: [`lease_claim_root`] now resolves every trigger of one
/// operation to the SAME key — the operation's root — so nested work inside a held operation is an
/// exact-match inherit inside the compare-and-swap itself. What is left for this function is the
/// shape the CAS still cannot see: a thread that belongs to the holder's area without sharing its
/// root key, which a re-parenting or a hand-built tree can still produce. It is kept rather than
/// removed because it is the ONE place the two ends are checked against each other, and because
/// deleting a guard on the grounds that the shape it catches is now unreachable is how the shape
/// comes back.
///
/// **Being inside the area is necessary but NOT sufficient, and the second condition is the whole
/// safety argument.** This is not one atomic step with the refused compare-and-swap, and making it
/// one would not help: even a perfectly atomic answer says nothing about the instant AFTER it
/// returns, when the holder could release and hand the lease to a rival while this chain is already
/// walking in. What actually keeps that from happening is that the holder CANNOT release —
/// question (2) of [`release_working_tree_if_scope_is_done`] refuses to let a scope go while
/// anything in it still owes a reply. So the claim inherits only when
/// [`ChatStore::work_scope_has_outstanding`] says its own area is owed something right now: the
/// nested work is then pinned inside the lease it is inheriting, by an obligation whose discharge
/// IS the work finishing.
///
/// **An earlier version of this comment asserted that condition instead of checking it** — it
/// claimed that "by the time any trigger reaches this gate, `role_trigger_in` has already declared
/// the obligation" — quoted as written, under the name that function carried before nxf 6j6v.ntp9
/// renamed it [`coordinator_commission_in`] — which is true of exactly one caller. The branch
/// review of PR #339 found three
/// more, and one of them was an ordinary production surface rather than a corner: [`role_resume`]
/// — typed as `nxc send --session` until 6j6v.dvyq §3 removed both that flag and `Engine::
/// role_resume`, leaving the body with no surface above it — reaches this gate with
/// `chain: Deeper` and declares nothing at all
/// ("there is no obligation to tell this resumed session about", its own words). A resume pushed
/// into an otherwise-quiet thread inside a held area would have inherited on the strength of a
/// sentence that did not cover it, and the next reply anywhere in that area would then have handed
/// the working copy to a rival underneath it. Checking the condition costs one read and makes the
/// argument hold for every caller instead of for the one it was written about.
///
/// **The residual, named rather than papered over.** "Owed now" is not "owed throughout": the
/// obligation that pins the area can be a THIRD party's, on a thread this trigger merely joined
/// ([`coordinator_commission_in`]'s `declared_here: None` branch), and that party answering
/// discharges it
/// while this work continues. That is the same exposure [`role_resume`]'s own thread-scoped lease
/// already carries and which the release path documents as a decision — narrowed by the same gate,
/// since only a reply inside the chain's own area can trigger it. What is closed is the case where
/// NOTHING pinned the area at all.
///
/// **It does not widen anything else.** `false` for an unparseable holder key (see
/// [`WorkScope::parse`]), for a scope with no threads at all — a [`WorkScope::Session`] claim, which
/// never reaches here — and, the case that matters, for a rival chain: its threads hang under a root
/// of their own, so no part of it is inside the holder's area and it queues exactly as before.
fn inherits_the_held_claim(
    store: &ChatStore,
    holder_key: &str,
    scope: &WorkScope,
    now: &str,
) -> Result<bool> {
    let Some(holder) = WorkScope::parse(holder_key) else {
        return Ok(false);
    };
    let area = store.work_scope_threads(&holder)?;
    let mine = store.work_scope_threads(scope)?;
    if mine.is_empty() || !mine.iter().all(|t| area.contains(t)) {
        return Ok(false);
    }
    // The pin, not a second opinion on the first question — see this function's own doc.
    store.work_scope_has_outstanding(scope, now)
}

type Parked = (Option<String>, i64, Vec<FailedConsequence>);

/// **When this claim's lease runs out — the operation's OWN declared windows, not a flat two hours**
/// (nxf 6j6v.8y6t; owner, 2026-08-23: *"Die 2-Stunden-Grenze ergibt keinen Sinn. Sie muss an den
/// Timeouts der einzelnen Aktionen hängen."*).
///
/// The rule is one sentence: **a lease runs to the last window its own area declared, and falls back
/// to [`WORKING_TREE_LEASE_BOUND`] only where something in it declared none.**
///
/// ```text
/// every outstanding obligation in the area carries a deadline  ->  the LATEST of them
/// any of them carries none (or nothing is outstanding yet)     ->  now + WORKING_TREE_LEASE_BOUND
/// ```
///
/// It is re-derived on every acquire, so a chain rides its bound forward exactly as it did before —
/// what changes is where the number comes from.
///
/// **Question one of the owner's note, answered: what applies to a step that declares no timeout.**
/// It has no window of its own, so it has no promise to hold the lease to, and one such step decides
/// for the whole area: the fallback applies. That is the safe direction (hold, then reclaim at the
/// backstop, rather than reclaim early), it keeps today's behaviour byte-for-byte for every
/// declaration written before this item, and it makes the incentive plain — declare `timeout:` on
/// your channels and this device reclaims the checkout on YOUR terms instead of on a two-hour guess.
/// The engine's own fallback chain still runs first, so "declares none" means none at any level: not
/// the channel's `timeout:`, not the thread's `--deadline`.
///
/// **What this closes that the flat bound could not**, and it is a residual
/// [`WORKING_TREE_LEASE_BOUND`]'s own doc has been carrying: a chain whose steps legitimately run
/// LONGER than two hours — a declared `timeout: 6h` review round — used to lose the lease under
/// itself while it worked, and the next chain could take the working copy while the first still had
/// hands on the git index. A 6h round now holds a 6h lease, because that is what it declared.
///
/// **And what makes the other direction safe.** A derived bound can also land SOONER than two hours,
/// which is the point — but a bound that lands while the work is genuinely still running must not
/// hand the checkout to a rival. So the acquire path asks the same liveness question the sweep has
/// always asked before reclaiming ([`expired_but_still_writing`]): an expired lease whose chain
/// still has a live process is not free. See there for question two of the owner's note.
///
/// **What it costs, named rather than left to be found** (review of PR #376, Integrity #4). Every
/// acquire — including the common INHERIT, where the answer is a renewal and nothing queues — now
/// pays a subtree walk plus one quorum read over the whole operation, where before it paid a single
/// date addition. That is deliberate and not free: the bound has to be re-derived on each trigger for
/// a chain to ride it forward, and it is the operation's CURRENT obligations it must be derived
/// from. The read is the same bulk one the release side already makes on every reply, with the same
/// [`crate::facade::MAX_BOUND_IDS`] ceiling behind it — past which an operation of more than 500
/// live threads reads the workspace's quorums instead of binding a list. An operation that large
/// would be paying that on its replies already.
fn operation_lease_expiry(ctx: &Ctx, store: &ChatStore, scope: &WorkScope) -> Result<String> {
    let fallback =
        facade::resolve_instant(ctx.now, WORKING_TREE_LEASE_BOUND, "the working-tree lease")?;
    let area = store.work_scope_threads(scope)?;
    Ok(store
        .declared_window_end(&area, ctx.now)?
        .unwrap_or(fallback))
}

fn acquire_or_queue(
    ctx: &Ctx,
    store: &mut ChatStore,
    scope: &WorkScope,
    entry: &QueuedTrigger,
) -> Result<Option<Parked>> {
    let expires = operation_lease_expiry(ctx, store, scope)?;
    let live_holder = expired_but_still_writing(ctx, store, scope, entry.thread.as_deref())?;
    // What this trigger's own arrival noticed on the way into the queue — see
    // [`TriggerAdmission::Queued`]'s `findings` for the two things that land here.
    let mut findings: Vec<FailedConsequence> = Vec::new();
    // **Is the copy PINNED where it is?** Two states say yes, and both mean the compare-and-swap
    // below must not run: a chain whose bound has passed and whose process has NOT, and — since fix
    // round 1 of nxf 6j6v.8bv9 — an expired holder whose work could not be parked for a reason that
    // can pass. The second is set inside the `None` arm, because only the attempt can tell.
    let mut pinned = live_holder.is_some();
    let behind = match &live_holder {
        // Held by a chain whose bound has passed and whose process has NOT — the compare-and-swap is
        // skipped entirely rather than allowed to win on the clock. See `expired_but_still_writing`.
        Some(holder) => Some(holder.clone()),
        None => {
            // **Whoever is ALREADY in the queue goes first** (nxf 6j6v.yd4w). The lease may be an
            // expired row that nothing has swept yet, with a rival parked behind it since before
            // this trigger existed; reclaiming it in the compare-and-swap below would overtake
            // them, because that statement never looks at the queue. So the queue's turn is handed
            // out first, and this trigger then competes for whatever is left — which, when somebody
            // was waiting, is a lease the promoted area now holds.
            //
            // **And that hand-off PARKS the expired holder's work first** (fix round 1 of nxf
            // 6j6v.8bv9), which is why it can now answer "the copy is staying where it is": a park
            // refused for a reason that can pass keeps the claim, on this path exactly as on the
            // tick's, and this trigger then queues behind that holder as it would have while the
            // lease was live.
            //
            // **Including when NOBODY is queued** (final review of this branch): there is no
            // fairness question then, but the copy still leaves a holder that came to grief — for
            // this very trigger — so it parks first and the compare-and-swap below then takes a
            // clean tree. See that function's doc for why the two questions had to be separated.
            match the_queue_goes_before_a_newcomer(ctx, store, scope, &mut findings)? {
                Some(holder) => {
                    pinned = true;
                    Some(holder)
                }
                None => {
                    if store.acquire_working_tree(scope, ctx.now, &expires)? {
                        return Ok(None);
                    }
                    let behind = match store.working_tree_holder(ctx.now)? {
                        Some(holder) => Some(holder),
                        None => {
                            if store.acquire_working_tree(scope, ctx.now, &expires)? {
                                return Ok(None);
                            }
                            store.working_tree_holder(ctx.now)?
                        }
                    };
                    // Refused, and somebody holds it — but the refusal is only meaningful if that
                    // somebody is a DIFFERENT chain (nxf 6j6v.43kw). Work commissioned from INSIDE
                    // the held area is the holder's own work: it inherits, exactly as a channel's
                    // second member inherits from its first.
                    if let Some(holder) = &behind {
                        if inherits_the_held_claim(store, holder, scope, ctx.now)? {
                            return Ok(None);
                        }
                    }
                    behind
                }
            }
        }
    };
    let id = store.enqueue_working_tree(entry, ctx.now)?;
    // The last attempt, for the holder that released between the refusal above and this INSERT —
    // and skipped where the copy is PINNED rather than merely claimed, because there the clock would
    // let it through and what is in the way is not a deadline: a live process, or work that is still
    // uncommitted in the tree because its park was refused.
    if !pinned && store.acquire_working_tree(scope, ctx.now, &expires)? {
        if store.remove_working_tree_queue_entry(id)? {
            return Ok(None);
        }
        // Already drained by somebody else; see this function's doc. Position 1 is not a fudge —
        // an entry that a drain has just taken IS the head. Nothing to arm: it is being FIRED.
        return Ok(Some((behind, 1, findings)));
    }
    // PARKED, and from here on something has to come back for it (nxf 6j6v.fabb). Arm the holder's
    // own bound: past it the lease holds nothing, and until 6j6v.fabb nothing swept the table or
    // polled the queue, so a commission parked behind a chain that then died waited past the bound
    // indefinitely. The instant is the HOLDER's expiry read off the lease row, not `expires` above
    // — that is what THIS trigger's lease would have run to, and it is not the one in the way.
    //
    // **A bound already in the past is armed on the liveness clock instead** (nxf 6j6v.8y6t): that
    // is the `expired_but_still_writing` case, where what the queue is waiting for is a process to
    // end rather than a deadline to pass, and 6j6v.858n's re-check interval is the one this house
    // already uses for exactly that wait. Arming the past instant would fire a tick immediately, let
    // the sweep decline on the same liveness read, and re-arm — the same answer, one round trip
    // later, on every parked commission. **Since nxf 6j6v.xb24 that clock is a candidate on every
    // call rather than on this case alone** — a holder inside a bound two hours out can die at any
    // moment — so what is special here is only that the bound loses, not that the cadence is asked
    // for; `drain_recheck_instant` is where the one rule is written.
    //
    // **And the SECOND clock this wait can end on** (nxf 6j6v.de9s): this entry arriving is one of
    // the two events that can make the lease CONTENDED, so the derivation runs here, right after the
    // row lands and before anything is armed. When it stands, the park deadline is usually the
    // earlier of the two instants, and [`drain_recheck_instant`] is what picks between them — one
    // function, for the reason its own doc gives at length.
    let contended_since = match note_the_contention(ctx, store) {
        Ok(since) => since,
        Err(e) => {
            eprintln!("warning: could not tell whether the working copy is contended: {e}");
            None
        }
    };
    let unarmed = match store.working_tree_lease_row() {
        Ok(Some((_, holder_expires))) => {
            match drain_recheck_instant(ctx.now, &holder_expires, contended_since.as_deref()) {
                Ok(when) => arm_the_lease_bound(ctx, store, entry, &when),
                Err(e) => unarmed_drain_finding(
                    store,
                    entry,
                    &format!("its instant could not be resolved: {e}"),
                ),
            }
        }
        // Nothing holds it any more — the acquire above already lost that race, and the drain has
        // nothing to wait for.
        Ok(None) => None,
        // STATED, not swallowed (review of this branch, Integrity #9): silently arming nothing
        // leaves the commission parked with no clock, which is the exact state this item removes.
        Err(e) => {
            unarmed_drain_finding(store, entry, &format!("its expiry could not be read: {e}"))
        }
    };
    findings.extend(unarmed);
    match store.working_tree_queue_position(id) {
        Ok(position) => Ok(Some((behind, position, findings))),
        // The SAME "already drained" answer as the branch above, reached by the other order of
        // events (PR review of nxf 6j6v.303b, carried into 6j6v.fe0f): a release path can take this
        // very row between the `INSERT` and this read, and `working_tree_queue_position` reports a
        // row it cannot find as `not_found`. Failing the trigger on that would be the worst
        // available answer — the message is persisted, the session is minted, and the entry is at
        // that moment being FIRED by whoever drained it. An entry a drain has just taken was the
        // head, so the position is 1, exactly as above. Any other error is still an error.
        Err(e) if e.kind == ErrorKind::NotFound => Ok(Some((behind, 1, findings))),
        Err(e) => Err(e),
    }
}

/// **Hand an expired lease to whoever is already waiting, before the caller reclaims it** (nxf
/// 6j6v.yd4w, the ticket's first acceptance criterion).
///
/// The bug this closes was measured in the acceptance run of 6j6v.dbwn and pinned there as an
/// assurance rather than left out: the queue was drained by a RELEASE and by nothing else, while an
/// expired lease was reclaimed by [`ChatStore::acquire_working_tree`] in a single compare-and-swap
/// that never asks whether anybody is queued. So the chain that happened to ask at that moment took
/// the working copy and started, and the rival standing at position 1 — who had been waiting for
/// exactly this — stayed at position 1. Waiting was punished by waiting.
///
/// It is not the same gap 6j6v.fabb closed, and the two are easy to confuse. That one was "nobody
/// ever comes back for a parked commission": [`sweep_expired_working_tree`] and
/// [`arm_the_lease_bound`] answered it, so a waiter is now reached even when nothing else happens
/// on this device. This one is about who wins when somebody DOES come — and the sweep cannot answer
/// it, because a newcomer's own trigger is precisely the event that runs no sweep.
///
/// **It PARKS the holder's work first, and can therefore also answer "nobody gets it"** (fix round 1
/// of nxf 6j6v.8bv9). This is the same occasion [`sweep_expired_working_tree`] acts on —
/// [`ParkOccasion::PastItsBound`], a lease run out with no live process behind it — reached by the
/// other door, and it had every one of that function's guards except the park: whenever a newcomer's
/// own trigger got here before a tick did, the dead holder's uncommitted work was handed on still
/// sitting in the tree, which is the defect the whole occasion exists to remove. So it goes through
/// the same [`park_and_hand_on`], under the same occasion, with the same refusal rule.
///
/// What the refusal rule means HERE is the return value: [`ParkOutcome::Held`] answers `Some(holder)`
/// — the copy is staying, and [`acquire_or_queue`] must skip its compare-and-swap and queue behind
/// that holder, exactly as it does for a lease whose process is still alive. That is not an exception
/// to this function's fairness rule but its ordinary reading: nobody gets the copy, so nobody is
/// overtaken, and the tick's retry is what eventually moves it.
///
/// **This path never retries a park and never clears a refusal's row.** Both belong to the tick —
/// `park_step` retries, and the sweep forgets a row whose occasion has passed. A trigger is not a
/// clock, and a newcomer arriving is no evidence that anything about the holder has changed.
///
/// **An EMPTY queue is no reason to skip the park** (final review of this branch, Finding 1), and
/// the park therefore happens BEFORE the queue is consulted at all. The two questions were run
/// together and they are not the same question. Fairness needs somebody to be waiting — with an
/// empty queue there is nobody to overtake and nothing to decide — but the park is not about
/// fairness: it is about the working copy LEAVING a holder that came to grief, and with nobody
/// queued the newcomer is itself what it leaves for. Deciding the empty queue first meant that the
/// most ordinary shape on this device — one agent, working alone, that crashes with uncommitted
/// work, a bound that passes, the next `nxc send` — fell through to
/// [`ChatStore::acquire_working_tree`], whose compare-and-swap reclaims any expired row, and the
/// newcomer started inside the dead holder's files. **And the tick cannot stand in for it**:
/// [`sweep_expired_working_tree`] returns on an empty queue deliberately, because nothing is handed
/// on there — which is right for the sweep and is exactly why this door has to do it.
///
/// So what the queue decides here is only who is on the OTHER side of the hand-off — the chain that
/// was already in line, or the caller — and the refusal rule is the same either way: on
/// [`ParkOutcome::Held`] nobody takes the copy, the newcomer included.
///
/// **The four "no"s, and none of them is a nicety.**
///
/// - **No lease row, or a lease still inside its bound** — nothing to reclaim, so nothing to
///   overtake anybody with. The ordinary acquire decides, exactly as before this item.
/// - **The expired row is the CALLER'S OWN** — a chain re-acquiring for its next step, which
///   [`ChatStore::acquire_working_tree`] treats as an inherit and renews. Handing the copy to the
///   queue there would take it from a chain that is at that instant demonstrably still working,
///   which is the silent mid-chain collision epic 6j6v.bqe0 exists to prevent. A chain never loses
///   the working copy to the queue on its own trigger; a tick's sweep may still reclaim it, and
///   that path asks the liveness question this one is not entitled to skip.
/// - **The holder's key cannot be read** — [`WorkScope::parse`] said no, so the chain's threads
///   cannot be resolved and its liveness cannot be asked. [`expired_but_still_writing`] answers
///   `None` for that shape WITHOUT having asked, so draining on the strength of that `None` would
///   be draining on a question nobody put. The sweep declines on the same condition and says so;
///   this is the acquire end of that decline.
/// - **A park of this holder is already refused** ([`park_is_refused`]) — the last, added with the
///   park itself. A refusal on record is always a transient one, so the copy is already staying and
///   somebody is already retrying; attempting the identical park again would meet the identical
///   answer and overwrite the row of whichever occasion owns it.
///
/// **What it costs, named rather than left to be found** (the discipline the review of PR #376 set
/// for [`operation_lease_expiry`], applied to this line). Every acquire that gets past
/// [`expired_but_still_writing`] now pays up to two extra single-row reads before the
/// compare-and-swap — the lease row and the holder-as-of-now — and an acquire that goes on to park
/// reads the queue head as well, for the sentence its finding carries. Each is an indexed read of
/// one row on a device-local table, and the common shapes stop at the first or second — no lease row
/// at all, or a lease still inside its bound. Beside the subtree walk plus quorum read the same
/// function already pays to derive its own bound, this is noise; it is written down anyway, because
/// "one more cheap read on the trigger path" is the sentence that stops being true when it is never
/// counted.
///
/// **What an acquire past those two reads costs is no longer only reads**, and that is the price of
/// the paragraph above: where the queue was empty this used to return, and now it attempts a park —
/// a git status, a commit and a checkout in the worst case, on the trigger's own thread. It is paid
/// only on the occasion itself (an expired, foreign lease with no live process behind it), which is
/// trouble by definition and is exactly the moment the tick would otherwise have to pay for; a
/// workspace whose worker names no directory pays one field read and a permanent refusal
/// ([`the_working_copy`]).
///
/// **Liveness is not re-asked here, and that is deliberate rather than forgotten.** The only caller
/// reaches this line with [`expired_but_still_writing`] having just answered `None` for this very
/// lease, which is precisely "expired, foreign, and no session in the holding chain has a live
/// process" — the sweep's own condition. Asking again would be a second subtree walk and a second
/// worker round trip per trigger for an answer that cannot have changed usefully in between, and
/// the value would be stale in the same way either way. What DOES protect the narrow race — the
/// holder renewing between that read and this write — is the guard inside
/// [`ChatStore::reclaim_expired_working_tree_and_take_next`], which names the exact `expires` that
/// was read.
fn the_queue_goes_before_a_newcomer(
    ctx: &Ctx,
    store: &mut ChatStore,
    mine: &WorkScope,
    warnings: &mut Vec<FailedConsequence>,
) -> Result<Option<String>> {
    let Some((holder_key, expires)) = store.working_tree_lease_row()? else {
        return Ok(None);
    };
    if holder_key == mine.key() {
        return Ok(None);
    }
    if store.working_tree_holder(ctx.now)?.is_some() {
        return Ok(None);
    }
    let Some(scope) = WorkScope::parse(&holder_key) else {
        return Ok(None);
    };
    // **A park of this holder is already refused, and the tick owns the retry.** Attempting it again
    // here would meet the identical refusal and, through [`ChatStore::note_park_refusal`], overwrite
    // the row with THIS occasion — restarting the "retrying since" of whichever occasion is actually
    // coming back for it. So the answer is the one the row already carries: the copy stays. This is
    // the acquire end of the sweep's `park_already_held`, and a row-read is the right check here
    // where it would not be there: a refusal on record is always a TRANSIENT one (a permanent
    // refusal hands the copy on and never records), and this path is not the one that retries.
    if park_is_refused(store, &holder_key) {
        return Ok(Some(holder_key));
    }
    // The claim ROOT, which is what the scope key names — the same anchor the sweep and
    // `park_the_stranded_holder` put their findings on.
    let anchor = match &scope {
        WorkScope::Thread(t) => Some(t.as_str()),
        WorkScope::Session(_) => None,
    };
    // Who the copy is about to go to — read for the SENTENCE and not for a decision: the park runs
    // either way (see this function's doc), and what the queue changes is only whether the finding a
    // refusal carries says "something else is waiting" or "this trigger is taking it over".
    let waiting = store.peek_working_tree_queue()?.is_some();
    let who = if waiting {
        "and something else is waiting for the copy"
    } else {
        "and this trigger is taking the copy over"
    };
    let why = format!(
        "operation {holder_key} has been holding this workspace's working copy past its bound \
         ({expires}) with nothing running in it any more, {who}"
    );
    let outcome = park_and_hand_on(
        ctx,
        store,
        &holder_key,
        HandOff::Expired {
            holder_key: &holder_key,
            expires: &expires,
        },
        &why,
        warnings,
        anchor,
        ParkOccasion::PastItsBound,
    )?;
    match outcome {
        // The copy left the holder — with its work on a branch, or (a permanent refusal) with a
        // named warning saying it is still in the tree. To whoever was already in line if anybody
        // was; otherwise the lease row is simply gone, and the caller's own compare-and-swap takes
        // the free copy one statement later, which is what `Ok(None)` means on both counts.
        ParkOutcome::Parked { .. } | ParkOutcome::HandedOnUnparked { .. } => Ok(None),
        // The rule's transient half. Not an exception to this function's fairness rule but the
        // ordinary reading of it: nobody gets the copy, so nobody is overtaken.
        ParkOutcome::Held { .. } => Ok(Some(holder_key)),
    }
}

/// **Is the working copy held by a chain whose lease has run out but whose process has not?** (nxf
/// 6j6v.8y6t) — the scope key of that chain, or `None` when the lease is free, unexpired, or this
/// caller's own.
///
/// This is question two of the owner's note — *what happens when a step hangs without tripping its
/// timeout* — answered where it actually bites. The flat two-hour bound was called the net for that
/// case, and it was the wrong shape of net: a hung process does not stop being a writer when a wall
/// clock passes, so all the bound ever bought there was the ability to hand the checkout to a rival
/// WHILE the hung step was still writing into it. [`WORKING_TREE_LEASE_BOUND`]'s own doc names that
/// as the "too short" failure it could not close.
///
/// What watches a hang now is nxf 6j6v.858n's clock, and it is a better net than a deadline: on a
/// channel that needs the copy to itself the flow does not advance past a step whose session is
/// still alive, and a re-check is scheduled every minute for as long as the process is there — so a
/// hang is a visible, watched wait, and the moment the process is gone the flow moves by itself.
/// This gate reads that same fact from the ACQUIRE end. The sweep
/// ([`sweep_expired_working_tree`]) has asked it before reclaiming since nxf 6j6v.fabb; asking it
/// here too is what makes [`operation_lease_expiry`]'s derived — and possibly much shorter — bound
/// safe rather than merely shorter.
///
/// **Fail-open, in the same direction as the sweep.** A worker that cannot tell whether a session is
/// running answers `false` for every session — and says so, if asked
/// ([`Worker::answers_liveness`](crate::worker::Worker::answers_liveness)) — so a runtime with no
/// processes to look at behaves exactly as it did before this item: the clock decides, alone. A read error on the way is treated
/// the same way rather than propagated — refusing to trigger because a liveness read failed would
/// turn a diagnostic into an outage, and the fallback is precisely the pre-existing behaviour.
///
/// `waiting_thread` is `entry.thread` from the caller's own `QueuedTrigger` — the commission the
/// read-error warning is about: this commission's own, not a thread inside the chain being asked
/// about. Naming a thread in the HOLDING chain instead would be refused `not_found` the moment
/// nothing is running in it, which is exactly the state this warning fires in (nxf 6j6v.b9nf).
/// What the warning names to withdraw is that commission's OPERATION, by its first thread, and who
/// may do it ([`how_a_waiting_commission_is_taken_back`], nxf 6j6v.ezbr).
fn expired_but_still_writing(
    ctx: &Ctx,
    store: &ChatStore,
    scope: &WorkScope,
    waiting_thread: Option<&str>,
) -> Result<Option<String>> {
    let Some((holder_key, _)) = store.working_tree_lease_row()? else {
        return Ok(None);
    };
    // Its own lease, expired or not, is an inherit and never a block.
    if holder_key == scope.key() {
        return Ok(None);
    }
    // Unexpired: the ordinary refusal, decided by the compare-and-swap as it always was.
    if store.working_tree_holder(ctx.now)?.is_some() {
        return Ok(None);
    }
    let Some(held) = WorkScope::parse(&holder_key) else {
        return Ok(None);
    };
    let threads = store.work_scope_threads(&held)?;
    match sessions_still_running(ctx, store, &threads) {
        Ok(running) if running.is_empty() => Ok(None),
        Ok(_) => Ok(Some(holder_key)),
        // **A read that FAILED is not a chain that is finished** (review of PR #376, Integrity #1 /
        // Code Quality #2). This arm used to fall in with the `None` above, on a doc claim that it
        // was "fail-open in the same direction as the sweep" — and that claim was simply false: the
        // sister call sites ([`sweep_expired_working_tree`] and [`park_the_stranded_holder`])
        // propagate this very error with `?`; only this one swallowed it.
        //
        // Both halves were wrong. Answering "nobody is writing" because we could not find out hands
        // the checkout to a rival while the real holder may still have hands on the git index — the
        // one collision this epic exists to prevent, produced by a diagnostic rather than by a
        // decision. So an unreadable answer counts as STILL WRITING.
        //
        // It is not propagated either, and that is the half of the original reasoning that survives:
        // this runs in a TRIGGER path, where an `Err` fails the whole commission. Parking costs the
        // caller a wait it can see (the receipt says `queued_behind`), and the queue is drained by
        // the sweep, or by withdrawing the commission that is waiting for it (its OWN thread, not a
        // thread in the holding chain — naming one of those is refused `not_found` once it has
        // nothing running in it) — neither of which is reached by refusing to commission the work
        // at all.
        Err(e) => {
            let take_back = how_a_waiting_commission_is_taken_back(store, waiting_thread);
            eprintln!(
                "warning: could not read whether the chain holding this workspace's working copy \
                 (`{holder_key}`) is still running ({e}), so this commission is being parked rather \
                 than started — the safe answer while that is unknown. It starts when that chain \
                 releases, or {take_back}"
            );
            Ok(Some(holder_key))
        }
    }
}

/// Give the working tree back, and start whoever was waiting for it — the counter-movement to
/// [`acquire_or_queue`], and the point at which this epic's deterministic done signal earns its keep
/// (nxf 6j6v.fe0f).
///
/// Runs on the path that processes a REPLY, after the reply is persisted and after the routing that
/// reply drives, for `thread_id` = the thread it landed in. Four questions, in this order:
///
/// 1. **Is this reply part of the chain that holds the working tree?** The holder is a `scope_key`
///    ([`ChatStore::working_tree_holder`]); its threads are [`ChatStore::work_scope_threads`] — the
///    OPERATION's subtree since nxf 6j6v.8y6t (a subtree since 6j6v.1xw1), so an answer anywhere in it
///    counts, however deep. A reply in some other conversation discharges nothing OF THIS SCOPE and
///    so decides nothing about it — which is the ticket's own sentence, "the reply that discharges a
///    scope's last outstanding expectation releases", read literally. Without this gate a stranger's
///    reply would be enough to free a lease whose chain merely has not registered anything yet,
///    which is precisely the state a freshly started chain is in.
/// 2. **Does anything in that scope still owe a reply?** `ChatStore::threads_have_outstanding`,
///    which is `thread_quorums` — the SAME derivation `threads list`, the app-facade quorum bar and
///    `reply --if-unanswered` read. Anything outstanding: the lease STAYS. That is the whole gap
///    between "the coder finished" and "the review is commissioned", and it is why the holder is a
///    chain rather than a session.
/// 3. **Was the claim HANDED BACK rather than closed?** `ChatStore::threads_handed_back` (nxf
///    6j6v.1xw1). Nothing outstanding is not the same as finished — see below.
///
/// **Questions 1-3 are asked of an already-resolved thread list, not of the scope**, which is why
/// they name the `pub(crate)` predicates rather than the `pub`
/// [`ChatStore::work_scope_has_outstanding`] / [`ChatStore::work_scope_handed_back`] the reader might
/// expect. The two shapes cannot disagree — the `pub` ones are thin wrappers that resolve the list
/// and delegate — but naming the wrapper HERE is what made a mutation of it pass while this path was
/// untouched, so this doc names what the body calls.
/// 4. **Is anybody waiting?** Release and take the queue's next CLAIM AREA as ONE step
///    ([`ChatStore::release_working_tree_and_take_next`]), then fire every entry in it.
///
/// **Order, and it is load-bearing**: release FIRST, then take, then fire. A head taken before the
/// lease is given up is fired against a lease that is still standing, and is queued straight back
/// behind the chain that was in the act of releasing it.
///
/// **The whole claim area, not one entry** (PR #336 review, Code Quality #1 — CRITICAL). Several
/// queued entries share one `scope_key` whenever a multi-member `working_tree: exclusive` board had
/// to wait at open time: every member of that fan-out resolves to the board's own thread. Firing one
/// and leaving the siblings parked deadlocks the board permanently — it owes their replies, so its
/// scope never reports "nothing outstanding" and question (2) above never lets it release again.
/// They are fired together here for the reason they run together when the lease is free: the first
/// acquires and the rest inherit. See [`ChatStore::release_working_tree_and_take_next`].
///
/// **A scope with NOTHING outstanding is released, deliberately** — including the one shape that
/// makes this a decision rather than a definition (PR review of nxf 6j6v.303b, item (b)):
/// [`role_resume`] takes a thread-scoped lease while registering no obligation at all, and the
/// thread it pushes into may already have had its quorum discharged. Such a lease has no
/// deterministic done signal, so the two available answers are "free it at the next reply into its
/// own thread" and "hold it for two hours". This takes the first, for the reason the epic already
/// gives when it refuses to take a SESSION-scoped lease at all: a lease nobody can release is worse
/// than no lease, and holding this device's working copy hostage to a backstop is the failure that
/// is loud and useless rather than the one that is quiet and useful. What it costs is named rather
/// than hidden: a reply landing in that thread while the resumed session is still working frees the
/// tree under it. The gate in (1) is what keeps that narrow — only a reply in the chain's OWN
/// conversation can do it, never any reply anywhere.
///
/// **Nothing here may fail the reply.** The reply is persisted and durable by the time this runs, so
/// every failure — the store read, the release, the promoted trigger's own spawn — is a breadcrumb
/// and an `Ok`, exactly as [`trigger_and_bind`] and every wake site in this module already treat
/// theirs. The general place for a failed consequence to become VISIBLE to a caller is nxf
/// 6j6v.hq71; this is deliberately the narrow slice.
///
/// **"Nothing is outstanding" is not the same as "the claim thread is CLOSED", and both are asked**
/// (nxf 6j6v.1xw1, question (3) below). An escalating reply — and an open question — discharges the
/// sender's turn exactly like a finished one, because 6j6v.cg8g deliberately gives the kind no
/// special case in the discharge predicate. So question (2) is already satisfied while the task is
/// mid-flight and the answer is travelling upward, possibly as far as the human, and only (3) stops
/// the release there. [`ChatStore::work_scope_handed_back`] carries that rule and which threads it
/// asks. Both directions matter and only one is safe to get wrong: holding the copy too long is loud
/// and visible, while handing it to a rival mid-chain is the silent collision the epic exists to
/// prevent.
///
/// That clause REPLACES the one this doc used to name here — `work_scope_has_outstanding` answering
/// `true` for a run that was still `Running`, which was 6j6v.fe0f's bridge over 6j6v.rp8k. It is
/// gone rather than moved (6j6v.1xw1 acceptance point 6); see that function's own doc for the
/// argument it made and why it no longer holds.
///
/// **This is no longer the only thing that drains the queue**, which two earlier versions of this
/// doc got wrong in opposite directions (nxf 6j6v.yd4w). It WAS: the bound let the next chain to ASK
/// reclaim an abandoned lease, but nothing handed the queue's turn out except a release running
/// right here, so a trigger already parked waited past the bound until one happened. Three
/// movements do it now — this one, [`sweep_expired_working_tree`] on a tick (6j6v.fabb), and
/// [`the_queue_goes_before_a_newcomer`] on somebody else's acquire (6j6v.yd4w) — and all three go
/// through [`release_and_fire`], differing only in when they may release.
///
/// # What holds when two of these run AT ONCE, and what does not (nxf 6j6v.jzaj)
///
/// Everything above is one process's reasoning, and `nxc reply` is a process: two of them can be
/// inside this function for the same claim area at the same time, each seeing whatever the other
/// has committed so far. That was raised as a finding-to-note rather than a demonstrated bug (the
/// independent review of PR #339, finding 2), and it is recorded here rather than left on the
/// board, because the answer is a property of this path rather than of that review.
///
/// **What is guaranteed, for any interleaving.** The queue's next claim area is started EXACTLY
/// ONCE. Both callers can pass questions (1)-(3) — nothing outstanding, nothing handed back — and
/// both can call the release; only one of them can perform it, because
/// [`ChatStore::release_working_tree_and_take_next`] deletes the lease row under the holder's own
/// key and takes the queue INSIDE that same transaction. The loser's delete matches nothing, so it
/// takes nothing: the promoted area cannot be started twice, and cannot be dropped between the two
/// either. `working_tree::tests::only_one_of_four_genuinely_concurrent_releases_of_one_scope_hands_
/// the_queue_over` drives that with four connections on one barrier, and
/// `working_tree_two_process_e2e.rs`'s
/// `two_concurrent_replies_completing_one_claim_area_promote_the_queue_exactly_once` drives the
/// same claim through two real `nxc reply` processes.
///
/// **What is NOT, and it is not new.** Questions (1)-(3) are read outside the transaction that acts
/// on them, so between this call deciding "nothing is outstanding" and the release committing,
/// another process can commission fresh work INSIDE the same area — which inherits the lease (same
/// key, so the compare-and-swap itself says yes) and starts. The release then hands the copy to the
/// next area while that step is running. This is the same exposure [`inherits_the_held_claim`]
/// already names from the acquire end in full — "'owed now' is not 'owed throughout'" — and it is
/// bounded by the same fact: only a reply inside the chain's OWN area can reach this function at
/// all. Closing it would take the obligation read and the release into one transaction, which is
/// the shape 6j6v.jzaj's own note points at and is not what that item was raised for.
fn release_working_tree_if_scope_is_done(
    ctx: &Ctx,
    store: &mut ChatStore,
    thread_id: &str,
) -> Result<()> {
    let Some(holder) = store.working_tree_holder(ctx.now)? else {
        return Ok(());
    };
    // An unparseable key is left alone rather than guessed at — see [`WorkScope::parse`].
    let Some(scope) = WorkScope::parse(&holder) else {
        return Ok(());
    };
    // ONE resolution of the claim area, for all three questions below (branch review of nxf
    // 6j6v.1xw1, Minor 8). Since that item the area is a SUBTREE, so resolving it costs a read of
    // the thread forest — cheap, but not free, and asking the same question three times on the reply
    // path is the kind of cost that only ever grows.
    //
    // **This is the only production caller of `work_scope_handed_back`**, and since nxf 6j6v.43kw the
    // SECOND of `work_scope_has_outstanding` — `inherits_the_held_claim` asks it from the acquire
    // end, which is deliberate symmetry: the same predicate decides whether a chain may let the
    // working copy go and whether nested work may lean on the fact that it may not. Both stay `pub`
    // as the scope-shaped API an embedder and this crate's tests ask the question through, and they
    // are thin wrappers over exactly these two — so the shapes cannot drift. Worth knowing before
    // trusting a change to one of them: mutating the wrapper does not touch THIS path, and a
    // mutation of it passed for exactly that reason during 6j6v.1xw1's fix round.
    let threads = store.work_scope_threads(&scope)?;
    if !threads.iter().any(|t| t == thread_id) {
        return Ok(());
    }
    if store.threads_have_outstanding(&threads, ctx.now)? {
        return Ok(());
    }
    // **A WITHDRAWN holder does not let go here** (nxf 6j6v.b9nf, requirement 8 of that item's
    // brief). The discharge `withdraw` performs leaves this claim area owing nothing — which is
    // exactly the state question (2) above and question (3) below release on — while the withdrawn
    // round's uncommitted work is still in the tree, waiting for the tick to park it once the
    // stopped process is gone. Any reply that lands in the area in that window — the stopped
    // session's own last word, a human's note — would otherwise hand the copy to the next holder
    // with that work in it. The marker is the one fact that distinguishes "over and clean" from
    // "over and not yet parked", and the tick's withdrawn occasion ([`park_a_withdrawn_holder`]) is
    // the one way such a holder lets go.
    //
    // **Read AFTER the debt and BEFORE the hand-back** (fix round 2 of this item's review, Minor
    // #3), which is the one position that is both cheap and complete. An area that still owes
    // declines on the line above and never pays for this read, which is the common case on every
    // reply; and once nothing is owed, this is the very next question, so nothing can reach the
    // release without passing it. Before question (3) rather than after, so a withdrawn holder
    // declines AS WITHDRAWN: (3)'s decline also derives and records contention, and what is waiting
    // for this holder is not a hand-back it might be raced to but the park, which is the only thing
    // that moves this copy. One indexed read on a table with at most one row per claim.
    if store.withdrawn_holder(&holder)?.is_some() {
        return Ok(());
    }
    // (3) …and was the claim HANDED BACK rather than closed? (nxf 6j6v.1xw1). Nothing being
    // outstanding is not the same as the claim thread being closed: an escalating reply — and an
    // open question — discharges the sender's turn exactly like a finished one, so question (2)
    // above is already satisfied while the task is mid-flight and the answer is travelling upward,
    // possibly as far as the human. `ChatStore::work_scope_handed_back` carries the rule and why it
    // asks the whole area rather than one level of it.
    if store.threads_handed_back(&threads)? {
        // **The other event that can begin CONTENTION** (nxf 6j6v.de9s). The queue may already have
        // been waiting when this hand-back arrived — the escalation is then the second half, not the
        // first — so the derivation runs here for the same reason it runs on the acquire path: this
        // is a point at which the answer can have changed, and the clock is measured from the first
        // instant both halves stood, not from whichever one happened to be noticed.
        //
        // Best-effort: the release has already been declined on the line above, and a memo that
        // could not be written costs the automatic park, never the claim. The next tick re-derives
        // it from scratch.
        if let Err(e) = note_the_contention(ctx, store) {
            eprintln!("warning: could not tell whether the working copy is contended: {e}");
        }
        return Ok(());
    }
    // The whole claim area at the head, not one entry — see
    // [`ChatStore::release_working_tree_and_take_next`]. Every promoted entry is fired, and a
    // failure on one is a breadcrumb that does NOT abandon the ones queued beside it: they share a
    // scope, so they were always going to run together, and stopping at the first failure would
    // strand the rest exactly as popping a single entry used to.
    release_and_fire(ctx, store, HandOff::Released(&scope), &holder)?;
    Ok(())
}

/// One trigger that had been parked behind the working-tree lease and has now been started
/// (nxf 6j6v.fabb). Declared field order = the JSON contract; the same shape
/// [`WithdrawnCommission`] reports for the opposite movement.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct PromotedTrigger {
    /// The thread the commission runs in.
    pub thread: String,
    /// The role that was started.
    pub role: String,
    /// The internal session it runs under.
    pub session: String,
}

/// What a release actually promoted: the entries that started, the ones that went back in line, and
/// the ones nothing will come back for.
///
/// **All three, deliberately.** Every release site in this module treats a failed START as a
/// breadcrumb rather than an error — the release itself has already committed, and refusing it
/// afterwards would leave the working copy held by nobody with the queue still parked behind it.
/// A breadcrumb on stderr is enough on the reply path, where the release is a side effect of
/// somebody else's turn. It is NOT enough for [`withdraw`], which a human or an agent runs on
/// purpose and reads the answer to, nor for a sweep that runs unattended with no terminal at all —
/// which is [`FailedConsequence`]'s whole argument, applied to this one movement.
///
/// **[`Self::requeued`] is the third answer, and it was missing** (independent review of PR #380,
/// Integrity & Robustness #1). It used to be folded into `started`, because
/// [`fire_queued_trigger`] threw [`TriggerAdmission`] away and every `Ok` counted as a spawn — the
/// exact silent-failure class that enum's own doc says it was given a return value to prevent, in
/// the one place that had stopped reading it.
#[derive(Debug, Clone, Default, PartialEq, Eq, serde::Serialize)]
pub struct Promotions {
    /// Started, in the queue's own order. A session is running for each of these.
    pub started: Vec<PromotedTrigger>,
    /// Taken off the queue and put straight back on it: by the time this entry was fired the
    /// working copy was no longer its claim area's, so it competed and lost, exactly as it did the
    /// first time. **Nothing is running for it and nothing has to be done about it** — it is in
    /// line, with the place it had already waited for ([`RoleSpawn::queued_since`]), and the next
    /// release starts it. Reported rather than silently counted as a start, because "a receipt that
    /// claims a session is working while the trigger is sitting in a queue" is what
    /// [`TriggerAdmission`] exists to make impossible.
    pub requeued: Vec<PromotedTrigger>,
    /// Taken off the queue and NOT started: the lease is gone, the entry is gone, and nothing is
    /// running for it. Its message is persisted and its session is minted, so this names what a
    /// reader has to go and look at.
    pub failed: Vec<PromotedTrigger>,
    /// **What starting those entries NOTICED** (nxf 6j6v.pkw9; review of PR #425, Integrity &
    /// Robustness #1) — the same always-present, never-omitted `warnings` list every other receipt
    /// in this module carries, empty when there was nothing to say.
    ///
    /// **It exists because of WHERE this type is read.** A release receipt has a person in front of
    /// it, and a stderr breadcrumb would nearly do. But this same [`Promotions`] rides
    /// [`WorkingTreeSweep`] onto [`TickReceipt::working_tree`], and `tick` is what the background
    /// service runs UNATTENDED, with no terminal anywhere — the verb this module's own docs call
    /// the one with the most to lose from silence. A finding that only ever reached stderr there
    /// reproduced the very shape nxf 6j6v.pkw9 exists to end: a session running under changed rules
    /// and no signal any watching process could see.
    ///
    /// The first cut of that item shipped exactly that breadcrumb and called this path "the one
    /// spawn path with no receipt to put it on". The receipt was here; what was missing was a field
    /// on it.
    pub warnings: Vec<FailedConsequence>,
}

impl Promotions {
    /// **Nothing left the queue** — no entry started, none went back in line, none failed on the way.
    ///
    /// For a hand-off that reached its reclaim, this is exactly the compare-and-swap having LOST:
    /// the queue was not empty (every caller that asks has just peeked a head), so a reclaim that
    /// matched the lease row would have taken at least that entry off it. The holder renewed
    /// between the read and the write, keeps the copy — and whoever was waiting is still waiting,
    /// which is what [`sweep_expired_working_tree`] then has to arm a look for.
    ///
    /// [`warnings`](Self::warnings) is deliberately not consulted: it says what starting an entry
    /// NOTICED, so it is only ever non-empty beside an entry that did start.
    ///
    /// `pub(crate)` for `cli::sweep_headline`, which asks the same question of the same value
    /// (independent review of PR #478, Code Quality #2). It used to re-derive this by De Morgan
    /// because it could not reach the method — correct then, and nothing would have kept the two
    /// forms in step the day [`Promotions`] gains a field.
    pub(crate) fn nothing_moved(&self) -> bool {
        self.started.is_empty() && self.requeued.is_empty() && self.failed.is_empty()
    }
}

/// **How the working copy is being taken from its current holder** — the FIRST move of a hand-off,
/// and the only thing the movements that hand it on disagree about (nxf 6j6v.yd4w).
///
/// Every arm ends in the same transaction, [`ChatStore::hand_the_working_tree_on`]'s: the outgoing
/// row goes, the queue's head area comes off the queue, and the lease is written for that area.
/// What differs is which row this caller is entitled to delete, and that question is settled inside
/// the transaction rather than by the caller having looked a moment ago.
enum HandOff<'a> {
    /// `scope` holds the lease and is giving it back — the reply path's own release, and every
    /// parking occasion [`park_and_hand_on`] hands on once its work is saved (a stranded
    /// escalation, an availability boundary, a withdrawn holder).
    Released(&'a WorkScope),
    /// The lease has RUN OUT and the chain behind it has no live process, so the queue takes it
    /// away. `expires` is the value read off the row and is the guard: a holder that renewed in
    /// between keeps the working copy, because the delete names the instant it was reclaimed FOR.
    Expired {
        holder_key: &'a str,
        expires: &'a str,
    },
    /// The lease still STANDS and the chain behind it does not — nxf 6j6v.xb24. The queue takes the
    /// copy on evidence rather than on a clock ([`holder_is_provably_dead`]), which is the whole
    /// difference from [`Expired`](Self::Expired) above; `expires` is the same guard doing the same
    /// job, and here it guards more than an ordering. A holder that renewed between the read and the
    /// write is a holder with a live process, which is precisely the evidence this arm rests on —
    /// so the compare-and-swap that fails is also the claim that was wrong, and the copy stays.
    DeadHolder {
        holder_key: &'a str,
        expires: &'a str,
    },
}

/// Give the working copy up and start everything the queue hands over, reporting both halves.
/// `held_by` names the outgoing holder in the breadcrumb — it is only ever prose.
///
/// The ONE place a release fires promoted triggers, shared by two paths: the reply path's own
/// [`release_working_tree_if_scope_is_done`], and [`park_and_hand_on`] — which every parking
/// occasion reaches (a stranded escalation, an availability boundary, the sweep past its bound or
/// over a holder proven dead inside it, a withdrawn holder) and which, since nxf 6j6v.yd4w, the
/// acquire path's own fairness gate, [`the_queue_goes_before_a_newcomer`], reaches the same way.
/// They differ in WHEN they may release and in nothing else, and this is what keeps that true.
///
/// **The lease is already the promoted area's by the time anything is fired** (nxf 6j6v.yd4w): the
/// transaction grants it, so the entries below are fired against a lease they already hold rather
/// than racing a newcomer for one that is briefly free. Firing therefore normally INHERITS — the
/// same key through [`ChatStore::acquire_working_tree`] — which is also what replaces the backstop
/// bound the grant wrote with the area's own derived one.
///
/// **"Normally", and the exception is REPORTED rather than assumed away** (independent review of
/// PR #380, Integrity & Robustness #1). No rival can take an unexpired lease by asking, but one
/// thing can still move it between the commit above and a fire below — a thread re-parented since
/// the entry was parked, so [`lease_claim_root`] re-derives a different key. [`fire_queued_trigger`]
/// spells it out, and its own doc says what closed the other one: a concurrent
/// `nxc release --thread <t>` naming the granted area used to slip through the same liveness
/// guard, before anything had started in it. The verb is gone (nxf 6j6v.b9nf), and `nxc withdraw`
/// cannot reopen the window — by the time the grant has happened the entry is off the queue, so a
/// withdraw that finds nothing running there finds nothing to take back either. The entry then
/// loses its acquire and goes back in line, which costs nothing and is safe — but it is NOT a
/// start, so it lands in [`Promotions::requeued`] and never in `started`.
/// An earlier version of this doc stated the inherit unconditionally while the code counted every
/// `Ok` as a spawn, which is how a receipt came to claim a session was working for an entry sitting
/// in a queue.
///
/// **The loop is the price of the grant, and it is what keeps a failed start from wedging the
/// device.** If nothing in the promoted area starts AND nothing went back in line — that is, the
/// area still holds the copy and has no process behind it — this hands it straight on to the next
/// area in the queue instead of leaving it standing until the backstop elapses. (A re-queued entry
/// ends the loop instead: the copy is demonstrably not this area's any more, so there is nothing
/// here to hand on.) Each round takes one claim area off the queue, so it terminates on the queue's
/// own length, and the ordinary case does not reach the second round at all.
///
/// **What that costs under a SYSTEMIC failure, named rather than left to be found** (same review,
/// Integrity & Robustness #3). The loop is bounded by the queue, not by a constant: if every queued
/// role has been removed from the catalogue, or the worker refuses everything, one release walks the
/// whole queue — one `BEGIN IMMEDIATE` transaction per claim area, synchronously, inside whatever
/// request called it. That is the intended behaviour rather than an oversight (the alternative is a
/// device wedged until the backstop, which is what this loop exists to prevent), and the shape is
/// self-limiting in practice: a queue is at most as long as the commissions this device has parked,
/// each round is one short write transaction with no I/O, and every failure prints a breadcrumb, so
/// the pathological case is loud rather than silent. No bound is imposed, because a bound would
/// stop the walk in exactly the state — copy held, nobody running — the walk is for.
fn release_and_fire(
    ctx: &Ctx,
    store: &mut ChatStore,
    from: HandOff<'_>,
    held_by: &str,
) -> Result<Promotions> {
    // Whose hand the copy is leaving, for the breadcrumb below. It MOVES with the loop: on the
    // second round it is the area this function itself granted to and could not start, and saying
    // the original holder there would name a release that is two steps old.
    let mut held_by = held_by.to_string();
    let mut out = Promotions::default();
    // The bound the grant writes for an area whose own window nothing has derived yet — see
    // `working_tree::hand_the_working_tree_on` for why it is a backstop rather than the real one.
    let granted_until =
        facade::resolve_instant(ctx.now, WORKING_TREE_LEASE_BOUND, "the working-tree lease")?;
    let mut next = match from {
        HandOff::Released(scope) => {
            store.release_working_tree_and_take_next(scope, ctx.now, &granted_until)?
        }
        HandOff::Expired {
            holder_key,
            expires,
        } => store.reclaim_expired_working_tree_and_take_next(
            holder_key,
            expires,
            ctx.now,
            &granted_until,
        )?,
        HandOff::DeadHolder {
            holder_key,
            expires,
        } => store.reclaim_a_dead_holders_working_tree_and_take_next(
            holder_key,
            expires,
            ctx.now,
            &granted_until,
        )?,
    };
    loop {
        let Some(granted_key) = next.first().map(|e| e.scope_key.clone()) else {
            return Ok(out);
        };
        let (started_before, requeued_before) = (out.started.len(), out.requeued.len());
        for entry in &next {
            let promoted = PromotedTrigger {
                thread: entry.thread.clone().unwrap_or_default(),
                role: entry.role.clone(),
                session: entry.session.clone(),
            };
            match fire_queued_trigger(ctx, store, entry) {
                // EXHAUSTIVE, with no `_` arm: a third admission is a compile error right here, so
                // whoever adds one has to decide what it means for a receipt — the same
                // construction `working_tree::hands_the_task_back` uses, and for the same reason. A
                // wildcard would sort the next answer into "started", which is the bug this arm
                // pair was written to fix.
                Ok(TriggerAdmission::Spawned {
                    declaration_changed,
                }) => {
                    // **On the receipt AND on stderr** (nxf 6j6v.pkw9; review of PR #425, Integrity
                    // & Robustness #1). A promoted entry is started by whoever RELEASED the working
                    // copy rather than by the caller that commissioned it — so this loop is the
                    // only place that can report what starting it noticed.
                    //
                    // The first cut breadcrumbed it and nothing else, on the argument that
                    // `Promotions` had no field for it. That argument was wrong about which reader
                    // matters: this very loop runs inside `sweep_expired_working_tree`, at the top
                    // of `tick`, which the background service runs with no terminal at all. A
                    // stderr-only finding there is invisible by construction — the shape this whole
                    // item exists to end. `Promotions::warnings` is the field; see its doc.
                    //
                    // The breadcrumb stays beside it for the reader who DOES have a terminal — a
                    // reply, a fresh commission that goes before a queued rival, or a resume that
                    // secures an interrupted tree can all reach this loop synchronously — which is
                    // the same both-halves rule every other finding in this module follows.
                    if let Some(finding) = declaration_changed {
                        eprintln!("warning: {finding}");
                        out.warnings.push(finding);
                    }
                    out.started.push(promoted);
                }
                Ok(TriggerAdmission::Queued { .. }) => out.requeued.push(promoted),
                Err(e) => {
                    eprintln!(
                        "warning: the working tree was released by {held_by}, but the trigger \
                         waiting for it (role {}, session {}) could not be started: {e}; its \
                         message is persisted and its session is minted, but nothing is running \
                         for it",
                        entry.role, entry.session
                    );
                    out.failed.push(promoted);
                }
            }
        }
        if out.started.len() > started_before || out.requeued.len() > requeued_before {
            return Ok(out);
        }
        // Nothing runs for the area the hand-off just gave the working copy to. Hand it on rather
        // than let it sit: an area with no process behind it is exactly the state the backstop
        // exists for, and reaching the backstop here would cost every chain still in the queue the
        // whole of it.
        let Some(granted) = WorkScope::parse(&granted_key) else {
            eprintln!(
                "warning: the working copy was handed to `{granted_key}`, nothing there could be \
                 started, and that key cannot be read back — so there is no thread to withdraw by \
                 name either; it is held until the sweep takes it at its bound"
            );
            return Ok(out);
        };
        held_by = granted_key;
        next = store.release_working_tree_and_take_next(&granted, ctx.now, &granted_until)?;
    }
}

// `ReleaseReceipt` and `pub fn release_working_tree` were here — the manual "give the working copy
// back when nothing is going to give it back on its own" (nxf 6j6v.fabb). REMOVED by nxf 6j6v.b9nf
// (owner decision, 2026-09-17: `release` leaves the user surface). Its safety reason: offered to an
// agent, it could take the working copy away from a running coding operation, and a
// `WorkerConfig::Custom` worker that never implemented `Worker::session_is_running` made it an
// unconditional release. The two rules that used to be its refusals — a thread must be inside the
// holding chain, and every session in it must be dead — are not lost: every hand-off now parks
// first (PR #478) and reaches the SAME [`sessions_still_running`] guard from inside
// [`park_and_hand_on`], and the ONE remaining reader of `ChatStore::withdrawn_holder` this function
// carried (a WITHDRAWN holder's copy is the tick's to park, not a caller's to hand on unparked) went
// with it rather than surviving as a dead check with no caller. What replaces the verb: a held copy
// of a dead chain is parked by the sweep on its own, past the bound or inside it where liveness is
// answered ([`sweep_expired_working_tree`], [`holder_is_provably_dead`]); a held copy of a live
// chain a caller wants back is [`withdraw`], which discharges it and stops its session. See
// `tests/seam_disposition.rs`'s row for the decision and removal dates.

/// **What became of one session** (nxf 6j6v.h383) — the value the READ side of the session seam
/// hands back.
///
/// Three answers, and the third is not a hedge. `Ended` is the session's OWN word
/// (`session_map.ended`, written by `nxc session ended`); `Running` is a live process behind it;
/// `Unknown` is neither — nothing announced an end and nothing answers for a process, which is a
/// session killed hard, a session this device never ran, or a worker that cannot tell. Collapsing
/// `Unknown` into `Ended` would state a fact nobody established, and collapsing it into `Running`
/// would report a corpse as working.
///
/// **`Unknown` is what the ADVANCE gate treats as "not writing"** and so is `Ended` — see
/// [`a_member_session_is_still_writing`], which asks for `Running` and nothing else. That the
/// reader distinguishes what the gate merges is the point of having a reader: a human deciding
/// whether to intervene needs to know which of the two it is looking at, and the gate does not.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "snake_case")]
pub enum SessionState {
    /// A live process stands behind this session — [`Worker::session_is_running`](crate::worker::
    /// Worker::session_is_running) says so.
    Running,
    /// The session announced its own end, at [`SessionStanding::ended`].
    Ended,
    /// No announcement, and no live process to be found. What that means depends on the worker
    /// asking: a hard-killed session, one another device ran, or a runtime whose worker does not
    /// answer the liveness question at all — and
    /// [`SessionStateReport::worker_answers_liveness`] says which of those two kinds of `Unknown`
    /// this is (nxf 6j6v.t41e).
    Unknown,
}

/// One session, as the seam reports it (nxf 6j6v.h383) — [`ChatStore::session_row`]'s record with
/// the PROCESS question answered on top of it.
///
/// `#[non_exhaustive]` since nxf 6j6v.npy3, which is the item that added the SECOND field here and
/// so the one that learned this record grows: a host reads these fields, and a literal it can no
/// longer write costs it nothing, while a source break at every future fact about a session costs
/// it a release. Its two neighbours on the status read ([`crate::facade::StatusThread`],
/// [`crate::facade::StatusOperation`]) carry the marker for the same reason and were already
/// carrying it.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
#[non_exhaustive]
pub struct SessionStanding {
    /// The internal, nxc-minted session id — what `send --to` hands back as `session` and what
    /// `refs.session_id` carries.
    pub session: String,
    /// The declared role this session was minted for.
    pub role: String,
    /// Running, over, or neither.
    pub state: SessionState,
    /// Where this session is: the thread it was last put in motion on.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub thread: Option<String>,
    /// The runtime's own session id, once the runtime has bound one. `None` while the session is
    /// still pending — it is minted before the SDK hands an id back.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub runtime_session: Option<String>,
    /// When the row was minted.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub started: Option<String>,
    /// When the session announced its end — present exactly when `state` is
    /// [`SessionState::Ended`].
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ended: Option<String>,
    /// **This session stopped because the model went away, and is coming back** (nxf 6j6v.npy3) —
    /// the hold standing over it, or `None`, which is the ordinary case.
    ///
    /// A fact BESIDE [`state`](Self::state) and never a value of it: an interrupted session has
    /// genuinely ended, so `state` reads [`SessionState::Ended`] and every host matching on that
    /// enum keeps working. See [`crate::interruption`] for why this is a row rather than a column,
    /// and [`crate::facade::StatusThread::interrupted`] for the same fact on the board-wide read —
    /// deliberately the SAME shape, spelled the same way, because two reads that answer one question
    /// must not qualify it differently.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub interrupted: Option<crate::interruption::Interruption>,
}

/// Which sessions [`session_state`] is being asked about.
///
/// The two questions the proving ground actually asked, one shape each ([`crate::engine::Engine::
/// session_state`] carries the measurement). A scope enum rather than two verbs, for
/// [`StatusScope`](crate::facade::StatusScope)'s reason: one read, one record, one place where what
/// it means to ask is decided.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SessionScope<'a> {
    /// One named session. **"Is the session I am holding still alive, or is it dead?"**
    Session(&'a str),
    /// Every session recorded under one thread, ended ones included. **"Is the previous session
    /// really over before I touch this?"**
    Thread(&'a str),
}

/// What [`session_state`] gave back.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct SessionStateReport {
    /// In `internal_id` order, which is a ULID order and therefore chronological. Exactly one entry
    /// for [`SessionScope::Session`]; any number, including none, for
    /// [`SessionScope::Thread`].
    pub sessions: Vec<SessionStanding>,
    /// **Whether the worker that answered was able to answer at all** —
    /// [`Worker::answers_liveness`](crate::worker::Worker::answers_liveness), carried on the report
    /// because [`SessionState::Unknown`] is where its absence is felt (nxf 6j6v.t41e).
    ///
    /// `Unknown` has always meant two opposite things at once, and its own doc says so: a session
    /// killed before it could announce anything, or a runtime nobody can ask. `false` here says the
    /// report is looking at the second — no process question was ever put, so every unended session
    /// reads `unknown` and none of them is evidence about a session.
    ///
    /// It is a property of the HANDLE's worker rather than of any row, which is why it sits here and
    /// not on [`SessionStanding`]; [`crate::engine::Engine::worker_answers_liveness`] is the same
    /// fact for a caller that has no session to ask about yet.
    pub worker_answers_liveness: bool,
}

/// **The READER the session seam never had** (nxf 6j6v.h383).
///
/// `nxc session bind` writes which runtime session a trigger became; `nxc session ended` writes
/// that its process is over. Both are written by the sidecar, and the second carries the fact a
/// declared channel's advance has rested on since nxf 6j6v.10yb — *a step ends when its session
/// ends*. Nothing could ask for either of them back.
///
/// What that cost, measured over six hours of continuous operation in a foreign project: the PM of
/// that run reached past the tool chain into `nxc`'s own directory and ran
/// `ps -p $(cat .nxs/agent-logs/<id>.pid)` — a file whose format is promised nowhere — because it
/// was the only way to tell a thread that was thinking from a thread that had died. Its own report:
/// *"the pid check saved me from reading the interim state as a failure yet again"*.
///
/// **Both sources, in the order [`a_member_session_is_still_writing`] sets**, so the reader and the
/// gate cannot disagree about one session: the announcement first, process liveness as the backstop
/// for a session killed before it could speak. The DIFFERENCE is what the reader does with the
/// residue — the gate folds "ended" and "nobody knows" into one *not writing*, and this keeps them
/// apart, because a human deciding whether to intervene is deciding exactly between those two.
///
/// It takes a [`Worker`](crate::worker::Worker) and not a whole [`Ctx`] because that is the whole
/// of what it needs: no clock, no identity, and nothing written. That is what lets
/// [`crate::engine::Engine::session_state`] be a plain read on the handle rather than a verb with a
/// caller.
pub fn session_state(
    store: &ChatStore,
    worker: &dyn Worker,
    scope: SessionScope<'_>,
) -> Result<SessionStateReport> {
    let rows = match scope {
        SessionScope::Session(internal) => vec![store
            .session_row(internal)?
            .ok_or_else(|| NxfError::not_found(format!("no such internal session: {internal}")))?],
        SessionScope::Thread(thread) => store.sessions_in_thread(thread)?,
    };
    let mut sessions = Vec::with_capacity(rows.len());
    for row in rows {
        sessions.push(SessionStanding {
            state: match &row.ended {
                Some(_) => SessionState::Ended,
                None if worker.session_is_running(&row.internal_id) => SessionState::Running,
                None => SessionState::Unknown,
            },
            // One read per session, unlike the board-wide `nxc status` path, which takes the same
            // fact in bulk: this scope is ONE session, and `Thread` is the sessions of one thread —
            // a handful, not a workspace. The bulk read exists for the report that carries 411
            // threads, and using it here would be a set-bind to answer about two rows.
            interrupted: store.current_interruption(&row.internal_id)?,
            session: row.internal_id,
            role: row.role,
            thread: row.thread,
            runtime_session: row.real_sdk_id,
            started: row.created,
            ended: row.ended,
        });
    }
    Ok(SessionStateReport {
        worker_answers_liveness: worker.answers_liveness(),
        sessions,
    })
}

/// Which sessions of `threads` still have a live process — the one question that separates "this
/// chain is over" from "this chain is working", asked in one place by the two callers that decide
/// on it (nxf 6j6v.fabb).
///
/// **Both sources, in the order [`a_member_session_is_still_writing`] sets.** A session that ENDED
/// said so, and [`ChatStore::unended_sessions_in_thread`] already excludes it; process liveness is
/// the backstop for one killed hard enough that it never announced anything.
///
/// **What a `false` from the worker is worth, and where it is not worth enough.**
/// [`Worker::session_is_running`](crate::worker::Worker::session_is_running) has a DEFAULT of
/// `false` — deliberately, so the trait could grow the method — and `LazyWorker` answers `false`
/// when worker SELECTION fails. For the channel-advance gate that default is the safe direction
/// (a `false` stalls nothing). Here it is the destructive one: an empty answer lets a hand-off
/// proceed, and the working copy moves while the holder may still have hands on the git index. So
/// the CLI resolves EVERY worker it builds from the WORKSPACE ROOT rather than from the process
/// cwd (`cli.rs`'s `CliCtx::resolve`, nxf 6j6v.npn0 — a decision that first bought this narrowly,
/// for the one verb this guard used to gate alone, and is general now that every hand-off in this
/// module shares it), and an embedder whose worker does not implement the method gets no guard at
/// all — which [`Engine::worker_answers_liveness`](crate::engine::Engine::worker_answers_liveness)
/// says out loud rather than implying.
///
/// **Which `false` it just got is now ASKABLE, and this function still does not ask** (nxf
/// 6j6v.t41e). [`Worker::answers_liveness`](crate::worker::Worker::answers_liveness) separates
/// "nothing is running" from "I never looked", and the three call sites below could each branch on
/// it. None of them does, deliberately: the fail-open direction of the default is reasoned and the
/// item that added the question asked for it to be preserved, not reversed. What changed is that
/// the decision is now a decision — visible here, and visible to a host through
/// [`Engine::worker_answers_liveness`](crate::engine::Engine::worker_answers_liveness), instead of
/// a silence that reads as a fact.
fn sessions_still_running(ctx: &Ctx, store: &ChatStore, threads: &[String]) -> Result<Vec<String>> {
    let mut running: Vec<String> = Vec::new();
    for thread in threads {
        for internal in store.unended_sessions_in_thread(thread)? {
            if ctx.worker.session_is_running(&internal) {
                running.push(internal);
            }
        }
    }
    Ok(running)
}

/// What a tick's sweep reclaimed — **and what it did with the holder's work first** (nxf
/// 6j6v.8bv9).
///
/// The park lives on this struct rather than on [`TickReceipt::parked`] or
/// [`TickReceipt::handed_on`] beside it, for the reason [`TickReceipt`] has one optional field per
/// MOVEMENT: the sweep is one movement, its `scope` and its `promotions` are already here, and a
/// reader that had to join two fields to learn what happened to one working copy is a reader that
/// will one day read only the first of them. [`TickReceipt::parked`] also carries a
/// `contended_since` this occasion has no value for.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct WorkingTreeSweep {
    /// The scope key whose lease had run out.
    pub scope: String,
    /// When it ran out.
    pub expired: String,
    /// **Where the holder's uncommitted work went** before the copy moved. `None` when nothing was
    /// parked, which since nxf 6j6v.8bv9 means exactly one thing: [`unparked`](Self::unparked) says
    /// why it could not be.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parked: Option<crate::park::Parked>,
    /// **Why it was NOT parked** — a PERMANENT refusal ([`ParkRefusal::is_permanent`]), so the copy
    /// went on with the holder's uncommitted work still in the tree. The
    /// [`ConsequenceClass::WorkHandedOnUnparked`] finding in [`TickReceipt::warnings`] says the same
    /// in words. A TRANSIENT refusal never reaches here: it keeps the claim, so there is no sweep to
    /// report.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub unparked: Option<ParkRefusal>,
    /// Who was waiting, and what happened to them.
    #[serde(flatten)]
    pub promotions: Promotions,
}

/// **Drain the queue once the lease's own bound has elapsed** (nxf 6j6v.fabb point 2, the gap
/// 6j6v.yd4w named).
///
/// [`WORKING_TREE_LEASE_BOUND`] was only ever half a backstop, and its own doc said so: expiry
/// stops an abandoned lease from refusing every FUTURE acquire, but nothing swept the lease table
/// and nothing polled the queue, so a trigger ALREADY parked waited past the bound indefinitely —
/// until some later chain happened to acquire and then release.
/// `working_tree_two_process_e2e.rs`'s
/// `a_hard_killed_holder_loses_the_lease_past_the_bound_but_the_queue_does_not_self_drain` pinned
/// exactly that, deliberately, "because a reader who assumes otherwise would file the real
/// behaviour as a bug". It IS the bug; what was missing was something to poll.
///
/// The clock 6j6v.74c0 built is that something, and this is what it runs. It sits at the front of
/// [`tick`] rather than in a verb of its own, on purpose:
///
/// - **`tick` is already "re-check what is due", and it is already idempotent and already hidden.**
///   A second scheduled verb would be a second thing to schedule, test and forget.
/// - **So the drain rides every tick there is.** A parked commission arms one for its holder's own
///   expiry ([`arm_the_lease_bound`]), but any channel `timeout:` tick that happens to fire
///   afterwards sweeps too.
///
/// # It asks the SAME liveness question every hand-off in this module refuses on
///
/// The review of this branch found this missing, and it was the right finding (Code Quality #1,
/// Integrity #2). Every hand-off this module makes refuses while any session in the chain still
/// has a live process ([`sessions_still_running`]), with the argument that yanking the tree out
/// from under a working chain "is the collision the lease exists to prevent" — and that argument
/// applies here WITH MORE FORCE, not less, because nobody is present.
///
/// [`WORKING_TREE_LEASE_BOUND`]'s own doc names the case: a single step that WORKS — not idles —
/// for more than two hours without commissioning anything loses the lease under itself. Before this
/// item that stayed theoretical for a parked rival, because nothing polled; [`arm_the_lease_bound`]
/// now guarantees somebody polls at exactly the bound, which would have turned an unlikely
/// collision into a scheduled one. So the sweep declines while anything is alive.
///
/// **Declining costs nothing that this ticket was about.** The state 6j6v.fabb measured is
/// precisely "no process anywhere"; a chain that IS alive will release on its own when it
/// finishes, through the ordinary reply path. What it does cost is named rather than hidden: a
/// holder that is alive at its bound and then dies HARD, without releasing, leaves the queue parked
/// until the next tick from anywhere — this same clause, re-asked, is what reclaims it, because by
/// then nothing is running. There is no longer a manual override for a chain that is simply gone
/// (nxf 6j6v.b9nf retired the one there used to be); the sweep is the whole answer now.
///
/// Three cheap conditions before that: there is a lease row at all; it is EXPIRED as of `now`
/// (which is exactly [`ChatStore::working_tree_holder`] answering `None` over a row that exists);
/// and somebody is actually waiting. A lease that has expired with an empty queue is left alone
/// rather than tidied — the next acquire reclaims it in one statement with no cleanup run, which is
/// the design, and deleting the row here would only move that work earlier.
///
/// **The reclaim itself is ONE transaction, and the check above is not part of it** (nxf 6j6v.yd4w).
/// Everything this function reads — the row, the queue head, the holder's liveness — is read before
/// it acts, and a holder can renew in between: every trigger a chain makes rides its bound forward.
/// So the act is [`ChatStore::reclaim_expired_working_tree_and_take_next`], whose delete names the
/// exact `expires` that was read. A lease renewed since then is not the row this decided about, the
/// delete matches nothing, and the sweep reports nothing rather than taking the working copy from a
/// chain that just proved it is alive.
///
/// **It is not the only reclaim any more, and the sibling runs where this one cannot.** A newcomer's
/// own trigger runs no tick, so [`the_queue_goes_before_a_newcomer`] asks the same question on the
/// acquire path — that is 6j6v.yd4w's fairness half, and it is why an expired lease is handed to
/// whoever is already in line rather than to whoever happens to ask.
///
/// **A decline RE-ARMS** (Code Quality #2). The tick a park scheduled is one-shot, so a holder that
/// renewed its lease — every trigger it makes rides the bound forward — would consume the alarm
/// early, and the parked commission would be back to "waits until some later chain releases", which
/// is the bug itself. So every decline schedules the next look, and since nxf 6j6v.xb24 that look is
/// at most one [`SESSION_LIVENESS_RECHECK_SECS`] away rather than at the bound
/// ([`drain_recheck_instant`]) — which is what makes the section below a rule that runs rather than
/// a rule that would first have to be reached.
///
/// **And so does a hand-off that moved NOTHING** (fix round 1 of nxf 6j6v.xb24): a park can go
/// through and the reclaim behind it still match no row, because the holder renewed in between. The
/// copy has not moved, the queue is still a queue, and this tick has spent the waiter's alarm just
/// as surely as a decline would — so both branches of this function arm through
/// [`arm_the_next_look`], which is the one site the rule now lives at.
///
/// # It does not wait for the bound when the holder is already GONE (nxf 6j6v.xb24)
///
/// The bound is a backstop for a holder nobody can ask about, and a chain that died hard is one this
/// device CAN ask about. So before it declines on a lease that is still standing, this asks
/// [`holder_is_provably_dead`] — five conditions, all of which must hold — and hands the copy on
/// under [`ParkOccasion::DiedInsideItsBound`] when they do. That occasion is
/// [`a_dead_holder_inside_its_bound`]'s; it reports through [`TickReceipt::handed_on`] rather than
/// through [`WorkingTreeSweep`], because it took a lease that had not expired and there is no
/// `expired` instant to put on one. [`SweepStep`] carries both and says why they cannot collide.
///
/// # It PARKS the holder's work first (nxf 6j6v.8bv9)
///
/// The occasion this function acts on is the one a crash can reach: a chain that died hard never
/// escalated and never announced an availability boundary, so neither park step ahead of it is even
/// asked — and until this item the copy was reclaimed with that chain's uncommitted work still
/// sitting in the tree, for the next holder to start inside. [`park_the_stranded_holder`]'s doc
/// named exactly that as the case it deliberately did not cover. It is covered here, by the same
/// [`park_and_hand_on`] every other occasion uses, under [`ParkOccasion::PastItsBound`] — so the
/// refusal rule, the `nxc status` mark and the retry are one behaviour across all three and not
/// three that resemble each other.
///
/// **The CAS is untouched, and the park does not widen what it guards.** `expires` is still the
/// value read off the row above, and it is still what
/// [`ChatStore::reclaim_expired_working_tree_and_take_next`]'s delete names — the park happens
/// BEFORE that call (it must: saving the work is the point), so what a renewal during the park
/// costs is that the reclaim matches nothing and the copy stays with the holder. That is the CAS
/// doing its job, not a hole in it: nothing is lost, because the work is on a branch and in
/// `parked_work`, and the holder's own next trigger is told where it is
/// ([`resume_parked_work`]). The window is narrow by construction — every session in the claim area
/// has already been asked and none is running, so a renewal there needs a process nothing can see.
///
/// **A refusal that can pass KEEPS the copy** — the whole of what the rule means here, and the one
/// thing this occasion could not be given before it owned the park. A tick used to say "the claim
/// stays where it is and whatever is queued keeps waiting" in a `work_not_parked` finding and then
/// reclaim the lease two lines later, because the sweep did not know a park had just been refused.
/// Now the refusal IS the sweep's, so [`ParkOutcome::Held`] is a decline: the tree is left exactly
/// as the person has to find it to fix it, and the retry armed by [`park_and_hand_on`] is what comes
/// back. **And it is not a wedge**, because the mark is only ever kept while the occasion stands:
/// nobody queued any more, or a lease no longer past its bound, and the row this occasion wrote goes
/// ([`forget_a_refusal_of_this_occasion`]).
///
/// **`park_already_held` is the other half of `park_step`'s "at most one occasion acts per tick".**
/// A stranded escalation over an expired lease stands for BOTH occasions; the park step reaches it
/// first, and if its park was refused, attempting the identical park again here would meet the
/// identical refusal — a second finding on the same receipt, and a stamp overwritten so that the
/// occasion that is actually retrying no longer owns its own row.
fn sweep_expired_working_tree(
    ctx: &Ctx,
    store: &mut ChatStore,
    park_already_held: bool,
    warnings: &mut Vec<FailedConsequence>,
) -> Result<SweepStep> {
    let Some((holder, expires)) = store.working_tree_lease_row()? else {
        return Ok(SweepStep::default());
    };
    // The head is what a re-arm has to be keyed on, and "is anybody waiting?" is the same read.
    let Some(head) = store.peek_working_tree_queue()? else {
        // **The occasion is over**: this one moves the copy for somebody who is waiting for it, and
        // nobody is. A refusal EITHER occasion recorded is not being retried by anybody any more and
        // goes with it (fix round 1 of nxf 6j6v.8bv9) — the clauses below are reasons not to act
        // NOW on a wait that still stands, and they leave the row alone. Both occasions are cleared
        // here because "nobody is waiting" ends both of them (nxf 6j6v.xb24); which of the two has a
        // row on record is settled by `forget_a_refusal_of_this_occasion`'s own stamp check.
        forget_a_refusal_of_this_occasion(store, ParkOccasion::PastItsBound);
        forget_a_refusal_of_this_occasion(store, ParkOccasion::DiedInsideItsBound);
        return Ok(SweepStep::default()); // nobody waiting; the next acquire reclaims the row itself
    };
    if store.working_tree_holder(ctx.now)?.is_some() {
        // The other way THAT occasion ends: the lease is not past its bound any more, so there is
        // nothing of `past_its_bound`'s to retry. Cleared BEFORE the arming below, because that is
        // what puts the waiting commission back on the clocks it should now be waiting for.
        forget_a_refusal_of_this_occasion(store, ParkOccasion::PastItsBound);
        // **…and the occasion that lives exactly here** (nxf 6j6v.xb24): a lease still inside its
        // bound with a holder that is provably GONE. Before this item the two hours it had left were
        // dead time for whoever was queued — nothing releases when the process that would release is
        // not there, and the bound was the only clock watching.
        let handed_on = a_dead_holder_inside_its_bound(
            ctx,
            store,
            &holder,
            &expires,
            park_already_held,
            warnings,
        )?;
        if let Some(handed_on) = handed_on {
            // **A hand-off that moved nothing still owes the waiter a look** (fix round 1 of nxf
            // 6j6v.xb24). The park went through and the reclaim behind it matched no row: the
            // holder renewed between the read and the write, which is the compare-and-swap doing
            // its job — but the copy is still where it was, the queue is still a queue, and the
            // alarm that brought this tick here has been spent. Without this the rival's wait would
            // fall back to "until some other chain releases", which is the wedge itself, reached
            // through the one door that reported a hand-off and returned.
            if handed_on.promotions.nothing_moved() {
                arm_the_next_look(ctx, store, &head, &expires)?;
            }
            return Ok(SweepStep {
                swept: None,
                handed_on: Some(handed_on),
            });
        }
        // Still within its bound with nothing proving its holder gone — the holder keeps it, and the
        // alarm moves to where the bound is NOW rather than being spent on a renewal. **Through
        // `drain_recheck_instant` since nxf 6j6v.de9s**, because the bound is no longer the only way
        // this wait can end: a contended lease also ends at its park deadline, and since nxf
        // 6j6v.xb24 every wait also ends at the liveness cadence — which is what makes a holder that
        // dies here noticed in a minute rather than at the bound, and is why this re-arms on EVERY
        // decline instead of only on the ones that had a process in the way.
        arm_the_next_look(ctx, store, &head, &expires)?;
        return Ok(SweepStep::default());
    }
    let Some(scope) = WorkScope::parse(&holder) else {
        // Stated, not swallowed (Integrity #10): a queue parked behind a key nothing can read is
        // exactly the "waiting forever with nothing said" this item exists to end. The way out named
        // below is the WAITING commission's operation, not a thread inside the unreadable holding
        // chain — naming one of those would be refused `not_found` the moment nothing is running in
        // it, which this warning cannot even tell (nxf 6j6v.b9nf) — and since nxf 6j6v.ezbr it is
        // named by that operation's FIRST thread, with who may use it.
        let take_back = how_a_waiting_commission_is_taken_back(store, head.thread.as_deref());
        eprintln!(
            "warning: this workspace's working-tree lease is recorded under a scope key this \
             version cannot read (`{holder}`), so the commission parked behind it cannot be \
             started automatically — {take_back}"
        );
        return Ok(SweepStep::default());
    };
    let running = sessions_still_running(ctx, store, &store.work_scope_threads(&scope)?)?;
    if !running.is_empty() {
        eprintln!(
            "warning: the chain holding this workspace's working copy (`{holder}`) is past its \
             bound ({expires}) but still has a live process ({}), so the working copy is NOT being \
             reclaimed — a commission is waiting behind it and will start when that chain finishes",
            running.join(", ")
        );
        // **Look again on the LIVENESS clock, not one lease-bound out** (review of PR #376, Code
        // Quality #1 / Integrity #2). This branch used to re-arm at `now + WORKING_TREE_LEASE_BOUND`
        // while the acquire path armed the same case a minute out — and because
        // [`arm_the_lease_bound`] REPLACES the pending window for a thread rather than stacking a
        // second one beside it, the first fast tick landed here and overwrote its own successor with
        // a two-hour wait. A holder that hung and then died was then noticed two hours late, which
        // is most of the wedge this whole line of work removes.
        //
        // Both sites now ask ONE function which instant this is, so they cannot drift apart again.
        arm_the_next_look(ctx, store, &head, &expires)?;
        return Ok(SweepStep::default());
    }
    if park_already_held {
        // A park of this very holder was attempted a moment ago by an occasion that reached it
        // first, and it was refused for a reason that can pass. Its row is on record, its retry is
        // armed, and the copy is staying — so there is nothing here but a duplicate to make. Nothing
        // is forgotten either: this occasion stands as much as the other one does.
        return Ok(SweepStep::default());
    }
    // The claim ROOT, which is what the scope key names — the same anchor `park_the_stranded_holder`
    // puts its findings on.
    let anchor = match &scope {
        WorkScope::Thread(t) => Some(t.as_str()),
        WorkScope::Session(_) => None,
    };
    let why = format!(
        "operation {holder} has been holding this workspace's working copy past its bound \
         ({expires}) with nothing running in it any more, and something else is waiting for the copy"
    );
    let outcome = park_and_hand_on(
        ctx,
        store,
        &holder,
        HandOff::Expired {
            holder_key: &holder,
            expires: &expires,
        },
        &why,
        warnings,
        anchor,
        ParkOccasion::PastItsBound,
    )?;
    let (parked, unparked, promotions) = match outcome {
        ParkOutcome::Parked { parked, promotions } => (Some(parked), None, promotions),
        ParkOutcome::HandedOnUnparked {
            refusal,
            promotions,
        } => (None, Some(refusal), promotions),
        // The rule's transient half: the claim stays, the refusal is on `nxc status`, the retry is
        // armed, and this sweep reports nothing because nothing moved. See this function's doc for
        // why declining here is what makes that finding true rather than contradicted.
        ParkOutcome::Held { .. } => return Ok(SweepStep::default()),
    };
    // A sweep that moved nothing reports nothing — and "moved" includes an entry that went back in
    // line (review of PR #380, Integrity #1): the lease WAS reclaimed and the entry WAS taken off
    // the queue, so a tick that says "nothing to do" would be hiding a reclaim that happened.
    //
    // **A park counts as movement on its own** (nxf 6j6v.8bv9): the work is on a branch and recorded
    // whether or not the reclaim behind it matched. The one shape where it did not — a holder that
    // renewed between the read and the write — is the CAS refusing to take the copy, and a receipt
    // that stayed silent about the commit would be the one place a reader could learn that the tree
    // moved. `unparked` is deliberately NOT such a fact: nothing was committed and nothing was
    // handed on, so there is no movement to report beyond the finding already on `warnings`.
    //
    // **And a reclaim that took nothing arms the next look** (fix round 1 of nxf 6j6v.xb24), on
    // both sides of the return below and for the reason [`arm_the_next_look`] gives: whichever of
    // the two this was, the copy is still the holder's, the queue is still a queue, and the alarm
    // that brought this tick here is spent. It is the same defect the branch inside the bound had —
    // one rule, one site, so neither can be fixed without the other.
    if promotions.nothing_moved() {
        arm_the_next_look(ctx, store, &head, &expires)?;
    }
    if parked.is_none() && promotions.nothing_moved() {
        return Ok(SweepStep::default());
    }
    Ok(SweepStep {
        swept: Some(WorkingTreeSweep {
            scope: holder,
            expired: expires,
            parked,
            unparked,
            promotions,
        }),
        handed_on: None,
    })
}

/// **What the tick's sweep came to** — at most one of the two, because the two occasions it can act
/// on are mutually exclusive: a lease is either past its bound or inside it (nxf 6j6v.xb24).
///
/// Two fields rather than one enum because they land on two different fields of the receipt, and
/// that is the point of the split: [`ParkOccasion::PastItsBound`] is a MOVEMENT with an `expired`
/// instant of its own and reports on [`TickReceipt::working_tree`], while
/// [`ParkOccasion::DiedInsideItsBound`] has no expiry to report — its lease was still standing — and
/// so reports through [`TickReceipt::handed_on`] beside the park step's own occasions, where
/// [`HandedOn::occasion`] says which trouble it was. Putting the second on `WorkingTreeSweep` would
/// have meant an `expired` field carrying an instant that has NOT passed, which is a receipt telling
/// a reader something untrue in the one field they would check first.
#[derive(Default)]
struct SweepStep {
    /// The lease that had run out, what happened to its holder's work, and who started.
    swept: Option<WorkingTreeSweep>,
    /// The hand-off of a holder that died INSIDE its bound.
    handed_on: Option<HandedOn>,
}

/// **Take the working copy from a holder that is gone before its bound says so** (nxf 6j6v.xb24) —
/// [`sweep_expired_working_tree`]'s inside-the-bound branch, split out because it is a whole
/// occasion rather than a clause.
///
/// `Ok(None)` is "the copy stays where it is", for any of four reasons, and the caller then arms its
/// re-check: the holder is not provably dead ([`holder_is_provably_dead`], which is the interesting
/// one and has five ways of answering `false`), the key cannot be read, another occasion is already
/// holding a refused park of this same holder, or the park was refused for a reason that can pass.
///
/// **The row discipline is the one two fix rounds of nxf 6j6v.8bv9 established**, applied to this
/// occasion: a `PARK REFUSED` mark is only true while something is retrying it, so the mark this
/// occasion wrote is forgotten the moment the holder stops being provably dead — a session that
/// starts answering again, a round that gets answered, a hold that appears. The caller forgets it
/// for the other two ways the occasion ends (nobody is waiting any more; the lease ran out, which
/// hands the retry to [`ParkOccasion::PastItsBound`] and whose own park attempt re-stamps the row).
///
/// **What it does NOT do is decide anything about a holder whose key it cannot read** (fix round 2's
/// rule): no park, and no forgetting either.
fn a_dead_holder_inside_its_bound(
    ctx: &Ctx,
    store: &mut ChatStore,
    holder: &str,
    expires: &str,
    park_already_held: bool,
    warnings: &mut Vec<FailedConsequence>,
) -> Result<Option<HandedOn>> {
    let Some(scope) = WorkScope::parse(holder) else {
        // Decide NOTHING about it: the branch below says this out loud once the bound has passed,
        // and saying it on every tick of every live lease would be a warning nobody can act on.
        return Ok(None);
    };
    if !holder_is_provably_dead(ctx, store, &scope)? {
        // The occasion does not stand, so nothing is retrying a park under it.
        forget_a_refusal_of_this_occasion(store, ParkOccasion::DiedInsideItsBound);
        return Ok(None);
    }
    if park_already_held {
        // `park_step`'s "at most ONE occasion acts per tick", for this occasion too: the same park
        // of the same holder was attempted a moment ago and refused for a reason that can pass, so
        // attempting it again would meet the same answer and overwrite the stamp of whichever
        // occasion actually owns the retry. Nothing is forgotten — this occasion stands as much as
        // the other one does.
        //
        // **It cannot fire today, and it is here rather than left out because of what would make it
        // fire.** The two occasions the park step acts on are DISJOINT from this one by
        // construction: a stranded escalation needs nothing outstanding and clause 2 above needs
        // something outstanding; an availability boundary in this claim area is clause 5's own
        // decline. So no tick can reach here with `park_already_held` set. A fourth occasion, or
        // either of those two narrowing, would change that silently — and the cost of the guard is
        // one branch, against a duplicate finding and a restamped row.
        return Ok(None);
    }
    let anchor = match &scope {
        WorkScope::Thread(t) => Some(t.as_str()),
        WorkScope::Session(_) => None,
    };
    let why = format!(
        "operation {holder} still holds this workspace's working copy inside its bound ({expires}), \
         but nothing in it is running any more and a thread of it is still owed an answer that \
         nothing ever ended — so it died without giving the copy back, and something else is \
         waiting for it"
    );
    let outcome = park_and_hand_on(
        ctx,
        store,
        holder,
        HandOff::DeadHolder {
            holder_key: holder,
            expires,
        },
        &why,
        warnings,
        anchor,
        ParkOccasion::DiedInsideItsBound,
    )?;
    // The rule's transient half, exactly as the branch past the bound applies it: the claim stays,
    // the refusal is on `nxc status`, the retry is armed by `park_and_hand_on`, and nothing here is
    // reported because nothing moved.
    Ok(outcome.handed_on(holder, ParkOccasion::DiedInsideItsBound))
}

/// **Is the operation holding this working copy GONE, although its bound has not run out?** (nxf
/// 6j6v.xb24) — the one question that lets [`sweep_expired_working_tree`] act inside the bound, and
/// every clause of it is a way of being wrong that the sweep must not be.
///
/// The gap it closes was the last two hours of the wedge. [`WORKING_TREE_LEASE_BOUND`] is a backstop
/// for a holder nobody can ask about; a holder that dies HARD is one everybody can ask about, and
/// until this item nothing did until the backstop elapsed. So the copy sat with a corpse while a
/// commission waited behind it — for up to two hours, on a device where the answer was available in
/// a couple of milliseconds.
///
/// **What it costs is measured rather than supposed, and measured AS A WHOLE**
/// (`tests::what_the_whole_dead_holder_check_costs`): this function END TO END, over a claim area of
/// twenty threads with twenty sessions, with every clause reached — a median of **1.971 ms** in a
/// debug build against the 50 ms per-tick threshold the item was given. The liveness pass inside it
/// is the bulk of that and is timed separately next door
/// (`tests::what_one_liveness_pass_over_a_claim_area_costs`, about 1.38 ms in a run of its own —
/// two stopwatches, so the two numbers are not from one run); the rest is the four reads around it,
/// two of which were an N+1 until fix round 1 of this item's review made them one bulk read each
/// ([`ChatStore::newest_sessions_in_threads`], [`ChatStore::interrupted_threads`] — with the same
/// staging, the N+1 cost a median of 2.68 ms and grew with the claim area).
///
/// **All five, and the answer is `false` the moment one of them is not met.** Taking a working copy
/// away writes into it (`git checkout`), so the direction that must never be guessed at is this one.
///
/// 1. **The worker ANSWERS the liveness question** ([`Worker::answers_liveness`](crate::worker::
///    Worker::answers_liveness)). [`Worker::session_is_running`](crate::worker::Worker::
///    session_is_running) has a fail-OPEN default of `false`, chosen so the trait could grow the
///    method and so one unknowable session could not stall a channel — and every other caller of
///    [`sessions_still_running`] deliberately does not branch on it. This one must: the others read
///    a `false` as permission to release a claim whose clock has ALREADY run out, while this reads
///    it as evidence that a chain is dead, and "I never looked" is not evidence of anything. A
///    worker that cannot answer never takes a copy early.
/// 2. **At least one thread in the claim area still OWES an answer**
///    ([`ChatStore::threads_owing_an_answer`]). A holder whose sessions all ended normally and
///    handed the task back is not dead, it is STRANDED — that is
///    [`ParkOccasion::StrandedEscalation`] and it keeps its thirty-minute contention rule, because
///    a human may still be about to answer. The two occasions are disjoint by construction:
///    [`note_the_contention`] requires that NOTHING is outstanding, and this requires that something
///    is.
/// 3. **Nothing in the claim area has a live process** ([`sessions_still_running`]) — the guard no
///    park may ever be without, and the same one the other occasions apply. A `git checkout` against
///    a tree a live session is writing into is the corruption this whole epic exists to prevent.
/// 4. **No owing thread's session reported its end** (`session_map.ended`). A reported end means the
///    sidecar's teardown RAN — the process shut itself down and said so — which is not a hard death,
///    whatever the register then says about an unanswered obligation. That is a session that ended
///    without replying, and taking its operation's copy on the strength of it would be acting on a
///    tidy shutdown as if it were a crash.
///
///    Asked of the NEWEST session of each owing thread, which is the one that owes: an older, ended
///    session on the same thread is history (a resume mints a new row), and reading it as a reported
///    end would make a thread uncoverable for ever once anything on it had ever shut down cleanly.
///    A thread that owes and has NO session at all is also `false` — it is waiting for a HUMAN, and
///    nothing there ever died.
/// 5. **Nothing in the claim area is interrupted at an availability boundary**
///    ([`ChatStore::interrupted_threads`], the one bulk read of the whole standing list — fix round
///    1 of this item's review put it here in place of a row read per hold). That occasion is
///    [`ParkOccasion::
///    AvailabilityBoundary`]'s, with its own window, its own "is the round already answered" question
///    and its own resume path — and an interrupted session is deliberately recorded as ENDED, so
///    without this clause the two would be telling one operation's story twice. Deliberately the
///    whole standing list for this claim area and not [`park_an_interrupted_holder`]'s narrower
///    "is it still an occasion" reading: this is a reason to DECLINE, and declining on a hold that
///    has fallen due costs a minute (the resume takes it up, or the next tick asks again), while
///    acting on one costs a park of an operation somebody else is about to resume.
///
/// It takes `&ChatStore`, writes nothing and decides nothing about what to DO — which is what lets
/// the sweep call it as a guard and lets it be reasoned about on its own.
fn holder_is_provably_dead(ctx: &Ctx, store: &ChatStore, scope: &WorkScope) -> Result<bool> {
    // Cheapest first, and it is also the one that disqualifies a whole class of host: a workspace
    // whose worker cannot look pays one field read per tick for this entire mechanism.
    if !ctx.worker.answers_liveness() {
        return Ok(false);
    }
    let threads = store.work_scope_threads(scope)?;
    let owing = store.threads_owing_an_answer(&threads, ctx.now)?;
    if owing.is_empty() {
        return Ok(false);
    }
    if !sessions_still_running(ctx, store, &threads)?.is_empty() {
        return Ok(false);
    }
    // ONE read for the whole clause, not one per owing thread (fix round 1): see
    // [`ChatStore::newest_sessions_in_threads`] for the N+1 that was here and why this table is the
    // wrong one to walk. An owing thread absent from the answer never ran a session at all.
    let newest = store.newest_sessions_in_threads(&owing)?;
    for thread in &owing {
        let Some(session) = newest.get(thread) else {
            return Ok(false); // nothing ever ran here: an obligation on a human, not a death
        };
        if session.ended.is_some() {
            return Ok(false);
        }
    }
    // …and one read for this clause too: the threads with a standing hold, intersected with the
    // claim area, instead of a row read per hold to place it.
    let interrupted = store.interrupted_threads()?;
    if threads.iter().any(|t| interrupted.contains(t)) {
        return Ok(false);
    }
    Ok(true)
}

/// **When to come back for a commission parked behind somebody else's claim** — the ONE decision,
/// asked by every place that makes it (nxf 6j6v.fabb; corrected by the review of PR #376; widened by
/// nxf 6j6v.xb24).
///
/// Three things can end this wait, and they end at different times. The answer is the EARLIEST of
/// them that is still ahead of `now`:
///
/// * **the LEASE runs out** — `holder_expires`, read off the lease row rather than guessed. An
///   instant already behind us is simply not a candidate ([`earliest_after`] filters it), which is
///   what stops an alarm being armed in the past.
/// * **the liveness cadence** ([`SESSION_LIVENESS_RECHECK_SECS`], nxf 6j6v.858n) — the interval this
///   house already uses for the wait *is that process gone yet*. It is now a candidate on EVERY
///   call, and that is nxf 6j6v.xb24's change: the three states that used to ask for it one at a
///   time — a holder past its bound with a process still running, a park refused and being retried,
///   and (new) a holder that may die at any moment inside a bound with two hours left on it — are
///   all the same question, *come back and look*. So it is asked once here instead of being
///   reconstructed by each caller, and the two booleans that used to select it are gone: they can
///   only ever have SHORTENED the wait to this same cadence, and the earliest-of rule shortens it
///   anyway.
/// * **the PARK deadline** ([`park_deadline`], nxf 6j6v.de9s) — a contended lease also ends at the
///   instant its holder's work may be parked, which is normally earlier than either.
///
/// **What the change costs and buys, stated plainly.** While anybody is queued behind a claim, a
/// tick now looks once a minute rather than once at the bound. That is the whole of what makes
/// [`ParkOccasion::DiedInsideItsBound`] arrive in a minute instead of in two hours, and what it
/// costs is one tick per minute per waiting commission. What that tick does about THIS is measured —
/// [`holder_is_provably_dead`] end to end, a median of 1.971 ms for a claim area of twenty sessions
/// (`tests::what_the_whole_dead_holder_check_costs`). What the surrounding `nxc tick` process costs
/// is not: it is the same process this service already runs on every other occasion, and this
/// changes how OFTEN it runs rather than what one run of it does.
///
/// **Why it is a function and not a few `if`s at each site.** The callers —
/// [`acquire_or_queue`] when it parks, [`sweep_expired_working_tree`] when it declines, and
/// [`arm_the_park_retry`] — disagreed: the acquire armed a minute out for a live holder and the
/// sweep armed two hours out for the same holder. [`arm_the_lease_bound`] REPLACES a thread's
/// pending window rather than stacking beside it, so the first fast tick reached the sweep and
/// overwrote its own successor with the slow one. The cadence collapsed to the old two-hour wait
/// after exactly one check, which is most of the wedge this line of work exists to remove, and no
/// test could see it because no test asked what was armed. One function is what makes them agree by
/// construction — there is one rule and one place to read it, so the drift is not fixed but
/// unavailable.
///
/// Every instant is UTC-normalized before it is compared, for [`crate::working_tree::to_utc_rfc3339`]'s
/// reason: these are byte comparisons, and a mixed-offset instant sorts wrongly.
fn drain_recheck_instant(
    now: &str,
    holder_expires: &str,
    contended_since: Option<&str>,
) -> Result<String> {
    let cadence = session_liveness_recheck(now)?;
    let bound = crate::working_tree::to_utc_rfc3339(holder_expires)?;
    let park = contended_since.map(park_deadline).transpose()?;
    let now = crate::working_tree::to_utc_rfc3339(now)?;
    let mut candidates = vec![bound.as_str(), cadence.as_str()];
    if let Some(park) = &park {
        candidates.push(park.as_str());
    }
    // The cadence is the fallback as well as a candidate: it is always in the future by
    // construction, so `unwrap_or` here is unreachable and is the right answer if it ever were not.
    Ok(earliest_after(&now, candidates.into_iter())
        .unwrap_or(cadence.as_str())
        .to_string())
}

/// Schedule the tick that will drain the queue when the lease this trigger just parked behind runs
/// out (nxf 6j6v.fabb).
///
/// Best-effort, exactly like every other scheduling site in this module: the commission is already
/// persisted and already parked, and a clock that could not be armed loses the automatic drain, not
/// the commission. It costs nothing to be wrong in the other direction either — the sweep is a
/// no-op on a lease that is still standing, so an early or duplicate tick simply declines.
///
/// **Keyed on the parked commission's own thread**, which is what makes a duplicate impossible
/// rather than merely unlikely: [`ServiceTimer`](crate::timer::ServiceTimer) files a deadline under
/// the thread id, so re-parking the same commission REPLACES its pending window instead of stacking
/// a second one beside it (an `at` queue does the latter). A trigger with no thread of its own (a session-scoped one) is
/// not queued in the first place — `trigger_role` skips the whole lease gate for those — so the
/// `None` arm here is unreachable in practice and is a decline rather than an assertion.
fn arm_the_lease_bound(
    ctx: &Ctx,
    store: &ChatStore,
    entry: &QueuedTrigger,
    expires: &str,
) -> Option<FailedConsequence> {
    let thread = entry.thread.as_deref()?;
    match ctx
        .timer
        .schedule(thread, expires, &crate::timer::tick_command(thread))
    {
        Ok(_) => None,
        Err(e) => unarmed_drain_finding(store, entry, &format!("scheduling it failed: {e}")),
    }
}

/// **Come back and look again, for whoever is still waiting** — the re-arm
/// [`sweep_expired_working_tree`] owes at every end of a tick that left the working copy in the same
/// hands (nxf 6j6v.fabb's rule, one site since fix round 1 of nxf 6j6v.xb24).
///
/// The tick that runs the sweep is the one an earlier arming scheduled, and it is ONE-SHOT. So a
/// sweep that ends without the copy moving has just spent the waiting commission's only alarm: unless
/// it arms the next look itself, that commission is back to "waits until some other chain happens to
/// release", which is the wedge this whole line of work removes. Every such end therefore arms —
/// the decline on a live process, the decline inside the bound, and (fix round 1) the hand-off whose
/// compare-and-swap lost its race, which is a park that happened and a copy that did not move.
///
/// `holder_expires` is the value read off the lease row at the top of the sweep. Where a renewal is
/// what made the caller land here, that value is now in the PAST — which is not a problem to correct
/// for: [`drain_recheck_instant`] simply does not count a passed instant as a candidate, and the
/// answer is the liveness cadence, a minute out. Re-reading the row to arm a renewed bound would be
/// arming the longer of the two waits.
///
/// Best-effort in the same way its neighbour is: an instant that cannot be resolved loses the
/// scheduled look, never the claim.
fn arm_the_next_look(
    ctx: &Ctx,
    store: &ChatStore,
    head: &QueuedTrigger,
    holder_expires: &str,
) -> Result<()> {
    if let Ok(next) = drain_recheck_instant(
        ctx.now,
        holder_expires,
        store.working_tree_contended_since()?.as_deref(),
    ) {
        let _ = arm_the_lease_bound(ctx, store, head, &next);
    }
    Ok(())
}

/// The finding an unarmed drain is, and the breadcrumb beside it — the pair every scheduling site
/// in this module keeps, for the reason 6j6v.93zd gives: a human at a terminal sees it now, and the
/// record travels to whoever is not there.
///
/// [`ConsequenceClass::TickUnscheduled`] rather than a new class: it means "the tick that watches
/// this window was not scheduled, so the window has no clock", and that is exactly true here — the
/// window is the holder's lease bound instead of a declared `timeout:`.
fn unarmed_drain_finding(
    store: &ChatStore,
    entry: &QueuedTrigger,
    why: &str,
) -> Option<FailedConsequence> {
    let thread = entry.thread.as_deref()?;
    let detail = format!(
        "the commission for role {} is parked behind the working-tree lease, and the tick that \
         would have drained the queue when that lease runs out was not armed ({why}) — it will \
         start when some other chain releases the working copy, or {}",
        entry.role,
        how_a_waiting_commission_is_taken_back(store, Some(thread))
    );
    eprintln!("warning: {detail}");
    Some(FailedConsequence::tick_unscheduled(thread, detail))
}

/// **How a message about a commission waiting behind the working copy says it can be taken back**
/// (nxf 6j6v.ezbr) — one sentence for the three places that say it: a trigger parked because the
/// holder's liveness could not be read, a queue behind a scope key this version cannot parse, and
/// a drain whose tick could not be armed.
///
/// All three used to name `nxc withdraw --thread <this commission's own thread>`, and since the
/// owner's decision of 2026-09-20 that is wrong twice over: the thread is a member of its operation
/// whenever an agent sent it, and a withdrawal names the operation's FIRST thread; and the reader
/// may itself be a session this workspace started — the first of these runs in whatever process
/// called `send` — which `withdraw` refuses. So it names the operation's root and who may use it,
/// and points a session at escalation.
///
/// The root is best-effort: a read that fails names the commission's own thread, which the
/// withdrawal then refuses by name with the root in its answer — a longer way round, never a wrong
/// one.
fn how_a_waiting_commission_is_taken_back(
    store: &ChatStore,
    waiting_thread: Option<&str>,
) -> String {
    const FROM_A_SESSION: &str = "a session this workspace started escalates instead \
                                  (`nxc reply --thread <its own thread> --escalate -`)";
    match waiting_thread {
        Some(thread) => {
            let root = store
                .thread_root(thread)
                .unwrap_or_else(|_| thread.to_string());
            format!(
                "the person who started operation {root} can take it back with `nxc withdraw \
                 --thread {root}` — {FROM_A_SESSION}"
            )
        }
        None => format!(
            "the person who started its operation can take it back with `nxc withdraw`, naming \
             that operation's first thread — {FROM_A_SESSION}"
        ),
    }
}

// ---- parking a stranded escalation (nxf 6j6v.de9s) ----------------------------------------------

/// **What a park did**, for the tick's receipt and for whoever reads it later.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct ParkedOperation {
    /// The claim area whose work was put away — the same `scope_key` form
    /// [`WorkingTreeSweep::scope`] carries.
    pub scope: String,
    /// When the contention this park ran out of first stood: the instant the deadline was measured
    /// from, not the instant the escalation happened. Reported because those two are different by
    /// design (the owner's rule), and a reader who assumes otherwise cannot check the arithmetic.
    pub contended_since: String,
    /// Where the work is now.
    pub parked: crate::park::Parked,
    /// Who was waiting, and what happened to them — the same shape a release and a sweep report.
    #[serde(flatten)]
    pub promotions: Promotions,
}

/// The instant a contention that began at `since` runs out into a park.
///
/// One function so the arming site and the deciding site cannot disagree about when that is —
/// [`drain_recheck_instant`]'s own argument, applied to the second clock this path now has.
fn park_deadline(since: &str) -> Result<String> {
    facade::resolve_instant(
        since,
        crate::park::PARK_AFTER,
        "the escalation park deadline",
    )
}

/// **Is the working copy CONTENDED right now, and since when?** — the whole of the owner's *"der
/// Timer startet bei KONTENTION, nicht beim Eskalieren"*, in one derivation.
///
/// Contention is two facts standing at the same time, and neither alone starts anything:
///
/// 1. **The holder has handed its task back and owes nothing.** That is questions (2) and (3) of
///    [`release_working_tree_if_scope_is_done`], asked from the other end: an escalation (or an open
///    question) discharged the sender's turn, so nothing is outstanding, and yet the claim is not
///    released because the task is mid-flight and travelling upward to a human. Nobody is working;
///    somebody is waiting to be answered.
/// 2. **Something else is in the queue.** With an empty queue there is no cost to anybody, so
///    nothing is measured and nothing is parked — which is exactly what keeps this mechanism off the
///    ordinary path rather than making it the normal way an escalation ends.
///
/// The instant is a MEMO of that derivation, not a state machine
/// ([`ChatStore::note_working_tree_contention`]): every call re-derives the pair and either records
/// the first instant it saw them together or clears a memo that no longer applies. So an escalation
/// that is answered, or a queue that drains, ends the contention with no event needed — and the
/// next one is measured from its own beginning rather than from a stale one.
///
/// **Called from the three places either half can change**: the acquire path when a rival parks
/// behind the lease, the reply path when a hand-back stops the release, and the tick before it
/// decides anything. It is cheap on the common path — no lease, or an empty queue, and it is two
/// indexed single-row reads — and pays for the subtree walk only when both halves already stand.
fn note_the_contention(ctx: &Ctx, store: &mut ChatStore) -> Result<Option<String>> {
    let Some((holder, _)) = store.working_tree_lease_row()? else {
        // No lease at all: there is nothing to contend for, and no row to write a memo on.
        return Ok(None);
    };
    let clear = |store: &mut ChatStore| -> Result<Option<String>> {
        store.note_working_tree_contention(None)?;
        Ok(None)
    };
    if store.peek_working_tree_queue()?.is_none() {
        return clear(store);
    }
    // An unreadable key is left alone rather than guessed at, exactly as the release and the sweep
    // leave it: its threads cannot be resolved, so neither half of the question can be asked, and
    // the sweep is the one place that says so out loud.
    let Some(scope) = WorkScope::parse(&holder) else {
        return Ok(None);
    };
    let threads = store.work_scope_threads(&scope)?;
    if store.threads_have_outstanding(&threads, ctx.now)? {
        return clear(store);
    }
    if !store.threads_await_an_unanswered_hand_back(&threads)? {
        // Two shapes end here, and neither is contention. A chain that is simply between steps —
        // nothing outstanding, nothing handed back, and a release about to happen on this very
        // path. And an escalation that HAS been answered: the operation is at work again, the
        // human's answer is the last word in the area, and parking now would commit somebody's
        // work out from under them. See that predicate for why it is not
        // `threads_handed_back` — the two questions differ by exactly this case.
        return clear(store);
    }
    store.note_working_tree_contention(Some(ctx.now))
}

/// The working copy this device's sessions run in, or the refusal that says why there is none.
///
/// The refusal is PERMANENT ([`ParkRefusal::is_permanent`]): whether a host names a directory is a
/// property of the host, and no tick changes it — so a park that meets it hands the copy on
/// unparked rather than holding a queue for an answer that will never be different.
fn the_working_copy(ctx: &Ctx) -> std::result::Result<crate::park::WorkingCopy, ParkRefusal> {
    match ctx.worker.working_copy() {
        Some(root) => Ok(crate::park::WorkingCopy::at(root)),
        None => Err(ParkRefusal::NoWorkingCopy(
            "this workspace's chat worker does not run sessions in a directory it can name, so an \
             operation's work cannot be committed anywhere"
                .to_string(),
        )),
    }
}

/// **Record where an operation stood the FIRST time it took the working copy** (correction 2).
///
/// Best-effort and never fatal: an operation with no recorded base simply cannot be parked, which is
/// a named refusal at park time rather than a failure at trigger time. The alternative — failing a
/// trigger because a git read did not answer — would take the whole workspace down for a mechanism
/// that only ever fires on an escalation nobody answered.
///
/// **One git read per OPERATION, not per trigger.** The store is asked first, and the working copy
/// is only read when nothing is recorded yet; a chain that acquires forty times pays for the first.
/// That is what keeps this off the hot path in the way that matters — the second acquire onward is
/// one indexed single-row read.
fn record_the_operation_base(ctx: &Ctx, store: &mut ChatStore, scope: &WorkScope) {
    let key = scope.key();
    match store.operation_base(&key) {
        Ok(Some(_)) => return,
        Ok(None) => {}
        Err(e) => {
            eprintln!("warning: could not read this operation's base branch: {e}");
            return;
        }
    }
    let Ok(copy) = the_working_copy(ctx) else {
        // A worker with no directory is the ordinary case for an embedder, and it is not worth a
        // line on every first acquire: the park's own refusal says it, once, where it matters.
        return;
    };
    match copy.here() {
        Ok(base) => {
            if let Err(e) = store.record_operation_base(&key, &base, ctx.now) {
                eprintln!("warning: could not record this operation's base branch: {e}");
            }
        }
        Err(refusal) => {
            // Also silent by design: "the workspace is not a git repository" is a permanent, benign
            // property of many workspaces, and saying it on every first acquire would be a warning
            // nobody can act on. The park says it once, when it is actually in the way.
            let _ = refusal;
        }
    }
}

/// **Which trouble a park step acted on** (nxf 6j6v.8bv9) — the occasions on which the working copy
/// is taken from a holder that is not going to give it back soon, and its work is parked first.
///
/// `#[non_exhaustive]` because the list grows on purpose: every trouble hand-off parks (owner
/// decision of 2026-09-17), and each new one is a new occasion here rather than a new receipt shape.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "snake_case")]
#[non_exhaustive]
pub enum ParkOccasion {
    /// The holder escalated, nobody answered, and another operation has been waiting for
    /// [`crate::park::PARK_AFTER`] — nxf 6j6v.de9s.
    StrandedEscalation,
    /// The holder stopped at an availability boundary and its window is not due, while another
    /// operation waits — nxf 6j6v.npy3, retried on the tick since nxf 6j6v.8bv9.
    AvailabilityBoundary,
    /// The holder's lease has RUN OUT, nothing in its claim area still has a process, and another
    /// operation is queued behind the copy — [`sweep_expired_working_tree`], which saved nothing
    /// before nxf 6j6v.8bv9. This is the occasion that needs no cooperation from the holder at all:
    /// a chain that died hard never escalated and never announced a boundary, so it is the only one
    /// of the three a crash can reach.
    PastItsBound,
    /// **The holder is GONE and its bound has not run out yet** — nxf 6j6v.xb24. The same hard death
    /// [`PastItsBound`](Self::PastItsBound) eventually catches, noticed while the lease is still
    /// standing instead of after the two hours it had left: nothing in the claim area has a process,
    /// at least one of its threads still owes an answer, and none of those threads reported an end.
    ///
    /// It is the one occasion that rests on EVIDENCE rather than on a clock, which is why it is also
    /// the one with a precondition on the worker: it acts only where
    /// [`Worker::answers_liveness`](crate::worker::Worker::answers_liveness) is `true`. See
    /// [`holder_is_provably_dead`] for the whole of what has to hold, and why each clause is there.
    DiedInsideItsBound,
    /// **The holder's running round was WITHDRAWN** (nxf 6j6v.b9nf) — a person or an agent took the
    /// commission back with `withdraw` while its session was still writing, the session was asked
    /// to stop, and once nothing in the claim area is running any more its work is parked and the
    /// copy handed on. The one occasion that is somebody's DECISION rather than a clock or a
    /// death, and the one with no contention requirement: the round was taken back whether or not
    /// anybody is waiting for the copy, so the park happens either way, and a promotion is simply
    /// empty when nobody is.
    ///
    /// What it rests on is a device-local marker (`withdrawn_holders`,
    /// [`ChatStore::note_withdrawn_holder`]) written by [`withdraw`] and read by
    /// [`park_a_withdrawn_holder`] — and that marker is also what keeps every other release from
    /// handing the copy on unparked in the meantime; see [`release_working_tree_if_scope_is_done`].
    Withdrawn,
}

impl ParkOccasion {
    /// The occasion's name as `--json` spells it — the serde tag, `snake_case`. It is what a
    /// refused park is STAMPED with ([`ChatStore::note_park_refusal`]), so the row a tick clears is
    /// the row its own occasion wrote, and what `nxc status --json` then carries on
    /// `park_refused.occasion`. ONE spelling for both, for [`ParkRefusal::kind`]'s reason, held to
    /// the serde tag by `tests::every_occasion_names_itself_the_way_json_does`.
    pub fn as_str(&self) -> &'static str {
        match self {
            ParkOccasion::StrandedEscalation => "stranded_escalation",
            ParkOccasion::AvailabilityBoundary => "availability_boundary",
            ParkOccasion::PastItsBound => "past_its_bound",
            ParkOccasion::DiedInsideItsBound => "died_inside_its_bound",
            ParkOccasion::Withdrawn => "withdrawn",
        }
    }
}

/// **A hand-off the tick made that [`TickReceipt::parked`] does not describe** (nxf 6j6v.8bv9) — the
/// stranded escalation whose park was refused for good, every hand-off of an operation on hold at an
/// availability boundary, — since nxf 6j6v.xb24 — every hand-off of a holder that DIED inside its
/// bound, and — since nxf 6j6v.b9nf — every hand-off of a holder whose running round was WITHDRAWN.
///
/// Exactly one of [`parked`](Self::parked) and [`unparked`](Self::unparked) is set: the work went
/// onto a branch first, or it could not and the copy went on anyway. `#[non_exhaustive]` so a later
/// occasion's fact is an additive field.
///
/// **[`ParkOccasion::PastItsBound`] is the one occasion not reported here**, and that is the shape
/// rather than an omission: the sweep past the bound is a movement of its own on
/// [`TickReceipt::working_tree`], where its `expired` instant belongs, and [`WorkingTreeSweep`]
/// carries the same `parked`/`unparked` pair beside it. Its sibling
/// [`ParkOccasion::DiedInsideItsBound`] has NO such instant — the lease it took was still standing —
/// so it reports here, which is also why this type is written by two producers and
/// [`SweepStep`] says why they cannot collide.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
#[non_exhaustive]
pub struct HandedOn {
    /// The claim area that gave the working copy up — [`ParkedOperation::scope`]'s form.
    pub scope: String,
    /// Why it had to.
    pub occasion: ParkOccasion,
    /// Where its work is now, when it was parked before the copy moved.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parked: Option<crate::park::Parked>,
    /// **Why it was NOT parked** — a PERMANENT refusal ([`ParkRefusal::is_permanent`]), so the copy
    /// went on with the operation's uncommitted work still in the tree. The
    /// [`ConsequenceClass::WorkHandedOnUnparked`] finding in [`TickReceipt::warnings`] says the same
    /// in words.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub unparked: Option<ParkRefusal>,
    /// Who was waiting, and what happened to them — the same shape a release and a sweep report.
    #[serde(flatten)]
    pub promotions: Promotions,
}

/// **What one park attempt came to** (nxf 6j6v.8bv9) — the owner's refusal rule of 2026-09-17,
/// applied by [`park_and_hand_on`] for every occasion so no caller decides it twice.
pub(crate) enum ParkOutcome {
    /// The work is committed and recorded, the tree is back on its base, the copy went on.
    Parked {
        parked: crate::park::Parked,
        promotions: Promotions,
    },
    /// A permanent refusal: the copy went on WITHOUT parking; a `WorkHandedOnUnparked` finding is on
    /// `warnings`.
    HandedOnUnparked {
        refusal: ParkRefusal,
        promotions: Promotions,
    },
    /// A transient refusal: the claim stays, the refusal is recorded for `nxc status`, a
    /// `WorkNotParked` finding is on `warnings`, and a retry tick is armed.
    Held { refusal: ParkRefusal },
}

impl ParkOutcome {
    /// **The claim STAYED because the refusal can pass** — asked before the outcome is consumed,
    /// because the next step of the tick ([`sweep_expired_working_tree`]) must not attempt the same
    /// park again in the same breath. See [`ParkStep::held`].
    fn is_held(&self) -> bool {
        matches!(self, ParkOutcome::Held { .. })
    }

    /// The tick's account of this outcome, for an occasion that reports through
    /// [`TickReceipt::handed_on`] — `None` for a hold, which is a finding and not a hand-off.
    fn handed_on(self, scope: &str, occasion: ParkOccasion) -> Option<HandedOn> {
        let (parked, unparked, promotions) = match self {
            ParkOutcome::Parked { parked, promotions } => (Some(parked), None, promotions),
            ParkOutcome::HandedOnUnparked {
                refusal,
                promotions,
            } => (None, Some(refusal), promotions),
            ParkOutcome::Held { refusal } => {
                // The rule's other half, held to: only a refusal that can pass keeps the claim.
                debug_assert!(
                    !refusal.is_permanent(),
                    "a permanent refusal was held: {refusal:?}"
                );
                return None;
            }
        };
        Some(HandedOn {
            scope: scope.to_string(),
            occasion,
            parked,
            unparked,
            promotions,
        })
    }
}

/// **The one sentence every refusal after the commit opens with** — pulled out to its own pure
/// function so it can be unit-tested without driving the whole park (fix round 1 of nxf 6j6v.7hqc's
/// review).
///
/// **It must not say "committed" when nothing was** (`parked.committed == false`) — reachable
/// two ways: a detached HEAD that was clean when it was parked (a branch was still created, for
/// its position to stay reachable, but nothing was committed onto it), and, since `nxf 6j6v.7hqc`,
/// a clean tree already standing on the base branch (no branch created either). Both leave the
/// working copy exactly as safe as a committed park does — nothing is lost either way — but
/// claiming a commit that did not happen is the kind of thing a person or an agent reading a
/// refusal takes literally.
fn park_safety_note(holder: &str, parked: &crate::park::Parked) -> String {
    if parked.committed {
        format!(
            "operation {holder}'s work IS SAFE — committed on branch {} at {}",
            parked.branch, parked.commit
        )
    } else {
        format!(
            "operation {holder} had nothing uncommitted — its working copy is safe at {} on {}",
            parked.commit, parked.branch
        )
    }
}

/// **Put an operation's work somewhere safe, then hand the working copy on — or apply the refusal
/// rule when it cannot** (nxf 6j6v.npy3 extracted the core from [`park_the_stranded_holder`]; nxf
/// 6j6v.8bv9 moved the rule into it).
///
/// Every occasion for a park shares this: they differ in WHEN they decide to park and in the
/// sentence that explains it — `why` — and in nothing else, which is why the decision stays with
/// each caller and the sequence and the rule live here. `hand_off` is how the copy leaves the
/// holder; `anchor` is the thread the findings name; `occasion` is which trouble is asking, and a
/// held refusal is STAMPED with it so the tick can tell a park still being retried from one whose
/// occasion has passed ([`ChatStore::note_park_refusal`]).
///
/// **The rule** (owner, 2026-09-17), and every refusal meets it exactly once, here:
///
/// - **Permanent** ([`ParkRefusal::is_permanent`]) — the copy is handed on WITHOUT committing
///   anything, a [`ConsequenceClass::WorkHandedOnUnparked`] finding says so (and says the
///   uncommitted work stays in the tree for the next holder), and the outcome is
///   [`ParkOutcome::HandedOnUnparked`]. Waiting would not change the answer, so a claim held for it
///   is a queue held for ever.
/// - **Transient** — the claim STAYS. The refusal is recorded ([`ChatStore::note_park_refusal`]) so
///   `nxc status` shows it on the holding operation, a [`ConsequenceClass::WorkNotParked`] finding
///   names what to fix and that the background service retries on every tick, and the retry is
///   armed ([`arm_the_park_retry`]). The outcome is [`ParkOutcome::Held`].
///
/// **THE ORDER OF THE FIRST THREE STEPS IS THE WHOLE OF THIS FUNCTION'S SAFETY** (independent review
/// of PR #435, Integrity #1 / Code Quality #1). Commit, then RECORD, then return the tree to its
/// base — and stop at the first one that fails.
///
/// The first cut committed and returned the tree in one call, and recorded afterwards. Every step of
/// that was reversible except the combination: a failed write left a clean tree standing on the
/// base, which the next tick could not tell from "never parked", so it minted a second and EMPTY
/// branch. Whichever row landed first then named the decoy, and the real commit sat on a ref nothing
/// pointed at.
///
/// Recording while the tree is still ON the branch removes that ambiguity instead of guarding
/// against it. Any failure below leaves a state the next attempt reads correctly: HEAD is not the
/// base, so `commit_onto_a_branch` reuses that same branch, re-derives the same commit, and
/// `record_parked_work` is idempotent on exactly that pair. That is also why those two failures are
/// TRANSIENT refusals ([`ParkRefusal::Git`]) — the work is already safe on the branch, and a retry
/// from exactly there is what the tick does next.
///
/// **What the eighth argument is**, so the growth is legible (the house form for an `#[allow]` here
/// — see `on_channel_complete`): `occasion`, which trouble is asking. It is not derivable from the
/// other seven — `why` is a sentence composed around the holder and its instants, and `hand_off` is
/// how the copy leaves, which two occasions can share — and it is not cosmetic: it is what a held
/// refusal is stamped with, and therefore what decides whose row a later tick may clear.
#[allow(clippy::too_many_arguments)]
fn park_and_hand_on(
    ctx: &Ctx,
    store: &mut ChatStore,
    holder: &str,
    hand_off: HandOff<'_>,
    why: &str,
    warnings: &mut Vec<FailedConsequence>,
    anchor: Option<&str>,
    occasion: ParkOccasion,
) -> Result<ParkOutcome> {
    let refusal = match attempt_the_park(ctx, store, holder, occasion)? {
        Ok(parked) => {
            let promotions = release_and_fire(ctx, store, hand_off, holder)?;
            forget_the_park_refusal(store, holder);
            return Ok(ParkOutcome::Parked { parked, promotions });
        }
        Err(refusal) => refusal,
    };
    if refusal.is_permanent() {
        let detail = format!(
            "{why} — and its work CANNOT be parked: {}. Waiting will not change that, so the working \
             copy is handed on WITHOUT parking: whatever this operation left uncommitted stays in \
             the tree, where the next holder will find it",
            refusal.detail()
        );
        eprintln!("warning: {detail}");
        warnings.push(FailedConsequence::work_handed_on_unparked(anchor, detail));
        let promotions = release_and_fire(ctx, store, hand_off, holder)?;
        forget_the_park_refusal(store, holder);
        return Ok(ParkOutcome::HandedOnUnparked {
            refusal,
            promotions,
        });
    }
    let mut detail = format!(
        "{why} — but its work is NOT being parked: {}. The working-tree claim stays where it is and \
         whatever is queued keeps waiting; the background service retries the park on every tick, \
         so once that is fixed the working copy goes on by itself",
        refusal.detail()
    );
    // Best-effort, and SAID when it fails: the claim is held either way, and what a lost row costs
    // is the `PARK REFUSED` line on `nxc status` — which this finding then has to stand in for.
    if let Err(e) = store.note_park_refusal(holder, &refusal, occasion, ctx.now) {
        detail.push_str(&format!(
            " (recording this refusal for `nxc status` failed: {e})"
        ));
    }
    eprintln!("warning: {detail}");
    warnings.push(FailedConsequence::work_not_parked(anchor, detail));
    if let Some(finding) = arm_the_park_retry(ctx, store) {
        warnings.push(finding);
    }
    Ok(ParkOutcome::Held { refusal })
}

/// **The park itself — every step up to the hand-off, and nothing of the rule.** `Ok(Err(_))` is a
/// refusal for [`park_and_hand_on`] to classify; `Err(_)` is the store failing underneath, which
/// is not a refusal and propagates.
///
/// The repository is asked about BEFORE the base, so a directory that is not a repository is
/// refused as exactly that rather than as the missing base that follows from it: the base is
/// recorded from a git read, and a directory git cannot read never had one.
fn attempt_the_park(
    ctx: &Ctx,
    store: &mut ChatStore,
    holder: &str,
    occasion: ParkOccasion,
) -> Result<std::result::Result<crate::park::Parked, ParkRefusal>> {
    let copy = match the_working_copy(ctx) {
        Ok(copy) => copy,
        Err(refusal) => return Ok(Err(refusal)),
    };
    if let Err(refusal) = copy.assert_repository() {
        return Ok(Err(refusal));
    }
    let Some(base) = store.operation_base(holder)? else {
        return Ok(Err(ParkRefusal::NoBaseRecorded(format!(
            "no base branch was ever recorded for operation {holder} — it never took the working \
             copy while one could be read — so there is nowhere to put the tree back to after a \
             park"
        ))));
    };
    let parked = match copy.commit_onto_a_branch(holder, ctx.now, &base, occasion) {
        Ok(parked) => parked,
        Err(refusal) => return Ok(Err(refusal)),
    };
    let safe = park_safety_note(holder, &parked);
    if let Err(e) = store.record_parked_work(holder, &parked, ctx.now) {
        return Ok(Err(ParkRefusal::Git(format!(
            "{safe} — but recording that against the operation failed ({e}), so the tree is left \
             standing on that branch. Nothing is lost and nothing has to be undone: the retry \
             starts from exactly here. Write the branch name down if you want to look yourself"
        ))));
    }
    if let Err(r) = copy.return_to_base(&base) {
        return Ok(Err(ParkRefusal::Git(format!(
            "{safe} and recorded — but the working copy could not be put back on its base ({}), and \
             the next operation would start in this one's files. Put it back by hand, or leave it \
             for the retry",
            r.detail()
        ))));
    }
    Ok(Ok(parked))
}

/// Forget `holder`'s refused park once the copy has moved on — best-effort with a breadcrumb, for
/// the reason the release underneath already did the same inside its own transaction
/// ([`ChatStore::note_park_refusal`] lists every place): this is the belt, that is the braces.
fn forget_the_park_refusal(store: &mut ChatStore, holder: &str) {
    if let Err(e) = store.clear_park_refusal(holder) {
        eprintln!("warning: could not clear operation {holder}'s refused park: {e}");
    }
}

/// **The occasion `occasion` no longer stands: forget the refusal IT wrote** (fix round 1 of nxf
/// 6j6v.8bv9) — the third way a row goes, beside a park that finally went through and a lease that
/// left its holder.
///
/// A refusal is recorded so `nxc status` can say a park is being RETRIED, and what makes that true
/// is not the refusal's own reason — a merge can sit half-finished for a week — but the trouble
/// that wants the working copy. The escalation is answered and the operation works on; the hold is
/// taken up, or its window falls due. Nothing attempts that park again, and a `PARK REFUSED` mark
/// left standing would send a person to look at an operation nobody is waiting on, while every
/// arming for that holder kept using the liveness cadence instead of its own bound.
///
/// **Only the CURRENT holder's row, and only when it is stamped with this occasion.** Both halves
/// are the narrowness this is worth having: another claim's row is not this tick's to judge, and
/// another occasion's retry is still running — dropping its row would reset the one instant it
/// keeps, and "retrying since" would restart every time a neighbouring occasion looked away.
///
/// Best-effort with a breadcrumb, like its neighbour: what a failure costs is a stale line on a
/// view, never the claim.
fn forget_a_refusal_of_this_occasion(store: &mut ChatStore, occasion: ParkOccasion) {
    let holder = match store.working_tree_lease_row() {
        Ok(Some((holder, _))) => holder,
        // No lease, no claim, and nothing a row could be about: the movement that took it cleared
        // the row in the same transaction.
        Ok(None) => return,
        Err(e) => {
            eprintln!("warning: could not read who holds the working copy: {e}");
            return;
        }
    };
    match store.park_refusal(&holder) {
        Ok(Some(note)) if note.occasion == occasion.as_str() => {
            forget_the_park_refusal(store, &holder)
        }
        Ok(_) => {}
        Err(e) => {
            eprintln!("warning: could not read operation {holder}'s refused park: {e}");
        }
    }
}

/// **Whether `holder`'s park is currently refused and being retried** — the fifth "no" of
/// [`the_queue_goes_before_a_newcomer`], which is its one caller (fix round 1 of nxf 6j6v.xb24: it
/// had three, and the other two were the flag [`drain_recheck_instant`] used to take. That function
/// no longer asks anybody, because the cadence a refused park comes back on is now a candidate on
/// every call — so this read is gone from both arming sites and what is left is the gate on the
/// acquire path).
///
/// An unreadable row answers `false` with a breadcrumb rather than propagating: what that costs is
/// that the newcomer attempts a park which meets the same refusal and re-stamps the row with its own
/// occasion — a duplicate finding and a restarted "retrying since" — and what refusing to decide
/// would cost is the commission. Never the claim either way.
fn park_is_refused(store: &ChatStore, holder: &str) -> bool {
    match store.park_refusal(holder) {
        Ok(note) => note.is_some(),
        Err(e) => {
            eprintln!("warning: could not read whether operation {holder}'s park was refused: {e}");
            false
        }
    }
}

/// **Arm the retry of a refused park** (nxf 6j6v.8bv9) — one tick for the commission at the head
/// of the queue, at the instant [`drain_recheck_instant`] names: at most a liveness re-check out,
/// sooner if the holder's own bound or the park deadline falls first.
///
/// Keyed on the queue head because that is the only key a working-tree tick has — the same key
/// [`acquire_or_queue`] and the sweep arm — and because arming REPLACES by key, all three have to
/// name the same instant for the same state or the last one to run silently wins. They do: all
/// three ask [`drain_recheck_instant`], with the same three facts and nothing of their own. Since
/// nxf 6j6v.xb24 that is literally all they pass — the refused park used to be a flag each caller
/// read a row to set, and the cadence it selected is now a candidate on every call.
///
/// Nobody waiting is not a failure: a copy nobody waits for is never handed on from the tick, so
/// there is nothing to come back for. A queue that cannot be read IS one, and is said.
fn arm_the_park_retry(ctx: &Ctx, store: &ChatStore) -> Option<FailedConsequence> {
    let head = match store.peek_working_tree_queue() {
        Ok(Some(head)) => head,
        Ok(None) => return None,
        Err(e) => {
            let detail = format!(
                "a park was refused and the queue behind it could not be read to arm the retry \
                 ({e}) — the next tick from anywhere retries it"
            );
            eprintln!("warning: {detail}");
            return Some(FailedConsequence::work_not_parked(None, detail));
        }
    };
    let when = (|| -> Result<String> {
        match store.working_tree_lease_row()? {
            Some((_, expires)) => drain_recheck_instant(
                ctx.now,
                &expires,
                store.working_tree_contended_since()?.as_deref(),
            ),
            None => session_liveness_recheck(ctx.now),
        }
    })();
    match when {
        Ok(when) => arm_the_lease_bound(ctx, store, &head, &when),
        Err(e) => unarmed_drain_finding(
            store,
            &head,
            &format!("its instant could not be resolved: {e}"),
        ),
    }
}

/// **Put a stranded escalation's work on a branch and hand the working copy on** — the whole of nxf
/// 6j6v.de9s, at the seam that decides it.
///
/// It runs at the front of every [`tick`], BEFORE [`sweep_expired_working_tree`], and the order is
/// load-bearing: both can hand the same working copy on, and only this one saves what is in it
/// first. Reversed, an operation whose declared window happened to be shorter than the park deadline
/// would have its checkout reclaimed with its uncommitted work still sitting in the tree — which is
/// what happens today and is the second half of what this item removes.
///
/// **When it acts**, and every clause is a decision this item was asked to make:
///
/// - **The lease is CONTENDED** ([`note_the_contention`]) — the holder handed its task back, owes
///   nothing, and somebody is waiting. Without a waiter there is no park; that is the counter-test
///   in this item's own Definition of Done.
/// - **The deadline has passed, OR the lease has run out.** The first is [`crate::park::PARK_AFTER`]
///   from the instant the contention began. The second is what makes the ordering above true rather
///   than merely usual: whichever clock reaches the hand-off first, the work is saved before the
///   copy moves.
/// - **Nothing in the holding area has a live process.** The same guard [`sessions_still_running`]
///   gates every hand-off in this module, and here it protects more than one: a `git checkout`
///   against a tree a live session is writing into is the corruption this whole epic exists to
///   prevent.
///
/// **A refused park is retried by this same function on every tick** (nxf 6j6v.8bv9), because none
/// of the clauses above is changed by a refusal: the contention memo keeps its first instant, the
/// deadline stays passed, and the claim stays with the holder. [`park_and_hand_on`] arms the next
/// look; this is what that look runs. **And it is this function that stops saying so**: when the
/// contention ends, the refusal it recorded is forgotten here
/// ([`forget_a_refusal_of_this_occasion`]), because from that tick on nobody is retrying it.
///
/// **What it does not cover, and who does since nxf 6j6v.8bv9.** A holder that died hard WITHOUT
/// escalating is not contended by this definition — nothing handed the task back — so this function
/// never looks at it. Its work is parked all the same, by the occasion that does watch for it:
/// [`sweep_expired_working_tree`], under [`ParkOccasion::PastItsBound`]. This paragraph used to say
/// the sweep hands such a checkout on with the work still in the tree "exactly as before", and it
/// does not any more.
///
/// `Ok(None)` is "this occasion does not stand"; `Ok(Some(_))` is "it did, and here is what the
/// tick reports" — which is nothing but the finding for a hold.
fn park_the_stranded_holder(
    ctx: &Ctx,
    store: &mut ChatStore,
    warnings: &mut Vec<FailedConsequence>,
) -> Result<Option<ParkStep>> {
    let Some(since) = note_the_contention(ctx, store)? else {
        // **The occasion is over** — the escalation was answered, or the queue drained — so a
        // refusal this occasion recorded is not being retried by anybody any more and goes with it
        // (fix round 1 of nxf 6j6v.8bv9). This is the ONLY clause of the ones below that means
        // that: every other one is a reason not to act NOW on a contention that still stands.
        forget_a_refusal_of_this_occasion(store, ParkOccasion::StrandedEscalation);
        return Ok(None);
    };
    // The ROW, not [`ChatStore::working_tree_holder`] — an expired lease reads as "free" there, and
    // an expired lease over a stranded escalation is precisely one of the two shapes this acts on.
    // Whether it has expired is asked separately, three lines down, because here the question is
    // only WHO holds it.
    let Some((holder, _)) = store.working_tree_lease_row()? else {
        return Ok(None);
    };
    let due = park_deadline(&since)?;
    let now = crate::working_tree::to_utc_rfc3339(ctx.now)?;
    let lease_ran_out = store.working_tree_holder(ctx.now)?.is_none();
    if now < due && !lease_ran_out {
        return Ok(None);
    }
    let Some(scope) = WorkScope::parse(&holder) else {
        return Ok(None); // the sweep is the one place that says this out loud
    };
    let claim_thread = store.work_scope_threads(&scope)?;
    let running = sessions_still_running(ctx, store, &claim_thread)?;
    if !running.is_empty() {
        // Not a finding: this is the guard working, and the sweep beside it already prints the
        // "past its bound and still writing" line for the same holder.
        return Ok(None);
    }
    // The claim ROOT, which is what the scope key names since nxf 6j6v.8y6t — not "some thread in
    // the area", which is what the subtree's first element happens to be and would move with the
    // walk's order.
    let anchor = match &scope {
        WorkScope::Thread(t) => Some(t.as_str()),
        WorkScope::Session(_) => None,
    };
    let why = format!(
        "operation {holder} has been holding this workspace's working copy since an unanswered \
         escalation and something else has been waiting since {since}"
    );
    let outcome = park_and_hand_on(
        ctx,
        store,
        &holder,
        HandOff::Released(&scope),
        &why,
        warnings,
        anchor,
        ParkOccasion::StrandedEscalation,
    )?;
    let held = outcome.is_held();
    Ok(Some(match outcome {
        ParkOutcome::Parked { parked, promotions } => ParkStep {
            parked: Some(ParkedOperation {
                scope: holder,
                contended_since: since,
                parked,
                promotions,
            }),
            handed_on: None,
            held,
        },
        other => ParkStep {
            parked: None,
            handed_on: other.handed_on(&holder, ParkOccasion::StrandedEscalation),
            held,
        },
    }))
}

/// **What the tick's park step reports** — [`TickReceipt::parked`] and [`TickReceipt::handed_on`],
/// at most one of them, and neither for a hold (whose report is its finding).
#[derive(Default)]
struct ParkStep {
    parked: Option<ParkedOperation>,
    handed_on: Option<HandedOn>,
    /// **An occasion acted and its park was REFUSED for a reason that can pass** (nxf 6j6v.8bv9):
    /// the claim stayed with the holder, a row is on record under that occasion's stamp, and the
    /// retry is armed. Not on the receipt — the `work_not_parked` finding is that — but
    /// [`sweep_expired_working_tree`] has to know: it is the one step after this that can attempt
    /// the SAME park in the same tick, and doing so would meet the same refusal and overwrite the
    /// stamp of the occasion that is actually retrying.
    held: bool,
}

/// **The tick's park step** — every occasion on which the working copy is taken from a holder that
/// is not going to give it back soon, in one place and in one order (nxf 6j6v.8bv9).
///
/// The stranded escalation first, then an operation on hold at an availability boundary, then —
/// since nxf 6j6v.b9nf — a holder whose running round was withdrawn. At most ONE acts per tick:
/// once an occasion stands, the copy has either moved or is held with a refusal the next tick
/// retries, and a second occasion asking about the same holder in the same breath would only
/// repeat the refusal. All three run before [`sweep_expired_working_tree`], for the reason
/// [`park_the_stranded_holder`] gives.
///
/// **An occasion that does NOT stand still has something to do here**: forget the refusal it left
/// behind ([`forget_a_refusal_of_this_occasion`]), which is why each occasion below decides that
/// for itself rather than this function deciding it for both. "No occasion acted this tick" is not
/// the same question — the second occasion is never even asked when the first one acts.
fn park_step(
    ctx: &Ctx,
    store: &mut ChatStore,
    warnings: &mut Vec<FailedConsequence>,
) -> Result<ParkStep> {
    if let Some(step) = park_the_stranded_holder(ctx, store, warnings)? {
        return Ok(step);
    }
    if let Some(step) = park_an_interrupted_holder(ctx, store, warnings)? {
        return Ok(step);
    }
    Ok(park_a_withdrawn_holder(ctx, store, warnings)?.unwrap_or_default())
}

/// **The withdrawn occasion, on the tick** (nxf 6j6v.b9nf) — the second half of [`withdraw`] on a
/// running round: the verb discharged the round and asked its sessions to stop, and this is what
/// parks the holder's work and hands the copy on once nothing in its claim area is running any
/// more.
///
/// **Why the park is here and not in the verb.** A stop is DELIVERED, not waited out
/// ([`Worker::stop_session`](crate::worker::Worker::stop_session) says why: the session's teardown
/// announces `nxc session ended`, a call back into the store the verb is holding), and a
/// `git checkout` under a process that is still writing is the collision this whole epic exists to
/// prevent. So the verb records the intent ([`ChatStore::note_withdrawn_holder`]) and arms a look
/// a liveness cadence out, and this runs at that look — and at every other tick, since the park
/// step rides them all.
///
/// **Three conditions**, cheapest first, and each is a reason to do nothing rather than a failure:
/// somebody holds the copy (the lease ROW, expired or not — an expired row with a marker is still
/// this occasion's before it is the sweep's); the holder is MARKED withdrawn; nothing in its claim
/// area has a live process ([`sessions_still_running`], the guard no park may be without). While a
/// process is still there the look is re-armed at the cadence ([`arm_a_look_at_the_withdrawn_holder`]),
/// because the tick that brought us here was one-shot and a withdrawal has no other clock.
///
/// **No contention requirement** — the one way this occasion differs from every other in
/// [`park_step`]: the round was TAKEN BACK, and a copy nobody has come back for is parked all the
/// same, because the work in it belongs to a round that is over. With nobody queued the hand-off's
/// promotions are simply empty and the lease row is gone. The refusal rule applies unchanged
/// ([`park_and_hand_on`]): a transient refusal keeps the claim and the marker and is retried; a
/// permanent one hands the copy on unparked, loudly, and the marker goes with the copy.
///
/// **The occasion ends ONE way: the copy goes on.** By this occasion's own park, or by any other
/// movement of the lease — each drops the marker inside its transaction (`working_tree`'s release
/// and both reclaims). Nothing else ends it, and in particular a session STARTING again in the
/// withdrawn claim does not (fix round 1 of this item's review reverted exactly that rule). The
/// case it was written for — the human's follow-up into the withdrawn thread arriving BEFORE the
/// tick parked — is safe under the literal rule: the resumed session works in the tree its work is
/// still in; at its normal end the guard in [`release_working_tree_if_scope_is_done`] holds the
/// copy; this occasion then parks it once nothing runs and hands on; and the next commission
/// restores the branch. What the reverted rule cost was the OTHER shape: the drop was keyed on the
/// claim root and ran for every session start there, so a nested shared session resumed alone —
/// no lease taken, nothing of its own in the tree — ended the withdrawal of the holder above it,
/// and that holder's normal end then handed the copy on with the coder's half-finished work in it,
/// with no warning and no parked row. A park that was not needed costs a branch; a release that
/// was not guarded costs the work.
///
/// `Ok(None)` is "this occasion does not stand, or not yet"; `Ok(Some(_))` is what the park came to.
fn park_a_withdrawn_holder(
    ctx: &Ctx,
    store: &mut ChatStore,
    warnings: &mut Vec<FailedConsequence>,
) -> Result<Option<ParkStep>> {
    let Some((holder, _)) = store.working_tree_lease_row()? else {
        return Ok(None);
    };
    let Some(marker) = store.withdrawn_holder(&holder)? else {
        // **The occasion does not stand**: this holder's round was never withdrawn. (A holder
        // whose round WAS withdrawn keeps its marker until the copy goes on — see this function's
        // doc — so this branch is not "withdrawn, then something else"; it is "not withdrawn".) A
        // `withdrawn`-stamped refusal can still be on record here, from a key that lost the copy
        // to another movement and whose retry nobody is running any more, and it goes — the same
        // discipline every other occasion in `park_step` keeps.
        forget_a_refusal_of_this_occasion(store, ParkOccasion::Withdrawn);
        return Ok(None);
    };
    let Some(scope) = WorkScope::parse(&holder) else {
        return Ok(None); // the sweep is the one place that says this out loud
    };
    // The claim ROOT, which is what the scope key names — the same anchor every other occasion puts
    // its findings on. Computed before the running check below so the wedged-session warning can
    // anchor on it too.
    let anchor = match &scope {
        WorkScope::Thread(t) => Some(t.as_str()),
        WorkScope::Session(_) => None,
    };
    let claim = store.work_scope_threads(&scope)?;
    let running = sessions_still_running(ctx, store, &claim)?;
    if !running.is_empty() {
        // Not a finding by itself: this is the guard working — the stop was delivered and the
        // process has not finished its teardown. Look again a cadence out.
        if let Some(finding) = arm_a_look_at_the_withdrawn_holder(ctx, store, &scope) {
            warnings.push(finding);
        }
        // **After several cadences it IS a finding — and, since nxf 6j6v.27b9, one further
        // SIGTERM** (the owner's decision of 2026-09-20; nxf 6j6v.b9nf's Integrity #2 fix only
        // named the session). See [`WITHDRAWN_SESSION_WEDGED_AFTER_CADENCES`] for why five and why
        // once, and [`the_one_further_stop`] for how.
        //
        // **Only a session this withdrawal STOPPED is either signalled or named**
        // ([`ChatStore::withdrawn_session`]). Everything else pinning the claim is somebody's
        // running work: a session a human's follow-up put back in motion, which lost its row when
        // its new process started, or one that started while the withdrawal ran. Naming those
        // "wedged" was a false alarm, and signalling them would stop work somebody had just asked
        // for.
        for session in &running {
            if let Some(further) = the_one_further_stop(ctx, store, &holder, session)? {
                warnings.push(warn_a_wedged_pinning_session(
                    ctx, anchor, &holder, session, &further,
                ));
            }
        }
        return Ok(None);
    }
    let why = format!(
        "operation {holder}'s running round was withdrawn by {} at {} and nothing in it is \
         running any more, so its work is being parked and this workspace's working copy handed on",
        marker.by, marker.withdrawn_at
    );
    let outcome = park_and_hand_on(
        ctx,
        store,
        &holder,
        HandOff::Released(&scope),
        &why,
        warnings,
        anchor,
        ParkOccasion::Withdrawn,
    )?;
    let held = outcome.is_held();
    if held {
        // The retry `park_and_hand_on` armed is keyed on the queue head, and this occasion may have
        // none: with nobody waiting, nothing would come back for a park refused for a reason that
        // can pass. So the holder's own look is armed beside it.
        if let Some(finding) = arm_a_look_at_the_withdrawn_holder(ctx, store, &scope) {
            warnings.push(finding);
        }
    }
    Ok(Some(ParkStep {
        parked: None,
        handed_on: outcome.handed_on(&holder, ParkOccasion::Withdrawn),
        held,
    }))
}

/// **Bring a parked operation back to its own files** — the return half, run at the moment the
/// operation has the working copy again.
///
/// It is called from [`trigger_role`] after the lease gate has said yes, which is the one place both
/// ways back converge: an answer that arrives while the copy is free acquires straight through, and
/// one that arrives while it is busy is queued and re-fired through the same function. Putting it
/// anywhere else would cover one of the two.
///
/// Returns the deterministic text ([`crate::park::resume_notice`]) to put in front of whatever the
/// session was going to be told, or `None` when this operation has nothing parked — which is every
/// trigger that ever existed before this item.
///
/// **The movement check runs BEFORE the checkout and its answer is carried, not re-asked.** Reading
/// the branch tips first is what makes the report the same whether or not the checkout succeeds; and
/// the checkout is allowed to fail without stopping anything, because a session that is told exactly
/// where its work is can act, while a trigger refused for a dirty tree simply leaves the answer
/// undelivered.
///
/// The row is stamped as resumed even when the checkout failed, deliberately: what the row records
/// is that somebody was TOLD about this park, and telling them twice about the same branch on the
/// next trigger would be noise, not safety. The branch is still in the table for a reader.
fn resume_parked_work(
    ctx: &Ctx,
    store: &mut ChatStore,
    scope: &WorkScope,
) -> Option<(i64, String)> {
    let key = scope.key();
    let rows = match store.parked_work(&key) {
        Ok(rows) => rows,
        Err(e) => {
            eprintln!("warning: could not read this operation's parked work: {e}");
            return None;
        }
    };
    // Newest first, and only the newest is resumed ONTO: an operation parked twice comes back to
    // the branch its last park left. The older rows stay in the table as history.
    let row = rows.into_iter().next()?;
    let copy = the_working_copy(ctx).ok()?;
    let movement = copy.movement(&row.parked);
    let restored = copy.restore(&row.parked.branch);
    if let Err(said) = &restored {
        eprintln!(
            "warning: operation {key} is resuming on parked branch {} and the working copy could \
             not be put back on it: {said}",
            row.parked.branch
        );
    }
    Some((
        row.id,
        crate::park::resume_notice(&row.parked, &restored, &movement),
    ))
}

/// Stamp a park as come back for — **after the spawn, and that is the whole meaning of the row**,
/// exactly as `note_spawn_declaration` a few lines below it argues for its own write.
///
/// What the stamp records is that somebody was TOLD about this park. A trigger that never reached a
/// worker told nobody, and stamping it before would spend the notice on a session that does not
/// exist: the next attempt would resume onto the same branch in silence, which is the one thing the
/// deterministic text exists to prevent.
///
/// It IS stamped when the checkout failed, deliberately — the session was still told, in a text that
/// says the tree is not on its branch and names the branch, which is exactly what it needs. And the
/// row stays in the table either way; `resumed_at` is a stamp, never a delete.
fn note_the_park_was_resumed(ctx: &Ctx, store: &mut ChatStore, id: i64) {
    if let Err(e) = store.mark_parked_work_resumed(id, ctx.now) {
        eprintln!("warning: could not mark parked work {id} as resumed: {e}");
    }
}

/// Fire one trigger that had been waiting for the working tree (nxf 6j6v.fe0f).
///
/// **The entry stores INPUTS, never a composed prompt** ([`QueuedTrigger`]'s own doc says why), so
/// everything derived is derived AGAIN here, against the catalogue and the store as they are NOW
/// rather than as they were when the entry was parked:
///
/// - **the role declaration**, re-resolved through [`Definitions::role`] — the whole reason a prompt
///   is not frozen at enqueue time. A role deleted from the catalogue in the meantime is a
///   `not_found` here, which the caller turns into a breadcrumb.
/// - **the real SDK session**, re-read: a queued RESUME has one, a queued summon does not, and
///   which it is belongs to the session map rather than to a copy taken earlier.
/// - **the obligation** ([`RoleSpawn::reply_thread`]) — the item this ticket was told to get right
///   (PR review of nxf 6j6v.303b, item (c)). Re-running [`coordinator_commission`]'s own condition
///   literally would be wrong: that condition is "nobody expects anybody here YET", and by now the
///   original call has already written the register. What must be reproduced is its RESULT, so the
///   question asked is the register's own — does this role still owe a reply in this thread? — via
///   [`facade::owes_reply`], the same predicate `reply --if-unanswered` discharges against. A
///   trigger fired from the queue therefore names exactly the obligation a caller could discharge,
///   and never one the register disagrees with.
///
/// **The depth is not re-derived, it is restored.** `record_trigger_depth` stamped the target's
/// depth before the entry was ever parked (deliberately — see [`trigger_role`]), so the fired
/// trigger has to land at exactly that number and not one past it: `hop` is `depth - 1` and
/// [`ChainMove::Deeper`] adds the one back. It still goes through [`check_depth_guard`], so a cap
/// lowered while the entry waited is honoured rather than bypassed.
///
/// It goes through [`trigger_role`] like any other trigger, which means it asks for the lease
/// exactly as it did the first time — but since nxf 6j6v.yd4w it is ORDINARILY asking for one it
/// already holds. The transaction that took this entry off the queue granted the lease to its claim
/// area in the same breath, so the acquire here is normally an INHERIT (same key), and that inherit
/// is also what replaces the backstop bound the grant wrote with the area's own derived one
/// ([`operation_lease_expiry`]). What that removes is the race this used to carry as the common
/// case: the copy was free between the release's commit and this line, so a newcomer arriving in
/// between won it outright and this entry was fired, refused, and queued again behind the chain it
/// had been ahead of.
///
/// **"Ordinarily" is doing real work in that sentence, and this function's RETURN VALUE is why it
/// can be said out loud** (independent review of PR #380, Integrity & Robustness #1). The grant
/// narrows the window to nothing for a rival that merely ASKS — no acquire can take an unexpired
/// lease — but it does not make the promoted area's hold unconditional between the commit and this
/// line. One thing can still move it, and it is not a race a clock decides:
///
/// - **A re-derived key that is not the one the entry was parked under.** The entry stores its
///   thread, and [`lease_claim_root`] resolves that thread's ROOT again here; a re-parenting in the
///   meantime makes this trigger a different claim area than the one the grant named
///   ([`inherits_the_held_claim`] documents that same shape from the acquire end).
///
/// **A second way used to exist, and closed with the verb that opened it** (nxf 6j6v.b9nf):
/// `nxc release --thread <t>` naming a thread inside the freshly granted area slipped through
/// [`sessions_still_running`] the same way — a claim area that has been granted the copy but not
/// yet fired has no session recorded as running in it (`record_session_thread` runs INSIDE
/// [`trigger_role`], after its own acquire), so that verb was not blocked and handed the copy on.
/// `nxc withdraw` cannot reopen it: the grant has already taken the entry off the queue by the time
/// nothing is running there, so a withdraw naming that thread finds nothing waiting and nothing
/// running, and is refused as `not_found` rather than stealing the copy.
///
/// The entry then loses its acquire and goes back on the queue with the place it had
/// already waited for — no corruption, no lost work, and the next release starts it. What must not
/// happen is that the caller be told a session is running for it, which is why the
/// [`TriggerAdmission`] is returned rather than discarded, and why [`Promotions`] has a
/// [`requeued`](Promotions::requeued) bucket at all.
///
/// **Every failure this returns happens BEFORE the trigger runs, and it has to stay that way**: the
/// only caller's breadcrumb says the entry "could not be started … nothing is running for it", which
/// is true of an early return and false of anything after [`trigger_role`]. Work that follows the
/// trigger is therefore best-effort with a breadcrumb of its own, never a `?`.
fn fire_queued_trigger(
    ctx: &Ctx,
    store: &mut ChatStore,
    entry: &QueuedTrigger,
) -> Result<TriggerAdmission> {
    // **Re-composed against the catalogue this entry's OWN operation is bound to** (nxf 6j6v.n92p).
    // The queue stores a trigger's INPUTS and never a composed prompt, precisely so the prompt is
    // built at release time rather than frozen at enqueue time — and that argument is unchanged.
    // What changes is which catalogue "release time" means: for an entry that belongs to a running
    // operation it is that operation's version, not whatever the folder says at the moment the lease
    // happens to come free. Without this, waiting in the queue would be the one way to slip an
    // edited declaration into a chain already under way, which is the whole hole this closes.
    //
    // An entry with no thread (`role_resume`'s session-scoped shape) belongs to no operation and
    // reads the folder, exactly as it always did.
    let frozen = match entry.thread.as_deref() {
        Some(thread) => operation_declarations(ctx, store, thread)?,
        None => None,
    };
    let ctx = &with_declarations(ctx, frozen.as_ref());
    let decl = ctx.defs.role(&entry.role)?.clone();
    let hop = CheckedHop(check_depth_guard(entry.depth.saturating_sub(1))?);
    let resume_real = store.resolve_real(&entry.session)?;
    let owes = facade::owes_reply(
        store,
        entry.thread.as_deref(),
        ctx.origin,
        &entry.role,
        ctx.now,
    )?;
    let admission = trigger_role(
        ctx,
        store,
        RoleSpawn {
            decl: &decl,
            internal_session: entry.session.clone(),
            resume_real,
            message: &entry.message,
            // **The release path** (nxf 6j6v.ntp9). The admission happened at whichever coordinator
            // parked this; what this site is, is the named place that lets a parked commission
            // through — which is why it re-reads the declaration and re-derives the obligation
            // instead of replaying a decision frozen at queue time.
            coordinator: Coordinator::Released,
            model_override: entry.model,
            hop,
            // Only a `Deeper` trigger is ever parked (an answer travelling back up a chain is never
            // queued), so this is the one it was.
            chain: ChainMove::Deeper,
            reply_thread: owes.then_some(entry.thread.as_deref()).flatten(),
            thread: entry.thread.as_deref(),
            priority: entry.priority,
            queued_since: entry.enqueued_at.as_deref(),
        },
    )?;
    // **A channel member's window starts when it actually STARTS** (nxf 6j6v.nf38). The clock is
    // armed at fan-out, when the requester begins waiting — but a trigger parked behind the working
    // tree has not run a single instruction, and it produces no transcript to reset its own clock
    // with. If the queue outlasts the window the member reads `stale`, `member_set_is_settled` says
    // the SET is settled, the channel consolidates WITHOUT it — and only then does this fire, so the
    // member works for an answer nobody will collect. Restarting here is the same shape as the
    // turn-two restart in `supervisor_hand_out_next_turn`: the member has just been put to work, so
    // its window runs from now. A no-op for every trigger that is not a channel member.
    //
    // **Best-effort, and that is what keeps the caller's breadcrumb true.** Everything above this
    // line fails BEFORE `trigger_role`, so the caller's "nothing is running for it" describes the
    // situation exactly. Propagating from here would make it a lie: the trigger ran two lines ago
    // and the member is working. So this breadcrumbs like its siblings (the transcript's own reset,
    // both scheduling sites) and returns `Ok` — the cost of a failure is this member's restart, not
    // the start it just got.
    if let Err(e) = store.reset_member_deadlines_of_session(&entry.session, ctx.now) {
        eprintln!(
            "warning: the trigger for session {} started, but restarting its channel timeout \
             failed: {e}; it may time out on the window it was given while it waited",
            entry.session
        );
    }
    Ok(admission)
}

/// **Whoever imposes the obligation grants the means** (nxf 6j6v.kffm) — the pairing rule, applied
/// at the one funnel every spawn passes through rather than at each call site.
///
/// A trigger that carries a [`reply_thread`](crate::worker::TriggerRequest::reply_thread) has
/// already written `expects_reply_from` on that thread, and
/// [`crate::role::compose_system_prompt`] has already told the session, in words that admit no
/// reading, that its turn may not end without an `nxc reply --thread <id>`. Nothing checked that it
/// could RUN one. A role that declares no `tools:` — the default, and what every role written before
/// the role runtime does — reached the sidecar with an empty auto-approval list, so its own
/// `nxc reply` was refused with "This command requires approval", and the teardown then settled the
/// debt in its name with a `sidecar:` failure. The expectation was discharged, the working copy was
/// handed on, and from the outside the round looked healthy.
///
/// **Here and not per call site.** The same defect was fixed once already, for the one spawn that
/// bypasses `trigger_role` (nxf 6j6v.04es granted the `summarize` synthesizer its `Bash`), and it
/// came straight back at the next spawn path — which is what says that repair sat at the wrong
/// height. This function sits under `trigger_role`'s literal, under the synthesizer's, and under
/// every one a later ticket adds, because all of them reach the worker through
/// [`trigger_and_bind`].
///
/// **Additive, never a replacement.** It appends to
/// [`RoleSpec::granted_tools`](crate::worker::RoleSpec::granted_tools) and does not touch what the
/// declaration says — see that field for why the two lists are separate, and for what the sidecar
/// does with each. A trigger that demands nothing grants nothing, so a role that owes nobody an
/// answer reads exactly as it did before this existed.
fn grant_the_means_for_the_obligation(req: &mut TriggerRequest) {
    if req.reply_thread.is_none() {
        return;
    }
    let tool = crate::role::REPLY_OBLIGATION_TOOL;
    if !req.role.granted_tools.iter().any(|t| t == tool) {
        req.role.granted_tools.push(tool.to_string());
    }
}

/// Hand `req` to the worker and bind whatever runtime session it hands back (nxf 6j6v.5x9j).
///
/// **The one place a [`TriggerOutcome`] is acted on**, so both spawn paths — every declared role via
/// [`trigger_role`], and the ephemeral synthesizer that deliberately bypasses it — treat a
/// worker-supplied session id identically. A remote runtime's OPAQUE id lands in the session map by
/// exactly the route the local sidecar's own in-session `nxc session bind` callback uses; nothing
/// here parses it or assumes any shape for it.
///
/// [`TriggerOutcome::Accepted`] binds nothing, and that is not a degraded case: it is what both
/// bundled workers answer, and what a remote host answers while its provisioning call is still in
/// flight — it completes the binding itself, later, through
/// [`crate::engine::Engine::bind_runtime_session`].
fn trigger_and_bind(
    ctx: &Ctx,
    store: &mut ChatStore,
    mut req: TriggerRequest,
) -> std::result::Result<(), TriggerError> {
    grant_the_means_for_the_obligation(&mut req);
    let internal_session = req.internal_session.clone();
    if let TriggerOutcome::Started { runtime_session } = ctx.worker.trigger(req)? {
        // **A failed bind AFTER a successful start is not a failed trigger** (PR #269 review, Code
        // Quality #5). This used to `?`, which reported "the session never started" about a session
        // that is running right now — and the callers act on that: a wake site records
        // `WakeSkipReason::TriggerFailed`, and a caller reading it may reasonably retry, minting a
        // SECOND real session on a runtime that is already paying for the first. Losing the binding
        // costs a later resume; inventing a phantom failure costs a duplicate session, which is
        // strictly worse and silent.
        //
        // So the trigger's own truth wins and the bookkeeping miss is a breadcrumb — the same call
        // this codebase already makes for `record_trigger_depth`, whose write rides along with every
        // trigger and likewise refuses to turn a bookkeeping miss into a failed spawn.
        if let Err(e) = store.bind_session(&internal_session, &runtime_session) {
            eprintln!(
                "warning: session {internal_session} was started as runtime session \
                 {runtime_session}, but binding the two failed ({e}); the session is RUNNING and \
                 cannot be resumed by id until it is bound"
            );
        }
    }
    Ok(())
}

// ---- identity helpers -------------------------------------------------------------------

impl Ctx<'_> {
    /// The caller's qualified chat identity, `origin/actor` — the space in which message `sender`,
    /// DM membership and `expects_reply_from` are all expressed.
    pub fn caller_handle(&self) -> String {
        format!("{}/{}", self.origin, self.actor)
    }

    /// Qualify a bare role handle into this workspace's chat-identity space.
    ///
    /// `pub(crate)` since nxf 6j6v.dq59: [`crate::surface`]'s 1:1 turn hand-back resolves the ROLE
    /// behind a return address and has to express it in the same space `expects_reply_from` does,
    /// and a second `format!` there is exactly how the two spaces would come to disagree.
    pub(crate) fn qualify(&self, bare: &str) -> String {
        format!("{}/{}", self.origin, bare)
    }
}

/// Split a chat identity into its bare role-handle half, discarding the `origin/` half — the
/// inverse of [`Ctx::qualify`]. A value with NO `/` at all is returned unchanged (already bare:
/// the shorthand `--expect <bare-handle>` case).
pub fn bare_handle_of(qualified_or_bare: &str) -> &str {
    qualified_or_bare
        .rsplit_once('/')
        .map_or(qualified_or_bare, |(_, bare)| bare)
}

/// The deterministic DM channel id (spec §3.2): `dm:` + the first 24 hex chars of
/// `sha256(sorted(a,b) joined by \x00)`. Both agents derive the SAME id with no rendezvous.
pub fn dm_channel_id(a: &str, b: &str) -> String {
    let mut pair = [a, b];
    pair.sort_unstable();
    let mut hasher = Sha256::new();
    hasher.update(pair[0].as_bytes());
    hasher.update([0u8]); // the \x00 separator
    hasher.update(pair[1].as_bytes());
    let hex = hasher
        .finalize()
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect::<String>();
    format!("dm:{}", &hex[..24])
}

/// Whether a channel id is a direct-message channel — i.e. one [`dm_channel_id`] minted.
///
/// **The property `reply`'s `is_quorum_thread` gate and [`crate::stream::settled`] both key on**
/// (review of nxf 6j6v.jepk, owner ruling 2026-08-12). Whether a thread is a quorum board is a
/// property of the CHANNEL it lives in, not of whether `expects_reply_from` happens to be
/// non-empty: `ask`/the declared-channel fan-out always open theirs on a non-DM (declared or raw
/// group) channel, and a DM thread is — by construction, `dm_channel_id` never mints anything
/// else — always the 1:1 conversation between exactly two handles, never a multi-party board, no
/// matter what its `expects_reply_from` register currently holds. Consolidating this into a
/// declared/typed property of the channel itself, instead of re-deriving it from the id's prefix
/// at every call site, is tracked separately (nxf 6j6v.hq71) — deliberately out of scope here.
pub(crate) fn is_dm_channel(channel_id: &str) -> bool {
    channel_id.starts_with("dm:")
}

/// A spawn-chain depth that has **passed the guard**, and the only thing [`trigger_role`] and the
/// completion-routing entry points accept as one (PR #267 review, Integrity & Robustness #1).
///
/// The guard used to be enforced by convention: `resolve_hop` at the top of each of the ~8 verbs,
/// and a bare `u32` threaded down from there. Nothing stopped a new call site — or any crate
/// depending on `nexus_chat` directly rather than through [`crate::engine::Engine`] — from handing
/// the spawning primitive a `0` it never checked, which is the very bypass nxf 6j6v.m48m closed one
/// layer up. A `u32` cannot say "this number was checked"; this type can, because its field is
/// private to this module and [`resolve_hop`] is the only public way to obtain one.
///
/// That is deliberately NOT true of [`check_depth_guard`], which stays a `u32 -> u32` cap check: a
/// constructor that took the caller's word for the depth would hand back exactly the certificate
/// this type exists to withhold.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CheckedHop(u32);

impl CheckedHop {
    /// The depth itself, for the two things that consume it: the `NXC_HOP` stamp
    /// ([`trigger_env`]) and the depth persisted against the spawned session — both resolved
    /// through [`ChainMove::depth_for`], never read apart.
    pub fn get(self) -> u32 {
        self.0
    }
}

/// The depth guard (spec §5.3): reject a hop past [`MAX_HOP`] before doing any work, so a spawn
/// chain — including two roles that only ever push work at each other — cannot loop forever.
/// Returns the CURRENT hop on success; callers thread it into [`RoleSpawn::hop`], where
/// [`ChainMove`] decides what it means for the depth the target lands at.
///
/// The bare cap check over an already-resolved depth, and deliberately still `u32 -> u32`: see
/// [`CheckedHop`] for why this one may not mint one. Verbs call [`resolve_hop`], which is where the
/// depth comes FROM; this stays separate so the cap and its wording live in exactly one place.
pub fn check_depth_guard(hop: u32) -> Result<u32> {
    if hop > MAX_HOP {
        return Err(NxfError::validation(format!(
            "role-runtime depth guard: hop {hop} exceeds the cap of {MAX_HOP}"
        )));
    }
    Ok(hop)
}

/// This call's effective spawn-chain depth, guarded (nxf 6j6v.m48m) — what every verb that can end
/// up spawning something runs before doing any work.
///
/// **The depth is read back from the store, not taken from the caller.** `ctx.hop` is what the
/// CALLER says its depth is: `NXC_HOP` on the CLI seam and, until nxf 6j6v.07me, a `hop` field on
/// the library seam's [`Caller`] too. Both are ambient state the calling process fully controls, and
/// every COMMISSIONED role can run a shell command — the shipped example's roles declare
/// `tools: [Bash]`, and since nxf 6j6v.kffm a role that declares nothing is GRANTED it, because it
/// is ordered to answer with `nxc reply` — so `unset NXC_HOP` (or, through the handle, passing `0`
/// every time) reset the counter on every hop and defeated the circuit breaker outright. Since each
/// hop is a real detached process plus a paid LLM call, that is a cost brake, not a formality.
///
/// So the authoritative value is [`ChatStore::session_depth`] of the caller's OWN session — written
/// by whoever spawned that session ([`trigger_role`]), before it ever ran. The claimed `ctx.hop` is
/// kept as a FLOOR (`max`, not a replacement): it may raise the depth, never lower it. That keeps
/// the field meaningful for a host driving a chain of its own — an app that tracks the hop count
/// itself still gets its value honoured — while making it useless as a way down.
///
/// **The library seam stopped claiming one at all** (6j6v.07me). `Caller::into_ctx` passes `0`, and
/// the paragraph above is why that costs nothing: the floor was only ever able to raise the depth,
/// and a host driving a chain drives it through SESSIONS, whose depths are in the map already. The
/// CLI still claims, because a spawned `nxc` process is handed `NXC_HOP` and has no other way to say
/// what it was told.
///
/// **What this does not close, stated plainly.** A caller that presents no session at all resolves
/// to its claimed hop, because a genuine human-at-the-terminal kickoff is exactly that shape. A role
/// determined to escape can therefore still discard its whole ambient identity (`NXC_SESSION`
/// included) and look like a fresh chain — at the price of everything that identity buys it: no
/// return address on its posts, no resume, no ambient session for anything to be attributed to.
/// Closing that last gap needs an unforgeable credential handed to the spawned process rather than
/// an environment variable, which is the access-control design (nxf 6j6v.6aza), not this guard.
/// The [`CheckedHop`] it returns is the certificate the spawning primitives demand, so "did anyone
/// run the guard" is a compile-time question rather than a review question.
pub fn resolve_hop(ctx: &Ctx, store: &ChatStore) -> Result<CheckedHop> {
    let persisted = match ctx.session {
        // An id that names no session of ours — a human's hand-set `NXC_SESSION`, a session from
        // another workspace — is `None` and contributes nothing, exactly like having no session.
        Some(session) => store.session_depth(session)?.unwrap_or(0),
        None => 0,
    };
    check_depth_guard(persisted.max(ctx.hop)).map(CheckedHop)
}

/// Idempotently materialise the deterministic DM between two DISTINCT handles (spec §3.2).
///
/// Calling it twice for the same pair is a true no-op the second time and returns the SAME id:
/// `set_channel_field` is LWW-idempotent, but `add_member`'s OR-set is NOT — a repeat add for a
/// handle already present mints a brand-new add-tag (each add is its own observed-remove instance,
/// by design), which would inflate the live-tag member count past 2 on every re-open and mislabel
/// the DM `degraded`. Every channel-less role trigger runs this, unlike the explicit `channels dm`
/// verb a caller runs once, so the `is_member` guard is required rather than cosmetic.
///
/// Takes `origin`/`actor` rather than a whole [`Ctx`] so the `nxc channels dm` verb — which opens a
/// DM and triggers nobody — can share it without constructing a worker and a declaration catalogue
/// it has no use for.
pub fn ensure_dm_channel(
    store: &mut ChatStore,
    origin: &str,
    actor: &str,
    a: &str,
    b: &str,
) -> Result<String> {
    if a == b {
        return Err(NxfError::validation("a DM needs two DISTINCT handles"));
    }
    // Both handles become membership ids — reject a SEP byte as `validation` (Integrity #1)
    // rather than let `add_member`'s own assert panic the process.
    facade::check_no_sep("handle", a)?;
    facade::check_no_sep("handle", b)?;
    let author = format!("{origin}/{actor}");
    let cid = dm_channel_id(a, b);
    store.set_channel_field(&cid, "kind", CHANNEL_KIND_DIRECT, &author);
    store.set_channel_field(&cid, "origin", origin, &author);
    for handle in [a, b] {
        if !store.is_member(&cid, handle)? {
            store.add_member(&cid, handle, &author);
        }
    }
    Ok(cid)
}

/// Idempotently materialise the substrate channel backing a DECLARED channel: a stable
/// `decl:<name>` id (a channel name is already a single stable string, so unlike a DM's handle pair
/// it needs no hashing), then join every declared member PLUS the caller's own qualified identity.
///
/// The caller's own join is not incidental: `thread_board`'s read path gates EVERY reader on
/// substrate membership, including the opener, and a declared channel's `members:` often does not
/// include the requester (a `pm` opening a review channel it is not itself a member of). Without
/// it, the caller who just opened the board would get `forbidden` reading it back.
fn ensure_declared_channel(
    ctx: &Ctx,
    store: &mut ChatStore,
    channel: &ChannelDecl,
) -> Result<String> {
    facade::check_no_sep("channel name", &channel.name)?;
    let author = ctx.caller_handle();
    let cid = format!("{DECLARED_CHANNEL_PREFIX}{}", channel.name);
    // The DECLARED kind, not a hardcoded one (nxf 6j6v.bd6g): a channel declared `kind: public`
    // materializes as the project's front door, which is what lets a cross-project directory select
    // by type instead of by an agreed-upon name. Absent in a declaration ⇒ `group`, exactly what
    // every `channels.yaml` written before the field meant.
    store.set_channel_field(&cid, "kind", channel.kind.as_str(), &author);
    store.set_channel_field(&cid, "origin", ctx.origin, &author);
    store.set_channel_field(&cid, "name", &channel.name, &author);
    // The CAST, not `members` alone (nxf 6j6v.g0yn) — a step target belongs to the channel it is
    // commissioned into, and joining only the member list left it outside the room it works in.
    let cast = crate::channel::cast(channel);
    for handle in cast
        .iter()
        .map(String::as_str)
        .chain(std::iter::once(author.as_str()))
    {
        if !store.is_member(&cid, handle)? {
            store.add_member(&cid, handle, &author);
        }
    }
    Ok(cid)
}

/// Stamp the ambient caller session into `refs.session_id` when the caller set none — the return
/// address a triggered role's eventual reply routes back through. Only when a REAL session exists:
/// a bare-terminal kickoff leaves it unset rather than reusing a placeholder that could later be
/// mistaken for a genuine identity.
fn with_return_address(ctx: &Ctx, mut refs: Refs) -> Refs {
    if refs.session_id.is_none() {
        if let Some(s) = ctx.session {
            refs.session_id = Some(s.to_string());
        }
    }
    refs
}

/// **Stamp where the working copy stood into `refs.working_copy`** (nxf 6j6v.2af2) — the second
/// thing this engine decides for itself about a message it is posting, beside
/// [`with_return_address`] above.
///
/// # WHERE this is called, as a CRITERION rather than a list
///
/// > **A message is stamped when posting it PUTS A SESSION IN MOTION or ANSWERS a turn.**
///
/// The criterion is the durable form and the list below is only its current answer — because a list
/// is what failed here (independent review of PR #474, Code Quality #1). This doc used to say the
/// sites were [`with_return_address`]'s, "which is not a coincidence: a message that needs a return
/// address is exactly a message that hands something over". That reading missed
/// [`supervisor_hand_out_next_turn`], where the SUPERVISOR — which is not a session and so has no
/// return address — forwards a live member its next turn. And the miss was worse than an absence:
/// [`ChatStore::working_copy_anchors`] reports the newest ANCHORED message per thread, so a member
/// on its second turn went on showing turn one's anchor as though it were the state it had just
/// been handed.
///
/// What the criterion answers today:
///
/// | site | why it qualifies |
/// | --- | --- |
/// | [`coordinator_commission_in`] | starts a persona's session — and a channel's flow step reaches it, so a fan-out member and a later step each carry the state THEY were handed |
/// | [`open_declared_channel_and_fan_out`] | opens the round the members are started for |
/// | [`role_resume`] | continues a session with new input |
/// | [`reply`] | answers a turn, and resumes whoever is on the other side |
/// | [`supervisor_hand_out_next_turn`] | hands a live member its second and later turn |
/// | the consolidation's delivery (in [`on_channel_complete`]) | discharges the channel thread and wakes the requester with the round's answer |
///
/// And what it excludes, so the exclusions are decisions rather than omissions: the note that says
/// an acceptance did NOT take effect (nothing is started — it explains a refusal), and `withdraw`'s
/// two notices (work is taken BACK; the anchor of the commission being withdrawn is already on the
/// thread). Every other `post_message` in this crate is inside `#[cfg(test)]`.
///
/// **One anchor read per message, and a fan-out pays it per member.** A channel opening for five
/// members takes five reads — which is what makes each member's commission name the tree IT was
/// given, and which is nothing beside the five sessions that opening starts.
///
/// **It never fails the call and it never warns.** The anchor is a fact ABOUT the handover, never a
/// precondition FOR it, so a host that names no working copy, a directory git does not know and a
/// git read that broke all post the same message with no anchor on it. Which of those it was, and
/// what stands in the place of a per-message warning, is [`crate::anchor`]'s own module doc.
///
/// **A caller cannot set it, and there is no request field that carries it** — the rule
/// [`Refs::substituted`] established for the one other engine-decided pointer. Anything a caller
/// put there is overwritten, because a claim about the tree that the tree was not asked about is
/// worse than no claim.
fn with_working_copy(ctx: &Ctx, mut refs: Refs) -> Refs {
    refs.working_copy = crate::anchor::anchor_for(ctx.worker).ok();
    refs
}

// `with_run_refs` stood here. REMOVED with the run record (6j6v.dvyq §3), and it is the one place
// in this cut where a real CAPABILITY goes rather than a second door: a message posted from inside
// a run carried that run's commissioned ticket set on `refs.nxf_ids` automatically, so "which
// ticket is this message about?" was a lookup rather than a judgement. With no run there is no
// commissioned set to stamp, and `with_return_address` — which every one of its call sites now
// uses directly — carries the return address alone. A caller that wants the reference says so:
// `--ref nxf_ids=<id>`, which always won over the stamp anyway.

// ---- the persona COORDINATOR (nxf 6j6v.ntp9), and role_resume ------------------------------
//
// **A message never reaches a role. It reaches a coordinator, and the coordinator decides what
// happens.** For a declared CHANNEL that has been true since nxf 6j6v.pf6j: `send --to <channel>`
// opens the channel thread and hands over at `supervisor_fan_out`, in that function's own words,
// "the supervisor takes it from here". For a declared PERSONA it was not true — `send --to
// <persona>` materialised a conversation, opened a thread and called [`trigger_role`], with the
// decisions spread over the SURFACE and the spawn primitive and nobody named in between. Both of
// the proving ground's worst findings arose exactly there (`6j6v.10yb`, `6j6v.ma7v`): a correctly
// built persona followed a correctly written instruction and the damage happened anyway, because
// what must happen deterministically was in the prompt instead of in the structure.
//
// [`coordinator_commission`] is that place for the persona path. It is the ONE entrance a task
// addressed to one role passes through, and everything the ticket lists as a coordinator's business
// is decided in it or in the [`trigger_role`] it hands to: take the message in, materialise the
// conversation, OPEN THE THREAD AND RETURN ITS ID, register the obligation, mint and hold the
// session id, choose the model, compose the system prompt, grant the tools, hand over the task.
//
// ---- DECISION: a persona commission is NOT a one-step channel (nxf 6j6v.ntp9) -----------------
//
// The item left this open — unify (every commission becomes a channel operation) or give the direct
// path its own leaner coordinator. It is the second, for four reasons, in the order they weigh:
//
//  1. **A one-step channel inserts a PARTY, not just a place.** The supervisor is a real identity:
//     it opens member threads, it is what the channel thread `expects`, and a member's answer is
//     addressed to IT. Making a 1:1 a channel therefore puts two thread levels under every direct
//     conversation and makes the persona's answer the supervisor's to consolidate and forward.
//     `nxc reply --thread <id>` answering the party that asked is what a direct conversation IS.
//  2. **The supervisor's machinery is about a SET** — the declared order (`flow:`), the settling
//     (`member_set_is_settled`), the consolidation (`on_complete`). A commission to one persona has
//     no set. Running all of it at N=1 would not unify anything; it would give each of those
//     decisions a second, degenerate meaning nobody declared.
//  3. **A channel needs a DECLARATION to exist at all** (`decl:<name>`, minted only by
//     `ensure_declared_channel`), so the direct path would have to synthesise one nobody wrote —
//     in a module whose branch (3) of [`crate::surface::send_to`] refuses an undeclared channel BY
//     NAME, on the argument that something addressable with no declaration behind it has no policy
//     to route by.
//  4. **What must be inherited has to live BELOW the surface** (nxf 41j0.vhsk). A host that
//     installs its own `WorkerConfig::Custom` inherits engine verbs, not declaration catalogues and
//     not `nxc`'s branches. A coordinator that is a channel declaration would be a workspace
//     artefact; a coordinator that is a verb on the trigger path is inherited by every seam.
//
// The cost of the decision, named rather than left to be discovered: the two coordinators are two
// functions, so a rule that must hold for BOTH has to be written where both reach it —
// [`trigger_role`], the funnel they share — and not in either one of them. That is where the depth
// guard, the working-tree lease and [`crate::worker::TurnTerms`] already live, and it is why
// [`crate::worker::Coordinator`] is a field on the request rather than a fact about the call stack.

/// Hand a role a NEW task: post the message, mint a pending session, trigger the role.
///
/// Named `RoleTriggerRequest` until nxf 6j6v.ntp9, when the entrance it belongs to became
/// [`coordinator_commission`] — the coordinator receives a COMMISSION, and the type says so.
#[derive(Debug, Clone)]
pub struct Commission<'a> {
    /// The bare handle of the role to summon.
    pub role: &'a str,
    pub body: &'a str,
    /// The channel to post to. `None` auto-opens/reuses the deterministic DM between the caller and
    /// the role — never make the caller open one first.
    pub channel: Option<&'a str>,
    pub kind: MessageKind,
    pub priority: Priority,
    pub disposition: Disposition,
    /// The thread this commission runs in. **`None` means the coordinator opens one** (nxf
    /// 6j6v.ntp9) — hung under wherever the caller is standing ([`ambient_parent`]), exactly as
    /// `crate::surface::send_to` used to open it one call further out.
    ///
    /// That is not a convenience. A commission with no thread posts no thread, so it declares no
    /// `expects_reply_from`, tells the persona nothing to answer into, and leaves the sidecar's
    /// teardown net with no obligation to settle — a role summoned with nothing to answer into and
    /// nobody expecting it, which is nxf 6j6v.rp8k's shape. It could not arise from `nxc send`
    /// only because the CLI surface happened to open a thread first, and "true on the CLI path" is
    /// precisely the property nxf 41j0.vhsk says will not hold for an embedding host. The
    /// coordinator owns it instead, so there is no caller left that can omit it.
    ///
    /// `Some` is for a caller that has ALREADY opened the thread and needs its id before the
    /// commission — the channel supervisor, whose member thread must hang under the channel thread
    /// and carry the board's deadline before the member is started ([`open_flow_step`]).
    pub thread: Option<&'a str>,
    pub refs: Refs,
    /// Per-call model override, beating both the step and the role's own declaration.
    pub model: Option<Model>,
    /// **Continue an EXISTING session instead of minting one** (nxf 6j6v.y1t9) — everything else
    /// about this commission is unchanged: the message is posted, the obligation is declared on the
    /// thread, and the role is started. What differs is that the party woken is the one that
    /// already worked here, with its own transcript behind it, rather than a stranger holding a
    /// notice about work it never did.
    ///
    /// `None` — every caller but the stepped channel's advance — mints a fresh session exactly as
    /// before.
    pub continue_session: Option<ContinuedSession>,
    /// **The machine chosen for this chat** (nxf 6j6v.1c6k) — see
    /// [`crate::surface::SendToRequest::machine`]. Read only by the persona coordinator opening a
    /// fresh chat; every other entrance passes `None`.
    pub machine: Option<&'a str>,
}

/// **A session a [`Commission`] is to CONTINUE rather than mint** (nxf 6j6v.y1t9) — the pair
/// [`crate::store::SessionRow`] already holds, carried together because using one without the other
/// is the mistake: the internal id alone starts the SDK from nothing under a name that has a
/// transcript, and the real id alone names a transcript nxc cannot account for.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ContinuedSession {
    /// The nxc-minted id — the identity the session map, the thread position, the depth budget and
    /// the liveness question all key on.
    pub internal: String,
    /// The runtime's own id, when a worker has handed one back. `None` is a session that was minted
    /// and never bound (a worker that reports `Accepted` rather than `Started`, which every dry run
    /// does), and it continues on the internal id alone — the same terms
    /// [`supervisor_resume_member`] has always resumed on.
    pub real: Option<String>,
}

// A `wake: Option<&str>` field stood here for one round of nxf 6j6v.ntp9 — an override for a
// caller
// with its own wording. **REMOVED before it ever shipped** (independent review of PR #378, Code
// Quality #3 / Test Quality #6): every construction site in the crate passed `None`, so what
// remained was a speculative branch with a trap in it — a `Some` caller would get NO thread-naming
// line appended, which is exactly the drift [`wake_message`] was centralised to prevent. The
// wordings the field anticipated (a hand-back, a completed quorum) travel through
// [`resume_return_address`] and [`wake_role_requester`], neither of which builds a [`Commission`] at
// all. It goes back in when a caller exists, with that caller's test.

/// Continue an EXISTING role session: post the message, resume that session.
#[derive(Debug, Clone)]
pub struct RoleResumeRequest<'a> {
    /// The internal session id to resume.
    pub session: &'a str,
    pub body: &'a str,
    pub channel: Option<&'a str>,
    pub kind: MessageKind,
    pub priority: Priority,
    pub disposition: Disposition,
    pub thread: Option<&'a str>,
    pub refs: Refs,
    pub model: Option<Model>,
}

/// What a summon/resume produced. Declared field order = the JSON contract.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct TriggerReceipt {
    pub message_id: String,
    /// **The thread this commission runs in** (nxf 6j6v.ntp9) — the one the caller handed in, or the
    /// one the coordinator opened for it. Never empty on a COMMISSION: a task addressed to a role
    /// always lands in a thread, which is what [`Commission::thread`] is about.
    ///
    /// It is here so a caller that did NOT open the thread can still address what it just started —
    /// `crate::surface::send_to` returns exactly this as its `thread_id`, and could only do so
    /// before because it had opened the thread itself, one call further out.
    ///
    /// EMPTY on exactly one path, and that path is not a commission: [`role_resume`], which pushes
    /// into whatever thread its caller named and deliberately keeps having none when its caller
    /// names none. See the field's own site there.
    ///
    /// **Omitted from the JSON when empty** (independent review of PR #378, Integrity #8): "empty
    /// reads as absent" is a convention this module uses internally, and a convention is not
    /// something to hand a `--json` reader: `"thread": ""` is a string a consumer treats as an
    /// id. An absent key is the one shape that cannot be misread, and it is what every other
    /// sometimes-absent field on this receipt already does.
    #[serde(skip_serializing_if = "String::is_empty")]
    pub thread: String,
    /// The internal session id the role runs under — freshly minted for a trigger, the resumed one
    /// for a resume.
    ///
    /// **Minted is not running**: when [`queue_position`](TriggerReceipt::queue_position) is set,
    /// this session exists and is what the queued entry will be fired against later, but nothing has
    /// started on it yet.
    pub session: String,
    /// The channel the message was posted to (the auto-opened DM, when none was given).
    pub channel: String,
    /// The `scope_key` of the chain currently holding the working tree, when this trigger had to
    /// wait for it (nxf 6j6v.303b). `None` on every trigger that ran — which is every trigger a
    /// `shared` role or channel ever makes.
    ///
    /// May also be `None` on a trigger that DID get queued; see
    /// [`TriggerAdmission::Queued`]'s `behind` for the narrow race that produces that, and key "was
    /// this queued?" on [`queue_position`](TriggerReceipt::queue_position) instead.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub queued_behind: Option<String>,
    /// This trigger's 1-based position in the working-tree queue, when it had to wait. `Some` iff
    /// **nothing was spawned**: the message is posted and the session is minted, but the role starts
    /// only once the holder releases (nxf 6j6v.fe0f).
    ///
    /// Both fields are ADDITIVE and skipped when absent, so an existing `--json` reader sees a
    /// byte-identical receipt for every trigger that behaves as it did before this ticket.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub queue_position: Option<i64>,
    /// **The typed discriminator for the three outcomes a trigger can have** (nxf 6j6v.hpv8, PR
    /// review, Important #4): `true` iff the worker actually got handed this trigger
    /// ([`TriggerAdmission::Spawned`]). The other two outcomes are `false`, and are told apart by
    /// the field that already existed for each: [`queue_position`](TriggerReceipt::queue_position)
    /// `Some` means queued behind the working-tree lease (nxf 6j6v.303b, nothing wrong, just
    /// waiting); [`warnings`](TriggerReceipt::warnings) non-empty means the spawn was attempted and
    /// failed. Never omitted — a bare `bool` can't sensibly be "additive", and a caller checking
    /// only `!warnings.is_empty()` (string-vec emptiness as control flow, which this field exists
    /// to replace as the primary signal) would misread a legitimately empty `warnings` on a
    /// `role_resume` trigger that still propagates `Err` the old way (this ticket's scope stops at
    /// `coordinator_commission`'s two callers, see that function's doc) as "it spawned", when the
    /// call
    /// never returned at all.
    pub spawned: bool,
    /// **The machine this chat was handed to instead of started here** (nxf 6j6v.1c6k) — `Some`
    /// exactly when the chat's designated machine is another one: nothing was started on this
    /// machine, and that one picks the order up after its next pull. Skipped when absent, so every
    /// receipt of a chat that runs where it was written is byte-identical to before.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub handed_to: Option<crate::machine::ExecutingMachine>,
    /// Best-effort steps that did NOT happen even though the message above is durably posted (nxf
    /// 6j6v.hpv8). Today this carries exactly one thing: [`coordinator_commission`]'s own summon
    /// failing
    /// AFTER the message, the thread's `expects_reply_from` and the pending session were already
    /// written — the caller used to get a bare `Err` there, which discarded all three and left "the
    /// message is durably in the channel and nobody is working on it" indistinguishable from
    /// "nothing happened at all". The receipt is returned instead, with the failure named here.
    ///
    /// **ALWAYS present, never `#[serde(skip_serializing_if)]`, empty on every trigger that spawned
    /// cleanly.** A field that appears only on failure forces every reader into a case distinction,
    /// and a reader who forgets to make it never sees the failure — precisely the class this closes.
    /// This is the shape 6j6v.r6pf (`sync bind`, still open) is told to follow rather than nulling
    /// the field it touches: additive, always-present, and a `Vec` so more than one best-effort step
    /// can report into the same receipt without a new named field per step. Since [`spawned`](
    /// TriggerReceipt::spawned) is what a caller now branches on, this field's job is narrower than
    /// it was before that field existed: human-readable DETAIL, not the yes/no signal itself.
    ///
    /// **The two seams express "receipt AND failure" differently, deliberately** (see this field's
    /// call site in `coordinator_commission` for the mechanics). `nxc`'s `--json` renders `spawned`
    /// and
    /// `warnings` alongside `message_id` exactly as any other field AND still exits non-zero — the
    /// JSON body carries what happened, the exit code is what a script that never parses JSON still
    /// notices. [`send_to`](crate::engine::Engine::send_to) — since nxf 6j6v.dvyq §3 the one seam
    /// method that reaches this — has no exit code to set, so its half of the contract is this: the
    /// call returns `Ok`, never
    /// `Err`, for this specific class of failure, and `spawned: false` is the ONLY place that
    /// survives — which is not "quietly" turning the error into a success, because the field cannot
    /// be omitted or overlooked the way a bare `eprintln!` breadcrumb could be. A caller that wants
    /// the CLI's loud behaviour reproduces it with one line: `if !receipt.spawned { /* failed or
    /// queued */ }`.
    ///
    /// **It used to carry only TEXT, and that was nxf 6j6v.6m6x** — filed because the `Err` this
    /// replaces carried an `ErrorKind` that a formatted string cannot give back. For the DISABLED
    /// worker that was no real loss (a host knows whether it passed one to `Engine::open_with`); for
    /// a genuine spawn failure it was, because a `Custom` worker returning `Err` and a `SidecarWorker`
    /// whose start failed became indistinguishable from every other cause — and the runtime already
    /// tells one of them apart on purpose ([`crate::worker::TriggerError::SessionGone`], because a
    /// vanished session needs a fresh one rather than a retry).
    ///
    /// It carries [`FailedConsequence`] since nxf 6j6v.93zd, which is where that distinction comes
    /// back: [`FailedConsequence::reason`] is the same [`WakeSkipReason`] the wake sites publish,
    /// classified by the same [`wake_skip_reason`], so a caller branches on a value instead of
    /// pattern-matching prose. The prose is still there, as `detail`, and
    /// [`FailedConsequence`]'s `Display` renders exactly it — so the stderr breadcrumb `nxc` prints
    /// is byte-for-byte what it always was.
    pub warnings: Vec<FailedConsequence>,
}

impl TriggerReceipt {
    /// Fill in the working-tree fields plus [`spawned`](TriggerReceipt::spawned) from what
    /// [`trigger_role`] answered — written once, here, because both callers that build a
    /// [`TriggerReceipt`] have to map the same admission the same way and a copy per call site is
    /// how they would drift apart. Exhaustive on [`TriggerAdmission`] (safe in-crate despite its
    /// `#[non_exhaustive]`, per that type's own doc) precisely so a future third admission cannot
    /// silently leave `spawned` at whatever the caller's base literal happened to set it to.
    fn with_admission(mut self, admission: TriggerAdmission) -> Self {
        match admission {
            TriggerAdmission::Spawned {
                declaration_changed,
            } => {
                self.spawned = true;
                // Folded into the ONE list a caller reads, exactly as the queued arm folds its own
                // finding below (nxf 6j6v.pkw9): a second field for "and by the way the rules
                // moved" would be a second place to look, which is the defect `warnings` exists to
                // end.
                if let Some(finding) = declaration_changed {
                    self.warnings.push(finding);
                }
            }
            TriggerAdmission::Queued {
                behind,
                position,
                findings,
            } => {
                self.spawned = false;
                self.queued_behind = behind;
                self.queue_position = Some(position);
                self.warnings.extend(findings);
            }
        }
        self
    }
}

/// **Take over a task addressed to ONE declared persona** — the persona path's coordinator, and the
/// single entrance to it (nxf 6j6v.ntp9).
///
/// `nxc send --to <persona>` and [`crate::engine::Engine::send_to`] both arrive here, through
/// [`crate::surface::send_to`], and so does every step of a declared channel's flow that names a
/// role ([`open_flow_step`]) — which is what makes this the place all the ways converge, the twin of
/// `supervisor_fan_out` for channels. See this section's header for the decision that a persona
/// commission gets its own leaner coordinator instead of becoming a one-step channel.
///
/// What it decides, in order:
///
/// 1. **the depth guard**, before the first write ([`resolve_hop`]);
/// 2. **the role**, resolved from the catalogue — resolving it after the message was posted was a
///    real defect: an unknown role left an orphan message behind a misleading non-zero exit;
/// 3. **the conversation**, materialised when the caller named no channel ([`ensure_dm_channel`]);
/// 4. **the thread**, opened when the caller handed none — see [`Commission::thread`] for why this
///    is the coordinator's and not the surface's;
/// 5. **the obligation**: this thread expects a reply from the role this call is summoning;
/// 6. **the session id**, minted and held;
/// 7. **the task**, handed over — the caller's words plus the one line of plumbing
///    ([`wake_message`]) — through [`trigger_role`], which composes the prompt, picks the model,
///    grants the tools and states the turn's terms.
///
/// **Preflight before persist**: steps 1 and 2 happen entirely before anything is written.
///
/// It was `role_trigger`/`role_trigger_with` — one public verb and one crate wrapper that differed
/// only in whether the caller passed a wake message — and before that `nxc send --role` and
/// `Engine::role_trigger`, both of which 6j6v.dvyq §3 removed. The wake is a field on the request
/// now, so there is one name.
pub fn coordinator_commission(
    ctx: &Ctx,
    store: &mut ChatStore,
    req: Commission,
) -> Result<TriggerReceipt> {
    coordinator_commission_in(
        ctx,
        store,
        req,
        Coordinator::Persona,
        SpawnFailure::Reported,
    )
}

/// What [`coordinator_commission_in`] does when the worker refuses or fails the spawn AFTER the
/// message, the obligation and the pending session are already durably written.
///
/// The two answers are both correct, for different callers, and the difference is entirely about
/// what the caller's own receipt can carry:
///
/// * [`Reported`](SpawnFailure::Reported) — nxf 6j6v.hpv8's shape, and what `send --to <persona>`
///   needs: return the receipt with the failure in [`TriggerReceipt::warnings`], because discarding
///   it behind an `Err` made "the message is durably in the channel and nobody is working on it"
///   indistinguishable from "nothing happened".
/// * [`Propagated`](SpawnFailure::Propagated) — what the CHANNEL fan-out needs: it keeps the
///   pre-existing contract `crate::surface::SendToReceipt::spawned` states for the channel path
///   (reaching `Ok` means every member started), error KIND included.
///
/// **nxf 6j6v.93zd considered turning the fan-out into `Reported` and did not, so the reason is
/// written here rather than left as an omission.** That item gave every receipt a
/// [`FailedConsequence`] list, which is the field this doc used to say was missing — but the two
/// cases are not alike. A `Reported` failure is one where the caller gets a receipt and would
/// otherwise get NOTHING: `Err` there discards a durable message, a registered obligation and a
/// minted session. A fan-out that propagates discards nothing — the threads it opened are durable
/// and visible in `nxc status`, and the caller gets a typed error naming the member that would not
/// start. Making it report instead would turn "this channel is running" into a claim the caller has
/// to disprove. The failure is loud; it is not silent, and 93zd is about the silent ones.
///
/// (The argument used to end on a second reason — that reporting would silently drop the finding on
/// `fire_channel_step`, the run engine's channel-step firing, which discarded its receipt. That
/// call site went with the run engine in 6j6v.dvyq §3; the first reason is the one that carries it.)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SpawnFailure {
    Reported,
    Propagated,
}

/// [`coordinator_commission`]'s body, with the two things a CHANNEL step decides differently.
///
/// It carried a third extra argument until 6j6v.dvyq §3 — which RUN drove this trigger, threaded
/// through to the prompt composition (nxf 6j6v.1wgd) instead of being rediscovered from the
/// caller's ambient session. The runs are gone; these two are what is left, and they are why the
/// split stays:
///
/// * [`SpawnFailure`] — a failing member propagates for the fan-out and is reported for a direct
///   commission; see that type's own doc for the argument.
/// * [`Coordinator`] — WHICH named place admitted this (nxf 6j6v.ntp9). The persona coordinator and
///   the channel supervisor share this body, so the answer cannot be derived from being here; it is
///   stated by whoever entered, travels on [`RoleSpawn::coordinator`] and is read back at the worker
///   seam.
///
/// The channel supervisor (nxf 6j6v.pf6j) is why this exists as its own entry point at all: it has
/// no session, deliberately, so the ambient resolution has nothing to find and a channel step's
/// members would silently be composed against whatever the catalogue nominates as its team workflow.
/// [`coordinator_commission`] is the `Ambient` wrapper, unchanged for every other caller — the same
/// shape [`channel_open`]/[`channel_open_in`] already use one level up.
fn coordinator_commission_in(
    ctx: &Ctx,
    store: &mut ChatStore,
    req: Commission,
    coordinator: Coordinator,
    on_spawn_failure: SpawnFailure,
) -> Result<TriggerReceipt> {
    let hop = resolve_hop(ctx, store)?;
    let decl = ctx.defs.role(req.role)?.clone();
    // **WHICH MACHINE RUNS THIS CHAT, decided before anything is written** (nxf 6j6v.1c6k). A
    // machine that is not online is ASKED about here, as a refusal that leaves no trace, so the
    // answer is simply the same call again with `--machine` — see [`designate_new_chat`].
    let designation = designate_new_chat(ctx, &decl, &req, coordinator)?;

    let channel = match req.channel {
        Some(c) => c.to_string(),
        None => ensure_dm_channel(
            store,
            ctx.origin,
            ctx.actor,
            &ctx.caller_handle(),
            &ctx.qualify(req.role),
        )?,
    };
    // **THE THREAD, and the coordinator is where it is opened** (nxf 6j6v.ntp9). A caller that has
    // already opened one hands it in — the supervisor must, because its member thread has to hang
    // under the channel thread and carry the board's deadline before the member starts. Every other
    // caller hands `None`, and gets one here, hung under wherever it is standing.
    //
    // It used to be `crate::surface::send_to`'s, one call further out, which made a thread-bearing
    // commission a property of the CLI/app surface rather than of the coordinator: reach this verb
    // by any other route and the summoned role had nothing to answer into, nobody expecting it, and
    // no obligation for the sidecar's teardown to settle (nxf 6j6v.rp8k's shape). See
    // [`Commission::thread`].
    // `opened_here` is `true` in EXACTLY the branch that MINTED a thread, and it is what decides
    // whether this commission also gives it a name (nxf 6j6v.e76c) — see `commission_thread_name`
    // for the rule and why a handed-in thread is left alone. The branch itself carries the answer,
    // rather than a second expression further down that could come to disagree about which case
    // this is.
    let (thread, opened_here) = match req.thread {
        Some(t) => (t.to_string(), false),
        None => {
            let parent = ambient_parent(ctx, store);
            (
                open_child_thread(ctx, store, &channel, parent.as_deref()),
                true,
            )
        }
    };
    // The OTHER place an operation is opened (nxf 6j6v.n92p) — `send --to <persona>`, the entrance
    // bqe0 §3.1 names beside `send --to <channel>`. Same `INSERT OR IGNORE` under the same root, so
    // a commission INSIDE a running chain (a channel's flow step, a re-commission out of a review)
    // binds nothing and inherits the version its operation already runs under.
    store.freeze_declarations(&store.thread_root(&thread)?, ctx.now, ctx.defs)?;
    let refs = with_working_copy(ctx, with_return_address(ctx, req.refs));
    let receipt = facade::send(
        store,
        facade::SendRequest {
            now: ctx.now,
            origin: ctx.origin,
            actor: ctx.actor,
            channel: &channel,
            body: req.body,
            kind: req.kind,
            priority: req.priority,
            disposition: req.disposition,
            thread: Some(&thread),
            refs,
        },
    )?;

    // **AFTER the opening message is posted, because that message IS the derivation's input** (nxf
    // 6j6v.e76c). The commissioned run reads the thread back; commissioning it a line earlier would
    // race it against an empty thread.
    if opened_here {
        commission_thread_name(ctx, &thread);
    }

    // **The chat's machine, written with the chat** (nxf 6j6v.1c6k) — whichever machine runs it,
    // so a reply written on ANY machine later knows where the persona lives. Written by the caller,
    // like the obligation below it: the register's authority is its op's signature, which is this
    // replica's key.
    let designated = designation.as_ref().and_then(|a| a.machine.clone());
    if let Some(m) = &designated {
        store.set_thread_machine(&thread, &m.machine_id, &ctx.caller_handle());
    }
    let handed_to = designated.clone().filter(|m| !m.here);

    // **The session id, minted and held — BEFORE the obligation below it** (independent review of
    // PR #378, Integrity #7). `create_pending_session` is the last fallible step on this path, and
    // while it stood AFTER the register write, a failure there left an `expects_reply_from` on a
    // thread that hangs under `ambient_parent` — i.e. inside the enclosing operation's claim
    // subtree, where `work_scope_has_outstanding` reads it as work still owed and holds the working
    // copy until `operation_lease_expiry`. Nothing would ever answer it: no session was minted, so
    // no worker was ever asked. Minting first costs nothing (a pending session with no trigger is
    // exactly what a queued commission already leaves behind, and `withdraw` is written for it) and
    // makes the register write the LAST thing this function does before the spawn.
    // **Minted, or CONTINUED** (nxf 6j6v.y1t9). A continued session needs no mint — it is already
    // in the map, with its role, its depth and its transcript — so the paragraph above applies to
    // the branch that mints and the other branch has nothing that can fail. What both hand down is
    // one id, which is what keeps everything below this line one path.
    // A chat handed to another machine mints no session HERE: the session belongs to the machine
    // that runs the persona, and that machine mints its own when it picks the order up.
    let (internal, resume_real) = match &req.continue_session {
        _ if handed_to.is_some() => (String::new(), None),
        Some(c) => (c.internal.clone(), c.real.clone()),
        None => {
            let internal = store.mint_session_id();
            store.create_pending_session(&internal, req.role)?;
            (internal, None)
        }
    };

    // Every commission declares, on its own thread, that it expects a reply from the role it just
    // summoned — the deterministic "still owes a reply" fact `ask` and the declared-channel fan-out
    // already leave behind, and the one the direct-persona path left nobody to observe (nxf
    // 6j6v.jepk). **There is always a thread to declare it on now** (nxf 6j6v.ntp9): the branch
    // that used to skip this whole block for a thread-less trigger is gone with the thread-less
    // trigger itself, one screen up.
    //
    // What stays is the other half: never OVERWRITE a thread that already carries an expectation —
    // a caller re-using an existing thread may be continuing a board the fan-out already put a
    // whole quorum on, and setting ours unconditionally would silently collapse it to one handle.
    //
    // `declared_here` is `Some(thread)` in EXACTLY the branch that actually wrote
    // `expects_reply_from` below, and feeds the guidance half (nxf 6j6v.enrs) the role is spawned
    // with — one boolean driving both, not two expressions that can drift apart (PR review,
    // 2026-08-13): telling a role "you owe a reply on thread X" while the register disagrees would
    // be a lie ticket 8's `--if-unanswered` discharge — which reads that SAME register — could not
    // catch, silently finding nothing owed for a role that believed otherwise.
    //
    // `thread_quorum` returning `None` (no `threads` row at all) is deliberately treated the same
    // as an EMPTY `expects`, not distinguished from it: either way this is a brand-new obligation
    // for this commission to declare, not something already owed to someone else (PR review,
    // deferred item, 2026-08-12).
    let already_expects = store
        .thread_quorum(&thread, ctx.now)?
        .is_some_and(|q| !q.expects.is_empty());
    let declared_here: Option<&str> = if already_expects {
        None
    } else {
        let expects_json =
            serde_json::to_string(&[ctx.qualify(req.role)]).expect("expects serialize");
        store.set_expects_reply_from(&thread, &expects_json, &ctx.caller_handle());
        Some(thread.as_str())
    };

    // **Handed over, not started** (nxf 6j6v.1c6k). The message, the chat's machine and the
    // obligation are durable; the designated machine reads exactly those after its next pull and
    // starts the persona there. Nothing here starts anything.
    if let Some(to) = handed_to {
        return Ok(TriggerReceipt {
            handed_to: Some(to),
            message_id: receipt.message_id,
            thread,
            session: String::new(),
            channel,
            queued_behind: None,
            queue_position: None,
            spawned: false,
            warnings: Vec::new(),
        });
    }
    // Designated HERE: this machine claims the order before it starts it, so the service's pickup
    // — in this replica or in another clone of the same stream on this machine — does not start it
    // a second time.
    if designated.is_some() {
        if let Some(m) = ctx.machines {
            claim_here(m, &thread, &receipt.message_id, ctx.db_path);
        }
    }

    // **The task, as the role will read it** (nxf 6j6v.ntp9). The caller's own words are what was
    // POSTED; what the session is STARTED with additionally names the thread it must answer into —
    // composed in one place instead of at each entrance from its own literal.
    let wake = wake_message(
        req.body,
        false,
        &reply_guidance(store, ctx.now, &ctx.qualify(req.role), Some(&thread)),
    );

    // NOT `?` (nxf 6j6v.hpv8). By this point the message is posted, the thread's obligation (if
    // any) is registered and the pending session above is minted — all durably, all before the
    // worker is ever asked to do anything. A trigger failure here used to propagate as a bare
    // `Err`, which discarded every one of those three facts and left the caller unable to tell
    // "nothing happened" from "the message is durably in the channel and nobody is working on it".
    // Matching instead of `?`-ing turns that into the same receipt a clean spawn returns, with the
    // failure named in `warnings` — see that field's own doc for why this is the deliberate shape
    // on BOTH seams and not merely "swallow the error": `warnings` is never omitted, so a `--json`
    // reader and a `Result`-matching Rust caller alike are forced to see it, and `nxc` (`cli.rs`)
    // still exits non-zero for a script that checks only the exit code.
    match trigger_role(
        ctx,
        store,
        RoleSpawn {
            decl: &decl,
            internal_session: internal.clone(),
            resume_real,
            message: &wake,
            // WHO admitted this — stated by whoever entered this body, never derived from being in
            // it: the persona coordinator and the channel supervisor both run it (nxf 6j6v.ntp9).
            coordinator,
            model_override: req.model,
            hop,
            chain: ChainMove::Deeper,
            // The guidance half of the SAME condition above (nxf 6j6v.enrs): `declared_here` is
            // `Some` only when this call actually wrote `expects_reply_from`, so the role is told
            // the obligation exactly when the register agrees it has one — never when a re-used
            // thread already carried someone else's quorum this trigger deliberately left alone.
            reply_thread: declared_here,
            // The thread this trigger BELONGS to, which is the thread whether or not
            // `declared_here` registered an obligation on it. A `--thread` reuse into a board
            // somebody else already put a quorum on lands here with `declared_here: None`, and that
            // board's outstanding expectation is what releases the lease (PR review, Finding 1).
            thread: Some(&thread),
            priority: req.priority,
            queued_since: None,
        },
    ) {
        Ok(admission) => Ok(TriggerReceipt {
            handed_to: None,
            message_id: receipt.message_id,
            thread: thread.clone(),
            session: internal,
            channel,
            queued_behind: None,
            queue_position: None,
            // Overwritten by `with_admission` in both of its match arms — see that impl's own doc
            // for why the initial value here is deliberately irrelevant.
            spawned: false,
            warnings: Vec::new(),
        }
        .with_admission(admission)),
        Err(e) => {
            // The claim goes back with the failed start (nxf 6j6v.1c6k), so the service's pickup on
            // this machine tries again rather than finding an order nobody will ever start.
            if designated.is_some() {
                if let Some(m) = ctx.machines {
                    m.release_order(ctx.db_path, &receipt.message_id);
                }
            }
            let warning = format!(
                "starting {} failed after the message was persisted and session {internal} was \
                 minted: {e} — nobody is working on this yet",
                req.role
            );
            if on_spawn_failure == SpawnFailure::Propagated {
                // The ERROR, not a rendering of it: a caller that has to fail on this still gets the
                // kind it always got (a `Disabled` worker is `validation`, a real spawn failure is
                // not), which a string reconstructed from `warnings` could never give back.
                let mut err = NxfError::from(e);
                err.msg = warning;
                return Err(err);
            }
            // **A step that did not start** — the same class, the same record and the same reason
            // taxonomy as everywhere else in this module (nxf 6j6v.93zd), which is what closes nxf
            // 6j6v.6m6x: WHY this did not start is now a value on the receipt rather than a phrase
            // inside a sentence.
            let reason = wake_skip_reason(&e);
            Ok(TriggerReceipt {
                handed_to: None,
                message_id: receipt.message_id,
                session: internal.clone(),
                channel,
                queued_behind: None,
                queue_position: None,
                spawned: false,
                warnings: vec![FailedConsequence::step_skipped(
                    Some(&thread),
                    Some(&internal),
                    reason,
                    warning,
                )],
                thread,
            })
        }
    }
}

/// **Which machine a NEW persona chat runs on** (nxf 6j6v.1c6k) — `None` when no machine is
/// designated (a host that names no machine, or an entrance that does not open a chat).
///
/// Only the persona coordinator opening a fresh chat designates: a channel member, a re-commission
/// into a thread that already exists, and a continued session all run where the operation they
/// belong to runs (`docs/specs/E4-executing-machine.md` §2.1). Naming a machine for one of those is
/// refused rather than ignored.
///
/// **A chat a running SESSION starts runs on that session's machine.** Its answer comes back into
/// the session that asked, and that session lives here — a sub-chat handed to another machine would
/// have its answer arrive where nobody is waiting for it. So the persona's `machine:` is not
/// consulted for such a chat, and a `--machine` naming another machine is refused.
fn designate_new_chat(
    ctx: &Ctx,
    decl: &RoleDecl,
    req: &Commission,
    coordinator: Coordinator,
) -> Result<Option<crate::machine::MachineAnswer>> {
    let fresh_chat = coordinator == Coordinator::Persona
        && req.thread.is_none()
        && req.continue_session.is_none();
    if !fresh_chat || ctx.machines.is_none() {
        if req.machine.is_some() {
            return Err(NxfError::validation(if fresh_chat {
                "this host names no machines, so a chat cannot be sent to one — `--machine` needs \
                 the `nxs` binary or an embedding host that passes its machines"
            } else {
                "a machine is named for a NEW persona chat only — a channel runs where it is \
                 started, and a thread that already exists keeps its machine (hand it over with \
                 `reply --thread <id> --machine <id|name>`)"
            }));
        }
        return Ok(None);
    }
    let from_session = ctx.session.is_some();
    let answer = crate::machine::resolve_or_ask(
        ctx.machines,
        ctx.db_path,
        crate::machine::Wanted {
            choice: req.machine,
            chat: None,
            persona: (!from_session).then_some(decl.machine.as_deref()).flatten(),
        },
        "--machine <id|name>",
    )?;
    if from_session && !answer.runs_here() {
        return Err(NxfError::validation(
            "a chat a running session starts runs on that session's machine: its answer comes \
             back into the session that asked, which lives here. Start it without --machine, or \
             ask the person you work for to start it on the other machine",
        ));
    }
    // …and it records no machine either: a sub-chat always runs here, so there is nothing for a
    // register to decide, and without one the chat keeps the ordinary routing a session's
    // conversation has always had.
    if from_session {
        return Ok(None);
    }
    Ok(answer.machine.is_some().then_some(answer))
}

/// Claim `message_id` and `thread` on this machine before starting the persona here (nxf
/// 6j6v.1c6k), so the service's pickup — in this replica or another clone of the same stream on
/// this machine — does not start it again.
///
/// **Both claims are FRESH by construction** — the thread and the message were minted by this very
/// call a few lines up, so nothing on this machine can have claimed either yet. A claim that comes
/// back taken (`Ok(false)`) is therefore not a race this function arbitrates but a broken
/// invariant (an id minted twice, a claim store shared across machines), and it is said on stderr
/// rather than silently ignored. It does not stop the start: the caller asked for it, and what keeps
/// two starts of one SESSION apart is the worker's single-process session lock
/// (`worker::SessionLock`), not this claim — this claim keeps the service's pickup from handing the
/// same MESSAGE over a second time.
///
/// A claim that cannot be WRITTEN is said on stderr too. What it costs, stated plainly: the pickup
/// finds the message unclaimed while the persona has not answered yet, and hands it over again —
/// resumed into the persona's own session (held while it works), not a second session.
fn claim_here(m: &dyn crate::machine::Machines, thread: &str, message_id: &str, db_path: &str) {
    match m.claim_thread(thread, db_path) {
        Ok(holder) if holder != db_path => eprintln!(
            "warning: chat {thread} was just opened here, yet {holder} already claims to serve it \
             on this machine — the persona starts here anyway"
        ),
        Ok(_) => {}
        Err(e) => {
            eprintln!("warning: could not record which workspace serves chat {thread}: {e}")
        }
    }
    match m.claim_order(db_path, message_id) {
        Ok(true) => {}
        Ok(false) => eprintln!(
            "warning: message {message_id} was just written here, yet it is already claimed on \
             this machine — the persona starts here anyway"
        ),
        Err(e) => eprintln!("warning: could not claim message {message_id} on this machine: {e}"),
    }
}

/// **A direct conversation with one declared persona** (nxf 6j6v.1c6k) — the only kind of thread
/// that has a machine in this slice. `persona` is qualified (`origin/handle`, what a message's
/// `sender` holds), `handle` bare (what the catalogue and the session map hold).
#[derive(Debug, Clone)]
pub(crate) struct PersonaChat {
    pub(crate) thread: String,
    pub(crate) persona: String,
    pub(crate) handle: String,
    pub(crate) machine: Option<crate::machine::ThreadMachine>,
    /// Whether the thread is held (nxf 6j6v.pzkb): an op that shaped it may not carry an action.
    pub(crate) held: bool,
}

/// `thread` read as a persona chat: it lives in a direct conversation, and the one party it was
/// opened to expect a reply from is a persona this catalogue declares. `None` for anything else.
pub(crate) fn persona_chat(
    ctx: &Ctx,
    store: &ChatStore,
    thread: &str,
) -> Result<Option<PersonaChat>> {
    let in_dm = store
        .thread_channel(thread)
        .or_else(|| store.thread_channel_via_message(thread))
        .is_some_and(|c| is_dm_channel(&c));
    if !in_dm {
        return Ok(None);
    }
    let Some(q) = store.thread_quorum(thread, ctx.now)? else {
        return Ok(None);
    };
    let [persona] = q.expects.as_slice() else {
        return Ok(None);
    };
    let handle = persona.rsplit('/').next().unwrap_or(persona).to_string();
    if ctx.defs.role(&handle).is_err() {
        return Ok(None);
    }
    Ok(Some(PersonaChat {
        thread: thread.to_string(),
        persona: persona.clone(),
        handle,
        machine: store.thread_machine(thread)?,
        held: q.held,
    }))
}

/// What [`serve_chat`] did for one chat.
#[derive(Debug, Clone)]
pub(crate) struct Served {
    /// The persona session the messages went to — resumed, held for, or freshly started.
    pub(crate) session: Option<String>,
    /// A fresh session was started (the chat's first turn on this machine).
    pub(crate) started: bool,
    /// The session was mid-turn: the messages are held and delivered when its turn ends.
    pub(crate) held: bool,
    /// The messages served, oldest first.
    pub(crate) messages: Vec<String>,
    /// A resume that could not be put in motion, and why.
    pub(crate) skipped: Option<WakeSkipped>,
    /// A start that failed; its claims were given back.
    pub(crate) error: Option<String>,
}

/// **Hand the persona of a chat on THIS machine what was written to it since its last answer**
/// (nxf 6j6v.1c6k) — the one path both the local `reply` and the service's [`pick_up`] take.
///
/// A decision over current state, never a reaction to arrival (`E4-auth…` §2.5): the messages that
/// count are the ACTING ones after the persona's own last acting message, and each is claimed on
/// this machine first ([`crate::machine::Machines::claim_order`]), so a message is served once
/// however many processes and replicas look. The chat itself is claimed for this replica
/// ([`crate::machine::Machines::claim_thread`]) so every turn goes where the persona's session
/// lives. `None` when there is nothing to serve here.
///
/// The persona's session in this replica is RESUMED (held for, when mid-turn — the ordinary
/// `reply` behaviour); when this replica holds none — the chat's first turn here, or a chat just
/// handed over from another machine — one is STARTED and told where the conversation so far is.
/// A start that fails gives its claims back, so the next pickup tries again.
pub(crate) fn serve_chat(
    ctx: &Ctx,
    store: &mut ChatStore,
    chat: &PersonaChat,
    hop: CheckedHop,
    just_posted: Option<&str>,
) -> Result<Option<Served>> {
    let Some(machines) = ctx.machines else {
        return Ok(None);
    };
    if chat.held {
        return Ok(None);
    }
    let msgs = store.acting_messages_in_thread(&chat.thread)?;
    let since_answer = match msgs.iter().rposition(|m| m.sender == chat.persona) {
        Some(last) => &msgs[last + 1..],
        None => &msgs[..],
    };
    if since_answer.is_empty() {
        return Ok(None);
    }
    let existing = store
        .sessions_in_thread(&chat.thread)?
        .into_iter()
        .rev()
        .find(|s| s.role == chat.handle);
    // **A reply written HERE to a persona that has a session here hands over that reply alone** —
    // the ordinary `reply` behaviour. The messages before it were handed over when they were
    // written; in a workspace that syncs nowhere nothing is claimed (see `Machines::claim_order`),
    // so re-reading them from the thread would deliver them twice. Everything since the persona's
    // last answer goes to a FRESH session, and to the service's pickup, whose claims say what is
    // new.
    let since_answer: Vec<_> = match (just_posted, &existing) {
        (Some(id), Some(_)) => since_answer
            .iter()
            .filter(|m| m.message_id == id)
            .cloned()
            .collect(),
        _ => since_answer.to_vec(),
    };
    let holder = machines
        .claim_thread(&chat.thread, ctx.db_path)
        .map_err(NxfError::io)?;
    if holder != ctx.db_path {
        // Another replica of this stream on this machine serves this chat: the persona's session
        // lives in ITS session map.
        return Ok(None);
    }
    let mut fresh = Vec::new();
    for m in &since_answer {
        if machines
            .claim_order(ctx.db_path, &m.message_id)
            .map_err(NxfError::io)?
        {
            fresh.push(m.clone());
        }
    }
    let Some(last) = fresh.last().cloned() else {
        return Ok(None);
    };
    let ids: Vec<String> = fresh.iter().map(|m| m.message_id.clone()).collect();
    let give_back = || {
        for id in &ids {
            machines.release_order(ctx.db_path, id);
        }
    };
    let body = fresh
        .iter()
        .map(|m| m.body.as_str())
        .collect::<Vec<_>>()
        .join("\n\n");
    let guidance = reply_guidance(store, ctx.now, &chat.persona, Some(&chat.thread));
    // A hand-back among them announces itself first, exactly as on the ordinary resume (nxf
    // 6j6v.gk9j) — the model reads the body, and that is where it has to learn it is being asked
    // for help rather than handed a result.
    let escalated = fresh
        .iter()
        .any(|m| m.kind == crate::model::KIND_ESCALATION);

    if let Some(session) = existing {
        let wake = wake_message(&body, escalated, &guidance);
        let hold = crate::collecting::Held {
            thread_id: chat.thread.clone(),
            message_id: last.message_id.clone(),
            sender: last.sender.clone(),
            body: body.clone(),
            escalated,
        };
        let attempt = resume_return_address(
            ctx,
            store,
            Resume {
                addr: &session.internal_id,
                body: &wake,
                model: None,
                hop,
                thread: Some(&chat.thread),
                on_busy: OnBusy::Hold(&hold),
            },
        );
        if attempt.woke.is_none() && attempt.held.is_none() {
            give_back();
        }
        return Ok(Some(Served {
            session: Some(session.internal_id),
            started: false,
            held: attempt.held.is_some(),
            messages: ids,
            skipped: attempt.skipped,
            error: None,
        }));
    }

    // No session of this persona here: start one. It did not see what came before on another
    // machine, so it is told where the whole conversation is.
    let decl = ctx.defs.role(&chat.handle)?.clone();
    let earlier = msgs.len() > fresh.len();
    let body = if earlier {
        format!(
            "{body}\n\nThis conversation began before this session — read it first: `nxc threads \
             show {}`.",
            chat.thread
        )
    } else {
        body
    };
    let wake = wake_message(&body, escalated, &guidance);
    let internal = store.mint_session_id();
    store.create_pending_session(&internal, &chat.handle)?;
    store.freeze_declarations(&store.thread_root(&chat.thread)?, ctx.now, ctx.defs)?;
    let started = trigger_role(
        ctx,
        store,
        RoleSpawn {
            decl: &decl,
            internal_session: internal.clone(),
            resume_real: None,
            message: &wake,
            coordinator: Coordinator::Persona,
            model_override: None,
            hop,
            chain: ChainMove::Deeper,
            reply_thread: Some(&chat.thread),
            thread: Some(&chat.thread),
            priority: Priority::Normal,
            queued_since: None,
        },
    );
    Ok(Some(match started {
        Ok(_) => Served {
            session: Some(internal),
            started: true,
            held: false,
            messages: ids,
            skipped: None,
            error: None,
        },
        Err(e) => {
            give_back();
            Served {
                session: Some(internal),
                started: false,
                held: false,
                messages: ids,
                skipped: None,
                error: Some(e.to_string()),
            }
        }
    }))
}

/// **What one pickup did** (nxf 6j6v.1c6k) — `nxc pick-up --json`, `Engine::pick_up`. Declared field
/// order is the JSON contract.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct PickupReport {
    /// This machine, as the pickup knew it; `None` when the host names none (nothing is picked up).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub machine: Option<crate::machine::MachineRef>,
    /// The chats a persona was put to work on.
    pub served: Vec<PickedUp>,
    /// The chats designated here that could not be served, and why.
    pub failed: Vec<PickupFailed>,
}

/// One chat a pickup served.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct PickedUp {
    pub thread: String,
    /// The persona, bare.
    pub persona: String,
    pub session: String,
    /// A fresh session was started; `false` resumed (or held for) the persona's own session.
    pub started: bool,
    /// The persona was mid-turn: the messages are held and go out when its turn ends.
    pub held: bool,
    /// The messages handed over, oldest first.
    pub messages: Vec<String>,
}

/// One chat a pickup could not serve. Its claims were given back, so the next pickup tries again.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct PickupFailed {
    pub thread: String,
    pub reason: String,
}

/// **Pick up every chat this machine runs that is owed a turn** (nxf 6j6v.1c6k) — what the
/// background service runs after a pass (`nxc pick-up`), and what an embedding host that executes
/// calls (`Engine::pick_up`).
///
/// A chat is picked up when its `machine` register names THIS machine and the op that wrote it may
/// carry an action here, it is a persona chat, and somebody wrote to the persona after its last
/// answer — see [`serve_chat`] for how, and `docs/specs/E4-executing-machine.md` §2.3 for why this
/// is a decision over current state and never a reaction to arrival. Idempotent: running it twice
/// serves nothing the second time.
pub fn pick_up(ctx: &Ctx, store: &mut ChatStore) -> Result<PickupReport> {
    let here = ctx.machines.and_then(|m| m.here());
    let mut report = PickupReport {
        machine: here.clone(),
        served: Vec::new(),
        failed: Vec::new(),
    };
    let Some(here) = here else {
        return Ok(report);
    };
    let hop = resolve_hop(ctx, store)?;
    for thread in store.threads_designated_to(&here.machine_id)? {
        let Some(chat) = persona_chat(ctx, store, &thread)? else {
            continue;
        };
        let frozen = operation_declarations(ctx, store, &thread)?;
        let ctx = &with_declarations(ctx, frozen.as_ref());
        match serve_chat(ctx, store, &chat, hop, None) {
            Ok(Some(s)) => match (&s.error, &s.skipped) {
                (Some(e), _) => report.failed.push(PickupFailed {
                    thread,
                    reason: e.clone(),
                }),
                (None, Some(skip)) => report.failed.push(PickupFailed {
                    thread,
                    reason: format!(
                        "the persona's session {} could not be resumed ({:?})",
                        skip.session, skip.reason
                    ),
                }),
                (None, None) => report.served.push(PickedUp {
                    thread,
                    persona: chat.handle.clone(),
                    session: s.session.unwrap_or_default(),
                    started: s.started,
                    held: s.held,
                    messages: s.messages,
                }),
            },
            Ok(None) => {}
            Err(e) => report.failed.push(PickupFailed {
                thread,
                reason: e.msg,
            }),
        }
    }
    Ok(report)
}

/// **What a summoned persona is started with**: the caller's text, then the one line of plumbing it
/// would otherwise have to guess.
///
/// **The coordinator's, since nxf 6j6v.ntp9.** It lived on the surface and was duplicated, from its
/// own literal, in `open_flow_step` — so the two entrances a role can be commissioned through told
/// it the same thing twice and could have drifted. Handing over the task is a coordinator's
/// business; this is what is handed over.
///
/// **`escalated` puts [`crate::channel::ESCALATION_NOTICE`] FIRST** (nxf 6j6v.gk9j) — ahead of the
/// body, because the body is what the model reads and it is where a hand-back was previously
/// indistinguishable from a result. The `escalated: true` field that already exists on `nxc status`
/// is not a substitute: an agent does not run `nxc status`, it reads the message that woke it.
pub(crate) fn wake_message(body: &str, escalated: bool, guidance: &str) -> String {
    let notice = if escalated {
        format!("{}\n\n", crate::channel::ESCALATION_NOTICE)
    } else {
        String::new()
    };
    // **Empty guidance appends NOTHING, not a blank line** (nxf 6j6v.dq59) — the body reaches its
    // requester as itself. That is a property `orchestration_reply.rs`'s
    // `an_ordinary_reply_on_the_direct_resume_is_handed_over_untouched` pins as an EQUALITY, and it
    // is why it is pinned that way: a `!contains("ESCALATION")` would also pass for a body that had
    // grown some other preamble.
    match guidance.is_empty() {
        true => format!("{notice}{body}"),
        false => format!("{notice}{body}\n\n{guidance}"),
    }
}

/// **The coordinator naming the addressees, at the moment it wakes somebody** (nxf 6j6v.dq59) — the
/// one line of plumbing [`wake_message`] carries, composed here so every entrance says it the same
/// way.
///
/// It replaces the fixed sentence `Reply via \`nxc reply --thread <id>\``, and the difference is the
/// item's whole point. That sentence named ONE thread whatever the situation was, so a session with
/// two open conversations — owing its commissioner an answer while its own consultation came back —
/// was handed one id and left to work out that the other existed. This says which conversations are
/// open, whom each one reaches, and which verb each one takes; and where there is only one, it says
/// the id may be left out, which is the simplification the id-free `reply` exists for.
///
/// **`handle` is the QUALIFIED identity being woken**, and `standing_in` the thread this wake lands
/// in — see [`crate::addressees::open_for`] for why a position contributes a shape no register can.
///
/// **Nothing open says nothing at all**, and that is deliberate rather than a gap. The old sentence
/// named a thread unconditionally, which on the direct resume meant naming one the woken session
/// owes nothing on — and an answer that reaches its requester with a preamble it did not ask for is
/// what `orchestration_reply.rs`'s `an_ordinary_reply_on_the_direct_resume_is_handed_over_untouched`
/// exists to refuse.
///
/// It costs nothing where 6j6v.553s part 1's measured failure lives, because on every path that
/// IMPOSES an obligation there is by construction something to name: a commission has just written
/// `expects_reply_from`, a member's next turn has just re-declared it, and a 1:1 turn hand-back
/// lands in a real thread, which contributes [`crate::addressees::Relation::Standing`] even when no
/// register claims it. What is left silent is the one case that should be: a message-addressed
/// conversation with no thread and no register, where there is no addressee to name.
pub(crate) fn reply_guidance(
    store: &ChatStore,
    now: &str,
    handle: &str,
    standing_in: Option<&str>,
) -> String {
    match crate::addressees::open_for(store, handle, standing_in, now) {
        Ok(open) => crate::addressees::render_for_a_wake(&open),
        // A read that FAILED is not a read that found nothing, and neither is worth a sentence
        // naming a thread this session may not owe: the answer still travels, whole, which is the
        // one thing that must not be lost here.
        Err(_) => String::new(),
    }
}

/// Continue a live role session.
///
/// **No surface reaches this any more.** `nxc send --session` and `Engine::role_resume` were its
/// two entrances and 6j6v.dvyq §3 removed both, as a named LOSS rather than a collapse: `reply
/// --thread` answers a conversation through its return address, which is a different act, and a
/// caller holding a session id and no thread has no path left. The body stays — it is what the
/// depth guard's commissioning cases are written against, and what nxf 6j6v.xr3z's
/// `reply --thread <id> --force` would build on once a signal into a running session exists.
///
/// Same preflight discipline: the session must resolve to a role, and that role must still be
/// declared, before anything is posted.
pub fn role_resume(
    ctx: &Ctx,
    store: &mut ChatStore,
    req: RoleResumeRequest,
) -> Result<TriggerReceipt> {
    let hop = resolve_hop(ctx, store)?;
    let role_handle = store
        .session_role(req.session)?
        .ok_or_else(|| NxfError::not_found(format!("no such session: {}", req.session)))?;
    let decl = ctx.defs.role(&role_handle)?.clone();

    let channel = match req.channel {
        Some(c) => c.to_string(),
        None => ensure_dm_channel(
            store,
            ctx.origin,
            ctx.actor,
            &ctx.caller_handle(),
            &ctx.qualify(&role_handle),
        )?,
    };
    let refs = with_working_copy(ctx, with_return_address(ctx, req.refs));
    let receipt = facade::send(
        store,
        facade::SendRequest {
            now: ctx.now,
            origin: ctx.origin,
            actor: ctx.actor,
            channel: &channel,
            body: req.body,
            kind: req.kind,
            priority: req.priority,
            disposition: req.disposition,
            thread: req.thread,
            refs,
        },
    )?;

    let resume_real = store.resolve_real(req.session)?;
    let admission = trigger_role(
        ctx,
        store,
        RoleSpawn {
            decl: &decl,
            internal_session: req.session.to_string(),
            resume_real,
            message: req.body,
            // The persona coordinator, pushing new work into a live 1:1 (nxf 6j6v.ntp9). It is a
            // commission like any other; what makes it its own verb is that the session already
            // exists.
            coordinator: Coordinator::Persona,
            model_override: req.model,
            hop,
            // Deeper even though the session already exists: a resume hands it NEW work,
            // which is the axis the guard counts. This is also the shape the runaway it exists for
            // takes — two roles pushing tasks at each other and never answering.
            chain: ChainMove::Deeper,
            // A resume sets no `expects_reply_from` (only `coordinator_commission` does, nxf
            // 6j6v.jepk) — there is no obligation to tell this resumed session about.
            reply_thread: None,
            // It still BELONGS to whatever thread the caller pushed into, which is the claim area a
            // resume competes under (PR review, Finding 6): registering no new obligation is not the
            // same as being part of no conversation.
            thread: receipt.thread_id.as_deref(),
            priority: req.priority,
            queued_since: None,
        },
    )?;
    // `warnings` stays empty and the `?` above is untouched deliberately (nxf 6j6v.hpv8 scopes its
    // fix to `coordinator_commission` — the persona summon — not to this resume path;
    // see that function's own doc for the reasoning this one does not yet carry). `spawned` is
    // overwritten by `with_admission`, exactly as `coordinator_commission`'s Ok arm.
    Ok(TriggerReceipt {
        handed_to: None,
        message_id: receipt.message_id,
        // **The one verb that can genuinely have none** (nxf 6j6v.ntp9). Every COMMISSION goes
        // through [`coordinator_commission_in`], which opens a thread when it is handed none — but
        // a
        // resume takes the caller's `thread` as it is and must keep doing so: giving it one here
        // would hand a `WorkScope` to a trigger that has deliberately had none since nxf 6j6v.303b,
        // and turn an un-surfaced verb into a competitor for the working-tree lease. Empty reads as
        // absent, the same way this module already reads an empty return address.
        thread: receipt.thread_id.unwrap_or_default(),
        session: req.session.to_string(),
        channel,
        queued_behind: None,
        queue_position: None,
        spawned: false,
        warnings: Vec::new(),
    }
    .with_admission(admission))
}

// (`trigger_role_at` lived here until PR #267's review: a wrapper that rebuilt the `Ctx` with an
// overridden `hop`, because `trigger_role` read the depth off the context. With the checked depth a
// field on [`RoleSpawn`], the override has nowhere left to hide and the wrapper has nothing left to
// do — every call site names its own `hop:` instead.)

/// **Commission the name of a thread this coordinator just OPENED** (nxf 6j6v.e76c) — the one call
/// site rule, in one place, so the two coordinators cannot come to apply it differently.
///
/// **A thread the coordinator OPENS is named; a thread it was HANDED is not.** That is the whole
/// rule and it needs no special case: a channel MEMBER thread reaches
/// [`coordinator_commission_in`] with its thread already open (the supervisor opened it), so the
/// branch this is called from is never taken for one — which is right, because a fan-out's members
/// all carry the same body and naming each of them would be N model calls for N copies of one name.
///
/// **Best-effort, and its failure is a breadcrumb rather than a
/// [`FailedConsequence`]** — deliberately, and the distinction is
/// [`crate::surface::SendToReceipt::refs_warning`]'s: every `FailedConsequence` is a consequence
/// that was OWED and did not happen, and a name was never owed. The thread is open, the message is
/// posted, the persona is running; only nobody worked out what to call it, and every surface renders
/// that state exactly as it did before names existed.
fn commission_thread_name(ctx: &Ctx, thread_id: &str) {
    let run = crate::naming::Naming {
        thread_id,
        db_path: ctx.db_path,
        origin: ctx.origin,
        actor: ctx.actor,
    };
    if let Err(e) = ctx.namer.commission(run) {
        eprintln!(
            "warning: thread {thread_id} could not be given a name: {e} — it is a valid thread \
             either way, and surfaces fall back to its id"
        );
    }
}

// ---- the thread tree (nxf 6j6v.a71h) ------------------------------------------------------

/// Mint and open a thread on an already-existing channel, hung under `parent` — **the one place a
/// 1:1 thread is stamped with its tree edge** (nxf 6j6v.a71h §3.1). Returns the workspace-unique id.
///
/// `parent` is passed rather than resolved here, and that is the whole point of the split: most
/// callers want [`ambient_parent`] ("wherever I am standing"), but the channel supervisor of
/// 6j6v.pf6j opens a thread PER MEMBER out of a thread it names explicitly, and a helper that could
/// only ever read the ambient session would force that call site to reimplement the stamping. Both
/// forms end in this one function, so the edge cannot be written two ways.
///
/// The `opener` is the caller's own qualified identity, which is what makes the requester wake
/// (`prime --json`'s `threads_you_opened`) find this conversation later.
pub fn open_child_thread(
    ctx: &Ctx,
    store: &mut ChatStore,
    channel_id: &str,
    parent: Option<&str>,
) -> String {
    let author = ctx.caller_handle();
    store.set_wall_clock(ctx.now);
    let thread_id = store.mint_thread_id();
    store.open_thread(
        &thread_id,
        &crate::model::ThreadRoot {
            origin: ctx.origin.to_string(),
            channel_id: channel_id.to_string(),
            opener: author.clone(),
            created: ctx.now.to_string(),
            parent: parent.map(str::to_string),
        },
        &author,
    );
    thread_id
}

/// Which thread `thread` competes for the working-tree lease UNDER: **the root of its OPERATION**
/// (nxf 6j6v.8y6t, owner decision (a) of 2026-08-23).
///
/// **What this used to be, and why it moved.** It used to resolve ONE hop upward for a supervised
/// channel member and answer the thread itself for everything else (nxf 6j6v.pf6j), which made the
/// claim area the subtree from THAT thread (nxf 6j6v.1xw1). Two consequences of that shape were
/// measured on 2026-08-22 and are what this change is for:
///
/// * **the operation was not atomic between rounds.** The claim fell as soon as the subtree under
///   `#coding` was worked off, so a `pm` commissioning a SECOND coding round of the same epic left a
///   window between the two that a foreign chain could step into — to the caller, an interruption in
///   the middle of its own operation.
/// * **the order of two operations could be inverted.** A chain whose exclusive step comes late took
///   nothing while it planned, so a foreign chain starting later could take the checkout first and
///   the earlier operation queued behind it.
///
/// **The claim still ARISES only at the first exclusive step** — [`needs_working_tree`] is
/// untouched, and so is the one-hop derivation in
/// [`Definitions::channel_needs_working_tree`](crate::definitions::Definitions::channel_needs_working_tree)
/// that decides whether a channel needs the copy at all. The owner refused the alternative that
/// would have changed THAT (way (b), looking ahead over the declared chain): it holds the working
/// copy through pure planning and serialises hardest. What moved is only the ANCHOR: the claim is
/// taken on behalf of the whole operation rather than of the branch it happened to start in, so it
/// is given back when the operation is finished rather than when that branch is.
///
/// **So the upward boundary 1xw1 drew is EXPRESSLY superseded** — that item stopped the area at the
/// claim thread so "one unanswered human" could not hold this device's working copy until tomorrow,
/// and that risk is real and now returns. What answers it is the other half of this same item: the
/// lease's bound is no longer a flat two hours but the operation's own declared windows
/// ([`operation_lease_expiry`]), and an expired lease is reclaimed by the sweep. Way (c) is
/// untouched and stays the escape hatch: a channel that declares `working_tree: exclusive` ITSELF
/// still claims from its own first step, so an operation that wants its planning phase protected
/// needs no code, only that line.
///
/// **The term this returns is the one nxf 6j6v.nby8 has to reuse rather than re-invent**: an
/// OPERATION is the thread tree hanging off a root, its identity is
/// [`ChatStore::thread_root`] and its extent is [`ChatStore::thread_subtree`] of that root. That
/// definition lives on `thread_root` itself, deliberately in one place.
///
/// A thread with no parent answers itself, which is the same walk `thread_root` does for every other
/// shape; `None` in, `None` out.
fn lease_claim_root(store: &ChatStore, thread: Option<&str>) -> Result<Option<String>> {
    let Some(thread) = thread else {
        return Ok(None);
    };
    Ok(Some(store.thread_root(thread)?))
}

/// Where this caller is standing: the thread a fresh thread it opens right now hangs under
/// ([`facade::parent_thread_of`] on the ambient session). `None` is a ROOT.
pub fn ambient_parent(ctx: &Ctx, store: &ChatStore) -> Option<String> {
    facade::parent_thread_of(store, ctx.session)
}

// ---- channel_open -----------------------------------------------------------------------

/// Open a DECLARED channel's review board and fan out to its members.
#[derive(Debug, Clone)]
pub struct ChannelOpenRequest<'a> {
    /// The declared channel's name (not a substrate channel id).
    pub channel: &'a str,
    pub body: &'a str,
    // `expect` was here — an explicit override of who must reply, empty meaning "use the channel's
    // own declared policy". REMOVED by 6j6v.dvyq §3 with `ask --expect`, its only door. `send --to`
    // never took one, so the field had no caller left that could set it: with every channel
    // declared, who must answer is written IN the channel, and a per-call list is a second answer
    // to a question the declaration already answers. Preflight (2b) went with it — it existed to
    // refuse exactly this override over a declared flow.
    /// An absolute RFC3339 instant or a duration like `20m`; `None` uses the channel's own declared
    /// `timeout`, if any.
    pub deadline: Option<&'a str>,
    pub kind: MessageKind,
    pub priority: Priority,
    pub refs: Refs,
    /// Per-call model override applied to every fanned-out trigger.
    pub model: Option<Model>,
}

// `orchestration::AskRequest` was here — the router's request, whose `channel` field was
// documented as "a declared channel's name, OR a raw substrate channel id". That sentence is the
// whole of what 6j6v.dvyq §3 removes: one field meaning two different kinds of thing, with the
// answer to "who must reply" coming from a flag in one case and from a declaration in the other.
// `ChannelOpenRequest` above is what survives, and its `channel` means one thing.

/// Open a declared channel and trigger every effective member except the sender.
///
/// **Two representations of the effective target set, not one.** `channel.members` and role
/// resolution live in the BARE handle namespace; `expects_reply_from` is matched against a real
/// reply's `sender`, which is ALWAYS the QUALIFIED `origin/actor` identity, by exact string
/// comparison. Passing the bare targets straight through as expects meant `"bob" != "local/bob"`
/// forever — outstanding never emptied, complete never flipped, which is precisely the deadlock
/// this epic already diagnosed once. Both forms are derived from the SAME preflight-passed list,
/// never two independent computations that could drift.
///
/// **Preflight before persist**, in this exact order and entirely before `ensure_declared_channel`
/// or the board open: (1) the depth guard; (2a) an effective member set that is not empty;
/// (3) every effective target
/// resolving to a declared role or a declared channel; (4) the declared window, read by the one
/// grammar that reads it (nxf 6j6v.nf38). A broken member reference — or an unreadable `timeout` —
/// must fail clean before anything is materialised: no opened board nobody will ever join, no
/// orphaned session.
///
/// Step (2) was `member_session: resume`, a declared policy that rejected its own second value by
/// name; nxf 6j6v.fepb retired the field with it — the question it asked is answered by the two
/// levels, not by a declaration ([`crate::channel::ChannelDecl`]).
pub fn channel_open(
    ctx: &Ctx,
    store: &mut ChatStore,
    req: ChannelOpenRequest,
) -> Result<ChannelOpened> {
    channel_open_in(ctx, store, req)
}

/// What opening a declared channel produced: the BOARD, and everything the opening should have
/// caused and did not (nxf 6j6v.p3sm).
///
/// **The second field is why this type exists.** `channel_open` returned a bare [`AskReceipt`], so
/// `send --to <channel>` had no place at all to report a best-effort step that failed — its
/// `SendToReceipt.warnings` was documented as "always empty on the channel path". That was true and
/// it was the defect: the one-shot job that watches the board's declared `timeout:` is scheduled
/// right here, and when it could not be scheduled the caller got `warnings: []` over a board whose
/// window nothing will ever look at. On macOS that was EVERY board, on every call.
///
/// The channel path still PROPAGATES real failures rather than reporting them (a member that could
/// not be started is an `Err`, unchanged and deliberate — see the preflight's own note); this
/// carries only what is genuinely best-effort and cannot fail a persisted board.
#[derive(Debug, Clone)]
pub struct ChannelOpened {
    /// The channel thread that was opened, with its expectations and its resolved deadline.
    pub board: AskReceipt,
    /// Best-effort steps that did not happen even though the board above IS durably open. Empty is
    /// the ordinary case.
    pub warnings: Vec<FailedConsequence>,
}

/// [`channel_open`]'s body.
///
/// It existed as a separate private entry point to carry one extra argument the public verb had no
/// room for: which RUN a channel step's board belonged to, threaded through to the fan-out's prompt
/// composition (nxf 6j6v.1wgd). 6j6v.dvyq §3 removed the runs and with them that argument, so the
/// split now buys nothing — it is kept only because [`channel_open`] and this pair mirror the
/// [`coordinator_commission`]/[`coordinator_commission_in`] shape one level down, and collapsing
/// one
/// of the two while leaving the other would make the symmetry a coincidence.
fn channel_open_in(
    ctx: &Ctx,
    store: &mut ChatStore,
    req: ChannelOpenRequest,
) -> Result<ChannelOpened> {
    let channel = ctx
        .defs
        .declared_channel(req.channel)?
        .ok_or_else(|| NxfError::not_found(format!("no such declared channel: {}", req.channel)))?
        .clone();
    let mut warnings = Vec::new();
    let board = open_declared_channel_and_fan_out(ctx, store, &channel, &req, None, &mut warnings)?;
    Ok(ChannelOpened { board, warnings })
}

/// The shared mechanism `channel_open` and [`ask`]'s declared branch both run — **the incoming end
/// of a channel's two levels** (nxf 6j6v.pf6j).
///
/// It opens the CHANNEL THREAD, whose two ends are the requester and the [`SUPERVISOR_HANDLE`], and
/// then hands the request to the supervisor, which opens one thread PER MEMBER below it
/// ([`supervisor_fan_out`]). What it does NOT do any more is stamp one thread with every member in
/// its `expects_reply_from` and trigger all of them onto it: requester and members sat in one
/// conversation, every member saw every other member's answer, and the data model had one thread
/// with N+1 ends as its normal case.
fn open_declared_channel_and_fan_out(
    ctx: &Ctx,
    store: &mut ChatStore,
    channel: &ChannelDecl,
    req: &ChannelOpenRequest,
    parent: Option<&str>,
    findings: &mut Vec<FailedConsequence>,
) -> Result<AskReceipt> {
    let hop = resolve_hop(ctx, store)?;
    let sender_qualified = ctx.caller_handle();

    // The effective (bare, qualified) target pairs — the channel's own declared fan-out, with the
    // sender removed: a requester is never expected to reply to, or trigger, itself.
    //
    // **The qualified half no longer becomes anybody's `expects_reply_from`** (nxf 6j6v.pf6j): the
    // channel thread expects the SUPERVISOR, and each member's own thread declares its one member
    // through `coordinator_commission`, which qualifies the handle itself from the same `ctx`. It
    // is
    // still computed here because the trigger loop below addresses members by both forms.
    //
    // ONE branch since 6j6v.dvyq §3. The other read a caller-supplied `--expect` and had to
    // re-qualify and de-duplicate it against the sender, because a caller could write an entry
    // either way. With the override gone the list comes from one place — the declaration — and
    // `fan_out_targets` already removes the sender.
    let effective: Vec<(String, String)> = crate::channel::fan_out_targets(channel, ctx.actor)
        .into_iter()
        .map(|bare| {
            let qualified = ctx.qualify(&bare);
            (bare, qualified)
        })
        .collect();

    // PREFLIGHT (2a): somebody has to be asked (nxf 6j6v.pf6j, fix round 1). An empty effective set
    // is reachable in two ordinary ways — a channel whose only member is the sender, and an explicit
    // `--expect` that filters down to nobody — and under the two levels it is no longer harmless: the
    // channel thread would be opened expecting the SUPERVISOR, and the supervisor resumes only when
    // its set of member threads is settled. An empty set is never settled (`member_set_is_settled`
    // says so deliberately, because "nobody has answered yet" and "there is nobody" must not read
    // alike), so the requester would wait on that thread forever.
    //
    // Refused here rather than made to settle instantly: an empty consolidation delivered back to the
    // requester answers a question nobody asked, while "this channel has nobody to ask" is a mistake
    // in the declaration or the call, and this module's whole discipline is to fail loudly on those
    // BEFORE anything is persisted. Before the two levels this shape opened a board with an empty
    // `expects_reply_from` — a thread nobody was waiting on, which nothing ever reported either; the
    // silence is not something worth preserving.
    //
    // **This propagates rather than reporting, unlike step (4b) of `reply`, and that is deliberate**
    // — the same question, answered the other way, so the two are decided together. (4b) is a path
    // whose own doc says nothing after the post may fail the call, and propagating there broke a rule
    // stated at that very site. THIS path has always propagated — an unresolvable member role, a
    // malformed declaration — so this adds one more reason to an existing
    // contract rather than changing it, and silently swallowing it here would make THIS reason
    // quieter than every reason beside it. Changing when a failed fan-out becomes visible is the
    // failed-consequence place (nxf 6j6v.93zd, which reports rather than relocates errors), not a
    // preflight.
    if effective.is_empty() {
        return Err(NxfError::validation(format!(
            "channel {:?} has nobody to ask: its effective members are empty once the sender \
             ({sender_qualified}) is removed — nothing would ever answer this",
            channel.name
        )));
    }
    // PREFLIGHT (2b) stood here: an explicit expectation set could not be laid over a DECLARED
    // FLOW (nxf 6j6v.hq71), because a sequential channel's answer to "who must answer, in what
    // order" is its declared member list and honouring an ad-hoc list too would mean two lists
    // deciding one thing. REMOVED with the override itself (6j6v.dvyq §3) — the guard's premise was
    // that a caller could supply a second list, and no caller can. The property it protected is now
    // structural: `fan_out_targets` reads the declaration and nothing else.
    // PREFLIGHT (3): every effective target must resolve — to a declared ROLE, or (nxf 6j6v.hq71) to
    // a declared CHANNEL, which is what a flow step may address exactly as `nxc send --to <name>`
    // always could. A broken member reference fails clean here, before the channel thread exists —
    // the declaration itself is not carried forward, because the persona path re-resolves it through
    // the catalogue at the moment of the trigger, which is the same discipline `fire_queued_trigger`
    // states at length: a declaration read now and used later is a declaration that can have changed
    // in between. **Since nxf 6j6v.n92p that re-resolution reads the version this OPERATION is bound
    // to**, so what it protects against is narrower than it was — an edit lands on the next
    // operation, not on this one — and the discipline itself is unchanged: nothing carries a
    // declaration across a wait.
    //
    // A channel target is resolved through `declared_channel`, so a step naming a channel whose own
    // declaration is malformed fails HERE rather than half way through the flow.
    let resolved: Vec<String> = effective
        .iter()
        .map(|(bare, _)| match flow_step_is_channel(ctx, bare) {
            // Through `declared_channel`, so a step naming a channel whose own declaration is
            // malformed fails HERE rather than half way through the flow.
            true => ctx.defs.declared_channel(bare).map(|_| bare.clone()),
            false => ctx.defs.role(bare).map(|_| bare.clone()),
        })
        .collect::<Result<_>>()?;

    // PREFLIGHT (4): what the declared window MEANS, resolved ONCE, here (nxf 6j6v.nf38).
    //
    // `ChannelDecl.timeout` is an opaque string the loader stores verbatim and does not interpret
    // (`channel.rs` says so at the field). This is where it is interpreted, and it is the only place
    // the AUTHOR'S string is read at all: `facade::resolve_deadline_spec` yields both halves of ONE
    // parse — the absolute instant the board falls due at, and the window a member's clock is
    // restarted by. What travels on to `facade::ask` below is that resolved instant, not the original
    // string, so the two values cannot come from two readings that could disagree.
    //
    // **An unreadable value is a `validation` error, never a silent "no cap"**, and that is why it
    // is a PREFLIGHT: a typo'd `timeout` that quietly meant "wait forever" is the failure nobody
    // notices, and this module fails loudly on bad declarations BEFORE anything is persisted. The
    // argument NAME travels with it so the message blames what the author actually wrote — a
    // channel's declared `timeout`, or the `deadline` a caller passed — rather than always the flag.
    //
    // **The label is `deadline` and no longer `--deadline`** (nxf 6j6v.ckeq, decision 2): the CLI
    // flag it named is gone, and `SendToRequest` no longer carries the field, so no path from the
    // command line or the app seam reaches this arm any more. It stays reachable — and so stays
    // labelled — for `orchestration::channel_open`, which is a crate verb its own callers still
    // construct a request for. Naming a flag nobody can type would blame the reader for a value
    // they cannot have written.
    let (deadline_arg, deadline_arg_name) = match req.deadline {
        Some(explicit) => (Some(explicit), "deadline"),
        None => (
            channel.timeout.as_deref(),
            "the channel's declared `timeout`",
        ),
    };
    let deadline_spec = match deadline_arg {
        Some(when) => Some(facade::resolve_deadline_spec(
            ctx.now,
            when,
            deadline_arg_name,
        )?),
        None => None,
    };
    let idle_window = deadline_spec.as_ref().and_then(|s| s.window);

    // Preflight passed — only now materialise the channel and open the CHANNEL THREAD.
    let decl_id = ensure_declared_channel(ctx, store, channel)?;
    let refs = with_working_copy(ctx, with_return_address(ctx, req.refs.clone()));
    // The channel thread hangs under whatever thread this caller is sending FROM (nxf 6j6v.a71h
    // §3.1) — the `send --to <channel>` entrance of the tree, the twin of the
    // `send --to <persona>` one in `surface::open_thread`.
    //
    // **Unless the caller NAMES the parent** (nxf 6j6v.hq71): a channel opened as a STEP of another
    // channel's declared flow is opened by the supervisor, which has no session for
    // [`ambient_parent`] to find — so the step's own channel thread would become a ROOT and the
    // operation would fall in two. The same explicit-parent split [`open_child_thread`] already has,
    // and for the same reason.
    let parent = match parent {
        Some(named) => Some(named.to_string()),
        None => ambient_parent(ctx, store),
    };
    let supervisor = supervisor_qualified(ctx.origin);
    let receipt = facade::ask_under(
        store,
        facade::AskRequest {
            now: ctx.now,
            origin: ctx.origin,
            actor: ctx.actor,
            channel: &decl_id,
            body: req.body,
            // EXACTLY TWO ENDS (nxf 6j6v.pf6j): the requester opened this thread and the supervisor
            // owes the answer on it. The members are not ends of it — they are ends of their own
            // threads, one each, below this one. `expects` (the effective member set derived above)
            // is what the supervisor fans out to, never what this register names.
            expect: std::slice::from_ref(&supervisor),
            // The instant PREFLIGHT (4) already resolved, not the string it resolved it from. An
            // explicit `--deadline` wins over the channel's declared `timeout` up there, and any
            // duration arithmetic happened there too — what `facade::ask` receives is an absolute
            // RFC3339 instant, which it re-reads as itself.
            deadline: deadline_spec.as_ref().map(|s| s.at.as_str()),
            kind: req.kind,
            priority: req.priority,
            refs,
        },
        parent.as_deref(),
    )?;

    // **BIND THIS OPERATION TO THE DECLARATIONS AS THEY ARE NOW** (nxf 6j6v.n92p) — one of the two
    // places an operation is opened, and therefore one of the two places the version in force is
    // fixed. `INSERT OR IGNORE` under the tree's ROOT, so a channel opened as a STEP of an outer
    // flow binds nothing: it is inside an operation that is already bound, and the outer binding is
    // the one that must govern its steps too.
    //
    // Immediately after the channel thread exists and BEFORE the fan-out below reads a single
    // declaration, so the very first step already runs under the version this call is binding. A
    // freeze taken later — at the first reply, say — would leave the gap between opening and the
    // first answer unguarded, which is exactly the gap a hurdle is meant to close.
    store.freeze_declarations(&store.thread_root(&receipt.thread_id)?, ctx.now, ctx.defs)?;

    // The channel's own head thread, named on the same rule the persona coordinator applies (nxf
    // 6j6v.e76c): this function OPENS this thread, so it names it. The member threads below it are
    // opened by the supervisor from this same body and are deliberately left unnamed.
    commission_thread_name(ctx, &receipt.thread_id);

    // Schedule the one-shot deadline re-check. Best-effort by design: a scheduling failure (no
    // `at`/`atd`) must not fail an already-persisted board — it just loses the automatic nudge.
    //
    // **This schedules the FIRST instant the window falls due; the job then moves itself** (nxf
    // 6j6v.nf38). Each member's clock is restarted by its own transcript, so a job firing here may
    // find every member alive — and `tick` then declines AND re-arms for the next instant a
    // member falls due ([`rearm_member_window`]). That chain is what keeps the automatic strike
    // alive: an `at` job fires exactly once, so a decline that scheduled nothing would spend the
    // whole mechanism on the first sign of life a member gave.
    //
    // **The chain belongs to THIS turn.** It ends when the set settles — which is what a completing
    // reply does — so a second turn does not inherit it; `supervisor_hand_out_next_turn` starts the
    // next one where it restarts the members' clocks.
    if let Some(deadline) = &receipt.deadline {
        if let Err(e) = ctx.timer.schedule(
            &receipt.thread_id,
            deadline,
            &crate::timer::tick_command(&receipt.thread_id),
        ) {
            // **Reported, not only breadcrumbed** (nxf 6j6v.p3sm). Without the tick this board's
            // declared `timeout:` is inert — `member_set_is_settled` reads `complete || stale`, and
            // nothing ever makes it stale — so a member that goes quiet holds the round forever.
            // That is precisely the case the window was declared for, and the caller used to be told
            // about it on stderr alone while its `--json` receipt said `warnings: []`.
            let detail = format!(
                "scheduling a timeout tick for thread {} failed: {e} — this board's declared \
                 `timeout` will not fire; run `nxc tick --thread {}` to check it by hand",
                receipt.thread_id, receipt.thread_id
            );
            eprintln!("warning: {detail}");
            findings.push(FailedConsequence::tick_unscheduled(
                &receipt.thread_id,
                detail,
            ));
        }
    }

    // The supervisor takes it from here — synchronously, inside this same write path. It opens the
    // channel's declared FLOW below the channel thread and STARTS it; what is waited on is the
    // starting, not the answer (nxf 6j6v.hq71 §1). How much of the flow starts now is what
    // `flow:` declares — every member at once, or the first step alone.
    supervisor_fan_out(
        ctx,
        store,
        findings,
        &SupervisorFanOut {
            channel,
            channel_id: &decl_id,
            channel_thread: &receipt.thread_id,
            body: req.body,
            members: &resolved,
            deadline: receipt.deadline.as_deref(),
            idle_window,
            kind: req.kind,
            priority: req.priority,
            model: req.model,
        },
        hop,
    )?;

    Ok(receipt)
}

// ---- the channel SUPERVISOR (nxf 6j6v.pf6j, and its declared FLOW, nxf 6j6v.hq71) --------------
//
// A declared channel has TWO LEVELS, and the supervisor stands between them:
//
//     T4   requester  <-> supervisor        the channel thread — exactly two ends
//     T5a  supervisor <-> reviewer-a        one thread PER STEP of the flow, hung under T4
//     T5b  supervisor <-> reviewer-b
//     T5c  supervisor <-> reviewer-c
//
// **Its ORDER is declared** (nxf 6j6v.hq71). `flow: parallel` — every channel written before that
// field existed — opens all of those at once, as drawn. `flow: sequential` opens T5a alone and T5b
// only once T5a has settled, which is what makes a channel a "real" workflow in the draft's own
// words: the same term with a fixed order. A step may also address a whole CHANNEL, in which case
// the slot under T4 is that channel's own channel thread and its answer is that channel's
// consolidation.
//
// It is MACHINERY OF THE ENGINE (see `channel::SUPERVISOR_HANDLE`): there is no session behind it,
// nothing resumes it and nobody waits for it to decide anything. It runs in exactly two moments,
// both of them inside a write path that is still returning to its caller:
//
//  * INCOMING — a `send --to <channel>` (and a follow-up `reply` into the channel thread) lands at
//    the supervisor and IT opens the per-step sends. That is what makes "a channel is a flow" true
//    rather than aspirational: only an incoming router can impose an order.
//  * OUTGOING — a step's reply discharges its own thread's single obligation, the supervisor asks
//    whether the SET of step threads is settled, and if it is, either starts the next step (an
//    ordered flow that has one left) or consolidates.
//
// **The quorum mechanic is rebuilt here, not extended.** What waits is no longer a THREAD with N
// expected handles; it is the supervisor waiting for N THREADS, each with one. The set is derived
// from the tree (`ChatStore::supervised_children`) rather than recorded, so opening a member thread
// under the channel thread IS the membership, and a per-member deadline hangs where exactly one session
// stands — which is what makes it RESETTABLE from that session's transcript (nxf 6j6v.nf38,
// `member_deadline.rs`).
//
// ---- HOW TO SCOPE A READ IN HERE, because getting it wrong has a track record ------------------
//
// Four times in this work order the same defect shipped past review: a predicate written over a
// thread's LIFETIME inside machinery scoped to the TURN. It was `replied` (nxf 6j6v.cg8g), then the
// assignee guard (6j6v.a71h), then `collected_replies` (6j6v.pf6j). Each time the code looked right,
// each time an existing test stayed green, and each time it was wrong from turn two on — which is the
// NORMAL case in this model. So, before adding a read that asks the RECORD about a thread's history,
// put it in one of these four categories and say which.
//
// (Not every read is one of these. A read that asks nothing about what has been said or what a thread
// is — `wake_role_requester`'s `addr.is_empty()`, a presence or shape check on a value already in
// hand — is outside the taxonomy and needs no category. The test is whether the answer could differ
// between turn one and turn five; if it could not, this section has nothing to say about it. But if
// you cannot place a read that COULD differ, that is the signal to stop and think, not to skip.)
//
//  1. **What was SAID** — must be turn-scoped, through `after_the_declaration` and nothing else
//     (`ChatStore::messages_since_the_declaration`, `replies_since_the_declaration`,
//     `last_reply_kind` — which `last_reply_escalated` and the working-tree claim both read, so the
//     answer to "what did this turn say" has ONE definition and two questions asked of it — and the
//     `complete`/`outstanding` that `thread_quorums` derives). Never a second copy of that
//     comparison: one definition is what keeps "who owes" and "who answered" from meaning two things
//     in adjacent fields of the same JSON object. It is also what makes the working-tree hold
//     SELF-CLEARING: re-declaring a turn moves the watermark, so a hand-back stops being this turn's
//     answer the moment the turn is re-opened (nxf 6j6v.1xw1).
//
//     **The one exception is category 4, and it is narrow**: where the watermark is written AFTER the
//     message you need, "since the declaration" cannot name it and no copy of the comparison would
//     help. Read 4 before concluding that this category forbids what you are about to write.
//  2. **What a thread IS** — opener, parent, channel — must NOT be turn-scoped. These are immutable
//     for a thread's life, and asking them per turn would invent a question the record cannot answer.
//     `supervised_children`, `lease_claim_root`, `facade::requester_of` are all this.
//  3. **An IDENTITY carried by something that was said** — a lifetime read, deliberately, and only
//     where the thing it names is itself lifetime-stable. That last clause is the ADMISSION TEST, and
//     it is the whole of the category: if the thing can differ between turn one and turn five, a
//     lifetime read of it is wrong, whatever it is called.
//
//     One member passes it: `supervisor_consolidate`'s root return address — an internal session id
//     is never re-minted on a resume, so the session that commissioned a thread on turn one is the
//     session still behind it on turn five.
//
//     One member **FAILS it**, and is here because it already shipped, not because it qualifies:
//     `facade::filter_board_messages`' "opening message" (the thread's first message stands for the
//     REQUEST, which is why a `requester_only` member still sees it). On a multi-turn thread that
//     message is turn ONE's request, so a member reading turn two's task through `threads show` sees
//     the wrong one. It is a known defect, parked with the owner, and it is listed here so the
//     category is not read as covering it. **A NEW read that fails the admission test is a defect,
//     not a limit case** — this one is not a precedent, and "mine is a limit case too" is the
//     misreading this paragraph exists to refuse.
//  4. **NEWEST-WINS** — "the last one of these", which is turn-scoped BY CONSTRUCTION only while
//     exactly one such message exists per turn. This is category 1's one exception, and the only
//     thing that earns it is that the watermark CANNOT answer: on the channel thread the
//     `set_expects` op is written AFTER the requester's message is durable, so "since the
//     declaration" would drop the very request the turn is about. Where the watermark can answer,
//     category 1 applies and this does not.
//
//     Two live here: `collected_replies`' request half and the forwarded body in
//     `supervisor_hand_out_next_turn`. Both are correct, and both rest on an assumption nothing
//     enforces (`reply` has no membership gate) — so a newest-wins read owes the reader the
//     assumption AND what breaks without it, at its own site. Note that the cost is NOT the same at
//     both: at `collected_replies` a stray message displaces a quoted line, while at
//     `supervisor_hand_out_next_turn` it becomes every member's next TASK. Work out your own site's
//     consequence rather than borrowing one.
//
// **A read whose answer differs per turn but that asks no MESSAGE anything** (nxf 6j6v.nf38). The
// per-member deadline is one: `quorum_sql`'s `COALESCE(md.deadline, t.deadline)` reads a device-local
// clock keyed on the thread, so none of the four categories describes it — yet its answer plainly
// differs between turn one and turn five, which is exactly when the escape hatch above says to stop
// and think rather than skip. What makes it turn-correct is not a predicate but a WRITE: the clock is
// re-armed at the start of every turn (`supervisor_fan_out` for the first, `reset_member_deadline` in
// `supervisor_hand_out_next_turn` for each one after), so there is no watermark to compare against
// because the stored value never belongs to a turn that is over. If you find yourself carrying
// per-turn state that is not a message, this is the shape: restart it where the turn is declared, and
// say so at both ends.

/// The channel supervisor's QUALIFIED identity for `origin` — the shape written into
/// `expects_reply_from` and compared against a thread's `opener`. Written once so the
/// bare-vs-qualified discipline `channel::SUPERVISOR_HANDLE` documents cannot be got wrong at one of
/// the several sites that need it.
pub fn supervisor_qualified(origin: &str) -> String {
    format!("{}/{}", origin, crate::channel::SUPERVISOR_HANDLE)
}

/// A [`Ctx`] that ACTS AS the supervisor: same workspace, same catalogue, same worker, different
/// actor.
///
/// This is how the supervisor gets to be a real party rather than a label. Everything below it goes
/// through the ordinary verbs — [`open_child_thread`] stamps the member thread with the supervisor as
/// its `opener`, [`coordinator_commission`] posts the task under the supervisor's own `sender` and
/// declares the member's obligation — because the actor those verbs read is this one. Nothing had to
/// grow an "opener" or "sender" override.
///
/// Two fields are deliberately NOT inherited:
///
/// * `session: None` — the supervisor has no session, no transcript and no way to be resumed.
///   Inheriting the caller's would stamp the caller's return address on the supervisor's posts, so a
///   member's answer would route back to whoever happened to be running instead of to the supervisor
///   that asked.
/// * `hop` — carried as the caller's already-RESOLVED depth. [`resolve_hop`] reads the authoritative
///   count off the caller's own session and the supervisor has none, so without this floor every
///   channel would restart the chain at zero and the depth guard would stop counting at the one place
///   a fan-out multiplies work.
fn as_supervisor<'a>(ctx: &Ctx<'a>, hop: CheckedHop) -> Ctx<'a> {
    Ctx {
        now: ctx.now,
        origin: ctx.origin,
        actor: crate::channel::SUPERVISOR_HANDLE,
        session: None,
        hop: hop.get(),
        defs: ctx.defs,
        worker: ctx.worker,
        timer: ctx.timer,
        namer: ctx.namer,
        db_path: ctx.db_path,
        project_claude_md: ctx.project_claude_md,
        module_primes: ctx.module_primes,
        machines: ctx.machines,
    }
}

/// **The catalogue an operation is bound to, as a context to act with** (nxf 6j6v.n92p).
///
/// Every verb that CONTINUES an operation calls this with the thread it was handed, and then works
/// with the returned context instead of the one it was given. That is one substitution per verb
/// rather than one per declaration read — and it has to be, because a chain reads declarations in a
/// dozen places (the channel a thread belongs to, the role a step names, the prompt a resumed
/// persona is composed from, the `working_tree` a lease is derived from) and a rule that held at
/// some of them would be no rule at all.
///
/// The frozen catalogue must be OWNED by the caller for the borrowed context to point at, so this
/// returns it and [`with_declarations`] joins the two. Two lines at each call site, which is the
/// price of `Ctx` borrowing its catalogue — and that borrow is what keeps every other verb from
/// cloning it.
///
/// `None` — no operation bound this thread — leaves the caller reading the folder, exactly as
/// everything did before this existed. See [`ChatStore::frozen_declarations`] for when that is the
/// right answer rather than a hole.
fn operation_declarations(
    ctx: &Ctx,
    store: &ChatStore,
    thread: &str,
) -> Result<Option<Definitions>> {
    store.frozen_declarations(&store.thread_root(thread)?, ctx.defs)
}

/// [`operation_declarations`]'s other half: the same context, reading the frozen catalogue.
///
/// Struct-update syntax rather than a field-by-field rebuild, deliberately — `Ctx` gained a field
/// twice in one epic, and a hand-written copy is where the next one gets forgotten.
fn with_declarations<'a>(ctx: &Ctx<'a>, defs: Option<&'a Definitions>) -> Ctx<'a> {
    match defs {
        Some(defs) => Ctx { defs, ..*ctx },
        None => *ctx,
    }
}

/// Everything one incoming fan-out needs. A struct rather than eleven positional parameters, for
/// [`RoleSpawn`]'s own stated reason.
#[derive(Clone, Copy)]
struct SupervisorFanOut<'a> {
    channel: &'a ChannelDecl,
    /// The materialised `decl:<name>` substrate id. Member threads live in it too — a member thread
    /// is a thread OF this channel, which is what keeps `working_tree`, `visibility` and the
    /// declared-channel reverse lookup resolving for it exactly as they do for the channel thread.
    channel_id: &'a str,
    channel_thread: &'a str,
    body: &'a str,
    /// The preflight-passed BARE member handles, in the channel's own order.
    members: &'a [String],
    /// The channel thread's resolved absolute deadline, stamped onto each member thread as well:
    /// with one thread per member the deadline hangs where exactly one session stands (nxf
    /// 6j6v.pf6j).
    deadline: Option<&'a str>,
    /// The WINDOW that deadline expresses, when it was declared as a duration (nxf 6j6v.nf38) —
    /// what each member's clock is restarted BY on every write to its session's transcript. `None`
    /// when the deadline names an absolute instant, which declares a point in time and has no
    /// window to be restarted by: such a deadline stays exactly as stubborn as it always was.
    idle_window: Option<time::Duration>,
    kind: MessageKind,
    priority: Priority,
    model: Option<Model>,
}

/// Open this channel's declared FLOW below the channel thread and start it.
///
/// **How much of it starts here is what `flow:` declares** (nxf 6j6v.hq71): a
/// [`Flow::Parallel`](crate::channel::Flow::Parallel) channel opens one thread per member and starts
/// them all, which is what every channel did before that field existed; a
/// [`Flow::Sequential`](crate::channel::Flow::Sequential) one opens the FIRST step and nothing else,
/// and [`supervisor_advance_flow`] opens each later step when the one before it settles.
///
/// **A ROLE member is addressed as a PERSONA** — [`coordinator_commission`], the same path
/// `send --to <persona>` takes — and that is the whole of acceptance point 4 (nxf 6j6v.pf6j): since
/// nxf 6j6v.jepk that path declares the expectation on the fresh thread it was handed and passes the
/// obligation on to the spawned session as `reply_thread`, so the thread-less trigger of nxf
/// 6j6v.rp8k (a role summoned with nothing to answer into and nobody expecting it) cannot arise on
/// this path at all. The old fan-out hand-rolled `trigger_role` and passed `reply_thread: None`,
/// which is precisely why the sidecar's `--if-unanswered` teardown net never fired for a channel
/// member.
///
/// A member's spawn failure still propagates — reaching `Ok` here means every member started, which
/// is what `surface::SendToReceipt::spawned` promises for the channel path.
/// [`coordinator_commission`]
/// reports such a failure in its receipt's `warnings` instead of erring (nxf 6j6v.hpv8), so it is
/// converted back here. **That stayed so under nxf 6j6v.93zd, deliberately** — see
/// [`SpawnFailure::Propagated`]'s own doc for the argument, which is that a propagated fan-out
/// failure is loud and discards nothing, and 93zd's subject is the failures that are silent.
fn supervisor_fan_out(
    ctx: &Ctx,
    store: &mut ChatStore,
    findings: &mut Vec<FailedConsequence>,
    req: &SupervisorFanOut,
    hop: CheckedHop,
) -> Result<Vec<String>> {
    // **The declared FLOW decides how many of them start now** (nxf 6j6v.hq71). `Parallel` — every
    // channel declared before that field existed — starts all of them, unchanged. `Sequential` starts
    // the FIRST declared step and nothing else; the rest do not exist yet, and each is opened by
    // [`supervisor_advance_flow`] once the one before it has settled. `req.members` is non-empty:
    // PREFLIGHT (2a) refused an empty effective set before anything persisted.
    // **A STEPPED channel opens its FIRST DECLARED STEP and nothing else** (nxf 6j6v.553s (d)),
    // and it opens it by the step's own target rather than out of `req.members` — on such a channel
    // `members:` is who belongs here, not what runs. Everything after this block is the
    // `parallel`/`flow: sequential` fan-out, untouched.
    if req.channel.is_stepped() {
        return supervisor_open_first_step(ctx, store, findings, req, hop);
    }
    let steps: &[String] = match req.channel.flow {
        crate::channel::Flow::Parallel => req.members,
        crate::channel::Flow::Sequential => &req.members[..1],
    };
    let sup = as_supervisor(ctx, hop);
    let mut opened = Vec::with_capacity(steps.len());
    for target in steps {
        // **`opened` travels INTO the gate** (nxf 6j6v.2d00). On a `parallel` channel this loop is
        // ONE pass — its members are the same step, not each other's previous one — and it has
        // already spawned the ones before this target, whose sessions are alive by the time the
        // next member's gate runs. Without this the brought-along hurdle read them as an earlier
        // step still writing and failed the whole `send --to <channel>`; see `preconditions_hold`.
        match open_flow_step(&sup, store, req, target, None, findings, &opened)? {
            StepOpened::Opened(thread) => opened.push(thread),
            // **A refused fan-out is LOUD** (nxf 6j6v.n92p). This runs inside the write path of the
            // `send --to <channel>` that asked, with the requester waiting on the return — so the
            // refusal travels back as the answer to that call rather than as a warning on a receipt
            // that would otherwise read like a started channel. It is the same treatment a member's
            // spawn failure has always had on this path (see this function's own doc), which is why
            // it adds a reason to an existing contract instead of changing one.
            //
            // `Forbidden` and not `Validation`: nothing about the declaration or the call is
            // malformed. A rule looked at the world and said not yet, and saying that with the kind
            // reserved for "you wrote this wrongly" would send the requester to fix the wrong thing.
            StepOpened::Refused(refusal) => {
                return Err(NxfError::forbidden(
                    refusal.detail(target, &req.channel.name),
                ))
            }
        }
    }
    Ok(opened)
}

/// **Open step one of a stepped channel's run** (nxf 6j6v.553s (d)) — [`supervisor_fan_out`]'s
/// branch for a declaration whose flow is a state machine.
///
/// It differs from the `flow: sequential` branch beside it in exactly two ways, and both are the
/// point of the field: the target comes from [`ChannelDecl::first_step`] rather than from
/// `members[0]`, and the slot is STAMPED with the run and the step it serves so a later back edge
/// cannot make two occurrences of one step indistinguishable.
///
/// A channel that declares `steps:` has at least one (an empty list reads as "no steps declared"),
/// so `None` here means the declaration is empty of steps and there is nothing to start — reported
/// as a started-nothing rather than an error, exactly as an unstartable step is.
fn supervisor_open_first_step(
    ctx: &Ctx,
    store: &mut ChatStore,
    findings: &mut Vec<FailedConsequence>,
    req: &SupervisorFanOut,
    hop: CheckedHop,
) -> Result<Vec<String>> {
    let Some(first) = req.channel.first_step() else {
        return Ok(Vec::new());
    };
    let Some((run, _)) = current_request(store, req.channel_thread)? else {
        return Ok(Vec::new());
    };
    let entry = StepEntry {
        mark: crate::store::FlowMark {
            run,
            step: first.id.clone(),
        },
        // The run's FIRST step, so there is nothing of this run's to continue whatever the
        // declaration says — the derivation below simply finds no earlier slot. The declared value
        // is honoured rather than hardcoded so this reads like every other step opener.
        resume: first.resume.unwrap_or(false),
        // …and nothing of this run's to be given, for the same reason: the first step of a run has
        // no predecessor, so its default is the request (nxf 6j6v.s0k5).
        from: None,
    };
    let sup = as_supervisor(ctx, hop);
    // **Step one may declare `input:` as well** (nxf 6j6v.s0k5), and the one form that means
    // anything there is `input: []` — a step that works from its own instructions rather than from
    // what the channel was asked. `None` is "the request", which `req.body` already IS on this
    // path, so an ordinary opening is byte-identical and re-derives nothing.
    //
    // Derived HERE rather than inside [`open_flow_step`], where the other three entrances meet:
    // that function is reached with a body its caller has already decided (a rework notice on the
    // back edge, the request on this one), and moving the decision into it would put two authors on
    // one string.
    let carried = step_input_body(&sup, store, req.channel_thread, &entry, first)?;
    let req = &match carried.as_deref() {
        Some(body) => SupervisorFanOut { body, ..*req },
        None => *req,
    };
    match open_flow_step(&sup, store, req, &first.target, Some(&entry), findings, &[])? {
        StepOpened::Opened(thread) => Ok(vec![thread]),
        // Loud, for [`supervisor_fan_out`]'s own reason: this runs inside the write path of the
        // `send --to <channel>` that asked, and a receipt that reads like a started channel over a
        // channel that started nobody is the shape nxf 6j6v.n92p refused.
        StepOpened::Refused(refusal) => Err(NxfError::forbidden(
            refusal.detail(&first.target, &req.channel.name),
        )),
    }
}

/// Whether a flow step's target names a declared CHANNEL rather than a declared role — the ONE
/// tie-break, delegated to [`crate::channel::flow_step_target`] so the preflight, the step opener and
/// `validate_channels` cannot answer it three ways. A role wins a name both declare; see that
/// function for why.
///
/// Takes any [`Ctx`] — it reads only the declaration catalogue and has no supervisor precondition,
/// unlike [`open_flow_step`] below it.
fn flow_step_is_channel(ctx: &Ctx, target: &str) -> bool {
    matches!(
        crate::channel::flow_step_target(ctx.defs.roles(), ctx.defs.channels(), target),
        Some(crate::channel::FlowStepTarget::Channel(_))
    )
}

/// Open ONE step of a channel's flow below the channel thread and start it.
///
/// Two shapes, one per kind of target a step may address — the same two `nxc send --to <name>` has
/// always reached (nxf 6j6v.hq71):
///
/// * a declared ROLE — the member thread nxf 6j6v.pf6j introduced: two ends, the supervisor and the
///   member, with the member addressed as a PERSONA through [`coordinator_commission_in`];
/// * a declared CHANNEL — that channel's OWN channel thread, opened under this one, with the
///   supervisor as its requester. It is a step exactly like a role is: it owes one answer on one
///   thread, and what it hands back is its own consolidation. Its members are its own business.
///
/// `sup` must already BE the supervisor ([`as_supervisor`]): the opener of the thread and the sender
/// of the task are read off it.
fn open_flow_step(
    sup: &Ctx,
    store: &mut ChatStore,
    req: &SupervisorFanOut,
    target: &str,
    entry: Option<&StepEntry>,
    findings: &mut Vec<FailedConsequence>,
    opened_in_this_pass: &[String],
) -> Result<StepOpened> {
    // **THE HURDLES, AND THEY RUN HERE BECAUSE HERE IS BEFORE THE TRIGGER** (nxf 6j6v.n92p,
    // decision 2). Once `coordinator_commission_in` below has run, the session is up and the damage
    // is up with it — so the check goes ahead of every write this function makes, not merely ahead
    // of the spawn: a refused step leaves no slot thread, no deadline and no armed clock behind, and
    // the absence of a slot is what tells every later reader that nothing was started.
    //
    // This is the ONE seam all four entrances meet at (`supervisor_fan_out` for a channel opening,
    // and `supervisor_advance_flow` reached from a reply, from a `tick`, or from a requester's
    // follow-up), which is the whole reason the gate is here and not at any of them.
    if let Some(refusal) = preconditions_hold(sup, store, req, opened_in_this_pass)? {
        return Ok(StepOpened::Refused(refusal));
    }
    // **WHICH STEP OF WHICH RUN, written down on the slot** (nxf 6j6v.553s (d)) — the one thing
    // about a stepped flow that is recorded rather than derived, stamped on the commission that
    // opens the slot so it is durable before the session it starts can answer.
    //
    // `None` for a channel that declares no `steps:`, and then this is `Refs::default()` — the
    // literal every pre-existing path wrote, so a `parallel` fan-out and a `flow: sequential` step
    // are byte-identical to what they were.
    let refs = match entry {
        Some(e) => Refs {
            flow_run: Some(e.mark.run.clone()),
            flow_step: Some(e.mark.step.clone()),
            ..Refs::default()
        },
        None => Refs::default(),
    };
    let opener = sup.caller_handle();
    // A step naming a declared CHANNEL. Resolved through `declared_channel` for its fail-closed
    // re-check, and cloned because the fan-out below needs `store` mutably while `sup.defs` is
    // borrowed.
    if flow_step_is_channel(sup, target) {
        let nested =
            sup.defs.declared_channel(target)?.cloned().ok_or_else(|| {
                NxfError::not_found(format!("no such declared channel: {target}"))
            })?;
        let receipt = open_declared_channel_and_fan_out(
            sup,
            store,
            &nested,
            &ChannelOpenRequest {
                channel: target,
                body: req.body,
                // Its own declared policy decides who answers inside it, and its own declared
                // `timeout` governs its members. What the outer flow's window means for this step is
                // decided below, once, rather than pushed down as a second opinion about the
                // members inside it.
                deadline: None,
                kind: req.kind,
                priority: req.priority,
                refs: refs.clone(),
                model: req.model,
            },
            Some(req.channel_thread),
            // A nested channel's own tick findings belong to the call that is opening it — there is
            // one operation and one caller, and a warning that stopped at this frame would be lost.
            findings,
        )?;
        // The outer flow's own window, stamped on this step only where the step declares none of its
        // own. Without it an outer channel with a `timeout` would wait forever on a step whose
        // channel declares none — `member_set_is_settled` reads `complete || stale`, and a thread
        // with no deadline is never stale. There is no idle WINDOW to arm here the way a role step
        // gets one: a channel step has no single session behind it, so there is no one transcript
        // whose writes are its sign of life (its members each have their own).
        if nested.timeout.is_none() {
            if let Some(deadline) = req.deadline {
                store.set_deadline(&receipt.thread_id, deadline, &opener);
            }
        }
        return Ok(StepOpened::Opened(receipt.thread_id));
    }

    // **WHICH session, re-derived from the record** (nxf 6j6v.y1t9). The step's declaration decided
    // WHETHER to continue one (that is [`StepEntry::resume`], resolved against the edge by the
    // caller that knows which edge it took); this is the other half, and it is read back off the
    // run rather than carried across the wait, for the reason `supervisor_advance_flow` gives for
    // everything else it re-derives.
    //
    // **BELOW the channel branch, because only a ROLE step can use the answer** — the fan-out above
    // never reads it, a channel having no one session behind it. It sat above that branch for one
    // round of this item, with an early return inside the derivation to match; the review of PR
    // #402 asked for a test of that early return, and the mutation written to answer it showed the
    // branch had no observable behaviour at all (removing it, and the guard behind it, changed
    // nothing). So the question is simply not asked where it cannot be answered — which also
    // spares a channel step the slot walk it was paying for and throwing away.
    //
    // **BEFORE this pass's own slot exists**, which is why it still stands above the line that
    // opens it: the derivation walks the run's slots, and a slot opened one statement earlier would
    // be in that walk. It would answer `None` there anyway (nothing has run in it), so this
    // ordering is not what makes the code correct today — it is what keeps the question honest:
    // "who has already run in this run" must not be able to see the pass that is only now
    // beginning.
    //
    // `None` — nothing to continue — is the ordinary first pass, not a failure: a run that has
    // never put this target in motion simply starts it.
    let continued = match entry.filter(|e| e.resume) {
        Some(e) => session_to_continue(store, req, e, target)?,
        None => None,
    };
    // The member's OWN thread, hung under the channel thread — stamped through the one function
    // that writes a tree edge (nxf 6j6v.a71h §3.1). The parent is named explicitly rather than
    // resolved from the ambient session, which is exactly the split that helper was given.
    let member_thread = open_child_thread(sup, store, req.channel_id, Some(req.channel_thread));
    if let Some(deadline) = req.deadline {
        store.set_deadline(&member_thread, deadline, &opener);
    }
    let started = coordinator_commission_in(
        sup,
        store,
        Commission {
            machine: None,
            role: target,
            body: req.body,
            channel: Some(req.channel_id),
            kind: req.kind,
            priority: req.priority,
            disposition: Disposition::InTurn,
            continue_session: continued,
            // The member thread this function opened two lines up, because it has to exist and
            // carry the board's deadline BEFORE the member is started — the one caller that cannot
            // let the coordinator open its own (see `Commission::thread`).
            thread: Some(&member_thread),
            refs,
            model: req.model,
        },
        // A flow step is the channel supervisor's commission, not the persona coordinator's, and
        // this body cannot tell which by being in it (nxf 6j6v.ntp9).
        Coordinator::Channel,
        SpawnFailure::Propagated,
    )?;
    // Arm this member's clock (nxf 6j6v.nf38). AFTER the trigger, because the session it names
    // is the one the trigger minted — the single session standing on this thread, and therefore
    // the only transcript whose writes are a sign of life FROM THIS MEMBER.
    //
    // **A QUEUED trigger (the working-tree lease made it wait) is armed here too, and it does
    // not keep this window.** It has minted its session, so there is a clock to arm — but it has
    // run nothing and produces no transcript to restart itself with, so a window running from
    // here would be spent in the queue and the member consolidated away before it ever worked.
    // [`fire_queued_trigger`] restarts it when the trigger actually fires, and arming it here is
    // exactly what lets it: the reset is an UPDATE, so it moves an armed clock and creates none.
    // Skipping the arming for a queued trigger would therefore not postpone its window — it
    // would leave the member on the stubborn op-folded instant this item exists to remove.
    if let (Some(deadline), Some(window)) = (req.deadline, req.idle_window) {
        store.arm_member_deadline(
            &member_thread,
            &started.session,
            window.whole_seconds(),
            deadline,
        )?;
    }
    Ok(StepOpened::Opened(member_thread))
}

/// **What [`open_flow_step`] did** — opened the step, or was stopped by a hurdle.
///
/// A typed outcome rather than an `Err`, because the two callers have to answer a refusal
/// DIFFERENTLY and neither answer is "the call failed":
///
/// * [`supervisor_fan_out`] is inside the write path of the `send --to <channel>` that asked, and a
///   live requester is waiting on its return. A channel that started nobody must not hand back a
///   receipt that reads like a started one, so the refusal becomes a loud
///   [`ErrorKind::Forbidden`](nxs_foundation::error::ErrorKind::Forbidden) error — exactly what a
///   member's spawn failure has always done on that path, one more reason on an existing contract.
/// * [`supervisor_advance_flow`] runs in the write path of a reply that is already durable, where
///   nothing after the post may fail the call. There the refusal becomes a
///   [`ConsequenceClass::PreconditionRefused`] finding on that reply's own receipt.
///
/// Distinguishing them by sniffing an error's `kind` would tie two unrelated things together — any
/// future `Forbidden` from deeper down would be read as a refusal — so the fork is in the type.
enum StepOpened {
    /// The step was opened; the string is the thread it stands on.
    Opened(String),
    /// A hurdle refused and NOTHING was written for this step.
    Refused(crate::precondition::Refusal),
}

/// **The session this run has already run for `target`, when the step being opened asks to continue
/// it** (nxf 6j6v.y1t9, part 3 of nxf 6j6v.553s).
///
/// Owner, 2026-08-31, on why the question is asked of the TARGET and not of the step id: *"wenn
/// einfach nur der naechste Schritt definiert wird, der zufaelligerweise an die gleiche Persona
/// geht, waere `resume: false`, aber wir koennen bei jedem Schritt `resume` auch festlegen"* — a
/// forward step onto the same persona is a case an author may deliberately turn ON, and it has no
/// earlier slot of its OWN id to find. So what is continued is *the party's* session in this run,
/// which is also the only reading under which the back edge's own notice ("what YOU handed over")
/// is true.
///
/// **Newest wins, and "newest" is the slot order.** `supervised_children` is `ORDER BY thread_id`,
/// a slot thread id is a ULID, and two slots of one stepped channel are never minted in the same
/// write path — the four-way enumeration in [`current_pass`] is that argument in full and it is
/// unchanged here.
///
/// **`None` on every one of three counts, and each is an ordinary state rather than a failure**:
/// the run has not run this target yet (the first pass); a slot that carries no session because its
/// trigger never started; and a mark whose step the declaration no longer has. Each falls back to a
/// fresh commission, which is the benign direction — the forward-edge behaviour, not something
/// nobody declared.
///
/// A CHANNEL target is not among them, and used to be: this returned early for one. The caller no
/// longer ASKS for a channel step (see its own comment), so the case cannot arrive — which is the
/// stronger form of the same answer, and the one that costs no walk.
///
/// **The real SDK id may be `None` and that is not a reason to refuse.** The INTERNAL session is
/// what nxc continues — the session map row, the thread position, the depth budget, the liveness
/// question all key on it — while `real_sdk_id` is only what the runtime needs to rehydrate a
/// transcript and is absent until a worker hands one back. [`supervisor_resume_member`] resumes on
/// exactly these terms, and this is the same act one level over.
fn session_to_continue(
    store: &ChatStore,
    req: &SupervisorFanOut,
    entry: &StepEntry,
    target: &str,
) -> Result<Option<ContinuedSession>> {
    for slot in store.supervised_children(req.channel_thread)?.iter().rev() {
        let Some(mark) = store.flow_mark(slot)? else {
            continue;
        };
        if mark.run != entry.mark.run {
            continue;
        }
        if req.channel.step(&mark.step).map(|s| s.target.as_str()) != Some(target) {
            continue;
        }
        // **`r.role == target` is a GUARD, not a filter, and it must survive a tidying refactor**
        // (independent review of PR #402, Code Quality #2). A slot holds one commission, so today
        // the newest row is always this target's and `.next_back()` would answer the same — which
        // is exactly the reasoning that would delete it. What it defends is a slot carrying a
        // session that is NOT this step's target, and the consequence of losing it is not a miss
        // but a WRONG ATTACHMENT: somebody else's transcript resumed under this step's obligation.
        //
        // Not reachable through any supported path within one run — `freeze_declarations` binds a
        // run to one declaration version, so a step's target cannot change under it — which is why
        // there is no regression test here and why this comment stands in place of one. A synced or
        // hand-edited log is not bound by that freeze, and this crate already treats the thread
        // graph as something a peer can hand it in any shape (`ChatStore::thread_root`,
        // `thread_subtrees`, and `slot_verdict_within`'s `seen` set all say so).
        if let Some(row) = store
            .sessions_in_thread(slot)?
            .into_iter()
            .rev()
            .find(|r| r.role == target)
        {
            return Ok(Some(ContinuedSession {
                internal: row.internal_id,
                real: row.real_sdk_id,
            }));
        }
    }
    Ok(None)
}

/// **Do this channel's hurdles let the next step start?** (nxf 6j6v.n92p) — the frame, in the order
/// the two classes are asked in.
///
/// `None` is a pass. `Some(refusal)` stops the step, and the FIRST refusal wins: nothing after it is
/// asked, so the answer names exactly one hurdle and the cost of a refused round is bounded by the
/// hurdle that refused rather than by the length of the list.
///
/// **BROUGHT-ALONG FIRST, DECLARED SECOND**, and the order is not cosmetic. The brought-along class
/// is what holds when nobody declared anything ([`crate::precondition::BUILT_IN_HURDLES`]), so a
/// declaration can never be what decides whether it is asked; and asking it first means a channel
/// whose previous step is still writing spends no processes finding that out.
///
/// **`opened_in_this_pass` is what the brought-along hurdle must NOT count** (nxf 6j6v.2d00). Its
/// question is whether an EARLIER STEP is still writing, and the members a `parallel` fan-out is
/// opening right now are not an earlier step — that channel has exactly one pass and they are all of
/// it. The loop above spawns them one after another, so by the time the second member's gate runs
/// the first one's session is alive; counting it refused the member, and on the fan-out path a
/// refusal fails the whole `send --to <channel>`. A four-member `working_tree: exclusive` quorum —
/// the shipped example's `review` — therefore could not be opened at all against a real worker: one
/// reviewer ran, the round died with `Forbidden`, and nothing was consolidated. Every test of this
/// gate declared `flow: sequential`, where the list is empty and nothing changes.
///
/// It excludes THESE THREADS rather than switching on the flow, because that is the actual property:
/// a step must not be gated on sessions its own call just started. An ORDERED advance passes an
/// empty slice and is untouched, down to the byte.
///
/// **The brought-along one asked here is nxf 6j6v.10yb's**, at the seam rather than at
/// [`supervisor_consider_set`] alone. That is what closes the entrance 10yb could not see:
/// [`supervisor_hand_out_next_turn`] starts a fresh pass of an ordered channel on a requester's
/// FOLLOW-UP, settling nothing and therefore passing through none of the checks a settled set runs
/// — so a second request while the first pass was still writing opened step one straight into the
/// same checkout. On the paths that DO come through a settled set the question has already been
/// answered `false` upstream, so asking it again is one query and cannot disagree.
///
/// **The cost, stated rather than discovered** (decision 4): one process start per DECLARED hurdle
/// per step. A quorum of four checkers with two declared hurdles is eight extra processes per round.
/// The brought-along one starts none — it is a store read plus
/// [`Worker::session_is_running`](crate::worker::Worker::session_is_running), which is a pid-file
/// read.
///
/// **And the cost in TIME is bounded, which is the half the first version left open** (PR #391
/// review, Code Quality #2 / Integrity & Robustness #2, raised independently by all three reviews).
/// [`crate::engine::Engine`] holds one mutex over its store for the whole of an orchestration verb,
/// and this runs inside it — so a channel that declares many hurdles, or a few slow ones, would
/// stall every other call through that handle for as long as the LIST takes. See
/// [`PRECONDITION_GATE_BUDGET`] for the bound and for why it is here rather than a cap on how many
/// hurdles a channel may declare.
fn preconditions_hold(
    sup: &Ctx,
    store: &ChatStore,
    req: &SupervisorFanOut,
    opened_in_this_pass: &[String],
) -> Result<Option<crate::precondition::Refusal>> {
    let siblings: Vec<ThreadQuorum> = supervised_member_threads(sup, store, req.channel_thread)?
        .into_iter()
        .filter(|q| !opened_in_this_pass.contains(&q.thread_id))
        .collect();
    if a_member_session_is_still_writing(sup, store, Some(req.channel), &siblings)? {
        return Ok(Some(
            crate::precondition::Refusal::previous_step_still_writing(&req.channel.name),
        ));
    }
    Ok(ask_declared_hurdles(
        &req.channel.preconditions,
        PRECONDITION_GATE_BUDGET,
        |command| sup.worker.run_precondition(command),
    ))
}

/// **How long ONE step's declared hurdles get, all of them together** (PR #391 review, Code Quality
/// #2 / Integrity & Robustness #2).
///
/// **This is the answer to "cap `preconditions.len()`?", and the answer is no.** A count cap is an
/// arbitrary number that constrains the wrong quantity: two hurdles that each take a minute are
/// worse than ten that take a millisecond, and any cap generous enough to be usable is still
/// `cap × bound` of stall. What actually matters is how long the engine's store mutex is held, so
/// that is what is bounded — and it is bounded independently of how many hurdles a channel declares,
/// which is the property a cap cannot give at any value.
///
/// **What it guarantees, exactly.** The budget is checked BEFORE each hurdle, so a step's gate
/// cannot RUN one after the budget is spent. It does not cut a hurdle short mid-flight: the last one
/// admitted still gets its own bound
/// ([`PRECONDITION_BOUND`](crate::worker::PRECONDITION_BOUND)), which belongs to the seam and not to
/// this loop — a host's own `run_precondition` has its own idea of a bound and this cannot reach
/// inside it. So the worst case is a hurdle admitted with a moment of budget left, i.e. a little
/// under two bounds, and it is INDEPENDENT OF N. That is the whole point.
///
/// **The residual, said out loud rather than discovered later:** a `parallel` fan-out opens one step
/// per member in a single call, and each step runs its own gate, so the OPENING of an N-member board
/// can still cost N budgets. That is the same multiplication `supervisor_fan_out` already has for
/// spawns, it is visible in the receipt, and narrowing it means moving the gate off the step — which
/// would break decision 2 (a hurdle is asked before the step it guards, not once for a set).
///
/// Sixty seconds rather than thirty: one slow-but-honest hurdle must not spend the whole budget and
/// starve the one after it, and a gate that is answering at all is worth waiting for a little longer
/// than a single command is.
pub const PRECONDITION_GATE_BUDGET: Duration = Duration::from_secs(60);

/// [`preconditions_hold`]'s declared half, with the executing seam and the budget as PARAMETERS.
///
/// Split out to be tested: the property that matters — a hurdle is never ASKED once the budget is
/// spent, and the refusal says so rather than blaming the project's rule — needs a slow answer and a
/// short budget, and neither is reachable through the real seam without waiting out
/// [`PRECONDITION_GATE_BUDGET`]. `ask` is `FnMut` so a test can count what it was asked.
///
/// The clock is [`std::time::Instant`] and not `ctx.now`, deliberately: this measures how long this
/// PROCESS has been holding a mutex, which is a monotonic duration on this machine and not a fact
/// about the workspace. `worker.rs` reads the same clock for the same kind of bound.
fn ask_declared_hurdles(
    hurdles: &[crate::precondition::Precondition],
    budget: Duration,
    mut ask: impl FnMut(&str) -> crate::precondition::PreconditionOutcome,
) -> Option<crate::precondition::Refusal> {
    let started = std::time::Instant::now();
    for hurdle in hurdles {
        if started.elapsed() >= budget {
            // Fail-closed, and reported as UNRUNNABLE rather than as a verdict: this hurdle never
            // ran, so saying the project's rule refused would blame the wrong thing.
            return Some(crate::precondition::Refusal {
                hurdle: hurdle.name.clone(),
                kind: crate::precondition::RefusalKind::Unrunnable,
                output: format!(
                    "the hurdles before it used up this step's whole {budget:?} budget, so it was \
                     never asked — the step is stopped rather than started unchecked. Make the \
                     earlier hurdles answer faster, or declare fewer of them"
                ),
            });
        }
        if let Some(refusal) = crate::precondition::verdict(hurdle, &ask(&hurdle.run)) {
            return Some(refusal);
        }
    }
    None
}

/// What the supervisor did about one reply — the five findings [`ReplyReceipt`] reports, so the
/// supervised path fills exactly the same receipt as the routing it replaces.
#[derive(Default)]
struct SupervisorRun {
    woke: Option<String>,
    wake_skipped: Option<WakeSkipped>,
    /// **The requester was working, so this channel's answer is HELD for it** (nxf 6j6v.gn8b;
    /// review of that branch) — the third outcome beside the two above, carried up into
    /// [`ReplyReceipt::held`] exactly as they are.
    ///
    /// It rides HERE and not only on [`CompletionRouted`] because the supervised path is the one a
    /// declared channel's member actually replies through: block (4b) of [`reply`] takes this whole
    /// record, so a field the supervisor did not carry would be a hold that happened and a receipt
    /// that never said so.
    held: Option<String>,
    completed: Option<CompletionOutcome>,
    /// **Everything the supervisor discovered that did not happen** (nxf 6j6v.93zd) — COMPLETE, not
    /// the remainder: it includes the finding `wake_skipped` above also carries, because the class
    /// of a failure is known here and not at the receipt (a member handed its next turn is a STEP,
    /// the requester of a consolidation is a WAKE, and a `WakeSkipped` alone cannot say which).
    /// [`reply`] takes this list as it stands; `debug_assert_one_place` is what checks that the
    /// `Option` fields beside it are represented in it.
    warnings: Vec<FailedConsequence>,
    /// **An ordered flow was moved on to its NEXT STEP by this run** (nxf 6j6v.ma7v) — as opposed to
    /// being consolidated, which since that item is the other thing a settled ordered set can lead
    /// to.
    ///
    /// It exists because one caller has to describe what it did and cannot re-derive it: [`tick`]'s
    /// [`TickMove::Advance`] branch reports a lapsed step with the sentence "the flow advanced to
    /// step X without it", and that sentence became a claim rather than a certainty the moment an
    /// escalating set could end the chain here instead. Inferring it from `completed` would be a
    /// second, indirect spelling — and a wrong one on the arm where a consolidation delivers
    /// nothing.
    ///
    /// `false` everywhere else, including on a `parallel` channel, which has no order to advance.
    advanced: bool,
}

/// The member threads under `channel_thread` — the SET the supervisor waits for.
///
/// Derived, never recorded: a child whose `opener` is the reserved supervisor identity is a member
/// thread of this channel, and nothing else can be (no declared role handle can name that identity).
/// A child opened by anybody else — a member that started its own conversation out of its thread —
/// is somebody's else's work hanging in the same tree and is not part of this quorum.
fn supervised_member_threads(
    ctx: &Ctx,
    store: &ChatStore,
    channel_thread: &str,
) -> Result<Vec<ThreadQuorum>> {
    supervised_member_threads_at(ctx.now, store, channel_thread)
}

/// [`supervised_member_threads`] with the clock alone, which is the whole of what it takes from a
/// [`Ctx`] — split out so a walk over this structure can be exercised without standing up a
/// catalogue, a worker and a timer for a question that reads two tables.
fn supervised_member_threads_at(
    now: &str,
    store: &ChatStore,
    channel_thread: &str,
) -> Result<Vec<ThreadQuorum>> {
    let children = store.supervised_children(channel_thread)?;
    let ids: Vec<&str> = children.iter().map(String::as_str).collect();
    store.thread_quorums(&ids, now)
}

/// The declared channel a thread belongs to, by the `decl:<name>` convention
/// [`ensure_declared_channel`] stamps. `None` for a thread in a plain substrate channel.
///
/// Deliberately the PLAIN lookup ([`Definitions::channel`]), not `declared_channel`: a declaration
/// edited into invalidity after a thread on it was opened must still be RECOGNISED here, exactly as
/// [`route_declared_channel_completion_with`] argues at its own site — the fail-closed re-check
/// belongs where the channel is acted on, not where it is identified.
fn declared_channel_of<'a>(ctx: &'a Ctx, q: &ThreadQuorum) -> Option<&'a ChannelDecl> {
    let name = q
        .channel_id
        .as_deref()?
        .strip_prefix(DECLARED_CHANNEL_PREFIX)?;
    ctx.defs.channel(name)
}

/// **Which flow step a slot thread serves ON A `flow: sequential` CHANNEL** (nxf 6j6v.hq71) —
/// derived from the thread, never recorded.
///
/// **Scoped to that flow, and since nxf 6j6v.553s (d) that scope is load-bearing.** A channel that
/// declares `steps:` may name the same target twice, so a target no longer identifies a step there;
/// its slots carry a recorded [`ChatStore::flow_mark`] instead, and every reader on that path asks
/// for the mark rather than calling this. Calling it there would answer with a name two steps can
/// share — which is the very defect `validate_channels`' check 6 refused a repeat to prevent.
///
/// Two shapes, matching [`open_flow_step`]'s two: a slot whose own `channel_id` differs from the
/// channel thread's is a nested CHANNEL step and names that channel; anything else is a ROLE step
/// and names the handle it expects. The discriminator is sound in both directions — a role slot
/// lives in the outer channel by construction, and a channel slot keeps its own `channel_id` even
/// after its consolidation retargets `expects` to an engine marker.
///
/// `None` for a slot whose expectation was dropped, which names no step at all.
fn slot_target(slot: &ThreadQuorum, channel_id: Option<&str>) -> Option<String> {
    match slot.channel_id.as_deref() {
        Some(own) if Some(own) != channel_id => own
            .strip_prefix(DECLARED_CHANNEL_PREFIX)
            .map(str::to_string),
        _ => slot.expects.first().map(|h| bare_handle_of(h).to_string()),
    }
}

/// **The declared flow of a `flow: sequential` `channel`, as the supervisor runs it** — the same
/// list [`open_declared_channel_and_fan_out`]'s own preflight derived when the channel thread was
/// opened, re-derived here from the declaration and the thread's recorded requester rather than
/// carried along.
///
/// **Not the answer for a channel that declares `steps:`** (nxf 6j6v.553s (d)): there the order is a
/// graph rather than a list, and `members:` is membership only. [`crate::channel::commissioned_names`]
/// is what answers "which of the two lists" where a reader genuinely has to ask; the supervisor's
/// stepped path never asks, because it walks the declaration's own edges.
///
/// **Two things could have made the re-derivation differ from the opened list, and both are refused
/// rather than tolerated** (nxf 6j6v.hq71, review round 1): `--expect`, by PREFLIGHT (2b), and a
/// declared `expects: <subset>`, by `channel::validate_channel_for_use` — which matters more than it
/// looks, because [`crate::channel::fan_out_targets`] returns a subset VERBATIM and would have made
/// the flow follow the subset's order and length instead of `members`'. With both refused, this
/// function and the fan-out read the same list for the same channel every time.
fn flow_steps(channel: &ChannelDecl, requester: Option<&str>) -> Vec<String> {
    crate::channel::fan_out_targets(channel, requester.map(bare_handle_of).unwrap_or_default())
}

/// **The request THIS RUN is serving, and its id** — the newest message on a channel thread from a
/// party that is not the engine (nxf 6j6v.553s (d)).
///
/// One derivation with two readers, deliberately: the BODY is the task every step of the run is
/// commissioned with, and the ID is what [`crate::model::Refs::flow_run`] stamps on each of that
/// run's slots. Reading them apart would let a run's slots be marked with one message while the
/// steps carried another's words.
///
/// **A run therefore begins when a new request lands and ends when the channel consolidates**, with
/// no state written down to say so: the requester's follow-up IS the new run id, and every counter
/// that hangs off a run starts over with it. That is where the owner's *"Bekommt er aber die
/// Erlaubnis von oben, wird max_passes wieder auf Null gesetzt"* comes from — not from a reset
/// anybody performs.
///
/// **It inherits `supervisor_hand_out_next_turn`'s NEWEST-WINS assumption**, stated there at
/// length: nothing gates who may post on a channel thread, so a stray message from a third party
/// becomes "the request". Here the cost is bounded and self-announcing rather than silent — the
/// run's existing slots stop matching the new id, [`slots_to_consolidate`] falls back to every slot
/// (its documented over-include), and the advance finds no step to be standing on and consolidates.
/// Closing it needs a membership gate on `reply`, which is nxf 6j6v.6aza's and not this function's.
///
/// **The SIGNATURE half is closed here, though** (nxf 6j6v.pzkb): the request is read only off
/// messages an agent action may follow, because its body is the instruction the run's steps are
/// handed. A message nobody on this replica can vouch for — unsigned, altered, or from an untrusted
/// key — is shown on the thread and never becomes a run's request. Who may post at all remains the
/// membership question above.
///
/// `None` for a channel thread that carries no non-engine message at all, which cannot arise for a
/// thread the supervisor is running: the request that opened it is one.
fn current_request(store: &ChatStore, channel_thread: &str) -> Result<Option<(String, String)>> {
    Ok(current_request_row(store, channel_thread)?.map(|m| (m.message_id, m.body)))
}

/// [`current_request`] with the ROW, for [`slot_answer_row`]'s reason: a step that is given the
/// request ALONGSIDE an answer reads it in an attributed block, and the attribution is the `sender`
/// column (nxf 6j6v.s0k5). One derivation for both readers, so the id a run's slots are marked with
/// and the words a step is given can never come from two different messages.
fn current_request_row(
    store: &ChatStore,
    channel_thread: &str,
) -> Result<Option<crate::store::MessageRow>> {
    Ok(store
        .acting_messages_in_thread(channel_thread)?
        .into_iter()
        .rev()
        // **AN ACCEPTANCE IS NOT A REQUEST, and that one line is what keeps `--accept` from doing
        // the very thing it exists to stop** (nxf 6j6v.am8j). A run begins when a new request lands
        // — the message id IS the run id — so without this filter the owner's `--accept` would
        // become the newest request, mint a run of its own, orphan every slot of the run it was
        // accepting, and start the flow over at step one: exactly the re-winding the ticket
        // measured, now spelled with the verb meant to end it. It is an override of a judgement
        // INSIDE the running round, so the round it belongs to is the one that was already there.
        //
        // Keyed on the KIND rather than on the sender, because the sender is the requester — the
        // same party whose ordinary follow-up genuinely IS a new run. The two are told apart by
        // what was said, which is the only thing that differs.
        .find(|m| !is_engine_identity(&m.sender) && m.kind != crate::model::KIND_ACCEPTED))
}

/// **The slot threads of the current RUN of a STEPPED flow** (nxf 6j6v.553s (d)) — every slot the
/// supervisor opened since the request now standing on the channel thread.
///
/// This is [`current_pass`]'s job for a channel whose flow is a state machine, and it cannot be done
/// the way that one does it. That derivation anchors a pass at "the newest slot serving the FIRST
/// declared step" — and a back edge normally points AT the first step, so the newest such slot is a
/// REWORK and everything the run had already done would fall outside its own pass, taking the
/// consolidation's answers with it. So a run says which one it is, once, on each slot it opens.
///
/// Order is preserved: the caller hands slots in `supervised_children`'s order and this only
/// filters.
fn run_slots(store: &ChatStore, slots: Vec<ThreadQuorum>, run: &str) -> Result<Vec<ThreadQuorum>> {
    let mut kept = Vec::new();
    for slot in slots {
        if store
            .flow_mark(&slot.thread_id)?
            .is_some_and(|m| m.run == run)
        {
            kept.push(slot);
        }
    }
    Ok(kept)
}

/// **The slot threads of the CURRENT PASS of an ordered flow** (nxf 6j6v.hq71).
///
/// A [`Flow::Parallel`](crate::channel::Flow::Parallel) channel has no passes — every slot belongs to
/// the one set, and this returns them all, which is what every channel did before this item.
///
/// **A STEPPED channel answers from its slots' recorded run mark instead** ([`run_slots`], nxf
/// 6j6v.553s (d)) — the anchor derivation below cannot survive a back edge, and that function says
/// why. Everything from the `Flow::Sequential` line on describes the flat-order derivation alone.
///
/// An ORDERED channel opens one slot per step and a FRESH slot for each step of each new pass, so its
/// children accumulate across passes. **A pass BEGINS at step one, and that beginning is what defines
/// it**: the anchor is the newest slot serving the first declared step, and the pass is that slot plus,
/// for each following step in declared order, the newest slot serving it that is NEWER THAN THE
/// ANCHOR — stopping at the first step nothing newer serves.
///
/// **The anchor is the correction of review round 3, and without it the derivation mixes passes.**
/// Round 2 took simply "the newest slot per step", which for a step the running pass has not reached
/// yet is the PREVIOUS pass's slot. Both orderings of the same two replies then went wrong: a
/// straggler's late answer read as the last step of a full pass and got folded into the newer
/// request's delivery, and — in the mirror ordering — the newer pass's own legitimate advance was
/// refused because a stale slot in the derived set was outstanding. A slot older than where this pass
/// began is not this pass's, and that is the whole of the rule.
///
/// **Never from the order the children come back in** — that was round 1's correction and it stands.
/// `supervised_children` is `ORDER BY thread_id`, a thread id is a ULID, and a ULID sorts by mint time
/// only to the MILLISECOND, after which the remaining bits are random; a PARALLEL fan-out mints every
/// slot of its set inside one write path, well inside one millisecond, so its children genuinely can
/// come back swapped. (The folded `threads` row order is no better, which is why that read was left
/// alone rather than re-ordered.) Matching each step to its own slot asks nothing of that order.
///
/// **What the anchor comparison DOES rest on, and why it is sound**: that two slots of one ORDERED
/// channel are never minted in the same write path. They are not, by construction, and here are ALL
/// THREE paths that mint one — the enumeration is the whole argument, so it is written out rather
/// than sampled (review round 4 caught it one short, and the one it was missing was the slot the
/// anchor IS):
///
/// 1. [`supervisor_fan_out`] — opens `members[..1]` for a sequential channel, exactly ONE slot, in
///    the write path of the `send --to <channel>` that opened it.
/// 2. [`supervisor_advance_flow`] reached from [`supervisor_consider_set`] — each later step of a
///    pass, in the write path of the REPLY that settled the step before it.
/// 3. [`supervisor_advance_flow`] reached from [`supervisor_hand_out_next_turn`] — **the step-one
///    slot of every pass after the first, and therefore the ANCHOR itself**, in the write path of the
///    requester's FOLLOW-UP. That write path settles no step, which is why it is easy to miss when
///    reasoning about (2); the conclusion survives untouched all the same, because a follow-up is
///    still its own separate call, a full round trip after whatever slot preceded it.
/// 4. [`supervisor_advance_flow`] reached from [`supervisor_consider_set`] **through [`tick`]** —
///    the step that follows one whose DEADLINE struck (nxf 6j6v.rs9k), in the write path of the
///    `nxc tick` a scheduled one-shot job runs. It is (2) with a lapse in place of the reply, and it
///    is the reason this enumeration gained a fourth entry rather than a fourth mechanism: the
///    supervisor's advance logic is entered the same way, with the settled slot handed in. A tick is
///    its own process and its own call, so it mints its one slot no closer to any other than a reply
///    does.
///
/// Each of the four is one slot in one call, and no call reaches two of them. So every pair of an
/// ordered channel's slots is separated by a real round trip — a reply or a request landing, and a
/// session spawning — and millisecond resolution decides it with room to spare. This is the
/// same-millisecond hazard's exact complement rather than a re-introduction of it: that hazard is
/// [`Flow::Parallel`](crate::channel::Flow::Parallel)'s, where one write path mints the whole set —
/// and where this function returns before the anchor comparison is ever reached.
///
/// Distinctness of steps is what makes "the slot serving step i" singular per pass, and
/// `channel::validate_channels`' check 6 plus the `expects`-subset refusal are what keep it so.
fn current_pass(
    store: &ChatStore,
    channel: Option<&ChannelDecl>,
    channel_q: &ThreadQuorum,
    slots: Vec<ThreadQuorum>,
) -> Result<Vec<ThreadQuorum>> {
    let Some(channel) = channel else {
        return Ok(slots);
    };
    // **A STEPPED channel answers this from the RUN MARK, not from the anchor below** (nxf
    // 6j6v.553s (d)) — see [`run_slots`] for why the anchor cannot survive a back edge. Everything
    // after this branch is the `flow: sequential` derivation, untouched.
    if channel.is_stepped() {
        let Some((run, _)) = current_request(store, &channel_q.thread_id)? else {
            return Ok(Vec::new());
        };
        return run_slots(store, slots, &run);
    }
    if channel.flow != crate::channel::Flow::Sequential {
        return Ok(slots);
    }
    let newest_serving = |step: &str, after: Option<&str>| -> Option<&ThreadQuorum> {
        slots
            .iter()
            .filter(|slot| {
                slot_target(slot, channel_q.channel_id.as_deref()).as_deref() == Some(step)
                    && after.is_none_or(|anchor| slot.thread_id.as_str() > anchor)
            })
            .max_by(|a, b| a.thread_id.cmp(&b.thread_id))
    };
    let steps = flow_steps(channel, channel_q.opener.as_deref());
    let Some(first) = steps.first() else {
        return Ok(Vec::new());
    };
    let Some(anchor) = newest_serving(first, None) else {
        return Ok(Vec::new());
    };
    let mut pass = vec![anchor.clone()];
    for step in &steps[1..] {
        match newest_serving(step, Some(&anchor.thread_id)) {
            Some(slot) => pass.push(slot.clone()),
            None => break,
        }
    }
    Ok(pass)
}

/// **The slots a CONSOLIDATION reads** — [`current_pass`], falling back to EVERY slot when the pass
/// cannot be derived (review round 2).
///
/// The two readers of a settled set pull in opposite directions, and this is where that is written
/// down. An ADVANCE must not over-include: a pass read too wide reports steps as already run and the
/// supervisor skips them, which is why [`supervisor_consider_set`] uses `current_pass` raw. A
/// CONSOLIDATION must not under-include: [`collected_replies`] answers an empty member list with the
/// channel thread's OWN messages — correct for a board that has no member threads at all, and badly
/// wrong for an ordered channel whose pass is underivable, because the requester's own request would
/// then be folded and delivered as the answer to it. [`set_escalated`] has the same shape one axis
/// over: an empty list answers `false`, and a lost escalation releases a working copy while a member
/// is stuck (nxf 6j6v.1xw1's malign direction).
///
/// So a consolidation over-includes rather than under-includes, and this preserves
/// `collected_replies`' original `is_empty()` meaning exactly: the list is empty here only when the
/// thread has no supervised children at all, which is the case that branch was written for.
///
/// **What reaches it**: an ordered channel whose step-one target no longer resolves to any slot —
/// `members` edited mid-flight so the first declared step is a name nothing served — consolidated
/// through the `tick` PULL path, which asks its own `due` question rather than
/// `supervisor_consider_set`'s (whose settled-set gate refuses an empty pass outright).
fn slots_to_consolidate(
    ctx: &Ctx,
    store: &ChatStore,
    channel_q: &ThreadQuorum,
) -> Result<Vec<ThreadQuorum>> {
    let all = supervised_member_threads(ctx, store, &channel_q.thread_id)?;
    let pass = current_pass(
        store,
        declared_channel_of(ctx, channel_q),
        channel_q,
        all.clone(),
    )?;
    Ok(if pass.is_empty() { all } else { pass })
}

/// The channel thread `thread` is a STEP OF, when it is one — i.e. its parent, if the supervisor is
/// what opened `thread`.
///
/// This is category 2 of the read taxonomy above ("what a thread IS"): opener and parent are
/// immutable for a thread's life, so this is deliberately not turn-scoped.
fn supervising_parent(store: &ChatStore, thread: &str) -> Result<Option<String>> {
    let Some(parent) = store.thread_parent(thread)? else {
        return Ok(None);
    };
    if store
        .supervised_children(&parent)?
        .iter()
        .any(|t| t == thread)
    {
        return Ok(Some(parent));
    }
    Ok(None)
}

/// **The supervisor, run synchronously in [`reply`]'s write path** (nxf 6j6v.hq71 §1, owner
/// 2026-08-14): the message is written, the obligation is recognised as discharged, the supervisor
/// runs, the next thread is opened and its sessions are STARTED, and only then does the call return.
/// What is waited on is the starting, never the result — the latency is a spawn.
///
/// The reason it is synchronous and not an event some worker picks up later is not latency: it is
/// that **only here does a failed consequence have an addressee**. Asynchronously the replying
/// session is already gone by the time the consequence runs, and a failure is noticed by nobody —
/// the "silent channel" class. Everything this function decides is therefore reportable in the
/// receipt of the very `reply` that caused it — and since nxf 6j6v.93zd it IS reported, in
/// [`ReplyReceipt::warnings`], which is what makes this paragraph a mechanism rather than a
/// possibility.
///
/// `Ok(None)` means **this reply has nothing to do with a channel's two levels** and the caller's own
/// routing applies unchanged — which is every reply outside a declared channel, and the channel
/// thread's own completing reply (the synthesizer's), which is an ordinary two-ended completion.
///
/// `Ok(Some(_))` means the supervisor owns this reply. That includes doing NOTHING: a member
/// answering while its siblings are still working is handled, and must not fall through to the
/// completion wake, which would hand the requester one member's raw answer as if the channel were
/// finished.
fn supervisor_after_reply(
    ctx: &Ctx,
    store: &mut ChatStore,
    thread_id: &str,
    sender: &str,
    said: MessageKind,
    body: &str,
    hop: CheckedHop,
) -> Result<Option<SupervisorRun>> {
    let supervisor = supervisor_qualified(ctx.origin);
    let Some(q) = store.thread_quorum(thread_id, ctx.now)? else {
        return Ok(None);
    };

    // (A) A MEMBER thread: the supervisor opened it, so it is one element of some channel thread's
    // set. Its own obligation is single-handled and was just answered (or was not — a follow-up from
    // the other end changes nothing about the set).
    //
    // **A nested CHANNEL step is not one of these, and the difference is load-bearing** (nxf
    // 6j6v.hq71). Since a flow step may address a channel, a supervisor-opened child can now BE a
    // channel thread — and such a thread owes its own consolidation first: a fold's phase-2 reply
    // lands here, and treating it as a member's answer would consolidate the OUTER flow while the
    // inner channel's own delivery never ran. Told apart by what the thread expects: a member slot
    // expects a real handle, a channel thread expects one of the engine's own reserved identities
    // (`__channel__` before it consolidates, `__synth__`/`__delivered__` after). What tells the outer
    // supervisor about a nested step is [`route_declared_channel_completion_with`]'s own hand-back,
    // which runs once the inner channel HAS delivered.
    let is_channel_thread = q.expects.iter().any(|h| is_engine_identity(h));
    if q.opener.as_deref() == Some(supervisor.as_str()) && !is_channel_thread {
        let Some(channel_thread) = store.thread_parent(thread_id)? else {
            // A member thread with no parent cannot exist through `supervisor_fan_out`; a synced
            // child whose parent has not folded here yet can. Deciding a set from a parent this
            // workspace cannot see would be deciding it from one member, so: handled, nothing done.
            return Ok(Some(SupervisorRun::default()));
        };
        return supervisor_consider_set(ctx, store, &channel_thread, thread_id, hop).map(Some);
    }

    // (B) A CHANNEL thread that already has member threads below it, answered by its own requester:
    // the supervisor is the INCOMING router in this direction too (nxf 6j6v.pf6j — "`pm -> send --to
    // #coding` lands at him, and HE opens `send --to <member>`"), and a follow-up into the channel
    // thread is the same door as the first message. This is where the next TURN is declared: nothing
    // else in the engine re-declares `expects_reply_from` on a resume, which is why a member's
    // teardown net had nothing to discharge from turn two on.
    let members = supervised_member_threads(ctx, store, thread_id)?;
    if !members.is_empty() && q.opener.as_deref() == Some(sender) {
        // **(B1) AN ACCEPTANCE IS THE OTHER THING A REQUESTER MAY SAY HERE** (nxf 6j6v.am8j), and it
        // is the opposite of the turn below it. A follow-up means "again", and again starts a NEW
        // run at step one — which is exactly what re-armed `max_passes` six times in the run this
        // item was opened on. This says "the verdict is overruled", and the SAME run continues from
        // the step that rejected.
        //
        // Everything that decides whether it may be said at all was established before the message
        // was posted ([`refuse_an_acceptance_that_cannot_be_honoured`]), so a kind that reaches here
        // is one this thread can honour. It is re-derived rather than carried across the post for
        // the reason nothing in this file is carried across a wait — and [`current_request_row`]
        // skips an acceptance, so the second read sees the same run as the first.
        if said == MessageKind::Accepted {
            let target = acceptance_target(ctx, store, sender, thread_id)?;
            return supervisor_accept_verdict(ctx, store, target, body, sender, hop).map(Some);
        }
        return supervisor_hand_out_next_turn(ctx, store, &q, &members, hop).map(Some);
    }
    Ok(None)
}

/// Is the SET complete? If it is, consolidate.
///
/// A member thread counts as settled when it is `complete` (its member answered this turn) **or**
/// `stale` (its own deadline struck) — hq71 §3's "when all have answered or the deadline strikes",
/// read against the per-member threads nxf 6j6v.pf6j puts the deadline on. Since nxf 6j6v.nf38 that
/// deadline is an IDLE one: every write to the one session's transcript behind a member thread
/// restarts the declared window, so `stale` here means "this member has shown no sign of life for
/// the whole window", not "the channel was opened a long time ago".
///
/// **Two entrances, and the second one is what makes the `stale` half of that sentence real** (nxf
/// 6j6v.rs9k): [`supervisor_after_reply`], in the write path of a real reply, and [`tick`], when a
/// step's window has run out with no reply at all. Until rs9k only the first existed, so a struck
/// deadline was settled everywhere the word appears and yet reached no advance: the tick read the
/// settled set as a finished flow and consolidated it, and the steps after the lapsed one never ran.
/// `settled` is handed in by both — the thread that was replied to, or the slot whose window
/// lapsed — and everything below this line cannot tell them apart, deliberately.
///
/// **A settled ordered set has TWO outcomes, not one** (nxf 6j6v.ma7v): the next step, or the end of
/// the chain. Which one is decided by the escalation of the set — the same declared bit the
/// consolidation below branches on — so a step that reported "I cannot" does not commission the work
/// that was to follow it. See the filter on the ordered branch for the measured run behind that.
fn supervisor_consider_set(
    ctx: &Ctx,
    store: &mut ChatStore,
    channel_thread: &str,
    settled: &str,
    hop: CheckedHop,
) -> Result<SupervisorRun> {
    let supervisor = supervisor_qualified(ctx.origin);
    let Some(channel_q) = store.thread_quorum(channel_thread, ctx.now)? else {
        return Ok(SupervisorRun::default());
    };
    // Only while the supervisor is still the one owing an answer up there. Once it has consolidated,
    // the channel thread's register names the `summarize`/`pass_through` marker instead, and a late
    // member reply must be a clean no-op rather than a second delivery.
    if channel_q.expects != [supervisor] {
        return Ok(SupervisorRun::default());
    }
    let declared = declared_channel_of(ctx, &channel_q).cloned();
    let all = supervised_member_threads(ctx, store, channel_thread)?;
    let members = current_pass(store, declared.as_ref(), &channel_q, all)?;

    // **THE FLOW MAY NOT BE OVER** (nxf 6j6v.hq71). A settled set ends a `parallel` channel, because
    // it asked everyone at once. An ORDERED one asked exactly ONE step, so what matters is whether
    // THAT step is done — and if it is, the supervisor's job is to start the next one, not to
    // consolidate. Only the last step's answer falls through to the consolidation below.
    //
    // **Where the flow is, is decided by the slot that just settled — handed in, not derived from
    // the pass's length** (review round 1). Length was wrong across passes: a second pass has a fresh
    // slot for step one and still the FIRST pass's slot for every step after it, so the pass reads
    // full the moment step one answers and the rest of the order is skipped. The step a reply belongs
    // to is not a guess — `supervisor_after_reply` knows which thread was replied to and the
    // hand-back knows which channel it just consolidated — so it is passed down rather than
    // reconstructed, and `slot_target` maps it to its position in the declared order.
    //
    // **The whole derived set must be settled before ANY of this — ordered channels included** (review
    // round 2). Round 1 dropped this gate on the sequential path on the reasoning that an ordered
    // channel runs one step at a time, so the settled slot alone decided where the flow was. That
    // reasoning had a hole, and it was in [`current_pass`]: the pass takes the newest slot PER STEP,
    // and for a step the current pass has not reached yet the newest slot is the PREVIOUS pass's. So a
    // pass genuinely can mix, and the mixed shape is reachable with nothing exotic — a follow-up
    // posted into the channel thread while a step is still working starts pass two beside pass one's
    // unanswered step, and that step's late answer then read as "the last step of a full pass" and
    // consolidated pass one's answers against pass two's request, leaving pass two a silent no-op.
    //
    // **What the gate is for NOW, after round 3 anchored the derivation**: [`current_pass`] no longer
    // mixes passes, so the gate is no longer what keeps a straggler out — the anchor is, and a slot
    // from an earlier pass simply is not in the set to be found. What the gate still does is refuse to
    // advance while a LATER step of this same pass is already running, which a second reply on an
    // already-settled earlier step would otherwise do: it would open that step a second time.
    //
    // (The comment here previously claimed the gate restored "what the code did before round 1's
    // redesign". That was too strong and review round 3 was right to say so: the derivation was
    // different then, and in one of the two orderings the pre-round-1 code advanced correctly where
    // the gate alone would have stalled.)
    //
    // It also subsumes the "is the slot that just settled actually settled" check that stood here:
    // every slot in the set is, this one included.
    if !member_set_is_settled(&members) {
        return Ok(SupervisorRun::default());
    }
    // **A step is over when its SESSION is over, not when its message arrives** (nxf 6j6v.10yb).
    // Measured: the coder answered at 00:16:33 with "ZWISCHENSTAND — nicht der Abschluss", the
    // finisher started three seconds later, and the coder went on writing until 00:34:27 — three
    // sessions in ONE working copy, one of them for thirteen minutes. Everything above this line
    // reads a fact about MESSAGES, and on a channel that declared it needs the working copy alone
    // that is the wrong fact to open the next step on.
    if a_member_session_is_still_writing(ctx, store, declared.as_ref(), &members)? {
        // **And something has to look again** (nxf 6j6v.858n). This is the path a real reply takes,
        // and it armed NOTHING at all: if the session's own end announcement never arrives — a
        // sidecar killed before its last teardown step, an older `nxc`, a host runtime with no
        // `Engine::session_ended` — the round sat here until a human worked out what state it was
        // in and ran `nxc tick --thread <id>`. Best-effort like every other scheduling site in this
        // file: the reply that got us here is durable, so a failure to arm is a finding on the
        // receipt, not a lost turn.
        let recheck = session_liveness_recheck(ctx.now)?;
        return Ok(SupervisorRun {
            warnings: rearm_window_with(ctx, channel_thread, &members, Some(&recheck))
                .into_iter()
                .collect(),
            ..SupervisorRun::default()
        });
    }
    // **AND THE ROUND MAY HAVE BEEN TAKEN BACK** (nxf 6j6v.b9nf, fix round 2 of that item's
    // review, Test Quality #5). The gate above asks whether anything is still WRITING; this one
    // asks whether what a stopped writer left is still IN THE TREE. They are different facts and
    // the second one outlives the first: `withdraw` discharges the round's threads and stops its
    // sessions, and the uncommitted work sits in the checkout until the tick's withdrawn occasion
    // parks it ([`park_a_withdrawn_holder`]). The marker is what says so, and until it goes this
    // claim area is not a place to start work in.
    //
    // **Measured, not reasoned** — the review could not settle this by reading and it turned out to
    // be two different answers — on the `session ended` path this gate sits on. (The tick the
    // withdrawal arms was measured only later, under nxf 6j6v.s2cj, and there BOTH shapes went
    // on; see [`withdraw`]'s call to [`interrupt_the_chain_above`].) A `flow: sequential` channel
    // is safe by accident on this path: the withdrawn
    // discharge retargets the member slot's `expects` onto the withdrawn identity, so
    // [`slot_target`] no longer maps that slot to its declared step, [`current_pass`] stops there,
    // and the settled slot is not in the derived pass at all. A channel that declares `steps:`
    // derives its pass from the recorded run mark instead ([`run_slots`]), which a discharge does
    // not touch — so the stopped session's own `session ended` reached [`supervisor_route_step`]
    // and commissioned the NEXT step into a checkout still holding the withdrawn round's
    // half-finished work, with the park still owed. `the_end_of_a_withdrawn_step_of_a_declared_
    // state_machine_does_not_route_the_next_one_either` is that run.
    //
    // **It delays, it does not cancel, and it decides nothing about the flow.** The occasion ends
    // one way — the copy goes on — and the clock that ends it is armed here as it is everywhere
    // else on this path ([`arm_a_look_at_the_withdrawn_holder`], keyed on the claim root, which for
    // a channel round IS this thread). That tick parks FIRST and reconsiders the board afterwards
    // ([`tick_reporting_its_own_failures`]), so whatever the set was going to do it does in the
    // same call, with the withdrawn work committed on a branch and recorded against the operation
    // — and what the next step then finds in the tree is the claim's own way back
    // ([`resume_parked_work`]), not this gate's business.
    //
    // **Since nxf 6j6v.s2cj this is the SECOND line, not the first.** Whether a step that was TAKEN
    // BACK may route its successor at all is now decided — no (owner, 2026-09-20, 6j6v.ymvg) — and
    // [`withdraw`] enforces it where it happens: it discharges this channel thread too
    // ([`interrupt_the_chain_above`]), so the `expects != [supervisor]` check at the top of this
    // function returns long before this gate is asked. What still reaches here is a round a
    // withdrawal did NOT discharge — one where a queued commission started while the withdrawal
    // ran (`started_meanwhile`), which leaves a live session in the claim and the marker standing.
    // For that round this gate is what keeps a next step out of the unparked tree, and
    // the two `a_claim_marked_withdrawn_opens_no_step_…` cases pin it on its own.
    if let Some(scope) = a_withdrawn_claim_awaiting_its_park(store, channel_thread)? {
        return Ok(SupervisorRun {
            warnings: arm_a_look_at_the_withdrawn_holder(ctx, store, &scope)
                .into_iter()
                .collect(),
            ..SupervisorRun::default()
        });
    }
    // **nxf 6j6v.wt37's branch, at the seam pf6j left for it.** A member that said "I cannot"
    // settled its own thread exactly like any other answer — that is 6j6v.cg8g's acceptance and it
    // is unchanged here — so the SET is settled either way and the consolidation runs either way.
    // What the escalation changes is what the supervisor hands UP: the escalation rides its own
    // discharge of the channel thread, so the question keeps travelling, possibly as far as the
    // human at T1, instead of being folded into a result nobody asked for.
    //
    // The supervisor branches on a signal whose MEANING IS WRITTEN IN THE CHANNEL (hq71 §4) — one
    // declared bit — rather than on a token an agent invents, which is the whole reason
    // `workflow step done --outcome` needed no replacement.
    //
    // **It is resolved HERE, above the ordered branch, because since nxf 6j6v.ma7v it decides that
    // branch too** — see the filter below. One derivation, read twice, rather than the same question
    // asked once per outcome.
    let escalated = set_escalated(ctx, store, &channel_q)?;
    // **A STEPPED channel routes on its own declaration** (nxf 6j6v.553s (d)) — the state machine,
    // which is the whole of this item. It sits ABOVE the ordered branch and never falls through to
    // it: a channel cannot declare both (`validate_channel_for_use` refuses the pair), so this is a
    // fork, not a precedence.
    //
    // An escalating set is filtered out here for exactly nxf 6j6v.ma7v's reason, unchanged: a task
    // that could not be carried out must not commission the work that was to follow it.
    if let Some(channel) = declared
        .as_ref()
        .filter(|c| c.is_stepped())
        .filter(|_| !escalated)
    {
        return supervisor_route_step(ctx, store, channel, &channel_q, settled, &members, hop);
    }
    if let Some(channel) = declared
        .as_ref()
        .filter(|c| c.flow == crate::channel::Flow::Sequential)
        // **AN ESCALATION ENDS THE CHAIN INSTEAD OF ADVANCING IT** (nxf 6j6v.ma7v). Until this item
        // the ordered branch ran regardless: `--escalate` settled the slot exactly like "I am
        // finished", so the next step opened on it — measured in a real run, a coder escalated at
        // 00:53:47 expressly TO stop the flow, and the next step's session started at 00:53:57 into
        // a checkout still standing on the pre-review commit.
        //
        // That left a member no correct move at all. Answering normally starts the successor;
        // answering `--escalate` started it too AND reported a blocker that did not exist; saying
        // nothing gets the session recalled and asked again (nxf 6j6v.gh7f). Four threads of one
        // run carried the escalation mark, each time deliberately, each time without effect — the
        // only thing that actually held the flow was a sentence in the commissioning prompt, which
        // is the kind of rule a next commission forgets.
        //
        // So the step counts as FAILED and its successors do not run: a task that could not be
        // carried out must not commission the work that was to follow it. That is the reading
        // `--escalate`'s own doc has always implied ("I cannot carry out this task") and the one
        // hq71 §4 left to the supervisor to write down — it says the supervisor decides what
        // becomes of an escalation, and this is that decision, for the ordered shape.
        //
        // **What this deliberately does NOT solve** is the case the measured coder actually had: he
        // had not failed, he was merely not finished, and no reply says that. The state disappears
        // altogether once the COORDINATOR commissions the review and resumes the member afterwards
        // (nxf 6j6v.553s parts 2-4); until then "not finished" still has no spelling, and this item
        // does not invent one. What it removes is the trap of the only spelling there IS having the
        // opposite effect.
        //
        // A `parallel` channel is untouched: nothing is ordered there, so there is no successor to
        // withhold — everyone was asked at once, and the escalation rides the consolidation up
        // exactly as it did before.
        .filter(|_| !escalated)
    {
        let steps = flow_steps(channel, channel_q.opener.as_deref());
        // A slot the derived pass does not contain is a late reply into an earlier one — a clean
        // no-op, which is what `find` answering `None` produces.
        let Some(just) = members.iter().find(|m| m.thread_id == settled) else {
            return Ok(SupervisorRun::default());
        };
        let Some(at) = slot_target(just, channel_q.channel_id.as_deref())
            .and_then(|t| steps.iter().position(|s| *s == t))
        else {
            return Ok(SupervisorRun::default());
        };
        if let Some(next) = steps.get(at + 1) {
            return supervisor_advance_flow(
                ctx,
                store,
                channel,
                &channel_q,
                &NextStep::to(next),
                hop,
            )
            .map(|(run, _started)| SupervisorRun {
                advanced: true,
                ..run
            });
        }
    }
    supervisor_consolidate(ctx, store, &channel_q, escalated, None, hop)
}

/// **The declared state machine, run once for the step that just settled** (nxf 6j6v.553s (d)+(a))
/// — the whole of what `steps:` buys, in one place.
///
/// The three endings a reply may carry are a TRICHOTOMY, and each has exactly one destination:
///
/// ```text
/// reply                 -> `next`, or the consolidation when the step declares none
/// reply --needs-rework  -> `on_needs_rework`, with the run's pass counter one higher
/// reply --escalate      -> the chain ends (resolved by the caller, above this function)
/// ```
///
/// **There is a FOURTH edge into `next`, and it does not come through here** (nxf 6j6v.am8j).
/// `reply --accept` is not one of a step's endings — it is said by the party that COMMISSIONED the
/// round, on the round's own thread, so it lands in [`supervisor_after_reply`]'s requester branch
/// and is routed by [`supervisor_accept_verdict`]. What it produces is the same edge the first line
/// above produces, reached without the reviewing step ever becoming satisfied. Nothing in this
/// function changes for it, which is the point: an accepted edge is opened by
/// [`supervisor_advance_flow`] exactly as this one is.
///
/// Everything it needs it reads back off the record: which step the settled slot served
/// ([`ChatStore::flow_mark`]), what that step declares (the channel, bound to this operation's
/// version), and what the answer said ([`slot_verdict`]). Nothing is carried across the wait, for
/// [`supervisor_advance_flow`]'s reason.
///
/// **A slot the run does not contain is a clean no-op**, which is a late reply into an earlier run's
/// step — the same answer `find` gives on the ordered branch, and for the same reason.
fn supervisor_route_step(
    ctx: &Ctx,
    store: &mut ChatStore,
    channel: &ChannelDecl,
    channel_q: &ThreadQuorum,
    settled: &str,
    members: &[ThreadQuorum],
    hop: CheckedHop,
) -> Result<SupervisorRun> {
    let Some(just) = members.iter().find(|m| m.thread_id == settled) else {
        return Ok(SupervisorRun::default());
    };
    let Some(mark) = store.flow_mark(settled)? else {
        return Ok(SupervisorRun::default());
    };
    let Some(step) = channel.step(&mark.step) else {
        // The declaration was edited and no longer has the step this slot was opened for. The run
        // cannot be routed, so it is consolidated where it stands rather than guessed at.
        return supervisor_consolidate(ctx, store, channel_q, false, None, hop);
    };
    let mut warnings = Vec::new();
    if slot_verdict(ctx, store, just)? {
        match (&step.on_needs_rework, step.max_passes) {
            (Some(back), Some(max)) => {
                // The pass this verdict would START. Counted over the RUN's own slots for THIS step,
                // so a channel with two cycles counts each of them separately — which is exactly why
                // `max_passes` sits on the edge and not on the channel.
                let pass = 1 + u32::try_from(rework_hops(ctx, store, members, &mark.step)?)
                    .unwrap_or(u32::MAX - 1);
                if pass > max {
                    // **THE CEILING ESCALATES, it does not stop quietly** (owner, 2026-08-29). The
                    // supervisor uses the one declared form there is for "the wanted result could
                    // not be reached" — no second reporting channel is invented — so the round
                    // travels up as an escalation, holds the working copy, and whoever asked
                    // decides. A re-commission from above is a NEW run and starts the count over.
                    // **THIS NOTE SAYS WHY THE ROUND STOPPED AND NOTHING ELSE.** Until nxf
                    // 6j6v.am8j it also said what to do about it — "commission the round again if
                    // another attempt is what you want" — and that was the only move a reader could
                    // see: a new run, a fresh ceiling, three more passes of a review that had
                    // already said no. Measured in `watch-bundestag`: six passes, six verdicts, the
                    // human re-arming the loop each time, because the message told them that was
                    // the move. The other move is `--accept`, and a door nobody is told about is
                    // not a door — so the OFFER is composed once, for every round that stops on a
                    // verdict however it stopped ([`accept_offer_note`]), and appended by
                    // [`supervisor_consolidate`]. A ceiling is not the only way to stop, and it
                    // must not be the only stop that names the exit.
                    let note = format!(
                        "The ceiling on this channel's rework edge was reached: step {:?} sent the \
                         work back {} time(s), and {:?} declares `max_passes: {max}`. No further \
                         attempt was started. Every answer of this round is below. Replying here \
                         commissions the round AGAIN, from its first step, with the ceiling set \
                         back to {max}.",
                        mark.step,
                        pass - 1,
                        mark.step,
                    );
                    return supervisor_consolidate(
                        ctx,
                        store,
                        channel_q,
                        true,
                        Some(note.as_str()),
                        hop,
                    );
                }
                // A dangling back edge is CONSOLIDATED, never panicked on. `validate_channel_for_use`
                // refuses one, but the channel is resolved here through the PLAIN lookup — the one
                // that deliberately still RECOGNISES a declaration edited into invalidity, so the
                // fail-closed re-check can happen where the channel is acted on. That is the same
                // reasoning `declared_channel_of` states, and it means an unreachable-by-validation
                // shape is still reachable by this code path. An `expect` here would turn a bad
                // declaration into a panic inside a write path that has already posted a message.
                let Some(to) = channel.step(back) else {
                    return supervisor_consolidate(ctx, store, channel_q, false, None, hop);
                };
                let verdict = slot_answer(ctx, store, &just.thread_id)?;
                let next = NextStep {
                    target: &to.target,
                    entry: Some(StepEntry {
                        mark: crate::store::FlowMark {
                            run: mark.run.clone(),
                            step: to.id.clone(),
                        },
                        // **A back edge CONTINUES by default** (nxf 6j6v.y1t9; owner, 2026-08-31).
                        // The notice composed two lines down says "what you handed over" and "your
                        // claim on the working copy is STILL YOURS" — both true only of the session
                        // that handed it over. The declaration may say otherwise per step.
                        resume: to.resume.unwrap_or(true),
                        // The step this edge was taken FROM (nxf 6j6v.s0k5). Recorded for the
                        // record's sake and read by nothing on this edge: the rework notice one
                        // line down is this step's body, and `input:` regulates forward edges only
                        // — the findings would otherwise arrive twice.
                        from: Some(mark.step.clone()),
                    }),
                    body: Some(crate::channel::compose_rework_notice(
                        channel, pass, max, &verdict,
                    )),
                };
                return supervisor_advance_flow(ctx, store, channel, channel_q, &next, hop).map(
                    |(run, _started)| SupervisorRun {
                        advanced: true,
                        ..run
                    },
                );
            }
            // **A verdict this step declares no edge for FALLS AWAY, and says so** (owner,
            // 2026-08-29: "REINE DIAGNOSE, keine Entscheidung und nicht in der Nachricht"). The bit
            // was never offered to this step's session ([`step_offers_rework`]), so reaching here
            // means somebody found the flag in the help and set it anyway. The run continues over
            // `next` exactly as if the answer had been plain — and the receipt of the very reply
            // that carried it says the channel declares no transition, which is the one thing that
            // later answers "why does this channel keep getting verdicts it cannot use?".
            _ => {
                let finding =
                    FailedConsequence::verdict_dropped(&just.thread_id, &mark.step, &channel.name);
                eprintln!("warning: {finding}");
                warnings.push(finding);
            }
        }
    }
    match &step.next {
        Some(id) => {
            let Some(to) = channel.step(id) else {
                return supervisor_consolidate(ctx, store, channel_q, false, None, hop);
            };
            let next = NextStep {
                target: &to.target,
                entry: Some(StepEntry {
                    mark: crate::store::FlowMark {
                        run: mark.run.clone(),
                        step: to.id.clone(),
                    },
                    // **A forward edge starts FRESH by default** (nxf 6j6v.y1t9). Two steps may
                    // name one target — `id` is what tells them apart — and sharing a target is not
                    // by itself a reason to carry a session across a new piece of work.
                    resume: to.resume.unwrap_or(false),
                    // **The step whose edge this one was reached over** (nxf 6j6v.s0k5) — the
                    // "immediate predecessor" a step that declares no `input:` is given the answer
                    // of. It is the step that just settled, which is a fact only this frame holds.
                    from: Some(mark.step.clone()),
                }),
                body: None,
            };
            supervisor_advance_flow(ctx, store, channel, channel_q, &next, hop).map(
                |(run, _started)| SupervisorRun {
                    advanced: true,
                    warnings: warnings.into_iter().chain(run.warnings).collect(),
                    ..run
                },
            )
        }
        // The end of the declared run: no `next`, so the channel answers whoever asked.
        None => {
            let mut run = supervisor_consolidate(ctx, store, channel_q, false, None, hop)?;
            run.warnings = warnings.into_iter().chain(run.warnings).collect();
            Ok(run)
        }
    }
}

/// **What an acceptance on this thread would DO** (nxf 6j6v.am8j) — resolved once, read twice.
///
/// `--accept` is refused BEFORE the message is posted (see
/// [`refuse_an_acceptance_that_cannot_be_honoured`]) and acted on AFTER it, and those two moments
/// must agree about every one of the questions below or the verb becomes the worst shape there
/// is: a refusal that fires for a state the router would have handled, or — far worse — a cheerful
/// receipt for a round nothing moved. So there is one derivation and both callers run it.
///
/// Running it twice in one call is safe by construction: the only thing that happens between the two
/// is the acceptance being posted, and [`current_request_row`] skips exactly that kind, so no read
/// below sees a different world the second time.
///
/// The `Err` arms ARE the feature. An acceptance that cannot be honoured must say WHICH condition
/// it failed and what to do instead — "nothing happened" is how a gate becomes a wall again, which
/// is the sentence this whole item was opened on.
fn acceptance_target(
    ctx: &Ctx,
    store: &ChatStore,
    caller: &str,
    thread: &str,
) -> Result<AcceptTarget> {
    let Some(q) = store.thread_quorum(thread, ctx.now)? else {
        return Err(NxfError::not_found(format!(
            "no thread {thread} in this workspace, so there is no round on it to accept"
        )));
    };
    // (1) **A SLOT is refused by name, and this is where the item's embedded ruling is enforced**
    // (nxf 6j6v.am8j: *"der ERZEUGER darf seinen eigenen Pruefer NICHT fuer zufrieden erklaeren"*).
    // A party serving a step answers on a thread the supervisor opened under the round — so
    // reaching for `--accept` there is precisely the producer declaring its own reviewer satisfied,
    // and it dissolves the separation the round exists to create. It is turned away with the verb
    // that IS an agent's way to ask for a decision it may not take, because a refusal that names no
    // alternative teaches nothing.
    if let Some(round) = supervising_parent(store, thread)? {
        return Err(NxfError::forbidden(format!(
            "thread {thread} is a STEP of the round in thread {round}, and a party serving a step \
             may not accept the verdict on its own work — the whole reason the round has two \
             parties is that the one producing the work is not the one judging it. Say what you \
             have to say with `nxc reply --thread {thread} --escalate -` instead: that asks the \
             party that commissioned this round to decide, and accepting is the move THEY then have"
        )));
    }
    // (2) A ROUND AT ALL, and one with a state machine: without `steps:` there is no verdict edge
    // and no `next:` for an acceptance to send anything on to.
    let Some(channel) = declared_channel_of(ctx, &q).cloned() else {
        return Err(NxfError::forbidden(format!(
            "thread {thread} is not a round of a declared channel — `--accept` overrules a verdict \
             inside one, and there is none here. An ordinary answer is `nxc reply --thread \
             {thread} \"…\"`"
        )));
    };
    if !channel.is_stepped() {
        return Err(NxfError::forbidden(format!(
            "channel {:?} declares no `steps:`, so nothing in it can send work back and there is \
             no verdict to accept. `--accept` is for a channel whose flow declares a cycle \
             (`on_needs_rework:`); an ordinary answer is `nxc reply --thread {thread} \"…\"`",
            channel.name
        )));
    }
    // (3) WHOSE ROUND IT IS. `expects_reply_from` says who owes an ANSWER and is no help here — on
    // a round that has consolidated it names the engine's own delivery marker — so the question is
    // asked of the immutable fact: who opened this thread.
    //
    // **A thread with NO recorded opener compares as the empty string, and that is fail-closed
    // rather than an accident** (independent review of PR #470, Integrity & Robustness #4). Every
    // caller handle is `<origin>/<actor>` ([`Ctx::caller_handle`]) and `origin` is never empty — it
    // is the workspace's replica prefix — so a real caller always carries a `/` and can never equal
    // `""`. An openerless thread therefore refuses every acceptance rather than admitting one, which
    // is the direction a missing authorization fact has to fail in.
    let opener = q.opener.clone().unwrap_or_default();
    if opener != caller {
        return Err(NxfError::forbidden(format!(
            "only the party that commissioned this round may accept a verdict on it. Thread \
             {thread} was opened by {opener:?} and you are {caller:?}"
        )));
    }
    // (4) A RUN. A round thread with no request on it has none, which cannot arise for a thread the
    // supervisor is running — the request that opened it is one — and is answered rather than
    // unwrapped.
    let Some((run, _)) = current_request(store, thread)? else {
        return Err(NxfError::forbidden(format!(
            "thread {thread} carries no request, so no run of channel {:?} has started on it",
            channel.name
        )));
    };
    let all = supervised_member_threads(ctx, store, thread)?;
    let members = run_slots(store, all, &run)?;
    // (5) **THE VERDICT IS WHAT THERE IS TO ACCEPT, and the LAST one is the one that stopped this
    // round.** A channel may declare more than one cycle, so "some step once said no" is not the
    // question; "which judgement is the round standing on now" is. Slots of one run are minted a
    // full round trip apart ([`current_pass`] enumerates all four openers and argues it), so their
    // ULID order is their order in the run.
    let mut rejecting: Option<(String, String)> = None;
    for slot in &members {
        let Some(mark) = store.flow_mark(&slot.thread_id)? else {
            continue;
        };
        if slot_verdict(ctx, store, slot)? {
            rejecting = Some((mark.step, slot.thread_id.clone()));
        }
    }
    let Some((step_id, verdict_slot)) = rejecting else {
        return Err(NxfError::forbidden(format!(
            "nothing in this round was sent back: no step of the run on thread {thread} answered \
             `--needs-rework`, so there is no verdict to accept. If you want another attempt, a \
             plain `nxc reply --thread {thread} -` commissions the round again"
        )));
    };
    let Some(next) = channel.step(&step_id).map(|s| s.next.clone()) else {
        // The declaration was edited and no longer has the step whose verdict is being accepted.
        // Refused rather than guessed at, which is what `supervisor_route_step` does one axis over
        // with the same shape.
        return Err(NxfError::forbidden(format!(
            "the step {step_id:?} whose verdict stopped this round is no longer declared by channel \
             {:?}, so there is no `next:` to send the round on to",
            channel.name
        )));
    };
    // (6) **AN ACCEPTANCE IS A TRANSITION, so a step with nowhere to go cannot carry one.** A step that
    // declares a back edge and no `next:` ends its channel's flow, so accepting its verdict would
    // send the round nowhere — and the round has already been handed to whoever asked, exactly as
    // it stands. Refused rather than quietly consolidating a second time: the second consolidation
    // is a no-op behind the delivery claim, which would hand the caller a cheerful receipt for
    // nothing at all.
    let Some(next) = next else {
        return Err(NxfError::forbidden(format!(
            "step {step_id:?} is the last step of channel {:?}'s flow — it declares no `next:`, so \
             there is nowhere for this round to go on to. Its answers have already been handed to \
             you as they stand; read them with `nxc threads show {thread}`",
            channel.name
        )));
    };
    // (7) **AND THE VERDICT HAS TO STILL STAND.** A run keeps every slot it ever opened, so "some step
    // of this run once said no" is answered `true` by a round that went back, was fixed, was passed
    // and shipped — and offering to accept a judgement that was superseded three steps ago would be
    // a delivery telling a finished round it can be un-finished. The check is the state, not the
    // history: if this run already has a slot serving the step the acceptance would open, the round
    // has been past this edge and there is nothing here to release.
    //
    // It is also what makes a second acceptance a clean refusal rather than a second `ship`.
    let mut been_past = false;
    for slot in &members {
        if store
            .flow_mark(&slot.thread_id)?
            .is_some_and(|m| m.step == next)
        {
            been_past = true;
        }
    }
    if been_past {
        return Err(NxfError::forbidden(format!(
            "this round has already gone on past step {step_id:?} — its successor {next:?} has run. \
             The verdict you are answering is a superseded one; read where the round stands with \
             `nxc threads show {thread}`"
        )));
    }
    // (8) **NOT THE COUNTER — the stillness.** The item asked whether this verb belongs only to an
    // exhausted `max_passes` or to every pass, and answered: every pass, because *"die Ungeduld des
    // Menschen ist keine Funktion des Zaehlers"*. Nothing here reads the counter, and that is that
    // answer implemented. What IS asked is whether the round is standing still, and it is asked for
    // a reason that has nothing to do with patience: advancing past a step that is still working
    // would put the successor into the same working copy beside it, which is nxf 6j6v.10yb's
    // measured damage — three sessions in one checkout, one of them for thirteen minutes. This
    // engine has no verb that stops a running session (`withdraw`'s own doc records that boundary
    // deliberately), so the honest answer while one runs is a refusal that says what is being
    // waited for.
    // **WHAT THIS DERIVATION IS NOT: ATOMIC** (independent review of PR #470, Integrity &
    // Robustness #1; tracked as nxf 6j6v.m01c). Every check above is a plain read, and the write
    // that acts on them happens in a separate statement — so two `nxc reply --accept` PROCESSES
    // against the same round can both pass check (7) in the window before either opens a slot, and
    // each then mints its own commission for the same `(run, next_step)`.
    //
    // **The likely double-tap is NOT this, and it is closed**: a human who is unsure the first call
    // worked and runs it again gets refused by (7), because an interactive call blocks until it
    // returns — `a_round_that_has_already_gone_past_the_verdict_cannot_be_accepted_backwards` pins
    // it. What is open is genuine concurrency: two terminals, or a script.
    //
    // **It is a CLASS, not this verb's own defect, which is why it is not closed here alone.**
    // [`supervisor_hand_out_next_turn`] — the ordinary follow-up, one branch over — has the same
    // shape and says so at length under its own NEWEST-WINS note, and defers the closure to the
    // membership gate (nxf 6j6v.6aza). Taking a claim here and nowhere else would leave the
    // identical hole one function away while reading as solved, which is the enumeration-instead-
    // of-class failure this crate keeps recording ([`crate::channel::RESERVED_HANDLE_PREFIX`],
    // [`set_escalated`]'s own note). The working-tree lease's `BEGIN IMMEDIATE` is not the
    // counter-example it looks like: that guards a resource shared across UNRELATED operations,
    // where no later read can ever notice the collision, while both racers here leave a durable
    // record on one thread.
    if !member_set_is_settled(&members)
        || a_member_session_is_still_writing(ctx, store, Some(&channel), &members)?
    {
        let working: Vec<&str> = members
            .iter()
            .filter(|m| !m.complete && !m.stale)
            .map(|m| m.thread_id.as_str())
            .collect();
        let waiting_on = match working.is_empty() {
            true => "a session of this round is still writing".to_string(),
            false => format!("thread(s) {} have not answered", working.join(", ")),
        };
        return Err(NxfError::forbidden(format!(
            "this round is still moving — {waiting_on}. Accepting now would open the step after \
             {step_id:?} beside work that is still going, in the same working copy. Read where it \
             stands with `nxc threads show {thread}`, let the step answer, and accept then — the \
             verdict will still be there"
        )));
    }
    Ok(AcceptTarget {
        channel,
        channel_q: q,
        run,
        step: step_id,
        next,
        verdict: slot_answer(ctx, store, &verdict_slot)?,
    })
}

/// **The sentence that tells a stopped round's requester it can end the cycle** (nxf 6j6v.am8j) —
/// composed from the very derivation that decides whether the verb would work.
///
/// That reuse is the whole design. An offer and a refusal are the same question asked from two
/// sides, and the way this goes wrong is a message that advertises a move the engine then declines
/// — so [`acceptance_target`] answers both, and an offer exists exactly where an acceptance would be
/// honoured. It asks on behalf of the thread's OPENER, because that is the party the consolidation
/// is being delivered to and the only party who may give it.
///
/// `None` is the ordinary case and covers everything: a channel with no cycle, a round nobody sent
/// back, a round still moving, a nested round whose acceptance belongs to the supervisor above it.
/// A round that is merely finishing cleanly says nothing extra, which is what keeps every healthy
/// delivery byte-identical to what it was.
///
/// **AND `None` ALSO SWALLOWS A REAL I/O FAILURE, which is said here rather than left to be read
/// off the `.ok()`** (independent review of PR #470, Integrity & Robustness #3). A store error
/// inside [`acceptance_target`] is indistinguishable here from "there is nothing to offer", and the
/// delivery goes out without the offer and without a word. That is deliberate and it is the benign
/// direction: this is DECORATION on a consolidation that must not fail, the round is delivered
/// either way, and the verb itself is unaffected — a requester who runs `--accept` gets the real
/// error from the real call. Reporting it would mean threading a finding out of a function whose
/// whole contract is "an `Option`, cheap, on every consolidation", to tell a reader about a
/// sentence they did not know they were missing.
fn accept_offer_note(ctx: &Ctx, store: &ChatStore, channel_q: &ThreadQuorum) -> Option<String> {
    let opener = channel_q.opener.clone()?;
    let target = acceptance_target(ctx, store, &opener, &channel_q.thread_id).ok()?;
    Some(format!(
        "This round is standing on the verdict of step {:?}, and you do not have to wait for that \
         step to change its mind: `nxc reply --thread {} --accept -` (the body on STDIN) accepts \
         the verdict as it stands and sends THIS round on to the step after {:?}. Your reasons go \
         to that step together with the verdict you set aside, so it knows the judgement was \
         overruled and not met.",
        target.step, channel_q.thread_id, target.step,
    ))
}

/// Everything [`supervisor_accept_verdict`] needs, and everything
/// [`refuse_an_acceptance_that_cannot_be_honoured`] had to establish to let the message be posted at
/// all — resolved together by [`acceptance_target`] because they are established together.
struct AcceptTarget {
    /// Bound to this operation's version, exactly as every other read on the routing side of
    /// [`reply`] is (nxf 6j6v.n92p) — resolved through the PLAIN lookup, so a declaration edited
    /// into invalidity is still recognised here and refused where it is acted on.
    channel: ChannelDecl,
    /// The round's own thread, read once so the router does not re-derive a quorum the preflight
    /// already had.
    channel_q: ThreadQuorum,
    /// The run the acceptance belongs to — the request standing on the thread, NOT the acceptance
    /// itself (see [`current_request_row`]).
    run: String,
    /// The step whose verdict is being overruled.
    step: String,
    /// Where that step's [`next:`](crate::channel::FlowStep::next) points — established, not
    /// optional: a step with no `next:` cannot carry an acceptance at all, and
    /// [`acceptance_target`] refuses one rather than handing the router a hole to decide about.
    next: String,
    /// The words that were set aside, carried to the successor beside the acceptance so it cannot
    /// mistake an override for a review that passed.
    verdict: String,
}

/// **Refuse an acceptance that cannot be honoured, before anything is written** (nxf 6j6v.am8j) —
/// [`crate::surface::reply_in_thread`]'s third preflight, beside the two already there.
///
/// It is a PREflight and not a receipt field, unlike everything else on this verb's routing side.
/// The rest of `reply`'s routing may not fail the call because the message is already durable by the
/// time it runs, and a receipt that says what did not happen is the honest answer. An acceptance is
/// the other shape: its whole content is a decision to move the round on, so an acceptance that
/// moves nothing is not a partial success — it is a message in a thread that reads, to every later
/// reader, exactly like one that worked. The owner would walk away believing the chain had gone on.
///
/// A call with `accept: false` asks nothing and reads nothing.
pub(crate) fn refuse_an_acceptance_that_cannot_be_honoured(
    ctx: &Ctx,
    store: &ChatStore,
    thread: &str,
) -> Result<()> {
    acceptance_target(ctx, store, &ctx.caller_handle(), thread).map(|_| ())
}

/// **The owner accepts a verdict, and the round goes on over `next`** (nxf 6j6v.am8j, owner
/// 2026-09-12) — [`supervisor_hand_out_next_turn`]'s sibling, and the difference between them is the
/// whole item.
///
/// A follow-up on a round's thread starts a NEW RUN at step one, which is right for "try again" and
/// is what re-armed the loop the ticket measured: `max_passes` bounds one run, so every answer from
/// above bought three more passes of a review that had said no six times out of six. This path does
/// the other thing — the one that had no spelling at all. The run is the SAME run, the step that
/// rejected counts as satisfied, and the flow continues where it was stopped.
///
/// **It reuses [`supervisor_advance_flow`] rather than moving a step itself**, so an accepted edge
/// is opened by the same code as every other edge: same preconditions, same working-copy
/// acquisition, same `resume:` resolution, same findings when a step will not start. The one thing
/// it decides for itself is the BODY, and that is the item's first open question answered — see
/// [`crate::channel::compose_accepted_notice`].
///
/// **The register is re-armed only once the step has actually STARTED**, which is
/// [`supervisor_hand_out_next_turn`]'s ordering and its reason unchanged: re-arming first would
/// leave the round's thread owing the supervisor with nothing beneath it, and the next reply or tick
/// would deliver the PREVIOUS pass as the answer to a request nobody made.
///
/// **ONE CONSEQUENCE IS WRITTEN DOWN RATHER THAN FIXED HERE** (nxf 6j6v.am8j, carried to nxf
/// 6j6v.96q8). A round can come to rest on a verdict two ways, and this verb deliberately serves
/// both: the ceiling, and a member ESCALATING during a rework — which is the shape the item's own
/// second half describes, since escalating is the producer's only legitimate move and this verb is
/// how the party above answers it. On the second of those, [`set_escalated`] goes on answering
/// `true` for the rest of the run: it reads every slot of the run, an escalating slot is never
/// re-declared, and nothing in an acceptance touches it. So a round that was accepted and then
/// finished cleanly is still DELIVERED as an escalation and still shows `needs_decision`.
///
/// It is stated rather than patched because every patch available here is worse than the wrong
/// label. Retargeting the escalating slot's register would clear it — `last_reply_escalated` reads
/// only since the current declaration — and would also move `complete`, `stale` and
/// `work_scope_handed_back` for that thread, which is three real derivations changed to correct one
/// word. Narrowing `set_escalated` to "the slots since the last acceptance" needs the acceptance's
/// position in the run, and this crate deliberately does not compare message ids against thread ids
/// (`a_declared_cycle_sends_the_work_back.rs` records why). The CEILING path — the one the item was
/// measured on — is unaffected: a verdict is not an escalation, so a run that stopped at
/// `max_passes` and was accepted consolidates clean, which
/// `the_round_a_ceiling_stopped_finishes_without_the_escalation_mark` pins.
fn supervisor_accept_verdict(
    ctx: &Ctx,
    store: &mut ChatStore,
    target: AcceptTarget,
    acceptance: &str,
    by: &str,
    hop: CheckedHop,
) -> Result<SupervisorRun> {
    let AcceptTarget {
        channel,
        channel_q,
        run: run_id,
        step,
        next: next_id,
        verdict,
    } = target;
    // A dangling `next:` is CONSOLIDATED, never panicked on — `supervisor_route_step`'s own answer
    // for the same shape, and for the same reason: the channel is resolved through the PLAIN lookup,
    // so a declaration edited into invalidity still reaches this code.
    let Some(to) = channel.step(&next_id).cloned() else {
        return supervisor_consolidate(ctx, store, &channel_q, false, None, hop);
    };
    let body = crate::channel::compose_accepted_notice(by, &step, acceptance, &verdict);
    let next = NextStep {
        target: &to.target,
        entry: Some(StepEntry {
            mark: crate::store::FlowMark {
                run: run_id,
                step: to.id.clone(),
            },
            // **A forward edge starts FRESH by default** (nxf 6j6v.y1t9), and an accepted edge IS a
            // forward edge — it is `next:`, reached early. Honoured rather than hardcoded, like
            // every other step opener.
            resume: to.resume.unwrap_or(false),
            // The step whose edge this was reached over, for the record (nxf 6j6v.s0k5). `input:` is
            // not consulted on this edge — `body` is `Some`, which is `supervisor_advance_flow`'s
            // own switch — for [`compose_rework_notice`]'s reason one axis over: the material is
            // already in the notice, and honouring `input:` as well would hand the verdict over
            // twice.
            from: Some(step.clone()),
        }),
        body: Some(body),
    };
    let (mut run, started) = supervisor_advance_flow(ctx, store, &channel, &channel_q, &next, hop)?;
    if !started {
        // **AN ACCEPTANCE THAT MOVED NOTHING SAYS SO IN THE RECORD** (independent review of PR
        // #470, Integrity & Robustness #2). The advance can decline — a declared hurdle refuses, a
        // step will not start — and `supervisor_advance_flow` reports that as a
        // [`FailedConsequence`] on the receipt of the reply that caused it. That is the right
        // answer for the CALLER and the wrong one for the RECORD: the receipt is not stored, while
        // the `accepted` message is, and the whole reason this verb has a kind of its own is that
        // an override must stay findable AS an override afterwards. Left alone, the thread carries
        // an acceptance indistinguishable from one that worked — which is this feature undoing its
        // own justification.
        //
        // So the engine writes one beside it, from its own identity. It is `Info` and never
        // `Accepted`: a second message of that kind would read as a second override, and
        // [`current_request_row`] skips engine senders, so this cannot become a run either.
        //
        // Best-effort, like every other write on the routing side of [`reply`]: the acceptance is
        // durable by the time this runs, so a note that could not be posted is a finding, not an
        // `Err` that would report failure for something that was in fact written.
        let note = format!(
            "The acceptance above did NOT take effect: step {:?} of channel {:?} was not started, \
             so this round has not gone on and the verdict of step {step:?} still stands where it \
             stood. Whoever accepted was told why on the receipt of that very reply. Accepting \
             again once the way is clear is what starts it.",
            to.id, channel.name
        );
        if let Err(e) = facade::send(
            store,
            facade::SendRequest {
                now: ctx.now,
                origin: ctx.origin,
                actor: crate::channel::SUPERVISOR_HANDLE,
                channel: channel_q.channel_id.as_deref().unwrap_or_default(),
                body: &note,
                kind: MessageKind::Info,
                priority: Priority::Normal,
                disposition: Disposition::InTurn,
                thread: Some(&channel_q.thread_id),
                refs: Refs::default(),
            },
        ) {
            let detail = format!(
                "an acceptance on thread {} started no step AND the note saying so could not be \
                 written: {e}. The record now carries an acceptance that looks like one that \
                 worked",
                channel_q.thread_id
            );
            eprintln!("warning: {detail}");
            run.warnings.push(FailedConsequence::step_skipped(
                Some(&channel_q.thread_id),
                None,
                WakeSkipReason::Unresolved,
                detail,
            ));
        }
        return Ok(run);
    }
    let opener = channel_q.opener.clone().unwrap_or_default();
    facade::set_expects(
        store,
        ctx.now,
        &opener,
        &channel_q.thread_id,
        std::slice::from_ref(&supervisor_qualified(ctx.origin)),
    )?;
    run.advanced = true;
    Ok(run)
}

/// **Did this settled slot come back with a verdict?** (nxf 6j6v.553s (a)) — and, for a step whose
/// target is a whole CHANNEL, did ANY member of it?
///
/// **ANY-MEMBER-WINS, and it is recursive on purpose** (owner, 2026-08-29: *"In unserem angedachten
/// Review Kanal duerfte jeder Reviewer dieses Bit setzen und der Kanal-Koordinator muss, wenn ein
/// Reviewer das Bit gesetzt hat, auch das Bit in Richtung Coder setzen"*). A checker that found
/// something must not be outvoted by three that did not.
///
/// **Re-affirmed rather than inherited, and it now carries a second thing** (nxf 6j6v.0dr0, third
/// acceptance point). The alternative was to let the CONSOLIDATION carry the bit — one folded
/// judgement decides whether the round goes back — and it is rejected for the reason the owner's
/// sentence gives and the paragraph below elaborates: a fold is authored by a synthesizer whose
/// answer the engine does not write, so making it the carrier means a real finding can be smoothed
/// away by the very step that exists to state it briefly. One is enough. That answer is what makes
/// [`step_offers_rework`] able to offer the third ending to EVERY member of a commissioned channel:
/// the offer is a promise that a verdict goes somewhere, and here each member's does.
///
/// **Why it reads the inner MEMBERS rather than the inner channel's discharge.** A `summarize`
/// channel — the shipped review quorum — answers with its SYNTHESIZER's reply, whose kind the engine
/// does not author, so a member's verdict has nothing to ride on at that level. That is the same gap
/// nxf 6j6v.e9qj closed for escalations by never folding an escalating set; doing it that way here
/// would mean a verdict ALSO turns the fold off, and then the coder is sent back three separate
/// reviews instead of the one judgement the channel was declared to produce. Reading one level
/// deeper keeps the fold and carries the bit — which is precisely *"auch das BIT muss gefaltet
/// werden, nicht nur der Text"*.
///
/// **THE WALK IS BOUNDED BY A `seen` SET, NOT BY THE DECLARATION** — and the first cut of this
/// function got that wrong (independent review of PR #400, Integrity & Robustness #1, High).
///
/// It claimed depth was bounded by `channel::flow_cycles`, which [`crate::definitions::Definitions::new`]
/// fails a catalogue on. That check is real and it guards a DIFFERENT GRAPH: the declared
/// channel-commissions-channel one. This recursion walks the stored `threads.parent` edges, which
/// have nothing to do with whether a declaration is valid once the threads exist. The two were
/// conflated, and the guard therefore did not exist.
///
/// **This crate already treats that structure as cycle-capable, everywhere else.**
/// [`ChatStore::thread_root`] says so in as many words — *"A cycle cannot arise from any write
/// here, but a synced or hand-edited log could carry one and a walk that trusts the data would
/// hang"* — and resolves it by taking the smallest id of the cycle;
/// [`ChatStore::thread_subtrees`] does a breadth-first walk with its own `seen` set for the same
/// reason. [`ChatStore::supervised_children`] is a bare single-level query and guards nothing, so by
/// this codebase's own convention the defence belongs at the caller. It is here now.
///
/// A thread already visited answers `false` for its own sub-walk rather than aborting the whole
/// question: the set is a TERMINATION guard, not a verdict, and a cycle must not be able to hide a
/// verdict that some other branch of the walk can still reach.
fn slot_verdict(ctx: &Ctx, store: &ChatStore, slot: &ThreadQuorum) -> Result<bool> {
    slot_verdict_within(ctx.now, store, slot, &mut std::collections::HashSet::new())
}

/// [`slot_verdict`] carrying the `seen` set across the recursion. One set per top-level question:
/// two slots of one run are separate walks, and sharing a set between them would let the first
/// walk's threads silently answer for the second's.
fn slot_verdict_within(
    now: &str,
    store: &ChatStore,
    slot: &ThreadQuorum,
    seen: &mut std::collections::HashSet<String>,
) -> Result<bool> {
    if !seen.insert(slot.thread_id.clone()) {
        return Ok(false);
    }
    if store.last_reply_needs_rework(&slot.thread_id)? == Some(true) {
        return Ok(true);
    }
    for inner in supervised_member_threads_at(now, store, &slot.thread_id)? {
        if slot_verdict_within(now, store, &inner, seen)? {
            return Ok(true);
        }
    }
    Ok(false)
}

/// **How many times this run has already gone back over one step's edge** — the counter
/// `max_passes` is compared against.
///
/// Derived from the run's own slots rather than recorded, which is what makes the reset free: a new
/// run has none of them. The slot that just settled is one of the ones counted, so the answer plus
/// one is the pass the rework would START.
fn rework_hops(
    ctx: &Ctx,
    store: &ChatStore,
    members: &[ThreadQuorum],
    step: &str,
) -> Result<usize> {
    let mut hops = 0;
    for slot in members {
        if store
            .flow_mark(&slot.thread_id)?
            .is_some_and(|m| m.step == step)
            && slot_verdict(ctx, store, slot)?
        {
            hops += 1;
        }
    }
    Ok(hops)
}

/// **The answer a settled slot gave**, as the text the next step is commissioned with.
///
/// The newest message on the slot that the supervisor did not write — which is the member's reply on
/// a role slot, and the inner channel's own delivered consolidation (a pass-through marker or a
/// synthesis) on a channel slot. One rule for both shapes, because both are "what came back from
/// this step".
fn slot_answer(ctx: &Ctx, store: &ChatStore, thread: &str) -> Result<String> {
    Ok(slot_answer_row(ctx, store, thread)?
        .map(|m| m.body)
        .unwrap_or_default())
}

/// [`slot_answer`] with the ROW it read the body off, which is the whole of the difference: the
/// `sender` column beside the body is the engine's own record of who posted, which is what the
/// attribution notice around a delimited block promises a reader (nxf 6j6v.s0k5).
///
/// `None` — a slot with nothing on it but the supervisor's own writes — is a step that has not
/// answered yet, which is an ordinary state and not a failure. Only a message an agent action may
/// follow counts as the step's answer (nxf 6j6v.pzkb): its body is handed on as the next step's
/// input, so one nobody here can vouch for would otherwise supply the text a later step acts on. [`slot_answer`] flattens it to the
/// empty string because its one caller composes a notice around whatever it gets; a caller deciding
/// whether an answer EXISTS needs the two apart.
fn slot_answer_row(
    ctx: &Ctx,
    store: &ChatStore,
    thread: &str,
) -> Result<Option<crate::store::MessageRow>> {
    let supervisor = supervisor_qualified(ctx.origin);
    Ok(store
        .acting_messages_in_thread(thread)?
        .into_iter()
        .rev()
        .find(|m| m.sender != supervisor))
}

/// **The answer each step of this run has standing, by step id** (nxf 6j6v.s0k5) — the LAST one
/// where a step ran more than once, which is [`crate::channel::FlowStep::input`]'s own rule.
///
/// **Counted as the slots go by rather than asked per slot**, exactly as [`collected_replies`]
/// counts passes and for the same reason: `run_slots` preserves `supervised_children`' order, a
/// slot id is a ULID, so the n-th slot serving one step of one run IS its n-th pass. Every slot
/// advances the counter, including one that has not answered — so the pass number a carried answer
/// is marked with names the pass it came FROM, not how many have answered.
///
/// A step whose newest slot is still running therefore contributes its previous pass's answer,
/// which is what "its last answer" means and the only reading that is true while a run is in
/// motion.
fn run_answers(
    ctx: &Ctx,
    store: &ChatStore,
    channel_thread: &str,
    run: &str,
) -> Result<std::collections::BTreeMap<String, crate::channel::CollectedReply>> {
    let all = supervised_member_threads(ctx, store, channel_thread)?;
    let mut passes: std::collections::BTreeMap<String, u32> = std::collections::BTreeMap::new();
    let mut answers = std::collections::BTreeMap::new();
    for slot in run_slots(store, all, run)? {
        let Some(mark) = store.flow_mark(&slot.thread_id)? else {
            continue;
        };
        let seen = passes.entry(mark.step.clone()).or_insert(0);
        *seen += 1;
        let Some(row) = slot_answer_row(ctx, store, &slot.thread_id)? else {
            continue;
        };
        let placement = SlotPlacement {
            step: mark.step.clone(),
            pass: *seen,
        };
        answers.insert(mark.step, collected_from(row, Some(&placement))?);
    }
    Ok(answers)
}

/// **What one step is given out of the run** (nxf 6j6v.s0k5) — [`crate::channel::FlowStep::input`]
/// resolved against this run's record, and composed by
/// [`crate::channel::compose_step_input`].
///
/// **`None` means "the run's REQUEST, verbatim"** and is the answer for two thirds of every
/// declaration there is: a step that declares nothing and has no predecessor (the first step of
/// every run), and a step that declares `input: [request]`. Returning `None` rather than the
/// request itself is what keeps those paths byte-identical — the caller already holds the request
/// and has always passed it, so this function never has to re-derive it and can never disagree with
/// the caller about which message it is.
///
/// **A named step that has not answered in this run contributes nothing**, and that is not an
/// error: a first step naming a later one is legitimate, and there genuinely is no such answer yet.
/// Where NOTHING is left — `input: []`, or only names that have not run — the composer says so
/// rather than handing a session an empty message.
///
/// **The order is the declaration's**, with the request first wherever it is among the sources: it
/// is the question the run was asked, and reading an answer before it reads backwards.
fn step_input_body(
    ctx: &Ctx,
    store: &ChatStore,
    channel_thread: &str,
    entry: &StepEntry,
    into: &crate::channel::FlowStep,
) -> Result<Option<String>> {
    // The DEFAULTS, and they are what carries the ordinary channel: the first step of a run is
    // given the request, every later step the answer of the step whose edge it was reached over.
    let sources: Vec<&str> = match &into.input {
        Some(declared) => declared.iter().map(String::as_str).collect(),
        None => match entry.from.as_deref() {
            Some(previous) => vec![previous],
            None => vec![crate::channel::INPUT_REQUEST],
        },
    };
    if sources == [crate::channel::INPUT_REQUEST] {
        return Ok(None);
    }
    let request = match sources.contains(&crate::channel::INPUT_REQUEST) {
        true => current_request_row(store, channel_thread)?
            .map(|m| collected_from(m, None))
            .transpose()?,
        false => None,
    };
    // Read only where a step actually names one, so a step given the request alone — and the first
    // step of every run, which is that case — pays for no walk at all.
    let carried: Vec<crate::channel::CollectedReply> =
        match sources.iter().any(|s| *s != crate::channel::INPUT_REQUEST) {
            true => {
                let answers = run_answers(ctx, store, channel_thread, &entry.mark.run)?;
                sources
                    .iter()
                    .filter(|s| **s != crate::channel::INPUT_REQUEST)
                    .filter_map(|s| answers.get(*s).cloned())
                    .collect()
            }
            false => Vec::new(),
        };
    Ok(Some(crate::channel::compose_step_input(
        request.as_ref(),
        &carried,
    )))
}

/// **The step [`supervisor_advance_flow`] is about to open**, and everything about it that is not
/// re-derivable from the record (nxf 6j6v.553s (d)).
///
/// A struct rather than three parameters because two of the three are `Option`s and a call site that
/// gets them the wrong way round still compiles. It is also where the ONE difference between a
/// `flow: sequential` advance and a stepped one is written down: the first passes
/// `entry: None`/`body: None` ([`NextStep::to`]) and reads exactly as it did before this item.
struct NextStep<'a> {
    /// The declared role handle or channel name to commission.
    target: &'a str,
    /// What a STEPPED channel knows about the step it is opening — `None` for a channel that
    /// declares no `steps:`, and then this advance is byte-identical to what it was.
    entry: Option<StepEntry>,
    /// The task, when it is NOT the channel thread's own request. `Some` only on a back edge.
    body: Option<String>,
}

impl<'a> NextStep<'a> {
    /// The plain advance a `flow: sequential` channel makes — no entry, no body of its own.
    fn to(target: &'a str) -> Self {
        NextStep {
            target,
            entry: None,
            body: None,
        }
    }
}

/// **What a step of a DECLARED state machine knows about itself** (nxf 6j6v.553s (d), widened by
/// nxf 6j6v.y1t9) — the two facts [`open_flow_step`] cannot re-derive on its own, together because
/// they are `Some`/meaningful under exactly the same condition: the channel declares `steps:`.
///
/// Keeping them apart invited the bug they are paired against — a caller that stamped the mark and
/// forgot the resume decision would silently take the forward-edge default on a back edge, which is
/// precisely the shape this item exists to remove.
struct StepEntry {
    /// Which run and which step this slot serves — stamped on the commission that opens it, so it
    /// is durable before the session it starts can answer.
    mark: crate::store::FlowMark,
    /// **The step whose edge this one was reached over** (nxf 6j6v.s0k5) — what
    /// [`crate::channel::FlowStep::input`] means by "the immediate predecessor", and therefore what
    /// a step that declares nothing is given.
    ///
    /// `None` where there IS no predecessor: the first step of a run, whichever of the three
    /// openers starts it. Then the default is the run's own request, which is what every step was
    /// given before that field existed.
    ///
    /// It is carried rather than derived because only the caller knows it. Deriving it from the
    /// record would mean asking "which slot settled last", and on a back edge that is not the same
    /// question: `slots_to_consolidate` over-includes by design, and the newest slot of a run is
    /// not always the one whose edge was taken.
    from: Option<String>,
    /// **Continue the session this run already ran for the step's TARGET** rather than start a
    /// fresh one ([`crate::channel::FlowStep::resume`]). Already resolved against the edge's
    /// default by the caller that knows which edge it took; WHICH session that is, is re-derived
    /// from the record where the step is opened.
    resume: bool,
}

/// **Start the next step of an ordered flow** (nxf 6j6v.hq71) — the incoming router doing the one
/// thing that makes a channel a workflow: imposing an order.
///
/// Everything the step needs is re-derived from the record rather than carried across the wait, for
/// the same reason `fire_queued_trigger` re-resolves a declaration: nothing is carried across a
/// wait. What it re-derives it FROM is the version this operation is bound to (nxf 6j6v.n92p), so a
/// declaration edited since the channel opened does not reach this step.
///
/// * **the task** — the newest message on the channel thread from a party that is not the engine.
///   NEWEST-WINS, category 4 of the read taxonomy above, and it carries that category's assumption
///   and cost verbatim from [`supervisor_hand_out_next_turn`]: nothing gates who may post here, and
///   this string becomes the next step's whole task. The flow forwards the REQUEST rather than the
///   previous step's answer, deliberately — a step of a declared flow is commissioned by the channel,
///   not by whoever spoke last, and the previous answers are all in the tree for the consolidation
///   to gather.
/// * **the window** — the channel's declared `timeout`, resolved from NOW, so each step gets the
///   window the author declared rather than the remains of the one before it. A channel that declares
///   none falls back to the channel thread's own deadline, which is what an explicit `--deadline` at
///   the opening call set and what every step of a `parallel` fan-out gets.
///
/// A step that cannot be started is REPORTED, not propagated: the reply that settled the previous
/// step is durable by the time this runs, so `warnings` is the honest answer (nxf 6j6v.93zd, class
/// 1 — the flow is stopped and nothing retries it).
///
/// **"Nothing retries it" means nothing UNATTENDED, and after nxf 6j6v.858n that distinction has to
/// be spelled out** (review of PR #375, Code Quality #2). Widening [`TickMove::Advance`] to a step
/// that ANSWERED made a hand-run `nxc tick` over this thread reach here a second time — but only in
/// the narrow case where this call opened NOTHING before it failed: a step naming a nested channel
/// whose declaration has gone missing, or an unparseable `timeout:` (the `?` above, which never
/// reaches [`open_flow_step`] at all). For a ROLE step the slot thread is written before the trigger
/// is attempted, so a failed start leaves an unanswered slot, the set is no longer settled, and the
/// next tick's move is `Waiting` — the same "one attempt" this sentence has always promised. In
/// neither case does anything schedule a second attempt by itself: 858n's clock arms only while a
/// session is still alive, and this branch arms nothing.
/// Returns whether the step actually STARTED, because one caller has to know:
/// [`supervisor_hand_out_next_turn`] re-arms the channel thread only on success, and inferring that
/// from an empty `warnings` list would be a second, indirect spelling of the same fact.
fn supervisor_advance_flow(
    ctx: &Ctx,
    store: &mut ChatStore,
    channel: &ChannelDecl,
    channel_q: &ThreadQuorum,
    next: &NextStep<'_>,
    hop: CheckedHop,
) -> Result<(SupervisorRun, bool)> {
    let target = next.target;
    let request = current_request(store, &channel_q.thread_id)?;
    // **A REWORK carries the verdict, not the request** (nxf 6j6v.553s (a)), and that is the one
    // place this function does not forward the channel thread's own words. The findings ARE the
    // task on the way back — the notice above them says so in as many words — while on the normal
    // way on the request is the task, because a step of a declared flow is commissioned by the
    // channel and not by whoever spoke last.
    // **What a step is given out of the run** (nxf 6j6v.s0k5) — `input:`, or the defaults behind
    // it. `None` is "the request", which is the line below it and what every step was given before
    // that field existed; a `flow: sequential` channel declares no steps at all and carries no
    // `entry`, so it never asks.
    //
    // **Asked only on a FORWARD edge**, which is what the arm order says: a rework already carries
    // the reviewer's findings verbatim, and honouring `input` over that edge as well would hand the
    // same text over twice. That is [`crate::channel::FlowStep::input`]'s own rule, and it is
    // enforced here rather than described, by never reaching this derivation.
    let carried = match (&next.body, &next.entry) {
        (None, Some(entry)) => match channel.step(&entry.mark.step) {
            Some(into) => step_input_body(ctx, store, &channel_q.thread_id, entry, into)?,
            None => None,
        },
        _ => None,
    };
    let body = match (&next.body, carried) {
        (Some(rework), _) => rework.clone(),
        (None, Some(carried)) => carried,
        (None, None) => request.map(|(_, body)| body).unwrap_or_default(),
    };
    let spec = match channel.timeout.as_deref() {
        Some(when) => Some(facade::resolve_deadline_spec(
            ctx.now,
            when,
            "the channel's declared `timeout`",
        )?),
        None => None,
    };
    let deadline = match &spec {
        Some(s) => Some(s.at.clone()),
        None => channel_q.deadline.clone(),
    };
    let sup = as_supervisor(ctx, hop);
    let fan = SupervisorFanOut {
        channel,
        channel_id: channel_q.channel_id.as_deref().unwrap_or_default(),
        channel_thread: &channel_q.thread_id,
        body: &body,
        // Unused on this path: the step to open is named, not selected out of a set.
        members: &[],
        deadline: deadline.as_deref(),
        idle_window: spec.as_ref().and_then(|s| s.window),
        kind: MessageKind::Task,
        priority: Priority::Normal,
        model: None,
    };
    let mut run = SupervisorRun::default();
    let mut started = false;
    // An ORDERED flow opens exactly one step per pass, so there is never a sibling this call has
    // just started — the empty slice is the honest value, not a placeholder (nxf 6j6v.2d00).
    match open_flow_step(
        &sup,
        store,
        &fan,
        target,
        next.entry.as_ref(),
        &mut run.warnings,
        &[],
    ) {
        // **A refused advance is REPORTED** (nxf 6j6v.n92p) — the other half of [`StepOpened`]'s
        // fork. The reply that got us here is durable, so nothing after it may fail the call; the
        // refusal rides that reply's own receipt as its declared class, and `started` stays false so
        // [`supervisor_hand_out_next_turn`] leaves the channel thread's register where the previous
        // consolidation put it.
        //
        // Nothing retries it, exactly as for a step that could not be STARTED — and here that is
        // the point rather than a residual: a hurdle refuses because the world is not ready, and an
        // engine that quietly kept asking would be a busy-wait on a human's working copy. The
        // requester was told, in the receipt of the call it made, and asking again is its move.
        Ok(StepOpened::Refused(refusal)) => {
            let finding = FailedConsequence::precondition_refused(
                &channel_q.thread_id,
                target,
                &channel.name,
                refusal,
            );
            eprintln!("warning: {finding}");
            run.warnings.push(finding);
        }
        Ok(StepOpened::Opened(_)) => {
            started = true;
            // This step's own window needs watching, and turn one's one-shot job is spent by now —
            // the same argument, and the same re-read, as `supervisor_hand_out_next_turn`'s.
            run.warnings.extend(rearm_after_the_members_moved(
                ctx,
                store,
                &channel_q.thread_id,
            ));
        }
        Err(e) => {
            let detail = format!(
                "step {target:?} of channel {:?} was never started: {e}. The flow stops here — the \
                 previous step's answer is durable, and nothing retries this",
                channel.name
            );
            eprintln!("warning: {detail}");
            run.warnings.push(FailedConsequence::step_skipped(
                Some(&channel_q.thread_id),
                None,
                step_skip_reason(&e),
                detail,
            ));
        }
    }
    Ok((run, started))
}

/// **Did this turn's settled set carry an escalation?** — nxf 6j6v.wt37, asked of a channel thread.
///
/// The set is the supervisor's own children of the CURRENT PASS ([`current_pass`] over
/// [`ChatStore::supervised_children`], the one rule for "which threads are the set" — for an ordered
/// flow that is the pass running now, not every step of every pass), and each member's answer is read
/// with [`ChatStore::last_reply_escalated`] — TURN-scoped, because "what did this member SAY this turn"
/// is a question about what was said. One member is enough: a set is not a result while any part of
/// it says it could not be produced, and the error direction is the benign one (a claim held too
/// long beats a working copy released while the work is mid-flight).
///
/// **Where the answer is USED — and it is no longer one path out of two.** It decides which OUTPUT
/// FORM the consolidator runs at all ([`ChannelDecl::consolidation`](crate::channel::ChannelDecl::consolidation),
/// nxf 6j6v.e9qj): an escalating set is never folded, so it is discharged through the pass-through
/// path — the `__delivered__` marker, which the ENGINE writes — whatever the channel declared. The
/// escalation therefore rides one level up on BOTH output forms.
///
/// **And since nxf 6j6v.ma7v it decides something one step earlier: WHETHER an ordered flow is
/// consolidated at all.** On a [`Flow::Sequential`](crate::channel::Flow::Sequential) channel an
/// escalating set ends the chain instead of opening the next step — so this answer is read by
/// [`supervisor_consider_set`] before its ordered branch and passed down to the consolidation, one
/// derivation for both. That is the reason the read is hoisted above the branch rather than sitting
/// where it used to, immediately before the consolidating call.
///
/// **This doc used to say the opposite, and how that was found is the part worth keeping.** It
/// described the `summarize` half as an open gap and named e9qj as future work. When that gap
/// closed, item wt37 had handed over a list of THREE artefacts that must move together — the
/// characterisation test, `last_reply_escalated`'s doc, and the EN+DE changelog clause. All three
/// moved, and the report truthfully said so. This doc was a FOURTH nobody had listed.
///
/// **And the corrected count of four was itself one short**: `route_declared_channel_completion`'s
/// PUBLIC rustdoc still spelled the workflow-advance skip as `on_complete == Summarize`, which this
/// item's own rule had made false. So the list was re-derived twice and was wrong both times.
///
/// **The rule that follows is therefore not a number.** Do not work an inherited "these N artefacts
/// move together" list; RE-DERIVE it first — search the gap's own terms (`set_escalated`,
/// `last_reply_escalated`, `summarize`, `escalat`) across `src`, `tests`, `changes/` and `docs/`, and
/// diff the result against the list you were handed. The difference is exactly what would otherwise
/// stand there telling readers the opposite of the code. And when you WRITE such a list, ship the
/// search you derived it with, not only its result: a list with its derivation is checkable, one
/// without it is a claim. Recorded in the project's durable memory as
/// `handover-lists-are-themselves-unverified`.
///
/// **Its code-level twin is on this branch**: [`crate::channel::RESERVED_HANDLE_PREFIX`], where an
/// enumeration of engine identities was replaced by a CLASS rule after that enumeration had been
/// wrong for exactly one round. Same failure, one level down — a list is a thing the next author has
/// to remember to extend, whether it lives in code or in a hand-off.
///
/// **This function is still not a cross-module escape hatch** — it is private, so a caller elsewhere
/// cannot reach it. The reachable shape is the one [`ChatStore::last_reply_escalated`]'s own doc
/// names: ask it of the CHANNEL thread (which now answers for both forms), or walk the MEMBER threads
/// with the `pub` [`ChatStore::supervised_children`]. This function is simply that walk, done here
/// for the supervisor's own branch.
///
/// **The working-tree claim is a different read, and deliberately not this one** (nxf 6j6v.1xw1, and
/// corrected here after that item's first cut got it wrong): [`ChatStore::work_scope_handed_back`]
/// asks the whole claim area rather than one level of members, and asks the wider question "was the
/// task handed back", which an open QUESTION satisfies and an escalation-only read does not. A
/// one-level read there released the working copy under a reviewer that was still waiting — see that
/// function's own doc for the shape.
fn set_escalated(ctx: &Ctx, store: &ChatStore, channel_q: &ThreadQuorum) -> Result<bool> {
    for member in slots_to_consolidate(ctx, store, channel_q)? {
        if store.last_reply_escalated(&member.thread_id)? == Some(true) {
            return Ok(true);
        }
    }
    Ok(false)
}

/// Fold the set and deliver it — the channel's declared `on_complete` policy, run on the CHANNEL
/// thread, with the answers gathered from the member threads.
///
/// It routes through [`route_declared_channel_completion`] rather than around it, deliberately: the
/// requester resolution, the `pass_through` idempotency marker and `summarize`'s single-claimant
/// synthesizer are all one mechanism, and a second copy of it for the supervised shape is how the
/// two would come apart.
///
/// `escalated` is the one thing the supervisor decided above it (nxf 6j6v.wt37) and the reason it is
/// passed rather than re-derived: the branch belongs at the seam, not scattered through the routing.
fn supervisor_consolidate(
    ctx: &Ctx,
    store: &mut ChatStore,
    channel_q: &ThreadQuorum,
    escalated: bool,
    note: Option<&str>,
    hop: CheckedHop,
) -> Result<SupervisorRun> {
    // **The ROOT's return address, deliberately LIFETIME-scoped** (the turn-scoping sweep's one
    // deliberate exception). Everything else around the supervisor had to become turn-scoped; this
    // must not, because the identity it names is itself stable for the thread's whole life: an
    // internal session id is never re-minted on a resume — `resume_return_address`,
    // `wake_role_requester` and `supervisor_resume_member` all pass the SAME id back into
    // `RoleSpawn::internal_session` — so the session that commissioned this channel on turn one is
    // the session still behind it on turn five. Reading "the newest return address" instead would
    // answer the same on every reachable path today, which is exactly why the ROOT is read
    // deliberately rather than by accident: the root is where the address a completion routes back
    // through was stamped, and a later message from somebody else is not that address.
    //
    // (Until 6j6v.dvyq §3 this paragraph named a second reason — the run engine's `workflow-run:`
    // sentinel, which only ever rode on the root and which reading the newest address would have
    // broken. That sentinel is gone with the runs; the reason above stood on its own beside it.)
    let msgs = store.acting_messages_in_thread(&channel_q.thread_id)?;
    let addr = match msgs.first() {
        Some(root) => store.message_return_address(&root.message_id)?,
        None => None,
    };
    // An empty address is the requester that left none — a human at a bare terminal. The routing
    // still runs (the channel thread has to reach `complete`, which is what the PULL surfaces
    // `opener_wake`/`inbox` read), and the wake it would have attempted is correctly reported as
    // "nobody was owed one" rather than as a failure — see `wake_role_requester`.
    let addr = addr.unwrap_or_default();
    // **What this fold has no answer from** (nxf 6j6v.rs9k), read BEFORE the routing retargets the
    // thread the pass is derived from. An ordered flow now moves PAST a step whose window ran out,
    // so the set that reaches here can legitimately be missing one — and a delivery that quietly
    // leaves it out is the "silently absorbed" shape this item's own decision forbids.
    let mut warnings = lapsed_step_findings(ctx, store, channel_q)?;
    // **THE ONE PLACE A STOPPED ROUND IS TOLD IT HAS AN EXIT** (nxf 6j6v.am8j). Every way a
    // supervised round comes to rest passes through here — the ceiling, an escalating member, a
    // lapsed window, the plain end — so the offer is made here rather than at the one of them that
    // happened to be measured. See [`accept_offer_note`] for what it asks before offering anything.
    let offer = accept_offer_note(ctx, store, channel_q);
    let note = match (note, offer.as_deref()) {
        (Some(why), Some(offer)) => Some(format!("{why} {offer}")),
        (None, Some(offer)) => Some(offer.to_string()),
        (why, None) => why.map(str::to_string),
    };
    match route_declared_channel_completion_with(
        ctx,
        store,
        channel_q,
        &addr,
        Some(escalated),
        note.as_deref(),
        hop,
    )? {
        Some(routed) => {
            warnings.extend(routed.warnings);
            Ok(SupervisorRun {
                woke: routed.woke,
                wake_skipped: routed.wake_skipped,
                held: routed.held,
                completed: Some(routed.outcome),
                warnings,
                advanced: false,
            })
        }
        None => Ok(SupervisorRun::default()),
    }
}

/// The incoming router, second turn and onwards: hand every member its next turn on its OWN existing
/// thread.
///
/// **That is the PARALLEL channel's second turn. An ORDERED one starts its flow over instead** (nxf
/// 6j6v.hq71) — step one, on a fresh slot thread, and each later step when the one before it settles,
/// exactly as its first request went. Waking every member of the previous pass at once would turn a
/// declared sequence into a fan-out on its second use. Everything below this paragraph describes the
/// parallel path only.
///
/// Two writes per member, in this order and both load-bearing:
///
/// 1. **the re-declaration** — [`facade::set_expects`], opener-only, and the supervisor IS the
///    opener of a member thread. Since nxf 6j6v.cg8g a re-declaration re-opens the debt for the turn
///    it declares, so this is what makes the member owe an answer again and what
///    `reply --if-unanswered` (the sidecar's teardown net) then discharges. Nothing else in the
///    engine does this on a resume, which is exactly the gap 6j6v.cg8g could only close at the
///    predicate level.
/// 2. **the resume**, carrying `reply_thread` — the obligation travels with the trigger, so the
///    spawned session is told what it owes and its teardown has something to settle. A plain
///    `role_resume` passes `None` there on purpose (it declares no obligation); this path declares
///    one, so it must.
///
/// The channel thread is re-armed first, for the same reason: without it the supervisor would not be
/// the party owing an answer up there and the set's eventual completion would consolidate into a
/// thread that considers itself finished.
///
/// **And one write for the turn as a whole, after the loop**: the one-shot job that watches the
/// windows this turn just restarted ([`rearm_member_window`]). Turn one's job chain has ended by the
/// time a second turn is handed out, so without it turn two's strike would depend on somebody else
/// asking — the exact state nxf 6j6v.nf38 corrected for the first turn.
fn supervisor_hand_out_next_turn(
    ctx: &Ctx,
    store: &mut ChatStore,
    channel_q: &ThreadQuorum,
    members: &[ThreadQuorum],
    hop: CheckedHop,
) -> Result<SupervisorRun> {
    let supervisor = supervisor_qualified(ctx.origin);
    let sup = as_supervisor(ctx, hop);
    // What the requester just asked — the newest message in the channel thread from a party that is
    // not the engine, the same rule `collected_replies` opens a turn with. `.last()` alone is right
    // on every path that reaches here today (the reply is posted immediately before the supervisor
    // runs) and would silently forward the `[pass_through delivered]` marker, or a synthesis, on any
    // path that ever is not.
    //
    // **NEWEST-WINS, so it rests on an assumption nothing enforces**: that exactly one message opens
    // a turn on the channel thread. `reply` has no membership gate, so nothing stops a requester
    // posting twice before the supervisor runs, or a third party posting here at all — and then "the
    // newest" is the last of several.
    //
    // **What that costs is worse HERE than at `collected_replies`, and the difference is the reason
    // this is written out twice rather than cross-referenced.** There, a stray message displaces one
    // quoted line in a rendering. Here, this string becomes the TASK every member is handed and
    // resumed with: a message that was never the requester's instruction would be sent to the whole
    // channel as its next turn's work. Nothing is corrupted and nothing routes on it — the obligation
    // and the discharge are the register's, not this text's — but the blast radius is every member
    // session, not a line of prose. Enforcing it means a membership gate on `reply`, which is the
    // access-control design (nxf 6j6v.6aza) and not a decision this function may take on its own.
    //
    // **What IS decided here is the signature half** (nxf 6j6v.pzkb): only a message an agent action
    // may follow can become the task, so an unsigned, altered or untrusted one is never handed to a
    // member as work, whoever it claims to be from.
    let body = store
        .acting_messages_in_thread(&channel_q.thread_id)?
        .into_iter()
        .rev()
        .find(|m| !is_engine_identity(&m.sender))
        .map(|m| m.body)
        .unwrap_or_default();
    // The re-declaration of the CHANNEL thread — the requester asked again, so the supervisor owes
    // again. Authored by the thread's own recorded opener, which is who `set_expects` admits.
    let opener = channel_q.opener.clone().unwrap_or_default();
    let rearm_channel_thread = |store: &mut ChatStore| -> Result<()> {
        facade::set_expects(
            store,
            ctx.now,
            &opener,
            &channel_q.thread_id,
            std::slice::from_ref(&supervisor),
        )?;
        Ok(())
    };

    // **An ORDERED channel starts its flow over rather than waking everybody** (nxf 6j6v.hq71). A
    // second request to a channel whose order is declared is a second run of that order: step one
    // first, and each later step when the one before it settles, exactly as the first request went.
    // Waking every member of the previous pass at once would turn a declared sequence into a fan-out
    // on its second use — the silent divergence this item exists to remove.
    //
    // The pass gets FRESH slot threads, which is what makes each pass answerable on its own: a slot
    // carries one obligation and one answer, and [`current_pass`] reads back the pass running now.
    //
    // **The channel thread is re-armed only once step one has actually STARTED, and that ordering is
    // the fix for a stale answer** (review round 1). A step can fail to start and mint no slot at all
    // — `open_flow_step` propagates every preflight of a nested CHANNEL step before it opens
    // anything. (It could also fail because a declaration read for pass one had changed by pass two;
    // since nxf 6j6v.n92p it cannot, because the operation is bound to one version — but a refused
    // PRECONDITION reaches the same shape, so the ordering below is no less load-bearing.) Re-arming
    // first
    // would then leave the channel thread owing the supervisor with NO slot of the new pass beneath
    // it, and the next reply or tick would re-enter [`supervisor_consider_set`], find the PREVIOUS
    // pass — settled, complete, about a request nobody made now — and deliver it as the answer to
    // this one. Leaving the register where the previous consolidation put it makes that impossible:
    // `supervisor_consider_set` returns early unless the supervisor is the party owing an answer. The
    // requester is not left guessing either — the `step_skipped` finding rides the very receipt of
    // the reply that asked, which is the whole point of the supervisor being synchronous.
    if let Some(channel) = declared_channel_of(ctx, channel_q)
        .filter(|c| c.is_stepped() || c.flow == crate::channel::Flow::Sequential)
        .cloned()
    {
        // **A STEPPED channel starts a NEW RUN here** (nxf 6j6v.553s (d)), and that is what makes
        // the pass counter reset itself: the follow-up the requester just posted is the new run's
        // id, so the slots this run opens carry a mark none of the previous run's slots share, and
        // `rework_hops` counts from zero again. The owner's *"Bekommt er aber die Erlaubnis von
        // oben, wird max_passes wieder auf Null gesetzt und weiter gemacht"* is therefore the
        // ordinary behaviour of a re-commission rather than a second mechanism.
        let steps = flow_steps(&channel, channel_q.opener.as_deref());
        let next = match channel.first_step() {
            Some(first) => {
                let Some((run, _)) = current_request(store, &channel_q.thread_id)? else {
                    return Ok(SupervisorRun::default());
                };
                NextStep {
                    target: &first.target,
                    entry: Some(StepEntry {
                        mark: crate::store::FlowMark {
                            run,
                            step: first.id.clone(),
                        },
                        // A NEW run has no slots of its own yet, so there is nothing of it to
                        // continue whatever the declaration says. Honoured rather than hardcoded,
                        // so every step opener reads the same way.
                        resume: first.resume.unwrap_or(false),
                        // The first step of the new run, so no predecessor and no answer of this
                        // run's to carry (nxf 6j6v.s0k5). The PREVIOUS run's answers are not this
                        // one's: a run is the unit, and `run_answers` reads the mark.
                        from: None,
                    }),
                    body: None,
                }
            }
            None => match steps.first() {
                Some(first) => NextStep::to(first),
                None => return Ok(SupervisorRun::default()),
            },
        };
        let (run, started) = supervisor_advance_flow(ctx, store, &channel, channel_q, &next, hop)?;
        if started {
            rearm_channel_thread(store)?;
        }
        return Ok(run);
    }
    rearm_channel_thread(store)?;

    let mut run = SupervisorRun::default();
    for member in members {
        let Some(handle) = member.expects.first().cloned() else {
            // A member thread whose expectation was dropped is a member the supervisor was told to
            // stop waiting for; it takes no further turn.
            continue;
        };
        facade::set_expects(
            store,
            ctx.now,
            &supervisor,
            &member.thread_id,
            std::slice::from_ref(&handle),
        )?;
        // **A new turn restarts this member's clock** (nxf 6j6v.nf38; the born-stale minor carried
        // forward from nxf 6j6v.cg8g). The line above re-declares the obligation, which makes
        // `outstanding` non-empty again — and `stale` is "past the deadline AND something is
        // outstanding". A turn declared after the previous window has run out would therefore be
        // born `stale`, which `member_set_is_settled` and `nxc tick` both read as DUE: the
        // supervisor would consolidate turn two the instant anything asked, with nobody's answer in
        // it. The member has just been asked, so its window starts now — the same event, and the
        // same restart, as a sign of life in its transcript.
        //
        // A no-op for a member with no armed clock, which includes the deliberate case: a deadline
        // given as an absolute instant declares a point in time and is not restarted by anything,
        // so a second turn asked after it has passed is genuinely overdue.
        store.reset_member_deadline(&member.thread_id, ctx.now)?;
        let session = store
            .thread_assignee_sessions_for(&[member.thread_id.as_str()])?
            .into_iter()
            .next()
            .map(|(_, s)| s);
        let Some(session) = session else {
            // Nothing was ever put to work on this thread ON THIS DEVICE. The obligation stands and
            // the PULL surfaces show it; there is simply no session here to resume.
            continue;
        };
        // **Through [`wake_message`], like every other hand-over** (independent review of PR #378,
        // Code Quality #4). This was the THIRD literal of the same sentence — nxf 6j6v.ntp9 folded
        // the surface's and `open_flow_step`'s into one function and left this one standing, so a
        // later edit to the plumbing line, or a decision to put `ESCALATION_NOTICE` in front of a
        // forwarded turn, would have reached three of the four entrances and silently kept the old
        // wording for a member's SECOND turn.
        let wake = wake_message(
            &body,
            false,
            // `handle` is the member's own QUALIFIED identity — the one the re-declaration above
            // just put back into `expects_reply_from`, so the block this composes names the very
            // obligation that was declared a few lines up.
            &reply_guidance(store, ctx.now, &handle, Some(&member.thread_id)),
        );
        // The forwarded turn, posted by the supervisor into the member's own thread — the member
        // must be able to read what it was asked without being told to go and look somewhere else.
        //
        // **And it records where the working copy stood** (nxf 6j6v.2af2, added on the independent
        // review of PR #474): this is a turn changing hands like any other — a live member session
        // is resumed two lines down — and it was the one handover the anchor missed. No return
        // address travels with it (the supervisor is not a session), which is exactly why keying the
        // stamp on `with_return_address`'s sites was the wrong reading; see [`with_working_copy`].
        facade::send(
            store,
            facade::SendRequest {
                now: ctx.now,
                origin: ctx.origin,
                actor: crate::channel::SUPERVISOR_HANDLE,
                channel: member.channel_id.as_deref().unwrap_or_default(),
                body: &body,
                kind: MessageKind::Task,
                priority: Priority::Normal,
                disposition: Disposition::InTurn,
                thread: Some(&member.thread_id),
                refs: with_working_copy(ctx, Refs::default()),
            },
        )?;
        // **ONE receipt for N resumes, and since nxf 6j6v.93zd that no longer means N-1 findings on
        // the floor.** `woke`/`wake_skipped` still carry the FIRST of each kind — a single-valued
        // field cannot do otherwise, and it is a published contract — but every member the
        // supervisor could not start is now recorded in `warnings`, which is what makes "the message
        // is durably in this member's thread and nobody is working on it" answerable for member 3 of
        // 5 rather than only for member 1.
        //
        // The class is decided here, where it is known: a member being handed its next turn is a
        // STEP being triggered (design §10.5's own case), not a requester being woken.
        let attempt =
            supervisor_resume_member(&sup, store, &session, &wake, &member.thread_id, hop);
        if run.woke.is_none() {
            run.woke = attempt.woke;
        }
        if let Some(skipped) = attempt.skipped {
            // The detail says what did not happen and then WHY, rather than handing on a bare
            // error: this record's reader is looking at one entry among several and needs to know
            // which member is unattended without reconstructing it from the ids.
            let detail = match &skipped.detail {
                Some(e) => format!(
                    "the next turn of thread {} was never started — session {} could not be \
                     resumed: {e}",
                    member.thread_id, skipped.session
                ),
                None => format!(
                    "the next turn of thread {} was never started — session {} no longer resolves \
                     to a live role",
                    member.thread_id, skipped.session
                ),
            };
            run.warnings.push(FailedConsequence::step_skipped(
                Some(&member.thread_id),
                Some(&skipped.session),
                skipped.reason,
                detail,
            ));
            if run.wake_skipped.is_none() {
                run.wake_skipped = Some(skipped);
            }
        }
    }
    // **Turn two's own strike, scheduled here** (nxf 6j6v.nf38). The loop restarted every member's
    // clock; nothing was watching it. Turn one's chain is over by the time this runs — the set
    // settled, so the fan-out's one-shot job either fired and acted or was overtaken by the
    // synchronous `reply` path, and an `at` job fires exactly once. Without this, a second turn falls
    // back to the state this item corrected for the first: the strike happens only if somebody else
    // happens to ask.
    //
    // **The members are re-read, and that is the load-bearing part.** The quorums handed in were
    // taken BEFORE the loop, so they still carry turn one's spent deadlines — which
    // [`rearm_member_window`]'s future-only filter would (rightly) discard, scheduling nothing at
    // all. What must be watched is the window each member was just given.
    //
    // **All slots, deliberately NOT [`current_pass`]** (nxf 6j6v.hq71 — recorded rather than changed,
    // and re-grounded in review round 4). Every OTHER site that asks "which slots are the set"
    // narrows to the current pass; this one does not.
    //
    // The reason given in round 1 was that an earlier pass's slots are always settled and their spent
    // windows can only be discarded by [`rearm_member_window`]'s future-only filter. **That premise
    // is the one declared FIRED at `tick`'s own note** — a follow-up posted while a step is
    // still working leaves an earlier pass ending unsettled — so it is not what makes this site safe.
    // What makes THIS site safe is narrower and does not depend on it: the sequential branch above
    // returns before ever reaching this loop, so everything that gets here is a
    // [`Flow::Parallel`](crate::channel::Flow::Parallel) channel, which has exactly one pass and for
    // which `current_pass` returns every slot anyway. The distinction is vacuous here rather than
    // merely harmless.
    //
    // Narrowing would therefore be a second definition of the pass that changes nothing at all, so
    // the inconsistency is written down instead of hidden.
    //
    // Best-effort in both halves, like every other scheduling site in this file: the reply is
    // persisted and the members are already resumed, so a failed read costs the automatic nudge and
    // never the turn.
    run.warnings.extend(rearm_after_the_members_moved(
        ctx,
        store,
        &channel_q.thread_id,
    ));
    Ok(run)
}

/// Resume the session standing on a member thread with its next turn. Skip, never fail: the reply
/// that caused this is persisted by the time it runs, so a role that is no longer declared or a
/// worker that refuses the spawn is reported, exactly as every other wake site in this module reports
/// its own.
fn supervisor_resume_member(
    sup: &Ctx,
    store: &mut ChatStore,
    session: &str,
    wake: &str,
    member_thread: &str,
    hop: CheckedHop,
) -> WakeAttempt {
    let unresolved = || {
        eprintln!(
            "warning: the channel supervisor could not hand session {session} its next turn on \
             thread {member_thread} — it no longer resolves to a live role"
        );
        WakeAttempt {
            held: None,
            woke: None,
            skipped: Some(WakeSkipped {
                session: session.to_string(),
                reason: WakeSkipReason::Unresolved,
                detail: None,
            }),
            findings: Vec::new(),
        }
    };
    let Ok(Some(role_handle)) = store.session_role(session) else {
        return unresolved();
    };
    let (Ok(resume_real), Ok(decl)) = (store.resolve_real(session), sup.defs.role(&role_handle))
    else {
        return unresolved();
    };
    let decl = decl.clone();
    match trigger_role(
        sup,
        store,
        RoleSpawn {
            decl: &decl,
            internal_session: session.to_string(),
            resume_real,
            message: wake,
            // The channel supervisor, handing a member its next turn (nxf 6j6v.ntp9).
            coordinator: Coordinator::Channel,
            model_override: None,
            hop,
            // NEW work for this member, not an answer travelling back up: the depth guard counts
            // exactly this axis, and a supervisor handing out turns in a loop is the runaway shape it
            // exists to bound.
            chain: ChainMove::Deeper,
            // The obligation this call just re-declared, travelling with the trigger.
            reply_thread: Some(member_thread),
            thread: Some(member_thread),
            priority: Priority::Normal,
            queued_since: None,
        },
    ) {
        Ok(admission) => WakeAttempt {
            held: None,
            woke: Some(session.to_string()),
            skipped: None,
            // The turn handed out here is the shape closest to the measured incident of nxf
            // 6j6v.pkw9 — a member running turn after turn under rules that quietly moved — so a
            // finding this trigger produced must reach the receipt, not this function's floor.
            findings: admission_findings(&admission),
        },
        Err(e) => {
            eprintln!(
                "warning: the channel supervisor could not start session {session} for its next \
                 turn on thread {member_thread}: {e}"
            );
            WakeAttempt {
                held: None,
                woke: None,
                skipped: Some(WakeSkipped {
                    session: session.to_string(),
                    reason: wake_skip_reason(&e),
                    detail: Some(e.to_string()),
                }),
                // Nothing started, so there is nothing it could have noticed.
                findings: Vec::new(),
            }
        }
    }
}

// `orchestration::ask` was here — the ROUTER that decided between a declared channel and a raw
// one. REMOVED by nxf 6j6v.dvyq §3 with the raw channels: with every channel declared there is
// nothing to route between, and `surface::send_to`'s channel branch reaches the declared half
// directly through [`open_declared_channel_and_fan_out`]. `facade::ask_under` — the write it
// called for the raw half — stays, because that same fan-out is built on it.

// ---- reply ------------------------------------------------------------------------------

/// A reply to post — and to ROUTE once posted (nxf 6j6v.7dw6).
#[derive(Debug, Clone)]
pub struct ReplyRequest<'a> {
    /// A thread id or a message id. A message target inherits that message's thread (if any); a
    /// thread target IS the thread.
    pub target: &'a str,
    pub body: &'a str,
    pub kind: MessageKind,
    pub priority: Priority,
    pub disposition: Disposition,
    pub refs: Refs,
    /// Per-call model override for the session this reply RESUMES through the target's own return
    /// address — the caller is choosing a model for the turn it is handing over. A
    /// quorum-completion wake is deliberately NOT covered: it resumes a THIRD party (the board's
    /// opener, or a declared channel's requester), whose model is that role's own declaration to
    /// make, not this replier's.
    pub model: Option<Model>,
    /// Post ONLY if the caller still owes a reply on the resolved thread (nxf 6j6v.ww0a, `nxc reply
    /// --if-unanswered`) — see [`facade::reply`]'s doc for exactly what "still owes" means. `false`
    /// (the default shape every existing caller keeps) is today's unconditional post, unchanged.
    /// **No seam verb takes this any more** (nxf 6j6v.ckeq, decision 4): it is not an agent option
    /// but the idempotency switch of the sidecar teardown (`worker.rs`, nxf 6j6v.ww0a), so it left
    /// `Engine` with `Engine::reply` itself. The mechanism is untouched — `surface::settle_if_
    /// unanswered` is the named entrance the teardown reaches it through, and this field is what it
    /// sets.
    pub if_unanswered: bool,
}

/// What a reply produced. Declared field order = the JSON contract.
///
/// `resumed`/`woke`/`completed` exist because the alternative is a caller GUESSING: an app that
/// replies through the library handle and gets back a bare message id cannot tell whether it just
/// completed a review board, spawned a synthesizer or moved a channel's flow on. That silence is the
/// exact bug this ticket fixes (the handle's reply used to post and stop), so the receipt says what
/// happened. The handle verb it names has since become [`crate::engine::Engine::reply_thread`], the
/// one reply form left on the seam (nxf 6j6v.ckeq); the receipt it returns is this one.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct ReplyReceipt {
    /// Whether this call actually wrote a message (nxf 6j6v.ww0a). Always `true` unless
    /// [`ReplyRequest::if_unanswered`] was set AND the caller no longer owed a reply on the thread —
    /// the ONE way this verb can succeed without posting. Every other field on this receipt describes
    /// what the post did; when `posted` is `false` none of them ran, and this is the single field a
    /// caller checks to tell "posted, nothing to route" apart from "correctly skipped".
    pub posted: bool,
    /// `None` only when `posted` is `false` — there is no message to name.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub message_id: Option<String>,
    /// The thread the reply landed in, when it landed in one at all.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub thread_id: Option<String>,
    /// `true` iff the reply resumed the TARGET's own return-address session — the direct 1:1 path
    /// (`nxc reply --json`'s `resumed` field verbatim). A quorum-completion wake is not a "resume"
    /// in this sense and never sets this; the two are mutually exclusive by construction, since the
    /// direct path is skipped entirely for a thread that is a quorum board.
    ///
    /// `false` covers two different things, and [`ReplyReceipt::wake_skipped`] is what separates
    /// them (nxf 6j6v.0akf): there was no return-address session to resume at all, or there was one
    /// and the resume was attempted and did not land.
    pub resumed: bool,
    /// The session this reply woke, if any: the direct resume's target, the opener of a
    /// (non-declared) board this reply completed, or the requester a declared channel's
    /// `on_complete` policy delivered to. `None` when nothing was woken — which since nxf 6j6v.bxdd
    /// (and, for the direct resume, 6j6v.0akf) means one of two distinguishable things, and
    /// [`ReplyReceipt::wake_skipped`] is what distinguishes them: there was nothing to wake (no
    /// return address, an address that is not a registered role session, a `summarize` phase 1 that
    /// is still waiting on its synthesizer), or a wake WAS attempted and did not land.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub woke: Option<String>,
    /// The wake that was ATTEMPTED and did not land — the completion routing's (nxf 6j6v.bxdd) or
    /// the direct 1:1 resume's (nxf 6j6v.0akf). `None` whenever nothing failed — including every
    /// case where there was simply nothing to wake, which is what keeps `resumed: false` and
    /// `woke: None` on their own readable.
    ///
    /// This is the visible half of "skip, don't fail" (see [`reply`]): the reply IS persisted, so
    /// returning `Err` would lie about it, but a bare `Ok` would swallow the fact that the next role
    /// was never woken — and a workflow that stalls because of it is noticed by nobody. Both seams
    /// report it; on the CLI it is `nxc reply --json`'s `wake_skipped` key, alongside the stderr
    /// breadcrumb a terminal reader sees.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub wake_skipped: Option<WakeSkipped>,
    /// The declared channel's completion routing result, when this reply completed a board backed
    /// by one. `None` for an ordinary reply AND for a completing reply into a plain (non-declared)
    /// channel, which has no `on_complete` policy to run.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub completed: Option<CompletionOutcome>,
    /// **Everything this call should have caused and did not** — the defined, readable place of nxf
    /// 6j6v.93zd, and the reason the supervisor runs synchronously at all (hq71 §1): the session that
    /// is still executing this very call is the only addressee a failed consequence has.
    ///
    /// **ALWAYS present, never `#[serde(skip_serializing_if)]`, empty on every reply that caused
    /// nothing to fail** — [`TriggerReceipt::warnings`]'s argument verbatim: a field that appears only
    /// on failure forces every reader into a case distinction, and a reader who forgets to make it
    /// never sees the failure, which is precisely the class this closes.
    ///
    /// [`wake_skipped`](ReplyReceipt::wake_skipped) is the FIRST of its class in this list and is
    /// repeated in it. It stays because it is a published contract with its own readers; this is
    /// what a caller reads when it wants ALL of them, which is the only reading that does not
    /// silently lose a second un-woken member or a consolidation that could not start.
    pub warnings: Vec<FailedConsequence>,
    /// **The answer was HELD for a caller that is working** (nxf 6j6v.gn8b) — the session it is
    /// waiting for, and `None` on every reply that woke somebody or had nobody to wake.
    ///
    /// [`woke`](ReplyReceipt::woke)'s sibling and the THIRD outcome of a hand-off: `woke` says the
    /// caller is running with this now, [`wake_skipped`](ReplyReceipt::wake_skipped) says a wake was
    /// attempted and lost, and this says the caller was mid-turn, so the delivery is in the
    /// coordinator's durable queue and goes out — with everything else that arrives meanwhile — as
    /// soon as that session settles.
    ///
    /// Before it, this case WAS `wake_skipped: {reason: "already_running"}`, which read as a
    /// failure and was one: nothing held the answer, so the caller was simply never told. A replier
    /// that reads this knows its answer landed AND that somebody will receive it.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub held: Option<String>,
    /// **How this caller learns what happens next** (nxf 6j6v.7qfm) — the twin of
    /// [`crate::surface::SendToReceipt::await_`], on the verb that hands a turn BACK.
    ///
    /// Whoever answers is in the same position the requester was: they have said their piece and
    /// the surface used to say nothing at all about what follows. The block names the thread's own
    /// two reads, the predicate for done, the predicate for stopped, where the answer sits and the
    /// declared window — see [`crate::awaiting`] for the contract in full.
    ///
    /// **`None` from this verb, `Some` from the surface**, and that split is deliberate:
    /// [`crate::surface::reply_in_thread`] is where the caller's identity is resolved, and the
    /// advice for a registered persona is the OPPOSITE of the advice for everybody else. This verb
    /// knows the routing; it does not know who is at the other end of the command line. A receipt
    /// that reached a caller through the surface — every `nxc reply` and every
    /// [`crate::engine::Engine::reply_thread`] — always carries it.
    /// **The machine this chat was handed to instead of started here** (nxf 6j6v.1c6k) — `Some`
    /// exactly when the chat's designated machine is another one: nothing was started on this
    /// machine, and that one picks the order up after its next pull. Skipped when absent, so every
    /// receipt of a chat that runs where it was written is byte-identical to before.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub handed_to: Option<crate::machine::ExecutingMachine>,
    #[serde(rename = "await")]
    pub await_: Option<crate::awaiting::Await>,
}

/// A wake that was attempted and did not land — a completion wake, or the direct 1:1 resume.
///
/// **Why a struct and not just a reason string.** An app is the only consumer that has no other
/// channel for this — the stderr breadcrumb goes to the *host process's* stderr, where an embedder's
/// UI will never see it — so the receipt has to carry enough to act on: WHICH session was left
/// un-woken (`session`, so the app can name it, re-drive it or surface it), WHY in a form worth
/// branching on (`reason`), and the underlying failure for a human to read (`detail`). Declared
/// field order = the JSON contract, as everywhere else in this module.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct WakeSkipped {
    /// The return-address session the wake was aimed at.
    pub session: String,
    pub reason: WakeSkipReason,
    /// The underlying error, rendered as `kind: msg` — a diagnostic, not a branching surface
    /// (that is [`WakeSkipReason`]'s job). `None` for [`WakeSkipReason::Unresolved`], on every path,
    /// where the resolution failure is deliberately collapsed to "did not resolve" (see
    /// [`resolve_quorum_wake_target`] and [`resume_return_address`]).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
}

/// Why a session was not put in motion. Two cases to begin with, because they call for different
/// responses: an `Unresolved` requester is *gone* (the board is orphaned — nothing to retry), while a
/// `TriggerFailed` one is still there and the spawn plumbing is what broke (retryable, and usually a
/// configuration fault).
///
/// **The name says "wake" and the question is wider** (nxf 6j6v.93zd/6j6v.6m6x). It is also the
/// reason a step that was never STARTED carries — [`FailedConsequence::reason`] — because "why did
/// this session not come to life" has one answer whether the session was being woken or freshly
/// spawned, and [`wake_skip_reason`] is the one classifier both go through. Renaming it would break
/// a published surface for a word; the name is historical, the taxonomy is not.
///
/// `#[non_exhaustive]` for the same reason [`Model`] is: this surface goes irreversibly public with
/// the open-source launch, and a third reason later must be an additive minor rather than a break
/// for every downstream `match`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "snake_case")]
#[non_exhaustive]
pub enum WakeSkipReason {
    /// The return-address session no longer resolves to a live role: a session-map row that is gone,
    /// a role file deleted or gone malformed since the address was stamped, or an I/O failure
    /// reading either.
    Unresolved,
    /// The role resolved, but [`Worker::trigger`] refused or failed the spawn.
    TriggerFailed,
    /// The role resolved and the worker was reached, but the RUNTIME SESSION behind the return
    /// address no longer exists — reaped for idleness, past its maximum lifetime, or otherwise
    /// gone without anyone being told (nxf 6j6v.5x9j; [`crate::worker::TriggerError::SessionGone`]).
    ///
    /// Split out of [`TriggerFailed`](WakeSkipReason::TriggerFailed) because the two call for
    /// opposite responses and the caller cannot tell them apart otherwise: a failed spawn is worth
    /// retrying against the same session, a vanished one never is — it needs a fresh session or an
    /// escalation. On a cloud runtime this is the ROUTINE outcome of a slow board, not an incident.
    SessionGone,
    /// **The session was already running, so it was not started a second time** (nxf 6j6v.7qtf;
    /// [`crate::worker::TriggerError::AlreadyRunning`]).
    ///
    /// The one reason in this enum that reports a mechanism WORKING rather than a consequence
    /// failing, and it is here anyway, because the caller has to be able to see it: this is the
    /// answer to a wake that arrived while its session was still mid-turn, and what the caller
    /// needs to know is that the message is durably in the thread and nobody was started for it.
    /// The alternative — the second spawn — is what destroyed a coder's work under a sibling
    /// process it could not see.
    ///
    /// Split from [`TriggerFailed`](WakeSkipReason::TriggerFailed) for that enum's own rule: the
    /// two call for opposite responses. A failed spawn invites a retry; this one must NOT be
    /// retried while it holds, and a caller that treats it as an incident would re-drive the very
    /// loop the guard exists to stop.
    AlreadyRunning,
    /// **The session was not started because it is IN LINE for the working copy** (nxf 6j6v.de9s).
    ///
    /// Only one shape reaches it, and it is the shape that item builds: an answer to an escalation
    /// arriving for an operation whose work was PARKED. The park handed that operation's checkout to
    /// somebody else, so its resume contends for it like any other trigger — and when the copy is
    /// busy, the resume goes into the queue instead of walking into a tree it no longer owns.
    ///
    /// **Nothing has to be done about it, which is what makes it its own reason.** The message is
    /// durably in the thread, the trigger's inputs are durably in the queue, and the next release
    /// starts it — so unlike [`TriggerFailed`](WakeSkipReason::TriggerFailed) it must NOT be
    /// retried, and unlike [`AlreadyRunning`](WakeSkipReason::AlreadyRunning) there is nothing to
    /// wait out at the other end. A caller that treated it as an incident would be reporting the
    /// queue working.
    Queued,
}

/// A wake attempt's findings as the ONE record type (nxf 6j6v.93zd) — empty when it landed and
/// noticed nothing.
///
/// **Two kinds, and the name says so since PR #425's review.** It was `not_woken_findings`, and the
/// name was a true claim about a body that produced exactly one class: every caller wakes the party
/// which ASKED for the answer, so a skip here is [`ConsequenceClass::RequesterNotWoken`] at all of
/// them (a site that starts a fresh STEP records [`FailedConsequence::step_skipped`] instead and
/// does not come through here). It now also carries what the wake NOTICED while succeeding —
/// [`WakeAttempt::findings`] — and a function still called `not_woken_findings` would have been a
/// name that quietly stopped describing its body.
fn wake_findings(thread: &str, attempt: &WakeAttempt) -> Vec<FailedConsequence> {
    attempt
        .skipped
        .iter()
        .map(|w| FailedConsequence::not_woken(Some(thread), w))
        .chain(attempt.findings.iter().cloned())
        .collect()
}

/// Which skip reason a [`TriggerError`] amounts to — written once, here, because all four wake
/// sites classify the same error the same way and a copy per site is how they would drift apart.
fn wake_skip_reason(e: &TriggerError) -> WakeSkipReason {
    if e.is_session_gone() {
        WakeSkipReason::SessionGone
    } else if e.is_already_running() {
        WakeSkipReason::AlreadyRunning
    } else {
        WakeSkipReason::TriggerFailed
    }
}

/// Which skip reason a failed flow STEP amounts to (nxf 6j6v.hq71). [`open_flow_step`] hands back
/// one [`NxfError`] for several causes — a target that no longer declares a role or a channel, a
/// malformed nested declaration, a worker that refused the spawn — so this classifies by kind and no
/// finer than the runtime itself can tell: a target that no longer resolves is `Unresolved`,
/// everything else is a start that did not happen.
fn step_skip_reason(e: &NxfError) -> WakeSkipReason {
    if e.kind == ErrorKind::NotFound {
        WakeSkipReason::Unresolved
    } else {
        WakeSkipReason::TriggerFailed
    }
}

// `AdvanceFailed` stood here — a run that stayed at its current step because the advance its
// channel's completion should have driven could not be carried out. REMOVED with the run record
// (6j6v.dvyq §3). A channel's supervisor is what decides a flow's next move now, and when IT cannot
// put a member in motion the finding is a `StepSkipped`, which is the class that already describes
// it.

/// **ONE consequence of this call that did not happen** — the defined, readable place nxf 6j6v.93zd
/// builds, and the element type of every receipt's `warnings`.
///
/// # Why there has to be a place at all
///
/// Design §4.3 names it as the price of loose coupling: *"if a reply should advance a step and the
/// advance fails, the answering party has long since acknowledged. The answer arrived, the
/// consequence did not — and nobody learns of it."* §10.5 proves it at the source rather than
/// suspecting it: a step whose triggering fails is NOT retried, it is reported as skipped with a
/// breadcrumb on stderr, and that is all. A breadcrumb goes to the HOST PROCESS's stderr, where an
/// embedding app's UI never sees it and an agent parsing `--json` never sees it either.
///
/// # Why one record and not a field per case
///
/// Because "one defined place" is the acceptance, and three fields that each carry one kind of
/// failure are three places. [`WakeSkipped`] came first, for the one case its own ticket met, and
/// dropped everything it had no field for — a second un-woken member, a consolidation that could
/// not start. This carries all of them, in the order the call discovered them, with the class named
/// so a caller can branch without reading prose.
///
/// # The classes are hq71's, not invented here
///
/// The DoD asks for "ein Test je Klasse: übersprungener Schritt, nicht geweckter Anforderer,
/// gescheiterte Weiterschaltung" — and [`ConsequenceClass`] is exactly those three, plus the fourth
/// shape the board note of 2026-08-15 added to the third. `crates/chat/tests/failed_consequences.rs`
/// is one test per class, each breaking a real consequence at the real path.
///
/// **The list is not frozen, and one class has been added since** (nxf 6j6v.rs9k):
/// [`ConsequenceClass::StepUnanswered`], for a step that WAS started and let its window run out.
/// hq71 could not have named it — it needs both halves of the seam this repo only had after
/// 6j6v.nf38 built the per-member deadline. Its test is `channel_flow.rs`'s pair on the lapsed
/// middle step, at the same real path as the rest: a declared window, and nobody answering inside
/// it.
///
/// # What is deliberately NOT here
///
/// A retry, and a fallback. The item is explicit that neither exists today and that the caps present
/// are abort brakes rather than retry strategies. The job is to make a failure VISIBLE, not to make
/// it not happen. Declared field order = the JSON contract, as everywhere else in this module.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
#[non_exhaustive]
pub struct FailedConsequence {
    /// Which of hq71's classes this is — the one field a caller branches on.
    pub class: ConsequenceClass,
    /// The thread the consequence belonged to: the member thread whose step was never started, the
    /// thread a wake was owed on, the channel thread whose completion drove an advance. `None` only
    /// where the call touched no thread at all.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub thread: Option<String>,
    /// The session that was to be started or woken and was not — so an app can name it, watch it or
    /// re-drive it. `None` for a failure that is not about one session.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub session: Option<String>,
    /// **Why a session was not put in motion, machine-readably** (nxf 6j6v.6m6x: "aus der Quittung
    /// eines fehlgeschlagenen Triggers ist maschinenlesbar erkennbar, WARUM nicht gestartet wurde —
    /// mindestens so fein, wie `TriggerError` es heute schon unterscheidet"). `None` where the
    /// question does not arise.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reason: Option<WakeSkipReason>,
    /// The failure in words — a diagnostic for a human and the text an app surfaces. Always present,
    /// and what [`Display`](std::fmt::Display) renders, so the stderr breadcrumb a terminal reader
    /// sees and the record an app reads say the same thing.
    pub detail: String,
    /// **Which hurdle refused, and what it produced** (nxf 6j6v.n92p) — present exactly on
    /// [`ConsequenceClass::PreconditionRefused`], `None` on every other class.
    ///
    /// It is the structured half of decision 3. The class alone already tells "a hurdle said no"
    /// from "the step failed"; this tells WHICH hurdle and shows its output, so a requester can act
    /// on the answer — re-run the one rule, name it back to a human — instead of matching
    /// substrings in [`detail`](FailedConsequence::detail), which is the free text the decision
    /// exists to replace.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub precondition: Option<crate::precondition::Refusal>,
    /// **Which role changed, and between which two versions** (nxf 6j6v.pkw9) — present exactly on
    /// [`ConsequenceClass::DeclarationChanged`], `None` on every other class.
    ///
    /// The structured half, for [`precondition`](FailedConsequence::precondition)'s reason: the
    /// class already says "the declaration is not the one the last spawn used"; this says whose and
    /// which, so a caller can look the version up, diff it or name it back to a human instead of
    /// pulling a hex string out of [`detail`](FailedConsequence::detail).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub declaration: Option<DeclarationChange>,
}

/// **The two versions a role was spawned under, either side of a change** (nxf 6j6v.pkw9) — the
/// payload of [`FailedConsequence::declaration`].
///
/// Both hashes are FULL, never the shortened form the prose uses: this is the record a caller
/// compares against a `spec.json`'s `declarationHash` or against
/// [`crate::declaration_freeze`]'s stored catalogue, and a truncated value there would be a value
/// that only sometimes matches.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
#[non_exhaustive]
pub struct DeclarationChange {
    /// The role handle whose declaration changed — unqualified, as it is declared and as
    /// `send --to` names it.
    pub role: String,
    /// The version THIS spawn runs under: `crate::declaration_version::role_declaration_hash` of
    /// the declaration its prompt was composed from, and the same value its `spec.json` carries as
    /// `declarationHash`.
    pub hash: String,
    /// The version the PREVIOUS spawn of this role ran under.
    pub previous_hash: String,
    /// When that previous spawn was recorded, so a reader can say how long the role had been
    /// running under the old version.
    pub previous_seen: String,
}

/// Which class of consequence failed — hq71's own three, plus the fourth shape recorded on the board
/// on 2026-08-15, minus the two that went with the run record, plus nxf 6j6v.rs9k's window class.
/// The list moves; what does not move is that the class is decided where the failure happens.
///
/// `#[non_exhaustive]` for [`WakeSkipReason`]'s reason: this surface goes irreversibly public with
/// the open-source launch, and a further class must be an additive minor rather than a break for
/// every downstream `match`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "snake_case")]
#[non_exhaustive]
pub enum ConsequenceClass {
    /// **A step whose triggering failed** — hq71's first class, and design §10.5's own words. The
    /// message is durably in the channel, the obligation is registered, and nobody is working on it.
    /// Nothing retries it.
    StepSkipped,
    /// **A requester that was not woken** — hq71's second class. Its board completed, its answer is
    /// sitting there, and the session that asked for it was never told.
    RequesterNotWoken,
    /// **A step that was started and never answered** — nxf 6j6v.rs9k's class, and the first one
    /// here that is about a WINDOW rather than about a spawn. The step ran, its declared window ran
    /// out with nothing in it, and what followed — the next step of an ordered flow, or the
    /// consolidation that ends it — happened WITHOUT that step's answer.
    ///
    /// Deliberately not [`StepSkipped`](ConsequenceClass::StepSkipped), which a reader branches on
    /// to mean "nobody was ever put to work on this": here somebody was, and the two call for
    /// opposite responses — a step that never started is plumbing to fix, a step that stayed silent
    /// is a member to chase. [`FailedConsequence::reason`] is `None` on this class for the same
    /// reason: nothing was being started, so none of [`WakeSkipReason`]'s answers applies to it.
    StepUnanswered,
    /// **The one-shot job that watches a declared `timeout:` was not scheduled** (nxf 6j6v.p3sm) —
    /// the call succeeded, the board is open, and NOTHING will ever notice that its window ran out.
    ///
    /// It is the third class about a WINDOW rather than a spawn, and the first about the MACHINERY
    /// of one. [`StepUnanswered`](ConsequenceClass::StepUnanswered) says a window passed with
    /// nothing in it; this says the window has no clock at all, so that finding can never be
    /// produced here. `nxc guide channels` describes `timeout:` as the fuse that releases a round —
    /// "a step whose window ran out with nothing in it" settles like one that answered — and
    /// without a tick a member that goes quiet holds the round FOREVER.
    ///
    /// **It was a line on stderr and nothing else**, on a path where nobody reads a terminal: a
    /// scheduled job runs unattended and an embedding app never sees the host's stderr at all. That
    /// is the same shape as every other class here, which is why it is one.
    ///
    /// A caller that sees this is not stuck: `nxc tick --thread <id>` is idempotent and callable by
    /// hand, and the [`detail`](FailedConsequence::detail) says so along with why the platform could
    /// not do it. [`reason`](FailedConsequence::reason) is `None` — nothing was being started or
    /// woken, so none of [`WakeSkipReason`]'s answers applies.
    TickUnscheduled,
    /// **A step a PRECONDITION refused to let start** (nxf 6j6v.n92p) — the declared class
    /// decision 3 of [`crate::precondition`] asks for.
    ///
    /// Deliberately not [`StepSkipped`](ConsequenceClass::StepSkipped), which a reader branches on
    /// to mean "the plumbing failed and nobody was put to work". Here the plumbing worked
    /// perfectly: a rule the project itself declared — or one the engine brings along — looked at
    /// the world and said not yet. The two call for opposite responses (fix the machinery / fix the
    /// working copy), and telling them apart by reading a sentence is what nxf 6j6v.gk9j showed
    /// does not survive the trip.
    ///
    /// [`FailedConsequence::precondition`] carries WHICH hurdle and WHAT it produced, so a
    /// requester never has to parse [`FailedConsequence::detail`] to find out.
    /// [`reason`](FailedConsequence::reason) is `None`: nothing was being started yet, so none of
    /// [`WakeSkipReason`]'s answers describes it — the step was stopped BEFORE the trigger, which
    /// is the whole point of the hurdle.
    PreconditionRefused,
    /// **A declared verdict with nowhere to go** (nxf 6j6v.553s (a)) — a step answered
    /// `--needs-rework` and its own declaration names no `on_needs_rework:` edge, so the flow
    /// continued over `next` as if the answer had been plain.
    ///
    /// **It is a DIAGNOSIS and not a failure**, which is why it is its own class rather than a
    /// `StepSkipped`: nothing failed, nothing was skipped, and the round is not worse off than it
    /// would have been without the bit. What it answers is a question that would otherwise take a
    /// transcript to answer at all — *why does this channel keep receiving verdicts it cannot act
    /// on?* — and the answer is almost always the same one: the channel is under-declared.
    ///
    /// It should be RARE by construction, and that is the point of reporting it: the bit is not even
    /// offered to a step that declares no edge ([`crate::role::ReplyObligation::may_ask_for_rework`]),
    /// so reaching this means somebody found the flag some other way. A channel that produces it
    /// steadily is telling you something about its declaration.
    ///
    /// [`reason`](FailedConsequence::reason) is `None`: nothing was being started or woken.
    VerdictDropped,
    /// **There is no background service doing this workspace's work** (nxf 6j6v.0j12) — the same
    /// honesty as [`TickUnscheduled`](ConsequenceClass::TickUnscheduled), one level up.
    ///
    /// `TickUnscheduled` says "this window has no clock". This says "there is nobody to run any of
    /// it", and it is a strictly bigger statement in two directions:
    ///
    /// - it does not need a window. A workspace with no declared `timeout:` anywhere is just as
    ///   affected and used to hear nothing at all;
    /// - it is not only the clock. The owner decision of 2026-08-25 made the ONE service the only
    ///   timekeeper, and it was already the only sync — so while it is down, declared windows do not
    ///   fire AND this machine's op log neither pushes nor pulls. Both halves are named in
    ///   [`detail`](FailedConsequence::detail), from
    ///   [`nxs_service::ServiceFault`], so no reader ever hears about one and not the other.
    ///
    /// Before the singleton (6j6v.8see) the clock was self-carrying — `launchd` fired a job per
    /// deadline whether anything was running or not — and this failure case did not exist. Since
    /// then it has existed and been SILENT: `nxs sync daemon status` answers on request, and nobody
    /// asks.
    ///
    /// Raised only for a workspace that is REGISTERED with the service. An unregistered workspace
    /// never asked for any of this, and a warning there would be a permanent line on every call for
    /// a machine behaving exactly as arranged.
    ///
    /// Like `TickUnscheduled` it does NOT make the verb exit non-zero: the call did everything it
    /// was asked. [`FailedConsequence::reason`] is `None` — nothing was being started or woken.
    ServiceNotRunning,
    /// **This role was last spawned under a DIFFERENT version of its declaration** (nxf 6j6v.pkw9).
    ///
    /// The rarest kind of entry in this list and the only one that is not about something failing:
    /// the spawn happened, the session is running, and what is reported is that the rules it runs
    /// under are not the rules the previous run of the same role ran under. It is closest to
    /// [`VerdictDropped`](ConsequenceClass::VerdictDropped) — a DIAGNOSIS the caller could
    /// otherwise only reach by holding a stored `spec.json` against a file by hand, which is
    /// literally how the incident behind the item was found.
    ///
    /// **A change is usually intended; an unnoticed one never is**, which is the whole argument for
    /// reporting rather than refusing. `.nxs-personas/` is runtime configuration in the working
    /// copy the declared agents themselves work in, so a `git switch`, a `stash` or a
    /// `checkout -- .` by one persona changes how the NEXT one thinks — a feedback loop no other
    /// configuration in this system has. In the proving ground it rolled three declarations back
    /// silently and 4 of 251 threads ended with the runtime answering in a persona's place.
    ///
    /// [`FailedConsequence::declaration`] carries WHICH role and WHICH two versions, so nobody
    /// parses [`detail`](FailedConsequence::detail) for a hash. `reason` is `None`: nothing was
    /// skipped, nothing failed to start. It does NOT change a verb's exit code — see
    /// `crate::cli`'s `changes_the_exit_code`, where the rule and its exceptions are stated.
    DeclarationChanged,
    /// **An operation's work was NOT parked, so the working copy stays where it is** (nxf
    /// 6j6v.de9s; since nxf 6j6v.8bv9 only for a refusal that can pass).
    ///
    /// A park is what a trouble hand-off runs INTO: commit the operation's work onto a branch and
    /// hand the checkout to whoever is waiting. A refusal that waiting can change —
    /// [`crate::park::ParkRefusal::MidSequence`], [`crate::park::ParkRefusal::Git`] — leaves two
    /// facts standing together, and a reader has to be told both: the work is still uncommitted in
    /// the tree, AND the commission behind it is still queued. The detail names what to fix; `nxc
    /// status` shows the same refusal on the holding operation (`PARK REFUSED`); and the background
    /// service retries the park on every tick, so fixing it is all a reader has to do.
    ///
    /// **Its own class rather than a [`StepSkipped`](ConsequenceClass::StepSkipped)**, which a
    /// reader branches on to mean "a session was to be started and was not". Nothing was being
    /// started here; something was being SAVED and was not, and the two call for opposite responses
    /// — a skipped step is plumbing to fix, an un-parked operation is a working copy to go and look
    /// at by hand.
    ///
    /// It does NOT make the verb exit non-zero, for [`TickUnscheduled`](ConsequenceClass::
    /// TickUnscheduled)'s reason: the tick did everything it was asked, and the queue is in exactly
    /// the state it was in before — visible, and retried. [`FailedConsequence::reason`] is `None`:
    /// nothing was being started or woken.
    WorkNotParked,
    /// **The working copy was handed on WITHOUT parking the operation's work** (nxf 6j6v.8bv9).
    ///
    /// The other half of the refusal rule: a refusal that waiting cannot change —
    /// [`crate::park::ParkRefusal::is_permanent`]: the host names no working copy, the directory is
    /// not a repository, no base branch was ever recorded — would hold the queue for ever if the
    /// claim stayed. So the copy goes on anyway, and this is the loud half of that: whatever the
    /// operation left uncommitted is still in the tree, now in the NEXT holder's hands, and the
    /// detail says which refusal and that.
    ///
    /// **Not [`WorkNotParked`](ConsequenceClass::WorkNotParked)**, whose reader is told the claim
    /// stayed and a retry is coming. Here the claim went and nothing is coming back for the work: a
    /// reader who branched on one class for both would wait for a park that will never happen.
    ///
    /// It does NOT make the verb exit non-zero, for `WorkNotParked`'s reason: the verb did what it
    /// was asked, and the finding is the whole of what went differently. [`FailedConsequence::reason`]
    /// is `None`: nothing was being started or woken.
    WorkHandedOnUnparked,
    /// **A session `withdraw` asked to stop, and the stop did not land** (nxf 6j6v.b9nf): the
    /// worker said it stops sessions and then could not — a pid file gone missing, a signal the
    /// operating system refused, a runtime that answered with an error.
    ///
    /// The thread's debt is ALREADY discharged when this is raised, deliberately: a withdrawal is
    /// first of all the register saying the round is over, and that part stood before the stop was
    /// even attempted. What is left standing is the process — still writing into the checkout if
    /// the round held it — and that is what this names, with the session, so a person can stop it
    /// by hand. The marker that parks its work is written all the same, so once the process is
    /// gone by whatever means the tick parks and hands on as if the stop had landed.
    ///
    /// It DOES make `nxc withdraw` exit non-zero, unlike the two park classes above it, and the
    /// house rule decides it the same way: those report a tree to fix while the verb did everything
    /// it was asked; this reports that the one act the verb exists for did not happen. A script
    /// that never parses JSON has to learn that the session is still running.
    /// [`FailedConsequence::session`] names it; [`FailedConsequence::reason`] is `None` — nothing
    /// was being started or woken.
    SessionNotStopped,
    /// **A withdrawn holder's stopped session has not left after several liveness cadences** (nxf
    /// 6j6v.b9nf, Integrity #2 of this item's review) — the SIGTERM was delivered, the marker
    /// stands, and [`park_a_withdrawn_holder`] has re-armed its own look [`WITHDRAWN_HOLDER_WARN_
    /// AFTER_CADENCES`] times running without the session it is waiting on ever going away.
    ///
    /// **Not [`SessionNotStopped`](Self::SessionNotStopped)**, which fires once, at `withdraw`
    /// itself, for a stop that did not land AT ALL (a missing pid file, a signal the OS refused).
    /// This is the opposite shape: the stop DID land — [`SessionNotStopped`](Self::SessionNotStopped)
    /// was never raised, or was and this is later — and the process simply has not exited: a wedged
    /// sidecar, a custom worker whose stop returns `Ok` and changes nothing, a reused pid. Before
    /// this class existed a person had no way to learn any of that from `nxc tick`'s own output; the
    /// claim stayed pinned, silently, for as long as the process did — which the removed `nxc
    /// release` verb at least refused BY NAME while it existed (see `withdraw`'s own history for
    /// that framing).
    ///
    /// **It does NOT make `nxc tick` exit non-zero** — simpler than `cli::changes_the_exit_code`'s
    /// list, which this class never reaches: `park_a_withdrawn_holder` runs only inside `tick`, and
    /// `cli::tick` never asks that function of ANY class its receipt carries, for
    /// [`WorkNotParked`](Self::WorkNotParked)'s own reason — the tick did what it was asked, and a
    /// background job that is red for a condition nobody at the terminal can fix is a status
    /// nobody reads.
    ///
    /// **Since nxf 6j6v.27b9 the tick that raises it has also sent ONE further SIGTERM** (the
    /// owner's decision of 2026-09-20 — it used to send none, on the ground that reusing a
    /// possibly-wrong pid was the owner's call): through the worker's own stop, so behind the same
    /// identity guard as the first, and never more than once. The detail says when it went or why
    /// it did not land. And it is raised only for a session the withdrawal ITSELF stopped — a
    /// session a human's follow-up put back in motion pins the claim too, and is not wedged.
    /// [`FailedConsequence::session`] names the pinning session; [`FailedConsequence::reason`] is
    /// `None`.
    WithdrawnHolderWedged,
    // `AdvanceFailed` and `NoVerdict` stood here — hq71's third class and its second
    // manifestation, both about a run that did not move on. REMOVED with the run record
    // (6j6v.dvyq §3). Nothing else ever produced them: they were the two classes only the
    // channel-step advance could raise.
}

impl std::fmt::Display for FailedConsequence {
    /// The breadcrumb's own wording, so the stderr line a terminal reader sees and the record an app
    /// reads never drift apart.
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.detail)
    }
}

impl FailedConsequence {
    /// A step that was to be started and was not (nxf 6j6v.93zd, class 1).
    pub(crate) fn step_skipped(
        thread: Option<&str>,
        session: Option<&str>,
        reason: WakeSkipReason,
        detail: impl Into<String>,
    ) -> Self {
        FailedConsequence {
            class: ConsequenceClass::StepSkipped,
            thread: thread.map(str::to_string),
            session: session.map(str::to_string),
            reason: Some(reason),
            detail: detail.into(),
            precondition: None,
            declaration: None,
        }
    }

    /// A step that was started and answered nothing inside its own declared window (nxf 6j6v.rs9k).
    ///
    /// `thread` is the step's OWN slot thread, so an app can name the silent member and go and look
    /// at it. No `session` and no `reason`: nothing was being started or woken here, so there is
    /// neither a session that failed to come up nor a start failure to classify — the failure is
    /// that a window passed.
    pub(crate) fn step_unanswered(thread: Option<&str>, detail: impl Into<String>) -> Self {
        FailedConsequence {
            class: ConsequenceClass::StepUnanswered,
            thread: thread.map(str::to_string),
            session: None,
            reason: None,
            detail: detail.into(),
            precondition: None,
            declaration: None,
        }
    }

    /// **A verdict the channel declares no transition for** (nxf 6j6v.553s (a)) — set, dropped, and
    /// said out loud.
    ///
    /// `thread` is the slot whose answer carried it, so an operator can go and read what was
    /// actually said. No `session` and no `reason`: nothing was being started or woken, and nothing
    /// failed — a step answered with a bit its declaration has nowhere to send.
    pub(crate) fn verdict_dropped(thread: &str, step: &str, channel: &str) -> Self {
        FailedConsequence {
            class: ConsequenceClass::VerdictDropped,
            thread: Some(thread.to_string()),
            session: None,
            reason: None,
            detail: format!(
                "step {step:?} of channel {channel:?} answered with `--needs-rework`, and that step \
                 declares no `on_needs_rework:` edge — the verdict was DROPPED and the flow \
                 continued over `next`. Nothing was lost from the answer itself; what is missing is \
                 a declared place for the verdict to go. If this channel is meant to send work back, \
                 declare the edge on that step"
            ),
            precondition: None,
            declaration: None,
        }
    }

    /// An operation whose work could not be parked (nxf 6j6v.de9s) — see
    /// [`ConsequenceClass::WorkNotParked`]. `thread` is the claim root, which is the operation this
    /// is about; a scope whose key names no thread reports `None` rather than inventing one.
    pub(crate) fn work_not_parked(thread: Option<&str>, detail: impl Into<String>) -> Self {
        FailedConsequence {
            class: ConsequenceClass::WorkNotParked,
            thread: thread.map(str::to_string),
            session: None,
            reason: None,
            detail: detail.into(),
            precondition: None,
            declaration: None,
        }
    }

    /// A working copy handed on without its holder's work being parked (nxf 6j6v.8bv9) — see
    /// [`ConsequenceClass::WorkHandedOnUnparked`]. `thread` is what [`Self::work_not_parked`]'s is:
    /// the thread of the operation whose work was left in the tree.
    pub(crate) fn work_handed_on_unparked(thread: Option<&str>, detail: impl Into<String>) -> Self {
        FailedConsequence {
            class: ConsequenceClass::WorkHandedOnUnparked,
            thread: thread.map(str::to_string),
            session: None,
            reason: None,
            detail: detail.into(),
            precondition: None,
            declaration: None,
        }
    }

    /// A session a withdrawal asked to stop, and the stop that did not land (nxf 6j6v.b9nf) — see
    /// [`ConsequenceClass::SessionNotStopped`]. `thread` is the discharged thread the session stood
    /// in and `session` the one still running, so a reader can go straight to the process.
    pub(crate) fn session_not_stopped(
        thread: &str,
        session: &str,
        detail: impl Into<String>,
    ) -> Self {
        FailedConsequence {
            class: ConsequenceClass::SessionNotStopped,
            thread: Some(thread.to_string()),
            session: Some(session.to_string()),
            reason: None,
            detail: detail.into(),
            precondition: None,
            declaration: None,
        }
    }

    /// A session that still pins a withdrawn holder after several liveness cadences (nxf 6j6v.b9nf,
    /// Integrity #2 of this item's review) — see [`ConsequenceClass::WithdrawnHolderWedged`].
    /// `thread` is [`Self::work_not_parked`]'s: the claim's own thread, `None` for a scope that names
    /// no thread to anchor on.
    pub(crate) fn withdrawn_holder_wedged(
        thread: Option<&str>,
        session: &str,
        detail: impl Into<String>,
    ) -> Self {
        FailedConsequence {
            class: ConsequenceClass::WithdrawnHolderWedged,
            thread: thread.map(str::to_string),
            session: Some(session.to_string()),
            reason: None,
            detail: detail.into(),
            precondition: None,
            declaration: None,
        }
    }

    /// The tick that watches a declared `timeout:` and was not scheduled (nxf 6j6v.p3sm).
    ///
    /// `thread` is the board whose window now has no clock, so a caller can name it and run
    /// `nxc tick --thread <id>` against it. No `session` and no `reason`: nothing was being started
    /// or woken, so there is neither a session that failed to come up nor a start failure to
    /// classify — what failed is the scheduling of a job.
    pub(crate) fn tick_unscheduled(thread: &str, detail: impl Into<String>) -> Self {
        FailedConsequence {
            class: ConsequenceClass::TickUnscheduled,
            thread: Some(thread.to_string()),
            session: None,
            reason: None,
            detail: detail.into(),
            precondition: None,
            declaration: None,
        }
    }

    /// The service that runs every window and every sync is not running (nxf 6j6v.0j12).
    ///
    /// `thread` is the thread the calling verb was about, so an app can say WHERE it noticed rather
    /// than only that it did. No `session` and no `reason`: nothing was being started or woken —
    /// what failed is that nothing is attending this workspace at all.
    pub(crate) fn service_not_running(thread: &str, detail: impl Into<String>) -> Self {
        FailedConsequence {
            class: ConsequenceClass::ServiceNotRunning,
            thread: Some(thread.to_string()),
            session: None,
            reason: None,
            detail: detail.into(),
            precondition: None,
            declaration: None,
        }
    }

    /// A wake that was attempted and did not land (class 2), from the finding the wake sites already
    /// produce — so the two say the same thing by construction rather than by copying.
    pub(crate) fn not_woken(thread: Option<&str>, skipped: &WakeSkipped) -> Self {
        FailedConsequence {
            class: ConsequenceClass::RequesterNotWoken,
            thread: thread.map(str::to_string),
            session: Some(skipped.session.clone()),
            reason: Some(skipped.reason),
            detail: skipped.detail.clone().unwrap_or_else(|| {
                "the return-address session did not resolve to a live role".to_string()
            }),
            precondition: None,
            declaration: None,
        }
    }

    /// **A step a hurdle would not let start** (nxf 6j6v.n92p).
    ///
    /// `thread` is the CHANNEL thread the step belongs to, never a slot thread: the gate runs
    /// before anything is opened, so there is no slot to name — and that absence is the honest
    /// signal that nothing was minted. No `session` and no `reason` for the same reason: nothing
    /// was being started, so there is neither a session that failed to come up nor a start failure
    /// to classify.
    pub(crate) fn precondition_refused(
        thread: &str,
        step: &str,
        channel: &str,
        refusal: crate::precondition::Refusal,
    ) -> Self {
        FailedConsequence {
            class: ConsequenceClass::PreconditionRefused,
            thread: Some(thread.to_string()),
            session: None,
            reason: None,
            detail: refusal.detail(step, channel),
            precondition: Some(refusal),
            declaration: None,
        }
    }

    /// **A role spawned under a different declaration than the last time it ran** (nxf 6j6v.pkw9).
    ///
    /// `thread` is the conversation this spawn belongs to and `session` the session it started, so
    /// a reader can go straight to the run that is affected — both are known here, unlike on the
    /// classes above that report something which never started. No `reason`: nothing was skipped,
    /// so none of [`WakeSkipReason`]'s answers describes this.
    ///
    /// **The sentence says what changed, what to do, and why it is being told at all**, in that
    /// order, because it is read by a person who did not necessarily make the change — that is the
    /// whole incident behind the item, where a persona's edit was rolled back by a third party's
    /// branch hygiene. The last clause is not decoration: an unversioned edit to a declaration is
    /// not an edit at all once agents work in the same tree, and that is the fix.
    pub(crate) fn declaration_changed(
        thread: Option<&str>,
        session: &str,
        role: &str,
        hash: &str,
        previous: &crate::declaration_version::PreviousSpawn,
    ) -> Self {
        use crate::declaration_version::short;
        FailedConsequence {
            class: ConsequenceClass::DeclarationChanged,
            thread: thread.map(str::to_string),
            session: Some(session.to_string()),
            reason: None,
            detail: format!(
                "the declaration of {role} changed since it was last started: this session runs \
                 under {}, the previous one ({}) ran under {} — if you did not mean to change it, \
                 the folder `.nxs-personas/` is where to look, and it belongs in version control",
                short(hash),
                previous.seen,
                short(&previous.hash),
            ),
            precondition: None,
            declaration: Some(DeclarationChange {
                role: role.to_string(),
                hash: hash.to_string(),
                previous_hash: previous.hash.clone(),
                previous_seen: previous.seen.clone(),
            }),
        }
    }
}

/// **The invariant that makes `warnings` THE place, checked instead of promised** (nxf 6j6v.93zd).
///
/// Each finding is recorded where it is DISCOVERED, by the site that knows which class it is — a
/// member the supervisor could not start is a skipped step, a requester the consolidation could not
/// wake is an un-woken requester, and no assembler above them can tell the two apart from a
/// [`WakeSkipped`] alone. The published `wake_skipped`/`advance_failed` fields are then the first of
/// their class, projected out of the same events.
///
/// That leaves exactly one way for the two to drift: a site that fills an `Option` and forgets the
/// list. This is the guard against it, and it runs in every debug test run rather than living in a
/// comment nobody re-reads.
///
/// **It checks the CLASS too, because the class is what this whole design turns on** (review fix
/// round 1). An earlier version matched on the identifier alone, so a site that recorded the right
/// session or run under the wrong class satisfied a guard whose stated job is "the class of a
/// failure is decided where it happens" — the one property it did not check.
///
/// The two halves are not symmetric, and the asymmetry is the point rather than a compromise:
///
/// * an ADVANCE that did not happen has exactly one class, so that is checked exactly. Note that
///   [`ConsequenceClass::NoVerdict`] also carries a `run`, which is precisely the wrong-class hole
///   an identifier-only check left open here;
/// * a WAKE that did not land has two legitimate classes, decided by the site: the consolidation
///   waking its requester records [`ConsequenceClass::RequesterNotWoken`], while the supervisor
///   handing a member its next turn records [`ConsequenceClass::StepSkipped`] for the SAME
///   `WakeSkipped` value — a member being started is a step, not a requester being woken. So the
///   class is checked against that pair, and the `reason` is checked exactly, which is what catches
///   an entry that names the right session while describing a different failure.
#[cfg(debug_assertions)]
fn debug_assert_one_place(warnings: &[FailedConsequence], wake_skipped: Option<&WakeSkipped>) {
    if let Some(w) = wake_skipped {
        assert!(
            warnings.iter().any(|f| {
                f.session.as_deref() == Some(w.session.as_str())
                    && f.reason == Some(w.reason)
                    && matches!(
                        f.class,
                        ConsequenceClass::RequesterNotWoken | ConsequenceClass::StepSkipped
                    )
            }),
            "a wake this call could not land is missing from `warnings` — or is in it under a class \
             or reason that does not describe it, which is the same defect (nxf 6j6v.93zd): {w:?} \
             not in {warnings:?}"
        );
    }
}

/// Release builds carry no such check — the assertion is a development guard, not a runtime policy.
#[cfg(not(debug_assertions))]
fn debug_assert_one_place(_warnings: &[FailedConsequence], _wake_skipped: Option<&WakeSkipped>) {}

/// Post a reply and route it (`nxc reply`).
///
/// **This does far more than post**, and every part of it is load-bearing:
///
/// 1. the **depth guard** (spec §5.3) BEFORE any work — `reply`'s routing shares the trigger path
///    with `send`, and a caller whose own chain is already past the cap must be refused here too,
///    or the one verb that never goes through `send` becomes the way around it.
///    The wakes it drives are [`ChainMove::Unwind`]s and so add no depth of their own (nxf
///    6j6v.ka09); this check is about the CALLER, and it is what keeps a session that ran out of
///    budget from spawning a real detached process per reply. Positioned before the post, not just
///    before the trigger: a half-guard that still persists an over-depth reply nothing will ever act
///    on is a strictly worse shape than rejecting the call outright, exactly as `send` does;
/// 2. the **ambient return-address stamp** on this reply's own `refs.session_id` — without it a
///    multi-hop resume chain (PM → coder → PM …) only survives while every intermediate reply
///    passes its own session by hand, and forgetting it kills the chain silently;
/// 3. the **direct return-address resume**: the target's `refs.session_id`, when it names a known
///    role session, is resumed with this reply's body. A target with no return address, or one
///    that is no longer a registered role session, triggers nothing — an ordinary case (a plain
///    human/ad-hoc post), not an error, and not a skipped wake either: nothing was owed one. An
///    address that DOES name a role session but cannot be resumed or spawned is the other thing,
///    and is reported (below);
/// 4. the **quorum-thread guard**: a reply landing in a thread that IS a quorum board (a non-empty
///    `expects`) skips (3) ENTIRELY and defers to (5). Every review role's declaration sanctions
///    replying to the ask's own ROOT MESSAGE id, and that root carries the same `refs.session_id`
///    `ask` stamped — without the skip, the FIRST reviewer's reply would resume the opener
///    immediately with that reviewer's raw text instead of waiting for the board to complete;
/// 5. the **completion routing**: when this reply is the one that COMPLETED the board, the
///    thread's opener is woken (or, for a DECLARED channel, [`route_declared_channel_completion`]
///    runs its `on_complete` policy, which can in turn move an ordered channel's flow on);
/// 6. the **working-tree release** (nxf 6j6v.fe0f): if this reply landed in a thread of the chain
///    that holds the working-tree lease, and NOTHING in that chain's scope still owes an answer,
///    the lease is given back and the head of the queue is started — see
///    [`release_working_tree_if_scope_is_done`], including why it must run after (5) and not before.
///
/// **"Skip, don't fail" throughout** — in the direct resume (3) as well as in the completion routing
/// (5), and in (5) on the declared-channel path as well as on the non-declared M2 quorum wake. The
/// reply is already persisted by the time any of them runs and its text is valid content regardless,
/// so a wake target that no longer resolves, a worker that refuses the spawn, a workflow that fails
/// to advance are each a stderr breadcrumb and an `Ok`, never a failed `reply`: an `Err` for a
/// message that WAS written lies to the caller.
///
/// **But "skip" means VISIBLY skipped, not silently.** A bare `Ok` has the opposite defect — it
/// swallows the fact that the next role was never woken, and a workflow that stalls because of it is
/// noticed by nobody. So a wake this call ATTEMPTS and cannot land is reported as
/// [`ReplyReceipt::wake_skipped`]: which session, and why. That is what leaves `resumed: false` +
/// `woke: None` meaning what it says — there was nothing to wake (no return address, an address that
/// is not a registered role session, a `summarize` phase 1 still waiting on its synthesizer) — and
/// it is the only channel an embedding app has, since the breadcrumb goes to the host process's
/// stderr where no app UI will ever see it. What DID happen is likewise reported in
/// [`ReplyReceipt`] rather than left to a guess.
///
/// **No exception is left** (nxf 6j6v.0akf, the owner's decision of 2026-08-01). The direct resume
/// in (3) was the last of the four wake sites still propagating its trigger failure with `?` — the
/// same shape one level up from (5)'s, on the path this verb takes far more often than any quorum
/// one. It now catches both of its failure points exactly as the completion wakes do: a role that
/// is no longer declared is [`WakeSkipReason::Unresolved`], a spawn the worker refuses is
/// [`WakeSkipReason::TriggerFailed`] (see [`resume_return_address`]). That changes `nxc reply`'s
/// EXIT CODE on that path and is in the changelog as one — taken deliberately, and before the
/// release rather than after, because one contract across all four sites is worth more than a
/// compatibility switch that would leave two.
pub fn reply(ctx: &Ctx, store: &mut ChatStore, req: ReplyRequest) -> Result<ReplyReceipt> {
    let hop = resolve_hop(ctx, store)?;
    let refs = with_working_copy(ctx, with_return_address(ctx, req.refs));
    let Some(receipt) = facade::reply(
        store,
        facade::ReplyRequest {
            now: ctx.now,
            origin: ctx.origin,
            actor: ctx.actor,
            target: req.target,
            body: req.body,
            kind: req.kind,
            priority: req.priority,
            disposition: req.disposition,
            refs,
            if_unanswered: req.if_unanswered,
        },
    )?
    else {
        // `--if-unanswered` found nothing owed (nxf 6j6v.ww0a): a deliberate no-op, not a failure —
        // nothing was written, so there is nothing left to route/resume/complete either.
        return Ok(ReplyReceipt {
            handed_to: None,
            posted: false,
            message_id: None,
            thread_id: None,
            resumed: false,
            woke: None,
            wake_skipped: None,
            completed: None,
            warnings: Vec::new(),
            held: None,
            // Filled by the surface, which is the layer that knows who is asking — see the field.
            await_: None,
        });
    };

    // **FROM HERE ON, THIS CALL WORKS WITH THE DECLARATIONS ITS OPERATION IS BOUND TO** (nxf
    // 6j6v.n92p). Everything above it is the POST, which reads no declaration; everything below is
    // the routing, which reads several — the channel a thread belongs to, the role a step names, the
    // prompt a resumed persona is composed from, the `working_tree` its lease is derived from.
    //
    // One substitution rather than one per read, deliberately: a stability rule that held at some of
    // those reads and not the others would be no rule at all, and a reader would have no way to say
    // which. `None` — a thread no operation opened — leaves this call reading the folder exactly as
    // it always did.
    let frozen = match receipt.thread_id.as_deref() {
        Some(tid) => operation_declarations(ctx, store, tid)?,
        None => None,
    };
    let ctx = &with_declarations(ctx, frozen.as_ref());

    // **A persona chat runs on ONE machine** (nxf 6j6v.1c6k). On any other machine this reply is
    // posted and nothing else happens here: the chat's machine picks it up after its next pull. On
    // that machine, a message TO the persona is served through the one path the pickup takes too —
    // claimed on this machine, then the persona's session resumed or, if this replica holds none, a
    // fresh one started. The persona's OWN answer falls through to the ordinary routing below,
    // which is what wakes whoever asked.
    if let Some(tid) = receipt.thread_id.as_deref() {
        if let Some(chat) = persona_chat(ctx, store, tid)? {
            if let Some(machine) = chat.machine.as_ref().filter(|m| m.acts) {
                let here = ctx.machines.and_then(|m| m.here());
                let is_here = here
                    .as_ref()
                    .is_some_and(|h| h.machine_id == machine.machine_id);
                if !is_here {
                    return Ok(ReplyReceipt {
                        handed_to: Some(crate::machine::ExecutingMachine {
                            machine_id: machine.machine_id.clone(),
                            name: None,
                            source: crate::machine::DesignationSource::Chat,
                            here: false,
                            online: None,
                            age_secs: None,
                        }),
                        posted: true,
                        message_id: Some(receipt.message_id),
                        thread_id: receipt.thread_id,
                        resumed: false,
                        woke: None,
                        wake_skipped: None,
                        completed: None,
                        warnings: Vec::new(),
                        held: None,
                        await_: None,
                    });
                }
                if ctx.caller_handle() != chat.persona {
                    let served = serve_chat(ctx, store, &chat, hop, Some(&receipt.message_id))?;
                    let mut warnings = Vec::new();
                    let (mut woke, mut held, mut wake_skipped) = (None, None, None);
                    if let Some(s) = served {
                        woke = s.session.clone().filter(|_| s.error.is_none() && !s.held);
                        held = s.session.clone().filter(|_| s.held);
                        if let Some(skip) = s.skipped {
                            warnings.push(FailedConsequence::not_woken(Some(tid), &skip));
                            wake_skipped = Some(skip);
                        }
                    }
                    if let Err(e) = release_working_tree_if_scope_is_done(ctx, store, tid) {
                        eprintln!(
                            "warning: could not decide whether the working-tree lease is releasable \
                             after the reply in thread {tid}: {e}"
                        );
                    }
                    return Ok(ReplyReceipt {
                        handed_to: None,
                        posted: true,
                        message_id: Some(receipt.message_id),
                        thread_id: receipt.thread_id,
                        resumed: woke.is_some(),
                        woke,
                        wake_skipped,
                        completed: None,
                        warnings,
                        held,
                        await_: None,
                    });
                }
            }
        }
    }

    // (4) `receipt.thread_id` already reflects the reply's resolved thread whether `target` named
    // the thread id itself or a message id within it.
    //
    // TWO conditions, ANDed — both halves of the owner ruling on the nxf 6j6v.jepk review
    // (2026-08-12, round 2). The gate used to be just `!q.expects.is_empty()`, which was sound only
    // while a DM thread's `expects_reply_from` was always empty; nxf 6j6v.jepk gave every
    // persona-DM thread a non-empty one, and since the register never clears on its own, that
    // reading would have made EVERY DM permanently a "quorum thread", skipping the direct 1:1
    // resume at (3) for good — Finding 1, round 1. Dropping the expects half entirely (keying on
    // the channel alone) over-corrected: a non-DM thread with an EMPTY `expects_reply_from` — a
    // completely ordinary shape, e.g. a plain `send --to <substrate-channel>` — would then ALSO
    // read as a quorum thread even though nothing ever declared a board on it, skipping the direct
    // resume for THAT thread too — Finding round 2. A thread is a quorum board only when BOTH hold:
    // it does not live in a DM channel ([`is_dm_channel`]) AND it actually carries a non-empty
    // `expects_reply_from`. `ask` on a raw (non-declared) group channel is unaffected either way —
    // an empty `--expect` is rejected there before anything persists (`cli.rs`'s `ask` validation).
    //
    // The channel is resolved via `thread_channel` (the `threads` table, M2 first-class threads)
    // with a fallback to `thread_channel_via_message` (M1: a thread only ever implied by a
    // `send --thread` stamp, never formally opened) — the same two-step resolution
    // [`facade::thread_board`](crate::facade::thread_board) already uses, so a thread whose
    // `expects_reply_from` was set before
    // it was ever `open_thread`-ed (a real, tested shape) still resolves to its real channel instead
    // of silently reading as a DM.
    let is_quorum_thread = match receipt.thread_id.as_deref() {
        Some(tid) => {
            let lives_in_dm = store
                .thread_channel(tid)
                .or_else(|| store.thread_channel_via_message(tid))
                .is_some_and(|c| is_dm_channel(&c));
            !lives_in_dm
                && store
                    .thread_quorum(tid, ctx.now)?
                    .is_some_and(|q| !q.expects.is_empty())
        }
        None => false,
    };

    // (3) The direct resume. Deliberately AFTER the post (unlike `send`'s preflight): "no known
    // role return address" is the ordinary case, not a caller mistake to reject before persisting.
    // And since the reply IS persisted by the time this runs, nothing in here may come back as an
    // `Err` — see [`resume_return_address`], which skips visibly instead (nxf 6j6v.0akf).
    //
    // `resumed` is exactly "the direct resume landed", so it reads off the attempt's `woke`: a
    // resume that was attempted and failed reports `resumed: false` together with the finding. That
    // lets the completion routing below run (it is guarded on `!resumed`), which cannot overwrite
    // the finding: (3) only runs for a thread that is NOT a quorum board, and (5) only ever assigns
    // for a completing reply into one that is — the two are mutually exclusive by construction.
    let mut resumed = false;
    let mut woke = None;
    let mut held = None;
    let mut wake_skipped = None;
    let mut completed = None;
    // Everything this call discovers that `woke`/`wake_skipped`/`completed`/`advance_failed` above
    // have no room for (nxf 6j6v.93zd) —
    // the second and further members a supervisor could not start, a consolidation that failed to
    // start, a run handed no verdict. Folded into the receipt's ONE list at the bottom.
    let mut also_failed: Vec<FailedConsequence> = Vec::new();
    if !is_quorum_thread {
        if let Some(addr) = store.message_return_address(req.target)? {
            // The thread this reply landed in is where the resumed session now stands (nxf
            // 6j6v.a71h §3.1) — what it opens next hangs under THIS thread, not under whichever one
            // it was triggered into originally.
            // A HAND-BACK announces itself before the answer (nxf 6j6v.gk9j) — the same notice
            // `crate::surface`'s 1:1 resume and a channel's pass-through put first, so a requester
            // meets one text whichever of the three paths woke it. This is the direct resume into a
            // thread that declares no board, which is the one path neither of those two covers.
            // **Through [`wake_message`], like every other hand-over**, which is what puts the
            // coordinator's own addressee block on it (nxf 6j6v.dq59). This site composed the
            // hand-back notice from its own literal and said nothing at all about how to answer —
            // so the one moment the owner's rule is written for, the answer of a consulted role
            // landing back at its caller, was the one wake that named no addressee. The notice
            // itself is unchanged: `wake_message` puts `ESCALATION_NOTICE` first for nxf 6j6v.gk9j's
            // reason, ahead of the body, because the body is what the model reads.
            // Never `?`: step (4b) of this verb forbids anything after the post from failing the
            // call, and a session-map lookup that errors must not turn a written reply into an
            // `Err`. An unresolvable role reads as an empty handle — see `crate::surface`'s twin.
            let resumed_handle = store
                .session_role(&addr)
                .ok()
                .flatten()
                .map(|role| ctx.qualify(&role))
                .unwrap_or_default();
            let landed_in = receipt.thread_id.as_deref().unwrap_or(req.target);
            let woken_with = wake_message(
                req.body,
                req.kind == MessageKind::Escalation,
                &reply_guidance(store, ctx.now, &resumed_handle, Some(landed_in)),
            );
            let body = woken_with.as_str();
            // What is HELD if the caller turns out to be mid-turn (nxf 6j6v.gn8b): the RAW facts,
            // not the composed text above — a delivery that batches four answers is composed once,
            // when it goes out, and storing four separate wake texts would leave nothing to
            // collect.
            let hold = crate::collecting::Held {
                thread_id: receipt
                    .thread_id
                    .clone()
                    .unwrap_or_else(|| req.target.to_string()),
                message_id: receipt.message_id.clone(),
                sender: ctx.caller_handle(),
                body: req.body.to_string(),
                escalated: req.kind == MessageKind::Escalation,
            };
            let attempt = resume_return_address(
                ctx,
                store,
                Resume {
                    addr: &addr,
                    body,
                    model: req.model,
                    hop,
                    thread: receipt.thread_id.as_deref(),
                    on_busy: OnBusy::Hold(&hold),
                },
            );
            resumed = attempt.woke.is_some();
            held = attempt.held;
            woke = attempt.woke;
            // Recorded HERE, where the class is known: this wake was aimed at the party whose own
            // message is being answered, so a skip is an un-woken requester (nxf 6j6v.93zd, class 2)
            // — not something an assembler above could tell from a `WakeSkipped` alone.
            if let Some(w) = &attempt.skipped {
                also_failed.push(FailedConsequence::not_woken(
                    receipt.thread_id.as_deref(),
                    w,
                ));
            }
            // …and what the resume NOTICED, which is a different statement from whether it landed
            // (nxf 6j6v.pkw9). This site builds its own finding above rather than going through
            // [`wake_findings`], because only here is the class known — so it has to carry the
            // attempt's own findings by hand too, or the one wake that resumes a chain hop after
            // hop would be the one that never reports a declaration that moved under it.
            also_failed.extend(attempt.findings);
            wake_skipped = attempt.skipped;
        }
    }

    // (4b) THE CHANNEL SUPERVISOR (nxf 6j6v.pf6j), synchronously, right here in the write path —
    // see `supervisor_after_reply` for what it decides and why it is not an asynchronous event. It
    // owns every reply that belongs to one of a declared channel's two levels; `None` means this
    // reply is none of its business and (5) below applies unchanged.
    //
    // **Nothing in here may fail the reply**, exactly as in (3) and (6): the message is persisted by
    // the time this runs, so an `Err` would report a failure for something that was in fact written.
    // The supervisor makes several fallible writes (two re-declarations and a post per member), and
    // a receipt that says what did NOT happen is the honest answer for all of them: since nxf
    // 6j6v.93zd such a failure is a [`FailedConsequence`] in `warnings`, not a breadcrumb plus a
    // receipt that claims nothing happened.
    //
    // A failure counts as SUPERVISED, deliberately: the fail-safe direction is to do nothing further
    // rather than to let (5) below hand the requester one member's raw answer as if the channel had
    // finished. Every store read in here is one (5) would make too, so a fault that reaches this also
    // reaches that.
    let mut supervised = false;
    if !resumed {
        if let Some(tid) = receipt.thread_id.as_deref() {
            let sender = ctx.caller_handle();
            match supervisor_after_reply(ctx, store, tid, &sender, req.kind, req.body, hop) {
                Ok(Some(run)) => {
                    supervised = true;
                    woke = run.woke;
                    wake_skipped = run.wake_skipped;
                    held = run.held;
                    completed = run.completed;
                    also_failed.extend(run.warnings);
                }
                Ok(None) => {}
                Err(e) => {
                    supervised = true;
                    let note = format!(
                        "the channel supervisor could not act on the reply in thread {tid}: {e}; \
                         the reply IS posted, but whatever it should have driven — a member's next \
                         turn, or this channel's consolidation — did not happen"
                    );
                    eprintln!("warning: {note}");
                    // …and into the receipt, which is the whole of nxf 6j6v.93zd: the supervisor
                    // runs synchronously precisely so that the session still executing this call is
                    // there to be told. `Unresolved` is the honest reason — nothing was started and
                    // no spawn was even reached, because the decision of WHAT to start is what
                    // failed.
                    also_failed.push(FailedConsequence::step_skipped(
                        Some(tid),
                        None,
                        WakeSkipReason::Unresolved,
                        note,
                    ));
                }
            }
        }
    }

    // (5) The quorum PUSH-wake. Only when this reply landed in a thread AND did not already trigger
    // a resume above — never a double wake.
    if !resumed && !supervised {
        if let Some(tid) = receipt.thread_id.as_deref() {
            if let Some(q) = store.thread_quorum(tid, ctx.now)? {
                if q.complete {
                    let msgs = store.acting_messages_in_thread(tid)?;
                    // `q.complete` is a stateless "is complete NOW" snapshot — it cannot tell a
                    // completing reply from an unrelated later follow-up into an already-complete
                    // thread. Three parts, each one a fix round:
                    //
                    // - the sender must be EXPECTED. `reply` has no membership gate, so any handle
                    //   in the system trivially satisfies "first post" the moment it replies here
                    //   for the first time, even into an already-complete board.
                    // - normally the sender's post must be their FIRST SINCE THE OBLIGATION WAS
                    //   DECLARED: otherwise that handle was already counted in `replied` before this
                    //   post and cannot be the one that flipped `complete` false→true. **Since the
                    //   turn watermark (nxf 6j6v.cg8g) that is "since the declaration", not "in the
                    //   thread"** — the older reading was a second, pre-cg8g expression of a
                    //   discharge, and from turn two on it said the wrong thing: a handle that
                    //   answered turn one is never anyone's first message again, so a re-declared
                    //   board's second completion routed nowhere at all. The question is asked of
                    //   `ChatStore::replies_since_the_declaration`, which splices the SAME comparison
                    //   `replied`/`outstanding` are computed from rather than counting rows here.
                    // - EXCEPT on a synth-retargeted thread. `expects == [synth_qualified]` is an
                    //   unambiguous, count-independent marker that this is a synthesizer-owned
                    //   phase-2 board rather than a real multi-member quorum (the reserved handle
                    //   guarantees no declared role can ever claim that identity). A synthesizer
                    //   reply landing there is always eligible to complete, first message or not.
                    //   The case it was built for (6j6v.mj8x, found live): a synthesizer whose first
                    //   attempt was unusable and which then self-corrected with a second, better
                    //   reply. Without this exception that second reply is not the sender's first
                    //   message in the thread, so nothing recognizes it, and the round stands still
                    //   forever with the right answer already sitting in the thread's history.
                    //   `!q.complete` was considered and rejected as the guard: once retargeted to
                    //   a single expected handle, `complete` flips true on that handle's FIRST
                    //   reply and stays true forever, so it cannot distinguish "still waiting" from
                    //   "already answered once" — it would exclude exactly the self-correcting
                    //   second reply this exception exists for.
                    let synth_qualified =
                        format!("{}/{}", ctx.origin, crate::channel::SYNTHESIS_HANDLE);
                    let is_synth_retarget = q.expects == [synth_qualified];
                    let is_completing_reply =
                        match msgs.iter().find(|m| m.message_id == receipt.message_id) {
                            Some(m) if q.expects.contains(&m.sender) => {
                                is_synth_retarget
                                    || store.replies_since_the_declaration(tid, &m.sender)? == 1
                            }
                            _ => false,
                        };
                    if is_completing_reply {
                        // The thread's root message (the `ask` request itself) — id-ordered, so
                        // `.first()` is it. Its `refs.session_id` is the opener's session, captured
                        // at commission time.
                        //
                        // **A channel opened as a STEP of another channel's flow has none, and must
                        // still route** (nxf 6j6v.hq71): the supervisor that opened it has no
                        // session to stamp, so a fold's phase-2 reply landing here would otherwise
                        // be dropped — the inner channel would never deliver and the outer flow
                        // would wait for a step that had in fact finished. An empty address is
                        // already the understood shape for "the requester left none" everywhere
                        // else this routing runs (`supervisor_consolidate` passes exactly that, and
                        // `wake_role_requester` reports it as "nobody was owed a wake" rather than
                        // as a failure). This substitutes it for the ONE case that can be
                        // recognised from the record — a thread the supervisor itself opened — and
                        // for no other, so a thread that simply has no return address keeps
                        // behaving as it always did.
                        let addr = match msgs.first() {
                            Some(root) => store.message_return_address(&root.message_id)?,
                            None => None,
                        };
                        let addr = match addr {
                            Some(addr) => Some(addr),
                            None if supervising_parent(store, tid)?.is_some() => {
                                Some(String::new())
                            }
                            None => None,
                        };
                        if let Some(addr) = addr {
                            // Never resume the session that just posted THIS completing reply: a
                            // role replying into its own opened thread must not re-trigger itself.
                            if ctx.session != Some(addr.as_str()) {
                                // What is HELD if the opener turns out to be mid-turn (nxf
                                // 6j6v.gn8b) — the raw facts of the answer, so a delivery that
                                // batches three of them can be composed once, when it goes out.
                                let hold = crate::collecting::Held {
                                    thread_id: tid.to_string(),
                                    message_id: receipt.message_id.clone(),
                                    sender: ctx.caller_handle(),
                                    body: req.body.to_string(),
                                    escalated: req.kind == MessageKind::Escalation,
                                };
                                let routed = route_completion(ctx, store, &q, &addr, hop, &hold)?;
                                woke = routed.woke;
                                wake_skipped = routed.skipped;
                                held = routed.held;
                                completed = routed.outcome;
                                also_failed.extend(routed.warnings);
                            }
                        }
                    }
                }
            }
        }
    }

    // (6) The working-tree release (nxf 6j6v.fe0f) — LAST, and after (5) on purpose. A reply that
    // drives a follow-up step must not release: a step fired by (5) has by then registered its own
    // expectation in the same scope, so the check below sees the chain as still owing and leaves the
    // lease exactly where it is. Running it BEFORE (5) would free the working copy in the gap
    // between one step of a chain and the next, which is the collision this whole epic exists to
    // prevent.
    //
    // **A follow-up that registers NOTHING has no net here, and this comment used to claim it did**
    // (corrected in nxf 6j6v.1xw1's third review round). It said such a step — a workflow ROLE step —
    // was "caught by the other half of the same rule, the run's own status". That half is GONE:
    // 6j6v.1xw1 acceptance point 6 removed the `Run` arm outright, and
    // `ChatStore::work_scope_has_outstanding`'s own doc records it as removed rather than replaced.
    // So the ordering above protects every follow-up that DECLARES an expectation — and since
    // 6j6v.dvyq §3 that is ALL of them: the one shape that registered nothing was the run engine's
    // role-step firing, which had no thread to declare on, and it went with the runs. What used to
    // be a named residual pinned by a characterisation test is now closed by construction, which is
    // what 6j6v.rp8k's own closing condition asked for.
    //
    // Nothing in here may fail the reply: it is persisted and durable by now.
    if let Some(tid) = receipt.thread_id.as_deref() {
        if let Err(e) = release_working_tree_if_scope_is_done(ctx, store, tid) {
            eprintln!(
                "warning: could not decide whether the working-tree lease is releasable after the \
                 reply in thread {tid}: {e}; the reply IS posted, but a chain waiting for the \
                 working copy may sit until the lease's own two-hour bound elapses"
            );
        }
    }

    debug_assert_one_place(&also_failed, wake_skipped.as_ref());
    let warnings = also_failed;
    Ok(ReplyReceipt {
        handed_to: None,
        posted: true,
        message_id: Some(receipt.message_id),
        thread_id: receipt.thread_id,
        resumed,
        woke,
        wake_skipped,
        completed,
        warnings,
        held,
        // Filled by the surface, which is the layer that knows who is asking — see the field.
        await_: None,
    })
}

/// What one completing reply's wake produced — the five findings [`ReplyReceipt`] reports, since the
/// declared and non-declared paths each fill only some of them.
struct CompletionWake {
    woke: Option<String>,
    skipped: Option<WakeSkipped>,
    /// **The delivery was HELD for a requester that is working** (nxf 6j6v.gn8b) — see
    /// [`WakeAttempt::held`], the same third outcome on the other wake path.
    held: Option<String>,
    /// What the routing could not carry out beyond those two (nxf 6j6v.93zd) — see
    /// [`CompletionRouted::warnings`].
    warnings: Vec<FailedConsequence>,
    outcome: Option<CompletionOutcome>,
}

/// The completing reply's wake, for one already-verified completing reply into thread `q` whose root
/// carries return address `addr`.
///
/// A resolution OR trigger failure here SKIPS the wake rather than failing the already-persisted
/// `reply` — see [`resolve_quorum_wake_target`]'s contract — but never silently, and since nxf
/// 6j6v.bxdd never invisibly either: a stderr breadcrumb for the terminal, a [`WakeSkipped`] for the
/// receipt. A skip with no breadcrumb at all makes "the requester never woke after quorum completed"
/// unfindable in production; a skip that is *only* a breadcrumb is unfindable to an embedding app,
/// which never sees this process's stderr.
fn route_completion(
    ctx: &Ctx,
    store: &mut ChatStore,
    q: &ThreadQuorum,
    addr: &str,
    hop: CheckedHop,
    hold: &crate::collecting::Held,
) -> Result<CompletionWake> {
    let wake_target = resolve_quorum_wake_target(store, ctx, addr);
    // This guard used to have a second arm: the run engine's `workflow-run:` sentinel address, which
    // never resolved to a live role by design and had to be let through anyway so the run could
    // consume the completion. 6j6v.dvyq §3 removed it with the runs, and what is left is the one
    // case below.
    //
    // **A FLOW STEP's channel thread carries an empty address, and must still route** (nxf
    // 6j6v.hq71): the supervisor that opened it has no session to stamp. Nobody is owed a wake there,
    // so calling it a SKIPPED one would report a failure where nothing failed, and returning here
    // would drop the completion the outer flow is waiting on. `wake_role_requester` already answers
    // an empty address with "neither a wake nor a skip", which is what the routing below reaches.
    //
    // **Conditioned on the thread being a supervisor-opened step, and NOT on the address being
    // empty** (review round 1, and it is not the same condition). An empty address is reachable on a
    // path that predates this item: `--ref session_id=` parses to `Some("")` unfiltered
    // (`cli.rs`'s `parse_refs`), and `ask` takes `--ref`, so a caller can already open a RAW quorum
    // board whose root carries one — and a raw board is precisely what reaches this function, since a
    // declared channel's completion is owned by the supervisor and never gets here. Relaxing on
    // emptiness alone would silently turn that caller's completion from "skipped wake, nothing
    // routed" into "routed", a change to a pre-existing path this item has no business making. Asking
    // the tree instead leaves it exactly where it was, and it is the SAME question `reply`'s own
    // substitution asks.
    let is_flow_step = supervising_parent(store, &q.thread_id)?.is_some();
    if wake_target.is_none() && !is_flow_step {
        eprintln!(
            "warning: quorum wake skipped for thread {} — return-address session {addr} did not \
             resolve to a live role (stale/deleted role file, malformed role YAML, or session-map \
             lookup failure)",
            q.thread_id
        );
        let skipped = WakeSkipped {
            session: addr.to_string(),
            reason: WakeSkipReason::Unresolved,
            detail: None,
        };
        return Ok(CompletionWake {
            woke: None,
            held: None,
            warnings: vec![FailedConsequence::not_woken(Some(&q.thread_id), &skipped)],
            skipped: Some(skipped),
            outcome: None,
        });
    }

    // A declared channel owns the whole decision (pass_through vs summarize, phase 1 vs phase 2).
    // `None` — no declared channel backs this thread, which since 6j6v.dvyq §3 block (a) means one
    // that reached this workspace by SYNC rather than one anybody here could open — falls through to
    // the original M2 quorum wake, untouched.
    match route_declared_channel_completion(ctx, store, q, addr, hop)? {
        Some(routed) => Ok(CompletionWake {
            woke: routed.woke,
            skipped: routed.wake_skipped,
            // **Relayed, not `None`** (review of this branch, Integrity & Robustness · High). A
            // declared channel collects across its MEMBERS, which is why this branch looked like it
            // needed nothing — but the caller that commissioned the CHANNEL can itself be mid-turn
            // when the composed answer fires, and then it is held exactly as a persona's answer is.
            // See `wake_role_requester`.
            held: routed.held,
            warnings: routed.warnings,
            outcome: Some(routed.outcome),
        }),
        None => {
            // Only a REAL role return address has anything to wake here, and an address that
            // resolves to nothing stays a defensive `let else`, never a force-unwrap.
            let Some((decl, resume_real)) = wake_target else {
                return Ok(CompletionWake {
                    woke: None,
                    skipped: None,
                    held: None,
                    outcome: None,
                    warnings: Vec::new(),
                });
            };
            let n = q.expects.len();
            let tid = &q.thread_id;
            // **A HAND-BACK says so before anything else** (nxf 6j6v.gk9j). This wake is the one a
            // `send --to <persona>` closes on — the commonest shape there is — and it is the path
            // the measured incident travelled: the requester was handed "the quorum is complete, go
            // and read it" over an escalation, which is not merely neutral but WRONG, because there
            // is no result to read. The notice is the same one the channel pass-through and the 1:1
            // resume put first, so a requester meets one text whichever path woke it.
            //
            // The WHOLE message changes, not just its first paragraph: the ordinary text says "the
            // quorum is complete, read the results and reply as appropriate", and over a hand-back
            // every clause of that is wrong — there is no result, and "reply as appropriate" is not
            // what is being asked for. Bolting a notice onto it would leave a message that
            // contradicts itself in its second sentence, which is a worse read than the one this
            // item is fixing.
            //
            // The ORDINARY branch is byte-identical to what it was, deliberately: this path closes
            // every `send --to <persona>` there is, and a finished round must not grow a paragraph.
            let wake = if store.last_reply_escalated(tid)? == Some(true) {
                format!(
                    "{}\n\nThread {tid} was handed back to you. Read what was said via `nxc \
                     threads show {tid}`, then decide.",
                    crate::channel::ESCALATION_NOTICE
                )
            } else {
                // A synthesized wake message — deliberately NOT the reviewer's raw finding text (the
                // trigger body carries only the task), and deliberately role-agnostic.
                format!(
                    "Review quorum for thread {tid} is complete ({n}/{n} replied). Read the results \
                     via `nxc threads show {tid}`, then act on the results and reply as appropriate."
                )
            };
            // nxf 6j6v.bxdd: this used to be `trigger_role_at(…)?`, the ONE place in (5) that
            // propagated — so a completing reply into a plain channel whose opener could not be
            // spawned returned `Err` for a message that was already in the store. It now catches
            // exactly as `wake_role_requester` does on the declared path, and reports.
            match trigger_role(
                ctx,
                store,
                RoleSpawn {
                    decl: &decl,
                    internal_session: addr.to_string(),
                    resume_real,
                    message: &wake,
                    // An answer travelling back up (nxf 6j6v.ntp9): the coordinator that
                    // commissioned this work is one level up, and this is its result arriving.
                    coordinator: Coordinator::Return,
                    model_override: None,
                    hop,
                    // `addr` is the board's OPENER: this hands it the result of the very quorum it
                    // commissioned, so the link closes here instead of opening one below the
                    // reviewer whose reply happened to complete it.
                    chain: ChainMove::Unwind,
                    // This wake CLOSES an obligation (the quorum just completed); it does not open a
                    // new one, so there is nothing to tell the opener it owes.
                    reply_thread: None,
                    // Unwind, so the lease gate is never reached — but this DOES put the opener
                    // back into the board thread it commissioned (nxf 6j6v.a71h §3.1), which is
                    // where it is standing when it decides what happens next.
                    thread: Some(tid),
                    // A wake carries no urgency of its own, and it can never be queued anyway: only
                    // a `ChainMove::Deeper` trigger competes for the working-tree lease (nxf
                    // 6j6v.303b), so the `Ok(_)` below is `Spawned` by construction, not by hope.
                    priority: Priority::Normal,
                    queued_since: None,
                },
            ) {
                Ok(admission) => Ok(CompletionWake {
                    woke: Some(addr.to_string()),
                    skipped: None,
                    held: None,
                    outcome: None,
                    // **NOT `Vec::new()`, which it was until PR #425's review** (nxf 6j6v.pkw9).
                    // This field is already threaded all the way onto `ReplyReceipt::warnings`, so
                    // the plumbing a finding needs to reach a caller existed and this arm simply
                    // did not use it — the worst of the five shapes the review found, because it
                    // looked like a receipt that had nothing to say.
                    //
                    // And this is the wake that closes every `send --to <persona>` there is: the
                    // opener is resumed here, under whatever its declaration says NOW.
                    warnings: admission_findings(&admission),
                }),
                // **THE OPENER IS WORKING, so the answer is HELD** (nxf 6j6v.gn8b) — the same
                // branch `resume_return_address` grew, on the wake that closes every
                // `send --to <persona>` there is, which is where it matters most: a caller that
                // commissioned three personas in one turn is by construction mid-turn when the
                // first of them answers eight seconds later.
                Err(e) if e.is_already_running() => match store.hold_wake(addr, hold, ctx.now) {
                    Ok(_) => Ok(CompletionWake {
                        woke: None,
                        held: Some(addr.to_string()),
                        skipped: None,
                        outcome: None,
                        warnings: Vec::new(),
                    }),
                    // A queue that could not be written is the one case where the answer really
                    // would be lost, so it is reported exactly as loudly as any other failed
                    // consequence.
                    Err(hold_failed) => {
                        eprintln!(
                            "warning: session {addr} is working and the answer to thread {tid} \
                             could not be held for it either: {hold_failed}"
                        );
                        let skipped = WakeSkipped {
                            session: addr.to_string(),
                            reason: wake_skip_reason(&e),
                            detail: Some(format!("{e}; and holding it failed: {hold_failed}")),
                        };
                        Ok(CompletionWake {
                            woke: None,
                            held: None,
                            warnings: vec![FailedConsequence::not_woken(Some(tid), &skipped)],
                            skipped: Some(skipped),
                            outcome: None,
                        })
                    }
                },
                Err(e) => {
                    eprintln!(
                        "warning: quorum wake failed for thread {tid} — session {addr} resolved \
                         but could not be triggered: {e}"
                    );
                    let skipped = WakeSkipped {
                        session: addr.to_string(),
                        reason: wake_skip_reason(&e),
                        detail: Some(e.to_string()),
                    };
                    Ok(CompletionWake {
                        woke: None,
                        held: None,
                        warnings: vec![FailedConsequence::not_woken(Some(tid), &skipped)],
                        skipped: Some(skipped),
                        outcome: None,
                    })
                }
            }
        }
    }
}

/// Resolve the quorum-completion PUSH-wake's target: the role declaration to compose + trigger, and
/// the real SDK session id (if any) to resume.
///
/// Returns `None` on ANY resolution failure — an unknown/since-deleted session-map row, an I/O
/// error reading it, or a role that is no longer declared — rather than propagating an error, so a
/// bad wake target only skips the wake attempt instead of failing the whole (already-persisted)
/// `reply` call that discovered it. That is the documented contract, and it is why the `Result` the
/// catalogue lookup returns is deliberately collapsed with `.ok()` here.
fn resolve_quorum_wake_target(
    store: &ChatStore,
    ctx: &Ctx,
    addr: &str,
) -> Option<(RoleDecl, Option<String>)> {
    let role_handle = store.session_role(addr).ok()??;
    let resume_real = store.resolve_real(addr).ok()?;
    let decl = ctx.defs.role(&role_handle).ok()?.clone();
    Some((decl, resume_real))
}

/// One wake attempt's result: the session actually woken, or the finding that says why nothing was.
/// At most one of the two is `Some` — which is what lets a caller read a bare `woke: None` as "there
/// was nothing to wake" instead of "something failed and nobody said so".
///
/// BOTH `None` is the one path that can be owed no wake at all: [`resume_return_address`], where an
/// address naming no role session is an ordinary plain post rather than a failure.
/// [`wake_role_requester`] is always owed one and always fills exactly one of the two.
pub(crate) struct WakeAttempt {
    pub(crate) woke: Option<String>,
    pub(crate) skipped: Option<WakeSkipped>,
    /// **The delivery was HELD, not lost** (nxf 6j6v.gn8b) — the session it is waiting for.
    ///
    /// The third outcome, and it is neither of the two above: nobody was woken, and nothing failed.
    /// The target session was mid-turn, so the answer went into the coordinator's durable queue
    /// ([`crate::collecting`]) and that session is resumed with it — together with everything else
    /// that arrives meanwhile — as soon as it settles.
    ///
    /// It is deliberately NOT a [`WakeSkipped`] with a new reason. `wake_skipped` is the visible
    /// half of "skip, don't fail" and every one of its reasons is a consequence that was owed and
    /// did not happen; a held delivery is one that WILL happen, and reporting it as a failure is
    /// how a caller would learn to ignore the field that matters.
    pub(crate) held: Option<String>,
    /// **What the wake NOTICED, as opposed to what it failed to do** (nxf 6j6v.pkw9; review of
    /// PR #425, Code Quality #1 / Integrity & Robustness #1).
    ///
    /// The two fields above are a pair — at most one of them is `Some`, and between them they say
    /// whether anybody was woken. This is neither: a wake that landed perfectly can still have
    /// something to report about the session it started, and until this field existed there was
    /// nowhere on this type to put it, so [`trigger_role`]'s
    /// [`declaration_changed`](TriggerAdmission::Spawned::declaration_changed) was dropped on the
    /// floor at all three producers.
    ///
    /// That mattered more here than anywhere else the finding travels: these are the wakes that
    /// hand a member its next TURN and carry an answer back up a chain — the shape closest to the
    /// measured incident, where a persona ran turn after turn without the rule it was supposed to
    /// have. [`wake_findings`] is what puts these on a receipt, together with the skip above.
    pub(crate) findings: Vec<FailedConsequence>,
}

/// The findings [`trigger_role`] produced for a wake that DID start something — an empty vector for
/// every admission that noticed nothing, which is the ordinary answer.
///
/// One helper rather than the same `match` at four sites (nxf 6j6v.pkw9): a wake site does not care
/// which finding it is carrying, only that it does not swallow one, and four copies of that
/// destructuring is exactly how the fifth site added later would come to forget it.
fn admission_findings(admission: &TriggerAdmission) -> Vec<FailedConsequence> {
    match admission {
        TriggerAdmission::Spawned {
            declaration_changed,
        } => declaration_changed.iter().cloned().collect(),
        // **Reachable since nxf 6j6v.de9s, and this comment used to say it was not.** A wake is
        // still a `ChainMove::Unwind` and still never takes the lease on that account — what
        // changed is that an operation whose work was PARKED no longer holds the copy, so
        // `trigger_role`'s gate makes its resume contend for it. What a queued trigger can have to
        // report is on `findings`: the clock that would have drained the queue was not armed, and —
        // since fix round 1 of nxf 6j6v.8bv9 — what the park of the expired holder this trigger
        // queued behind came to. `behind`/`position` are not findings — being in line is the queue
        // working, and the caller learns it from [`WakeSkipReason::Queued`].
        TriggerAdmission::Queued { findings, .. } => findings.clone(),
    }
}

/// (3)'s direct 1:1 return-address resume: hand this reply's own body to the session `addr` names,
/// if it names a live role session at all.
///
/// **"Skip, don't fail" here too, since nxf 6j6v.0akf** — the owner's decision of 2026-08-01, and
/// the fourth and last site of the shape [`route_completion`] and `tick` were aligned with
/// before it. This runs AFTER the reply is persisted, so neither a target that no longer resolves
/// nor a worker that refuses the spawn may turn it into an `Err`: that would be an error for a
/// message that was in fact written. Both are a stderr breadcrumb, an `Ok`, and the matching
/// [`WakeSkipped`] in [`ReplyReceipt::wake_skipped`] — which is what makes the difference between a
/// silent failure and a visibly skipped one, since `resumed: false` + `woke: None` is otherwise
/// indistinguishable from the ordinary case below.
///
/// **That ordinary case is why this has a THIRD state** and does not simply call
/// [`resolve_quorum_wake_target`]. A return address that names no role session — a plain human or
/// ad-hoc post — is not a wake that failed, it is a wake nobody was ever owed, and it returns both
/// fields `None`. The completion wake has no such case (a board's root address is stamped by `ask`
/// and always names a role), so it collapses that lookup into "did not resolve" as well. Here only
/// `session_role`'s `Ok(None)` is split off; everything else that cannot be resolved — a failed
/// session-map read, a role no longer declared — collapses to [`WakeSkipReason::Unresolved`] with no
/// `detail`, exactly as [`resolve_quorum_wake_target`] does and as [`WakeSkipped::detail`] documents.
/// **What a wake does when the target session turns out to be working** (nxf 6j6v.gn8b; review of
/// this branch, Code Quality) — the one bit [`resume_return_address`] cannot decide for itself.
///
/// It was an `Option<&Held>` whose `None` meant "do not re-hold", documented at both call sites. A
/// two-armed enum makes the illegal state unrepresentable instead of merely commented: there is no
/// way to spell "hold it, but I have nothing to hold", and a reader of a call site is told WHY the
/// drain is different rather than having to find the note.
pub(crate) enum OnBusy<'a> {
    /// Put this answer in the caller's queue and let the settle deliver it.
    Hold(&'a crate::collecting::Held),
    /// **This call IS the queue's drain.** A refusal here leaves the held rows exactly where they
    /// are — writing them back would be the same answers under a second key.
    ReportOnly,
}

/// **Everything one direct resume needs, as ONE value** — the parameter list grew past clippy's
/// bound when [`OnBusy`] joined it (nxf 6j6v.gn8b), and a struct is this crate's own answer to that
/// for [`RoleSpawn`]'s reason rather than for the lint's: `addr` and `thread` are two ids whose
/// transposition would survive compilation, and naming them at the call site is what stops it.
pub(crate) struct Resume<'a> {
    /// The return-address session to start again.
    pub(crate) addr: &'a str,
    /// What that session is handed.
    pub(crate) body: &'a str,
    pub(crate) model: Option<Model>,
    pub(crate) hop: CheckedHop,
    /// The thread the resumed session now stands on (nxf 6j6v.a71h §3.1); `None` leaves it where it
    /// was, which is the honest answer for a delivery that spans several threads.
    pub(crate) thread: Option<&'a str>,
    /// What to do if that session turns out to be mid-turn.
    pub(crate) on_busy: OnBusy<'a>,
}

pub(crate) fn resume_return_address(
    ctx: &Ctx,
    store: &mut ChatStore,
    req: Resume<'_>,
) -> WakeAttempt {
    let Resume {
        addr,
        body,
        model,
        hop,
        thread,
        on_busy,
    } = req;
    let unresolved = || {
        eprintln!(
            "warning: direct resume skipped for session {addr} — the return-address session did \
             not resolve to a live role (stale/deleted role file, malformed role YAML, or \
             session-map lookup failure)"
        );
        WakeAttempt {
            held: None,
            woke: None,
            skipped: Some(WakeSkipped {
                session: addr.to_string(),
                reason: WakeSkipReason::Unresolved,
                detail: None,
            }),
            findings: Vec::new(),
        }
    };
    let role_handle = match store.session_role(addr) {
        // The ordinary case, and the ONLY outcome here that reports nothing: no role session behind
        // this address, so no wake was ever owed.
        Ok(None) => {
            return WakeAttempt {
                held: None,
                woke: None,
                skipped: None,
                findings: Vec::new(),
            }
        }
        Ok(Some(handle)) => handle,
        // A lookup that FAILED is not a lookup that answered "no role session": it cannot say
        // whether a wake was owed, so it is reported rather than swallowed.
        Err(_) => return unresolved(),
    };
    let (Ok(resume_real), Ok(decl)) = (store.resolve_real(addr), ctx.defs.role(&role_handle))
    else {
        return unresolved();
    };
    let decl = decl.clone();
    match trigger_role(
        ctx,
        store,
        RoleSpawn {
            decl: &decl,
            internal_session: addr.to_string(),
            resume_real,
            message: body,
            // An answer travelling back up (nxf 6j6v.ntp9) — see `Coordinator::Return`.
            coordinator: Coordinator::Return,
            model_override: model,
            hop,
            // The return address is by construction the session that POSTED what is being replied
            // to — this reply answers it, so the chain unwinds one link rather than descending one.
            chain: ChainMove::Unwind,
            // Same reasoning as the quorum wake above: this resume closes an obligation, it does not
            // open one.
            reply_thread: None,
            // The thread this resume puts the session INTO — the one the reply that woke it landed
            // in (nxf 6j6v.a71h §3.1). It used to be `None`, which was harmless while the field's
            // only consumer was the working-tree lease (an `Unwind` never reaches that gate — see
            // the note on `priority` below) and is exactly wrong for the parent edge: a71h's chain
            // has the `#coding` supervisor open T4 out of T3 because it was resumed BY the coder's
            // answer in T3, and a `None` here would leave it standing in T2 and hang T4 under the
            // wrong branch. Still inert for the lease, for the unchanged reason.
            thread,
            // Unwind, so the lease gate never reaches it — see the quorum wake's own note.
            priority: Priority::Normal,
            queued_since: None,
        },
    ) {
        // **A resume that was QUEUED is not a wake** (nxf 6j6v.de9s). It happens for exactly one
        // shape — an answer to an escalation whose operation was parked, arriving while somebody
        // else has the working copy — and reporting `woke: Some(..)` for it would be the receipt
        // claiming a session is working while its trigger sits in a queue, which is precisely what
        // [`TriggerAdmission`] was given a return value to prevent.
        Ok(TriggerAdmission::Queued {
            behind,
            position,
            findings,
        }) => WakeAttempt {
            held: None,
            woke: None,
            skipped: Some(WakeSkipped {
                session: addr.to_string(),
                reason: WakeSkipReason::Queued,
                detail: Some(format!(
                    "this operation's work was parked while it waited, so it no longer holds the \
                     working copy: the answer is durably in the thread and its session is queued \
                     at position {position}{}, and the next release starts it",
                    behind
                        .as_deref()
                        .map(|b| format!(" behind {b}"))
                        .unwrap_or_default()
                )),
            }),
            findings,
        },
        Ok(admission) => WakeAttempt {
            held: None,
            woke: Some(addr.to_string()),
            skipped: None,
            // An answer travelling back up still STARTS a session, under whatever the declaration
            // says now (nxf 6j6v.pkw9) — a multi-hop PM/coder chain is exactly where a rolled-back
            // rule used to run for turn after turn with nobody told.
            findings: admission_findings(&admission),
        },
        // **THE CALLER IS WORKING, so the answer is HELD** (nxf 6j6v.gn8b) — the branch this whole
        // item turns on. The single-process guard (nxf 6j6v.7qtf) refuses a second process for a
        // session that has one, and until this the whole of what happened was a
        // `wake_skipped: {reason: "already_running"}` on the REPLIER's receipt: a line the caller
        // never sees, about an answer it would never be told about. Now the delivery goes into the
        // coordinator's durable queue and the caller is resumed with it — and with everything else
        // that arrives meanwhile — as soon as its session settles.
        //
        // [`OnBusy::ReportOnly`] is the one caller that must NOT re-hold: [`deliver_held`] itself,
        // which is draining that very queue. A drain refused because the session started again in
        // the meantime leaves its rows where they are and reports the ordinary skip.
        Err(e) if e.is_already_running() && matches!(on_busy, OnBusy::Hold(_)) => {
            let OnBusy::Hold(item) = on_busy else {
                unreachable!("the guard above established it")
            };
            match store.hold_wake(addr, item, ctx.now) {
                Ok(_) => WakeAttempt {
                    woke: None,
                    skipped: None,
                    held: Some(addr.to_string()),
                    findings: Vec::new(),
                },
                // A queue that could not be written is the one case where the answer really would
                // be lost, so it is reported as loudly as any other failed consequence — never
                // collapsed into the held case it did not reach.
                Err(hold_failed) => {
                    eprintln!(
                        "warning: session {addr} is working and the answer could not be held for \
                         it either: {hold_failed} — it is durably in its thread, but nothing will \
                         hand it over"
                    );
                    WakeAttempt {
                        woke: None,
                        skipped: Some(WakeSkipped {
                            session: addr.to_string(),
                            reason: wake_skip_reason(&e),
                            detail: Some(format!("{e}; and holding it failed: {hold_failed}")),
                        }),
                        held: None,
                        findings: Vec::new(),
                    }
                }
            }
        }
        Err(e) => {
            eprintln!(
                "warning: direct resume failed for session {addr} — the return address resolved \
                 but could not be triggered: {e}"
            );
            WakeAttempt {
                held: None,
                woke: None,
                skipped: Some(WakeSkipped {
                    session: addr.to_string(),
                    reason: wake_skip_reason(&e),
                    detail: Some(e.to_string()),
                }),
                findings: Vec::new(),
            }
        }
    }
}

/// Deliver `body` to a `Role` requester's return-address session — the SAME
/// [`resolve_quorum_wake_target`] + trigger mechanism the non-declared PUSH-wake path uses, never a
/// parallel one.
///
/// A resolution OR trigger failure only logs a stderr breadcrumb and returns the matching
/// [`WakeSkipped`], never propagates: [`on_channel_complete`]'s contract is to always return `Ok`,
/// even when the delivery attempt it makes for a FAILED synthesis also fails to reach a live worker
/// (the outcome's own text still names the original failure regardless).
fn wake_role_requester(
    ctx: &Ctx,
    store: &mut ChatStore,
    addr: &str,
    body: &str,
    hop: CheckedHop,
    thread: &str,
) -> WakeAttempt {
    // The requester left NO return address at all — a human at a bare terminal, which the channel
    // supervisor reaches with an empty address (nxf 6j6v.pf6j). Nothing was ever owed a wake here, so
    // this reports neither a wake nor a skip: the PULL surfaces (`opener_wake`/`inbox`) are how that
    // requester collects its answer, and the routing around this call is what gets the thread to the
    // `complete` state those surfaces read. Mirrors `resume_return_address`'s third state exactly.
    if addr.is_empty() {
        return WakeAttempt {
            held: None,
            woke: None,
            skipped: None,
            findings: Vec::new(),
        };
    }
    let skipped = |reason, detail| WakeAttempt {
        held: None,
        woke: None,
        skipped: Some(WakeSkipped {
            session: addr.to_string(),
            reason,
            detail,
        }),
        findings: Vec::new(),
    };
    match resolve_quorum_wake_target(store, ctx, addr) {
        Some((decl, resume_real)) => {
            match trigger_role(
                ctx,
                store,
                RoleSpawn {
                    decl: &decl,
                    internal_session: addr.to_string(),
                    resume_real,
                    message: body,
                    // An answer travelling back up (nxf 6j6v.ntp9) — see `Coordinator::Return`.
                    coordinator: Coordinator::Return,
                    model_override: None,
                    hop,
                    // Same closure as the M2 quorum wake: `addr` is the requester that opened the
                    // declared channel, and this is its own result coming back.
                    chain: ChainMove::Unwind,
                    // A closing wake, same as its two Unwind siblings above.
                    reply_thread: None,
                    // …but it does put the requester back INTO the board thread it commissioned
                    // (nxf 6j6v.a71h §3.1): what that session opens next hangs under this board, not
                    // under whatever it was doing before it commissioned it. Inert for the lease,
                    // which an `Unwind` never reaches.
                    thread: Some(thread),
                    // Unwind, so the lease gate never reaches it — see the quorum wake's own note.
                    priority: Priority::Normal,
                    queued_since: None,
                },
            ) {
                Ok(admission) => WakeAttempt {
                    held: None,
                    woke: Some(addr.to_string()),
                    skipped: None,
                    // The requester is put back to work by this wake, so what its start noticed is
                    // its caller's business too (nxf 6j6v.pkw9).
                    findings: admission_findings(&admission),
                },
                // **THE REQUESTER IS WORKING, so the channel's answer is HELD** (nxf 6j6v.gn8b;
                // review of this branch, Integrity & Robustness · High).
                //
                // This is the THIRD wake path, and it was missed on the first pass because a
                // declared channel already collects — across its MEMBERS. That is a different
                // question from the one this branch answers: whether the OUTER requester, the
                // caller that commissioned the channel, is itself mid-turn when the composed answer
                // finally fires. It can be, and commonly is — a caller that commissions a channel
                // and a persona in the same turn is by construction working when the first of them
                // comes back. Without this branch that caller read
                // `wake_skipped: {reason: "already_running"}` and the channel's whole consolidated
                // answer was recoverable only by going and looking, which is the exact silent loss
                // this item exists to close.
                //
                // **One held delivery per (session, channel thread)**, which is what the synthetic
                // message key says: the three call sites of this function are the three mutually
                // exclusive OUTCOMES of one round — a synthesis, a pass-through, or the note that
                // the consolidator could not start — so a second one for the same thread would be a
                // duplicate of the same answer rather than a second answer.
                //
                // The body is held VERBATIM, framing and all. A composed channel answer already
                // carries its own `<untrusted_channel_replies>` block, and nesting it inside the
                // delivery's is correct rather than redundant: [`crate::channel::block_boundary`]
                // picks the outer delimiter after reading the content, so it cannot be the one the
                // inner text spells, and [`crate::channel::ATTRIBUTION_NOTICE`] already tells the
                // reader that a `<message…>` seen INSIDE a block is that block's own text.
                Err(e) if e.is_already_running() => {
                    let hold = crate::collecting::Held {
                        thread_id: thread.to_string(),
                        // **Keyed on the ROUND, not on the thread** (review of this branch, second
                        // pass). A synthetic `<thread>#channel` was the first cut and it was wrong
                        // in one shape: a thread can legitimately hold a SECOND round — the opener
                        // re-declares `expects` back to real members and they answer again, which
                        // `consolidation_claim`'s own doc names as a supported case — and if the
                        // opener's session is STILL busy across both, the second round's answer
                        // collides with the first's queued row and `INSERT OR IGNORE` drops it
                        // silently. That is the exact loss this queue exists to prevent, one layer
                        // further out than the wake paths it was built for.
                        //
                        // `(expects_reply_from_v, expects_reply_from_site)` is the pair the
                        // consolidation claim already trusts to tell two rounds apart, and it keeps
                        // the idempotence the first cut had: a RETRY of the same round is refused by
                        // that claim before this function is reached a second time, and the version
                        // has not moved anyway. A thread whose row is gone falls back to the thread
                        // id, which is the honest answer when there is no round to name.
                        message_id: match store.expects_version(thread) {
                            Ok(Some((v, site))) => format!("{thread}#round-{v}.{site}"),
                            // No row: the thread is gone, and the thread id is the honest key when
                            // there is no round left to name.
                            Ok(None) => format!("{thread}#channel"),
                            // A failing READ is not the same thing, and it is said out loud for the
                            // reason its sibling below is (review of this branch): falling back
                            // quietly here would make a SECOND round of this thread collide with a
                            // first that is still queued, which is the loss the round key exists to
                            // prevent.
                            Err(e) => {
                                eprintln!(
                                    "warning: could not read the round of thread {thread} ({e}) — \
                                     the channel answer is held under the thread alone, so a \
                                     second round of it that completes before this one is \
                                     delivered would be dropped as a duplicate"
                                );
                                format!("{thread}#channel")
                            }
                        },
                        // The engine's own identity for what a channel says, which is what the
                        // pass-through's `__delivered__` marker already is on the thread.
                        sender: format!("{}/{}", ctx.origin, crate::channel::SUPERVISOR_HANDLE),
                        body: body.to_string(),
                        // The same derivation `route_completion` uses to decide whether to lead
                        // with the escalation notice — a member's "I cannot" reaches the CHANNEL
                        // thread on both output forms (see `ChatStore::last_reply_escalated`), so
                        // this is the answer of record and not a guess. A read that FAILS collapses
                        // to "an ordinary answer", which is this function's contract everywhere
                        // else: nothing in here may fail a delivery that is already composed.
                        escalated: match store.last_reply_escalated(thread) {
                            Ok(marked) => marked.unwrap_or(false),
                            // Breadcrumbed rather than swallowed (review of this branch): a
                            // hand-back that loses its `set apart` placement because a read failed
                            // is a quiet downgrade of the one message that stops a chain, and an
                            // operator is entitled to find it. Still not fatal — nothing in here
                            // may fail a delivery that is already composed.
                            Err(e) => {
                                eprintln!(
                                    "warning: could not tell whether the channel answer for thread \
                                     {thread} is a hand-back ({e}) — it is held as an ordinary \
                                     answer, so it will be delivered in the batch rather than set \
                                     apart"
                                );
                                false
                            }
                        },
                    };
                    match store.hold_wake(addr, &hold, ctx.now) {
                        Ok(_) => WakeAttempt {
                            woke: None,
                            skipped: None,
                            held: Some(addr.to_string()),
                            findings: Vec::new(),
                        },
                        Err(hold_failed) => {
                            eprintln!(
                                "warning: session {addr} is working and the channel answer for \
                                 thread {thread} could not be held for it either: {hold_failed}"
                            );
                            skipped(
                                wake_skip_reason(&e),
                                Some(format!("{e}; and holding it failed: {hold_failed}")),
                            )
                        }
                    }
                }
                Err(e) => {
                    eprintln!("warning: channel completion wake failed for session {addr}: {e}");
                    skipped(wake_skip_reason(&e), Some(e.to_string()))
                }
            }
        }
        None => {
            eprintln!(
                "warning: channel completion wake skipped for session {addr} — return-address \
                 session did not resolve to a live role (stale/deleted role file, malformed role \
                 YAML, or session-map lookup failure)"
            );
            skipped(WakeSkipReason::Unresolved, None)
        }
    }
}

/// What running a completed declared channel's `on_complete` policy produced: the
/// [`CompletionOutcome`] itself, plus which requester session (if any) it actually woke on the way
/// — the caller cannot re-derive the latter, since a wake is a fire-and-forget trigger that leaves
/// no trace in the store.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CompletionRouted {
    pub outcome: CompletionOutcome,
    /// The requester session woken. `None` for `summarize` phase 1 (the synthesizer runs first),
    /// and for a wake attempt that did not land.
    pub woke: Option<String>,
    /// Set only for that last case: a wake this routing ATTEMPTED and could not land, so `woke:
    /// None` stays readable as "there was nothing to wake" (nxf 6j6v.bxdd). Carried up into
    /// [`ReplyReceipt::wake_skipped`] verbatim.
    pub wake_skipped: Option<WakeSkipped>,
    /// **The requester was working, so the channel's answer is HELD for it** (nxf 6j6v.gn8b) — the
    /// third outcome beside [`woke`](Self::woke) and [`wake_skipped`](Self::wake_skipped), carried
    /// up into [`ReplyReceipt::held`] exactly as they are. `None` on every routing that woke
    /// somebody, had nobody to wake, or genuinely failed.
    pub held: Option<String>,
    /// **Everything this routing could not carry out** (nxf 6j6v.93zd) — COMPLETE, including the two
    /// findings the fields above also carry, for [`SupervisorRun::warnings`]'s reason: the class of
    /// a failure is known where it happens and nowhere else. Carried up verbatim into the receipts'
    /// one `warnings` list.
    pub warnings: Vec<FailedConsequence>,
}

/// **Run this channel's declared CONSOLIDATOR over one settled set** (nxf 6j6v.e9qj) — which output
/// form runs is `consolidation`'s, resolved by [`ChannelDecl::consolidation`](crate::channel::ChannelDecl::consolidation)
/// from the declaration and this set's escalation, never from anything about the thread's shape.
/// This function executes a decision; it does not take one.
///
/// **Both output forms are one mechanism with a declared difference**, and the shared spine is:
/// claim the round ([`ChatStore::claim_consolidation`](crate::store::ChatStore::claim_consolidation)),
/// retarget `expects_reply_from` to that form's own marker, then act. What differs is the marker and
/// the act — `__delivered__` and a wake carrying the answers in the defined shape, or `__synth__`
/// and an ephemeral session that will reply with the fold.
///
/// **The two-phase mechanism** (`channel.rs`'s module docs work through WHY this is unavoidable —
/// `Worker::trigger` is fire-and-forget): pass-through is one synchronous call — retarget,
/// self-satisfy, wake the `Role` requester now with the collected answers
/// ([`compose_pass_through_wake`](crate::channel::compose_pass_through_wake)). A fold is
/// recognized as phase 1 or phase 2 by a cheap, deterministic marker: `thread.expects` already
/// equalling the single QUALIFIED synthesis identity means a PRIOR call already re-targeted this
/// thread and this completion is the synthesizer's OWN reply landing (phase 2) — actually deliver
/// the synthesizer's reply body to the requester, waking it. Otherwise
/// (phase 1, a real quorum just completed): [`facade::set_expects`] re-targets `expects_reply_from`
/// to that SAME qualified identity (OPENER-only — `thread.opener` is the re-declaring actor, since
/// only the opener may call it) and an ephemeral synthesizer is triggered directly, bypassing the
/// declaration catalogue entirely: it is not a declared role, it is built at spawn time from the
/// consolidator's own resolved `prompt` and `model`.
///
/// **Never `Err` except where the round is left unclaimable.** Both forms retarget under a won
/// claim, and both hand that claim back before propagating a retarget failure — a claim left
/// standing is indistinguishable from a consolidation that really ran, which wedges the round.
///
/// **The bare-vs-qualified discipline** (learned from a shipped bug of exactly this class):
/// [`SYNTHESIS_HANDLE`](crate::channel::SYNTHESIS_HANDLE) is BARE and used ONLY as the
/// synthesizer's `RoleSpec.handle`/trigger target; the identity `set_expects` is given, and the
/// identity `thread.expects` is compared against for phase-2 recognition, is ALWAYS the QUALIFIED
/// `<origin>/__synth__` — what the synthesizer's own eventual `nxc reply` actually stamps as its
/// `sender` (`facade::reply` always qualifies), so the exact-match join in `thread_quorums`
/// genuinely fires phase 2. A bare handle in `expects_reply_from` would never match a real reply's
/// qualified `sender`, silently deadlocking completion forever.
///
/// **Never silent, never `Err`** for a delivery/synthesis failure (mirroring
/// [`resolve_quorum_wake_target`]'s own "a bad wake target only skips the wake" tone): if the
/// synthesizer's own spawn fails, that is captured as an explicit failure — an error-note wake for
/// the requester (the SAME [`wake_role_requester`] mechanism `pass_through` uses), plus a stderr
/// breadcrumb. `?` is reserved for genuinely exceptional plumbing; only a worker-trigger failure is
/// caught and turned into a reportable `Ok`.
///
/// A second failure mode lived here until 6j6v.dvyq §3: a phase-2 synthesis whose text carried no
/// parseable `outcome:` token, which the engine substituted with the `"fail"` sentinel so a run
/// could route on it. There is no token and no run; a fold that produced nothing usable is now
/// delivered as the note it is, to a requester who reads it.
///
/// # Why seven positional parameters and not a request struct
///
/// The branch review of PR #337 (Code #2) asked this against [`SupervisorFanOut`], which collapsed
/// its own growing list into a struct in this very diff. **Deliberately not followed here**, for
/// three reasons that are about the two sites and not about taste:
///
/// 1. **The precedent's hazard does not exist here.** `SupervisorFanOut` packs ELEVEN values,
///    three of them consecutive `&str` (`channel_id`, `channel_thread`, `body`) — swap two and it
///    COMPILES and ships. All seven here are mutually distinct types, so no swap survives `cargo
///    check`. The precedent is about a failure mode this signature cannot have.
/// 2. **`SupervisorFanOut` is private; this is `pub`.** Packing these would mint a second public
///    type whose only content is "the arguments of the function below it", on a surface that goes
///    irreversibly public at launch and where every added type is a compatibility promise. A lint
///    suppression is cheaper than a public struct that exists to hold four references.
/// 3. **This module's own precedent for a PUBLIC many-argument entry point is the allow**: the two
///    step-firing primitives the run engine had both carried it, and both predated this branch. The
///    struct precedent covers private fan-out helpers; this one covers public entry points, and
///    this is one.
///
/// What the seventh argument actually is, so the growth is legible: `consolidation` — the output
/// form resolved from the declaration AND this set's escalation, resolved once by the caller
/// ([`route_declared_channel_completion_with`]) so it cannot be re-derived differently underneath.
/// It cannot be folded into `channel`, which is still needed whole for its name and its fail-closed
/// re-validation.
#[allow(clippy::too_many_arguments)]
pub fn on_channel_complete(
    ctx: &Ctx,
    store: &mut ChatStore,
    channel: &ChannelDecl,
    consolidation: &Consolidation,
    thread: &ThreadQuorum,
    addr: &str,
    note: Option<&str>,
    hop: CheckedHop,
) -> Result<CompletionRouted> {
    use crate::channel::{
        compose_pass_through_wake, compose_synthesis_trigger, ConsolidatorOutput, DELIVERED_HANDLE,
        SYNTHESIS_HANDLE,
    };

    let synth_qualified = format!("{}/{}", ctx.origin, SYNTHESIS_HANDLE);
    let msgs = store.acting_messages_in_thread(&thread.thread_id)?;
    let replies = collected_replies(ctx, store, thread)?;

    // Phase-2 recognition: a PRIOR call already re-targeted this SAME thread to the synthesis
    // marker — this completion is the synthesizer's own reply landing, not a real member quorum.
    if thread.expects == vec![synth_qualified.clone()] {
        let synthesis_body = msgs
            .iter()
            .rev()
            .find(|m| m.sender == synth_qualified)
            .map(|m| m.body.clone())
            .unwrap_or_default();
        let attempt =
            wake_role_requester(ctx, store, addr, &synthesis_body, hop, &thread.thread_id);
        let warnings = wake_findings(&thread.thread_id, &attempt);
        return Ok(CompletionRouted {
            held: attempt.held,
            outcome: CompletionOutcome {
                delivered: synthesis_body,
            },
            woke: attempt.woke,
            wake_skipped: attempt.skipped,
            warnings,
        });
    }

    // Phase 1: a real quorum just completed. Which output form runs was decided by the DECLARATION
    // (nxf 6j6v.e9qj) — and, where the set escalated, by the consolidator's own declared rule for
    // that (`ChannelDecl::consolidation`). Nothing about the thread's shape is asked here.
    match &consolidation.output {
        ConsolidatorOutput::PassThrough => {
            let delivered_qualified = format!("{}/{}", ctx.origin, DELIVERED_HANDLE);
            // Win the round before delivering anything — the SAME claim the fold below takes, keyed
            // on this form's own marker (nxf 6j6v.296n, widened by 6j6v.e9qj). Before this item the
            // pass-through form was gated only on "the channel thread still expects the supervisor",
            // which makes a LATE second completion a clean no-op but lets two SIMULTANEOUS ones both
            // deliver — waking the requester twice with the same answers. Both forms are one
            // mechanism with a declared difference, so both are guarded by one.
            if !store.claim_consolidation(&thread.thread_id, &delivered_qualified, ctx.now)? {
                return Ok(CompletionRouted {
                    held: None,
                    outcome: CompletionOutcome {
                        delivered: format!(
                            "channel {:?} consolidation for thread {} was already delivered by a \
                             concurrent completion — nothing to do",
                            channel.name, thread.thread_id
                        ),
                    },
                    woke: None,
                    wake_skipped: None,
                    warnings: Vec::new(),
                });
            }
            // The idempotency marker, retargeted and self-satisfied BEFORE the wake, exactly as the
            // fold retargets before it spawns. `pass_through` is single-phase and has no
            // phase-1/phase-2 marker of its own the way a fold does, so it gets an equivalent one:
            // `expects_reply_from` is retargeted to the qualified `__delivered__` identity and
            // IMMEDIATELY self-satisfied with a real posted message (no async round trip needed).
            //
            // **Self-satisfying synchronously rather than emptying `expects` to `[]`** (the
            // first-round design, corrected): emptying it made a completed `pass_through` thread's
            // `complete` flip to `false` FOREVER, erasing it from `opener_wake`/inbox/`threads show`
            // — all of which derive purely from `q.complete`/`q.stale` — which silently removed the
            // PULL-based safety net for the case where the PUSH wake itself fails (a wake never
            // propagates its own failure). A real self-satisfying message makes `outstanding` empty
            // and `complete` flip to `true` immediately, matching the shape a fold ends up in once
            // its synthesizer's reply lands.
            //
            // A failure here HANDS THE CLAIM BACK, for the reason the fold's own retarget does.
            let opener = thread.opener.clone().unwrap_or_default();
            if let Err(e) = facade::set_expects(
                store,
                ctx.now,
                &opener,
                &thread.thread_id,
                std::slice::from_ref(&delivered_qualified),
            ) {
                if let Err(release) = store.release_consolidation_claim(&thread.thread_id) {
                    eprintln!(
                        "warning: could not release the consolidation claim for thread {} after a \
                         failed re-target — the next completion of this round will be refused as \
                         already delivered: {release}",
                        thread.thread_id
                    );
                }
                return Err(e);
            }
            // Its KIND is where an escalation leaves the channel (nxf 6j6v.wt37). This message is
            // the channel thread's answer OF RECORD — the one thing the ENGINE itself writes to
            // discharge it — so marking it is what carries a member's "I cannot" one level up
            // instead of letting it die at the supervisor. Without that, a `#coding` whose coder
            // cannot proceed would read as finished at its own channel thread, which is the exact
            // thread nxf 6j6v.1xw1 releases the working copy on. Since 6j6v.e9qj this is reached by
            // a declared `summarize` channel too, because an escalating set is never folded.
            store.post_message(&MessageEnvelope {
                origin: ctx.origin.to_string(),
                channel_id: thread.channel_id.clone().unwrap_or_default(),
                sender: delivered_qualified,
                kind: if consolidation.escalated {
                    MessageKind::Escalation
                } else {
                    MessageKind::Info
                },
                priority: Priority::Background,
                disposition: Disposition::NextSession,
                thread_id: Some(thread.thread_id.clone()),
                // **The turn goes back here, so the anchor does too** (nxf 6j6v.2af2, applying
                // [`with_working_copy`]'s criterion while the review of PR #474 had this file open).
                // The body is a marker rather than the answer — the answer is the wake composed two
                // lines down — but this message is the one that discharges the channel thread, and
                // the requester's session is put in motion by the same step. A requester resumed
                // after an interruption asks where the tree stood when it was woken, and this is
                // that moment.
                refs: with_working_copy(ctx, Refs::default()),
                body: "[pass_through delivered]".to_string(),
            });
            // **This is where unverified member content enters an LLM-trusted trigger** (nxf
            // 6j6v.k1gb). `compose_pass_through_wake` renders every member's raw body into the
            // defined shape; `wake_role_requester` below hands that string to the requester's
            // session as its OPERATOR's message. Two separate guarantees ride on that, and it is
            // worth keeping them apart when reading either end:
            //
            // - WHO said it is now settled by construction. `channel::block_boundary` picks this
            //   round's delimiter from what the answers demonstrably do not contain, so no body can
            //   open or close a block and no member can put words in another's mouth. That is what
            //   k1gb closed; before it, the shape was a shape and `from=` was a claim.
            // - WHAT it says is still unverified, and always will be. The
            //   `<untrusted_channel_replies…>` framing (branch review of PR #337, Integrity #4) is
            //   what covers that half, and the boundary does not make it redundant.
            //
            // Named HERE as well as at the composer because the composer alone cannot tell you what
            // the string is FOR: this is the second of k1gb's two sites, and the one a reader
            // chasing "who trusts this?" arrives at. (Its being missing is itself an instance of
            // `handover-lists-are-themselves-unverified` — the review named two sites and only one
            // carried the pointer.)
            let delivered = compose_pass_through_wake(
                &channel.name,
                &replies,
                &thread.thread_id,
                consolidation.escalated,
                note,
            );
            let attempt = wake_role_requester(ctx, store, addr, &delivered, hop, &thread.thread_id);
            let warnings = wake_findings(&thread.thread_id, &attempt);
            Ok(CompletionRouted {
                held: attempt.held,
                outcome: CompletionOutcome { delivered },
                woke: attempt.woke,
                wake_skipped: attempt.skipped,
                warnings,
            })
        }
        ConsolidatorOutput::Fold {
            model: fold_model,
            prompt: fold_prompt,
        } => {
            let trigger_message =
                compose_synthesis_trigger(&channel.name, &replies, &thread.thread_id);

            // Win the right to spawn before doing anything (nxf 6j6v.296n). Everything below is a
            // check-then-act over `thread.expects` — read the quorum, retarget, spawn — with no
            // transaction around the sequence, so two callers completing this SAME thread at nearly
            // the same moment (a completing reply landing exactly as `nxc tick`'s scheduled
            // timer fires for it) both hold a pre-retarget snapshot and would each spawn their own
            // synthesizer for one board. The claim is a single-statement compare-and-swap in the
            // store, so the loser is decided by the database — which is what it takes, since the two
            // racers are typically two PROCESSES, not two call sites.
            //
            // The loser delivers a "nothing to do" note rather than a result: the WINNER's
            // synthesizer is the one that will produce the summary, and it routes it itself when it
            // lands.
            if !store.claim_consolidation(&thread.thread_id, &synth_qualified, ctx.now)? {
                return Ok(CompletionRouted {
                    held: None,
                    outcome: CompletionOutcome {
                        delivered: format!(
                            "channel {:?} synthesis for thread {} was already spawned by a \
                             concurrent completion — nothing to do",
                            channel.name, thread.thread_id
                        ),
                    },
                    woke: None,
                    wake_skipped: None,
                    warnings: Vec::new(),
                });
            }

            // Re-target expects BEFORE spawning (opener-only re-declare — `facade::set_expects`
            // rejects anyone but `thread.opener` itself). The thread stops being "complete": a
            // fresh single-entry `expects` that hasn't replied yet.
            //
            // A failure here HANDS THE CLAIM BACK (PR #271 review, found independently by all three
            // reviews). Claiming and doing the work are two steps, and this is the step between:
            // a claim left standing after a refused retarget is indistinguishable from a synthesizer
            // that really started, so every later completion of the round would be refused and the
            // board would only recover when a human re-declares it — a wedged thread instead of the
            // merely wasteful double spawn this guard exists to prevent. The error itself still
            // propagates unchanged; releasing is about what the NEXT caller finds, and a release
            // that itself fails only leaves a breadcrumb rather than masking the real error.
            let opener = thread.opener.clone().unwrap_or_default();
            if let Err(e) = facade::set_expects(
                store,
                ctx.now,
                &opener,
                &thread.thread_id,
                &[synth_qualified],
            ) {
                if let Err(release) = store.release_consolidation_claim(&thread.thread_id) {
                    eprintln!(
                        "warning: could not release the synthesis claim for thread {} after a \
                         failed re-target — the next completion of this round will be refused as \
                         already spawned: {release}",
                        thread.thread_id
                    );
                }
                return Err(e);
            }

            // The synthesizer is NOT a declared role — bypass the catalogue entirely and build the
            // `RoleSpec`/`TriggerRequest` directly (mirrors `trigger_role`'s own body, minus the
            // declaration lookup and the workflow-block composition — a synthesizer has no workflow
            // block to append). Wrapped so ANY failure inside is captured as ONE "synthesizer spawn
            // failed" outcome, never propagated via `?` (this function's own contract: always
            // `Ok`).
            //
            // Two fixes live in here (nxf 6j6v.04es, found live by the 6j6v.8e45 smokes: every
            // prior test of this branch ran under a dry worker, which never actually spawns a real
            // synthesizer session, so neither bug was ever exercised for real before then):
            //
            // 1. `tools: Some(vec!["Bash".to_string()])`, NOT `Some(vec![])`. The channel's own
            //    `summary_prompt` instructs the synthesizer to post its synthesis via `nxc reply
            //    <thread> "<...>"` — an explicit zero-tools grant disables ALL built-in tools,
            //    including Bash (see `worker.rs`'s doc on `RoleSpec.tools`), so the synthesizer had
            //    no way to ever run that command: a real synthesis was generated but never
            //    delivered. Granting exactly `Bash` (not `None`, which would hand it the SDK's full
            //    default toolset) keeps it narrowly scoped to what it needs.
            // 2. `store.create_pending_session` below, mirroring the fan-out's member loop exactly.
            //    Without it the synthesizer's internal session was never registered, so the
            //    sidecar's post-query `nxc session bind` callback failed with `not_found` and
            //    crashed the node process with an uncaught exception every single time.
            let spawn: Result<()> = (|| {
                // Fail-closed re-check: a declaration could have been edited to become invalid
                // AFTER this thread already opened — see `validate_channel_for_use`'s own doc.
                // Falls into the SAME "synthesis failed to start" handling below as any other spawn
                // failure, no new code path.
                if let Some(err) = crate::channel::validate_channel_for_use(channel) {
                    return Err(NxfError::validation(format!(
                        "declared channel {:?} is malformed: {}",
                        channel.name, err.what
                    )));
                }
                let internal = store.mint_session_id();
                store.create_pending_session(&internal, SYNTHESIS_HANDLE)?;
                // The synthesizer bypasses `trigger_role` (it is not a declared role), so it also
                // bypasses the one place the chain depth is written — and it is a Bash-enabled
                // session that posts its own `nxc reply`, i.e. exactly the shape the guard exists
                // for. Stamped here instead (nxf 6j6v.m48m), from one value shared with its
                // `NXC_HOP` below exactly as `trigger_role` does it. Always a commission: this is a
                // freshly minted session doing new work below the caller, never a wake travelling
                // back up, so there is no `ChainMove` to resolve.
                let depth = hop.get() + 1;
                store.record_trigger_depth(&internal, depth)?;
                // …and it bypasses the OTHER write `trigger_role` makes on that same shared path:
                // where this session is standing (nxf 6j6v.a71h §3.1). Without it a `nxc send --to X`
                // from this very Bash-enabled session resolves no parent and opens a ROOT, silently
                // detaching a branch from the operation it belongs to — the one real exception to
                // acceptance point 1's "without exception". It is standing in the board thread it
                // was minted to summarize, which is what every other trigger into that thread
                // records too.
                store.record_session_thread(&internal, Some(&thread.thread_id))?;
                trigger_and_bind(
                    ctx,
                    store,
                    TriggerRequest {
                        internal_session: internal,
                        resume_real: None,
                        message: trigger_message,
                        role: RoleSpec {
                            handle: SYNTHESIS_HANDLE.to_string(),
                            // **The DEFINED PROMPT of output form (b)** — the consolidator's, not a
                            // second read of the declaration: `ConsolidatorOutput::Fold` already
                            // resolved it, so the prompt that runs and the prompt the declaration
                            // names cannot come apart.
                            system_prompt: crate::channel::compose_synthesizer_system_prompt(
                                fold_prompt,
                            ),
                            use_claude_code_preset: false,
                            tools: Some(vec!["Bash".to_string()]),
                            // Nothing is DEMANDED of the synthesizer through the register (see
                            // `reply_thread` below), so the funnel's grant does not apply to it and
                            // its own narrow declaration above is the whole of its toolset (nxf
                            // 6j6v.kffm).
                            granted_tools: Vec::new(),
                            permissions: None,
                            // **The DEFINED MODEL of output form (b)** (nxf 6j6v.e9qj). It used to be
                            // `None` — the SDK's own default, a choice nobody declared and nobody
                            // could look up. The question the old comment here refused to answer
                            // ("WHERE would it be declared?") is answered by the item: on the
                            // CHANNEL, beside the prompt it runs, as `summary_model:` — and a channel
                            // that declares none folds at `DEFAULT_CONSOLIDATOR_STAGE` rather than at
                            // whatever the SDK picks this month.
                            model: Some(*fold_model),
                            // **There is no declaration to stamp** (nxf 6j6v.pkw9). The
                            // synthesizer's prompt comes from the CHANNEL's `summary_prompt`, not
                            // from a `.nxs-personas/<handle>.yaml`, so there is no role file whose
                            // version this could name — and the channel's own version is already
                            // frozen for the operation (`declaration_freeze`). `None` says that,
                            // where a hash of something else would misidentify it.
                            declaration_hash: None,
                        },
                        // The synthesizer bypasses `trigger_role` entirely (it is not a declared
                        // role, see the comment above), so it never went through the coordinator's
                        // `expects_reply_from` write either — there is no obligation for its own
                        // teardown to settle.
                        reply_thread: None,
                        // **The one spawn that reaches the worker without passing `trigger_role`,
                        // and it still names its coordinator** (nxf 6j6v.ntp9). Bypassing the
                        // declared-role funnel is not the same as having nobody in between: this is
                        // the CHANNEL's own consolidation, started by the same supervisor that ran
                        // the round. Every other write `trigger_role` makes is already reproduced
                        // above for exactly this reason; this is that list's fourth entry.
                        coordinator: Coordinator::Channel,
                        // The synthesizer owes no thread an answer through the register, so the
                        // reminder bound has nothing to act on — but the RETRY bound does, and a
                        // consolidation that dies at a `529` is as worth starting again as any
                        // other turn. Same terms as every commission; there is one definition.
                        terms: TurnTerms::default(),
                        env: trigger_env(ctx.origin, ctx.db_path, depth),
                    },
                )
                .map_err(NxfError::from)
            })();

            match spawn {
                Ok(()) => Ok(CompletionRouted {
                    held: None,
                    outcome: CompletionOutcome {
                        delivered: format!(
                            "synthesizer spawned for channel {:?}, thread {}",
                            channel.name, thread.thread_id
                        ),
                    },
                    woke: None,
                    wake_skipped: None,
                    warnings: Vec::new(),
                }),
                Err(e) => {
                    let note = format!(
                        "the channel {:?} synthesis failed to start: {e}",
                        channel.name
                    );
                    eprintln!("warning: {note}");
                    // **The consolidator itself is a step that did not start** (nxf 6j6v.93zd,
                    // class 1). Until this item the only machine-readable trace was the `delivered`
                    // PROSE — a requester was handed a sentence about a failure where it expected
                    // the channel's answer.
                    let did_not_start = FailedConsequence::step_skipped(
                        Some(&thread.thread_id),
                        None,
                        WakeSkipReason::TriggerFailed,
                        note.clone(),
                    );
                    let attempt =
                        wake_role_requester(ctx, store, addr, &note, hop, &thread.thread_id);
                    let mut warnings = vec![did_not_start];
                    warnings.extend(wake_findings(&thread.thread_id, &attempt));
                    Ok(CompletionRouted {
                        held: attempt.held,
                        outcome: CompletionOutcome { delivered: note },
                        woke: attempt.woke,
                        wake_skipped: attempt.skipped,
                        warnings,
                    })
                }
            }
        }
    }
}

/// "The collected replies" of a completed declared channel — what `pass_through` hands the requester
/// and what `summarize`'s synthesizer folds.
///
/// **Under the two levels (nxf 6j6v.pf6j) the answers are not in this thread.** They are one level
/// down, in the member threads the supervisor opened; a channel thread of its own carries only the
/// requester's request and the engine's bookkeeping.
///
/// **And it is scoped to the TURN, not to the thread's lifetime** (fix round 1 — the third time this
/// exact defect appeared in this work order, after `replied` in 6j6v.cg8g and the assignee guard in
/// 6j6v.a71h). Read over a whole life, turn two folded turn one's answers back in, plus the literal
/// `[pass_through delivered]` marker and any previous synthesis, and handed the lot to the requester
/// or to a model as if it were the new round. Multi-turn channels are the NORMAL case in this model,
/// so the two halves are each turn-scoped, by the shape they are each turn-scoped BY:
///
/// * the members' answers, through [`ChatStore::messages_since_the_declaration`] — which splices
///   `after_the_declaration`, the one definition of "written since the obligation was declared", so
///   this cannot drift from the `complete` that decided the set was settled in the first place;
/// * the request, as the NEWEST message in the channel thread from a party that is not the engine.
///   Deliberately not the same comparison: the channel thread's own register is re-declared AFTER the
///   requester's message is posted (`facade::reply` writes, then the supervisor runs), so "since the
///   declaration" would drop the very request this turn is about. On turn one it is the thread's only
///   message, so nothing about the first round's output moved.
///
/// **The request half rests on an ASSUMPTION, and it is worth naming rather than implying**: that a
/// turn is opened by exactly one such message. `reply` has no membership gate, so nothing enforces
/// it — a requester posting twice before the supervisor runs, or any third party posting into the
/// channel thread at all, makes "the newest" the last of several. What breaks if it is violated is
/// bounded and is not corruption: the consolidation quotes ONE request line instead of the several
/// that were said, so a `pass_through` requester sees less context than it wrote and a `summarize`
/// model folds against the last instruction rather than all of them. Nothing routes on it, nothing is
/// discharged by it, and the members' answers — the load-bearing half — are unaffected. Enforcing it
/// would mean a membership gate on `reply`, which is a surface-wide decision (who may speak in a
/// thread at all) rather than a consolidation one; it belongs with the access-control design
/// (nxf 6j6v.6aza), not here.
///
/// A thread with NO member threads below it collects its own messages exactly as before: that is a
/// plain `ask` on a declared channel id, and every thread written before this item.
fn collected_replies(
    ctx: &Ctx,
    store: &ChatStore,
    thread: &ThreadQuorum,
) -> Result<Vec<crate::channel::CollectedReply>> {
    let supervisor = supervisor_qualified(ctx.origin);
    let own = store.acting_messages_in_thread(&thread.thread_id)?;
    // The CURRENT PASS, not every slot the supervisor ever opened (nxf 6j6v.hq71): an ordered flow
    // opens a fresh slot per step per pass, so a later pass's consolidation would otherwise gather
    // every earlier pass's answers as well. For a `parallel` channel the two are the same list.
    let members = slots_to_consolidate(ctx, store, thread)?;
    if members.is_empty() {
        return own.into_iter().map(|m| collected_from(m, None)).collect();
    }
    // The request that opened THIS turn. `__synth__`/`__delivered__`/`__channel__` are the engine's
    // own bookkeeping in here (a delivered marker, a synthesis, a forwarded turn), never something a
    // requester said, and they are recognised by the one prefix that reserves all three.
    let mut replies: Vec<crate::channel::CollectedReply> = own
        .into_iter()
        .rev()
        .find(|m| !is_engine_identity(&m.sender))
        // The REQUEST is not a pass of the run — it is what the run was asked to do — so it carries
        // no placement, and a reader can tell the question from the answers to it.
        .map(|m| collected_from(m, None).map(|r| vec![r]))
        .transpose()?
        .unwrap_or_default();
    // **Which pass of its step each slot is** (nxf 6j6v.y1t9), counted as the slots go by rather
    // than asked per slot: `members` arrives in slot order — `supervised_children` is `ORDER BY
    // thread_id`, a slot id is a ULID, and `run_slots`/`current_pass` preserve that order — so the
    // n-th slot serving one step of one run IS its n-th pass. Keyed on the pair and not on the step
    // alone, because `slots_to_consolidate` deliberately over-includes when a pass cannot be
    // derived, and a step counter shared across two runs would number the second run's first pass
    // as the first run's second.
    let mut passes: std::collections::BTreeMap<(String, String), u32> =
        std::collections::BTreeMap::new();
    for member in members {
        let placement = match store.flow_mark(&member.thread_id)? {
            Some(mark) => {
                let seen = passes
                    .entry((mark.run.clone(), mark.step.clone()))
                    .or_insert(0);
                *seen += 1;
                Some(SlotPlacement {
                    step: mark.step,
                    pass: *seen,
                })
            }
            None => None,
        };
        for m in store.messages_since_the_declaration(&member.thread_id)? {
            if m.sender == supervisor {
                continue;
            }
            replies.push(collected_from(m, placement.as_ref())?);
        }
    }
    Ok(replies)
}

/// **Where in a declared run one slot stands** (nxf 6j6v.y1t9) — the step it served and which time
/// round that was, derived once per slot in [`collected_replies`] and stamped on every message the
/// slot contributed.
///
/// A slot-level fact, not a message-level one: everything one slot's session said belongs to the
/// same pass of the same step. The one message-level fact of this item — which answer carried the
/// verdict — rides on the message's own `kind` instead, where the engine already wrote it.
struct SlotPlacement {
    step: String,
    pass: u32,
}

/// **What the ENGINE knows about one collected message, read off the row it already had** (review of
/// PR #397, Integrity & Robustness · High).
///
/// The mark comes from a column [`collected_replies`] was already selecting and throwing away, so
/// this costs no extra query: `refs.substituted` is where nxf 6j6v.kffm records that the runtime
/// wrote a reply on behalf of a session that ended without one.
///
/// **A `refs` blob that does not parse is an ERROR, not a `false`** (second review round of PR #397,
/// Code Quality). The first cut swallowed it, on the argument that "an ordinary reply" is the safe
/// reading — and that argument does not survive being written down beside its neighbours:
/// [`crate::facade::MessageView::try_from`] and [`ChatStore::message`] both raise
/// `io: message <id> has unparseable refs` for this very column, so a third answer here would be the
/// one place the same blob means something different.
///
/// **And the swallowed direction is not the safe one.** A dropped mark renders a runtime-written
/// message as an ordinary opinion in front of a consolidator — which is precisely the defect this
/// whole item exists to remove, reintroduced silently at the last hop. Unreachable today (an
/// envelope is validated before it folds, so the column holds what this crate wrote), which is
/// exactly why making it loud costs nothing and why "unreachable" is the wrong reason to be quiet:
/// the paths that could reach it — a schema drift, a replica syncing a newer shape — are the ones
/// nobody is watching.
///
/// **`needs_rework` comes off `kind` and is deliberately per-MESSAGE** (nxf 6j6v.y1t9), where the
/// step and the pass beside it are per-SLOT. `ChatStore::last_reply_needs_rework` answers the same
/// question for a thread and would answer it for the wrong message here: a slot may contribute
/// several, and marking all of them because the last one carried the verdict would attribute a
/// judgement to text that did not make it. The column the engine wrote is exact and free.
fn collected_from(
    m: crate::store::MessageRow,
    placement: Option<&SlotPlacement>,
) -> Result<crate::channel::CollectedReply> {
    let substituted = match m.refs.as_deref() {
        Some(txt) => {
            serde_json::from_str::<Refs>(txt)
                .map_err(|_| {
                    NxfError::io(format!("message {} has unparseable refs", m.message_id))
                })?
                .substituted
        }
        None => false,
    };
    Ok(crate::channel::CollectedReply {
        needs_rework: m.kind == crate::model::KIND_NEEDS_REWORK,
        sender: m.sender,
        body: m.body,
        substituted,
        step: placement.map(|p| p.step.clone()),
        pass: placement.map(|p| p.pass),
        // `None` on every channel round, which is what keeps this composer's output byte-identical
        // to what it was: a channel's answers all belong to the one board its requester is being
        // told about (nxf 6j6v.gn8b).
        thread: None,
    })
}

/// Whether `sender` is one of the engine's own synthetic identities rather than a real party —
/// `<origin>/__synth__`, `<origin>/__delivered__`, `<origin>/__channel__`.
///
/// Keyed on [`crate::channel::RESERVED_HANDLE_PREFIX`], the same rule that makes those identities
/// unclaimable by a declaration, so "is this the engine talking" has one answer and gains the next
/// marker for free.
pub(crate) fn is_engine_identity(sender: &str) -> bool {
    sender
        .rsplit_once('/')
        .map(|(_, bare)| bare)
        .unwrap_or(sender)
        .starts_with(crate::channel::RESERVED_HANDLE_PREFIX)
}

/// Resolve whether `q`'s channel is a DECLARED one and, if so, build the right `Requester` and route
/// the completion through [`on_channel_complete`] — shared by [`reply`]'s completion block and
/// [`tick`]'s deadline re-check, which must run the exact same sequence rather than duplicating
/// it. `Ok(None)` when no declared channel backs the thread; the caller supplies its own fallback
/// (`reply` keeps the original hardcoded wake; `tick` has none, by design — a non-declared thread
/// has no `on_complete` policy behind it at all).
///
/// **Who the result goes to**: `addr` — the thread root's return address, resolved by the caller.
/// It used to be checked first against a `workflow-run:` sentinel, which built a second kind of
/// requester whose completion the run engine consumed directly; 6j6v.dvyq §3 removed both the
/// sentinel and the engine, so there is one kind of requester and it is a return address.
///
/// **Which CONSOLIDATOR runs is resolved here and executed one level down.** The escalation of the
/// settled set is resolved first (see `escalated` below), because since nxf 6j6v.e9qj it decides
/// which output form runs at all — not merely how the discharge is marked. `on_channel_complete`
/// then owns everything the chosen form does, including pass-through's own idempotency marker
/// (retarget to [`DELIVERED_HANDLE`](crate::channel::DELIVERED_HANDLE), self-satisfy) which used to
/// live in this function. Both belong at the point the claim is won, or the losing racer of a
/// pass-through would still write the marker it did not earn.
///
/// **What used to follow the routing, and no longer does**: a run whose channel-target step this
/// completion discharged was advanced from here through its declared transitions, on the
/// `outcome:` token the synthesis carried. That whole branch went with the run record
/// (6j6v.dvyq §3), and with it 6j6v.e9qj's finding F8 — an escalating set passes through, a
/// pass-through emits no token, so the run took a `default` arm as if nothing had gone wrong. What
/// a flow does with an escalation is now the channel supervisor's decision, branching on a DECLARED
/// signal rather than on a token nobody could enumerate.
///
/// What DOES still follow the routing is one level up: if this channel is itself a STEP of another
/// channel's flow, its consolidation just discharged that step, and the outer supervisor is asked
/// to consider its set (see the body's own comment at that call).
pub fn route_declared_channel_completion(
    ctx: &Ctx,
    store: &mut ChatStore,
    q: &ThreadQuorum,
    addr: &str,
    hop: CheckedHop,
) -> Result<Option<CompletionRouted>> {
    // `None` = "nobody has decided this yet, resolve it if you reach the one place that consumes it"
    // — the PULL path ([`tick`]) reaches here without going through the supervisor's
    // synchronous branch, and most calls never get past the `declared` early return below, so
    // deriving here would buy a wasted query on every non-declared completion. The synchronous path
    // resolves it AT THE SEAM and hands it in — see `supervisor_consider_set`.
    route_declared_channel_completion_with(ctx, store, q, addr, None, None, hop)
}

/// [`route_declared_channel_completion`]'s body, with the escalation of the settled set optionally
/// already resolved.
///
/// `escalated: Some(_)` is the supervisor's synchronous branch having decided it ONCE, at the seam
/// (nxf 6j6v.wt37), rather than having it re-derived underneath itself. `None` is **every caller
/// that did not come through that seam** — the `pub` [`route_declared_channel_completion`] passes it
/// unconditionally — which is two callers, not one: [`tick`]'s PULL path, and [`reply`]'s own
/// completion block, whose declared-channel completions are a fold's PHASE 2 (the synthesizer's
/// reply landing). Both have it resolved below.
///
/// **How far the laziness reaches, since nxf 6j6v.e9qj**: to the `declared` early return and no
/// further. It used to be resolved inside the pass-through branch alone, because that was the only
/// branch whose output it changed; it now DECIDES which output form runs at all
/// ([`ChannelDecl::consolidation`](crate::channel::ChannelDecl::consolidation)), so every declared
/// channel's completion pays for the one query and every non-declared one still pays for none.
fn route_declared_channel_completion_with(
    ctx: &Ctx,
    store: &mut ChatStore,
    q: &ThreadQuorum,
    addr: &str,
    escalated: Option<bool>,
    note: Option<&str>,
    hop: CheckedHop,
) -> Result<Option<CompletionRouted>> {
    // The `decl:<name>` reverse lookup: which declared channel, if any, backs this thread. Note
    // this is deliberately the plain lookup, not `Definitions::declared_channel` — a declaration
    // that has since been edited into invalidity must still be RECOGNIZED here, so that
    // `on_channel_complete`'s own fail-closed re-check can turn it into a reported failure rather
    // than an unrecognized channel that silently routes nowhere.
    let declared = ctx
        .defs
        .channels()
        .iter()
        .find(|c| Some(format!("{DECLARED_CHANNEL_PREFIX}{}", c.name)) == q.channel_id);
    let Some(channel) = declared else {
        return Ok(None);
    };
    // **The consolidator, resolved once, here** (nxf 6j6v.e9qj). The escalation is no longer a
    // decoration on one branch — it DECIDES which output form runs (`ChannelDecl::consolidation`'s
    // declared rule: an escalation is never folded away) — so it is resolved before the call rather
    // than at a point one branch reaches. It is still resolved only for a DECLARED channel: every
    // completion that is not one has already returned above, which is what the lazy `None` buys.
    let escalated = match escalated {
        Some(decided) => decided,
        None => set_escalated(ctx, store, q)?,
    };
    let consolidation = channel.consolidation(escalated);
    let mut routed = on_channel_complete(ctx, store, channel, &consolidation, q, addr, note, hop)?;

    // A `Requester::WorkflowRun` branch stood here: a run whose channel-target step this completion
    // discharged, advanced through its declared transitions on the `outcome:` token the synthesis
    // carried. REMOVED with the run record (6j6v.dvyq §3). It also carried 6j6v.e9qj's finding F8 —
    // an escalating set passes through, a pass-through emits no token, so the run took a `default`
    // arm as if nothing had gone wrong — and that finding goes with the mechanism that had it: a
    // channel's supervisor branches on the escalation itself, which is a DECLARED signal and not a
    // token nobody could enumerate.

    // **This channel may itself be a STEP of another channel's flow** (nxf 6j6v.hq71), and if it is,
    // its consolidation just discharged that step. Nothing else would notice: the discharge above is
    // written by the engine through `facade`, not through [`reply`], so the outer supervisor's
    // ordinary entrance is never reached for it.
    //
    // Placed HERE rather than in `supervisor_consolidate` because this is the ONE funnel every
    // declared completion passes through — the supervisor's synchronous branch, `reply`'s own
    // completion block (a fold's phase 2 lands there), and [`tick`]'s PULL path. A hook one
    // level up would have covered only the first.
    //
    // It needs no "did it really finish?" guard: [`supervisor_consider_set`] asks whether the outer
    // set is settled, and a fold's phase 1 leaves this thread expecting the synthesizer and not
    // complete, so the outer supervisor correctly does nothing until phase 2 lands.
    if let Some(outer) = supervising_parent(store, &q.thread_id)? {
        let up = supervisor_consider_set(ctx, store, &outer, &q.thread_id, hop)?;
        // The single-valued fields keep the INNER answer: this receipt belongs to the reply that
        // completed THIS channel, and what it completed is this channel. Everything the outer flow
        // could not carry out is appended, because `warnings` is the one place that is complete
        // rather than first-of-its-kind (nxf 6j6v.93zd).
        routed.woke = routed.woke.or(up.woke);
        routed.wake_skipped = routed.wake_skipped.or(up.wake_skipped);
        routed.warnings.extend(up.warnings);
    }

    Ok(Some(routed))
}

/// What [`session_ended`] found and did. Declared field order = the JSON contract.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct SessionEndedReceipt {
    /// The internal session that announced its end.
    pub session: String,
    /// The thread that session was last put in motion on, when this workspace knows one — the
    /// address the reconsideration below was run against.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub thread: Option<String>,
    /// Why this call ended where it did: `considered` (the announcement reached a supervised step
    /// and its channel was asked again), `acted` (that reconsideration consolidated and delivered),
    /// `not_a_channel_step` (the session stood in a thread no channel supervises — an ordinary
    /// direct conversation), or `no_thread` (the session was never put in motion on one).
    pub reason: String,
    /// The requester session the reconsideration woke, if any — [`TickReceipt::woke`]'s twin, and
    /// reported for its reason: a wake leaves no trace in the store, so no read can recover it.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub woke: Option<String>,
    /// A wake that was attempted and did not land — [`TickReceipt::wake_skipped`]'s twin.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub wake_skipped: Option<WakeSkipped>,
    /// **The requester was working, so the answer is HELD for it** (nxf 6j6v.gn8b) — the third
    /// outcome, and it belongs beside the two above wherever they are reported: an announcement can
    /// settle a channel set, and the requester of that set can be mid-turn like anybody else.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub held: Option<String>,
    /// **Everything this call should have caused and did not** (nxf 6j6v.93zd) — always present,
    /// empty when nothing failed. It matters here for `tick`'s reason and one more: the caller is an
    /// exiting sidecar, so nobody is reading this process's stderr either.
    pub warnings: Vec<FailedConsequence>,
}

/// **A session announces that its own process is over** (`nxc session ended`, nxf 6j6v.10yb) — the
/// sidecar's second callback, beside `session bind`, and the fact a sequential channel was missing.
///
/// **Why it has to be announced rather than observed.** A step of a declared flow used to end when
/// its member's REPLY arrived. That is a fact about a message, and the session behind it can keep
/// working: measured in `watch-bundestag`, a coder replied at 00:16:33 and went on writing until
/// 00:34:27, while the next step of the same `working_tree: exclusive` channel started at 00:16:36
/// and a third session joined thirteen minutes later — all three in one checkout, one of them
/// leaving an unreverted mutation probe in the tree the next was about to commit.
///
/// Process liveness alone cannot close it, and that is not a detail: the only moment anything knows
/// a session is ending is its own teardown, and the process running that teardown is by definition
/// still alive. So the END is recorded here and
/// [`Worker::session_is_running`](crate::worker::Worker::session_is_running) stays as the backstop
/// for the session that was killed hard and never spoke.
///
/// **It is a read plus a re-ask, not a new piece of routing.** Marking the row is the whole of the
/// write; everything after it hands the SAME [`supervisor_consider_set`] the same question a reply
/// would have asked, so a flow that declined to advance while this session was writing advances now
/// through one code path rather than two. Nothing here decides anything a reply does not.
///
/// **Idempotent.** [`ChatStore::mark_session_ended`] is first-wins, and the reconsideration is the
/// one `tick` already documents as safe to repeat — a channel that has consolidated no longer
/// expects its supervisor, which is the marker that makes a second call a clean no-op.
///
/// Rejection: an internal session this workspace never minted is `not_found`, the same answer
/// [`ChatStore::bind_session`] gives its own unknown id — the sidecar's callbacks are a contract,
/// and a silently successful callback about a session nobody knows would hide a spec/env mismatch.
pub fn session_ended(
    ctx: &Ctx,
    store: &mut ChatStore,
    internal_session: &str,
) -> Result<SessionEndedReceipt> {
    let hop = resolve_hop(ctx, store)?;
    if store.session_role(internal_session)?.is_none() {
        return Err(NxfError::not_found(format!(
            "no such internal session: {internal_session}"
        )));
    }
    store.mark_session_ended(internal_session, ctx.now)?;
    // **THE SETTLE SIGNAL** (nxf 6j6v.gn8b). This announcement is the one moment the system knows a
    // caller has stopped working, and it is where a held delivery is armed — not delivered: the
    // process making the announcement is by definition still alive while it speaks, so a resume
    // from here would be refused by the very guard that put the answers in the queue. See
    // [`DELIVERY_GRACE`].
    //
    // Before the early returns below, all of which are ordinary outcomes of the CHANNEL question
    // this verb also answers: whether a held delivery is armed has nothing to do with whether the
    // ending session stood on a channel step.
    let armed = arm_the_held_delivery(ctx, store, internal_session);
    let receipt = |reason: &str, thread: Option<String>| SessionEndedReceipt {
        session: internal_session.to_string(),
        thread,
        reason: reason.to_string(),
        woke: None,
        wake_skipped: None,
        held: None,
        warnings: armed.clone(),
    };
    let Some(thread) = store.session_thread(internal_session)? else {
        return Ok(receipt("no_thread", None));
    };
    // Only a SUPERVISED step is reconsidered. A session that stood in an ordinary direct
    // conversation owes its answer to one named party and there is no set whose settling this could
    // change — the same narrowing [`supervisor_after_reply`]'s branch (A) makes, asked directly
    // because the caller here is not a reply and has no sender to route on.
    let Some(channel_thread) = supervising_parent(store, &thread)? else {
        return Ok(receipt("not_a_channel_step", Some(thread)));
    };
    // The operation's own declarations (nxf 6j6v.n92p) — [`reply`]'s substitution, at the third
    // entrance into the supervisor. A session announcing its end can settle a set and therefore
    // start the next step, so it reads the same declarations and must read the same VERSION.
    let frozen = operation_declarations(ctx, store, &channel_thread)?;
    let ctx = &with_declarations(ctx, frozen.as_ref());
    let run = supervisor_consider_set(ctx, store, &channel_thread, &thread, hop)?;
    debug_assert_one_place(&run.warnings, run.wake_skipped.as_ref());
    let mut warnings = armed;
    warnings.extend(run.warnings);
    Ok(SessionEndedReceipt {
        session: internal_session.to_string(),
        thread: Some(thread),
        reason: if run.completed.is_some() {
            "acted"
        } else {
            "considered"
        }
        .to_string(),
        woke: run.woke,
        wake_skipped: run.wake_skipped,
        held: run.held,
        warnings,
    })
}

// ---- the collecting delivery (nxf 6j6v.gn8b) --------------------------------

/// **How long after a session announces its end the delivery is armed for.**
///
/// It is a fact about PROCESSES, not a policy: the announcement is made by the ending session,
/// whose process is necessarily still alive while it speaks, so a resume attempted from inside
/// `session ended` is refused by the single-process guard (nxf 6j6v.7qtf) — the very refusal that
/// put the answer in the queue. This is the time that process needs to be gone.
///
/// Ten seconds, and the two directions cost differently. Too short and the drain finds the sidecar
/// still winding down, leaves the rows where they are and waits for the NEXT settle — a delay,
/// never a loss. Too long and a caller sits idle with its answers in hand. The measured round-trip
/// this whole item is about is eight to nine seconds, so ten is the shorter of the two mistakes
/// while still clearing an ordinary teardown.
pub const DELIVERY_GRACE: &str = "10s";

/// **How many settled sessions one tick's sweep will drain.**
///
/// The sweep is a backstop on a verb that runs unattended, and every drain it performs SPAWNS a
/// session. A workspace whose service was down for a day can have a long queue, and a tick that
/// started forty processes at once would be a worse failure than the one it is recovering from.
/// The rest stay held and the next tick takes them, which is exactly the behaviour a bounded sweep
/// should have.
const MAX_DRAINS_PER_TICK: usize = 4;

/// What one delivery did. Declared field order = the JSON contract.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct DeliveryReceipt {
    /// The caller this delivery was for.
    pub session: String,
    /// How many held answers it carried — `0` means nothing was waiting, which is a clean no-op
    /// and the ordinary answer for a session that settled with an empty queue.
    pub delivered: usize,
    /// How many of those were hand-backs, delivered set apart from the ordinary answers.
    pub escalations: usize,
    /// The session this resumed, when the resume landed. `None` when nothing was delivered, or
    /// when the resume was attempted and did not land — [`wake_skipped`](Self::wake_skipped) is
    /// what tells those two apart.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub woke: Option<String>,
    /// The resume that was attempted and did not land. **The held rows are NOT released in that
    /// case** — they stay in the queue for the next settle, which is the whole point of the queue
    /// being durable.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub wake_skipped: Option<WakeSkipped>,
    /// The caller's own commissions that had still not answered when this delivery went out — the
    /// threads, in the same order the delivery names them.
    pub outstanding: Vec<String>,
    /// Everything this call should have caused and did not — [`ReplyReceipt::warnings`]'s twin, and
    /// it matters here for [`TickReceipt::warnings`]' reason: this verb runs unattended.
    pub warnings: Vec<FailedConsequence>,
}

/// **Hand a settled caller everything that arrived while it was working** (`nxc session deliver`,
/// nxf 6j6v.gn8b).
///
/// ONE resume with ONE composed delivery, in the same shape a channel round's `pass_through` uses,
/// naming what is still outstanding — see [`crate::collecting::compose_collected_wake`] for the
/// three things that delivery says and why each is load-bearing.
///
/// **Idempotent, and idempotent in the safe direction.** An empty queue is a clean `delivered: 0`,
/// never an error: this verb is run by a scheduled job and by a sweep, and both may reach a session
/// whose queue another one has already drained. The rows are deleted only AFTER the resume has been
/// handed over, so the failure mode of a crash in that window is a caller told twice rather than
/// never — see [`crate::collecting`] for that argument in full.
///
/// **It does not ask whether the session is running.** The one caller that has to — the tick's
/// sweep — asks before it calls, because it is guessing at the settle; the scheduled job does not,
/// because it was armed BY the settle. A resume into a session that started again in the meantime
/// is refused by the guard, reported as an ordinary skip, and leaves the queue intact.
pub fn deliver_held(ctx: &Ctx, store: &mut ChatStore, session: &str) -> Result<DeliveryReceipt> {
    let hop = resolve_hop(ctx, store)?;
    let rows = store.held_wakes(session)?;
    let nothing = |outstanding: Vec<String>| DeliveryReceipt {
        session: session.to_string(),
        delivered: 0,
        escalations: 0,
        woke: None,
        wake_skipped: None,
        outstanding,
        warnings: Vec::new(),
    };
    if rows.is_empty() {
        return Ok(nothing(Vec::new()));
    }
    let (escalations, answers): (Vec<_>, Vec<_>) = rows.iter().partition(|r| r.held.escalated);
    let collected = |rows: &[&crate::collecting::HeldRow]| -> Vec<crate::channel::CollectedReply> {
        rows.iter()
            .map(|r| crate::channel::CollectedReply {
                // WHICH commission this answers — the fact a caller with three of them outstanding
                // cannot recover from the body, and the reason `CollectedReply` grew the field.
                thread: Some(r.held.thread_id.clone()),
                ..crate::channel::CollectedReply::new(r.held.sender.clone(), r.held.body.clone())
            })
            .collect()
    };
    let outstanding = outstanding_commissions(ctx, store, session)?;
    // Where the resumed session now stands. ONE held answer puts it on that answer's thread, the
    // same as an ordinary 1:1 resume (nxf 6j6v.a71h §3.1); several put it nowhere new, because a
    // delivery spanning three commissions has no single thread it happened in and picking one
    // would hang whatever the caller opens next under an arbitrary branch.
    let stands_on = match rows.as_slice() {
        [only] => Some(only.held.thread_id.as_str()),
        _ => None,
    };
    // **The coordinator names the addressees here too** (nxf 6j6v.dq59) — this is the wake a caller
    // that was mid-turn finally gets, and it is exactly the shape the rule is written for: several
    // answers arriving at once is how a session ends up with more than one open conversation.
    // "Still outstanding" above says what has NOT come back; this says where this session may
    // speak, which is a different question and the one `reply` needs answered.
    let guidance = reply_guidance(
        store,
        ctx.now,
        &store
            .session_role(session)
            .ok()
            .flatten()
            .map(|role| ctx.qualify(&role))
            .unwrap_or_default(),
        stands_on,
    );
    let body = crate::collecting::compose_collected_wake(
        &collected(&escalations),
        &collected(&answers),
        &outstanding,
        &guidance,
    );
    let attempt = resume_return_address(
        ctx,
        store,
        Resume {
            addr: session,
            body: &body,
            model: None,
            hop,
            thread: stands_on,
            // NEVER re-hold: this call IS the queue's drain, and holding what it failed to deliver
            // would be the same rows written back under a second id.
            on_busy: OnBusy::ReportOnly,
        },
    );
    let mut warnings = Vec::new();
    if let Some(w) = &attempt.skipped {
        warnings.push(FailedConsequence::not_woken(stands_on, w));
    }
    warnings.extend(attempt.findings.iter().cloned());
    if attempt.woke.is_some() {
        // AFTER the hand-over, never before — see [`crate::collecting`].
        let ids: Vec<i64> = rows.iter().map(|r| r.id).collect();
        store.release_held_wakes(&ids)?;
    }
    Ok(DeliveryReceipt {
        session: session.to_string(),
        delivered: rows.len(),
        escalations: escalations.len(),
        woke: attempt.woke,
        wake_skipped: attempt.skipped,
        outstanding: outstanding.into_iter().map(|o| o.thread_id).collect(),
        warnings,
    })
}

/// **The caller's own commissions that have still not answered** — the half of a collected delivery
/// that keeps it honest (nxf 6j6v.gn8b).
///
/// "Everything that arrived" is not "all the answers", and a wake carrying two of three is honest
/// only if it says the third is still owed. Without this the wakes are merely BATCHED and the
/// bookkeeping still sits with the caller, which is the defect the whole item exists to remove.
///
/// **Scoped to the caller's HANDLE, not to its session**, and that is a deliberate widening: the
/// opener recorded on a thread is a chat identity (`<origin>/<handle>`), never a session id, so a
/// session-exact answer would need a second derivation over every message's return address. A
/// persona has one live session at a time by construction — the single-process guard is what makes
/// that true — and on the rare occasion it has two, naming a sibling session's outstanding
/// commission is still the caller's own work rather than somebody else's.
///
/// A thread is outstanding when it DECLARES an expectation and has not discharged it: no expected
/// handle means nobody was ever asked, `complete` means everybody answered, and `stale` means the
/// declared window ran out — a round that has stopped, which is not the same as one still owed.
fn outstanding_commissions(
    ctx: &Ctx,
    store: &ChatStore,
    session: &str,
) -> Result<Vec<crate::collecting::Outstanding>> {
    let Some(role) = store.session_role(session)? else {
        return Ok(Vec::new());
    };
    let handle = format!("{}/{}", ctx.origin, role);
    let opened = store.threads_opened_by(&handle)?;
    if opened.is_empty() {
        return Ok(Vec::new());
    }
    let refs: Vec<&str> = opened.iter().map(String::as_str).collect();
    Ok(store
        .thread_quorums(&refs, ctx.now)?
        .into_iter()
        .filter(|q| !q.expects.is_empty() && !q.complete && !q.stale)
        .map(|q| crate::collecting::Outstanding {
            thread_id: q.thread_id,
            expects: q.expects,
        })
        .collect())
}

/// Arm the delivery of whatever is held for `session`, if anything is (nxf 6j6v.gn8b).
///
/// Best-effort by construction, and it must be: it rides on `session ended`, whose own doc says a
/// failure there costs a DELAY and never a wrong answer. A workspace with no service attending it
/// gets the same treatment every other unarmed window gets — the deadline is recorded, the finding
/// is reported, and the tick's sweep is the other way the same queue drains.
fn arm_the_held_delivery(ctx: &Ctx, store: &ChatStore, session: &str) -> Vec<FailedConsequence> {
    match store.held_wakes(session) {
        Ok(rows) if rows.is_empty() => Vec::new(),
        Ok(_) => {
            let due = match facade::resolve_instant(ctx.now, DELIVERY_GRACE, "the delivery grace") {
                Ok(due) => due,
                Err(e) => return vec![FailedConsequence::tick_unscheduled(session, &e.msg)],
            };
            match ctx.timer.schedule_delivery(session, &due) {
                Ok(_) => Vec::new(),
                Err(e) => vec![FailedConsequence::tick_unscheduled(session, &e.msg)],
            }
        }
        Err(e) => vec![FailedConsequence::tick_unscheduled(session, &e.msg)],
    }
}

/// Deliver to every session that is holding something and is no longer running — the tick's
/// backstop for a caller that was killed before it could announce its end (nxf 6j6v.gn8b).
///
/// **Bounded** ([`MAX_DRAINS_PER_TICK`]) and **guarded**: a session the worker reports as running
/// is skipped without a resume attempt, so the ordinary case of a busy caller costs one pid read.
/// A worker that cannot answer the liveness question at all answers `false` — the reasoned default
/// — and this sweep then tries the delivery, which the guard refuses if a process really is there.
/// That is the same fail-open direction every other reader of that flag takes, and here it is
/// harmless: the refusal leaves the queue intact.
fn sweep_held_deliveries(ctx: &Ctx, store: &mut ChatStore) -> Vec<FailedConsequence> {
    let sessions = match store.sessions_holding_wakes() {
        Ok(sessions) => sessions,
        Err(e) => {
            return vec![FailedConsequence::tick_unscheduled(
                "held deliveries",
                &e.msg,
            )]
        }
    };
    let mut findings = Vec::new();
    let mut drained = 0;
    for session in sessions {
        if drained >= MAX_DRAINS_PER_TICK {
            break;
        }
        if ctx.worker.session_is_running(&session) {
            continue;
        }
        drained += 1;
        match deliver_held(ctx, store, &session) {
            Ok(receipt) => findings.extend(receipt.warnings),
            Err(e) => findings.push(FailedConsequence::tick_unscheduled(&session, &e.msg)),
        }
    }
    findings
}

// ---- the way back from an availability boundary (nxf 6j6v.npy3) ------------------------------

/// **How long after a session stops at an availability boundary the way back is FIRST armed.**
///
/// The same fact as [`DELIVERY_GRACE`], written as the same value rather than a second number: the
/// announcement is made BY the stopping session, whose process is necessarily still alive while it
/// speaks, and this is the time that process needs to be gone. A resume attempted before then is
/// refused by the single-process guard (nxf 6j6v.7qtf) — correctly — and a park attempted before
/// then would commit a tree underneath a process still standing in it.
///
/// **FIRST armed**, because the way back fires twice over one hold. This grace is the near firing,
/// which secures the working copy and re-arms for the instant the window actually lifts; a weekly
/// window puts that up to a week out, and holding a checkout for a week is not on offer.
pub const RESUME_GRACE: &str = DELIVERY_GRACE;

/// What recording one hold did. Declared field order = the JSON contract.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct InterruptionReceipt {
    /// The session that stopped.
    pub session: String,
    /// The thread it was standing on, when it was standing on one.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub thread: Option<String>,
    /// Which boundary the runtime named.
    pub limit: String,
    /// When the runtime says the boundary falls, or absent when it named no instant.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub until: Option<String>,
    /// **When the way back was armed for** — `None` when nothing could be armed, which
    /// [`warnings`](Self::warnings) then says the reason for.
    ///
    /// It is the near firing ([`RESUME_GRACE`]), not [`until`](Self::until): what runs then decides
    /// whether the window has lifted and re-arms itself if it has not.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub armed_for: Option<String>,
    /// Everything this call should have caused and did not.
    pub warnings: Vec<FailedConsequence>,
}

/// **Record that a session stopped because the model went away** (`nxc session interrupted`, nxf
/// 6j6v.npy3) — the runtime's third callback, beside `session bind` and `session ended`.
///
/// It says nothing the engine could have worked out for itself, which is why it is a callback and
/// not a derivation: only the runtime knows that a provider refused this session as opposed to
/// crashing under it, and only the runtime is told when the window lifts. What this verb does with
/// that is put it somewhere a reader can see and arm the return.
///
/// **The measured gap it closes is the first half, not the second.** Of thirty sessions in one run,
/// one hit the weekly window; afterwards `nxc session state` reported a clean `ended`, its thread
/// read `answered`, and nothing anywhere was `escalated` or `substituted`. The whole channel record
/// of that workspace was searched and the interruption was not in it. The system could not SAY it
/// had been interrupted, which is a shorter sentence than "cannot resume it" and a worse one.
///
/// **Idempotent**, at the store ([`ChatStore::record_interruption`]): a retried teardown re-arms the
/// same deadline under the same key and leaves one row, never two.
///
/// An unknown `internal_session` is `not_found`, exactly as [`session_ended`] treats one — a
/// callback naming a session this workspace never minted is a mistake to report, not a row to
/// invent.
pub fn session_interrupted(
    ctx: &Ctx,
    store: &mut ChatStore,
    internal_session: &str,
    limit: &str,
    until: Option<&str>,
    detail: &str,
) -> Result<InterruptionReceipt> {
    if store.session_role(internal_session)?.is_none() {
        return Err(NxfError::not_found(format!(
            "no such internal session: {internal_session}"
        )));
    }
    store.record_interruption(internal_session, limit, until, detail, ctx.now)?;
    let thread = store.session_thread(internal_session)?;
    let mut warnings = Vec::new();
    // **Armed for the GRACE and not for `until`**, even when `until` is known and far away. What
    // fires then does the half of the way back that cannot wait — securing the working copy, so a
    // week-long window does not hold this workspace's checkout for a week — and re-arms itself for
    // the instant the window lifts.
    //
    // And armed even when the runtime named NO instant: the working copy still has to be handed on.
    // What such a hold does not get is an automatic return, which is that firing's decision to make
    // and not this one's.
    let armed_for = match facade::resolve_instant(ctx.now, RESUME_GRACE, "the resume grace") {
        Ok(due) => match ctx.timer.schedule_resume(internal_session, &due) {
            Ok(_) => Some(due),
            Err(e) => {
                warnings.push(FailedConsequence::tick_unscheduled(
                    internal_session,
                    &e.msg,
                ));
                None
            }
        },
        Err(e) => {
            warnings.push(FailedConsequence::tick_unscheduled(
                internal_session,
                &e.msg,
            ));
            None
        }
    };
    Ok(InterruptionReceipt {
        session: internal_session.to_string(),
        thread,
        limit: limit.to_string(),
        until: until.map(str::to_string),
        armed_for,
        warnings,
    })
}

/// Which hold [`resume_interrupted`] is being asked to take up.
///
/// Two addressings of one thing, for [`SessionScope`]'s reason — one verb, one record, one place
/// where what it means to ask is decided:
///
/// * [`Thread`](ResumeScope::Thread) is what a HUMAN types, because a thread id is what `nxc status`
///   puts in front of them and an operation is what they are taking up.
/// * [`Session`](ResumeScope::Session) is what the background service's job carries, because the
///   hold is keyed on the session that stopped.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ResumeScope<'a> {
    /// The session that stopped, by its internal id.
    Session(&'a str),
    /// Any thread of the operation that stopped. The hold is looked up across the thread's own
    /// sessions.
    Thread(&'a str),
}

/// **What a resume decided** — and every variant but [`Resumed`](ResumeOutcome::Resumed) is a
/// decision NOT to start anything, which is the point of the type.
///
/// The rule this enumerates is the owner's: *beim Fortsetzen wird die Welt GEPRUEFT, nicht der
/// letzten Absicht geglaubt.* An interrupted turn may have written files, created tickets and posted
/// messages before the window closed — the measured case missed by 0.6 seconds — so a resume that
/// trusted the record of what was being attempted would redo whatever had already landed.
///
/// `#[non_exhaustive]` for the reason [`TriggerError`] and [`WakeSkipReason`] carry it: a further
/// refusal later must be an additive minor for a host matching on this, never a source break.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "snake_case", tag = "outcome")]
#[non_exhaustive]
pub enum ResumeOutcome {
    /// Nothing is on hold here — never interrupted, or already taken up. A clean no-op, which is
    /// what makes this verb safe to run twice: the background job and a human can both arrive.
    NothingOnHold,
    /// **The boundary has not fallen yet.** The near firing secured what it could and the return is
    /// re-armed for the instant the runtime named. A human asking for this by hand is told the
    /// same, and is not stopped by it — see [`ResumeRequest::force`].
    NotYet {
        /// When the window lifts, or ABSENT when the runtime named no instant.
        ///
        /// Absent is a real answer and the receipt keeps saying it: the working copy has been
        /// secured and the hold stands, but nothing will start this on its own, because no moment
        /// was ever stated to start it at. `nxc resume --thread <id>` is then the way back, run by
        /// somebody who knows what the record does not.
        #[serde(skip_serializing_if = "Option::is_none")]
        until: Option<String>,
    },
    /// **The round was already answered before the window closed**, so there is nothing to continue
    /// and the hold is stamped taken up without anything being started.
    ///
    /// THE MEASURED CASE, and the cheapest of all the world checks: the quota struck 0.6 s after
    /// the session's own `nxc reply` landed. The judgement was durable, the turn's obligation
    /// discharged — and a resume that had not looked would have paid for a session to redo three
    /// full review rounds and post a second verdict over the first.
    AlreadyAnswered,
    /// A process for this session is ALREADY ALIVE, so nothing was started — the refusal IS the fix
    /// (nxf 6j6v.7qtf). It is what keeps a human resuming early from colliding with the background
    /// job arriving at the reset time, and it is deliberately the EXISTING guard rather than a
    /// second watchdog built beside it.
    AlreadyRunning,
    /// **The working copy moved while this operation waited, and nothing was parked** — so a
    /// question went back to the thread that started the operation and nothing was resumed.
    ///
    /// The owner's rule of 2026-09-12, in the words it was given in: *"Ist der Zustand gewandert,
    /// geht eine Frage zurueck an den anfaenglichen Faden, der den Vorgang gestartet hat."* It is
    /// the same emergency exit nxf 6j6v.am8j uses, deliberately — the machine does not decide, it
    /// asks whoever commissioned the work.
    TreeMoved {
        /// What moved, so the human answering the question can see it without a git command.
        drift: crate::anchor::Drift,
    },
    /// **This runtime cannot continue a conversation it began** — [`Worker::resumes_sessions`] is
    /// false, so a "resume" here would silently start a FRESH session under a name that has a
    /// transcript.
    ///
    /// Refused by name rather than done quietly, because the transcript is the whole protection
    /// against doing the work twice: a session that sees its own `nxf create` and the id it
    /// returned does not create the ticket again, and one started from nothing does.
    ProviderCannotResume,
    /// The session was started again, with its transcript in front of it.
    Resumed,
}

/// Take up an operation that stopped at an availability boundary.
#[derive(Debug, Clone)]
pub struct ResumeRequest<'a> {
    /// Which hold to take up.
    pub scope: ResumeScope<'a>,
    /// **Start it even though the runtime's window has not lifted yet.**
    ///
    /// For the case the owner named: *"Vielleicht hat der Nutzer noch einen anderen Account und
    /// will direkt weiter machen."* The record knows when the boundary falls for the account that
    /// hit it, and it does not know what the person at the terminal has arranged since — so
    /// [`NotYet`](ResumeOutcome::NotYet) is a report to a human, never a refusal of one.
    ///
    /// `false` for the background service, always: an unattended job that overrode the runtime's
    /// own reset time would spend a paid start on a window it was told is closed.
    pub force: bool,
}

/// What one resume did. Declared field order = the JSON contract.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct ResumeReceipt {
    /// The session whose hold this was, when one was found.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub session: Option<String>,
    /// The thread that session was standing on.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub thread: Option<String>,
    /// What was decided — and mostly, what was decided AGAINST. See [`ResumeOutcome`].
    #[serde(flatten)]
    pub outcome: ResumeOutcome,
    /// **When the way back was re-armed for**, on the firing that found the window still closed.
    /// `None` on every other outcome, and on one that should have re-armed and could not — which
    /// [`warnings`](Self::warnings) then names.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub armed_for: Option<String>,
    /// Everything this call should have caused and did not.
    pub warnings: Vec<FailedConsequence>,
}

/// **Take up an operation that stopped at an availability boundary** (`nxc resume`, nxf 6j6v.npy3).
///
/// Run by a human who is not waiting for the window, and by the background service when it falls —
/// the same verb both times, because the checks a human needs are the checks an unattended job needs
/// more.
///
/// # The world is checked; the last intention is not believed
///
/// The owner's rule, and every early return of [`ResumeOutcome`] is one clause of it. An interrupted
/// turn may already have written files, created tickets and posted messages: the transcript records
/// each tool call WITH its result, so a continued session can see what it did — but the boundary can
/// fall BETWEEN a `tool_use` and its `tool_result`, and then the continued session sees a call with
/// no answer and will make it again. In the measured case the result landed 0.6 s before the wall;
/// that was luck, not a guarantee. So the cheap facts are re-read here, at the one place that can
/// act on them, before anything is started.
///
/// # What it does NOT do: replay
///
/// The session is started again WITH its runtime conversation ([`ContinuedSession`], `resume_real`),
/// never from the top. `TurnTerms::runtime_retries` states the reason in its own words — *the files,
/// the messages, the pull requests all happen a second time* — and it is why that retry covers only
/// the one shape where the model produced nothing at all. Continuing is SAFER than repeating,
/// because the transcript is what stops the work being done twice.
///
/// # The residual, named rather than left to be discovered
///
/// **A CHANNEL MEMBER can be on hold for longer than its own declared `timeout:`.** A weekly window
/// is days; a member's window is usually minutes. While the hold stands the slot is neither
/// `complete` nor — at first — `stale`, so [`member_set_is_settled`] keeps the set open and the
/// channel waits, which is what should happen. Once that window lapses the slot reads `stale`, the
/// set settles, and the channel consolidates WITHOUT this member's answer — leaving the hold
/// standing over a round that has moved on.
///
/// Nothing here prevents that, and nothing here should: a declared `timeout:` is a promise about
/// when an answer is due, and overriding it because a provider was busy would make the declaration
/// mean something different depending on the provider's mood. What happens instead is that the
/// resume fires, finds its round consolidated, and the session's reply is refused by name — the
/// refusal `tests/a_reply_into_a_finished_round_is_refused.rs` pins. That is why
/// [`continuation_message`] tells the session to check the world before acting rather than assume
/// its thread is where it left it. The failure is loud, late and harmless, which is the shape it
/// should have; a version that quietly answered into a finished round would not be.
///
/// It is also strictly better than what stood here before this item, where such a member posted a
/// substitute escalation the instant the window closed — discharging the round with a sentence the
/// agent never said.
pub fn resume_interrupted(
    ctx: &Ctx,
    store: &mut ChatStore,
    req: ResumeRequest,
) -> Result<ResumeReceipt> {
    let mut warnings = Vec::new();
    let nothing = |outcome: ResumeOutcome| ResumeReceipt {
        session: None,
        thread: None,
        outcome,
        armed_for: None,
        warnings: Vec::new(),
    };
    let Some(hold) = standing_hold(store, req.scope)? else {
        return Ok(nothing(ResumeOutcome::NothingOnHold));
    };
    let session = hold.session.clone();
    let thread = store.session_thread(&session)?;
    let receipt = |outcome: ResumeOutcome, armed_for, warnings| ResumeReceipt {
        session: Some(session.clone()),
        thread: thread.clone(),
        outcome,
        armed_for,
        warnings,
    };

    // **ALREADY RUNNING — asked first, because everything below costs something.** It is the same
    // fact the single-process guard acts on (nxf 6j6v.7qtf), read rather than re-implemented: a
    // human resuming early and the service arriving at the reset time are exactly the two processes
    // that rule exists to keep out of one working copy. If this read races, the guard underneath
    // still refuses — this only saves the message and the git reads.
    if ctx.worker.session_is_running(&session) {
        return Ok(receipt(ResumeOutcome::AlreadyRunning, None, warnings));
    }

    // **ALREADY ANSWERED — the measured case, and the cheapest check there is.** The round this
    // session was working on is discharged, so there is nothing to continue and the hold is closed
    // without a model call. Asked BEFORE the window question on purpose: work that is finished is
    // finished whether or not the boundary has fallen.
    if round_is_discharged(ctx, store, &hold, thread.as_deref())? {
        stamp_taken_up(ctx, store, hold.id, &mut warnings);
        return Ok(receipt(ResumeOutcome::AlreadyAnswered, None, warnings));
    }

    // **NOT YET.** This is the near firing: secure the working copy — a weekly window is up to a
    // week, and holding this workspace's checkout for a week is not on offer — and re-arm for the
    // instant the runtime named. A hold with no instant is still secured and simply gets no
    // automatic return, which is the honest consequence of nobody having said when it lifts.
    if !hold.is_due(ctx.now) && !req.force {
        secure_the_interrupted_tree(ctx, store, thread.as_deref(), &mut warnings);
        let armed_for = hold.until.as_deref().and_then(|until| {
            match ctx.timer.schedule_resume(&session, until) {
                Ok(_) => Some(until.to_string()),
                Err(e) => {
                    warnings.push(FailedConsequence::tick_unscheduled(&session, &e.msg));
                    None
                }
            }
        });
        return Ok(receipt(
            ResumeOutcome::NotYet {
                until: hold.until.clone(),
            },
            armed_for,
            warnings,
        ));
    }

    // **CAN THIS RUNTIME CONTINUE WHAT IT BEGAN?** Only asked where there is something to continue:
    // a session that was never bound to a runtime session never produced anything, so starting it
    // fresh loses nothing and is exactly right. Where there IS a conversation, a worker that cannot
    // resume would start a NEW one under a name that has a transcript — and the transcript is the
    // whole protection against doing the work a second time.
    let resume_real = store.resolve_real(&session)?;
    if resume_real.is_some() && !ctx.worker.resumes_sessions() {
        // **AND THE HOLD IS HANDED TO A PERSON RATHER THAN LEFT STANDING FOREVER** (independent
        // review of PR #476, Integrity & Robustness #2).
        //
        // Every other outcome here is a state that CHANGES: a window lifts, a process exits, a
        // human answers a question about a moved tree. This one does not. Whether a runtime can
        // continue a conversation it began is a fixed fact about the workspace's worker, so a hold
        // left standing on it is a hold that every future resume — human and scheduled alike —
        // will refuse in exactly the same words, for as long as the workspace exists. That is a
        // dead end with an "ON HOLD" label on it, which is worse than a refusal: it reads like
        // something is coming.
        //
        // So it is STAMPED, and `resume_parked_work` two hundred lines up is the precedent for what
        // that means here — *"what the row records is that somebody was TOLD about this park, and
        // telling them twice about the same branch on the next trigger would be noise, not
        // safety"*. Same word, same reading: the hold has been DEALT WITH, not the session
        // restarted. The row stays in the table with its instant, so what happened is still
        // readable.
        //
        // And the person is actually told, on the thread that started the operation — the same
        // emergency exit `TreeMoved` takes, because this is the same kind of moment: the machine
        // cannot carry this out and will not pretend otherwise. Continuing here would mean starting
        // a FRESH conversation with none of the session's history, and redoing side effects it has
        // already had is precisely what the transcript exists to prevent; whether that is worth it
        // for this particular piece of work is a judgement, and it is not the engine's.
        tell_the_root_thread(
            ctx,
            store,
            &hold,
            thread.as_deref(),
            &provider_cannot_resume_notice(&hold, thread.as_deref()),
            &mut warnings,
        );
        stamp_taken_up(ctx, store, hold.id, &mut warnings);
        return Ok(receipt(ResumeOutcome::ProviderCannotResume, None, warnings));
    }

    // **DID THE TREE MOVE WHILE THIS OPERATION WAITED?** Only where nothing was PARKED: a park
    // records its own branch and reports its own [`crate::park::Movement`] when the trigger below
    // brings it back, and asking both questions would report the park's own commit as drift every
    // single time. Where nothing was parked, this is the only thing that can notice that another
    // chain has been through the checkout.
    if let Some(drift) = the_tree_moved_under_the_hold(ctx, store, thread.as_deref())? {
        ask_the_root_thread(ctx, store, &hold, thread.as_deref(), &drift, &mut warnings);
        // **The hold is NOT stamped and nothing is re-armed.** The operation has not been taken up
        // — it is waiting for a person to say what should happen — so it stays on hold, which is
        // what keeps it visible in `nxc status` instead of looking finished. And nothing re-arms,
        // so the question is asked once rather than at every window a long wait produces; the way
        // back after an answer is the same verb, run by whoever answered.
        return Ok(receipt(ResumeOutcome::TreeMoved { drift }, None, warnings));
    }

    let role = store
        .session_role(&session)?
        .ok_or_else(|| NxfError::not_found(format!("no such session: {session}")))?;
    let body = continuation_message(&hold, &role, thread.as_deref());
    let channel = thread
        .as_deref()
        .and_then(|t| store.thread_quorum(t, ctx.now).ok().flatten())
        .and_then(|q| q.channel_id);
    let started = role_resume(
        ctx,
        store,
        RoleResumeRequest {
            session: &session,
            body: &body,
            channel: channel.as_deref(),
            kind: MessageKind::Info,
            priority: Priority::Normal,
            disposition: Disposition::InTurn,
            thread: thread.as_deref(),
            refs: Refs::default(),
            model: None,
        },
    );
    match started {
        Ok(r) => {
            warnings.extend(r.warnings);
            // Stamped AFTER the trigger, for `note_the_park_was_resumed`'s reason: what the stamp
            // records is that somebody was actually put back to work. A hold closed before a spawn
            // that then failed would be a hold nothing ever comes back to.
            stamp_taken_up(ctx, store, hold.id, &mut warnings);
            Ok(receipt(ResumeOutcome::Resumed, None, warnings))
        }
        // **A failure here PROPAGATES, and is deliberately not reclassified.** The single-process
        // guard can still refuse below this line — the pre-check above and the spawn are two
        // moments — and the temptation is to map that back onto
        // [`AlreadyRunning`](ResumeOutcome::AlreadyRunning) by matching on the message. That is
        // exactly what [`crate::worker::TriggerError`]'s own doc rules out: a caller string-matching
        // an error text is the defect that type exists to remove, and buying a tidier receipt with
        // it would be paying in the currency this crate has already decided not to spend. What a
        // lost race costs is an error instead of an outcome, on a path whose pre-check makes it
        // rare, and the refusal did its job either way.
        Err(e) => Err(e),
    }
}

/// The hold a [`ResumeScope`] names, or `None` when nothing is on hold there.
///
/// A thread resolves through the sessions recorded ON it, newest first — which is the session that
/// was working when the window closed. It deliberately does NOT walk the whole operation: a thread
/// is what a human reads off `nxc status`, and taking up "some session somewhere under this root"
/// would start work the person did not point at.
fn standing_hold(
    store: &ChatStore,
    scope: ResumeScope<'_>,
) -> Result<Option<crate::interruption::Interruption>> {
    match scope {
        ResumeScope::Session(session) => store.current_interruption(session),
        ResumeScope::Thread(thread) => {
            for row in store.sessions_in_thread(thread)?.into_iter().rev() {
                if let Some(hold) = store.current_interruption(&row.internal_id)? {
                    return Ok(Some(hold));
                }
            }
            Ok(None)
        }
    }
}

/// **Is the round this session was working on already finished?** — the world check that costs one
/// indexed read and saves a whole paid turn.
///
/// The question is asked of the QUORUM and not of the session: a role that was expected on this
/// thread and is no longer outstanding has answered, whatever happened to the process afterwards.
/// A session that was never expected on its thread at all reads `false` — there is no discharge to
/// observe, so the work is not known to be done and the resume goes ahead, which is the safe
/// direction for a session that was commissioned with no registered obligation.
fn round_is_discharged(
    ctx: &Ctx,
    store: &ChatStore,
    hold: &crate::interruption::Interruption,
    thread: Option<&str>,
) -> Result<bool> {
    let (Some(thread), Some(role)) = (thread, store.session_role(&hold.session)?) else {
        return Ok(false);
    };
    let handle = ctx.qualify(&role);
    Ok(store
        .thread_quorum(thread, ctx.now)?
        .is_some_and(|q| q.expects.contains(&handle) && !q.outstanding.contains(&handle)))
}

/// Stamp a hold as taken up, best-effort. A failure costs the bookkeeping, never the work that was
/// just started — the same call every other `mark_*_resumed` site in this module makes.
fn stamp_taken_up(
    ctx: &Ctx,
    store: &mut ChatStore,
    id: i64,
    warnings: &mut Vec<FailedConsequence>,
) {
    if let Err(e) = store.mark_interruption_resumed(id, ctx.now) {
        let detail = format!("the hold {id} was taken up, but recording that failed: {e}");
        eprintln!("warning: {detail}");
        warnings.push(FailedConsequence::step_unanswered(None, detail));
    }
}

/// **Has the working copy moved since this operation last described it?** — [`crate::anchor::
/// Anchor::drift_from`]'s one consumer, which that function's own doc names.
///
/// `None` — no drift to report — covers every reason the question cannot be answered as well as the
/// answer "nothing moved", and that collapse is deliberate: this gates whether to ask a HUMAN a
/// question, and a question nobody can act on is worse than none. A workspace whose runtime names no
/// directory, a thread whose handovers recorded no anchor, a git read that failed — all of them mean
/// *this check has nothing to say*, and the resume goes ahead exactly as it would have before
/// anchors existed.
///
/// **Skipped where THIS OPERATION has work parked.** A park commits the tree onto its own branch
/// and returns the checkout to the base, so the anchor of the handover and the tree afterwards
/// differ by construction — asking here would report drift on every parked hold and send every one
/// of them to a human. What answers the question for a parked operation is
/// [`crate::park::Movement`], reported by the resume of the park itself when the trigger brings it
/// back.
///
/// **THIS operation's, and the distinction is a correctness one** (independent review of PR #476,
/// Code Quality #2). [`ChatStore::any_parked_work`] is a WORKSPACE-WIDE flag, and it is used in
/// this module exactly once elsewhere — in [`trigger_role`]'s lease gate, where its own comment
/// says what it is for: a cheap pre-filter that is *always* followed by
/// `store.parked_work(&scope.key())`, so that "a trigger belonging to any other operation leaves
/// this gate exactly as it found it". Read as a DECISION rather than a pre-filter, it means an
/// unrelated park anywhere in the workspace — a contended exclusive channel three operations away —
/// silently switches off drift detection for THIS one, and the resume then walks into a tree that
/// genuinely moved. That is the "resuming blind" case the item exists to prevent, arriving through
/// the very check written to prevent it.
fn the_tree_moved_under_the_hold(
    ctx: &Ctx,
    store: &ChatStore,
    thread: Option<&str>,
) -> Result<Option<crate::anchor::Drift>> {
    let Some(thread) = thread else {
        return Ok(None);
    };
    // The cheap workspace-wide read first, then THIS operation's own — the pre-filter discipline
    // `trigger_role` states, so a workspace that has never parked anything pays one indexed read
    // and no thread-tree walk.
    if store.any_parked_work()? {
        let scope = crate::working_tree::resolve_scope(
            lease_claim_root(store, Some(thread))?.as_deref(),
            "",
        );
        if !store.parked_work(&scope.key())?.is_empty() {
            return Ok(None);
        }
    }
    let Some(then) = store
        .working_copy_anchors(&[thread])?
        .into_iter()
        .next()
        .map(|a| a.anchor)
    else {
        return Ok(None);
    };
    let Ok(copy) = the_working_copy(ctx) else {
        return Ok(None);
    };
    let Ok(now) = copy.anchor() else {
        return Ok(None);
    };
    let drift = now.drift_from(&then);
    Ok(drift.any().then_some(drift))
}

/// **Put the question back to the thread that started the operation** — the owner's rule of
/// 2026-09-12, in the words it was given in: *"Ist der Zustand gewandert, geht eine Frage zurueck an
/// den anfaenglichen Faden, der den Vorgang gestartet hat."*
///
/// The ROOT and not the session's own thread, and that is the whole point: the session's thread is
/// where the machine was working, and the root is where the person who commissioned the work is
/// reading. It is the same emergency exit nxf 6j6v.am8j takes, and the sameness is wanted — a second
/// mechanism for "the machine will not decide this" is how two of them come to behave differently.
///
/// Best-effort. A question that could not be posted is a warning and not a failure: the resume has
/// already decided not to start anything, and that decision stands whether or not the sentence
/// explaining it arrived.
fn ask_the_root_thread(
    ctx: &Ctx,
    store: &mut ChatStore,
    hold: &crate::interruption::Interruption,
    thread: Option<&str>,
    drift: &crate::anchor::Drift,
    warnings: &mut Vec<FailedConsequence>,
) {
    let Some(t) = thread else { return };
    let body = drift_question(hold, t, drift);
    tell_the_root_thread(ctx, store, hold, thread, &body, warnings);
}

/// **Put `body` in front of the person who started the operation** — the delivery half of
/// [`ask_the_root_thread`], shared with the one other outcome that has to reach a human
/// ([`ResumeOutcome::ProviderCannotResume`]).
///
/// The ROOT and not the session's own thread, and that is the whole point: the session's thread is
/// where the machine was working, and the root is where the person who commissioned the work is
/// reading. It is the same emergency exit nxf 6j6v.am8j takes, and the sameness is wanted — a
/// second mechanism for "the machine will not decide this" is how two of them come to behave
/// differently.
///
/// Best-effort. A message that could not be posted is a warning and not a failure: the resume has
/// already decided not to start anything, and that decision stands whether or not the sentence
/// explaining it arrived.
fn tell_the_root_thread(
    ctx: &Ctx,
    store: &mut ChatStore,
    hold: &crate::interruption::Interruption,
    thread: Option<&str>,
    body: &str,
    warnings: &mut Vec<FailedConsequence>,
) {
    let _ = hold;
    let Some(thread) = thread else { return };
    let root = match store.thread_root(thread) {
        Ok(root) => root,
        Err(e) => {
            warnings.push(FailedConsequence::step_unanswered(
                Some(thread),
                format!("the working copy moved under a hold and the operation's root could not be resolved to ask about it: {e}"),
            ));
            return;
        }
    };
    let channel = store
        .thread_quorum(&root, ctx.now)
        .ok()
        .flatten()
        .and_then(|q| q.channel_id);
    let Some(channel) = channel else {
        warnings.push(FailedConsequence::step_unanswered(
            Some(&root),
            "the working copy moved under a hold and the operation's root names no channel to ask in"
                .to_string(),
        ));
        return;
    };
    if let Err(e) = facade::send(
        store,
        facade::SendRequest {
            now: ctx.now,
            origin: ctx.origin,
            actor: ctx.actor,
            channel: &channel,
            body,
            kind: MessageKind::Info,
            priority: Priority::Urgent,
            disposition: Disposition::InTurn,
            thread: Some(&root),
            refs: Refs::default(),
        },
    ) {
        warnings.push(FailedConsequence::step_unanswered(
            Some(&root),
            format!("the working copy moved under a hold and the question about it could not be posted: {e}"),
        ));
    }
}

/// **Secure the interrupted operation's uncommitted work and hand the checkout on** — the half of
/// the way back that cannot wait for the window to lift.
///
/// A weekly quota is up to a week, and an operation that holds this workspace's only working copy
/// for a week holds the workspace. So the tree is committed onto the operation's own park branch
/// and the lease goes to whoever is next; the resume brings it back through the path that already
/// exists ([`resume_parked_work`], which every trigger passes on its way through the lease gate),
/// and [`crate::park::Movement`] is what tells the returning session whether the base moved while it
/// was away.
///
/// The conditions are [`park_the_interrupted_tree`]'s, and what a refusal does is
/// [`park_and_hand_on`]'s rule: a permanent one hands the copy on unparked and says so, a transient
/// one holds the claim, shows on `nxc status` and is retried — by the TICK
/// ([`park_an_interrupted_holder`]) rather than by this verb, which runs twice per hold and could
/// not be the retry on its own.
///
/// Best-effort throughout: the hold is recorded and the return is armed whatever happens here. What
/// a failure of the store costs is a finding on this receipt and a park the next tick attempts
/// again — never the work and never the way back.
fn secure_the_interrupted_tree(
    ctx: &Ctx,
    store: &mut ChatStore,
    thread: Option<&str>,
    warnings: &mut Vec<FailedConsequence>,
) {
    let Some(thread) = thread else { return };
    if let Err(e) = park_the_interrupted_tree(ctx, store, thread, warnings) {
        let detail = format!("a session is on hold and its work could not be secured: {e}");
        eprintln!("warning: {detail}");
        warnings.push(FailedConsequence::work_not_parked(Some(thread), detail));
    }
}

/// **The availability-boundary occasion for one interrupted thread** — the conditions both of its
/// callers share, and the park (nxf 6j6v.npy3; shared with the tick since nxf 6j6v.8bv9).
///
/// **Two conditions, and each of them is a reason to do nothing rather than a failure:**
///
/// * the lease is not held by this operation at all — there is nothing of ours in that checkout;
/// * something in this chain is still writing — the guard that keeps a park from committing a tree
///   underneath a live process, and the reason this runs a grace after the announcement rather than
///   inside it.
///
/// What the CALLER has already established is the rest: the hold stands and is not due, its session
/// is not running, and its round is not answered — [`resume_interrupted`] by the order of its own
/// checks, [`park_an_interrupted_holder`] by asking them again. `Ok(None)` is "the occasion does not
/// stand"; `Ok(Some((holder, outcome)))` is what the park came to.
fn park_the_interrupted_tree(
    ctx: &Ctx,
    store: &mut ChatStore,
    thread: &str,
    warnings: &mut Vec<FailedConsequence>,
) -> Result<Option<(String, ParkOutcome)>> {
    let Some((holder, _)) = store.working_tree_lease_row()? else {
        return Ok(None);
    };
    let Some(scope) = WorkScope::parse(&holder) else {
        return Ok(None);
    };
    let claim_threads = store.work_scope_threads(&scope)?;
    // Somebody else's checkout: nothing of this operation's is in it, so there is nothing to secure
    // and nothing to hand on.
    if !claim_threads.iter().any(|t| t == thread) {
        return Ok(None);
    }
    // The guard a park may never be without. It is also why this runs a grace after the
    // announcement rather than inside it: the announcing process is alive while it speaks.
    if !sessions_still_running(ctx, store, &claim_threads)?.is_empty() {
        return Ok(None);
    }
    let why = format!(
        "operation {holder} stopped at an availability boundary and its window is not due yet, so \
         this workspace's working copy is to be handed on rather than held until it lifts"
    );
    let outcome = park_and_hand_on(
        ctx,
        store,
        &holder,
        HandOff::Released(&scope),
        &why,
        warnings,
        Some(thread),
        ParkOccasion::AvailabilityBoundary,
    )?;
    Ok(Some((holder, outcome)))
}

/// **The availability-boundary occasion, on the tick** (nxf 6j6v.8bv9) — so a park the resume
/// could not make is retried like every other refused park, without waiting for the next firing of
/// a job that fires twice per hold.
///
/// It asks what [`resume_interrupted`] asks before it secures a tree, in the same order: the hold
/// stands and its window is NOT due (a due one is the resume's to take up, not to park), no process
/// runs for its session, and its round is not already answered. Then
/// [`park_the_interrupted_tree`]'s own two conditions. And one of its own: **somebody is waiting**.
/// A copy nobody waits for is never handed on from the tick — the resume path secures one anyway,
/// because a week is a week, but the tick is a clock and not a policy, and it moves the copy only
/// for a commission that is standing still because of it.
///
/// Cheapest first: a workspace with nothing on hold pays one indexed read of an empty table.
///
/// **And when no hold of the CURRENT HOLDER is an occasion any more** — its window fallen, its
/// round answered, its session running again, or nobody waiting for the copy — a refusal this
/// occasion recorded is forgotten ([`forget_a_refusal_of_this_occasion`]), for the reason
/// [`park_the_stranded_holder`] forgets its own: a mark that says "retrying" is only true while
/// something is retrying.
///
/// **Whose occasion, asked of the holder's claim area and not of the workspace** (fix round 2 of
/// nxf 6j6v.8bv9). Holds are recorded per session, and a workspace can carry several at once: a
/// session interrupted in an operation that needs no working copy at all is on that list beside the
/// holder's own. Only a hold of a thread in the holder's claim area can ever park THIS checkout —
/// [`park_the_interrupted_tree`] refuses to act on any other — so only such a hold may keep the
/// holder's refusal alive. Deciding it from the store-wide list left a stale `PARK REFUSED` and its
/// once-a-minute retry standing on an operation whose own occasion had ended, for as long as
/// anybody anywhere was interrupted.
fn park_an_interrupted_holder(
    ctx: &Ctx,
    store: &mut ChatStore,
    warnings: &mut Vec<FailedConsequence>,
) -> Result<Option<ParkStep>> {
    let holds = store.standing_interruptions()?;
    if holds.is_empty() || store.peek_working_tree_queue()?.is_none() {
        forget_a_refusal_of_this_occasion(store, ParkOccasion::AvailabilityBoundary);
        return Ok(None);
    }
    // WHOSE occasion: the claim area of whoever holds the copy right now. Read once, here, rather
    // than inferred from the holds — see this function's doc for what deciding it store-wide cost.
    let Some((holder, _)) = store.working_tree_lease_row()? else {
        // Nobody holds the copy: no occasion to stand, and no row to forget either — the movement
        // that took the lease forgot it in the same transaction.
        return Ok(None);
    };
    let Some(scope) = WorkScope::parse(&holder) else {
        // A holder key this version cannot read is a reason to decide NOTHING about it — neither to
        // park nor to forget what it recorded. The sweep is the one place that says it out loud.
        return Ok(None);
    };
    let claim_threads = store.work_scope_threads(&scope)?;
    // Whether any hold OF THIS HOLDER is still an occasion at all, whatever the park then comes to
    // — the question a refusal this occasion recorded is retried on (fix round 1 of nxf 6j6v.8bv9).
    // It is set BEFORE the park is attempted, so the two conditions inside
    // [`park_the_interrupted_tree`] — the lease is not ours, something is still writing — leave the
    // row alone: the second is a guard against acting now, not the trouble passing.
    let mut an_occasion_stands = false;
    for hold in holds {
        // A window that has fallen due is the resume's to take up, an answered round is over, and a
        // session that is running again is not stopped at anything: none of the three is a park
        // waiting to happen, so none of them keeps a refusal "retrying".
        if hold.is_due(ctx.now) || ctx.worker.session_is_running(&hold.session) {
            continue;
        }
        let Some(thread) = store.session_thread(&hold.session)? else {
            continue;
        };
        // Somebody else's trouble: nothing of that operation is in this checkout, so its hold is
        // neither a park this tick could make nor a reason to keep the holder's refusal standing.
        if !claim_threads.iter().any(|t| t == &thread) {
            continue;
        }
        if round_is_discharged(ctx, store, &hold, Some(&thread))? {
            continue;
        }
        an_occasion_stands = true;
        // …and the holder it reports acting for, rather than the one read above, so what the
        // receipt names is what the park itself saw.
        let Some((parked_for, outcome)) = park_the_interrupted_tree(ctx, store, &thread, warnings)?
        else {
            continue;
        };
        let held = outcome.is_held();
        return Ok(Some(ParkStep {
            parked: None,
            handed_on: outcome.handed_on(&parked_for, ParkOccasion::AvailabilityBoundary),
            held,
        }));
    }
    if !an_occasion_stands {
        forget_a_refusal_of_this_occasion(store, ParkOccasion::AvailabilityBoundary);
    }
    Ok(None)
}

/// **The question that goes back to the root thread when the tree moved** — deterministic, so it is
/// testable without a repository and reads the same every time a person meets it.
///
/// It states the three things a person needs in order to answer, and nothing else: what was on hold
/// and why, what moved, and that nothing has been started. The decision itself is deliberately NOT
/// offered as a menu — the machine does not know whether the movement matters to this piece of work,
/// which is precisely why it is asking.
fn drift_question(
    hold: &crate::interruption::Interruption,
    thread: &str,
    drift: &crate::anchor::Drift,
) -> String {
    let mut out = format!(
        "The operation on thread {thread} stopped at {} because the model was not available to it \
         ({}), and it is being taken up again now. **The working copy has moved since then, so \
         nothing has been started.**\n\nWhat changed:\n",
        hold.at, hold.limit
    );
    if let Some(commit) = &drift.commit_now {
        out.push_str(&format!(
            "  - HEAD is a different commit now: {commit}. The history the interrupted session was \
             working against is not what is checked out.\n"
        ));
    }
    if let Some(branch) = &drift.branch_now {
        out.push_str(&match branch.is_empty() {
            true => "  - the working copy is on a detached HEAD now.\n".to_string(),
            false => format!("  - the working copy is on branch {branch} now.\n"),
        });
    }
    if drift.uncommitted_now {
        out.push_str(
            "  - the commit is where it was and the uncommitted work is not: something has been \
             edited, added or removed in the tree since.\n",
        );
    }
    out.push_str(
        "\nWhat is NOT covered either way: ignored files — `.env`, local databases, `node_modules` \
         — are outside both the anchor and the park, so nothing here has looked at them.\n\n\
         Decide what should happen, then run `nxc resume --thread <the thread above>` to continue \
         with the session's own transcript, or take the work up yourself.",
    );
    out
}

/// **What the root thread is told when this runtime cannot continue a conversation it began** —
/// deterministic, like its two siblings and for their reason.
///
/// It says the one thing a person needs in order to decide, and it does not pretend there is a
/// button: nothing here can continue this session, so the choice is theirs — take the work up by
/// hand, or commission it again knowing what the interrupted turn may already have done.
fn provider_cannot_resume_notice(
    hold: &crate::interruption::Interruption,
    thread: Option<&str>,
) -> String {
    let where_ = match thread {
        Some(t) => format!(" on thread {t}"),
        None => String::new(),
    };
    format!(
        "The operation{where_} stopped at {at} because the model was not available to it ({limit}: \
         {detail}), and **it cannot be taken up automatically**: this workspace's runtime does not \
         continue a conversation it began.\n\n\
         Nothing has been started, and nothing will be. Continuing would mean opening a FRESH \
         session with none of that one's history — so it would not see the work it had already \
         done, and would be free to do it again. Whether that is worth it for this piece of work is \
         a judgement, and not one the machine should make for you.\n\n\
         The hold is closed, so nothing will keep offering to resume it. What the session managed \
         before it stopped is still readable with `nxc transcript show {session}`. Take the work up \
         yourself, or commission it again.",
        at = hold.at,
        limit = hold.limit,
        detail = hold.detail,
        session = hold.session,
    )
}

/// **What the continued session is told** — deterministic, like [`crate::park::resume_notice`] and
/// [`crate::collecting::compose_collected_wake`], and for their reason: a text that varies is a text
/// nobody can test and every reader has to re-read.
///
/// It says three things and each one is load-bearing:
///
/// 1. **What happened** — so the session does not have to work out from a gap in its own transcript
///    why it is being spoken to again.
/// 2. **That its own history is in front of it.** This is the whole safety argument of continuing
///    rather than restarting: the transcript carries every tool call WITH its result, so a session
///    that already ran `nxf create` can see the id it got back and will not create the ticket twice.
/// 3. **Check the world, do not trust the last intention.** The one place the transcript cannot
///    protect it: if the boundary fell between a `tool_use` and its `tool_result`, the record shows
///    a call with no answer, and the obvious move is to make it again. For a side-effecting verb
///    that is exactly the wrong move, and it is cheap to avoid — the thread, the board and the
///    repository can all simply be looked at.
fn continuation_message(
    hold: &crate::interruption::Interruption,
    role: &str,
    thread: Option<&str>,
) -> String {
    let where_ = match thread {
        Some(t) => format!(" on thread {t}"),
        None => String::new(),
    };
    format!(
        "Your session was interrupted at {at} — not by anything you did, and not by anything that \
         broke. The model was not available to you for a while ({limit}: {detail}). It is available \
         again, so you are continuing{where_}.\n\n\
         **You are continuing WITH your own transcript, not starting over.** Everything you did \
         before the interruption is in front of you, including every tool call and what it \
         returned. Do not redo work you can see you already did.\n\n\
         **Before you act, CHECK THE WORLD rather than trusting your last intention.** The \
         interruption can have fallen between a command and its result, so the last thing you see \
         may be a call whose answer never arrived — and it may well have taken effect. Look, do not \
         assume: has the thread already been answered, does the ticket already exist, is the commit \
         already there, was the message already sent? Verifying costs one command; doing it twice \
         costs a duplicate.\n\n\
         Your working copy may also have been handed to another operation while you waited and \
         given back. If your own work was secured on a parked branch, you are told so separately, \
         along with whether the base moved.\n\n\
         Then carry on as {role} and finish the turn the way you always do.",
        at = hold.at,
        limit = hold.limit,
        detail = hold.detail,
    )
}

/// Re-check one channel board's deadline and route it if it is due (`nxc tick --thread <id>`).
#[derive(Debug, Clone)]
pub struct TickRequest<'a> {
    /// The thread whose board to re-check. Keyed on the THREAD, and on nothing above it: a tick
    /// resolves everything it needs from the thread itself.
    pub thread_id: &'a str,
}

/// What one tick decided. Declared field order = the JSON contract.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct TickReceipt {
    pub thread_id: String,
    /// `true` iff this tick actually ran the channel's `on_complete` routing.
    ///
    /// **`false` is not "nothing happened"** since nxf 6j6v.rs9k: a tick that found an ordered
    /// flow's step lapsed STARTS THE NEXT STEP and routes no completion, which is `false` here and
    /// `advanced` in [`reason`](TickReceipt::reason). That is the one `false` that is not a no-op,
    /// and the reason a caller reads the two fields together rather than this one alone.
    pub acted: bool,
    /// Why — `acted`, `advanced` (nxf 6j6v.rs9k: an ordered flow's step let its window run out, so
    /// the flow moved on instead of ending — [`warnings`](TickReceipt::warnings) names the step that
    /// stayed silent and the one started for it), or which no-op case applied (`not_due`,
    /// `not_a_declared_channel`, `already_handled`, `no_return_address`).
    pub reason: String,
    /// What the routing delivered, when it acted at all.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub delivered: Option<String>,
    /// The requester session this tick's routing woke, if any — [`ReplyReceipt::woke`] for the PULL
    /// path, and reported for the same reason: a wake is a fire-and-forget trigger that leaves no
    /// trace in the store, so a caller cannot re-derive it from any read. `None` when there was
    /// nothing to wake (`summarize` phase 1 spawns the synthesizer instead) OR when a wake was
    /// attempted and did not land — which [`wake_skipped`](TickReceipt::wake_skipped) is what
    /// distinguishes.
    ///
    /// It belongs on THIS receipt and not only on `reply`'s because `acted: true` says the routing
    /// ran, never that the hand-off arrived — and a tick is precisely the recovery path a caller
    /// reaches for when it suspects an earlier hand-off did not land.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub woke: Option<String>,
    /// The completion wake that was ATTEMPTED and did not land — [`ReplyReceipt::wake_skipped`]'s
    /// twin, on the same routing and under the same "skip, don't fail" contract (nxf 6j6v.bxdd).
    ///
    /// This verb runs [`route_declared_channel_completion`] exactly as [`reply`] does and used to
    /// DISCARD its findings, so a tick reported `acted: true` while the requester was never woken
    /// and the only trace was a stderr breadcrumb (PR #265 review, Integrity & Robustness #1). That
    /// is the wrong seam to lose it on twice over: a scheduled timer runs this verb unattended, with
    /// nobody reading that terminal, and an embedding app calling it never sees the host process's
    /// stderr at all.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub wake_skipped: Option<WakeSkipped>,
    /// **The requester was working, so the routed answer is HELD for it** (nxf 6j6v.gn8b) — the
    /// third outcome, reported here for [`woke`](TickReceipt::woke)'s reason: this verb runs
    /// unattended, and a hold that appears nowhere is indistinguishable from a wake that was lost.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub held: Option<String>,
    /// **Everything this tick should have caused and did not** — [`ReplyReceipt::warnings`]'s twin
    /// (nxf 6j6v.93zd), the PULL seam's half of the one defined place. Always present, empty when
    /// nothing failed, and it carries the findings the two `Option`s above have no room for: a
    /// consolidation that could not start, a run handed no verdict to move on.
    ///
    /// It matters more here than on `reply`, not less: a scheduled timer runs this verb unattended,
    /// so there is no session standing by to read a breadcrumb at all.
    pub warnings: Vec<FailedConsequence>,
    /// The expected handles that had not replied at the moment this tick decided — reported even
    /// for a no-op, so a caller can tell WHO is missing without a second read.
    pub outstanding: Vec<String>,
    /// An expired working-tree lease this tick reclaimed, and who it started (nxf 6j6v.fabb).
    ///
    /// **Not about this thread**, unlike every field above it: the lease is the WORKSPACE's, one
    /// row in its own `.nxs/db.sqlite` and never synced (see `working_tree.rs` for why it is not in
    /// the op log), and this verb is the only hand this house's clock has. Absent — and omitted
    /// from the JSON entirely — whenever there was nothing to sweep, which is every ordinary
    /// tick.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub working_tree: Option<WorkingTreeSweep>,
    /// **An operation whose work this tick parked, and who it started** (nxf 6j6v.de9s).
    ///
    /// [`working_tree`](TickReceipt::working_tree)'s sibling and its neighbour in every sense: not
    /// about this thread, one row in this device's own db, and absent from the JSON entirely on
    /// every ordinary tick. What separates them is which clock ran out — a lease's bound with
    /// nobody behind it any more, or an escalation's park deadline with somebody waiting — and what
    /// happened to the tree: a sweep reclaims a checkout, a park SAVES what was in it first.
    ///
    /// A park that was DUE and refused is not here. A refusal that can pass is a
    /// [`ConsequenceClass::WorkNotParked`] finding in [`warnings`](TickReceipt::warnings), because a
    /// refusal is not a park and reporting it as one would be the silent-failure shape this receipt
    /// exists to close; a refusal that cannot pass moved the copy anyway, and is
    /// [`handed_on`](TickReceipt::handed_on).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parked: Option<ParkedOperation>,
    /// **Every other hand-off this tick's park step made** (nxf 6j6v.8bv9): a stranded escalation
    /// whose park was refused for good and whose copy went on UNPARKED, and an operation on hold at
    /// an availability boundary whose copy went on — parked or not — because somebody was waiting.
    ///
    /// [`parked`](TickReceipt::parked)'s sibling, and never set beside it: one tick's park step acts
    /// on at most one occasion. Absent from the JSON on every tick that moved nothing.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub handed_on: Option<HandedOn>,
}

/// One commission that was taken back before it ever started (nxf 6j6v.0h3p). Declared field order =
/// the JSON contract.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct WithdrawnCommission {
    /// The thread that was waiting for it, now discharged and carrying a message that says so.
    pub thread: String,
    /// The role that would have been started.
    pub role: String,
    /// The internal session that was minted for it and never ran.
    pub session: String,
}

/// One RUNNING session that a withdrawal asked to stop (nxf 6j6v.b9nf) — [`WithdrawnCommission`]'s
/// twin for the round that had started. Declared field order = the JSON contract.
///
/// "Stopped" is the request DELIVERED, not the process gone: [`Worker::stop_session`](crate::
/// worker::Worker::stop_session) returns once the signal is sent, and the session's own teardown
/// runs after that. A stop that could not even be delivered is still listed here — its thread is
/// discharged all the same — and named on [`WithdrawReceipt::warnings`] as
/// [`ConsequenceClass::SessionNotStopped`].
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct StoppedSession {
    /// The thread the session stood in, now discharged and carrying a message that says so.
    pub thread: String,
    /// The role it was running as.
    pub role: String,
    /// The internal session that was asked to stop.
    pub session: String,
    /// **Nothing had to be signalled, because the session was already over** (nxf 6j6v.b9nf, fix
    /// round 3 of that item's review, Code Quality #6) — the worker's own sentence saying what it
    /// found ([`SessionStop::NothingToStop`](crate::worker::SessionStop::NothingToStop)), and
    /// `None` when the stop was actually delivered.
    ///
    /// It is a NOTE and not a warning, which is the whole of the fix: a round that ends on its own
    /// between this call's liveness read and its signal is the ordinary race here and lands on the
    /// state the caller asked for. Reported as a failure it printed "the process is still there;
    /// stop it by hand" about a process that had gone, and exited 1 on success.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub already_gone: Option<String>,
}

/// What [`withdraw`] took back.
///
/// `#[non_exhaustive]` since nxf 6j6v.b9nf, which is the item that added the running case and so the
/// one that learned this receipt grows: a host reads these fields, and a literal it can no longer
/// write costs it nothing, while a source break at every future fact about a withdrawal costs it a
/// release.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
#[non_exhaustive]
pub struct WithdrawReceipt {
    /// The thread the caller named — since nxf 6j6v.ezbr always its operation's FIRST thread, and
    /// the root of the area that was searched.
    pub thread_id: String,
    /// What was withdrawn before it started, in queue order. Empty when the area held nothing
    /// queued — and then [`stopped`](Self::stopped) is not: a call that finds nothing waiting AND
    /// nothing running is a `not_found`, so a caller never has to tell "I took something back"
    /// from "there was nothing there" by inspecting two arrays' lengths.
    pub withdrawn: Vec<WithdrawnCommission>,
    /// Entries that were in the queue when this call looked and gone when it reached them — the
    /// release path took them in between, so they are RUNNING now and were deliberately not touched.
    /// Empty is the ordinary case.
    pub started_meanwhile: Vec<String>,
    /// **The running sessions this call discharged and asked to stop** (nxf 6j6v.b9nf), in the
    /// area's thread order. Omitted from the JSON when there were none, which is every withdrawal
    /// of a commission that had not started.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub stopped: Vec<StoppedSession>,
    /// **Whether the withdrawn round's work is going to be PARKED** (nxf 6j6v.b9nf): `true` when a
    /// stopped session's operation holds this workspace's working copy, so the background service
    /// will commit whatever it left uncommitted onto a branch once its processes are gone and hand
    /// the copy on. `false` for a round that holds no working copy — a shared persona, a host that
    /// takes no lease — where there is nothing of it in the checkout to save.
    ///
    /// A bool and not an option, because it is an answer either way: a caller that took a running
    /// round back needs to know whether to expect a branch.
    pub will_park: bool,
    /// **Why there will be NO branch although the round DOES hold the working copy** (fix round 2
    /// of this item's review, Code Quality #1) — the third state, which `will_park` alone cannot
    /// say. `false` used to mean one thing ("nothing of it is in this checkout") and now covers two,
    /// so the second one carries its reason: the permanent refusal a park of this work would meet —
    /// a host that names no working copy, a directory that is not a git repository, an operation
    /// with no recorded base ([`ParkRefusal::is_permanent`]). The copy is still handed on once
    /// nothing in the operation is running; it is handed on UNPARKED, and the tick says so.
    ///
    /// `None` for both of the other two states, so a reader branches on the pair rather than on a
    /// sentence: `will_park` true is a branch, `will_park` false with `None` here is a round that
    /// holds nothing, and `Some(_)` is work in the checkout that cannot be saved on this host.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub cannot_park: Option<String>,
    /// **Everything this call should have caused and did not** (nxf 6j6v.93zd's one defined place,
    /// on this receipt since nxf 6j6v.b9nf): a stop that did not land
    /// ([`ConsequenceClass::SessionNotStopped`]), a tick that could not be armed for the park
    /// ([`ConsequenceClass::TickUnscheduled`]). Omitted from the JSON when empty, like the field it
    /// arrived with.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub warnings: Vec<FailedConsequence>,
}

/// **Take back a commission — one still waiting for the working copy, or a round that is RUNNING**
/// (`nxc withdraw`, nxf 6j6v.0h3p; the running case since nxf 6j6v.b9nf).
///
/// **Whose verb it is** (nxf 6j6v.ezbr — the owner's decision 6j6v.s8gf of 2026-09-20): a human's,
/// or an assistant's that a human started, and only the caller who ran the operation's FIRST
/// `send`, naming that thread. A session this workspace started is refused whatever it names, a
/// caller who did not open the operation is told who did, and a member thread is refused with the
/// operation's first thread named instead — all before anything changes. The owner's decision of
/// 2026-09-17 made `withdraw` "the ONE verb a human or an agent has to take a commission back"; the
/// verb is still the one, and the agent half of that sentence is what 2026-09-20 took back. An
/// agent that wants a round stopped escalates.
///
/// Two cases, one verb, and they differ in what taking back costs:
///
/// - **A commission still parked in the working-tree queue** has no session, no transcript and no
///   model call behind it. Withdrawing it loses nothing, because nothing has happened yet.
/// - **A round whose session is RUNNING** has work in flight. Withdrawing it means three things
///   in this order: the thread's debt is discharged (the register says the round is over), the
///   session is asked to stop ([`Worker::stop_session`](crate::worker::Worker::stop_session)),
///   and — when the round holds this workspace's working copy — whatever it leaves uncommitted is
///   **parked, never rolled back**: the background tick commits it onto a branch once nothing in
///   the claim area is running any more, and hands the copy on ([`park_a_withdrawn_holder`]).
///   Nothing on this path runs `git reset`, `git checkout -- .` or `git clean`.
///
/// **The whole call is refused before anything changes when a running session cannot be stopped**
/// ([`Worker::stops_sessions`](crate::worker::Worker::stops_sessions) is `false`): a withdrawal
/// that discharged the register and left the session writing would be the two-agents-one-checkout
/// failure this whole seam exists to prevent, wearing a receipt that says the round is over. A
/// stop that IS supported and then does not land is different — the discharge stood before the
/// attempt — and is a [`ConsequenceClass::SessionNotStopped`] finding on the receipt naming the
/// session, not a failure of the call.
///
/// **The queue removal IS the precondition check for the queued case**, which is what makes it
/// safe without a lock: [`ChatStore::remove_working_tree_queue_entry`] deletes by id and reports
/// whether the row was still there. A `false` means the release path popped that entry between
/// this call's read and its write — the trigger has been fired, a session is running, and it is
/// reported on [`WithdrawReceipt::started_meanwhile`] and left strictly alone. (Such a session is
/// not on [`stopped`](WithdrawReceipt::stopped) either: the running list was read before the
/// queue loop, so a session that started in between is nobody's to stop in this call — the next
/// call finds it running.)
///
/// That primitive is what the queued case's safety argument rests on, and it is tested:
/// `working_tree::tests::removing_an_entry_that_is_already_gone_reports_false_rather_than_failing`.
/// **The COMPOSED branch here — a `false` becoming a `started_meanwhile` — has no deterministic
/// test, and that is a named gap** (independent review of that branch, Test Quality/High). Reaching
/// it needs the release path to fire between this call's list read and its removal, which is a real
/// race and not a state a single-threaded test can construct. Left as a gap on purpose, and it
/// fails SAFE: the branch's whole behaviour is to skip and report.
///
/// **What the thread is left as**, in both cases. Each withdrawn thread is discharged the way every
/// other ended thread is: `expects_reply_from` is retargeted to the reserved
/// [`crate::channel::WITHDRAWN_HANDLE`] identity and satisfied immediately by a real posted message
/// naming who withdrew it — and, for a running round, what becomes of its work. So the board reads
/// `complete: true`, stays visible on every PULL surface, and the message is the record.
///
/// **The way back for parked work** is the way back every park has ([`resume_parked_work`]): the
/// next commission into the SAME claim area — a `reply --thread` into the withdrawn thread on a
/// direct persona thread, a follow-up into the channel thread for a round — puts the tree back on
/// the park branch and tells the session where its work is. `nxc status` lists the branch under
/// the operation until then. A fresh `send` opens a new claim and does not find it.
///
/// **A withdrawal INTERRUPTS the chain below the thread it names** (nxf 6j6v.s2cj — the owner's
/// decision 6j6v.ymvg of 2026-09-20: a taken-back step does not commission its successor). Every
/// thread between what was taken back and the operation's first thread that is still waiting — a
/// channel thread owing its supervisor's answer, a persona thread waiting on the round below it —
/// is discharged onto the withdrawn identity too ([`interrupt_the_chain_above`]). So neither shape
/// of an ordered channel goes on after the park: not to the next step, and not to the step that was
/// taken back. It is the opposite of a consolidation: nothing is delivered and nobody is woken; the
/// register says there is no round left. (Until that decision this verb deliberately did NOT touch
/// the round above, and discharged it only when EVERY commission of its current pass was taken back
/// — nxf 6j6v.7me0. A round with an answered step and a withdrawn one went on.)
///
/// Rejection: a thread this workspace does not know, or an area with nothing waiting and nothing
/// running in it, is `not_found` naming what was looked for. Where the worker cannot answer the
/// liveness question at all ([`Worker::answers_liveness`](crate::worker::Worker::answers_liveness)
/// is `false`) and the area holds sessions that never reported an end, it is refused BY NAME
/// instead: "nothing is running" would be a fact this call never established.
pub fn withdraw(ctx: &Ctx, store: &mut ChatStore, thread_id: &str) -> Result<WithdrawReceipt> {
    // **WHO may take it back** (nxf 6j6v.ezbr — the owner's decision 6j6v.s8gf of 2026-09-20).
    // Four questions, each a refusal before anything changes, in the order below:
    //
    // 1. Is the caller a session this workspace STARTED? Then no, whatever it names — see
    //    [`refuse_a_session_this_workspace_started`] for what this can and cannot tell.
    // 2. May the caller READ the board? The bar until this item (independent review of the queued
    //    case's branch, Integrity/Medium: a thread id used to be the whole credential). It stays,
    //    first of the three thread questions, for one reason: the refusal below names who opened
    //    the operation, and a caller who cannot even read the thread is not told that.
    // 3. Did the caller OPEN the operation — run its first `send`? That is the bar now, and it
    //    implies 2: an operation's opener reads every thread in it.
    // 4. Is the thread it names the operation's FIRST one? A withdrawal takes back that commission
    //    and interrupts the chain below it; a member thread is refused and the root is named.
    //
    // None of this is access control — this surface has none, and building it is nxf 6j6v.6aza.
    // The caller's identity is still the one it presents; what the session map adds is the one
    // thing it can PROVE, that a presented session is one this workspace started.
    refuse_a_session_this_workspace_started(ctx, store)?;
    let channel = store
        .thread_channel(thread_id)
        .or_else(|| store.thread_channel_via_message(thread_id))
        .ok_or_else(|| NxfError::not_found(format!("no such thread: {thread_id}")))?;
    let policy = crate::channel::declared_policy(ctx.defs.channels(), Some(&channel));
    let caller = ctx.caller_handle();
    facade::require_thread_readable(store, &channel, thread_id, &caller, &policy)?;
    let root = store.thread_root(thread_id)?;
    if !facade::opened_the_operation(store, thread_id, &caller)? {
        let opened_by = match store.thread_opener(&root)? {
            Some(opener) => format!("{opener} did, with the `nxc send` that began it"),
            // `thread_root` ends the walk at a parent this workspace has not folded yet, and that
            // parent has no row — so its opener is not unknown to the caller alone, it is not HERE.
            None => format!(
                "its first thread, {root}, has not arrived in this workspace yet, so who did \
                 cannot be established here"
            ),
        };
        return Err(NxfError::forbidden(format!(
            "{caller} did not open operation {root} — {opened_by}. Only the caller who sent an \
             operation's first commission may take it back; nothing was withdrawn"
        )));
    }
    if root != thread_id {
        return Err(NxfError::validation(format!(
            "thread {thread_id} is not where operation {root} began, and a withdrawal names the \
             initial `send`: `nxc withdraw --thread {root}` takes that commission back and \
             interrupts the chain below it, this thread included; nothing was withdrawn"
        )));
    }

    // The AREA, not the one thread: `send --to <channel>` hands its caller the CHANNEL thread, while
    // the trigger that is actually parked hangs on a member thread below it. A caller withdrawing
    // "the round I just commissioned" names what it was given.
    let area = store.thread_subtree(thread_id)?;
    let parked: Vec<_> = store
        .list_working_tree_queue()?
        .into_iter()
        .filter(|q| {
            q.thread
                .as_deref()
                .is_some_and(|t| area.iter().any(|in_area| in_area == t))
        })
        .collect();
    // **The running half** (nxf 6j6v.b9nf): every unended session in the area that the worker says
    // has a live process — the same two reads, in the same order, as `sessions_still_running`.
    let running = sessions_running_under(ctx, store, &area)?;
    if parked.is_empty() && running.is_empty() {
        // **A worker that cannot LOOK does not get to say nothing is running** (fix round 3 of this
        // item's review, Code Quality #7 (a)). `running` is empty for two different reasons: the
        // worker looked and found nothing, or the worker cannot look at all — a custom worker
        // without `session_is_running`, or a build on a platform with no liveness question
        // ([`Worker::answers_liveness`]). In the second case the by-name `stops_sessions` refusal
        // below is unreachable, and a genuinely running round would read as "there is nothing to
        // withdraw" — a statement of fact about processes nobody asked about, on the one surface a
        // person uses to clear up a round they can see is going.
        //
        // So the refusal here NAMES what is not established, rather than claiming its opposite. It
        // is a `validation` and not a `not_found` for the same reason the `stops_sessions` refusal
        // is: the thread is there, the call is well formed, and what is missing is a capability of
        // this host.
        if !ctx.worker.answers_liveness() {
            let unended: Vec<String> = unended_sessions_under(store, &area)?
                .into_iter()
                .map(|(_, session)| session)
                .collect();
            if !unended.is_empty() {
                return Err(NxfError::validation(format!(
                    "this host cannot tell whether a session is running; nothing was withdrawn — \
                     no commission is queued behind the working copy under thread {thread_id}, and \
                     session(s) {} there have never reported an end, but this workspace's chat \
                     worker does not answer the liveness question. Whether they are still writing \
                     cannot be established here, and this call will not assume it — implement \
                     `Worker::session_is_running` on this host, or end the session by hand and \
                     withdraw the queue",
                    unended.join(", ")
                )));
            }
        }
        // Said differently depending on what was actually asked: a worker that cannot look never
        // established that nothing has a live process, only that nothing is left open.
        let nothing_running = if ctx.worker.answers_liveness() {
            "no session there has a live process"
        } else {
            "every session recorded there has reported its end"
        };
        return Err(NxfError::not_found(format!(
            "nothing under thread {thread_id} is waiting or running: no commission is queued \
             behind the working copy and {nothing_running}, so there is nothing to withdraw"
        )));
    }
    // **REFUSED WHOLE, before anything changes.** Asked here, after both reads and before the
    // first write, so a host that cannot stop a session gets a refusal and an unchanged workspace
    // rather than a queue half taken back and a session still writing.
    if !running.is_empty() && !ctx.worker.stops_sessions() {
        return Err(NxfError::validation(format!(
            "this host cannot stop a running session; nothing was withdrawn — session(s) {} under \
             thread {thread_id} have a live process, and this workspace's chat worker does not \
             stop sessions it started, so taking the round back would leave it writing into the \
             working copy",
            running
                .iter()
                .map(|s| s.session.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        )));
    }
    // **Does the withdrawn round hold the working copy?** The lease ROW, expired or not — an
    // expired row is still a claim the tick's occasions act on — and its claim area against the
    // threads the running sessions stand in. When it does, the work is the tick's to park.
    let holder = match store.working_tree_lease_row()? {
        Some((key, _)) => WorkScope::parse(&key).map(|scope| (key, scope)),
        None => None,
    };
    // The claim area itself, not only the answer derived from it: which thread of the withdrawn
    // round holds the copy is a PER-THREAD fact the discharge below has to tell each thread
    // truthfully (fix round 2 of this item's review, Minor #5).
    let claim = match &holder {
        Some((_, scope)) if !running.is_empty() => store.work_scope_threads(scope)?,
        _ => Vec::new(),
    };
    // **Whether anything of the withdrawn round is in the checkout at all** — the question the
    // marker turns on, and the one that decides which threads may be told anything about a park.
    let holds_the_copy = running.iter().any(|s| claim.contains(&s.thread));
    // **…and whether a park of it would actually PRODUCE a branch** (fix round 2 of this item's
    // review, Code Quality #1). Until this round `will_park` was the line above and nothing else, so
    // it promised a branch for every host that holds the copy — including the three that can never
    // deliver one, which are exactly the PERMANENT refusals [`attempt_the_park`] opens with. On the
    // commonest host of all (a worker that names no working copy, which is every `Worker` but the
    // sidecar) the promise was simply false, and the truth appeared only in the unattended tick's
    // warning, hours later, to nobody.
    //
    // The three checks are asked here BY THE SAME FUNCTIONS the park asks them with, and all three
    // are reads — `Worker::working_copy`, one `git rev-parse --git-dir`, one indexed store read —
    // so this changes nothing about the rule that this verb's refusal comes before its first write.
    let cannot_park = if holds_the_copy {
        match &holder {
            Some((key, _)) => a_park_here_would_not_produce_a_branch(ctx, store, key),
            None => None,
        }
    } else {
        None
    };
    let will_park = holds_the_copy && cannot_park.is_none();

    let withdrawn_by = ctx.caller_handle();
    let withdrawn_qualified = format!("{}/{}", ctx.origin, crate::channel::WITHDRAWN_HANDLE);

    // **The marker, and the clock that comes back for it** (nxf 6j6v.b9nf) — written BEFORE this
    // call discharges ANYTHING, and the order is the whole of the guard (fix rounds 1 and 2 of this
    // item's review).
    //
    // The one state the marker exists for is an area that owes nothing while its work is still in
    // the tree, which is exactly what the two discharge loops below produce; and the stopped session
    // is a separate PROCESS, which can complete an in-flight `nxc reply` in any window this call
    // leaves open. That reply ends in `release_working_tree_if_scope_is_done`, which releases on
    // "nothing outstanding in the area" — so every write that reduces what the area owes has to
    // happen with the guard already standing. BOTH loops do: the queued one discharges the threads
    // of commissions that never started, and a queued thread inside the holder's claim area is
    // exactly what keeps that release declining until this call takes it back. Round 1 of the review
    // hoisted this above the running loop and left the queued loop above it, which is the same
    // window one write earlier.
    //
    // **What the order costs, and it is the trade already accepted here**: a store error in either
    // loop now returns with a marker standing for a claim whose round was not fully taken back. The
    // holder then declines every release until the tick's withdrawn occasion parks it — a park the
    // round may not have needed, and `nxc status` names the operation either way. That is the same
    // direction the rest of this path takes: a park costs a branch, an unguarded release costs the
    // work.
    // **Written on `holds_the_copy`, not on `will_park`** (fix round 2 of this item's review): the
    // guard is about what is IN THE TREE, and a round whose park is permanently refused has left
    // exactly as much in it as one whose park will succeed. What differs is only what becomes of it
    // — a branch, or a loud unparked hand-on — and both of those are the tick's, reached through
    // this marker. Gating the marker on the promise of a branch would leave the commonest host of
    // all (no working copy named) with no guard at all on the one path that stops a discharged area
    // releasing the copy from under a process that is still shutting down.
    let mut warnings: Vec<FailedConsequence> = Vec::new();
    if holds_the_copy {
        if let Some((key, scope)) = &holder {
            store.note_withdrawn_holder(key, &withdrawn_by, ctx.now)?;
            // …and WHICH of its sessions this call is about to stop (nxf 6j6v.27b9): the only
            // ones the tick may ever send a further SIGTERM to. Written with the marker, before
            // the stops below, so no tick can find the marker without them.
            let stopping: Vec<String> = running
                .iter()
                .filter(|s| claim.contains(&s.thread))
                .map(|s| s.session.clone())
                .collect();
            store.note_withdrawn_sessions(key, &stopping, ctx.now)?;
            if let Some(finding) = arm_a_look_at_the_withdrawn_holder(ctx, store, scope) {
                warnings.push(finding);
            }
        }
    }

    let (mut withdrawn, mut started_meanwhile) = (Vec::new(), Vec::new());
    for entry in parked {
        let thread = entry.thread.clone().unwrap_or_default();
        // The ATOMIC step, and the whole precondition: gone already ⇒ it is running ⇒ hands off.
        if !store.remove_working_tree_queue_entry(entry.id)? {
            started_meanwhile.push(thread);
            continue;
        }
        discharge_a_withdrawn_thread(
            ctx,
            store,
            &thread,
            &withdrawn_qualified,
            &format!(
                "[withdrawn by {withdrawn_by}] this commission for {} was waiting for the working \
                 copy and never started — no session ran and nothing was written",
                entry.role
            ),
            None,
        )?;
        withdrawn.push(WithdrawnCommission {
            thread,
            role: entry.role,
            session: entry.session,
        });
    }

    // **The running round: discharge, then stop** (nxf 6j6v.b9nf), in that order on purpose. The
    // register saying the round is over is the part a person reads and the part every other path
    // decides on; the stop is a request into a process that answers in its own time. A stop that
    // does not land leaves a discharged thread and a named finding, never an undischarged thread
    // and a stopped session.
    let mut stopped: Vec<StoppedSession> = Vec::new();
    let mut discharged: Vec<String> = Vec::new();
    for session in &running {
        if !discharged.contains(&session.thread) {
            // **Per THREAD, not per call** (fix round 2 of this item's review, Minor #5).
            // `will_park` answers for the whole withdrawal — *something* in it holds the copy — and
            // this sentence is read by ONE session, which may not be in that claim at all. The test
            // is therefore the thread's own: is it inside the claim area that holds the copy? Then
            // the park is its operation's park, the branch is listed under that operation, and the
            // next commission into this thread comes back onto it, because a trigger anywhere in an
            // operation resolves to the same claim key ([`resume_parked_work`]). If it is not, the
            // withdrawal parks something, but nothing of THIS thread's, and saying otherwise would
            // send a session looking for a branch that does not carry its work.
            //
            // The wait is named as the claim's, not as this session's: the park happens once
            // NOTHING in the area is running, which for a shared session beside the holder is a
            // different instant from its own process ending.
            //
            // **And a third sentence since fix round 2 of this item's review (Code Quality #1)**:
            // the thread is in the claim AND this host can never park it. This text is PERSISTED on
            // the board and read by whoever comes back to the round — promising it a branch that a
            // permanent refusal will never produce is the same false map on the durable surface
            // that `will_park` was on the receipt.
            //
            // **"Nothing of it is in the working copy" was itself a false map** (fix round 3 of
            // this item's review, Code Quality #7 (b)): a thread outside the claim held no LEASE,
            // but a SHARED persona takes none and may still have written into the workspace root
            // beside the holder — the claim area is about who OWNS the checkout, not about who
            // touched it. What is true is narrower: this thread's session held no lease, so nothing
            // of ITS was ever the tick's to park, and whatever it wrote is not rolled back — it
            // simply stays in the tree, wherever the holder's own park leaves that tree.
            let work = if !claim.contains(&session.thread) {
                "It held no lease of this workspace's working copy, so its work is not the tick's \
                 to park — whatever it wrote there stays in the tree"
                    .to_string()
            } else if let Some(why) = &cannot_park {
                format!(
                    "Whatever it left uncommitted in the working copy CANNOT be parked on a branch \
                     here ({why}), so the copy is handed on as it stands once nothing in this \
                     operation is running any more, with the work still in it and a warning saying \
                     so"
                )
            } else {
                "Whatever it left uncommitted in the working copy is parked on a branch by the \
                 background service once nothing in this operation is running any more; `nxc \
                 status` lists the branch under this operation, and the next commission into this \
                 thread brings it back"
                    .to_string()
            };
            discharge_a_withdrawn_thread(
                ctx,
                store,
                &session.thread,
                &withdrawn_qualified,
                &format!(
                    "[withdrawn by {withdrawn_by}] this commission for {} was running and was taken \
                     back — session {} was asked to stop. {work}",
                    session.role, session.session
                ),
                Some(&session.session),
            )?;
            discharged.push(session.thread.clone());
        }
    }

    // **A withdrawal INTERRUPTS the chain below the thread it names** (nxf 6j6v.s2cj — the owner's
    // decision 6j6v.ymvg of 2026-09-20: a taken-back step does not commission its successor).
    //
    // Every thread between something this call took back and the operation's first thread that is
    // still WAITING — a channel thread that owes its supervisor's answer, a persona thread whose
    // session is waiting on the round below it — is discharged onto the withdrawn identity too,
    // with a message of its own. That is what makes "the chain stops" true on every path at once,
    // because every path that could carry the chain on asks the same register first: the
    // supervisor opens a next step or consolidates only while a channel thread still expects IT
    // ([`supervisor_consider_set`]), and so does the tick ([`tick_move`]), whose consolidation step
    // treats the withdrawn identity as handled.
    //
    // **Measured before this was written, not reasoned** — the two channel shapes both carried on,
    // each by a path of its own. A `steps:` channel routed to the next step as soon as the park was
    // done. A `flow: sequential` one was thought safe, and was only on the `session ended` path:
    // the tick the withdrawal itself arms is keyed on the claim root — the CHANNEL THREAD — and it
    // parks first and reconsiders the board in the same call, found a pass that stopped short of
    // the withdrawn slot, and commissioned the taken-back step AGAIN.
    // `after_the_park_a_withdrawn_ordered_round_does_not_commission_the_next_step` is that run.
    //
    // **HERE — after every thread this call takes back is discharged, and before the first stop**
    // (review of PR #483, Integrity #2). Before the stops, because it is the last write that decides
    // whether the chain goes on, and a failure after a session was signalled used to leave that
    // session stopped under a chain that carried on at the next tick; now a failure here leaves
    // nothing signalled, and a retry finds every session still running and completes the call. After
    // the discharges, and not first, because ORDER is a fact `nxc status` reads: a member thread
    // whose discharge came after its round's reads `orphaned` — an answer nothing was done with —
    // which is exactly the false alarm that state is built never to raise. And it can no longer fail
    // on anything but the store: an ancestor this workspace has not folded an opener for is skipped
    // rather than refused.
    //
    // It is not the consolidation this verb's own doc refuses to drive, and it is the opposite of
    // one: nothing is delivered, nobody is woken, and the answers that were already given stay
    // where they were posted. (This replaced nxf 6j6v.7me0's narrower rule, which discharged the
    // named thread only when EVERY commission of its current pass had been taken back — a round with
    // one answered step and one withdrawn one was "partly withdrawn", and its supervisor still had a
    // job. Since the owner's decision it has none.)
    //
    // A queued commission that STARTED while this call ran (`started_meanwhile`) is inside a chain
    // that is interrupted all the same — the call was asked to take all of it back — and is reported
    // by name; the next call stops it.
    let taken_back: Vec<String> = withdrawn
        .iter()
        .map(|w| w.thread.clone())
        .chain(discharged.iter().cloned())
        .collect();
    interrupt_the_chain_above(ctx, store, thread_id, &taken_back, &withdrawn_qualified)?;

    for session in running {
        // **Three outcomes, and only one of them is a failure** (fix round 3 of this item's
        // review, Code Quality #6). A session that ended on its own between the liveness read above
        // and this signal — the ordinary race for a round that was about to finish — reaches the
        // state this call was asked for, and reporting it as a failure printed "the process is
        // still there; stop it by hand" about a process that had gone, and exited 1. It is a note
        // on the receipt instead. `Err` keeps its whole meaning: something may still be running.
        let mut session = session;
        match ctx.worker.stop_session(&session.session) {
            Ok(crate::worker::SessionStop::Requested) => {}
            Ok(crate::worker::SessionStop::NothingToStop(note)) => {
                session.already_gone = Some(note);
            }
            Err(e) => {
                let detail = format!(
                    "session {} (role {}) on thread {} was asked to stop and the request did not \
                     land: {e}. Its commission IS withdrawn — the thread owes nothing any more — \
                     but the process may still be there; stop it by hand. Whatever it leaves in \
                     the working copy is parked by the background service once it is gone",
                    session.session, session.role, session.thread
                );
                eprintln!("warning: {detail}");
                warnings.push(FailedConsequence::session_not_stopped(
                    &session.thread,
                    &session.session,
                    detail,
                ));
            }
        }
        stopped.push(session);
    }

    // **"Its work will be parked" is a promise about a TICK, so say when there is nothing to run
    // one** (nxf 6j6v.0j12's finding at a fourth verb; fix round 2 of this item's review,
    // Integrity #4). `send`, `reply` and `tick` all ask this question and this one did not — and it
    // is the verb with the most riding on the answer: while the marker stands EVERY other release
    // path declines by design, so with no background service the copy is held by a round that is
    // over, with nobody told and nothing coming. The `nxc withdraw` text names `nxc tick --thread
    // <id>` for exactly this reader.
    //
    // Asked on `holds_the_copy` rather than on `will_park`, for the reason the marker is written on
    // it: the unparked hand-on is a tick too. A withdrawal that left nothing in the checkout needs
    // no tick and gets no finding — the class is exempt from the exit code either way, and a
    // warning on every withdrawal of a shared persona is a warning readers learn to skip.
    if holds_the_copy {
        warnings.extend(service_finding(ctx, thread_id));
    }

    Ok(WithdrawReceipt {
        thread_id: thread_id.to_string(),
        withdrawn,
        started_meanwhile,
        stopped,
        will_park,
        cannot_park,
        warnings,
    })
}

/// **`withdraw` is not a verb for a session this workspace started** (nxf 6j6v.ezbr — the owner's
/// decision 6j6v.s8gf of 2026-09-20): not for the running case, not for the queued one, not for its
/// own round and not for anybody else's. It belongs to a person, or to an assistant a person
/// started — and an agent that wants a round stopped ESCALATES, which is the path that goes up to
/// whoever may decide.
///
/// **What this can tell, and nothing more.** The caller is refused when it NAMES a session the
/// session map knows (the refusal says "names", not "comes from": a hand-set `NXC_SESSION` naming a
/// real session is refused exactly the same way, and nothing here can tell the two apart) — [`Ctx::session`] naming a row that whoever spawned it wrote, the same record
/// [`Caller::resolve_actor`] and [`resolve_hop`] read instead of believing a claim. It is NOT
/// refused for merely looking like an agent: `NXC_ACTOR` is how a person at a terminal names
/// themself, and the process environment a spawned session carries is one a Bash-enabled role can
/// rewrite (the hop guard learned exactly that, nxf 6j6v.m48m). A session that clears its own
/// `NXC_SESSION` reads as a caller without one, and what stops it then is the next gate — it must
/// also be the one who sent the operation's first commission — and, past that, only that the work
/// is PARKED rather than lost and the act is on the record. The refusal therefore states what the
/// map says about THIS call and makes no claim about callers it cannot see.
///
/// A session id the map does not know — a hand-set `NXC_SESSION`, one from another workspace — is
/// not refused here, for [`Caller::resolve_actor`]'s reason: it names no session of ours.
fn refuse_a_session_this_workspace_started(ctx: &Ctx, store: &ChatStore) -> Result<()> {
    let Some(session) = ctx.session else {
        return Ok(());
    };
    let Some(role) = store.session_role(session)? else {
        return Ok(());
    };
    // Where to escalate: the thread this session stands in, which is the one its commissioner is
    // waiting on. A session that was never put in motion on a thread has none to name.
    let escalate = match store.session_thread(session)? {
        Some(thread) => format!("`nxc reply --thread {thread} --escalate -`"),
        None => "`nxc reply --thread <the thread you were commissioned in> --escalate -`".into(),
    };
    Err(NxfError::forbidden(format!(
        "withdraw is not a verb for a session this workspace started, and this call names one — \
         session {session}, started for {role}; nothing was withdrawn. Taking an operation back \
         belongs to the person who started it. If this round should stop, say so to whoever \
         commissioned you: {escalate} hands the question UP to whoever may decide"
    )))
}

/// **Every session under `threads` that is RUNNING, with what it runs as and where** (nxf
/// 6j6v.b9nf) — [`sessions_still_running`]'s two reads, kept in its order, answering the question
/// `withdraw` asks: not only *is anything running* but *what exactly*, because each one is stopped
/// by name and reported by name.
///
/// A session the map knows no role for is skipped with a breadcrumb rather than reported as a
/// blank: a row without a role is one this workspace never minted through the spawn funnel, and a
/// stop sent for it would be a signal about a process nobody here started.
fn sessions_running_under(
    ctx: &Ctx,
    store: &ChatStore,
    threads: &[String],
) -> Result<Vec<StoppedSession>> {
    let mut running = Vec::new();
    for (thread, internal) in unended_sessions_under(store, threads)? {
        if !ctx.worker.session_is_running(&internal) {
            continue;
        }
        let Some(role) = store.session_role(&internal)? else {
            eprintln!(
                "warning: session {internal} in thread {thread} has a live process and no role \
                 on record, so it is not this workspace's to stop and is left alone"
            );
            continue;
        };
        running.push(StoppedSession {
            thread,
            role,
            session: internal,
            already_gone: None,
        });
    }
    Ok(running)
}

/// **Every session under `threads` the store has no end for, with the thread it stands in** — the
/// candidate set [`sessions_running_under`] asks the worker about, named once because a second
/// reader now has to work from exactly the same set (fix round 3 of nxf 6j6v.b9nf's review, Code
/// Quality #7 (a)): the refusal [`withdraw`] raises when the worker CANNOT answer the liveness
/// question has to name the sessions it is refusing about, and naming a different set from the one
/// that would have been asked is how a refusal and the act it stands in for drift apart.
///
/// A store read and nothing else — no worker, no clock. "Unended" is the register's own fact: the
/// session announced no end, which is true of a session that is working and of one that died hard.
fn unended_sessions_under(store: &ChatStore, threads: &[String]) -> Result<Vec<(String, String)>> {
    let mut all = Vec::new();
    for thread in threads {
        for internal in store.unended_sessions_in_thread(thread)? {
            all.push((thread.clone(), internal));
        }
    }
    Ok(all)
}

/// **Discharge one withdrawn thread**: retarget its expectation onto the withdrawn identity and
/// satisfy it at once with a real posted message saying what happened — the one shape both cases
/// of [`withdraw`] leave a thread in, so they cannot drift apart in what a board reads afterwards.
///
/// Retargets as the thread's OWN opener — `set_expects` refuses anybody else, and the opener of a
/// supervised member thread is the supervisor, which is exactly who declared the expectation being
/// taken back.
///
/// **`return_address` is what makes the way back reachable for a stopped session** (nxf
/// 6j6v.b9nf). The follow-up that brings parked work back is the next commission into the same
/// thread, and on a direct persona thread that is the human's `reply --thread`, whose 1:1 fallback
/// resumes "the other side" — found by [`crate::surface`]'s walk for the newest message from
/// somebody else that carries a `refs.session_id`. An escalated coder left one on its escalation;
/// a coder stopped mid-turn before it ever spoke left NOTHING, so the follow-up would resume
/// nobody and the park would sit until somebody guessed the session id. The discharge message is
/// this round's last word, written in the engine's name for the session it stands in for, and
/// [`Refs::session_id`](crate::model::Refs::session_id) is the message's own provenance — so it
/// carries the stopped session, and the follow-up resumes exactly the session that was stopped,
/// with its transcript, onto its park branch. A queued commission's message carries none: no
/// session ever ran, and today's behaviour for that case is kept unchanged.
fn discharge_a_withdrawn_thread(
    ctx: &Ctx,
    store: &mut ChatStore,
    thread: &str,
    withdrawn_qualified: &str,
    body: &str,
    return_address: Option<&str>,
) -> Result<()> {
    let opener = store
        .thread_opener(thread)?
        .unwrap_or_else(|| ctx.caller_handle());
    facade::set_expects(
        store,
        ctx.now,
        &opener,
        thread,
        std::slice::from_ref(&withdrawn_qualified.to_string()),
    )?;
    store.post_message(&MessageEnvelope {
        origin: ctx.origin.to_string(),
        channel_id: store.thread_channel(thread).unwrap_or_default(),
        sender: withdrawn_qualified.to_string(),
        kind: MessageKind::Info,
        priority: Priority::Background,
        disposition: Disposition::NextSession,
        thread_id: Some(thread.to_string()),
        refs: Refs {
            session_id: return_address.map(str::to_string),
            ..Refs::default()
        },
        body: body.to_string(),
    });
    Ok(())
}

/// **After how many [`SESSION_LIVENESS_RECHECK_SECS`] cadences a session a withdrawal stopped, and
/// that still pins its claim, gets a NAMED warning** (nxf 6j6v.b9nf, Integrity #2 of this item's
/// review) — the same clock [`park_a_withdrawn_holder`] already re-arms on, counted rather than a
/// clock of its own — **and, since nxf 6j6v.27b9, its ONE further SIGTERM** (the name said "warn"
/// until the review of PR #483 pointed out that a later "tune the warning" edit would then move a
/// signal). Counted per session, from its own stop ([`the_one_further_stop`]).
///
/// **Why the further signal goes at the same count, and why only once** (the owner decided THAT it
/// may go, on 2026-09-20, and left when and how often to whoever built it). At five cadences the
/// process has outlived every bound its own teardown runs under: the shipped sidecar's teardown is
/// a handful of `nxc` calls, each bounded at thirty seconds (`NXC_CALL_TIMEOUT_MS`), so even a
/// teardown in which every one of them hangs to its bound is over in half this time. Anything
/// earlier would signal a process that is still doing what the first signal asked; at five minutes
/// it demonstrably is not. And ONCE, because a process that let two SIGTERMs pass is not waiting
/// for a third — more of them would be noise in its log and nothing else, and the step after a
/// SIGTERM is SIGKILL, which stays the owner's: the sidecar's whole teardown (its transcript flush,
/// its `session ended`) happens on SIGTERM, and a kill would take exactly that away.
///
/// **Five, chosen against what is ordinary on this path and what is not.** A stopped session's own
/// teardown — bind its runtime session, flush its transcript, post `nxc session ended` — is the
/// sub-second-to-low-seconds work `a-worker-can-stop-a-session.md` describes; the ordinary case
/// clears on the FIRST re-arm, almost always before it. Five cadences is five minutes at
/// [`SESSION_LIVENESS_RECHECK_SECS`]'s pace: long enough that no teardown this codebase has ever
/// measured comes anywhere near it, and short beside this crate's own other clocks —
/// [`crate::park::PARK_AFTER`] is thirty minutes, an abandoned lease's own bound two hours — so a
/// person learns about a wedged process while the fix is still one `kill` away, not after the
/// working copy has been stuck for the length of a coffee break. It is a constant rather than a
/// config knob for [`SESSION_LIVENESS_RECHECK_SECS`]'s own reason: one number, argued here, beats a
/// setting nobody will ever have cause to move.
const WITHDRAWN_SESSION_WEDGED_AFTER_CADENCES: i64 = 5;

/// How many whole [`SESSION_LIVENESS_RECHECK_SECS`] cadences have passed since `withdrawn_at`, or
/// `None` when either instant cannot be parsed. This is a DIAGNOSTIC read, not a gate — a `now` or
/// a stored marker this cannot parse is silence here rather than the loud failure a decision would
/// need, because the worst this gets wrong is one tick where a warning that should fire does not.
/// Negative (a marker somehow younger than `now`, which a monotonic clock never produces) reads as
/// zero rather than as a negative cadence count.
fn cadences_since(withdrawn_at: &str, now: &str) -> Option<i64> {
    use time::format_description::well_known::Rfc3339;
    use time::OffsetDateTime;
    let then = OffsetDateTime::parse(withdrawn_at, &Rfc3339).ok()?;
    let now = OffsetDateTime::parse(now, &Rfc3339).ok()?;
    Some(((now - then).whole_seconds().max(0)) / SESSION_LIVENESS_RECHECK_SECS)
}

/// **Name the session, its pid and its pid file, and say how to end it by hand** (nxf 6j6v.b9nf,
/// Integrity #2 of this item's review) — [`ConsequenceClass::WithdrawnHolderWedged`]'s own words.
///
/// **The pid is read straight off the pid file, not asked of the worker** — there is no seam for
/// it: [`Worker::session_is_running`] answers a yes/no, never a number, and inventing one just for
/// this diagnostic would be a second, narrower liveness question nobody else needs. The claim file's
/// shape ([`crate::worker::session_claim_for`]) is a crate-wide convention, public for exactly this
/// kind of reader, so reading it here is not a layering breach — it is the same file `nxc status`'s
/// own reader ([`crate::worker::live_sessions_in`]) already knows the name of. A pid that cannot be
/// read costs only the number in the sentence, never the warning itself.
///
/// **It says what the tick sent, and what it will never send** (nxf 6j6v.27b9). Until the owner's
/// decision of 2026-09-20 this sentence said nxs sends no second signal at all; now the tick sends
/// ONE further SIGTERM — through the worker's own stop, so behind the same identity guard as the
/// first, which is what answers the reused-pid worry that kept it out — and the sentence names when
/// it went, or why it did not land. Past that, a third signal and a SIGKILL are a person's.
fn warn_a_wedged_pinning_session(
    ctx: &Ctx,
    anchor: Option<&str>,
    holder: &str,
    session: &str,
    further: &FurtherStop,
) -> FailedConsequence {
    let where_and_pid = match ctx.worker.working_copy() {
        Some(root) => {
            let path = crate::worker::agent_logs_dir(&root).join(format!("{session}.pid"));
            let pid = std::fs::read_to_string(&path)
                .ok()
                .and_then(|s| s.lines().next().map(str::trim).map(str::to_string))
                .and_then(|s| s.parse::<u32>().ok());
            match pid {
                Some(pid) => format!("pid {pid}, recorded in {}", path.display()),
                None => format!("its pid could not be read from {}", path.display()),
            }
        }
        None => "its pid is not recorded on this host".to_string(),
    };
    let sent = match further {
        FurtherStop::SentNow => "one further SIGTERM was sent just now".to_string(),
        FurtherStop::NotDelivered(why) => {
            format!("one further SIGTERM was attempted just now and did not land ({why})")
        }
        FurtherStop::SentEarlier(at) => format!("one further SIGTERM was sent at {at}"),
        FurtherStop::NotDeliveredEarlier(at, why) => {
            format!("one further SIGTERM was attempted at {at} and did not land ({why})")
        }
    };
    let detail = format!(
        "operation {holder}'s withdrawn round is still pinned by session {session} ({where_and_pid}) \
         after {WITHDRAWN_SESSION_WEDGED_AFTER_CADENCES} liveness cadences with no sign of it \
         leaving — the stop `withdraw` sent was delivered, not waited out, and {sent}. nxs sends \
         nothing more, and never SIGKILL: if it should not still be there, end it by hand"
    );
    eprintln!("warning: {detail}");
    FailedConsequence::withdrawn_holder_wedged(anchor, session, detail)
}

/// What became of the tick's one further SIGTERM to a session a withdrawal stopped (nxf 6j6v.27b9)
/// — the half of [`warn_a_wedged_pinning_session`]'s sentence that changes from tick to tick.
enum FurtherStop {
    /// This tick sent it, and the worker says it was delivered.
    SentNow,
    /// This tick tried, and the worker could not deliver it — the reason in its own words.
    NotDelivered(String),
    /// An earlier tick sent it, at this instant; nothing more is sent.
    SentEarlier(String),
    /// An earlier tick tried at this instant and it did not land, for this reason; nothing more is
    /// sent (review of PR #483, Integrity #3: the stamp alone used to read "sent" about it).
    NotDeliveredEarlier(String, String),
}

/// **The one further SIGTERM a withdrawn session gets, decided and sent** (nxf 6j6v.27b9) — `None`
/// when there is nothing to say about `session` on this tick, `Some` with what became of the
/// signal when it is a wedged session to name.
///
/// Four steps, in an order each of which is load-bearing:
///
/// 1. **Is it a session this withdrawal stopped?** No row, nothing to do — see the caller.
/// 2. **Has it been [`WITHDRAWN_SESSION_WEDGED_AFTER_CADENCES`] since ITS OWN stop?** Counted from
///    the row's `stopped_at`, not from the marker (review of PR #483, Integrity #4): a session
///    resumed by a follow-up and withdrawn a second time under a marker that is older must not be
///    signalled a minute after its own stop.
/// 3. **Claim it, THEN send it.** [`ChatStore::claim_withdrawn_session_resignal`] is a
///    compare-and-swap; only the one tick that wins it signals, so two overlapping ticks (the
///    service's and a person's) cannot both send one (Integrity #4). A tick that loses the claim
///    stays silent — the winner names the session.
/// 4. **Send it through the worker's own stop**, the same door and so the same identity guard the
///    first signal went through: nothing is signalled that has not proved by its recorded start
///    instant that it is this session's process. A signal that does not land is recorded in the
///    worker's words, so no later tick calls it sent (Integrity #3). A session that is gone by the
///    time the signal is sent is the state that was wanted and not a wedged process to name.
fn the_one_further_stop(
    ctx: &Ctx,
    store: &mut ChatStore,
    holder: &str,
    session: &str,
) -> Result<Option<FurtherStop>> {
    let Some(row) = store.withdrawn_session(holder, session)? else {
        return Ok(None);
    };
    if !cadences_since(&row.stopped_at, ctx.now)
        .is_some_and(|n| n >= WITHDRAWN_SESSION_WEDGED_AFTER_CADENCES)
    {
        return Ok(None);
    }
    if let Some(at) = row.resignalled_at {
        return Ok(Some(match row.resignal_refused {
            Some(why) => FurtherStop::NotDeliveredEarlier(at, why),
            None => FurtherStop::SentEarlier(at),
        }));
    }
    if !store.claim_withdrawn_session_resignal(holder, session, ctx.now)? {
        return Ok(None);
    }
    Ok(match ctx.worker.stop_session(session) {
        Ok(crate::worker::SessionStop::Requested) => Some(FurtherStop::SentNow),
        // Recorded all the same, in the worker's words: nothing was signalled, and a later tick
        // that still found the session pinning must not call it sent.
        Ok(crate::worker::SessionStop::NothingToStop(note)) => {
            store.note_withdrawn_session_resignal_refused(holder, session, &note)?;
            None
        }
        Err(why) => {
            store.note_withdrawn_session_resignal_refused(holder, session, &why)?;
            Some(FurtherStop::NotDelivered(why))
        }
    })
}

/// **Come back and look at a withdrawn holder** (nxf 6j6v.b9nf) — one tick,
/// [`SESSION_LIVENESS_RECHECK_SECS`] out, keyed on the holder's claim root, the same
/// `schedule` + [`crate::timer::tick_command`] pair [`rearm_window_with`] arms with.
///
/// **Why its own key rather than the queue head's.** Every other arming on the park path goes
/// through [`arm_the_lease_bound`] / [`arm_the_park_retry`], keyed on the commission waiting behind
/// the copy — and this occasion has no contention requirement: a withdrawn round is parked whether
/// or not anybody is waiting, so there may be no head to key on. The claim root is the one key
/// this occasion always has. Arming REPLACES by key, so a head's own look and this one are two
/// clocks that do not overwrite each other, and both run the same park step.
///
/// **The liveness cadence and nothing shorter**, for [`drain_recheck_instant`]'s reason: what this
/// wait is for is a process to be gone, and the cadence is the interval this house already uses for
/// exactly that wait. A session-scoped claim has no thread to key a tick on; there the look is the
/// head's ([`arm_the_park_retry`]), and with nobody queued the next tick from anywhere is what
/// comes back — best-effort, like every scheduling site in this module.
fn arm_a_look_at_the_withdrawn_holder(
    ctx: &Ctx,
    store: &ChatStore,
    scope: &WorkScope,
) -> Option<FailedConsequence> {
    let thread = match scope {
        WorkScope::Thread(thread) => thread.as_str(),
        WorkScope::Session(_) => return arm_the_park_retry(ctx, store),
    };
    let failed = |why: String| {
        let detail = format!(
            "the tick that parks the withdrawn operation {}'s work once its processes are gone \
             was not armed ({why}) — run `nxc tick --thread {thread}` once nothing is running \
             there, or the next tick from anywhere does it",
            scope.key()
        );
        eprintln!("warning: {detail}");
        Some(FailedConsequence::tick_unscheduled(thread, detail))
    };
    let when = match session_liveness_recheck(ctx.now) {
        Ok(when) => when,
        Err(e) => return failed(format!("its instant could not be resolved: {e}")),
    };
    match ctx
        .timer
        .schedule(thread, &when, &crate::timer::tick_command(thread))
    {
        Ok(_) => None,
        Err(e) => failed(format!("scheduling it failed: {e}")),
    }
}

/// **Would a park of `holder`'s work produce a branch, or meet a refusal nothing can clear?** (nxf
/// 6j6v.b9nf, fix round 2 of this item's review, Code Quality #1) — `None` is "a branch"; `Some(why)`
/// is the permanent refusal in its own words.
///
/// **The same three questions [`attempt_the_park`] opens with, in the same order, asked by the same
/// functions** — a working copy the worker names, a git repository, a recorded base — and that is
/// the whole design: they are exactly [`ParkRefusal::is_permanent`]'s set, they are all READS, and
/// re-deriving them here rather than copying their conditions is what keeps this answer and the
/// park's own from drifting. The repository is asked about before the base for that function's
/// reason: a directory git cannot read never had one, and reporting the missing base would name the
/// consequence instead of the cause.
///
/// **What it deliberately does NOT ask** is anything TRANSIENT — a merge in progress, a git command
/// that failed. Those are answered by waiting, and the caller of this is deciding what to PROMISE:
/// a branch that arrives at the next tick is still a branch, and hedging it would make every
/// mid-merge withdrawal read like a host that cannot park at all.
fn a_park_here_would_not_produce_a_branch(
    ctx: &Ctx,
    store: &ChatStore,
    holder: &str,
) -> Option<String> {
    let copy = match the_working_copy(ctx) {
        Ok(copy) => copy,
        Err(refusal) => return Some(refusal.detail().to_string()),
    };
    if let Err(refusal) = copy.assert_repository() {
        return Some(refusal.detail().to_string());
    }
    match store.operation_base(holder) {
        Ok(Some(_)) => None,
        Ok(None) => Some(format!(
            "no base branch was ever recorded for operation {holder} — it never took the working \
             copy while one could be read — so there is nowhere to put the tree back to after a park"
        )),
        // A store that cannot be read is not a statement that the park will fail: the promise is
        // left as it was and the tick, which asks the same question again, is what finds out.
        Err(e) => {
            eprintln!(
                "warning: could not read operation {holder}'s recorded base to say whether its \
                 work can be parked ({e}) — the receipt answers as if it can, and the tick decides"
            );
            None
        }
    }
}

/// **Does the claim `thread` stands in hold a WITHDRAWN round's work that is not parked yet?** (nxf
/// 6j6v.b9nf, fix round 2 of this item's review, Test Quality #5) — the marker read as the fact it
/// is, by a caller that is about to start work in that checkout.
///
/// One question, asked the way [`withdraw`] itself asks it, so the two cannot drift: the lease ROW
/// (expired or not — an expired row is still a claim the tick's occasions act on), its marker, and
/// whether this thread is inside the claim area that key names. `withdraw` decides which threads it
/// may promise a park to with the same three reads (`claim.contains(&session.thread)`); anything
/// looser here would decline for a withdrawal that has nothing to do with this operation, and
/// anything tighter would miss the shared session standing beside the holder.
///
/// `None` is "nothing was taken back here, or its copy has already gone on" — the marker's whole
/// lifetime, which ends at the hand-off and at every other movement of the lease
/// (`working_tree`'s release and both reclaims).
fn a_withdrawn_claim_awaiting_its_park(
    store: &ChatStore,
    thread: &str,
) -> Result<Option<WorkScope>> {
    let Some((key, _)) = store.working_tree_lease_row()? else {
        return Ok(None);
    };
    if store.withdrawn_holder(&key)?.is_none() {
        return Ok(None);
    }
    let Some(scope) = WorkScope::parse(&key) else {
        return Ok(None); // the sweep is the one place that says this out loud
    };
    if !store
        .work_scope_threads(&scope)?
        .iter()
        .any(|t| t == thread)
    {
        return Ok(None);
    }
    Ok(Some(scope))
}

/// **Discharge every thread that is still waiting on work this withdrawal took back** — the threads
/// between each taken-back thread and `root`, the operation's first thread (nxf 6j6v.s2cj; see the
/// call site in [`withdraw`] for why, and for the measured run behind it).
///
/// A thread on that path is discharged when it still owes an answer: a channel thread expecting its
/// supervisor, a persona thread whose session is waiting on the round below it. Left alone: one
/// that is complete — nothing waits there; one already on the withdrawn identity; one that is
/// ITSELF being taken back, which the loops of [`withdraw`] discharge with a message of their own
/// right after this (`root` included, when its own session is the one being stopped); and one whose
/// opener this workspace has not folded yet — the discharge is written as the thread's opener, and
/// refusing the whole withdrawal over an ancestor that is still in flight would be the worse
/// failure (nxf 6j6v.7me0's helper skipped it the same way).
///
/// The walk stops at `root`, and it stops at a thread it has already seen: `root` is what
/// [`ChatStore::thread_root`] resolved, which takes the smallest id of a cycle in a synced or
/// hand-edited log, so a walk up from inside one may never reach it by parent edges.
fn interrupt_the_chain_above(
    ctx: &Ctx,
    store: &mut ChatStore,
    root: &str,
    taken_back: &[String],
    withdrawn_qualified: &str,
) -> Result<()> {
    let mut waiting: Vec<String> = Vec::new();
    for thread in taken_back {
        // Walks up from every thread, including one that is itself an ancestor of another: the
        // `contains` below keeps it off the discharge list either way.
        let mut seen: Vec<String> = vec![thread.clone()];
        let mut at = thread.clone();
        while at != root {
            let Some(parent) = store.thread_parent(&at)? else {
                break;
            };
            if seen.contains(&parent) {
                break;
            }
            seen.push(parent.clone());
            if !waiting.contains(&parent) && !taken_back.contains(&parent) {
                waiting.push(parent.clone());
            }
            at = parent;
        }
    }
    for thread in waiting {
        let Some(q) = store.thread_quorum(&thread, ctx.now)? else {
            continue;
        };
        if q.complete || q.expects.is_empty() || q.expects.iter().any(|h| h == withdrawn_qualified)
        {
            continue;
        }
        if store.thread_opener(&thread)?.is_none() {
            continue;
        }
        // **The way back, on a persona thread** (review of PR #483, Code Quality #8). What brings
        // parked work back is the next commission into the operation's first thread, and on a
        // persona thread that is the person's `reply`, whose fallback resumes the newest message
        // from the other side that carries a session. A `pm` that commissioned a round and was
        // waiting for it has usually posted NOTHING in its own thread — so without an address here
        // the follow-up resumed nobody and the park sat there. The session standing in this thread
        // is the one that was waiting, and this message is its return address, exactly as a stopped
        // session's own discharge carries it ([`discharge_a_withdrawn_thread`]). A ROUND's thread
        // gets none: its follow-up is the supervisor's (a new pass), not a resume.
        let return_address = if supervised_member_threads(ctx, store, &thread)?.is_empty() {
            store
                .newest_sessions_in_threads(std::slice::from_ref(&thread))?
                .remove(&thread)
                .map(|row| row.internal_id)
        } else {
            None
        };
        discharge_a_withdrawn_thread(
            ctx,
            store,
            &thread,
            withdrawn_qualified,
            &format!(
                "[withdrawn by {}] work below this thread was taken back, and a withdrawal \
                 interrupts the chain it belongs to — nothing further is commissioned from here, \
                 and nothing is left to consolidate",
                ctx.caller_handle()
            ),
            return_address.as_deref(),
        )?;
    }
    Ok(())
}

/// Re-check one channel board and, if it is genuinely due, route its completion
/// (`nxc tick --thread <id>`, nxf 6j6v.z06n).
///
/// This is what a declared channel's scheduled one-shot timer invokes when it fires
/// ([`crate::timer::schedule_tick`]); nothing ever waits synchronously for it, and it is equally
/// safe to invoke by hand (to force a board's timeout check, or as a recovery tool).
///
/// Steps: (1) load the thread's quorum, `not_found` if unknown; (2) if nothing is due yet, a clean,
/// successful no-op (a timer firing early through clock skew, or a race, is not a caller mistake) —
/// **and the one-shot job is re-armed for the next instant a member's clock falls due**
/// ([`rearm_member_window`], nxf 6j6v.nf38), since a member's window moves and a fired `at` job does
/// not fire twice; (2b) **an ordered flow whose step let its window run out is ADVANCED rather than
/// consolidated** (nxf 6j6v.rs9k) — a settled set ends a `parallel` channel and ends an ordered one
/// only at its LAST step, so the tick asks [`tick_move`] which of the three it is looking at;
/// (3) resolve the declared channel backing this thread by the
/// `decl:<name>` reverse lookup — a non-declared channel's thread has no `on_complete` policy at
/// all, a deliberate "nothing to do"; (4) the idempotency check below; (5) route through
/// [`route_declared_channel_completion`], the SAME completion logic [`reply`]'s PUSH-wake block
/// uses, resolving the return address from the thread's root message exactly as `reply` does.
///
/// **Idempotent — the actual "no double-fire" guarantee** this verb rests on, since a real
/// cross-process `cancel` of the scheduled OS job is explicitly out of scope (see `timer.rs`: the
/// design offers "cancels/ignores" as equally valid, and this relies on "ignores"). A thread whose
/// completion was ALREADY handled — by a real completing `reply`, or an earlier tick — must be
/// recognized and be a clean no-op, never a second wake or a second synthesizer spawn.
///
/// **The check asks which marker the thread CARRIES, not which one its declaration implies** (nxf
/// 6j6v.e9qj, fix round 1). It used to branch on `channel.on_complete` and look for that form's
/// single marker; since an escalating set is never folded, a `summarize` channel can be discharged
/// through the pass-through path, and the declared-form lookup then missed its own marker. Either
/// marker means a consolidation has run here:
/// - `summarize`: the phase-1/phase-2 marker — `thread.expects` already equalling the QUALIFIED
///   synthesis identity — IS the "already handled" signal, checked BEFORE routing at all. That one
///   check covers BOTH sub-states a later tick could observe: still waiting on the synthesizer's
///   own reply (the marker was set, phase 2 hasn't landed), or phase 2 already delivered (the
///   synthesizer's own `nxc reply` routed it synchronously, within THAT call, before this tick
///   could ever have observed it first) — either way there is nothing new to do.
/// - `pass_through`: single-phase, so it has no phase marker of its own;
///   [`route_declared_channel_completion`] gives it an equivalent one — it retargets
///   `expects_reply_from` to the qualified [`crate::channel::DELIVERED_HANDLE`] identity and
///   immediately self-satisfies it with a real posted message, so the thread ends up
///   `complete: true` FOREVER, matching `summarize`'s eventual visible shape and staying
///   discoverable via `opener_wake`/inbox/`threads show` (an earlier design emptied
///   `expects_reply_from` instead, which read as neither complete nor stale — a clean idempotency
///   signal, but one that silently erased the board from every PULL surface, losing the safety net
///   for a PUSH wake that itself fails). The check here is symmetric with `summarize`'s — and since
///   6j6v.e9qj this marker is also what an ESCALATING set leaves behind on a channel that declares
///   `summarize`, which is the whole reason the check reads the thread rather than the declaration.
///
/// **Neither marker check can be replaced by step 2's due-check.** Step 2 is two predicates, not one
/// (see the comment at the site): a thread with member threads below it is due when its SET is
/// settled, and one without them keeps the original `complete || stale`. The argument here is about
/// the SECOND — a `summarize` thread whose phase-1 retarget left its ORIGINAL deadline untouched, so
/// it can still read `stale` (outstanding the synthesizer's own reply, past that old deadline) long
/// after phase 1 ran; and a `pass_through` one that, once self-satisfied, reads `complete: true`,
/// which neither branch treats as pending. In both cases only the marker distinguishes "already
/// handled" from "genuinely due".
///
/// **What it acted on is reported, and so is what it could not do.** The receipt carries the whole
/// result of the routing — [`TickReceipt::woke`] and `wake_skipped` beside `delivered`, and
/// `warnings` carrying ALL of what did not happen where the two before it carry at most the first of
/// their own kind (nxf 6j6v.93zd) — because this verb
/// inherits [`reply`]'s "skip, don't fail" contract along with its
/// implementation, and `acted: true` alone would otherwise read as a delivered hand-off even when
/// the requester was never woken (PR #265 review, Integrity & Robustness
/// #1/#2). Nobody is watching this verb's stderr: it is what a scheduled timer runs unattended, and
/// what an app calls through the handle. (This paragraph named an `advance_failed` field beside the
/// two `Option`s until 6j6v.dvyq §3 removed the run record it reported on; what a stopped flow
/// leaves behind is a `StepSkipped` in `warnings`, and since 6j6v.rs9k a step that stayed SILENT
/// leaves a `StepUnanswered` there beside it.)
///
/// Rejection: an unknown `thread_id` is `not_found`. Everything else is a clean, successful no-op —
/// a non-declared-channel thread, or an unresolvable return address — mirroring `reply`'s own "no
/// known return address is ordinary, not an error" tone. The one successful outcome that is neither
/// a routing nor a no-op is the flow ADVANCE of step 2b, which reports itself as
/// [`TICK_ADVANCED`].
pub fn tick(ctx: &Ctx, store: &mut ChatStore, req: TickRequest) -> Result<TickReceipt> {
    let mut receipt = tick_reporting_its_own_failures(ctx, store, req)?;
    // **A tick is the verb with the most to lose from silence** (nxf 6j6v.0j12): it is what the
    // service itself runs unattended, and what an app calls when nothing else will. Appended after
    // the work, so the finding rides a receipt that is otherwise exactly what it was.
    receipt
        .warnings
        .extend(service_finding(ctx, &receipt.thread_id));
    Ok(receipt)
}

fn tick_reporting_its_own_failures(
    ctx: &Ctx,
    store: &mut ChatStore,
    req: TickRequest,
) -> Result<TickReceipt> {
    // FIRST, and before the thread below is even resolved (nxf 6j6v.fabb): reclaim an expired
    // working-tree lease and start whoever is parked behind it. That question is about the
    // WORKSPACE, not about this thread — see [`sweep_expired_working_tree`] for why it rides this verb rather
    // than one of its own — and asking it first is what makes it independent of how the channel
    // half below decides, including its refusals.
    //
    // **A sweep that happened is durable even when this call goes on to fail.** If the thread named
    // here does not exist, the `not_found` below is what the caller gets and the report of the
    // sweep is lost with it — but the release and the triggers it started are already committed,
    // and the next read shows them. Losing a REPORT of work that happened is the acceptable half of
    // that trade; the other order — refusing to sweep because a thread id was wrong — would leave
    // the queue parked for the one reason that has nothing to do with it.
    //
    // **The park step goes FIRST, ahead of the sweep** (nxf 6j6v.de9s), and the order is
    // load-bearing rather than tidy: both can hand the same working copy on, and the step above
    // acts on troubles the sweep's own clock knows nothing about. See [`park_the_stranded_holder`]
    // for the whole rule and [`park_step`] for the occasions after it (nxf 6j6v.8bv9) — which is
    // also where a park refused on an earlier tick is retried.
    //
    // **The sweep saves the holder's work too now** (nxf 6j6v.8bv9), so the order is no longer what
    // keeps a hand-off from losing it — it is what keeps two occasions from parking the same holder
    // twice in one tick, which is what `park.held` carries across.
    let mut park_warnings = Vec::new();
    let park = park_step(ctx, store, &mut park_warnings)?;
    let sweep = sweep_expired_working_tree(ctx, store, park.held, &mut park_warnings)?;
    // **And the third workspace-wide question, on the same terms** (nxf 6j6v.gn8b): is anybody
    // holding answers for a caller that has stopped running? The scheduled job armed by
    // `session ended` is the ordinary way that queue drains; this is the backstop for the caller
    // that was killed before it could announce anything, and it rides this verb for exactly the
    // reason the two sweeps above do — it is about the WORKSPACE, and it must not depend on how the
    // channel half below decides, including its refusals.
    park_warnings.extend(sweep_held_deliveries(ctx, store));
    let mut receipt = tick_the_thread(ctx, store, req)?;
    receipt.working_tree = sweep.swept;
    receipt.parked = park.parked;
    // **Two producers, one field, and they cannot both fire** (nxf 6j6v.xb24). The park step's
    // occasions act on the holder of the moment; if one of them handed the copy on, the lease has
    // MOVED and the sweep behind it looks at a different holder — one that was started a statement
    // ago and is therefore alive. If one of them HELD, `park.held` is what stops the sweep
    // attempting anything at all. So `or` is an ordering rather than a choice, and it puts the step
    // that ran first first.
    receipt.handed_on = park.handed_on.or(sweep.handed_on);
    // Same durability trade the sweep above documents: if `tick_the_thread` had failed, the park
    // would already be committed and this report lost with the error. Losing the REPORT of work that
    // happened is the acceptable half; refusing to park because a thread id was wrong is not.
    receipt.warnings.extend(park_warnings);
    Ok(receipt)
}

/// [`tick`]'s channel half — everything this verb has always done, unchanged. Split out so the
/// workspace-wide sweep above runs on every call regardless of which of the many no-op arms below
/// reached.
fn tick_the_thread(ctx: &Ctx, store: &mut ChatStore, req: TickRequest) -> Result<TickReceipt> {
    let hop = resolve_hop(ctx, store)?;
    let thread_id = req.thread_id;
    let q = store
        .thread_quorum(thread_id, ctx.now)?
        .ok_or_else(|| NxfError::not_found(format!("no such thread: {thread_id}")))?;
    // The operation's own declarations (nxf 6j6v.n92p) — `reply`'s substitution, on the PULL path.
    // A tick can advance a flow, consolidate a set and start sessions, so it reads exactly the same
    // declarations a reply does and must read the same VERSION of them: a lapsed window resolved
    // against a freshly edited folder would be the stability hole reopened by the one path nobody
    // is present on.
    //
    // After the thread is resolved, so a tick against a thread that does not exist still fails with
    // its own `not_found` rather than with anything this line could say.
    let frozen = operation_declarations(ctx, store, thread_id)?;
    let ctx = &with_declarations(ctx, frozen.as_ref());
    // Read ONCE, up front — and since the branch review of PR #337 (Code #1) that is true rather
    // than merely intended: every receipt below reports it, `outstanding_for_report` derives from
    // it, and re-deriving it per branch is how the no-op arms and the acted arm would start
    // answering differently.
    let members = supervised_member_threads(ctx, store, thread_id)?;
    let outstanding = outstanding_for_report(&q, &members);

    // Step 1b: a HELD thread (nxf 6j6v.pzkb) — an op that shaped its obligation came from nobody this
    // replica can vouch for. It is never `complete` nor `stale`, so every branch below would decline
    // anyway; saying WHY here is what keeps "held" from reading as "still waiting for an answer".
    if q.held {
        return Ok(tick_no_op(thread_id, "held", outstanding));
    }

    // Step 2: genuinely still pending (see this fn's own doc for why "already delivered" is NOT
    // generally caught here for either policy — that is step 4's job).
    //
    // **A supervised channel thread is due when its SET is settled** (nxf 6j6v.pf6j), not when its
    // own register is discharged: that register names the supervisor, and the supervisor discharging
    // it IS the thing this tick exists to make happen when the synchronous path did not. Without
    // this the PULL safety net would silently stop covering exactly the case it was built for — a
    // member's reply that was written while the consequence it should have driven never ran.
    //
    // **…and its OWN `stale` says nothing about it** (nxf 6j6v.nf38). A channel thread's advisory
    // deadline is one absolute instant, stamped when the channel opened and moved by nothing. Read
    // as a trigger here it IS the stubbornly running deadline this item exists to remove: the timer
    // fires at that instant, the channel thread is trivially `stale` (it expects the supervisor,
    // which by definition has not answered while the members are working), and the requester is
    // handed a consolidation containing nobody's answer — with every member still healthily at work
    // half an hour into an hour of it. What is actually being waited for is the SET, each member of
    // which carries its own resettable clock, so on a supervised thread that is the whole question.
    // A thread with no member threads below it is unchanged: its own register is all there is.
    //
    // **`members` here is every slot, not [`current_pass`]** (nxf 6j6v.hq71 — recorded rather than
    // changed, and CORRECTED in review round 3).
    //
    // Round 1 justified the equivalence with "a slot of an EARLIER pass is always `complete || stale`,
    // because the pass only ended because it settled", and named its own trigger: "if passes ever come
    // to end unsettled, this read has to narrow". **That trigger has since fired.** A requester may
    // follow up into the channel thread while a step is still working, which starts the next pass
    // beside an unanswered slot — `channel_flow.rs`'s two straggler tests construct exactly that — so
    // an earlier pass CAN end with an outstanding slot and the two lists are no longer equivalent.
    //
    // **The read is left wide anyway, deliberately, and here is the reasoning rather than the old
    // claim.** Widening can only make the WAITING answer easier to reach: an extra outstanding slot
    // turns a "settled" into a "not settled", never the reverse. So the failure direction is a tick
    // that declines where a narrowed one would have acted — a stall, never a delivery of the wrong
    // set, and the PUSH path (`supervisor_consider_set`, which IS anchored to the current pass) is
    // the primary route and is unaffected. Narrowing would also narrow `outstanding_for_report` and
    // `rearm_member_window` at this same site, which is a change to what the timeout mechanism
    // reports and re-arms.
    //
    // **The deadline-strike semantics this comment used to defer to have since been decided (nxf
    // 6j6v.rs9k), and the read still did not have to narrow.** That item asked what a struck
    // deadline MEANS in an ordered flow, and the answer — a lapsed step advances the flow — is
    // decided one line down in [`tick_move`], which derives the CURRENT PASS for itself and asks the
    // ordered question of that. The wide read here is now exactly the "is there anything at all to
    // look at" gate and nothing more; the narrow question is asked where it belongs, and neither
    // `outstanding_for_report` nor `rearm_member_window` had to change to get it.
    //
    // **The residual, said out loud, and it is unchanged**: while a straggler from an earlier pass is
    // outstanding, this channel thread gets no automatic strike at all, even if the CURRENT pass is
    // genuinely overdue — an ordered flow's lapse included. It is a stall, not a wrong answer.
    //
    // **What the settled set MEANS is a THIRD question and it is asked here** (nxf 6j6v.rs9k): a set
    // that is settled ends a `parallel` channel, and it ends an ordered one only if the step that
    // settled it was the LAST one. See [`TickMove`].
    let mut mv = tick_move(ctx, store, &q, &members)?;
    // **…and a FOURTH question, on a channel that needs the working copy alone** (nxf 6j6v.10yb):
    // is a session behind one of these slots still running? The PUSH path asks it inside
    // [`supervisor_consider_set`]; the PULL path has to ask it here, because `tick_move` decides
    // between three moves from the board alone and the board cannot see a process.
    //
    // `members` here is every slot rather than the current pass — the same wide read the block above
    // argues for, and in the same safe direction: an extra slot can only turn a move into
    // `Waiting`, never the reverse. A LAPSED slot is skipped by the predicate itself, so the one
    // move a hung process must never block — `TickMove::Advance`, which exists precisely to get past
    // a step that went silent — still gets through.
    let mut waiting_on_a_session = false;
    if !matches!(mv, TickMove::Waiting)
        && a_member_session_is_still_writing(ctx, store, declared_channel_of(ctx, &q), &members)?
    {
        mv = TickMove::Waiting;
        waiting_on_a_session = true;
    }
    if matches!(mv, TickMove::Waiting) {
        // **Re-arm before declining** (nxf 6j6v.nf38). A one-shot `at` job fires ONCE; declining
        // without scheduling the next one would end the automatic strike for good the first time any
        // member showed a sign of life — and on the commonest shape of all, a one-member channel,
        // that means the requester waits forever for a member that wrote one line and then hung.
        // The window moved, so the job that watches it moves with it. Same pattern, same file, same
        // best-effort rules as the step-liveness clock's own re-arm (`next_window`, reached from
        // `workflow_liveness`'s "alive, slide it forward" branch).
        // **The liveness gate gets a clock of its own** (nxf 6j6v.858n). `rearm_member_window`
        // arms the next instant a member's REPLY window falls due — and a member that has replied
        // is `complete`, so on the commonest shape of all (one member per step) there is no
        // candidate and nothing was armed. That is precisely the state a board blocked on a live
        // session is in, so the one thing nothing watched was the one thing that needed watching.
        // Folded into the SAME arm rather than added beside it, because arming replaces by thread.
        let recheck = match waiting_on_a_session {
            true => Some(session_liveness_recheck(ctx.now)?),
            false => None,
        };
        let unscheduled = rearm_window_with(ctx, thread_id, &members, recheck.as_deref());
        // **`not_due` and `waiting_for_a_session` are different answers, and the second one is the
        // only one a reader can act on** (review of PR #361, Code Quality #1). A board whose set is
        // settled and whose only remaining blocker is a live process is NOT "nothing to do": it is
        // a flow that is ready to move and is waiting for a fact this call cannot bring about.
        //
        // It matters because it names a WAIT nothing else can end. The member-window re-arm above
        // arms the next instant a member's REPLY window falls due, and a member that already
        // replied is `complete` — so it is not among those candidates, and on the commonest shape
        // (one member per step) there are none at all. The channel's declared `timeout:` cannot end
        // it either: that window is a deadline for an ANSWER and this member has answered. What
        // ends it is the session announcing its own end ([`session_ended`]), this verb finding the
        // process gone — which it now does on a clock of its own (nxf 6j6v.858n, armed just above)
        // — or somebody asking by hand. Saying `not_due` over any of that would send an operator
        // looking for a board that is not yet ripe, which is the opposite of what is true.
        let reason = if waiting_on_a_session {
            TICK_WAITING_FOR_A_SESSION
        } else {
            "not_due"
        };
        let mut receipt = tick_no_op(thread_id, reason, outstanding);
        // A decline that could not re-arm is the ONE no-op that is not clean (nxf 6j6v.p3sm): the
        // board looked fine, nothing was due, and the job that was supposed to look again does not
        // exist. Nobody is watching this verb's stderr — it is what a scheduled timer runs
        // unattended and what an app calls through the handle — so it travels on the receipt.
        receipt.warnings.extend(unscheduled);
        return Ok(receipt);
    }

    // **Step 2b: a lapsed step of an ordered flow ADVANCES it** (nxf 6j6v.rs9k, owner 2026-08-21).
    //
    // This is the route a deadline strike had no way into. Until this item only a real REPLY reached
    // [`supervisor_advance_flow`] — through [`supervisor_after_reply`] — so a middle step whose window
    // ran out left a set that read settled, and the tick below consolidated it and delivered. Every
    // step after the lapsed one then never ran, on a channel whose own declaration says a step starts
    // once the one before it has SETTLED, `stale` included.
    //
    // **It goes through [`supervisor_consider_set`] rather than around it**, which is the whole point
    // of routing a lapse "into the supervisor" at all: where the flow stands, which step is next,
    // whether a later step of this pass is already running, what a step that cannot start reports,
    // and the re-arm of the window that watches the new step are ONE piece of logic with one set of
    // corrections behind it. A second copy here is how the PUSH and PULL paths would come apart.
    //
    // **No further gate is needed before it, and that is by construction rather than by luck**:
    // `TickMove::Advance` is only ever produced for a thread that a DECLARED, `sequential` channel
    // backs (step 3's gate) and that still expects the supervisor (step 4's marker check, one axis
    // over — a consolidated thread expects `__synth__`/`__delivered__`, never the supervisor). The
    // return address of step 5 has no bearing on a step that is being STARTED, not delivered to.
    if let TickMove::Advance {
        settled_slot,
        settled_step,
        next_step,
        lapsed,
    } = &mv
    {
        let run = supervisor_consider_set(ctx, store, thread_id, settled_slot, hop)?;
        // A LAPSE is a finding, not a silent premise of the advance (nxf 6j6v.93zd's rule, rs9k's
        // class): a step was commissioned, said nothing for its whole window, and the flow went on
        // without it. It is recorded FIRST, because it is the reason this call happened at all, and
        // whatever the advance itself could not do follows it.
        //
        // **A step that ANSWERED gets no such finding** (nxf 6j6v.858n): nothing went wrong there
        // at all — the flow was waiting for its process to end and now it has. Reporting a
        // `step_unanswered` for it would be a false alarm on the commonest path this branch now
        // takes.
        //
        // **And it is asked of what the supervisor DID, not of what `tick_move` predicted** (nxf
        // 6j6v.ma7v). The move is decided here from the board's rows; whether the flow then really
        // advanced is decided one level down, where the escalation of the set is readable — an
        // escalating set ends the chain instead, and the sentence below would then name a step that
        // never opened. The consolidation that runs in its place reports the same lapse in its own
        // words ([`lapsed_step_findings`]), so nothing goes unsaid either way.
        let mut warnings = Vec::new();
        if *lapsed && run.advanced {
            warnings.push(FailedConsequence::step_unanswered(
                Some(settled_slot),
                format!(
                    "step {settled_step:?} gave no answer inside its declared window; the flow \
                     advanced to step {next_step:?} without it"
                ),
            ));
        }
        warnings.extend(run.warnings);
        debug_assert_one_place(&warnings, run.wake_skipped.as_ref());
        // **`completed` used to be `None` on every path that reaches here, and since nxf 6j6v.ma7v
        // it is not.** The old reasoning was that `supervisor_consider_set` takes its ADVANCE branch
        // by construction, `tick_move` having asked the same two questions of the same rows in this
        // same call. ma7v adds a third question that only the supervisor can ask — did the settled
        // set ESCALATE — because answering it needs the store, which [`tick_move`] does not have. So
        // a lapse or a liveness release on a step that escalated reaches here as `Advance` and comes
        // back CONSOLIDATED, and the receipt says so: `acted`, with what was delivered.
        //
        // Reporting it rather than dropping it was always the rule — a consolidation that happened
        // and was reported as "advanced, nothing delivered" would be exactly the silent hand-off
        // this receipt exists to make impossible — and it is now load-bearing rather than
        // belt-and-braces.
        let (acted, reason, delivered) = match run.completed {
            Some(outcome) => (true, "acted", Some(outcome.delivered)),
            None => (false, TICK_ADVANCED, None),
        };
        return Ok(TickReceipt {
            thread_id: thread_id.to_string(),
            acted,
            reason: reason.to_string(),
            delivered,
            woke: run.woke,
            wake_skipped: run.wake_skipped,
            held: run.held,
            warnings,
            outstanding,
            // Attached by [`tick`], which is where the sweep runs.
            working_tree: None,
            parked: None,
            handed_on: None,
        });
    }

    // Step 3: which declared channel, if any, backs this thread — through the SAME catalogue the
    // routing below resolves it through, so the two can never disagree.
    let declared = ctx
        .defs
        .channels()
        .iter()
        .find(|c| Some(format!("{DECLARED_CHANNEL_PREFIX}{}", c.name)) == q.channel_id);
    // A GATE, not a lookup of the policy: since the idempotency check below reads which marker the
    // thread carries rather than which one the declaration implies (fix round 1, review F1), nothing
    // here needs the declaration's contents — only the fact that one exists, which is what makes the
    // routing in step 6 resolvable.
    if declared.is_none() {
        return Ok(tick_no_op(thread_id, "not_a_declared_channel", outstanding));
    }

    // Step 4: idempotency — keyed on the marker the consolidation ACTUALLY used, which is the one
    // the thread is retargeted to, NOT the one this channel's declaration names.
    //
    // **The two can differ, and that is nxf 6j6v.e9qj's doing** (fix round 1). This check used to
    // `match channel.on_complete` and ask for the single marker that form would have written. Since
    // an escalating set is never folded, a channel declaring `summarize` is discharged through the
    // PASS-THROUGH path and carries `__delivered__` — so the declared-form lookup asked for
    // `__synth__`, found `__delivered__`, and concluded the turn was still due. That is not a
    // cosmetic miss: the tick then re-routes an already-delivered turn, reports `acted: true` for
    // work it did not do, and — if the member has since replied again without escalating — resolves
    // the consolidator afresh, gets `Fold`, wins a claim under the NEW expects version and
    // **spawns a second paid synthesizer over a turn the requester was already handed**.
    //
    // Both markers are engine identities no declared role can hold ([`RESERVED_HANDLE_PREFIX`]), so
    // "the thread expects one of them" cannot be a legitimate pending state for any channel: it
    // means a consolidation has run here, whichever form ran it.
    //
    // **And a THIRD marker since nxf 6j6v.s2cj: the withdrawn identity.** A withdrawal discharges
    // every round it interrupts onto it ([`interrupt_the_chain_above`]), and such a thread reads
    // `complete` with a settled set below it — exactly what this step would otherwise consolidate
    // and deliver. For a person's round that was a no-op only by luck (a person carries no return
    // address); for a round an AGENT commissioned it woke that agent with the taken-back round as
    // its answer, and the chain went on above the step that was taken back. Measured, in
    // `a_tick_on_a_withdrawn_round_does_not_wake_the_agent_that_commissioned_it` — and it was
    // already reachable for nxf 6j6v.7me0's fully withdrawn round. "Already handled" is the true
    // word: the round's debt was settled, by the withdrawal, and there is nothing to deliver.
    let handled_markers = [
        format!("{}/{}", ctx.origin, crate::channel::SYNTHESIS_HANDLE),
        format!("{}/{}", ctx.origin, crate::channel::DELIVERED_HANDLE),
        format!("{}/{}", ctx.origin, crate::channel::WITHDRAWN_HANDLE),
    ];
    if q.expects.len() == 1 && handled_markers.contains(&q.expects[0]) {
        return Ok(tick_no_op(thread_id, "already_handled", outstanding));
    }

    // Step 5: the thread's root message (its FIRST, id-ordered) carries the return address — the
    // exact resolution `reply`'s own completion block performs.
    let msgs = store.acting_messages_in_thread(thread_id)?;
    let addr = match msgs.first() {
        Some(root) => store.message_return_address(&root.message_id)?,
        None => None,
    };
    let Some(addr) = addr else {
        return Ok(tick_no_op(thread_id, "no_return_address", outstanding));
    };

    // Read BEFORE the routing, while the pass is still the pass this consolidation is about (nxf
    // 6j6v.rs9k): what the delivery below carries no answer from is a fact about the set as it
    // stands now, and `route_declared_channel_completion` retargets the thread it is derived from.
    let mut warnings = lapsed_step_findings(ctx, store, &q)?;
    let routed = route_declared_channel_completion(ctx, store, &q, &addr, hop)?
        .expect("a declared channel backs this thread, resolved in step 3");
    // Every field of the routing's result travels into the receipt, not just `delivered`: what it
    // woke and the wake it could not land are exactly the parts a caller cannot re-derive from a
    // later read (PR #265 review, Integrity & Robustness #1/#2) — and they are the parts that make
    // `acted: true` mean something.
    warnings.extend(routed.warnings);
    debug_assert_one_place(&warnings, routed.wake_skipped.as_ref());
    Ok(TickReceipt {
        thread_id: thread_id.to_string(),
        acted: true,
        reason: "acted".to_string(),
        delivered: Some(routed.outcome.delivered),
        woke: routed.woke,
        wake_skipped: routed.wake_skipped,
        held: routed.held,
        warnings,
        outstanding,
        // Attached by [`tick`], which is where the sweep runs.
        working_tree: None,
        parked: None,
        handed_on: None,
    })
}

/// **How long after a look blocked ONLY by a live session the board is looked at again** (nxf
/// 6j6v.858n) — the liveness window, named once because both paths arm it.
///
/// It is NOT the channel's declared `timeout:`, and it could not be: that window is a deadline for
/// an ANSWER, and the member whose session is holding this gate has answered. `stale` needs a
/// non-empty `outstanding`; there is none. So this gate needed a clock of its own, and this is its
/// one number.
///
/// **A minute, and the trade is in both directions.** What it costs when a session is genuinely
/// working is one store read and one pid read per minute — for the eighteen minutes the incident in
/// nxf 6j6v.10yb actually measured, eighteen of them. What it buys when the end announcement is
/// LOST — a sidecar killed before its fourth teardown step, an older `nxc`, a host runtime with no
/// `Engine::session_ended` — is that the channel frees itself within a minute instead of waiting
/// for a human to work out that this was the state they were in and type
/// `nxc tick --thread <id>`. A shorter window buys latency nobody is waiting on; a longer one is
/// indistinguishable from the stall it exists to end.
pub const SESSION_LIVENESS_RECHECK_SECS: i64 = 60;

/// When a board blocked on a live session must be looked at again — `now` plus
/// [`SESSION_LIVENESS_RECHECK_SECS`] (nxf 6j6v.858n).
///
/// It PROPAGATES rather than swallowing an unreadable `now`. A `now` this cannot parse is a broken
/// pin (`NXC_NOW`) or a broken clock, and every deadline this file resolves would be wrong the same
/// way; answering "no re-check" there would turn a loud, one-line failure into the exact silent
/// stall this item exists to end.
fn session_liveness_recheck(now: &str) -> Result<String> {
    facade::instant_after(
        now,
        time::Duration::seconds(SESSION_LIVENESS_RECHECK_SECS),
        "the session-liveness re-check",
    )
}

/// The earliest of `candidates` that is still in the FUTURE relative to `now`, or `None`.
///
/// Pulled out so the selection can be tested for itself and so the two things that want a look at a
/// board — a member's reply window and [`SESSION_LIVENESS_RECHECK_SECS`] — are chosen between in
/// one place rather than armed one after the other. Arming is REPLACE-by-thread
/// (`nxs_service::timers::arm`), so two arms in a row are not two jobs: the second wins, and a
/// second arm that happened to be LATER would silently push a real window out.
fn earliest_after<'a>(now: &str, candidates: impl Iterator<Item = &'a str>) -> Option<&'a str> {
    candidates.filter(|d| *d > now).min()
}

/// Move the one-shot job that watches a supervised channel to the next instant a member's clock
/// falls due (nxf 6j6v.nf38) — the twin of [`next_window`], for the other clock this module drives.
///
/// **Why a re-arm is needed at all, in one sentence**: an `at` job fires once, and since a member's
/// window is restarted by its own transcript, the instant the job was scheduled for is no longer the
/// instant anything falls due. Without this the automatic strike is spent by the FIRST sign of life
/// a member gives, which on a one-member channel means nothing ever asks again.
///
/// **Two callers, one per way a window moves.** [`tick`]'s decline, when a transcript moved
/// it; and [`supervisor_hand_out_next_turn`], when a new turn restarted it — a turn whose predecessor
/// settled the set, and therefore ended the job chain that had been watching it. Both hand in the
/// members as they are AFTER the move; a caller passing a pre-move read would find every deadline
/// already spent and schedule nothing.
///
/// **Which instant.** The earliest deadline among the members that have NOT settled — the next
/// moment `member_set_is_settled` could change its answer on its own. A member that has settled is
/// not waited for, and a member with no deadline at all (an undeclared `timeout`) is not waited for
/// on a clock; when nobody is, nothing is scheduled, which is the same "nothing to arm" answer
/// [`next_window`] gives a step that declares no window.
///
/// **Best-effort, and it REPORTS what it could not do** (nxf 6j6v.p3sm). A scheduling failure (no
/// `at`/`atd`, or a platform whose daemon will not run the job at all) costs the automatic check and
/// never the call — exactly as at the fan-out's own scheduling site — but it is no longer only a
/// breadcrumb on stderr: it comes back as a [`ConsequenceClass::TickUnscheduled`] finding for the
/// caller's `warnings`, because a re-arm that has quietly stopped happening is a feature that has
/// quietly reverted, and the two callers here are a verb an app calls and a job that runs unattended
/// — neither has a terminal anybody is reading.
///
/// `None` when there was nothing to arm (no unsettled member with a future deadline) AND when the
/// job was scheduled: both are "nothing failed here".
#[must_use]
fn rearm_member_window(
    ctx: &Ctx,
    channel_thread: &str,
    members: &[ThreadQuorum],
) -> Option<FailedConsequence> {
    rearm_window_with(ctx, channel_thread, members, None)
}

/// [`rearm_member_window`] plus one extra instant the caller wants looked at — the liveness
/// re-check (nxf 6j6v.858n).
///
/// **The union rather than a second arm**, for the reason [`earliest_after`] states. Today the two
/// sets are provably disjoint — a board can only reach the liveness gate once its whole set is
/// settled, and a settled member is `complete || stale` and therefore not a candidate here — so the
/// union is degenerate and this could have been an `if`. It is written as a union anyway, because
/// the day that stops being true is not a day anybody will remember to come back here for, and the
/// failure it would produce is a real window pushed quietly out.
fn rearm_window_with(
    ctx: &Ctx,
    channel_thread: &str,
    members: &[ThreadQuorum],
    also: Option<&str>,
) -> Option<FailedConsequence> {
    let next = earliest_after(
        ctx.now,
        members
            .iter()
            .filter(|m| !m.complete && !m.stale)
            .filter_map(|m| m.deadline.as_deref())
            .chain(also),
    )?;
    // The FUTURE filter lives in `earliest_after`, and it is load-bearing rather than implied. A
    // passed deadline with something outstanding IS `stale`, which the filter above already
    // excluded — but not universally: a member thread whose `expects_reply_from` was emptied is
    // neither `complete` (that needs a non-empty register) nor `stale` (that needs a non-empty
    // `outstanding`), and its deadline can sit in the past. Without it the tick would schedule a job
    // for a past instant, that job would fire, observe the same state, and schedule it again — a
    // tight loop of jobs off a state that is merely stuck. The stuck set is pre-existing and not
    // this function's to fix; turning it into a scheduling loop would be.
    //
    // `?`, not a `let…else`: "nothing to arm" and "nothing failed" are the same answer here, and
    // the early return is exactly what this function's `None` means.
    if let Err(e) = ctx.timer.schedule(
        channel_thread,
        next,
        &crate::timer::tick_command(channel_thread),
    ) {
        let detail = format!(
            "re-scheduling the timeout tick for thread {channel_thread} at {next} failed: {e} — \
             this board's window will not be noticed on its own; run `nxc tick --thread \
             {channel_thread}` to check it by hand"
        );
        // The breadcrumb STAYS beside the finding, exactly as every other site in this module keeps
        // both: a human at a terminal sees it now, and the record travels to whoever is not there.
        eprintln!("warning: {detail}");
        return Some(FailedConsequence::tick_unscheduled(channel_thread, detail));
    }
    None
}

/// Re-read a supervised channel's member threads and move its one-shot job to the next instant one
/// of them falls due — the PAIR both re-arm sites run, so the two cannot report differently.
///
/// A failed re-read and a failed schedule are one finding here, deliberately: the caller's question
/// is "will this board's window be noticed?", and the answer is no either way. Best-effort in both
/// halves, like every other scheduling site in this file — the reply that caused this is persisted
/// and the members are already resumed, so neither failure costs the turn.
fn rearm_after_the_members_moved(
    ctx: &Ctx,
    store: &ChatStore,
    channel_thread: &str,
) -> Option<FailedConsequence> {
    match supervised_member_threads(ctx, store, channel_thread) {
        Ok(restarted) => rearm_member_window(ctx, channel_thread, &restarted),
        Err(e) => {
            let detail = format!(
                "could not re-read the members of thread {channel_thread} to schedule its timeout \
                 tick: {e} — this board's window will not be noticed on its own; run `nxc tick \
                 --thread {channel_thread}` to check it by hand"
            );
            eprintln!("warning: {detail}");
            Some(FailedConsequence::tick_unscheduled(channel_thread, detail))
        }
    }
}

/// **The finding "nothing is doing this workspace's work"** (nxf 6j6v.0j12).
///
/// Asked at the OUTERMOST verbs — `send --to`, `reply --thread`, `tick` — rather than at the
/// scheduling sites, and that placement is the item: [`ConsequenceClass::TickUnscheduled`] is
/// raised where a window fails to be armed, so a workspace that declares no `timeout:` anywhere
/// heard nothing at all while its deadlines and its sync were both dead. This does not need a
/// window; it needs a call.
///
/// The two classes coexist deliberately when a window WAS being armed. They are different
/// statements — "this board has no clock" and "there is nobody to run any of it" — and they call
/// for different responses; suppressing either would put a reader back to inferring the second
/// from the first, which is the substring-matching this whole vocabulary replaces.
///
/// The stderr breadcrumb stays beside the finding, exactly as every other site in this module keeps
/// both: a human at a terminal sees it now, and the record travels to whoever is not there.
#[must_use]
pub(crate) fn service_finding(ctx: &Ctx, thread: &str) -> Option<FailedConsequence> {
    let detail = ctx.timer.service_fault()?.detail();
    eprintln!("warning: {detail}");
    Some(FailedConsequence::service_not_running(thread, detail))
}

/// A tick that decided not to act, with the reason it decided that — always successful, always
/// reporting who had not replied at the moment it looked. Nothing was routed, so all three of the
/// routing's own findings are absent by construction.
fn tick_no_op(thread_id: &str, reason: &str, outstanding: Vec<String>) -> TickReceipt {
    TickReceipt {
        thread_id: thread_id.to_string(),
        acted: false,
        reason: reason.to_string(),
        delivered: None,
        woke: None,
        wake_skipped: None,
        // Nothing was routed, so nothing could be held either.
        held: None,
        warnings: Vec::new(),
        outstanding,
        working_tree: None,
        parked: None,
        handed_on: None,
    }
}

/// Who a thread is still waiting for, **as a caller reads that word**.
///
/// For an ordinary thread this is its own `outstanding`. For a SUPERVISED channel thread (nxf
/// 6j6v.pf6j) it is not: that thread's single expectation is the SUPERVISOR, which is engine
/// machinery and never the answer to "who has not responded". The members hang one level down, one
/// per thread, so the question is asked of them — which is the level it is now genuinely answerable
/// at, since each member owes on a thread of its own instead of sharing one register with the rest.
///
/// **`members` is HANDED IN, not read here** (branch review of PR #337, Code #1). It used to
/// re-derive the set from the store, three lines under the one caller's own "read ONCE, up front"
/// comment — which made that comment false and paid for the same two queries twice. Taking it as an
/// argument is what makes the comment true; an empty slice is a thread with no member threads, i.e.
/// not a supervised channel, which is the same case it always was.
fn outstanding_for_report(q: &ThreadQuorum, members: &[ThreadQuorum]) -> Vec<String> {
    if members.is_empty() {
        return q.outstanding.clone();
    }
    members
        .iter()
        .flat_map(|m| m.outstanding.iter().cloned())
        .collect()
}

/// Every member thread of `channel_thread` is settled — answered, or past its own deadline.
///
/// hq71 §3's rule, and the SET the rebuilt quorum mechanic waits for: not a thread waiting for its
/// replies, but the supervisor waiting for N threads. `false` for a thread with no member threads at
/// all, which is not a supervised channel and has no set to be complete.
fn member_set_is_settled(members: &[ThreadQuorum]) -> bool {
    !members.is_empty() && members.iter().all(|m| m.complete || m.stale)
}

/// **Is a session behind one of these slots still running?** (nxf 6j6v.10yb) — the second half of
/// "settled", asked separately because it is a fact about this MACHINE while everything
/// [`member_set_is_settled`] reads is a fact about the board.
///
/// **Only on a channel that needs the working copy to itself.** `working_tree` is the declaration
/// that says "this work must not share the tree", derived one hop up from the members exactly as
/// [`needs_working_tree`] derives it at the acquire end. On a `shared` channel two live sessions are
/// not a defect — the damage 10yb measured is two writers in one checkout — so nothing changes for
/// one, down to the byte.
///
/// **A `stale` slot is skipped, and that is the answer to "what if the process never dies" — for a
/// slot that never ANSWERED.** The declared `timeout:` is a deadline for an answer, so it can strike
/// only while one is outstanding; gating the lapse on liveness too would wedge the channel with
/// nothing able to release it. A slot that answered inside its window is gated; a slot that answered
/// nothing for its whole window is not.
///
/// **For a slot that DID answer there is no such bound, and saying so is the point** (review of PR
/// #361, Code Quality #1, which found this branch's docs claiming otherwise). Once a member is
/// `complete` its window can never strike again — `stale` needs a non-empty `outstanding` — and
/// [`rearm_member_window`] excludes `complete` members from the instants it schedules a job for, so
/// on one member per step nothing is scheduled at all. The wait therefore ends when the session
/// announces its own end ([`session_ended`]) or when somebody asks again (`nxc tick --thread <id>`,
/// which reports [`TICK_WAITING_FOR_A_SESSION`] rather than "nothing to do"). That is a STALL and
/// never a wrong advance — the gate fails closed, holding the checkout — and an automatic re-check
/// is tracked as nxf 6j6v.858n rather than bolted on here (it needs a clock, and the one this house
/// has does not fire on the platform all of this was measured on — nxf 6j6v.p3sm).
///
/// **Two sources, in this order.** The session's own announcement (`session_map.ended`, written by
/// [`session_ended`]) is what covers a normal end, because process liveness cannot: the
/// announcement is made BY the ending session, and its process is necessarily still alive while it
/// speaks. [`Worker::session_is_running`](crate::worker::Worker::session_is_running) is the backstop
/// for a session killed hard enough that it never announced anything — and it answers `false` for
/// every worker that cannot tell, which is what keeps this gate from stalling a channel on a runtime
/// that has no processes to look at.
fn a_member_session_is_still_writing(
    ctx: &Ctx,
    store: &ChatStore,
    channel: Option<&ChannelDecl>,
    members: &[ThreadQuorum],
) -> Result<bool> {
    let Some(channel) = channel else {
        return Ok(false);
    };
    if !ctx.defs.channel_needs_working_tree(channel) {
        return Ok(false);
    }
    for member in members {
        if member.stale {
            continue;
        }
        for internal in store.unended_sessions_in_thread(&member.thread_id)? {
            if ctx.worker.session_is_running(&internal) {
                return Ok(true);
            }
        }
    }
    Ok(false)
}

/// The reason string a tick that MOVED A FLOW ON reports — not `acted` (it ran no `on_complete`
/// routing and delivered nothing) and not a no-op either (nxf 6j6v.rs9k). Named once, because the
/// CLI's human rendering branches on it and a second spelling would silently print
/// "nothing to do" over a flow that just started its next step.
pub(crate) const TICK_ADVANCED: &str = "advanced";

/// The reason a tick declines when the ONLY thing left is a live process (nxf 6j6v.10yb; review of
/// PR #361, Code Quality #1). Named once, for [`TICK_ADVANCED`]'s reason: the CLI branches on it to
/// print what the board is waiting for instead of "nothing to do", and a second spelling would let
/// the two drift.
///
/// **What it tells a reader, and it is the honest form of a sentence this branch got wrong once**:
/// the set is settled, the flow is ready to move, and it is waiting for a session to finish.
///
/// It is NOT the channel's declared `timeout:` that ends that wait — that is a deadline for an
/// answer which has already arrived — and it is not the member-window re-arm either: a member that
/// has replied is `complete` and therefore not among its candidates, so on one member per step it
/// arms nothing. Both of those were once the whole story, and the wait had no clock at all. Since
/// nxf 6j6v.858n a decline that reaches this reason schedules its OWN re-check
/// [`SESSION_LIVENESS_RECHECK_SECS`] later, in both paths, so the wait ends when the session
/// announces its end, when its process is found gone, or — unchanged — whenever somebody asks by
/// hand.
pub(crate) const TICK_WAITING_FOR_A_SESSION: &str = "waiting_for_a_session";

/// **What a settled set MEANS for the thread [`tick`] is looking at** (nxf 6j6v.rs9k) — three
/// answers where the code read two, and the reason a lapsed middle step no longer ends a flow.
///
/// A settled set ends a `parallel` channel: it asked everyone at once, so nothing is left to ask.
/// An ORDERED one asked exactly one step, and `settled` there is `complete || stale` — the same
/// two-branch reading [`crate::channel::Flow::Sequential`]'s own doc declares ("each started only
/// once the one before it has settled"). Reading "settled" as "finished" therefore consolidated a
/// flow the moment any step's window ran out, and every step behind that one never ran.
#[derive(Debug)]
enum TickMove {
    /// Nothing is due. The tick re-arms the window that watches the set and declines.
    Waiting,
    /// The turn is over: consolidate and deliver, which is what every `due` tick did before this
    /// item and what a lapse on the LAST step still does — there is no step after it to start, so
    /// summarising IS the honest answer (and 6j6v.hq71's empty-run case rests on exactly that).
    Consolidate,
    /// The deepest step of an ordered flow has SETTLED and the declared order has a step after it:
    /// the flow advances instead of ending.
    ///
    /// **Two ways to settle, and both reach here** (nxf 6j6v.858n widened this from one). A step
    /// that let its window run out is [`lapsed`](TickMove::Advance::lapsed) — nxf 6j6v.rs9k's case,
    /// where the flow moves on WITHOUT an answer. A step that ANSWERED and was left standing here
    /// is the other: the PUSH path a reply takes declined, and the only thing that ever declines a
    /// settled ordered set is the liveness gate of nxf 6j6v.10yb. Until 858n this second shape fell
    /// through to [`Consolidate`](TickMove::Consolidate), which is why the escape hatch PR #361
    /// documented — *run `nxc tick --thread <id>`* — did not do what it says: on a board with a
    /// return address it FOLDED the round and the remaining steps never ran, and on one without it
    /// answered `no_return_address` and changed nothing at all. Neither is "the flow gets released".
    Advance {
        /// The slot thread the flow is standing on — handed to [`supervisor_consider_set`] as "the
        /// one that just settled", the same way a real reply's thread is, so where the flow stands
        /// is told to the supervisor rather than re-derived by it.
        settled_slot: String,
        /// The step that thread served, for the report. A step is named by its target, exactly as
        /// the declaration names it.
        settled_step: String,
        /// The step being started for it, likewise for the report.
        next_step: String,
        /// It settled by letting its window RUN OUT rather than by answering — the half that is a
        /// finding in its own right, because a declared step was asked and said nothing.
        lapsed: bool,
    },
}

/// Which of [`TickMove`]'s three this thread is in.
///
/// **The wide/narrow seam of the tick, in one place.** The settledness question is asked of EVERY
/// slot (see the long comment at the call site for why that read stays wide); the ORDERED question
/// — which step settled the set, and is there one after it — is asked of [`current_pass`], which is
/// the only list that can answer it. A pass read too wide reports steps as already run and the
/// supervisor skips them, which is the failure `supervisor_consider_set` uses the raw pass to avoid.
///
/// **A step that ANSWERED advances from here too, and that is nxf 6j6v.858n's doing.** This
/// paragraph used to say the opposite — *"only a LAPSE advances from here, never a step that merely
/// answered"* — on the reasoning that an answered step has already been through the supervisor
/// synchronously, in the write path of its own reply, so a settled answered step whose successor was
/// never opened could only mean that successor FAILED to start, and re-opening it here would be a
/// retry invented at the one seam that runs unattended.
///
/// **That reasoning had a hole, and it was the liveness gate of nxf 6j6v.10yb.** On a channel
/// declared `working_tree: exclusive` the supervisor DECLINES a settled answered step while the
/// step's session still has a live process — so "settled, answered, successor never opened" has a
/// second, entirely healthy cause, and it is the commonest one. Reading it as a failed start meant
/// the escape hatch this verb documents did the wrong thing twice over: with a return address it
/// FOLDED the round and every remaining step never ran, and without one it answered
/// `no_return_address` and changed nothing. Neither is "the flow gets released".
///
/// **What is NOT reachable, and it is by construction rather than by a guard**: the retry the old
/// paragraph feared, for a ROLE step. [`open_flow_step`] opens the slot thread BEFORE it triggers,
/// so a start that failed leaves an open, unanswered slot behind — the set is then not settled,
/// `Waiting` is the move, and no second attempt is made. `a_failed_step_start_is_not_retried_by_a_
/// later_tick` holds that.
///
/// What IS reachable is the narrow case where nothing was opened at all: a step naming a nested
/// CHANNEL whose declaration has since gone missing, or a channel whose `timeout:` no longer parses
/// (both fail before the first write). A tick run over that thread again will try the step again —
/// and that is recovery from a declaration that has since been fixed, which is what this verb's own
/// doc says a hand-run tick is for. Nothing UNATTENDED retries it either way: the liveness clock
/// (858n) arms only while a session is still alive, and a failed start arms nothing at all.
///
/// Everything else falls back to [`TickMove::Consolidate`], which is what the verb did before this
/// item — an undeclared channel, a `parallel` one, a thread whose pass cannot be derived at all
/// (whose consolidation deliberately over-includes, see [`slots_to_consolidate`]), and a thread that
/// has already been consolidated (which the marker check of step 4 then names properly).
fn tick_move(
    ctx: &Ctx,
    store: &ChatStore,
    q: &ThreadQuorum,
    members: &[ThreadQuorum],
) -> Result<TickMove> {
    if members.is_empty() {
        // Not a supervised channel: its own register is all there is, unchanged.
        return Ok(if q.complete || q.stale {
            TickMove::Consolidate
        } else {
            TickMove::Waiting
        });
    }
    if !(q.complete || member_set_is_settled(members)) {
        return Ok(TickMove::Waiting);
    }
    // **A STEPPED channel comes through here too** (nxf 6j6v.553s (d)). It has to: the tick is the
    // only path a lapsed window has into the flow, and a declared cycle stalls at a silent step
    // exactly as a flat order does. What it does NOT do here is route — the executor of
    // `TickMove::Advance` hands the settled slot straight to [`supervisor_consider_set`], which owns
    // the state machine, so this only has to decide THAT there is somewhere to go.
    let Some(channel) = declared_channel_of(ctx, q)
        .filter(|c| c.is_stepped() || c.flow == crate::channel::Flow::Sequential)
    else {
        return Ok(TickMove::Consolidate);
    };
    // Still the supervisor's turn to answer up there? Once a consolidation has run, the register
    // names a `__synth__`/`__delivered__` marker instead, and starting a further step over a turn
    // the requester was already handed would be a second flow on a finished thread.
    if q.expects != [supervisor_qualified(ctx.origin)] {
        return Ok(TickMove::Consolidate);
    }
    let pass = current_pass(store, Some(channel), q, members.to_vec())?;
    // The DEEPEST step this pass reached: `current_pass` collects in declared order and stops at the
    // first step nothing serves, so the last element is the step the flow is standing on. On a
    // STEPPED channel the run is collected in `supervised_children` order, which is thread-id order
    // — and an ordered flow mints one slot per call, so the last element is likewise the newest.
    let Some(last) = pass.last() else {
        return Ok(TickMove::Consolidate);
    };
    // **SETTLED, either way** (nxf 6j6v.858n). It used to be `if !last.stale { Consolidate }`, so
    // only a lapsed step could move the flow on from here — and a step that had ANSWERED, which is
    // the state the liveness gate leaves a board in, was folded away with its successors never run.
    // A slot that is neither is not settled at all and must not move anything: the guard above lets
    // one through when the CHANNEL THREAD is complete, which says nothing about the members.
    if !(last.complete || last.stale) {
        return Ok(TickMove::Consolidate);
    }
    // **The stepped fork answers the same two questions from the declaration's own graph.** Which
    // step settled is the slot's recorded mark rather than its target name (two steps may share a
    // target), and what follows is that step's `next` — the ceiling and the back edge are decided
    // one level down, where the verdict is readable, so a lapse (which carries no verdict) is
    // exactly the `next` case here.
    if channel.is_stepped() {
        let Some(mark) = store.flow_mark(&last.thread_id)? else {
            return Ok(TickMove::Consolidate);
        };
        let Some(next_step) = channel.step(&mark.step).and_then(|s| s.next.clone()) else {
            return Ok(TickMove::Consolidate);
        };
        return Ok(TickMove::Advance {
            settled_slot: last.thread_id.clone(),
            settled_step: mark.step,
            next_step,
            lapsed: last.stale,
        });
    }
    let steps = flow_steps(channel, q.opener.as_deref());
    let Some(settled_step) = slot_target(last, q.channel_id.as_deref()) else {
        return Ok(TickMove::Consolidate);
    };
    let Some(at) = steps.iter().position(|s| *s == settled_step) else {
        return Ok(TickMove::Consolidate);
    };
    Ok(match steps.get(at + 1) {
        Some(next_step) => TickMove::Advance {
            settled_slot: last.thread_id.clone(),
            settled_step,
            next_step: next_step.clone(),
            lapsed: last.stale,
        },
        None => TickMove::Consolidate,
    })
}

/// **The steps of an ordered channel's pass that never answered** (nxf 6j6v.rs9k) — the honest half
/// of "a lapsed step advances the flow".
///
/// A step whose window ran out contributes nothing to [`collected_replies`], so without this it
/// vanishes: the requester is handed a fold or a pass-through of everyone ELSE's answers with no
/// sign that a declared step was asked and stayed silent. The consolidation still delivers — that
/// is the decision — but it says what it is missing, in the one defined place a caller reads for
/// exactly that (nxf 6j6v.93zd's `warnings`, and its "ALL of what did not happen" rule).
///
/// **The slots are [`slots_to_consolidate`]'s, deliberately** — the same list the delivery is folded
/// from, so what is reported and what is delivered can never describe different sets. Its
/// over-inclusion on an underivable pass is inherited with it: the report may then name a lapsed
/// slot of an earlier pass, which is the same direction that function argues for at its own site.
///
/// **`Flow::Sequential` only, and that is not timidity.** On a `parallel` channel a lapse means
/// "that member did not answer" and nothing more — nobody was skipped over, no order was cut short,
/// and `outstanding` on the receipt already names who is missing. In an ordered flow the lapse is
/// load-bearing: it is what let the flow move on (or end), so it belongs in the record of what this
/// call did.
fn lapsed_step_findings(
    ctx: &Ctx,
    store: &ChatStore,
    channel_q: &ThreadQuorum,
) -> Result<Vec<FailedConsequence>> {
    let Some(channel) =
        declared_channel_of(ctx, channel_q).filter(|c| c.flow == crate::channel::Flow::Sequential)
    else {
        return Ok(Vec::new());
    };
    let mut findings = Vec::new();
    for slot in slots_to_consolidate(ctx, store, channel_q)? {
        if !slot.stale {
            continue;
        }
        let Some(step) = slot_target(&slot, channel_q.channel_id.as_deref()) else {
            continue;
        };
        findings.push(FailedConsequence::step_unanswered(
            Some(&slot.thread_id),
            format!(
                "step {step:?} of channel {:?} gave no answer inside its declared window; the \
                 consolidation carries none from it",
                channel.name
            ),
        ));
    }
    Ok(findings)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// **The stored occasion and the JSON spell it the same way.** `as_str` is what a refused park
    /// is stamped with and what the tick compares a row against; the serde tag is what a receipt
    /// and `nxc status --json` carry. A variant renamed in one and not the other would leave rows
    /// nothing ever clears — `ParkRefusal::kind`'s test, for its reason, on the other half.
    #[test]
    fn every_occasion_names_itself_the_way_json_does() {
        for occasion in [
            ParkOccasion::StrandedEscalation,
            ParkOccasion::AvailabilityBoundary,
            ParkOccasion::PastItsBound,
            ParkOccasion::DiedInsideItsBound,
            ParkOccasion::Withdrawn,
        ] {
            let json = serde_json::to_value(occasion).unwrap();
            assert_eq!(json, serde_json::json!(occasion.as_str()), "{json}");
        }
    }

    // ---- the measurements (nxf 6j6v.xb24) -------------------------------------------------------
    //
    // Two stopwatches over one staging, both `#[ignore]`d. They are stopwatches and not assertions
    // on purpose: a wall-clock number is not something CI can be held to on borrowed hardware, and a
    // timing test that fails on a loaded machine teaches everyone to re-run the suite until it is
    // green. Run them by hand, with `-- --ignored --nocapture`.

    /// How many threads, each with one session of its own, both measurements stage.
    const MEASURED_THREADS: usize = 20;
    /// How many timed repetitions each of them takes.
    const MEASURED_REPETITIONS: usize = 200;
    /// The instant both measurements run at — every window in the staging is well ahead of it.
    const MEASURED_NOW: &str = "2026-09-18T09:00:00Z";

    /// **The claim area both measurements are taken over**: [`MEASURED_THREADS`] threads under one
    /// root, each OWING an answer, each with one session of its own whose pid file says `pid`.
    ///
    /// Shared so the two numbers are two readings of the same thing rather than two set-ups that
    /// resemble each other. Returns the store, the claim root and every thread of the area, in the
    /// order [`ChatStore::work_scope_threads`] returns them.
    ///
    /// The register is set for the same reason the pid files are written: `holder_is_provably_dead`
    /// reads it, and a claim area where nothing is outstanding would take its cheapest exit and
    /// measure almost nothing.
    fn a_measured_claim_area(
        root: &std::path::Path,
        db_path: &str,
        pid: u32,
    ) -> (ChatStore, String, Vec<String>) {
        let logs = crate::worker::agent_logs_dir(root);
        std::fs::create_dir_all(&logs).unwrap();
        let mut store = ChatStore::open(db_path, 1).expect("open the store on disk");
        let claim_root = "t-0000".to_string();
        for n in 0..MEASURED_THREADS {
            let thread = format!("t-{n:04}");
            store.open_thread(
                &thread,
                &crate::model::ThreadRoot {
                    origin: "local".into(),
                    channel_id: "c-1".into(),
                    opener: "local/pm".into(),
                    created: "2026-09-18T08:00:00Z".into(),
                    // Every thread but the first hangs under it, so the claim area IS the subtree.
                    parent: (n > 0).then(|| claim_root.clone()),
                },
                "local/pm",
            );
            store.set_expects_reply_from(&thread, r#"["local/coder"]"#, "local/pm");
            let session = format!("m-measure-{n:04}");
            store.create_pending_session(&session, "coder").unwrap();
            store
                .record_session_thread(&session, Some(&thread))
                .unwrap();
            // The pid file `SidecarWorker::session_is_running` reads, so every probe takes the LONG
            // path — the file exists, it parses, and the signal is actually sent.
            std::fs::write(logs.join(format!("{session}.pid")), format!("{pid}\n")).unwrap();
        }
        let threads = store
            .work_scope_threads(&WorkScope::Thread(claim_root.clone()))
            .expect("the claim area reads");
        assert_eq!(threads.len(), MEASURED_THREADS, "{threads:?}");
        (store, claim_root, threads)
    }

    /// The sorted samples, as a line a person can read, and the median for the caller to judge.
    fn report_the_samples(what: &str, mut samples: Vec<std::time::Duration>) -> f64 {
        samples.sort();
        let ms = |d: std::time::Duration| d.as_secs_f64() * 1000.0;
        let median = ms(samples[samples.len() / 2]);
        println!(
            "{what} over {MEASURED_THREADS} sessions, {MEASURED_REPETITIONS} repetitions: \
             min {:.3} ms, median {median:.3} ms, max {:.3} ms",
            ms(samples[0]),
            ms(samples[samples.len() - 1]),
        );
        median
    }

    /// **WHAT ONE LIVENESS PASS OVER A CLAIM AREA COSTS** — the first of the two measurements nxf
    /// 6j6v.xb24 was told to take before it changed any behaviour, kept because the numbers are the
    /// whole argument for the behaviour they authorised.
    ///
    /// **It measures [`sessions_still_running`] and nothing else** — one clause of the check the
    /// sweep now runs per tick, and the only one that leaves the process. The whole check is
    /// [`what_the_whole_dead_holder_check_costs`] below, which is the number the threshold is
    /// really about; this one stays because it is the one that answers *what does ASKING THE
    /// OPERATING SYSTEM cost*, separately from the reads around it.
    ///
    /// Every pid written here is this test process's own, so every probe takes the LONGER path: the
    /// file exists, it parses, and the signal check answers "alive". A claim area of dead sessions
    /// is cheaper, and a measurement of the cheaper case would not have decided anything.
    ///
    /// What it measured on the development machine, in a DEBUG build (the slower of the two this
    /// repo builds, and so the conservative direction): min 1.277 ms, **median 1.354–1.368 ms** over
    /// four runs, max 2.568 ms.
    ///
    /// ```text
    /// cargo test -p nexus-chat --lib \
    ///     orchestration::tests::what_one_liveness_pass_over_a_claim_area_costs \
    ///     -- --ignored --nocapture
    /// ```
    #[test]
    #[ignore = "a measurement, not an assertion — run it by hand with --ignored --nocapture"]
    fn what_one_liveness_pass_over_a_claim_area_costs() {
        const THREADS: usize = MEASURED_THREADS;
        const REPETITIONS: usize = MEASURED_REPETITIONS;

        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path();
        let db = root.join("db.sqlite");
        let db_path = db.to_str().unwrap().to_string();
        // A pid that is genuinely alive — this very process — so `kill(pid, 0)` takes the answering
        // path rather than the early "no such file" one.
        let (store, _claim_root, threads) =
            a_measured_claim_area(root, &db_path, std::process::id());

        let worker = crate::worker::SidecarWorker {
            sidecar: root.join("main.mjs"),
            cwd: root.to_path_buf(),
        };
        let defs = Definitions::default();
        let timer = crate::timer::DisabledTimer;
        let namer = crate::naming::DryNamer;
        let ctx = Ctx {
            now: MEASURED_NOW,
            origin: "local",
            actor: "carsten",
            session: None,
            hop: 0,
            defs: &defs,
            worker: &worker,
            timer: &timer,
            namer: &namer,
            db_path: &db_path,
            project_claude_md: None,
            module_primes: None,
            machines: None,
        };

        // One pass outside the timing loop: it is the one that pays for SQLite's page cache and for
        // the statement this store has not prepared yet, and including it would report a cost the
        // per-tick caller never meets again.
        let warm = sessions_still_running(&ctx, &store, &threads).unwrap();
        assert_eq!(warm.len(), THREADS, "every session answers as running");

        let mut samples: Vec<std::time::Duration> = Vec::with_capacity(REPETITIONS);
        for _ in 0..REPETITIONS {
            let at = std::time::Instant::now();
            let running = sessions_still_running(&ctx, &store, &threads).unwrap();
            samples.push(at.elapsed());
            assert_eq!(running.len(), THREADS);
        }
        report_the_samples("one liveness pass", samples);
    }

    /// **WHAT THE WHOLE DEAD-HOLDER CHECK COSTS** — [`holder_is_provably_dead`] END TO END, which is
    /// the thing the sweep actually runs per tick per waiting commission and therefore the thing the
    /// threshold is about (fix round 1 of this item's review, Finding 1).
    ///
    /// The first cut measured [`sessions_still_running`] alone and attached its number to the whole
    /// check. The rest of the check is not free and was never timed: the claim area's subtree read,
    /// the quorum read that says which threads OWE an answer, the newest session of each owing
    /// thread, and the standing holds. Two of those were an N+1 when this was written, which is the
    /// other half of the same finding — they are one bulk read each now
    /// ([`ChatStore::newest_sessions_in_threads`], [`ChatStore::interrupted_threads`]), and this is
    /// the measurement that says what the result costs.
    ///
    /// **Staged so that every clause RUNS.** The check answers `false` at the first clause that is
    /// not met, so a staging that trips an early one would measure almost nothing. Here the worker
    /// answers liveness, all twenty threads owe an answer, every pid file exists and parses and
    /// names a process that is REAPED — so each of the twenty probes does its `read_to_string` and
    /// its `kill(2)` and answers "gone" — no session has announced an end, and nothing is on hold.
    /// The check therefore runs all five clauses, reaches `true`, and the number below is the whole
    /// of it.
    ///
    /// **The threshold it was run against** (controller ruling, 2026-09-18): a median below 50 ms on
    /// the development machine continues; at or above it the check is not affordable per tick and
    /// the item stops. What it measured in a DEBUG build (the slower of the two profiles this repo
    /// builds, and so the conservative direction): min 1.851 ms, **median 1.971 ms**, max 2.871 ms —
    /// about 25 times under the line. One run, over 200 repetitions, and it is the run the two
    /// prose sites that quote this number ([`holder_is_provably_dead`], [`drain_recheck_instant`])
    /// quote too; three places disagreeing about one measurement is how the final review of this
    /// branch found them.
    ///
    /// ```text
    /// cargo test -p nexus-chat --lib \
    ///     orchestration::tests::what_the_whole_dead_holder_check_costs \
    ///     -- --ignored --nocapture
    /// ```
    #[test]
    #[ignore = "a measurement, not an assertion — run it by hand with --ignored --nocapture"]
    fn what_the_whole_dead_holder_check_costs() {
        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path();
        let db = root.join("db.sqlite");
        let db_path = db.to_str().unwrap().to_string();

        // A pid that certainly names nothing: a child this process started, waited for and reaped.
        // Every probe still reads the file, parses it and sends the signal — the long path — and
        // gets "gone" for an answer, which is what lets the check run past its liveness clause.
        let mut child = std::process::Command::new("/bin/sh")
            .args(["-c", "exit 0"])
            .spawn()
            .expect("spawn a process to reap");
        let reaped = child.id();
        child.wait().expect("reap it");

        let (store, claim_root, _threads) = a_measured_claim_area(root, &db_path, reaped);
        let scope = WorkScope::Thread(claim_root);

        let worker = crate::worker::SidecarWorker {
            sidecar: root.join("main.mjs"),
            cwd: root.to_path_buf(),
        };
        let defs = Definitions::default();
        let timer = crate::timer::DisabledTimer;
        let namer = crate::naming::DryNamer;
        let ctx = Ctx {
            now: MEASURED_NOW,
            origin: "local",
            actor: "carsten",
            session: None,
            hop: 0,
            defs: &defs,
            worker: &worker,
            timer: &timer,
            namer: &namer,
            db_path: &db_path,
            project_claude_md: None,
            module_primes: None,
            machines: None,
        };

        // The warm-up, outside the loop for the reason the measurement beside it gives — and it is
        // also the proof that what is being timed is the WHOLE check: an answer of `true` is only
        // reachable through all five clauses.
        assert!(
            holder_is_provably_dead(&ctx, &store, &scope).unwrap(),
            "the staging has to reach the end of the check, or the number means nothing"
        );

        let mut samples: Vec<std::time::Duration> = Vec::with_capacity(MEASURED_REPETITIONS);
        for _ in 0..MEASURED_REPETITIONS {
            let at = std::time::Instant::now();
            let dead = holder_is_provably_dead(&ctx, &store, &scope).unwrap();
            samples.push(at.elapsed());
            assert!(dead);
        }
        let median = report_the_samples("the whole dead-holder check", samples);
        println!("the controller's threshold is 50 ms; this run's median is {median:.3} ms");
    }

    // ---- fix round 1, Finding 2 (review of nxf 6j6v.7hqc): the safety note must not claim a
    // commit that did not happen ------------------------------------------------------------------

    #[test]
    fn the_safety_note_never_claims_a_commit_that_did_not_happen() {
        let committed = crate::park::Parked {
            branch: "nxs/park/thread-x/20260905T090000Z".into(),
            commit: "abc123".into(),
            base_branch: "main".into(),
            base_commit: "def456".into(),
            created_branch: true,
            committed: true,
        };
        let note = park_safety_note("thread:x", &committed);
        assert!(note.contains("committed on branch"), "{note}");
        assert!(note.contains(&committed.branch), "{note}");
        assert!(note.contains(&committed.commit), "{note}");

        // Reachable two ways since `nxf 6j6v.7hqc`: a clean detached HEAD (a branch was created,
        // nothing committed onto it) and a clean tree already on the base branch (no branch
        // created either). Both share the one property this test pins: NOTHING was committed, so
        // the note must not say so.
        let clean = crate::park::Parked {
            committed: false,
            ..committed
        };
        let note = park_safety_note("thread:x", &clean);
        assert!(
            !note.contains("committed on branch"),
            "nothing was committed at this park: {note}"
        );
        assert!(note.contains("had nothing uncommitted"), "{note}");
        assert!(note.contains(&clean.branch), "{note}");
        assert!(note.contains(&clean.commit), "{note}");
    }

    // ---- the declared-hurdle gate's TIME budget (PR #391 review, Code Quality #2) --------------

    fn hurdle(name: &str) -> crate::precondition::Precondition {
        crate::precondition::Precondition {
            name: name.to_string(),
            run: format!("cmd-{name}"),
            expect: None,
        }
    }

    fn passes() -> crate::precondition::PreconditionOutcome {
        crate::precondition::PreconditionOutcome::Ran {
            status: Some(0),
            stdout: String::new(),
            stderr: String::new(),
        }
    }

    #[test]
    fn every_hurdle_is_asked_while_the_budget_lasts() {
        let asked = std::cell::RefCell::new(Vec::new());
        let refusal = ask_declared_hurdles(
            &[hurdle("a"), hurdle("b"), hurdle("c")],
            Duration::from_secs(60),
            |c| {
                asked.borrow_mut().push(c.to_string());
                passes()
            },
        );
        assert!(refusal.is_none());
        assert_eq!(asked.into_inner(), vec!["cmd-a", "cmd-b", "cmd-c"]);
    }

    #[test]
    fn a_hurdle_is_never_asked_once_the_step_budget_is_spent() {
        // The property the bound exists for: the engine holds its store mutex across this loop, so
        // a channel that declares many hurdles must not be able to stall every other call through
        // the handle for `N × bound`. Driven with a budget of milliseconds and one slow answer, so
        // it is deterministic and costs a tenth of a second rather than a minute.
        let asked = std::cell::RefCell::new(Vec::new());
        let refusal = ask_declared_hurdles(
            &[hurdle("slow"), hurdle("b"), hurdle("c")],
            Duration::from_millis(50),
            |c| {
                asked.borrow_mut().push(c.to_string());
                if c == "cmd-slow" {
                    std::thread::sleep(Duration::from_millis(80));
                }
                passes()
            },
        )
        .expect("the gate stops rather than running on");
        assert_eq!(
            asked.into_inner(),
            vec!["cmd-slow"],
            "neither of the two after it was ASKED — which is the whole bound, and it holds \
             however many are declared"
        );
        assert_eq!(
            refusal.hurdle, "b",
            "the refusal names the one that never ran"
        );
        assert_eq!(
            refusal.kind,
            crate::precondition::RefusalKind::Unrunnable,
            "…as UNRUNNABLE, not as a verdict: the project's rule never spoke, so blaming it would \
             send the reader to fix the wrong thing"
        );
        assert!(refusal.output.contains("budget"), "{refusal:?}");
    }

    #[test]
    fn a_hurdle_that_refuses_still_wins_over_the_budget() {
        // The budget is a backstop, not a reordering: a real verdict from a hurdle that DID run is
        // still what comes back, with its own kind.
        let refusal = ask_declared_hurdles(&[hurdle("a")], Duration::from_secs(60), |_| {
            crate::precondition::PreconditionOutcome::Ran {
                status: Some(1),
                stdout: "no".into(),
                stderr: String::new(),
            }
        })
        .expect("refused");
        assert_eq!(refusal.kind, crate::precondition::RefusalKind::Verdict);
    }

    #[test]
    fn a_channel_with_no_declared_hurdles_asks_nothing_and_spends_no_budget() {
        let mut calls = 0;
        assert!(ask_declared_hurdles(&[], Duration::from_millis(0), |_| {
            calls += 1;
            passes()
        })
        .is_none());
        assert_eq!(calls, 0, "an empty list is not a zero-budget refusal");
    }

    /// **What a parked commission comes back to, and why it is not always the lease's own expiry**
    /// (review of PR #376, Code Quality #1 / Integrity #2 — the bug — and Test Quality #3, which
    /// named the absence of this test as the reason it got through).
    ///
    /// The two callers of [`drain_recheck_instant`] disagreed: one armed a minute out for a holder
    /// whose bound had passed but whose process had not, the other two hours out for the same
    /// holder — and since `arm_the_lease_bound` REPLACES a thread's pending window, the fast one was
    /// overwritten by the slow one after a single check.
    ///
    /// **The lease's own expiry no longer wins on its own since nxf 6j6v.xb24**, and this test moved
    /// with the rule rather than being deleted by it. The holder of an unexpired lease can DIE
    /// inside it, which is the whole of that item; waiting out its bound is exactly the two hours of
    /// dead time it removes. So the cadence is now a candidate on every call and the bound wins only
    /// when it is the sooner of the two — which the third assertion below pins.
    #[test]
    fn a_parked_commission_waits_on_the_lease_but_on_the_liveness_clock_for_a_live_holder() {
        let now = "2026-08-22T09:00:00Z";
        let holder_expires = "2026-08-22T11:00:00Z";

        assert_eq!(
            drain_recheck_instant(now, holder_expires, None).unwrap(),
            session_liveness_recheck(now).unwrap(),
            "an unexpired LEASE two hours out: look again on the cadence, because its holder can \
             die inside it (nxf 6j6v.xb24)"
        );
        assert_eq!(
            drain_recheck_instant(now, holder_expires, None).unwrap(),
            "2026-08-22T09:01:00Z",
            "…which is one minute, spelled out so a change to the cadence is a change to this test"
        );
        assert_eq!(
            drain_recheck_instant(now, "2026-08-22T09:00:30Z", None).unwrap(),
            "2026-08-22T09:00:30Z",
            "a bound that runs out SOONER than the cadence is still the sooner look"
        );
        // An expiry already behind us — the shape the PR #376 bug produced — is not a candidate at
        // all: arming a tick in the past fires it at once, for the same answer.
        assert_eq!(
            drain_recheck_instant(now, "2026-08-22T08:00:00Z", None).unwrap(),
            "2026-08-22T09:01:00Z",
            "an expiry already behind us must not arm a tick in the past either"
        );
    }

    /// **A CONTENDED lease ends its wait at the earliest of the clocks** (nxf 6j6v.de9s).
    ///
    /// The park deadline is folded into this one function rather than armed beside it, for the
    /// reason the test above exists at all: `arm_the_lease_bound` REPLACES a thread's pending
    /// window, so two alarms on one thread are not two alarms — they are whichever the call order
    /// left standing. These assertions are what makes "the earliest" a property rather than an
    /// intention.
    #[test]
    fn a_contended_lease_comes_back_at_whichever_clock_runs_out_first() {
        let now = "2026-09-05T09:00:00Z";
        let holder_expires = "2026-09-05T11:00:00Z";

        // Contention that began long enough ago that the park deadline is already behind us, with a
        // lease that still stands: a passed instant is not a candidate, so the look is the cadence —
        // which is the very next tick's worth of waiting rather than the lease's two hours.
        assert_eq!(
            drain_recheck_instant(now, holder_expires, Some("2026-09-05T07:00:00Z")).unwrap(),
            "2026-09-05T09:01:00Z",
        );
        // A park deadline still AHEAD and sooner than the cadence is what the wait ends on: it is
        // the instant the holder's work may be put away, and there is nothing to gain by looking
        // after it.
        assert_eq!(
            drain_recheck_instant(
                "2026-09-05T09:24:50Z",
                holder_expires,
                Some("2026-09-05T08:55:00Z")
            )
            .unwrap(),
            "2026-09-05T09:25:00Z",
            "the park deadline is 30m after CONTENTION began, and it beats both the lease and the \
             cadence when it falls first"
        );
        // A LEASE that runs out before either keeps its own instant — every clock here is an
        // additional way this wait can end, never a later one substituted for an earlier.
        assert_eq!(
            drain_recheck_instant(now, "2026-09-05T09:00:20Z", Some("2026-09-05T08:55:00Z"))
                .unwrap(),
            "2026-09-05T09:00:20Z",
        );
    }

    /// **A REFUSED park is retried a liveness re-check out, never at its passed deadline** (nxf
    /// 6j6v.8bv9).
    ///
    /// The park step at the front of every tick is what retries a refused park, so the next look is
    /// the next attempt — and the three places that arm it (the park itself, the sweep, the acquire
    /// path) have to name the same instant, because arming replaces by key. The deadline has no say
    /// here: it is behind us by construction, and arming it would fire at once and refuse again.
    ///
    /// **Since nxf 6j6v.xb24 nothing has to TELL this function that a park was refused** — the
    /// cadence is a candidate on every call, so the answer for a refused park is the answer it
    /// always was, reached by the general rule instead of by a flag every caller had to read a row
    /// to set. These assertions are unchanged in what they claim and are what proves that.
    #[test]
    fn a_refused_park_comes_back_on_the_liveness_cadence_and_never_in_the_past() {
        let now = "2026-09-05T10:01:00Z";
        let retry = "2026-09-05T10:02:00Z";
        let two_hours_out = "2026-09-05T11:00:00Z";
        // Contended, deadline long passed, lease still standing: the retry, not the deadline.
        assert_eq!(
            drain_recheck_instant(now, two_hours_out, Some("2026-09-05T09:30:00Z")).unwrap(),
            retry
        );
        // Not contended at all (an operation on hold at an availability boundary): the retry, not
        // the holder's bound — which is what would otherwise overwrite it.
        assert_eq!(
            drain_recheck_instant(now, two_hours_out, None).unwrap(),
            retry
        );
        // A holder bound that runs out SOONER than the retry is still the sooner look.
        assert_eq!(
            drain_recheck_instant(now, "2026-09-05T10:01:30Z", None).unwrap(),
            "2026-09-05T10:01:30Z"
        );
        // …and one already behind us is not: that would be a tick at once, refused again.
        assert_eq!(
            drain_recheck_instant(now, "2026-09-05T10:00:00Z", None).unwrap(),
            retry
        );
    }

    /// **[`earliest_after`] picks the soonest FUTURE instant out of everything the caller wants
    /// looked at** (review of PR #375, Test Quality #1 / Integrity #3).
    ///
    /// It is asked here rather than through a board, because the case that matters — a member's
    /// reply window and 858n's liveness re-check both live and both in the future — is one no board
    /// can currently reach: the liveness gate is only consulted once the whole set is SETTLED, and a
    /// settled member is `complete || stale` and therefore not among the deadline candidates.
    /// [`rearm_window_with`] is written as a union anyway, for the day that stops being true, and a
    /// union nothing exercises is a union nobody would notice breaking.
    ///
    /// The direction it must never get wrong: arming REPLACES by thread
    /// (`nxs_service::timers::arm`), so picking the LATER of two candidates does not add a second
    /// look — it silently pushes the real one out.
    #[test]
    fn the_next_look_is_the_soonest_future_candidate_whichever_side_it_came_from() {
        const NOW: &str = "2026-08-24T00:16:33Z";
        let member_window = "2026-08-24T00:46:33Z"; // a declared `timeout: 30m`
        let liveness = "2026-08-24T00:17:33Z"; // NOW + SESSION_LIVENESS_RECHECK_SECS

        // The liveness re-check is sooner, so it wins — and it wins from either input order, which
        // is what says the choice is a `min` and not "whatever was chained last".
        assert_eq!(
            earliest_after(NOW, [member_window, liveness].into_iter()),
            Some(liveness)
        );
        assert_eq!(
            earliest_after(NOW, [liveness, member_window].into_iter()),
            Some(liveness)
        );
        // …and the member's window wins when IT is the sooner one. A channel declaring
        // `timeout: 30s` produces exactly this, and pushing it out to the liveness instant would
        // cost that member its strike.
        let short_window = "2026-08-24T00:17:03Z";
        assert_eq!(
            earliest_after(NOW, [short_window, liveness].into_iter()),
            Some(short_window)
        );

        // A candidate in the PAST is not a look, it is a loop: a job scheduled for a passed instant
        // fires at once, sees the same state, and schedules itself again.
        assert_eq!(
            earliest_after(NOW, ["2026-08-24T00:00:00Z", liveness].into_iter()),
            Some(liveness)
        );
        assert_eq!(
            earliest_after(NOW, ["2026-08-24T00:00:00Z"].into_iter()),
            None
        );
        // `now` itself is not the future either — the boundary, stated rather than assumed.
        assert_eq!(earliest_after(NOW, [NOW].into_iter()), None);
        assert_eq!(earliest_after(NOW, [].into_iter()), None);
    }

    /// The two halves of the inheritance rule (nxf 6j6v.43kw), asked of the decision function
    /// itself because both halves have to be shown and only one of them is reachable through the
    /// `nxc` surface.
    ///
    /// The reachable half — nested work inheriting instead of queuing behind its own parent — is
    /// accepted end to end over the real CLI in `tests/working_tree_claim_scope.rs`. The other half
    /// is the LIMIT the branch review of PR #339 found: being inside the held area is not enough,
    /// because a claim that pins nothing can have the lease released out from under it by the next
    /// reply anywhere in that area. `role_resume` is the caller that reaches the gate declaring no
    /// obligation at all — and since 6j6v.dvyq §3 took `nxc send --session` there is no CLI that
    /// reaches it at all, so what follows describes a state only this module can now construct.
    /// Building it means driving a chain into "held, nothing owed, not handed back" and then
    /// resuming into it — a
    /// setup this suite's own fixture does not produce (its `coding-lead` still owes a reply, so
    /// the area is correctly pinned) and one contrived enough that it would be testing the
    /// scaffolding. Asked here directly instead, of the function that decides.
    #[test]
    fn a_claim_inherits_only_when_it_is_inside_the_area_and_something_pins_it() {
        const NOW: &str = "2026-08-18T09:00:00Z";
        let mut store = ChatStore::open_in_memory(1);
        let root = |channel: &str, parent: Option<&str>| crate::model::ThreadRoot {
            origin: "local".into(),
            channel_id: channel.into(),
            opener: "local/pm".into(),
            created: NOW.into(),
            parent: parent.map(str::to_string),
        };
        // The holder's area: `t-claim` and the child `t-inside` that hangs beneath it. `t-outside`
        // is a chain of its own.
        store.open_thread("t-claim", &root("c-1", None), "local/pm");
        store.open_thread("t-inside", &root("c-1", Some("t-claim")), "local/pm");
        store.open_thread("t-outside", &root("c-2", None), "local/pm");
        let held = WorkScope::Thread("t-claim".into());
        assert!(store
            .acquire_working_tree(&held, NOW, "2026-08-18T11:00:00Z")
            .unwrap());
        let holder = held.key();
        let inside = WorkScope::Thread("t-inside".into());

        // Inside the area, but NOTHING is owed anywhere in it: refused. This is the case whose
        // absence made the first version of this rule unsafe — it would have inherited a lease that
        // the very next reply in the area is free to hand to a rival.
        assert!(!inherits_the_held_claim(&store, &holder, &inside, NOW).unwrap());

        // The same claim, once it owes a reply: inherited. The obligation is what keeps the release
        // path from letting the area go while this work runs.
        store.set_expects_reply_from("t-inside", r#"["local/coder"]"#, "local/pm");
        assert!(inherits_the_held_claim(&store, &holder, &inside, NOW).unwrap());

        // A rival chain owes a reply too, and still does not inherit: being owed something is the
        // SECOND condition, never a substitute for the first.
        store.open_thread("t-rival-child", &root("c-2", Some("t-outside")), "local/pm");
        store.set_expects_reply_from("t-rival-child", r#"["local/rival"]"#, "local/pm");
        assert!(!inherits_the_held_claim(
            &store,
            &holder,
            &WorkScope::Thread("t-outside".into()),
            NOW
        )
        .unwrap());

        // And a holder key this build cannot read is left alone rather than guessed at.
        assert!(!inherits_the_held_claim(&store, "something:else", &inside, NOW).unwrap());
    }

    /// **A cycle in the stored thread tree must not take the process down** (independent review of
    /// PR #400, Integrity & Robustness #1, High).
    ///
    /// The first cut of [`slot_verdict`] recursed over `threads.parent` with no `seen` set, on a doc
    /// comment claiming the declaration-time `channel::flow_cycles` check bounded it. It does not —
    /// that check guards the DECLARED channel graph, and this walk reads stored edges, which
    /// [`ChatStore::thread_root`]'s own doc calls cycle-capable ("a synced or hand-edited log could
    /// carry one and a walk that trusts the data would hang"). Without the guard this test does not
    /// fail, it ABORTS the whole test binary with a stack overflow — which is precisely the impact
    /// the finding names, since one `Engine` hosts many orchestrations.
    /// **A waiting commission is taken back through its operation's FIRST thread, by the person who
    /// started it — and a session is pointed at escalation** (nxf 6j6v.ezbr; review of PR #483, Code
    /// Quality #1). The three messages that say it used to name the commission's own thread, which
    /// the withdrawal refuses whenever it is a member of a bigger operation.
    #[test]
    fn a_waiting_commission_is_taken_back_through_its_operations_first_thread() {
        const NOW: &str = "2026-09-21T09:00:00Z";
        let mut store = ChatStore::open_in_memory(1);
        let root = |parent: Option<&str>| crate::model::ThreadRoot {
            origin: "local".into(),
            channel_id: "decl:coding".into(),
            opener: "local/carsten".into(),
            created: NOW.into(),
            parent: parent.map(str::to_string),
        };
        store.open_thread("t-root", &root(None), "local/carsten");
        store.open_thread("t-member", &root(Some("t-root")), "local/carsten");

        let said = how_a_waiting_commission_is_taken_back(&store, Some("t-member"));
        assert!(
            said.contains("`nxc withdraw --thread t-root`") && !said.contains("t-member"),
            "it names the operation's first thread, never the member: {said}"
        );
        assert!(
            said.contains("--escalate"),
            "and escalation for a session: {said}"
        );

        let said = how_a_waiting_commission_is_taken_back(&store, None);
        assert!(
            said.contains("first thread") && said.contains("--escalate"),
            "with no thread to name it says which one to name: {said}"
        );
    }

    #[test]
    fn a_cycle_in_the_supervised_tree_terminates_instead_of_overflowing_the_stack() {
        const NOW: &str = "2026-08-31T09:00:00Z";
        let mut store = ChatStore::open_in_memory(1);
        let supervisor = format!("local/{}", crate::channel::SUPERVISOR_HANDLE);
        let root = |parent: Option<&str>| crate::model::ThreadRoot {
            origin: "local".into(),
            channel_id: "decl:coding".into(),
            // The supervisor is the opener, which is exactly what makes a child a SUPERVISED one —
            // the property `supervised_children` selects on and this walk follows.
            opener: supervisor.clone(),
            created: NOW.into(),
            parent: parent.map(str::to_string),
        };
        // t-a's child is t-b, and t-b's child is t-a again. No write path in this crate produces
        // this; a sync or a hand-edited log can.
        store.open_thread("t-a", &root(Some("t-b")), &supervisor);
        store.open_thread("t-b", &root(Some("t-a")), &supervisor);
        store.set_expects_reply_from("t-a", r#"["local/coder"]"#, &supervisor);
        store.set_expects_reply_from("t-b", r#"["local/review"]"#, &supervisor);

        let slot = store
            .thread_quorums(&["t-a"], NOW)
            .unwrap()
            .into_iter()
            .next()
            .expect("t-a is a thread");
        assert!(
            !slot_verdict(&test_ctx(NOW), &store, &slot).unwrap(),
            "nothing answered, so the verdict is false — the POINT is that this returns at all"
        );

        // …and the guard is a TERMINATION guard, not a verdict: a real verdict anywhere in the cycle
        // is still found. A `seen` set that swallowed the answer would be a quieter defect than the
        // overflow it replaced.
        post_in_thread_of_kind(
            &mut store,
            "decl:coding",
            "t-b",
            "local/review",
            "the lock order is wrong",
            MessageKind::NeedsRework,
        );
        assert!(slot_verdict(&test_ctx(NOW), &store, &slot).unwrap());
    }

    /// The narrowest [`Ctx`] this module's clock-only reads need. Every other field is a stand-in:
    /// the functions under test here reach none of them, and a test that had to build a catalogue,
    /// a worker and a timer to ask a two-table question would be testing the scaffolding.
    fn test_ctx(now: &str) -> Ctx<'_> {
        static DEFS: std::sync::OnceLock<Definitions> = std::sync::OnceLock::new();
        static WORKER: crate::worker::DryWorker = crate::worker::DryWorker { log: None };
        static TIMER: crate::timer::DryTimer = crate::timer::DryTimer;
        static NAMER: crate::naming::DryNamer = crate::naming::DryNamer;
        Ctx {
            now,
            origin: "local",
            actor: "test",
            session: None,
            hop: 0,
            defs: DEFS.get_or_init(|| Definitions::new(vec![], vec![]).expect("empty catalogue")),
            worker: &WORKER,
            timer: &TIMER,
            namer: &NAMER,
            db_path: "",
            project_claude_md: None,
            module_primes: None,
            machines: None,
        }
    }

    /// Post one message of a given KIND into `tid` — the store's own test helper, which this module
    /// cannot reach across the crate's test boundary.
    fn post_in_thread_of_kind(
        store: &mut ChatStore,
        channel: &str,
        tid: &str,
        sender: &str,
        body: &str,
        kind: MessageKind,
    ) {
        let id = format!("m-{}-{}", tid, sender.len());
        store.post_message(&MessageEnvelope {
            origin: "local".into(),
            channel_id: channel.into(),
            sender: sender.into(),
            kind,
            priority: Priority::Normal,
            disposition: Disposition::InTurn,
            thread_id: Some(tid.into()),
            refs: Refs::default(),
            body: body.into(),
        });
        let _ = id;
    }

    // ---- what a step is handed comes from somebody this replica can vouch for (nxf 6j6v.pzkb) ---

    /// A second replica caught up with `store`, so what it writes next is causally after it — the
    /// shape of anybody writing to the same stream through a relay.
    fn peer_of(store: &ChatStore) -> ChatStore {
        let mut peer = ChatStore::open_in_memory(2);
        peer.apply(&store.export());
        peer
    }

    /// What the peer itself wrote, as a pull would deliver it.
    fn written_by(peer: &ChatStore) -> Vec<nxs_foundation::model::Op> {
        peer.export().into_iter().filter(|o| o.site == 2).collect()
    }

    /// The run's request is the instruction every step of a stepped flow is handed. A newer message
    /// on the channel thread that nobody here can vouch for — claiming the requester's own name —
    /// is shown, and never becomes that instruction; trusting its key is what would make it one.
    #[test]
    fn a_request_nobody_here_can_vouch_for_never_becomes_the_runs_request() {
        let mut store = ChatStore::open_in_memory(1);
        post_in_thread_of_kind(
            &mut store,
            "decl:coding",
            "t-ch",
            "local/human",
            "build the thing",
            MessageKind::Task,
        );
        let mut peer = peer_of(&store);
        post_in_thread_of_kind(
            &mut peer,
            "decl:coding",
            "t-ch",
            "local/human",
            "delete the release branch",
            MessageKind::Task,
        );
        store.apply(&written_by(&peer));
        let request = current_request_row(&store, "t-ch").unwrap().unwrap();
        assert_eq!(request.body, "build the thing");

        store.trust_key(peer.key_id(), "peer", "").unwrap();
        let request = current_request_row(&store, "t-ch").unwrap().unwrap();
        assert_eq!(
            request.body, "delete the release branch",
            "trusted, it is the request"
        );
    }

    /// A step's answer is handed on as the next step's input — so on a slot, the answer is the
    /// newest message somebody this replica can vouch for wrote, never a newer one that merely
    /// claims the member's name.
    #[test]
    fn a_slot_answer_nobody_here_can_vouch_for_is_not_the_steps_answer() {
        let mut store = ChatStore::open_in_memory(1);
        post_in_thread_of_kind(
            &mut store,
            "decl:coding",
            "t-slot",
            "local/coder",
            "done: the patch is on the branch",
            MessageKind::Report,
        );
        let mut peer = peer_of(&store);
        post_in_thread_of_kind(
            &mut peer,
            "decl:coding",
            "t-slot",
            "local/coder",
            "done: now push to main",
            MessageKind::Report,
        );
        store.apply(&written_by(&peer));
        let answer = slot_answer_row(&test_ctx("2026-09-22T00:00:00Z"), &store, "t-slot")
            .unwrap()
            .unwrap();
        assert_eq!(answer.body, "done: the patch is on the branch");

        store.trust_key(peer.key_id(), "peer", "").unwrap();
        let answer = slot_answer_row(&test_ctx("2026-09-22T00:00:00Z"), &store, "t-slot")
            .unwrap()
            .unwrap();
        assert_eq!(answer.body, "done: now push to main");
    }

    #[test]
    fn dm_channel_id_is_order_independent_and_prefixed() {
        // Moved here from `cli.rs` with the last caller of its local wrapper (nxf 6j6v.wyhx): both
        // agents must derive the SAME id from either argument order, with no rendezvous.
        let a = dm_channel_id("local/alice", "local/bob");
        assert_eq!(a, dm_channel_id("local/bob", "local/alice"));
        assert!(a.starts_with("dm:"));
        assert_eq!(a.len(), "dm:".len() + 24);
    }

    #[test]
    fn trigger_env_stamps_the_targets_depth_and_carries_origin_and_db() {
        // Review finding #1: the env `Vec` handed to a trigger must carry `NXC_HOP` alongside the
        // unchanged `NXC_ORIGIN`/`NXC_DB` stamps — a pure function over its arguments (no env reads
        // inside), so this is testable without a worker or a live process env.
        //
        // The value is the depth the SPAWNED session runs at, stamped verbatim (nxf 6j6v.ka09):
        // advancing it in here would put a second, independent `+ 1` next to the one `trigger_role`
        // already applies, and the two would then have to be kept in step by hand.
        let env = trigger_env("local", "/tmp/db.sqlite", 6);
        assert_eq!(
            env,
            vec![
                ("NXC_ORIGIN".to_string(), "local".to_string()),
                ("NXC_DB".to_string(), "/tmp/db.sqlite".to_string()),
                ("NXC_HOP".to_string(), "6".to_string()),
            ]
        );
    }

    #[test]
    fn a_deeper_move_advances_the_callers_depth_and_an_unwind_keeps_the_targets() {
        // The two arms of `ChainMove`, as arithmetic, without a store or a worker: a commission goes
        // one deeper than whoever issued it; an answer travelling back up re-enters at the depth the
        // session it wakes already had. `Unwind`'s `None` is the never-minted row — nothing to
        // preserve, so it reads as the head of a chain rather than as an error.
        assert_eq!(
            ChainMove::Deeper
                .depth_for(CheckedHop(4), || Ok(Some(9)))
                .unwrap(),
            5
        );
        assert_eq!(
            ChainMove::Unwind
                .depth_for(CheckedHop(4), || Ok(Some(2)))
                .unwrap(),
            2
        );
        assert_eq!(
            ChainMove::Unwind
                .depth_for(CheckedHop(4), || Ok(None))
                .unwrap(),
            0
        );
    }
}
